def _cost_policy_authorize(provider, purpose, *, automatic=True,
                           event_id="", event_phase="", confirmation=False,
                           estimated_cost_usd=None, estimated_tokens=None):
    """Central gate for every generated-AI provider call (no I/O)."""
    return argus_cost_policy.authorize(
        _COST_POLICY, provider=provider, purpose=purpose,
        automatic=automatic,
        now_iso=datetime.now(pytz.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        event_id=event_id, event_phase=event_phase,
        confirmation=confirmation,
        estimated_cost_usd=estimated_cost_usd,
        estimated_tokens=estimated_tokens,
        provider_enabled=True,
        scheduled_daily_budget_usd=_SCHEDULED_AI_DAILY_USD)


def _deterministic_skip_payload(purpose):
    # The skip reason must state the TRUE mode (v13.5.36): under SCHEDULED_AI
    # only the news purposes run automatically, so other purposes skip with
    # their own reason instead of falsely claiming deterministic mode.
    if _COST_POLICY.get("mode") == "SCHEDULED_AI":
        return {"ok": True, "status": "scheduled_scope_required",
                "reason": "scheduled_scope_required",
                "classification": "expected_skip", "purpose": purpose,
                "noteJa": "定常AIはニュースの日本語要約/補助解析のみ。この用途は自動実行しません。"}
    return {"ok": True, "status": "deterministic_mode",
            "reason": "deterministic_mode", "classification": "expected_skip",
            "purpose": purpose,
            "noteJa": "決定論モードのため生成AIは実行していません。"}


def _scheduled_ai_skip(provider, purpose):
    if (purpose == "event_analysis" and _COST_POLICY.get("mode") == "EVENT_OPT_IN"
            and _COST_POLICY.get("eventOptIn")):
        if any((ev or {}).get("enabled") for ev in
               (_COST_POLICY.get("events") or {}).values()):
            return None  # each event is authorized again with ID/phase at call time
    decision = _cost_policy_authorize(
        provider, purpose, automatic=True,
        estimated_cost_usd=0.10, estimated_tokens=8000)
    if decision["allowed"]:
        return None
    return {**_deterministic_skip_payload(purpose),
            "status": decision.get("status"),
            "reason": decision.get("reason")}


def _cost_policy_record(provider, purpose, *, event_id="", event_phase="",
                        estimated_cost_usd=0.0):
    updated = argus_cost_policy.record_execution(
        _COST_POLICY, provider=provider, purpose=purpose,
        at=datetime.now(pytz.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        estimated_cost_usd=estimated_cost_usd,
        event_id=event_id, event_phase=event_phase)
    _COST_POLICY.clear()
    _COST_POLICY.update(updated)
    # Usage counters and the event phase de-duplication guard are durable state.
    # Persist immediately so a restart cannot silently re-authorize the same run.
    persist = globals().get("_osint_persist")
    if callable(persist):
        persist()

# ━━━ DST Auto-Detection & Market Time ━━━
TZ_ET  = pytz.timezone("US/Eastern")
TZ_JST = pytz.timezone("Asia/Tokyo")

def is_dst_now():
    return bool(datetime.now(TZ_ET).dst())

def get_jst_schedule():
    dst = is_dst_now()
    offset = 13 if dst else 14
    return {
        "ph1":   f"{8+offset:02d}:30",
        "ph2":   f"{8+offset:02d}:50",
        "ph3":   f"{9+offset:02d}:10",
        "ph4":   f"{9+offset:02d}:20",
        "ph5_1": f"{9+offset:02d}:30",
        "ph5_2": f"{10+offset:02d}:00",
    }

MARKET_OPEN_ET  = (9, 30)
MARKET_CLOSE_ET = (16, 0)

def _market_calendar_states(now=None):
    current = now or datetime.now(pytz.utc)
    if current.tzinfo is None:
        current = pytz.utc.localize(current)
    current_utc = current.astimezone(pytz.utc)
    return {
        "JP": argus_market_clock.market_session(
            argus_market_clock.JP_EQUITY, current_utc),
        "US": argus_market_clock.market_session(
            argus_market_clock.US_EQUITY, current_utc),
        "FX": argus_market_clock.market_session(
            argus_market_clock.FX, current_utc),
        "CRYPTO": argus_market_clock.market_session(
            argus_market_clock.CRYPTO, current_utc),
    }


def is_market_open():
    """Check if US market is currently open (regular + pre-market)"""
    state = _market_calendar_states()["US"]
    label = {
        "PRE_MARKET": "premarket",
        "REGULAR": "regular",
        "AFTER_HOURS": "afterhours",
        "WEEKEND_CLOSED": "closed_weekend",
        "HOLIDAY_CLOSED": "closed_holiday",
        "EMERGENCY_CLOSED": "closed_emergency",
    }.get(state["session"], "closed")
    return state["session"] in (
        "PRE_MARKET", "REGULAR", "AFTER_HOURS"), label

