# ━━━ Flask App & State Management ━━━
claude     = anthropic.Anthropic(api_key=ANTHROPIC_API_KEY)
STATE_FILE = "/tmp/scan_state.json"
app        = Flask(__name__)

# CORS for /api/argus/* — lets the React frontend (Vercel, GitHub Pages,
# and localhost dev) call the ledger / rates endpoints. Other routes
# stay same-origin.
if CORS is not None:
    _PUBLIC_BROWSER_ORIGINS = [
        re.compile(r"^http://localhost(:\d+)?$"),
        re.compile(r"^http://127\.0\.0\.1(:\d+)?$"),
        # Pin Vercel to this project's deploys (argus*.vercel.app) rather than
        # any *.vercel.app — the latter let any attacker-controlled Vercel
        # subdomain read the /api/argus/* endpoints. Adjust the prefix if the
        # Vercel project is ever renamed.
        re.compile(r"^https://argus[a-z0-9-]*\.vercel\.app$"),
        re.compile(r"^https://mitsugue\.github\.io$"),
    ]
    CORS(app, resources={
        # Operational diagnostics are server-to-server only.  The more
        # specific expression wins Flask-CORS resource ordering and prevents
        # any browser origin from receiving an allow-origin header.
        r"/api/argus/admin/diagnostics/operational": {"origins": []},
        r"/api/argus/*": {"origins": _PUBLIC_BROWSER_ORIGINS},
    })

@app.after_request
def add_no_cache(response):
    if request.path == "/api/argus/today-headline":
        # Same explicit ETag/revalidate contract as the verified snapshot
        # route; the global no-store fallback must not erase it.
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response
    if request.path == "/api/argus/chart-intelligence" and \
            request.args.get("snapshot") == "verified":
        # This endpoint sets a private must-revalidate policy plus ETag.  Do not
        # let the global legacy no-store guard erase that explicit contract.
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response
    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response


_MEMORY_HTTP_KNOWN_ROUTES = {
    "/healthz", "/readyz", "/api/state",
    "/api/argus/data-quality/status",
    "/api/argus/admin/memory-attribution",
    "/api/argus/admin/missions/tick",
}
_MEMORY_HTTP_KNOWN_PREFIXES = (
    "/api/argus/admin/checkpoint", "/api/argus/market",
    "/api/argus/prediction", "/api/argus/osint",
)


@app.before_request
def _memory_attribution_request_begin():
    """Start a light scalar-only request sample; never retain request data."""
    try:
        rule = request.url_rule.rule if request.url_rule is not None else \
            "unmatched"
        known = (rule in _MEMORY_HTTP_KNOWN_ROUTES or
                 any(rule.startswith(prefix)
                     for prefix in _MEMORY_HTTP_KNOWN_PREFIXES))
        g.argus_memory_operation = _MEMORY_OPERATIONS.begin(
            kind="HTTP", name=f"{request.method} {rule}", known=known,
            metadata={"missionActive": _mission_tick_context_active()})
    except Exception:
        g.argus_memory_operation = None


@app.after_request
def _memory_attribution_request_complete(response):
    try:
        _MEMORY_OPERATIONS.complete(
            getattr(g, "argus_memory_operation", None),
            metadata={"statusCode": int(response.status_code),
                      "missionActive": _mission_tick_context_active()})
    except Exception:
        pass
    return response

# ── Per-IP rate limit (v9.10) ────────────────────────────────────────
# The /api/argus/* endpoints are public; a hostile loop could drain the
# Twelve Data daily credits (dynamic ?symbols= sets) or hammer J-Quants.
# Simple in-memory sliding window per IP: generous for the SPA (~10 calls
# per page load), stricter for "heavy" requests that can bust caches via
# query params. OPTIONS (CORS preflight) is never limited.
_RL_LOCK    = threading.Lock()
_RL_BUCKETS = {}          # ip -> deque[timestamps]
_RL_WINDOW  = 60.0        # seconds
_RL_MAX     = 300         # default requests / IP / minute — v11.13.1: Today now
                          # mounts ~20 cached-read endpoints and polls them across
                          # the owner's Mac+iPhone+iPad on ONE home IP; 120 made the
                          # app 429 ITSELF (需給/フロー消失・crypto BTC/ETHのみ残留,
                          # observed 2026-07-04). All these are cheap cache reads.
# Heavy (cache-busting) budget: was 30/min pre-15s-polling. Legit usage is now
# ~10-12/min PER DEVICE (jp+us watchlist every 15s + action-labels) and one
# home IP often runs phone+Mac+preview simultaneously — 30 made the app
# rate-limit ITSELF (observed 2026-06-13). 90 keeps 3 devices + scout taps
# comfortable while still bounding abuse (all heavy endpoints are cached).
_RL_MAX_HEAVY = 200       # 90→140 (v11.8.1) → 200 (v11.13.1): every release
                          # added polling; 3 devices + preview share one IP and all
                          # heavy endpoints are cached reads on Render Standard.
# Interactive symbol-search gets its OWN bucket (v11.8.1) so background quote
# polling can never starve a human typing in the search box into 「混雑」.
_RL_MAX_SEARCH = 30
_RL_MAX_IPS = 5000        # memory bound on a public endpoint

def _rl_client_ip():
    fwd = (request.headers.get("X-Forwarded-For", "").split(",")[0] or "").strip()
    return request.headers.get("CF-Connecting-IP") or fwd or (request.remote_addr or "?")

@app.before_request
def _rate_limit():
    p = request.path
    if not p.startswith("/api/argus/") or request.method == "OPTIONS":
        return None
    # v11.8.1 (owner report 「検索すると混雑してるとよく言われる」): symbol-search
    # used to share the heavy bucket with the app's own quote polling (Mac+
    # iPhone+iPad on one home IP), so background polling starved interactive
    # search into 429s. Search now has its OWN per-IP bucket — polling can no
    # longer eat the search budget — and the heavy budget is raised for the
    # v11.7/11.8 polling growth (all cached reads on Render Standard 2GB).
    search = "symbol-search" in p
    heavy = (not search) and any(k in request.args
                                 for k in ("symbols", "jp", "us", "ids", "q", "symbol"))
    limit = _RL_MAX_SEARCH if search else (_RL_MAX_HEAVY if heavy else _RL_MAX)
    now = time.time()
    ip = _rl_client_ip() + (":search" if search else "")
    with _RL_LOCK:
        if len(_RL_BUCKETS) > _RL_MAX_IPS:
            _RL_BUCKETS.clear()
        dq = _RL_BUCKETS.setdefault(ip, deque())
        while dq and now - dq[0] > _RL_WINDOW:
            dq.popleft()
        if len(dq) >= limit:
            return jsonify({"error": "rate_limited",
                            "message": "Too many requests — wait a minute and retry."}), 429
        dq.append(now)
    return None

def safe_json(text):
    text = re.sub(r"```json\s*", "", text)
    text = re.sub(r"```\s*", "", text).strip()
    try:
        from json_repair import repair_json
        return json.loads(repair_json(text))
    except Exception: pass
    try:
        fixed = re.sub(r'(?<=": ")(.*?)(?=")', lambda m: m.group(0).replace('\n', ' '), text, flags=re.DOTALL)
        return json.loads(fixed)
    except Exception: pass
    try: return json.loads(text.replace('\n', ' '))
    except Exception: return {}

# Reentrant lock guarding STATE_FILE: serializes reads/writes across the scan
# worker, scheduler, and request threads. Reentrant so a load→modify→save done
# while already holding the lock (see add_log) doesn't deadlock.
_STATE_LOCK = threading.RLock()

def load_state():
    with _STATE_LOCK:
        try:
            with open(STATE_FILE, "r") as f: return json.load(f)
        except Exception: return {"phase": 0, "log": []}

def save_state(state):
    # Atomic write: dump to a temp file then os.replace, so a concurrent reader
    # never sees a half-written (truncated) file — which previously surfaced as
    # load_state() falling back to {"phase": 0} and momentarily resetting phase.
    with _STATE_LOCK:
        try:
            tmp = f"{STATE_FILE}.{os.getpid()}.tmp"
            with open(tmp, "w") as f: json.dump(state, f, ensure_ascii=False, default=str)
            os.replace(tmp, STATE_FILE)
        except Exception: pass

def clear_state():
    save_state({"phase": 0, "log": []})

def add_log(msg):
    now = datetime.now(TZ_JST)
    entry = f"[{now.strftime('%H:%M:%S')}] {msg}"
    LOG_BUFFER.append(entry)
    # Hold the lock across the whole read-modify-write so concurrent add_log
    # calls can't clobber each other's appended lines.
    with _STATE_LOCK:
        state = load_state()
        logs = state.get("log", [])
        logs.append(entry)
        state["log"] = logs[-50:]
        save_state(state)

def push_notify(title, msg, priority="default", *, subject_symbol=None,
                notification_scope=None):
    """Legacy ntfy transport with the same owner-universe firewall as events.

    Phase/digest/system messages remain available.  Any call whose primary
    subject is an individual security must name ``subject_symbol`` and is denied
    unless the private Layer-2B membership resolves it as held or marked.
    """
    if not SCHEDULED_RUN:
        return False
    decision = _push_eligibility(notification_scope, subject_symbol)
    if not decision["pushEligible"]:
        return False
    try:
        requests.post(f"https://ntfy.sh/{NTFY_CHANNEL}", data=msg.encode("utf-8"),
            headers={"Title": title, "Priority": priority,
                     "Tags": "chart_with_upwards_trend" if "📈" in title else "warning"}, timeout=10)
        return True
    except Exception as e:
        add_log(f"[WARN] ntfy failed: {e}")
        return False

# ━━━ Finnhub API Functions ━━━
def finnhub_get(endpoint, params=None):
    finnhub_rate_limit()
    params = params or {}
    params["token"] = FINNHUB_API_KEY
    try:
        r = requests.get(f"https://finnhub.io/api/v1/{endpoint}", params=params, timeout=10)
        if r.status_code == 200: return r.json()
    except Exception: pass
    return None


def _legacy_provider_number(value):
    """Finite numeric provider scalar, without bool/string coercion."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    number = float(value)
    return number if math.isfinite(number) else None


_DECISION_NEWS_MAX_AGE_SEC = 24 * 3600
_DECISION_OFFICIAL_FACT_MAX_AGE_SEC = 72 * 3600


def _decision_event_time(value, *, now_epoch=None, max_age_seconds,
                         naive_utc_offset_hours=None):
    """Strict provider/event timestamp proof for current decision evidence."""
    source_epoch = None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        source_epoch = float(value)
    elif isinstance(value, str):
        raw = value.strip()
        if not raw or re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
            return None  # a calendar date cannot prove intraday causal order
        parsed = None
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except (TypeError, ValueError):
            try:
                from email.utils import parsedate_to_datetime
                parsed = parsedate_to_datetime(raw)
            except (TypeError, ValueError, OverflowError):
                parsed = None
        if parsed is None:
            return None
        if parsed.tzinfo is None or parsed.utcoffset() is None:
            if naive_utc_offset_hours is None:
                return None
            parsed = parsed.replace(
                tzinfo=timezone(timedelta(hours=float(
                    naive_utc_offset_hours))))
        source_epoch = parsed.timestamp()
    if source_epoch is None or not math.isfinite(source_epoch) \
            or source_epoch <= 0:
        return None
    try:
        now = time.time() if now_epoch is None else float(now_epoch)
        budget = float(max_age_seconds)
    except (TypeError, ValueError, OverflowError):
        return None
    if (not math.isfinite(now) or not math.isfinite(budget)
            or budget < 0):
        return None
    age = now - source_epoch
    if age < 0 or age > budget:
        return None
    return {
        "sourceEpoch": source_epoch,
        "sourceTimestamp": datetime.fromtimestamp(
            source_epoch, pytz.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "sourceAgeSec": int(age),
        "sourceTimeStatus": "CURRENT_EXACT",
    }


def _decision_news_row(row, *, now_epoch=None, timestamp_keys=(
        "publishedAt", "datetime", "time")):
    """Copy one bounded current news row, or return None."""
    if not isinstance(row, dict):
        return None
    raw_timestamp = next((row.get(key) for key in timestamp_keys
                          if row.get(key) is not None), None)
    truth = _decision_event_time(
        raw_timestamp, now_epoch=now_epoch,
        max_age_seconds=_DECISION_NEWS_MAX_AGE_SEC)
    if truth is None:
        return None
    return {
        **row, **truth,
        "publishedAt": truth["sourceTimestamp"],
        "datetime": int(truth["sourceEpoch"]),
        "decisionUsable": True,
        "freshness": "FRESH" if truth["sourceAgeSec"] <= 6 * 3600
                     else "DELAYED",
    }


def _decision_official_disclosure(row, market, *, now_epoch=None):
    """Current official fact with a real bounded publication timestamp."""
    if not isinstance(row, dict):
        return None
    truth = _decision_event_time(
        row.get("disclosedAt") or row.get("time"),
        now_epoch=now_epoch,
        max_age_seconds=_DECISION_OFFICIAL_FACT_MAX_AGE_SEC,
        naive_utc_offset_hours=(9 if str(market).upper() == "JP" else None))
    if truth is None:
        return None
    return {**row, **truth, "decisionUsable": True}


def _finnhub_quote_for_decision(data, *, required_fields=("c",),
                                 now_epoch=None):
    """Validate one Finnhub quote before any legacy decision consumer.

    Finnhub transport success is not market-time truth.  The quote's provider
    timestamp is mandatory, cannot be in the future, and must satisfy the same
    bounded source-age contract as every other decision-relevant quote.
    """
    if not isinstance(data, dict):
        return None
    timestamp = data.get("t")
    if _legacy_provider_number(timestamp) is None:
        return None
    truth = _canonical_quote_source_age(timestamp, now_epoch=now_epoch)
    if truth.get("realtimeEvidence") is not True:
        return None
    for field in required_fields:
        if _legacy_provider_number(data.get(field)) is None:
            return None
    return data


def _finnhub_latest_daily_source_date(timestamp, *, now_epoch=None):
    """Return the exact latest completed US session for a Finnhub daily row."""
    source_epoch = _legacy_provider_number(timestamp)
    if source_epoch is None or source_epoch <= 0:
        return None
    try:
        source_date = datetime.fromtimestamp(source_epoch, pytz.utc).date()
        decision_epoch = time.time() if now_epoch is None else float(now_epoch)
        if not math.isfinite(decision_epoch):
            return None
        latest_completed = argus_market_clock.latest_completed_session_date(
            argus_market_clock.US_EQUITY,
            datetime.fromtimestamp(decision_epoch, pytz.utc))
    except (TypeError, ValueError, OverflowError, OSError):
        return None
    if source_date != latest_completed or not argus_market_clock.is_trading_day(
            argus_market_clock.US_EQUITY, source_date):
        return None
    return source_date.isoformat()

def get_us_symbols():
    global SYMBOL_CACHE, SYMBOL_CACHE_TIME
    now = time.time()
    if SYMBOL_CACHE and now - SYMBOL_CACHE_TIME < 86400: return SYMBOL_CACHE
    data = finnhub_get("stock/symbol", {"exchange": "US"})
    if data:
        symbols = [s for s in data if s.get("type") in ("Common Stock", "EQS")
                   and s.get("symbol") and "." not in s["symbol"] and len(s["symbol"]) <= 5]
        SYMBOL_CACHE = symbols
        SYMBOL_CACHE_TIME = now
        return symbols
    return []

def get_quote(symbol):
    data = finnhub_get("quote", {"symbol": symbol})
    data = _finnhub_quote_for_decision(
        data, required_fields=("c", "o", "h", "l", "pc"))
    if data:
        current = _legacy_provider_number(data["c"])
        opened = _legacy_provider_number(data["o"])
        high = _legacy_provider_number(data["h"])
        low = _legacy_provider_number(data["l"])
        previous = _legacy_provider_number(data["pc"])
        if current is None or current <= 0 or previous is None or previous <= 0 \
                or any(value is None or value < 0
                       for value in (opened, high, low)):
            return None
        return {"current": current, "open": opened, "high": high, "low": low,
                "prev_close": previous,
                "change_pct": round((current - previous) / previous * 100, 2),
                # Finnhub /quote exposes no volume.  Its ``t`` field is the
                # source timestamp and must never be relabelled as volume.
                "volume": 0}
    return None

def get_quotes_batch(symbols):
    results = {}
    for sym in symbols:
        q = get_quote(sym)
        if q: results[sym] = q
    return results

