_TWELVEDATA_API_KEY = os.environ.get("TWELVEDATA_API_KEY")
_TWELVEDATA_QUOTE   = "https://api.twelvedata.com/quote"

# `mock` holds plausible fallback values (NOT real quotes) for the mock state.
