_JP_CALENDAR_REGISTER = {"lastAt": 0.0}


def _jp_canonical_calendar_autoregister():
    """Owner directive 2026-08-26: DAILY authority runs on the canonical
    J-Quants trading calendar. Registers a proven ±45-day window daily
    (7-day request windows per the provider contract); the clock falls back
    to the versioned official snapshot inside its coverage and fails
    conservatively beyond it — never weekday arithmetic."""
    if not _JQUANTS_API_KEY:
        return
    now = time.time()
    if now - _JP_CALENDAR_REGISTER["lastAt"] < 20 * 3600:
        return
    _JP_CALENDAR_REGISTER["lastAt"] = now
    start_dt = datetime.now(TZ_JST) - timedelta(days=45)
    end_dt = datetime.now(TZ_JST) + timedelta(days=45)
    frm_iso = start_dt.strftime("%Y-%m-%d")
    to_iso = end_dt.strftime("%Y-%m-%d")
    rows = []
    try:
        cursor = start_dt
        while cursor <= end_dt:
            window_end = min(cursor + timedelta(days=6), end_dt)
            rows.extend(_jquants_paginated(
                "/markets/calendar",
                {"from": cursor.strftime("%Y-%m-%d"),
                 "to": window_end.strftime("%Y-%m-%d")}))
            cursor = window_end + timedelta(days=1)
        days = argus_foundation_jobs.trading_dates(
            rows, start=frm_iso, end=to_iso)
        if len(days) < 20:        # ±45d must contain many sessions
            add_log(f"[calendar] canonical register skipped (days={len(days)})")
            return
        info = argus_market_clock.register_canonical_calendar(
            argus_market_clock.JP_EQUITY, days, start=frm_iso, end=to_iso,
            source="jquants:/markets/calendar")
        add_log(f"[calendar] canonical JP registered {info['days']}d "
                f"{info['start']}..{info['end']}")
    except Exception as exc:
        add_log(f"[calendar] canonical register failed: {type(exc).__name__}")


_INVESTOR_TYPES_REFRESH = {"lastAt": 0.0}


def _recovery_phase_a_begin_market_ledger_observation():
    """Start optional D05 scalar timing without changing ledger authority."""
    try:
        if not _recovery_phase_a_pre_authority_observer_enabled():
            return None
        return time.monotonic_ns()
    except Exception:
        return None


def _recovery_phase_a_finish_market_ledger_observation(
        started_ns, result, checkpoint):
    """Observe D05 only after the existing legacy checkpoint is verified."""
    try:
        if type(started_ns) is not int or type(result) is not dict or \
                type(checkpoint) is not dict or \
                checkpoint.get("verified") is not True:
            return
        preview = result.get("preview")
        if type(preview) is not list:
            preview = []
        canonical_bytes = len(json.dumps(
            preview, ensure_ascii=False, allow_nan=False, sort_keys=True,
            separators=(",", ":")).encode("utf-8"))
        _recovery_phase_a_record(
            "market.ledger_update",
            estimated_plaintext_bytes=canonical_bytes,
            record_count=len(preview),
            latency_micros=_recovery_phase_a_elapsed_micros(started_ns),
            observed_at=datetime.now(pytz.utc))
    except Exception:
        pass


def _investor_types_autorefresh():
    """D05 supply (v13.5.36): the PIT investor-types adapter existed but only
    as a manual admin backfill — flow.foreign went stale and SHO D05 sat at
    判定不能 despite the paid J-Quants plan carrying the data. Daily bounded
    refresh (weekly series, 45-day window); idempotent via ledger dedup;
    same PIT publication policy as the manual route; origin=cron."""
    if not _JQUANTS_API_KEY:
        return
    now = time.time()
    if now - _INVESTOR_TYPES_REFRESH["lastAt"] < 20 * 3600:
        return
    _INVESTOR_TYPES_REFRESH["lastAt"] = now
    now_iso = _ai_now_iso()
    frm = (datetime.now(TZ_JST) - timedelta(days=45)).strftime("%Y-%m-%d")
    to = datetime.now(TZ_JST).strftime("%Y-%m-%d")
    try:
        raw = _jquants_paginated(
            "/equities/investor-types",
            {"section": "TokyoNagoya", "from": frm, "to": to})
        candidates = argus_market_intelligence.normalize_jquants_investor_rows(
            raw, now_iso, "TokyoNagoya")
        existing = {(x.get("seriesId"), x.get("periodEnd"),
                     x.get("availableFrom"), x.get("value"))
                    for x in (_MARKET_LEDGER.get("observations") or [])
                    if isinstance(x, dict)}
        candidates = [x for x in candidates
                      if (x.get("seriesId"), x.get("periodEnd"),
                          x.get("availableFrom"), x.get("value"))
                      not in existing]
        if not candidates:
            return
        measurement_started = \
            _recovery_phase_a_begin_market_ledger_observation()
        result = argus_market_ledger.import_rows(
            _MARKET_LEDGER, candidates, now_iso=now_iso, dry_run=False)
        if result.get("ok"):
            _MARKET_LEDGER.clear()
            _MARKET_LEDGER.update(result.pop("state"))
            _journal("market_ledger_investor_types_autorefresh",
                     "market_ledger", result.get("importId"),
                     {"rowCount": len(result.get("preview") or [])},
                     origin="cron")
            checkpoint = _osint_persist()
            _recovery_phase_a_finish_market_ledger_observation(
                measurement_started, result, checkpoint)
            add_log(f"[d05] investor-types autorefresh "
                    f"+{len(result.get('preview') or [])} rows")
    except Exception as exc:
        add_log(f"[d05] investor-types autorefresh failed: {type(exc).__name__}")


@app.route("/api/argus/institutional-intelligence/collect", methods=["POST"])
def api_argus_intel_collect():
    """Admin/cron: run the public-feed collection (the ONLY fetch path)."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    out = collect_institutional_intel()
    try:
        _investor_types_autorefresh()      # v13.5.36: keep SHO D05 fed (daily)
    except Exception:
        pass
    try:
        _jp_canonical_calendar_autoregister()   # daily-authority calendar
    except Exception:
        pass
    # v11.10.0: warm the supply/demand caches here (admin path — fetching is
    # allowed). Without this, a fresh deploy leaves _JQ_MARGIN_CACHE/_JSF_CACHE
    # cold and every 需給ランク reads Unknown until the owner happens to tap
    # エントリー診断. Both fetchers honor their own TTLs (12h margin / 6h JSF),
    # so this 30-min cron is a cheap no-op most runs.
    warmed = {"jsf": False, "margin": 0}
    try:
        table, _d = _jsf_balance_table()
        warmed["jsf"] = bool(table)
    except Exception:
        pass
    for s in _JP_WATCHLIST:
        try:
            code4 = str(s.get("symbol") or "")[:4]
            if code4.isdigit() or (code4 and code4[0].isdigit()):
                if _jq_weekly_margin(code4):
                    warmed["margin"] += 1
                _jq_price_history(code4)   # daily bars → avgVolume/daysToCover/runup
        except Exception:
            continue
    for s in _US_WATCHLIST:                    # v11.11.0: US bars for 需給/outcome
        try:
            if _us_price_history(str(s.get("symbol") or "")):
                warmed["usBars"] = warmed.get("usBars", 0) + 1
        except Exception:
            continue
    # v12.0.6: デバイスから要求された追加銘柄(有界レジストリ)もウォームする —
    # 公開GETはcached-onlyのため、ここが唯一のfetch経路(30分毎・TTL付き)。
    for xs, meta in list(_SD_EXTRA_SYMBOLS.items()):
        try:
            if meta.get("market") == "JP":
                code4 = xs[:4]
                if _jq_weekly_margin(code4):
                    warmed["extraMargin"] = warmed.get("extraMargin", 0) + 1
                _jq_price_history(code4)
            else:
                if _us_price_history(xs):
                    warmed["extraUsBars"] = warmed.get("extraUsBars", 0) + 1
        except Exception:
            continue
    # v13.5.61 Recovery (owner iPhone review 2026-09-07: 7011/314A/6330/7794/
    # 4392 never showed a price). Names outside the curated seven — the
    # owner's Layer 2B members and any code a device asked for — were never
    # fetched by anything, and the public GET is cache-only, so they stayed
    # 「価格なし」 forever. Warm them here on every collect (J-Quants EOD, one
    # bounded batch); the cache-only reads then assemble them per symbol.
    owner_codes = _owner_jp_symbols_for_warm()
    if owner_codes:
        try:
            _get_japan_watchlist_core(list(owner_codes), allow_provider_fetch=True)
            warmed["ownerJp"] = len(owner_codes)
        except Exception as exc:
            warmed["ownerJpError"] = type(exc).__name__
    out["supplyDemandWarm"] = warmed
    # v13.5.36: warm the SHO CORE input caches (^N225/^VIX OHLCV, 1570 weekly
    # margin, FRED VIX). This admin/cron path is the ONLY fetch route; the
    # public decision-evidence GET reads these caches cached-only.
    try:
        out["shoInputWarm"] = dict(
            _sho_pit_inputs(warm=True).get("sourceStatus") or {})
    except Exception as exc:
        out["shoInputWarm"] = {"error": type(exc).__name__}
    return jsonify(out)


# ━━━ V11.5.3 C.A.O.S. Watchtower — Core Portfolio source universe + patrol ━━━
# The owner's June-19-news-as-current-lead complaint exposed two gaps: (1) no
# freshness gate (fixed in argus_news_freshness + mover cause), (2) no defined
# "who do we watch, where, how often" registry. This block wires the pure
# universe/source/plan modules to real collection, tracks per-source freshness,
# and exposes it all as public cache-only status. Public GETs never fetch/LLM;
# the admin refresh is the ONLY patrol path (cron: caos-watchtower.yml).

_US_STOCK_NEWS_CACHE = {}          # sym -> {"expires": float}
_US_STOCK_NEWS_TTL = 30 * 60


def _google_news_us_rss(query):
    """Google News US RSS — DISCOVERY LAYER for US names (same parser as JP;
    items resolve to their true publisher via argus_caos_source_universe)."""
    try:
        url = ("https://news.google.com/rss/search?q=" + quote(query)
               + "&hl=en-US&gl=US&ceid=US:en")
        xml = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=8).text
        return _parse_rss(xml, "google_news_us", _ai_now_iso())
    except Exception:
        return []


def _us_stock_news_intel(pairs):
    """US counterpart of _jp_stock_news_intel — per-symbol English headlines into
    _INTEL_STORE (metadata only, symbolHint for association). 30-min per-symbol cache."""
    now = time.time()
    pushed = 0
    seen = {(it.get("title") or "") for it in _INTEL_STORE}
    for sym, name in pairs:
        sym = str(sym).upper()
        nm = (name or sym).strip()
        if not sym:
            continue
        c = _US_STOCK_NEWS_CACHE.get(sym)
        if c and now < c["expires"]:
            continue
        _US_STOCK_NEWS_CACHE[sym] = {"expires": now + _US_STOCK_NEWS_TTL}
        for r in _google_news_us_rss(f'"{nm}" stock (earnings OR news OR falls OR surges)')[:6]:
            t = r.get("title") or ""
            if not t or t in seen:
                continue
            seen.add(t)
            r = dict(r)
            r["symbolHint"] = sym
            r["lang"] = "en"
            r["corroboration"] = "single"
            r.setdefault("intelligenceId", hashlib.md5(
                f"google_news_us|{r.get('canonicalUrl')}|{t}".encode()).hexdigest()[:16])
            _INTEL_STORE.append(r)
            pushed += 1
    if len(_INTEL_STORE) > _INTEL_STORE_MAX:
        del _INTEL_STORE[:len(_INTEL_STORE) - _INTEL_STORE_MAX]
    return pushed


_WATCHTOWER_STATE = {"restored": False, "lastRefreshAt": None,
                     "sources": {}, "lastSummary": None}
_WATCHTOWER_FILE = "/tmp/argus_watchtower.json"


def _watchtower_persist():
    try:
        with open(_WATCHTOWER_FILE, "w") as f:
            json.dump({k: _WATCHTOWER_STATE[k] for k in
                       ("lastRefreshAt", "sources", "lastSummary")},
                      f, ensure_ascii=False, default=str)
    except Exception:
        pass


def _watchtower_restore_once():
    if _WATCHTOWER_STATE["restored"]:
        return
    _WATCHTOWER_STATE["restored"] = True
    try:
        with open(_WATCHTOWER_FILE) as f:
            blob = json.load(f)
        for k in ("lastRefreshAt", "sources", "lastSummary"):
            if blob.get(k) is not None:
                _WATCHTOWER_STATE[k] = blob[k]
    except Exception:
        pass


def _watchtower_configured():
    """Which API paths are configured — boolean flags only, never values."""
    return {"JQUANTS_API_KEY": bool(_JQUANTS_API_KEY),
            "FINNHUB_API_KEY": bool(FINNHUB_API_KEY),
            "TWELVEDATA_API_KEY": bool(_TWELVEDATA_API_KEY),
            "FRED_API_KEY": bool(_FRED_API_KEY)}


def _watchtower_plan_build(now_iso, src_uni=None):
    src_uni = src_uni or argus_caos_source_universe.build_universe(_watchtower_configured(), now_iso)
    _mover_causes_restore_once()
    try:
        events = (_build_dashboard_events(limit=8) or {}).get("items") or []
    except Exception:
        events = []
    return argus_caos_watchtower_plan.build_plan(
        watchlist_jp=list(_JP_WATCHLIST), watchlist_us=list(_US_WATCHLIST),
        movers=_mover_causes_today(), macro_events=events,
        universe_sources=src_uni["sources"], now_iso=now_iso)


