def _normalized_hash_counter_observer(counters):
    """Count normalized-hash outcomes without retaining callback metadata."""
    def observe(event, _metadata):
        try:
            if event == "normalized_input_reused":
                counters["normalizedHashFastPathCount"] = int(
                    counters.get("normalizedHashFastPathCount") or 0) + 1
            elif event == "normalized_input_fallback":
                counters["normalizedHashFallbackCount"] = int(
                    counters.get("normalizedHashFallbackCount") or 0) + 1
        except Exception:
            return

    return observe


def _memory_state_hash_observer(store_kind, counters=None):
    """Map finite, scalar-only hash callbacks to exact S7 boundaries."""
    prefix = "S7V" if store_kind == "verified" else "S7A"
    phase_numbers = {
        "hash_enter": 2,
        "internal_normalize_complete": 3,
        "normalized_input_reused": 3,
        "stable_tree_ready": 4,
        "hash_projection_ready": 4,
        "canonical_string_ready": 5,
        "utf8_bytes_ready": 6,
        # The final boundary is captured by the caller only after temporaries
        # have left the hash function frame.
        "hash_complete": None,
    }
    counter_observer = _normalized_hash_counter_observer(
        counters if isinstance(counters, dict) else {})
    state = {"fallbackPrelude": False}

    def observe(event, metadata):
        counter_observer(event, metadata)
        if event == "normalized_input_fallback":
            # The fail-safe normalized API announces fallback before delegating
            # to the unchanged raw state_hash.  Capture that boundary as V/A2,
            # then suppress the delegated hash_enter duplicate so the remaining
            # raw phases retain their chronological V/A3..V/A6 ordering.
            state["fallbackPrelude"] = True
            _memory_attribution_source_capture(
                f"{prefix}2", f"{store_kind}_{event}",
                metadata if isinstance(metadata, dict) else None)
            return
        if event == "hash_enter" and state["fallbackPrelude"]:
            return
        number = phase_numbers.get(str(event))
        if number is None:
            return
        _memory_attribution_source_capture(
            f"{prefix}{number}", f"{store_kind}_{event}",
            metadata if isinstance(metadata, dict) else None)

    return observe


def _memory_operation_begin(kind, name, *, known=True, metadata=None):
    try:
        values = {"missionActive": _mission_tick_context_active()}
        if isinstance(metadata, dict):
            values.update(metadata)
        return _MEMORY_OPERATIONS.begin(
            kind=kind, name=name, known=known, metadata=values)
    except Exception:
        return None


def _memory_operation_complete(token, metadata=None):
    try:
        values = {"missionActive": _mission_tick_context_active()}
        if isinstance(metadata, dict):
            values.update(metadata)
        return _MEMORY_OPERATIONS.complete(token, metadata=values)
    except Exception:
        return None


def _memory_operation_run(
        kind, name, callback, *args, _attribution_after_callback=None,
        **kwargs):
    """Run an existing task unchanged while measuring only scalar boundaries."""
    token = _memory_operation_begin(kind, name, known=True)
    try:
        result = callback(*args, **kwargs)
    except Exception as exc:
        _memory_operation_complete(
            token, {"result": "error", "errorClass": type(exc).__name__})
        raise
    if callable(_attribution_after_callback):
        try:
            _attribution_after_callback(result)
        except Exception:
            pass
    _memory_operation_complete(token, {"result": "ok"})
    return result


def _memory_attribution_not_applicable(phases, reason):
    try:
        record_id = _memory_attribution_record_id()
        if record_id:
            _MEMORY_ATTRIBUTION.mark_not_applicable(
                record_id, phases, reason=reason)
    except Exception:
        return


def _memory_attribution_finish_mission(*, mission_complete, error_class=None):
    """Close only a real mission record and never affect request semantics."""
    try:
        record_id = _memory_attribution_record_id()
        if not record_id:
            return
        sample = (_memory_attribution_scalar_snapshot()
                  or _memory_attribution_initial_snapshot())
        if not isinstance(sample, dict):
            return
        metadata = {"missionComplete": bool(mission_complete)}
        if error_class:
            metadata["errorClass"] = str(error_class)[:120]
        _memory_attribution_capture("T11", metadata, sample=sample)
        try:
            _MEMORY_OPERATIONS.open_intermission(
                record_id=record_id,
                mission_window_id=_MISSION_TICK_CONTEXT.get(
                    "missionWindowId"),
                sample=sample)
        except Exception:
            pass
    except Exception:
        return


def _memory_attribution_initial_snapshot():
    try:
        return argus_memory_attribution.memory_snapshot(
            _memory_attribution_logical_counts())
    except Exception:
        return None


def _memory_attribution_scalar_snapshot():
    """Full process/allocator scalar sample without logical-store traversal."""
    try:
        return argus_memory_attribution.memory_snapshot(None)
    except Exception:
        return None


def _memory_attribution_complete(record_id):
    try:
        return _MEMORY_ATTRIBUTION.complete(record_id)
    except Exception:
        return None


def _memory_attribution_isolated_hook(phase, metadata=None):
    """Fail-open callback used at exact isolated-writer parent boundaries."""
    try:
        _memory_attribution_capture(phase, metadata=metadata)
        if phase == "T6":
            record_id = _memory_attribution_record_id()
            if record_id:
                _MEMORY_ATTRIBUTION.update_metadata(
                    record_id, {"v2GenerationAttempted": True})
        if phase == "T10" and isinstance(metadata, dict):
            record_id = _memory_attribution_record_id()
            if record_id:
                _MEMORY_ATTRIBUTION.update_metadata(
                    record_id, {"v2GenerationId": metadata.get(
                        "generationId")})
    except Exception:
        return


def _mission_tick_durability_snapshot(*, remote_export=False):
    state = dict(_MISSION_BATCH_STATE)
    if remote_export:
        # This exact local checkpoint cursor is what the Remote Journal will
        # contain after publication. It is not a claim about a later WAL tail.
        state["remoteWalAppliedSequence"] = int(
            state.get("walAppliedSequence") or 0)
    else:
        state["remoteWalAppliedSequence"] = int(
            _REMOTE_CYCLE.get("remoteWalAppliedSequence") or 0)
    state["verifiedWalSequence"] = int(
        _REMOTE_CYCLE.get("verifiedWalSequence") or 0)
    state["compactReceiptHash"] = _REMOTE_CYCLE.get("compactReceiptHash")
    return state


def _persist_remote_wal_receipt(saved_at=None):
    saved_at = saved_at or _ai_now_iso()
    receipt = argus_tick_durability.remote_receipt_record(
        saved_at=saved_at,
        remote_commit_sha=_REMOTE_CYCLE.get("remoteCommitSha"),
        committed_at=_REMOTE_CYCLE.get("committedAt"),
        expected_hash=_REMOTE_CYCLE.get("expectedHash"),
        actual_hash=_REMOTE_CYCLE.get("actualHash"),
        read_back_at=_REMOTE_CYCLE.get("readBackAt"),
        read_back_verified=bool(_REMOTE_CYCLE.get("readBackVerified")),
        remote_wal_applied_sequence=int(
            _REMOTE_CYCLE.get("remoteWalAppliedSequence") or 0),
        verified_wal_sequence=int(
            _REMOTE_CYCLE.get("verifiedWalSequence") or 0),
        compact_receipt_hash=_REMOTE_CYCLE.get("compactReceiptHash"),
        error_class=_REMOTE_CYCLE.get("errorClass"),
        wal_read_back_verified=bool(
            _REMOTE_CYCLE.get("walReadBackVerified")),
        wal_error_class=_REMOTE_CYCLE.get("walErrorClass"),
        remote_durability_state=_REMOTE_CYCLE.get(
            "remoteDurabilityState"),
        receipt_commit_sha=_REMOTE_CYCLE.get("receiptCommitSha"),
        receipt_created_at=_REMOTE_CYCLE.get("receiptCreatedAt"),
        receipt_verified_at=_REMOTE_CYCLE.get("receiptVerifiedAt"),
        receipt_age_seconds=_REMOTE_CYCLE.get("receiptAgeSeconds"),
        receipt_attempts=int(_REMOTE_CYCLE.get("receiptAttempts") or 0),
        receipt_error_class=_REMOTE_CYCLE.get("receiptErrorClass"))
    return argus_persistent_storage.atomic_write_json(
        _MISSION_RECEIPT_FILE, receipt,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=argus_tick_durability.verify_remote_receipt)


def _persist_remote_receipt_queue(store=None):
    """Fsync the small intent queue without touching the legacy checkpoint."""
    global _REMOTE_RECEIPT_QUEUE
    candidate = (store if isinstance(store, dict)
                 else _REMOTE_RECEIPT_QUEUE)
    if not argus_remote_receipt_queue.verify_store(candidate):
        raise ValueError("remote_receipt_queue_invalid")
    result = argus_persistent_storage.atomic_write_json(
        _REMOTE_RECEIPT_QUEUE_FILE, candidate,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=argus_remote_receipt_queue.verify_store)
    _REMOTE_RECEIPT_QUEUE = copy.deepcopy(candidate)
    return result


def _restore_remote_receipt_queue():
    """Restore v13.4.2 intents or deterministically migrate the v13.4.1 sidecar."""
    global _REMOTE_RECEIPT_QUEUE
    try:
        with open(_REMOTE_RECEIPT_QUEUE_FILE, encoding="utf-8") as handle:
            restored = json.load(handle)
    except FileNotFoundError:
        restored = None
    except (OSError, json.JSONDecodeError):
        _DURABLE_STATE["remoteReceiptQueueRestore"] = "unreadable"
        return {"status": "unreadable"}
    if restored is not None:
        if not argus_remote_receipt_queue.verify_store(restored):
            _DURABLE_STATE["remoteReceiptQueueRestore"] = "tampered"
            return {"status": "tampered"}
        _REMOTE_RECEIPT_QUEUE = copy.deepcopy(restored)
        _DURABLE_STATE["remoteReceiptQueueRestore"] = "restored"
        return {"status": "restored", **argus_remote_receipt_queue.summary(
            _REMOTE_RECEIPT_QUEUE, now_iso=_ai_now_iso())}

    try:
        with open(_MISSION_RECEIPT_FILE, encoding="utf-8") as handle:
            legacy = json.load(handle)
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        legacy = None
    build_sha = _backend_exact_sha()
    if legacy is not None and build_sha:
        commit = str(legacy.get("remoteCommitSha") or "")
        migrated = argus_remote_receipt_queue.migrate_legacy_receipt(
            legacy, backend_build_sha=build_sha,
            idempotency_key=("migration-v1341-" +
                             hashlib.sha256(commit.encode("utf-8"))
                             .hexdigest()[:24]))
    else:
        migrated = argus_remote_receipt_queue.empty_store()
        migrated["migration"] = {
            "sourceSchemaVersion": (
                legacy.get("schemaVersion") if isinstance(legacy, dict)
                else None),
            "status": "no_migratable_receipt",
        }
    _persist_remote_receipt_queue(migrated)
    _DURABLE_STATE["remoteReceiptQueueRestore"] = "migrated"
    return {"status": "migrated", **argus_remote_receipt_queue.summary(
        _REMOTE_RECEIPT_QUEUE, now_iso=_ai_now_iso())}


def _persist_durability_metadata():
    """Persist receipt proof first, then non-payload recovery cursors."""
    saved_at = _ai_now_iso()
    receipt_write = _persist_remote_wal_receipt(saved_at)
    cursor = {
        "schemaVersion": "argus-mission-cursor-v1",
        "savedAt": saved_at,
        "buildSha": os.environ.get("RENDER_GIT_COMMIT") or _backend_sha(),
        "bootId": _RUNTIME.get("bootId") if "_RUNTIME" in globals() else None,
        "missionTickDurability": _mission_tick_durability_snapshot(),
    }
    cursor_write = argus_persistent_storage.atomic_write_json(
        _MISSION_CURSOR_FILE, cursor,
        temp_directory=_DURABILITY_PATHS["tempDirectory"])
    return {"cursor": _MISSION_CURSOR_FILE, "receipt": _MISSION_RECEIPT_FILE,
            "cursorWrite": cursor_write, "receiptWrite": receipt_write}


def _restore_persistent_remote_receipt():
    """Recover a newer fsynced receipt without rolling checkpoint truth back."""
    try:
        with open(_MISSION_RECEIPT_FILE, encoding="utf-8") as handle:
            receipt = json.load(handle)
    except FileNotFoundError:
        return {"status": "missing"}
    except (OSError, json.JSONDecodeError):
        _DURABLE_STATE["remoteReceiptRestore"] = "unreadable"
        return {"status": "unreadable"}
    if not argus_tick_durability.verify_remote_receipt(receipt):
        _DURABLE_STATE["remoteReceiptRestore"] = "tampered"
        return {"status": "tampered"}

    current_committed = argus_remote_journal._ep(
        _REMOTE_CYCLE.get("committedAt"))
    incoming_committed = argus_remote_journal._ep(receipt.get("committedAt"))
    if current_committed is not None and incoming_committed is not None and \
            incoming_committed < current_committed:
        _DURABLE_STATE["remoteReceiptRestore"] = "stale"
        return {"status": "stale"}

    current_sequence = int(
        _REMOTE_CYCLE.get("verifiedWalSequence") or 0)
    incoming_sequence = int(receipt.get("verifiedWalSequence") or 0)
    if receipt.get("walReadBackVerified") is True and \
            incoming_sequence < current_sequence:
        _DURABLE_STATE["remoteReceiptRestore"] = "sequence_regression"
        return {"status": "sequence_regression"}
    if _REMOTE_CYCLE.get("walReadBackVerified") is True and \
            receipt.get("walReadBackVerified") is not True and \
            receipt.get("remoteCommitSha") == \
            _REMOTE_CYCLE.get("remoteCommitSha"):
        _DURABLE_STATE["remoteReceiptRestore"] = "duplicate_older_state"
        return {"status": "duplicate_older_state"}

    current_receipt_hash = _REMOTE_CYCLE.get("compactReceiptHash")
    for key in (
            "remoteCommitSha", "committedAt", "expectedHash", "actualHash",
            "readBackAt", "readBackVerified", "walReadBackVerified",
            "remoteWalAppliedSequence", "verifiedWalSequence",
            "compactReceiptHash", "errorClass", "walErrorClass",
            "remoteDurabilityState", "receiptCommitSha",
            "receiptCreatedAt", "receiptVerifiedAt", "receiptAgeSeconds",
            "receiptAttempts", "receiptErrorClass"):
        if key in receipt:
            _REMOTE_CYCLE[key] = receipt.get(key)
    status = "duplicate" if (
        incoming_sequence == current_sequence and
        receipt.get("compactReceiptHash") ==
        current_receipt_hash
    ) else "restored"
    _DURABLE_STATE["remoteReceiptRestore"] = status
    return {"status": status, "verifiedWalSequence": incoming_sequence}


def _verified_persistent_wal_sequence():
    """Return coverage only when the fsynced receipt matches in-memory truth."""
    try:
        with open(_MISSION_RECEIPT_FILE, encoding="utf-8") as handle:
            receipt = json.load(handle)
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        return 0
    if not argus_tick_durability.verify_remote_receipt(receipt) or \
            receipt.get("readBackVerified") is not True or \
            receipt.get("walReadBackVerified") is not True:
        return 0
    for key in (
            "remoteCommitSha", "expectedHash", "actualHash",
            "compactReceiptHash"):
        if receipt.get(key) != _REMOTE_CYCLE.get(key):
            return 0
    sequence = int(receipt.get("verifiedWalSequence") or 0)
    if sequence != int(
            _REMOTE_CYCLE.get("verifiedWalSequence") or 0) or \
            sequence != int(
                receipt.get("remoteWalAppliedSequence") or 0):
        return 0
    return sequence


def _checkpoint_recovery_targets(checkpoint_blob, durability):
    """Extract every WAL-mutated target from one checkpoint read-back."""
    if not isinstance(checkpoint_blob, dict) or not isinstance(durability, dict):
        raise ValueError("recovery_checkpoint_projection_invalid")
    required = set(argus_remote_recovery.TARGET_KEYS) - {
        "missionTickDurability"}
    if not required.issubset(checkpoint_blob):
        raise ValueError("recovery_checkpoint_projection_incomplete")
    result = {
        key: copy.deepcopy(checkpoint_blob[key]) for key in required}
    result["missionTickDurability"] = copy.deepcopy(durability)
    return result


def _recovery_ledger_base(checkpoint_blob):
    cycle = checkpoint_blob.get("remoteJournalCycle")
    if not isinstance(cycle, dict) or cycle.get("readBackVerified") is not True or \
            cycle.get("walReadBackVerified") is not True or \
            cycle.get("remoteDurabilityState") != "verified" or \
            any(cycle.get(key) not in (None, "") for key in (
                "errorClass", "walErrorClass", "receiptErrorClass")):
        raise ValueError("recovery_ledger_base_unverified")
    commit = str(cycle.get("remoteCommitSha") or "").lower()
    expected = str(cycle.get("expectedHash") or "").lower()
    actual = str(cycle.get("actualHash") or "").lower()
    receipt_hash = str(cycle.get("compactReceiptHash") or "").lower()
    remote_wal = cycle.get("remoteWalAppliedSequence")
    verified_wal = cycle.get("verifiedWalSequence")
    receipt_commit = str(cycle.get("receiptCommitSha") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", commit) or \
            receipt_commit != commit or \
            not re.fullmatch(r"[0-9a-f]{16}", expected) or \
            expected != actual or not re.fullmatch(
                r"[0-9a-f]{16}", receipt_hash) or \
            isinstance(remote_wal, bool) or not isinstance(remote_wal, int) or \
            isinstance(verified_wal, bool) or not isinstance(verified_wal, int) or \
            remote_wal <= 0 or remote_wal != verified_wal:
        raise ValueError("recovery_ledger_base_invalid")
    return commit


_REMOTE_RECOVERY_NONCE_STATE_LEGACY_SCHEMA = \
    "argus-remote-recovery-nonce-v2"
_REMOTE_RECOVERY_NONCE_STATE_SCHEMA = "argus-remote-recovery-nonce-v3"
_REMOTE_RECOVERY_NONCE_HISTORY_SCHEMA = \
    "argus-remote-recovery-nonce-history-v1"
_REMOTE_RECOVERY_NONCE_HISTORY_HEAD_SCHEMA = \
    "argus-remote-recovery-nonce-history-head-v1"
_REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES = 4096
_REMOTE_RECOVERY_NONCE_MAX_DOMAINS = 16
_REMOTE_RECOVERY_NONCE_MAX = (1 << 96) - 1
_REMOTE_RECOVERY_NONCE_LOCK_HEADER = \
    b"argus-remote-recovery-nonce-anchor-v1\n"
_REMOTE_RECOVERY_NONCE_ANCHOR_HEADER = \
    b"argus-remote-recovery-nonce-anchor-v2\n"
_REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES = 4172
_REMOTE_RECOVERY_NONCE_LOCK_PAYLOAD_BYTES = 4096
_REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES = 64 * 1024 * 1024
_REMOTE_RECOVERY_NONCE_ANCHOR_HEADER_BYTES = \
    len(_REMOTE_RECOVERY_NONCE_ANCHOR_HEADER) + 8 + 8 + 32 + 32


def _remote_recovery_nonce_anchor_path(handle):
    return handle._argus_nonce_anchor_path


class _AuthenticatedRemoteRecoveryNonceFloor:
    """Process-private handoff for one authenticated remote nonce floor.

    Key material must never be copied into a checkpoint, provenance, durable
    status, or log.  A slotted, non-serializable-by-our-JSON-writer object keeps
    the authenticated material and counter confined to the cold-restore call
    stack until the local current-key reservation has consumed the handoff.
    """

    __slots__ = ("_key", "_remote_counter", "_seeded_counter")

    def __init__(self, key, remote_counter):
        self._key = key
        self._remote_counter = remote_counter
        self._seeded_counter = None


class _RemoteRecoveryNonceReservation:
    """Process-private nonce plus the exact committed carry-forward floors."""

    __slots__ = ("_nonce", "_key_material_counters")

    def __init__(self, nonce, key_material_counters):
        self._nonce = nonce
        self._key_material_counters = dict(key_material_counters)


_REMOTE_RECOVERY_AUTHORITY_PROCESS_TOKEN = object()


class _AuthenticatedRemoteRecoveryNonceAuthority:
    """Process-private capability for one AES-authenticated authority map."""

    __slots__ = ("_token", "_key_material_counters", "_seeded_counters")

    def __init__(self, key_material_counters):
        self._token = _REMOTE_RECOVERY_AUTHORITY_PROCESS_TOKEN
        self._key_material_counters = dict(key_material_counters)
        self._seeded_counters = None


_PINNED_REMOTE_RECOVERY_PROCESS_TOKEN = object()


class _AuthenticatedPinnedRemoteRecoveryEvidence(
        _AuthenticatedRemoteRecoveryNonceAuthority):
    """One private, immutable-ref recovery pair authenticated during boot.

    The decrypted payload can contain private mission state.  It therefore
    stays in a slotted process object and is never placed in durable status,
    checkpoint provenance, logging, or an exception.  Inheriting the nonce
    authority capability lets the same authenticated object seed every
    carried material floor before either local or remote state is selected.
    """

    __slots__ = (
        "_pinned_token", "_base", "_commit_sha", "_owner", "_repository",
        "_readback", "_envelope", "_payload", "_selected", "_ancestry",
    )

    def __init__(
            self, pinned_ledger, readback, envelope, payload, selected,
            ancestry, key_material_counters):
        super().__init__(key_material_counters)
        self._pinned_token = _PINNED_REMOTE_RECOVERY_PROCESS_TOKEN
        self._base = pinned_ledger["base"]
        self._commit_sha = pinned_ledger["commitSha"]
        self._owner = pinned_ledger["owner"]
        self._repository = pinned_ledger["repository"]
        self._readback = copy.deepcopy(readback)
        self._envelope = copy.deepcopy(envelope)
        self._payload = copy.deepcopy(payload)
        self._selected = {
            "keyId": selected["keyId"], "key": selected["key"]}
        self._ancestry = copy.deepcopy(ancestry)


_PINNED_LEGACY_READBACK_PROCESS_TOKEN = object()


class _AuthenticatedPinnedLegacyReadbackEvidence:
    """Process-private exact readback from a proved pre-sidecar ledger.

    During the one activation window the immutable ledger head can still be a
    legacy compact-only generation while the local disk already contains a
    keyed checkpoint/sidecar pair.  The exact readback and its pinned ref stay
    in this capability so boot can compare public WAL/receipt authority before
    accepting local private state.  The capability is minted only after the
    recovery path-history query proves that no sidecar existed at or before
    the same immutable head.
    """

    __slots__ = (
        "_token", "_base", "_commit_sha", "_owner", "_repository",
        "_path_prefix", "_readback", "_readback_hash", "_restore_token",
    )

    def __init__(self, pinned_ledger, readback, restore_token=None):
        self._token = _PINNED_LEGACY_READBACK_PROCESS_TOKEN
        self._base = pinned_ledger["base"]
        self._commit_sha = pinned_ledger["commitSha"]
        self._owner = pinned_ledger["owner"]
        self._repository = pinned_ledger["repository"]
        self._path_prefix = pinned_ledger["pathPrefix"]
        self._readback = copy.deepcopy(readback)
        self._readback_hash = \
            argus_persistent_storage._canonical_sha256(readback)
        self._restore_token = restore_token


_LEGACY_RECOVERY_LEDGER_BASE_PROCESS_TOKEN = object()


class _LegacyRecoveryLedgerBaseCapability:
    """Single-use first-activation authority for one staged checkpoint.

    The capability never becomes durable authority.  It binds the exact
    authenticated legacy readback, pinned Git head, restore invocation,
    sealed local generation, key material domain, and proved linear ancestry.
    Ordinary checkpoint writers cannot construct or consume it.
    """

    __slots__ = (
        "_token", "_restore_token", "_legacy_evidence", "_pinned_ledger",
        "_checkpoint_hash", "_target_wal", "_remote_wal",
        "_remote_receipt_hash", "_base_commit", "_ancestry", "_key_id",
        "_key_domain", "_binding_hash", "_consumed",
    )

    def __init__(
            self, restore_token, legacy_evidence, pinned_ledger,
            checkpoint_hash, target_wal, remote_wal, remote_receipt_hash,
            base_commit, ancestry, key_id, key_domain):
        self._token = _LEGACY_RECOVERY_LEDGER_BASE_PROCESS_TOKEN
        self._restore_token = restore_token
        self._legacy_evidence = legacy_evidence
        self._pinned_ledger = copy.deepcopy(pinned_ledger)
        self._checkpoint_hash = checkpoint_hash
        self._target_wal = target_wal
        self._remote_wal = remote_wal
        self._remote_receipt_hash = remote_receipt_hash
        self._base_commit = base_commit
        self._ancestry = copy.deepcopy(ancestry)
        self._key_id = key_id
        self._key_domain = key_domain
        self._binding_hash = \
            _legacy_recovery_ledger_base_capability_hash(self)
        self._consumed = False


def _legacy_recovery_ledger_base_capability_hash(capability):
    return argus_persistent_storage._canonical_sha256({
        "pinnedLedger": capability._pinned_ledger,
        "checkpointHash": capability._checkpoint_hash,
        "targetWalSequence": capability._target_wal,
        "remoteWalSequence": capability._remote_wal,
        "remoteReceiptHash": capability._remote_receipt_hash,
        "ledgerBaseCommitSha": capability._base_commit,
        "ancestry": capability._ancestry,
        "keyId": capability._key_id,
        "keyMaterialDomain": capability._key_domain,
        "legacyReadbackHash": capability._legacy_evidence._readback_hash,
    })


_LOCAL_RECOVERY_PAIR_PROCESS_TOKEN = object()


class _AuthenticatedLocalRecoveryPair:
    """Process-private exact local checkpoint/sidecar authentication result."""

    __slots__ = (
        "_token", "_readback", "_payload", "_envelope", "_selected",
        "_ledger_commit",
    )

    def __init__(
            self, readback, payload, envelope, selected, ledger_commit):
        self._token = _LOCAL_RECOVERY_PAIR_PROCESS_TOKEN
        self._readback = copy.deepcopy(readback)
        self._payload = copy.deepcopy(payload)
        self._envelope = copy.deepcopy(envelope)
        self._selected = {
            "keyId": selected["keyId"], "key": selected["key"]}
        self._ledger_commit = ledger_commit


_REMOTE_RECOVERY_GENESIS_PROCESS_TOKEN = object()


class _RemoteRecoveryNonceGenesisCapability:
    """Single-use, process-private proof for the one legacy activation.

    The capability is deliberately neither serializable nor reconstructible
    from durable state.  It binds the exact canonical sealed checkpoint inode
    observed after an authoritative Git path-history absence proof.  Normal
    nonce reservation never accepts this object and therefore cannot silently
    reinterpret deleted or rolled-back authority as a new installation.
    """

    __slots__ = (
        "_token", "_checkpoint_path", "_checkpoint_hash",
        "_checkpoint_identity", "_key_domain", "_pinned_commit",
        "_consumed",
    )

    def __init__(
            self, checkpoint_path, checkpoint_hash, checkpoint_identity,
            key_domain, pinned_commit):
        self._token = _REMOTE_RECOVERY_GENESIS_PROCESS_TOKEN
        self._checkpoint_path = checkpoint_path
        self._checkpoint_hash = checkpoint_hash
        self._checkpoint_identity = checkpoint_identity
        self._key_domain = key_domain
        self._pinned_commit = pinned_commit
        self._consumed = False


def _remote_recovery_file_identity(metadata):
    return (
        metadata.st_dev, metadata.st_ino, metadata.st_mode, metadata.st_size,
        metadata.st_mtime_ns, metadata.st_ctime_ns)


def _remote_recovery_nonce_domain(key):
    """Return a private state index bound to AES key material, not its ID."""
    # This pseudonymous value is confined to the private nonce-state file.  It
    # is never included in the public envelope, telemetry, logs, or errors.
    return argus_remote_recovery.nonce_material_domain(key)


def _validated_remote_recovery_nonce_counters(value, *, allow_empty=False):
    if not isinstance(value, dict) or len(value) > \
            _REMOTE_RECOVERY_NONCE_MAX_DOMAINS or (
                not value and not allow_empty):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_invalid")
    counters = {}
    for domain, counter in value.items():
        if not isinstance(domain, str) or not re.fullmatch(
                r"[0-9a-f]{64}", domain) or isinstance(counter, bool) or \
                not isinstance(counter, int) or counter < 1 or \
                counter > _REMOTE_RECOVERY_NONCE_MAX:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_invalid")
        counters[domain] = counter
    return counters


def _validated_remote_recovery_nonce_state(value):
    if not isinstance(value, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_invalid")
    schema = value.get("schemaVersion")
    if schema == _REMOTE_RECOVERY_NONCE_STATE_LEGACY_SCHEMA:
        if set(value) != {"schemaVersion", "keyMaterialCounters"}:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_invalid")
        return {
            "schemaVersion": schema,
            "keyMaterialCounters":
                _validated_remote_recovery_nonce_counters(
                    value.get("keyMaterialCounters")),
        }
    if schema != _REMOTE_RECOVERY_NONCE_STATE_SCHEMA or set(value) != {
            "schemaVersion", "historyGeneration", "historyRecordHash",
            "keyMaterialCounters"}:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_invalid")
    generation = value.get("historyGeneration")
    record_hash = str(value.get("historyRecordHash") or "")
    if isinstance(generation, bool) or not isinstance(generation, int) or \
            generation < 0 or not re.fullmatch(r"[0-9a-f]{64}", record_hash):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_invalid")
    return {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_STATE_SCHEMA,
        "historyGeneration": generation,
        "historyRecordHash": record_hash,
        "keyMaterialCounters":
            _validated_remote_recovery_nonce_counters(
                value.get("keyMaterialCounters"),
                allow_empty=(generation == 0)),
    }


def _remote_recovery_nonce_record_hash(value):
    return hashlib.sha256(
        argus_persistent_storage._canonical(value)).hexdigest()


def _validated_remote_recovery_nonce_history(value):
    if not isinstance(value, dict) or set(value) != {
            "schemaVersion", "generation", "previousRecordHash",
            "keyMaterialCounters", "recordHash"} or value.get(
                "schemaVersion") != _REMOTE_RECOVERY_NONCE_HISTORY_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_invalid")
    generation = value.get("generation")
    previous = value.get("previousRecordHash")
    if isinstance(generation, bool) or not isinstance(generation, int) or \
            generation < 0 or (generation == 0 and previous is not None) or \
            (generation > 0 and not re.fullmatch(
                r"[0-9a-f]{64}", str(previous or ""))):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_invalid")
    counters = _validated_remote_recovery_nonce_counters(
        value.get("keyMaterialCounters"), allow_empty=(generation == 0))
    body = {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_HISTORY_SCHEMA,
        "generation": generation,
        "previousRecordHash": previous,
        "keyMaterialCounters": counters,
    }
    record_hash = str(value.get("recordHash") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", record_hash) or \
            not hmac.compare_digest(
                record_hash, _remote_recovery_nonce_record_hash(body)):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_invalid")
    return {**body, "recordHash": record_hash}


def _build_remote_recovery_nonce_history(
        generation, previous_record_hash, counters):
    body = {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_HISTORY_SCHEMA,
        "generation": generation,
        "previousRecordHash": previous_record_hash,
        "keyMaterialCounters":
            _validated_remote_recovery_nonce_counters(
                counters, allow_empty=(generation == 0)),
    }
    return _validated_remote_recovery_nonce_history({
        **body, "recordHash": _remote_recovery_nonce_record_hash(body)})


def _validated_remote_recovery_nonce_history_head(value):
    if not isinstance(value, dict) or set(value) != {
            "schemaVersion", "generation", "recordHash", "headHash"} or \
            value.get("schemaVersion") != \
            _REMOTE_RECOVERY_NONCE_HISTORY_HEAD_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_head_invalid")
    generation = value.get("generation")
    record_hash = str(value.get("recordHash") or "")
    if isinstance(generation, bool) or not isinstance(generation, int) or \
            generation < 0 or not re.fullmatch(r"[0-9a-f]{64}", record_hash):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_head_invalid")
    body = {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_HISTORY_HEAD_SCHEMA,
        "generation": generation,
        "recordHash": record_hash,
    }
    head_hash = str(value.get("headHash") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", head_hash) or not \
            hmac.compare_digest(
                head_hash, _remote_recovery_nonce_record_hash(body)):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_head_invalid")
    return {**body, "headHash": head_hash}


def _build_remote_recovery_nonce_history_head(history):
    body = {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_HISTORY_HEAD_SCHEMA,
        "generation": history["generation"],
        "recordHash": history["recordHash"],
    }
    return _validated_remote_recovery_nonce_history_head({
        **body, "headHash": _remote_recovery_nonce_record_hash(body)})


def _remote_recovery_crash_boundary(_name):
    """No-op production hook used by deterministic crash-matrix tests."""


def _acquire_remote_recovery_nonce_lock(
        path, *, blocking=True, create=True):
    descriptor = None
    handle = None
    created = False
    try:
        lock_path = path + ".reservation.lock"
        _remote_recovery_crash_boundary("before_lock_creation")
        if not create:
            descriptor = os.open(
                lock_path,
                os.O_RDWR | getattr(os, "O_NOFOLLOW", 0))
        else:
            try:
                descriptor = os.open(
                    lock_path,
                    os.O_RDWR | os.O_CREAT | os.O_EXCL |
                    getattr(os, "O_NOFOLLOW", 0), 0o600)
                created = True
                _remote_recovery_crash_boundary("after_empty_lock_creation")
            except FileExistsError:
                descriptor = os.open(
                    lock_path,
                    os.O_RDWR | getattr(os, "O_NOFOLLOW", 0))
        handle = os.fdopen(descriptor, "a+b")
        handle._argus_nonce_anchor_path = lock_path + ".anchor"
        handle._argus_nonce_lock_created = created
        descriptor = None
        metadata = os.fstat(handle.fileno())
        if not stat.S_ISREG(metadata.st_mode):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_lock_invalid")
        if stat.S_IMODE(metadata.st_mode) & 0o077:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_lock_permissions_invalid")
        operation = fcntl.LOCK_EX
        if not blocking:
            operation |= fcntl.LOCK_NB
        fcntl.flock(handle.fileno(), operation)
        installed = os.stat(lock_path, follow_symlinks=False)
        if (metadata.st_dev, metadata.st_ino) != \
                (installed.st_dev, installed.st_ino):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_lock_changed")
        _remote_recovery_crash_boundary("after_initial_lock_metadata")
        return handle
    except BlockingIOError as exc:
        if handle is not None:
            handle.close()
            handle = None
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_lock_busy") from exc
    except Exception:
        if handle is not None:
            handle.close()
        elif descriptor is not None:
            os.close(descriptor)
        raise


def _release_remote_recovery_nonce_lock(handle):
    if handle is None:
        return
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    except OSError:
        pass
    handle.close()


def _remote_recovery_nonce_lock_anchor(handle):
    """Read the latest fixed-width monotonic anchor from the locked file."""
    epoch_path = _remote_recovery_nonce_anchor_path(handle)
    try:
        if os.path.lexists(epoch_path):
            descriptor = os.open(
                epoch_path,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
            try:
                metadata = os.fstat(descriptor)
                if not stat.S_ISREG(metadata.st_mode) or \
                        stat.S_IMODE(metadata.st_mode) & 0o077:
                    raise OSError("recovery_nonce_lock_permissions_invalid")
                with os.fdopen(descriptor, "rb", buffering=0) as anchor_handle:
                    descriptor = None
                    return argus_remote_nonce_anchor.read(
                        anchor_handle,
                        maximum_bytes=_REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES,
                        validate_counters=
                        _validated_remote_recovery_nonce_counters)
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        size = os.fstat(handle.fileno()).st_size
        if size == 0:
            return None
        header_bytes = len(_REMOTE_RECOVERY_NONCE_LOCK_HEADER)
        if size < header_bytes + _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES or \
                size > _REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES or \
                (size - header_bytes) % \
                _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES:
            raise OSError("recovery_nonce_lock_size_invalid")
        handle.seek(0)
        if handle.read(header_bytes) != _REMOTE_RECOVERY_NONCE_LOCK_HEADER:
            raise OSError("recovery_nonce_lock_header_invalid")
        count = (size - header_bytes) // \
            _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES
        handle.seek(size - _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES)
        encoded = handle.read(_REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES)
        generation = struct.unpack(">Q", encoded[:8])[0]
        history_hash = encoded[8:40]
        payload_length = struct.unpack(">I", encoded[40:44])[0]
        if payload_length <= 0 or payload_length > \
                _REMOTE_RECOVERY_NONCE_LOCK_PAYLOAD_BYTES:
            raise OSError("recovery_nonce_lock_record_invalid")
        payload_bytes = encoded[44:44 + payload_length]
        if any(encoded[44 + payload_length:4140]):
            raise OSError("recovery_nonce_lock_record_invalid")
        try:
            payload = json.loads(payload_bytes.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise OSError("recovery_nonce_lock_record_invalid") from exc
        if not isinstance(payload, dict) or set(payload) != {
                "previousRecordHash", "keyMaterialCounters"}:
            raise OSError("recovery_nonce_lock_record_invalid")
        previous_record_hash = payload["previousRecordHash"]
        counters = _validated_remote_recovery_nonce_counters(
            payload["keyMaterialCounters"], allow_empty=(generation == 0))
        journal_hash = encoded[4140:4172]
        if count == 1:
            previous_generation = None
            previous_journal_hash = hashlib.sha256(
                _REMOTE_RECOVERY_NONCE_LOCK_HEADER).digest()
        else:
            handle.seek(size - 2 * _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES)
            previous = handle.read(_REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES)
            previous_generation = struct.unpack(">Q", previous[:8])[0]
            previous_journal_hash = previous[4140:4172]
        expected = hashlib.sha256(
            previous_journal_hash + encoded[:4140]).digest()
        if generation != count - 1 or (
                previous_generation is not None and
                previous_generation + 1 != generation) or not \
                hmac.compare_digest(journal_hash, expected):
            raise OSError("recovery_nonce_lock_record_invalid")
        return {
            "generation": generation,
            "recordHash": history_hash.hex(),
            "journalHash": journal_hash.hex(),
            "previousRecordHash": previous_record_hash,
            "counters": counters,
        }
    except (OSError, argus_remote_nonce_anchor.AnchorError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_lock_invalid") from exc


def _append_remote_recovery_nonce_lock_anchor(handle, history):
    current = _remote_recovery_nonce_lock_anchor(handle)
    expected_generation = 0 if current is None else current["generation"] + 1
    if history["generation"] != expected_generation or (
            current is not None and history["previousRecordHash"] !=
            current["recordHash"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_lock_sequence_invalid")
    try:
        epoch_path = _remote_recovery_nonce_anchor_path(handle)
        if os.path.lexists(epoch_path):
            descriptor = os.open(
                epoch_path,
                os.O_RDWR | getattr(os, "O_NOFOLLOW", 0))
            try:
                metadata = os.fstat(descriptor)
                if not stat.S_ISREG(metadata.st_mode) or \
                        stat.S_IMODE(metadata.st_mode) & 0o077:
                    raise OSError("recovery_nonce_lock_permissions_invalid")
                with os.fdopen(descriptor, "r+b", buffering=0) as anchor_handle:
                    descriptor = None
                    return argus_remote_nonce_anchor.append(
                        anchor_handle, history, path=epoch_path,
                        maximum_bytes=_REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES,
                        validate_counters=
                        _validated_remote_recovery_nonce_counters)
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        if current is not None and os.fstat(handle.fileno()).st_size + \
                _REMOTE_RECOVERY_NONCE_LOCK_RECORD_BYTES > \
                _REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES:
            # Re-read the v1 journal through the epoch codec to obtain its
            # terminal epoch digest; the legacy scanner shape intentionally
            # exposed only generation/counter fields.
            rollover_current = argus_remote_nonce_anchor.read(
                handle,
                maximum_bytes=_REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES,
                validate_counters=_validated_remote_recovery_nonce_counters)
            return argus_remote_nonce_anchor.replace_successor(
                epoch_path, rollover_current, history,
                maximum_bytes=_REMOTE_RECOVERY_NONCE_LOCK_MAX_BYTES,
                validate_counters=_validated_remote_recovery_nonce_counters)
        if current is None:
            previous_journal_hash = hashlib.sha256(
                _REMOTE_RECOVERY_NONCE_LOCK_HEADER).digest()
            handle.seek(0)
            handle.write(_REMOTE_RECOVERY_NONCE_LOCK_HEADER)
        else:
            previous_journal_hash = bytes.fromhex(current["journalHash"])
            handle.seek(0, os.SEEK_END)
        try:
            payload = argus_persistent_storage._canonical({
                "previousRecordHash": history["previousRecordHash"],
                "keyMaterialCounters": history["keyMaterialCounters"],
            })
            if len(payload) > _REMOTE_RECOVERY_NONCE_LOCK_PAYLOAD_BYTES:
                raise OSError("recovery_nonce_lock_payload_oversized")
            prefix = (
                struct.pack(">Q", history["generation"]) +
                bytes.fromhex(history["recordHash"]) +
                struct.pack(">I", len(payload)) + payload +
                b"\x00" * (_REMOTE_RECOVERY_NONCE_LOCK_PAYLOAD_BYTES -
                           len(payload)))
        except (TypeError, ValueError) as exc:
            raise OSError("recovery_nonce_lock_payload_invalid") from exc
        record = prefix + hashlib.sha256(
            previous_journal_hash + prefix).digest()
        handle.write(record)
        handle.flush()
        os.fsync(handle.fileno())
        verified = _remote_recovery_nonce_lock_anchor(handle)
        if verified["generation"] != history["generation"] or not \
                hmac.compare_digest(
                    verified["recordHash"], history["recordHash"]):
            raise OSError("recovery_nonce_lock_readback_failed")
    except (OSError, argus_remote_nonce_anchor.AnchorError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_lock_activation_failed") from exc
    return verified


def _read_remote_recovery_nonce_json(
        path, *, missing_ok, validator, invalid_classification,
        require_private):
    """Read one bounded stable private JSON inode without following links."""
    descriptor = None
    try:
        descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_size <= 0 or \
                before.st_size > _REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES or \
                (require_private and stat.S_IMODE(before.st_mode) & 0o077):
            raise argus_remote_recovery.RecoveryBundleError(
                invalid_classification)
        encoded = bytearray()
        while True:
            chunk = os.read(descriptor, 4096)
            if not chunk:
                break
            if len(encoded) + len(chunk) > \
                    _REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES:
                raise argus_remote_recovery.RecoveryBundleError(
                    invalid_classification)
            encoded.extend(chunk)
        after = os.fstat(descriptor)
        current = os.stat(path, follow_symlinks=False)
        identity = lambda item: (
            item.st_dev, item.st_ino, item.st_mode, item.st_size,
            item.st_mtime_ns, item.st_ctime_ns)
        if identity(before) != identity(after) or identity(after) != \
                identity(current) or len(encoded) != after.st_size:
            raise argus_remote_recovery.RecoveryBundleError(
                f"{invalid_classification}_changed")
        try:
            value = json.loads(encoded.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise argus_remote_recovery.RecoveryBundleError(
                invalid_classification) from exc
        return validator(value)
    except FileNotFoundError:
        if missing_ok:
            return None
        raise argus_remote_recovery.RecoveryBundleError(
            f"{invalid_classification}_missing")
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except (OSError, TypeError, ValueError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            f"{invalid_classification}_unreadable") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _write_remote_recovery_nonce_state(path, history):
    reserved = _validated_remote_recovery_nonce_state({
        "schemaVersion": _REMOTE_RECOVERY_NONCE_STATE_SCHEMA,
        "historyGeneration": history["generation"],
        "historyRecordHash": history["recordHash"],
        "keyMaterialCounters": history["keyMaterialCounters"],
    })
    write = argus_persistent_storage.atomic_write_json(
        path, reserved,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=lambda value: value == reserved,
        temp_label="recovery-nonce",
        maximum_bytes=_REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES,
        file_mode=0o600)
    if write.get("readBackVerified") is not True or \
            _read_remote_recovery_nonce_state(
                path, missing_ok=False) != reserved:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_unverified")
    return reserved


def _read_remote_recovery_nonce_state(path, *, missing_ok):
    value = _read_remote_recovery_nonce_json(
        path, missing_ok=missing_ok,
        validator=_validated_remote_recovery_nonce_state,
        invalid_classification="recovery_nonce_state",
        # A legacy v2 file may predate explicit mode enforcement.  It is
        # rewritten 0600 before a nonce can be returned.
        require_private=False)
    if value is not None and value.get("schemaVersion") == \
            _REMOTE_RECOVERY_NONCE_STATE_SCHEMA:
        try:
            if stat.S_IMODE(os.stat(
                    path, follow_symlinks=False).st_mode) & 0o077:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_nonce_state_permissions_invalid")
        except FileNotFoundError as exc:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_changed") from exc
    return value


def _read_remote_recovery_nonce_history(path, *, missing_ok):
    return _read_remote_recovery_nonce_json(
        path, missing_ok=missing_ok,
        validator=_validated_remote_recovery_nonce_history,
        invalid_classification="recovery_nonce_history",
        require_private=True)


def _read_remote_recovery_nonce_history_head(path, *, missing_ok):
    return _read_remote_recovery_nonce_json(
        path, missing_ok=missing_ok,
        validator=_validated_remote_recovery_nonce_history_head,
        invalid_classification="recovery_nonce_history_head",
        require_private=True)


def _write_remote_recovery_nonce_history(path, history):
    write = argus_persistent_storage.atomic_write_json(
        path, history,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=lambda value: value == history,
        temp_label="recovery-nonce-history",
        maximum_bytes=_REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES,
        file_mode=0o600)
    if write.get("readBackVerified") is not True or \
            _read_remote_recovery_nonce_history(
                path, missing_ok=False) != history:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_unverified")


def _write_remote_recovery_nonce_history_head(path, history):
    head = _build_remote_recovery_nonce_history_head(history)
    write = argus_persistent_storage.atomic_write_json(
        path, head,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=lambda value: value == head,
        temp_label="recovery-nonce-history-head",
        maximum_bytes=_REMOTE_RECOVERY_NONCE_STATE_MAX_BYTES,
        file_mode=0o600)
    if write.get("readBackVerified") is not True or \
            _read_remote_recovery_nonce_history_head(
                path, missing_ok=False) != head:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_head_unverified")
    return head


def _remote_recovery_nonce_paths():
    return {
        "state": _DURABILITY_PATHS["recoveryNonceState"],
        "history": _DURABILITY_PATHS["recoveryNonceHistory"],
        "head": _DURABILITY_PATHS["recoveryNonceHistoryHead"],
    }


def _load_remote_recovery_nonce_authority(
        lock_handle, configured, *, allow_activation,
        verify_installed_floor=True):
    """Load or migrate the private authority under the reservation lock."""
    paths = _remote_recovery_nonce_paths()
    anchor = _remote_recovery_nonce_lock_anchor(lock_handle)
    history = _read_remote_recovery_nonce_history(
        paths["history"], missing_ok=True)
    head = _read_remote_recovery_nonce_history_head(
        paths["head"], missing_ok=True)
    state = _read_remote_recovery_nonce_state(
        paths["state"], missing_ok=True)
    if history is None and head is None:
        if anchor is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_missing")
        if not allow_activation:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_missing")
        counters = {}
        if state is not None:
            if state.get("schemaVersion") == \
                    _REMOTE_RECOVERY_NONCE_STATE_SCHEMA:
                # A v3 cache proves history existed.  Missing authority is
                # deletion/rollback, never a fresh activation.
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_nonce_history_missing")
            counters.update(state["keyMaterialCounters"])
        installed = _installed_remote_recovery_nonce_floor(configured)
        if installed is not None:
            installed_domain, installed_counter = installed
            counters[installed_domain] = max(
                int(counters.get(installed_domain) or 0), installed_counter)
        history = _build_remote_recovery_nonce_history(
            0, None, counters)
        _write_remote_recovery_nonce_history(paths["history"], history)
        _remote_recovery_crash_boundary("after_history_write")
        head = _write_remote_recovery_nonce_history_head(
            paths["head"], history)
        _remote_recovery_crash_boundary("after_head_write")
        _append_remote_recovery_nonce_lock_anchor(lock_handle, history)
        _remote_recovery_crash_boundary("after_anchor_write")
        state = _write_remote_recovery_nonce_state(paths["state"], history)
        return history, head, state

    if history is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_missing")

    # Complete only exact one-generation crash windows.  The append-only
    # anchor is committed first; a following history/head/state replace may
    # fail and is safely reconstructed from the anchor's counter record.
    if anchor is None:
        if history["generation"] != 0:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_lock_missing")
        if head is None:
            head = _write_remote_recovery_nonce_history_head(
                paths["head"], history)
        elif head["generation"] != 0 or not hmac.compare_digest(
                head["recordHash"], history["recordHash"]):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_rollback")
        anchor = _append_remote_recovery_nonce_lock_anchor(
            lock_handle, history)
    elif history["generation"] + 1 == anchor["generation"] and \
            anchor.get("counters") is not None and \
            anchor.get("previousRecordHash") == history["recordHash"]:
        if head is not None and (
                head["generation"] != history["generation"] or not
                hmac.compare_digest(
                    head["recordHash"], history["recordHash"])):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_rollback")
        history = _build_remote_recovery_nonce_history(
            anchor["generation"], anchor["previousRecordHash"],
            anchor["counters"])
        if not hmac.compare_digest(
                history["recordHash"], anchor["recordHash"]):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_rollback")
        _write_remote_recovery_nonce_history(paths["history"], history)
        head = _write_remote_recovery_nonce_history_head(
            paths["head"], history)
    elif history["generation"] != anchor["generation"] or not \
            hmac.compare_digest(
                history["recordHash"], anchor["recordHash"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_rollback")

    if history["generation"] != anchor["generation"] or not \
            hmac.compare_digest(
                history["recordHash"], anchor["recordHash"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_rollback")
    expected_head = _build_remote_recovery_nonce_history_head(history)
    if head != expected_head:
        # The fsynced anchor is committed before its replaceable mirrors.  If
        # the exact history mirror reached the same authority but the process
        # crashed immediately before/during the head replace, repairing that
        # derived head cannot lower a counter.  A future or otherwise
        # divergent head remains rollback evidence and is never overwritten.
        if head is not None and head["generation"] >= history["generation"]:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_rollback")
        head = _write_remote_recovery_nonce_history_head(
            paths["head"], history)
    expected_state = {
        "schemaVersion": _REMOTE_RECOVERY_NONCE_STATE_SCHEMA,
        "historyGeneration": history["generation"],
        "historyRecordHash": history["recordHash"],
        "keyMaterialCounters": history["keyMaterialCounters"],
    }
    if state != expected_state:
        state = _write_remote_recovery_nonce_state(paths["state"], history)
    if verify_installed_floor:
        _verify_installed_remote_recovery_nonce_floor(history, configured)
    return history, head, state


def _commit_remote_recovery_nonce_authority(
        lock_handle, history, counters):
    """Commit a consumed floor before returning or encrypting with a nonce."""
    paths = _remote_recovery_nonce_paths()
    anchor = _remote_recovery_nonce_lock_anchor(lock_handle)
    if anchor is None or anchor["generation"] != history["generation"] or \
            not hmac.compare_digest(
                anchor["recordHash"], history["recordHash"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_rollback")
    next_history = _build_remote_recovery_nonce_history(
        history["generation"] + 1, history["recordHash"], counters)
    # The append-only anchor is the monotonic authority.  Commit it before the
    # replaceable mirrors.  If either later write fails, the next invocation
    # sees mirrors one generation behind and reconstructs the consumed floor
    # from this anchor record instead of reusing the nonce.
    _append_remote_recovery_nonce_lock_anchor(lock_handle, next_history)
    _remote_recovery_crash_boundary("after_durable_reservation_anchor")
    _write_remote_recovery_nonce_history(paths["history"], next_history)
    _remote_recovery_crash_boundary("after_history_write")
    _write_remote_recovery_nonce_history_head(paths["head"], next_history)
    _remote_recovery_crash_boundary("after_head_write")
    _write_remote_recovery_nonce_state(paths["state"], next_history)
    verified_history = _read_remote_recovery_nonce_history(
        paths["history"], missing_ok=False)
    verified_head = _read_remote_recovery_nonce_history_head(
        paths["head"], missing_ok=False)
    verified_state = _read_remote_recovery_nonce_state(
        paths["state"], missing_ok=False)
    if verified_history != next_history or \
            verified_head != _build_remote_recovery_nonce_history_head(
                next_history) or verified_state.get(
                    "historyRecordHash") != next_history["recordHash"]:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_commit_unverified")
    return next_history


def _installed_remote_recovery_nonce_floor(configured):
    """Authenticate the installed sidecar and return its material-domain floor."""
    if not os.path.lexists(_REMOTE_RECOVERY_FILE):
        return None
    sidecar = _read_local_recovery_sidecar()
    envelope = sidecar["recovery"]
    selected = None
    for slot in ("current", "previous"):
        candidate = configured.get(slot)
        if not isinstance(candidate, dict):
            continue
        try:
            # Pass the authenticated envelope ID deliberately: this detects
            # the same AES material after an operator-only key-ID rename.
            argus_remote_recovery.validate_pair(
                sidecar["readback"], envelope, candidate["key"],
                key_identifier=envelope["keyId"])
            selected = candidate
            break
        except argus_remote_recovery.RecoveryBundleError:
            continue
    if selected is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_sidecar_authentication_failed")
    nonce = argus_remote_recovery._b64_decode(
        envelope.get("nonce"), "recovery_nonce_invalid")
    counter = int.from_bytes(nonce, "big")
    if len(nonce) != 12 or counter <= 0:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_sidecar_invalid")
    return _remote_recovery_nonce_domain(selected["key"]), counter


def _probe_pinned_remote_recovery_nonce_floor(
        configured, pinned_ledger, *, restore_token=None):
    """Authenticate the latest immutable pair and return carried key floors.

    This is a boot-time rollback boundary, not an optional availability probe:
    once keys are configured, every ambiguous transport/pair/ancestry result
    is terminal.  Both objects are fetched from the one ref resolution in
    ``pinned_ledger`` so a moving ledger ref cannot mix generations.
    """
    if not isinstance(pinned_ledger, dict) or set(pinned_ledger) < {
            "base", "commitSha", "owner", "repository"}:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_probe_invalid")
    readback_result = _fetch_pinned_recovery_object(
        f"{pinned_ledger['base']}{_REMOTE_READBACK_PATH}",
        _DURABLE_READBACK_MAX_BYTES, "readback")
    recovery_result = _fetch_pinned_recovery_object(
        f"{pinned_ledger['base']}{_REMOTE_RECOVERY_PATH}",
        _DURABLE_RECOVERY_MAX_BYTES, "recovery")
    if recovery_result.get("status") == "absent":
        # A sidecar-free immutable head is not sufficient evidence by itself.
        # Preserve its exact compact proof only after (a) strict receipt/WAL
        # validation and (b) an authoritative path-history absence proof for
        # this same pinned head.  Otherwise a rolled-back local keyed pair
        # could silently outrank a newer legacy ledger generation.
        if readback_result.get("status") == "absent":
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_remote_legacy_readback_missing")
        if readback_result.get("status") != "present":
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_remote_probe_ambiguous")
        readback = readback_result.get("value")
        if not isinstance(readback, dict) or not \
                argus_remote_journal.verify_strict_compact_readback_snapshot(
                    readback):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_remote_legacy_readback_invalid")
        if not _pinned_recovery_path_never_existed(pinned_ledger):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_remote_history_exists")
        return _AuthenticatedPinnedLegacyReadbackEvidence(
            pinned_ledger, readback, restore_token)
    if recovery_result.get("status") != "present":
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_probe_ambiguous")
    if readback_result.get("status") != "present":
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_pair_missing")
    sidecar_value = recovery_result.get("value")
    if not isinstance(sidecar_value, dict) or sidecar_value.get(
            "schemaVersion") != argus_remote_recovery.SIDECAR_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_sidecar_required")
    sidecar = argus_remote_recovery.validate_sidecar(sidecar_value)
    readback = readback_result.get("value")
    if sidecar["readback"] != readback:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_pair_mismatch")
    envelope = sidecar["recovery"]
    selected = _recovery_key_for_envelope(envelope, configured)
    payload = argus_remote_recovery.validate_pair(
        readback, envelope, selected["key"],
        key_identifier=selected["keyId"])
    ancestry = _verify_authenticated_ledger_commit_path(
        payload["ledgerBaseCommitSha"], pinned_ledger["commitSha"],
        owner=pinned_ledger["owner"],
        repository=pinned_ledger["repository"])
    nonce_authority = _authenticated_remote_recovery_nonce_authority(
        envelope, payload, configured, selected)
    return _AuthenticatedPinnedRemoteRecoveryEvidence(
        pinned_ledger, readback, envelope, payload, selected, ancestry,
        nonce_authority._key_material_counters)


def _validated_pinned_remote_recovery_evidence(
        evidence, pinned_ledger, configured):
    """Revalidate one private pair without resolving or fetching a moving ref."""
    if not isinstance(evidence, _AuthenticatedPinnedRemoteRecoveryEvidence) or \
            evidence._pinned_token is not \
            _PINNED_REMOTE_RECOVERY_PROCESS_TOKEN or not isinstance(
                pinned_ledger, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_invalid")
    expected = (
        pinned_ledger.get("base"), pinned_ledger.get("commitSha"),
        pinned_ledger.get("owner"), pinned_ledger.get("repository"))
    observed = (
        evidence._base, evidence._commit_sha, evidence._owner,
        evidence._repository)
    if observed != expected or not re.fullmatch(
            r"[0-9a-f]{40}", str(evidence._commit_sha or "")):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_binding_invalid")
    selected = evidence._selected
    available = [candidate for candidate in (
        configured.get("current"), configured.get("previous"))
        if isinstance(candidate, dict)] if isinstance(configured, dict) else []
    if not isinstance(selected, dict) or not any(
            candidate.get("keyId") == selected.get("keyId") and
            isinstance(candidate.get("key"), bytes) and
            isinstance(selected.get("key"), bytes) and
            hmac.compare_digest(candidate["key"], selected["key"])
            for candidate in available):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_key_unavailable")
    payload = argus_remote_recovery.validate_pair(
        evidence._readback, evidence._envelope, selected["key"],
        key_identifier=selected["keyId"])
    if payload != evidence._payload:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_changed")
    ancestry = evidence._ancestry
    if not isinstance(ancestry, dict) or ancestry.get("status") != "verified" or \
            ancestry.get("ledgerBaseCommitSha") != \
            payload["ledgerBaseCommitSha"] or ancestry.get(
                "exactCommitSha") != evidence._commit_sha or isinstance(
                    ancestry.get("distance"), bool) or not isinstance(
                        ancestry.get("distance"), int) or ancestry.get(
                            "distance") < 0:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_ancestry_invalid")
    _validated_remote_recovery_nonce_authority(evidence, seeded=False)
    return evidence


def _validated_pinned_legacy_readback_evidence(
        evidence, pinned_ledger, *, restore_token=None):
    """Revalidate one pre-sidecar compact proof at the already-pinned head."""
    if not isinstance(evidence, _AuthenticatedPinnedLegacyReadbackEvidence) or \
            evidence._token is not _PINNED_LEGACY_READBACK_PROCESS_TOKEN or \
            not isinstance(pinned_ledger, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_legacy_evidence_invalid")
    expected = (
        pinned_ledger.get("base"), pinned_ledger.get("commitSha"),
        pinned_ledger.get("owner"), pinned_ledger.get("repository"),
        pinned_ledger.get("pathPrefix"))
    observed = (
        evidence._base, evidence._commit_sha, evidence._owner,
        evidence._repository, evidence._path_prefix)
    readback = evidence._readback
    if observed != expected or (
            restore_token is not None and (
                evidence._restore_token is not restore_token or
                evidence._restore_token is None)) or not re.fullmatch(
            r"[0-9a-f]{40}", str(evidence._commit_sha or "")) or not \
            isinstance(readback, dict) or not \
            hmac.compare_digest(
                evidence._readback_hash,
                argus_persistent_storage._canonical_sha256(readback)) or not \
            argus_remote_journal.verify_strict_compact_readback_snapshot(
                readback):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_legacy_evidence_invalid")
    durability = readback.get("missionTickDurability") or {}
    target_wal = durability.get("walAppliedSequence")
    if isinstance(target_wal, bool) or not isinstance(target_wal, int) or \
            target_wal <= 0 or durability.get(
                "remoteWalAppliedSequence") != target_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_legacy_evidence_invalid")
    return evidence


def _mint_legacy_recovery_ledger_base_capability(
        checkpoint_blob, configured, pinned_ledger, legacy_evidence,
        restore_token):
    """Prove one first-activation base before any nonce is reserved."""
    if restore_token is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_restore_invalid")
    legacy = _validated_pinned_legacy_readback_evidence(
        legacy_evidence, pinned_ledger, restore_token=restore_token)
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if not isinstance(configured, dict) or configured.get(
            "status") != "configured" or not isinstance(
            current, dict) or configured.get("previous") is not None or not \
            isinstance(current.get("key"), bytes) or len(
                current["key"]) != 32:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_key_invalid")
    marker = _validated_recovery_required_marker(checkpoint_blob)
    if marker is None or marker["keyId"] != current.get("keyId") or not \
            argus_persistent_storage.verify_checkpoint(
                checkpoint_blob, require_seal=True):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_checkpoint_invalid")
    expected_base = (
        f"https://raw.githubusercontent.com/{pinned_ledger.get('owner')}/"
        f"{pinned_ledger.get('repository')}/"
        f"{pinned_ledger.get('commitSha')}"
        + (f"/{pinned_ledger.get('pathPrefix')}"
           if pinned_ledger.get("pathPrefix") else ""))
    if pinned_ledger.get("base") != expected_base:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_binding_invalid")
    durability = checkpoint_blob.get("missionTickDurability")
    local_wal = durability.get("walAppliedSequence") \
        if isinstance(durability, dict) else None
    remote_durability = legacy._readback.get("missionTickDurability") or {}
    remote_wal = remote_durability.get("walAppliedSequence")
    remote_receipt_hash = str(
        legacy._readback.get("receiptHash") or "").lower()
    if isinstance(local_wal, bool) or not isinstance(local_wal, int) or \
            local_wal <= 0 or isinstance(remote_wal, bool) or not isinstance(
                remote_wal, int) or remote_wal <= 0 or remote_wal > \
            local_wal or not re.fullmatch(
                r"[0-9a-f]{16}", remote_receipt_hash):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_authority_invalid")
    cycle = checkpoint_blob.get("remoteJournalCycle")
    remote_commit = str(
        cycle.get("remoteCommitSha") if isinstance(cycle, dict) else ""
    ).lower()
    receipt_commit = str(
        cycle.get("receiptCommitSha") if isinstance(cycle, dict) else ""
    ).lower()
    if not re.fullmatch(r"[0-9a-f]{40}", remote_commit) or \
            receipt_commit != remote_commit:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_commit_invalid")
    ancestry = _verify_authenticated_ledger_commit_path(
        remote_commit, pinned_ledger["commitSha"],
        owner=pinned_ledger["owner"],
        repository=pinned_ledger["repository"])
    if ancestry != {
            "status": "verified", "ledgerBaseCommitSha": remote_commit,
            "exactCommitSha": pinned_ledger["commitSha"],
            "distance": ancestry.get("distance")} or isinstance(
                ancestry.get("distance"), bool) or not isinstance(
                    ancestry.get("distance"), int) or ancestry.get(
                        "distance") < 0:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_ancestry_invalid")
    return _LegacyRecoveryLedgerBaseCapability(
        restore_token, legacy, pinned_ledger,
        argus_persistent_storage._canonical_sha256(checkpoint_blob),
        local_wal, remote_wal, remote_receipt_hash, remote_commit, ancestry,
        current["keyId"], _remote_recovery_nonce_domain(current["key"]))


def _consume_legacy_recovery_ledger_base_capability(
        capability, checkpoint_blob, compact_readback, configured,
        restore_token):
    """Consume one exact migration proof before durable nonce allocation."""
    if not isinstance(
            capability, _LegacyRecoveryLedgerBaseCapability) or \
            capability._token is not \
            _LEGACY_RECOVERY_LEDGER_BASE_PROCESS_TOKEN or \
            capability._consumed or restore_token is None or \
            capability._restore_token is not restore_token or not \
            hmac.compare_digest(
                capability._binding_hash,
                _legacy_recovery_ledger_base_capability_hash(capability)):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_capability_invalid")
    _validated_pinned_legacy_readback_evidence(
        capability._legacy_evidence, capability._pinned_ledger,
        restore_token=restore_token)
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if not isinstance(configured, dict) or configured.get(
            "status") != "configured" or not isinstance(
            current, dict) or configured.get("previous") is not None or \
            current.get("keyId") != capability._key_id or not isinstance(
                current.get("key"), bytes) or not hmac.compare_digest(
                    _remote_recovery_nonce_domain(current["key"]),
                    capability._key_domain):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_key_invalid")
    marker = _validated_recovery_required_marker(checkpoint_blob)
    durability = checkpoint_blob.get("missionTickDurability")
    local_wal = durability.get("walAppliedSequence") \
        if isinstance(durability, dict) else None
    ancestry = capability._ancestry
    if marker is None or marker["keyId"] != capability._key_id or not \
            argus_persistent_storage.verify_checkpoint(
                checkpoint_blob, require_seal=True) or not \
            hmac.compare_digest(
                capability._checkpoint_hash,
                argus_persistent_storage._canonical_sha256(
                    checkpoint_blob)) or local_wal != \
            capability._target_wal or capability._remote_wal > local_wal or \
            not isinstance(ancestry, dict) or ancestry.get(
                "status") != "verified" or ancestry.get(
                    "ledgerBaseCommitSha") != capability._base_commit or \
            ancestry.get("exactCommitSha") != capability._pinned_ledger.get(
                "commitSha") or isinstance(
                    ancestry.get("distance"), bool) or not isinstance(
                        ancestry.get("distance"), int) or ancestry.get(
                            "distance") < 0:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_capability_invalid")
    if not isinstance(compact_readback, dict) or not \
            argus_remote_journal.verify_strict_compact_readback_snapshot(
                compact_readback) or (compact_readback.get(
                    "missionTickDurability") or {}).get(
                        "walAppliedSequence") != local_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_compact_invalid")
    if capability._remote_wal == local_wal and not hmac.compare_digest(
            capability._remote_receipt_hash,
            str(compact_readback.get("receiptHash") or "").lower()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_legacy_receipt_mismatch")
    capability._consumed = True
    return capability._base_commit


def _pinned_recovery_path_never_existed(pinned_ledger):
    """Prove the recovery path has no commit at or before the pinned head."""
    if not isinstance(pinned_ledger, dict) or set(pinned_ledger) < {
            "commitSha", "owner", "repository", "pathPrefix"}:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_query_invalid")
    prefix = str(pinned_ledger.get("pathPrefix") or "").strip("/")
    path = "/".join(filter(None, (prefix, _REMOTE_RECOVERY_PATH.strip("/"))))
    if not path or not re.fullmatch(r"[A-Za-z0-9_./-]+", path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_query_invalid")
    response = None
    try:
        response = requests.get(
            (f"https://api.github.com/repos/{pinned_ledger['owner']}/"
             f"{pinned_ledger['repository']}/commits"),
            params={
                "sha": pinned_ledger["commitSha"], "path": path,
                "per_page": 1,
            },
            timeout=(6, 15), stream=True,
            headers={"Accept": "application/vnd.github+json"})
        if response.status_code != 200:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_query_http_error")
        value = _response_bounded_json(
            response, _LEDGER_REF_RESPONSE_MAX_BYTES,
            "recovery_nonce_history_query_unreadable")
        if not isinstance(value, list):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_history_query_invalid")
        return len(value) == 0
    except (_RemoteRecoveryRestoreError,
            argus_remote_recovery.RecoveryBundleError):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_query_ambiguous")
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_history_query_ambiguous") from exc
    finally:
        if response is not None:
            response.close()


def _authenticated_installed_recovery_nonce_floor(configured):
    """Return a private floor after authenticating the installed exact pair."""
    if not os.path.lexists(_REMOTE_RECOVERY_FILE):
        return None
    sidecar = _read_local_recovery_sidecar()
    envelope = sidecar["recovery"]
    selected = None
    for slot in ("current", "previous"):
        candidate = configured.get(slot)
        if not isinstance(candidate, dict):
            continue
        try:
            # Key IDs are operational labels.  Authenticate with the envelope
            # ID so an explicit rename of identical key material retains its
            # nonce domain without making arbitrary-key fallback possible.
            argus_remote_recovery.validate_pair(
                sidecar["readback"], envelope, candidate["key"],
                key_identifier=envelope["keyId"])
            selected = {
                "keyId": envelope["keyId"], "key": candidate["key"]}
            break
        except argus_remote_recovery.RecoveryBundleError:
            continue
    if selected is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_sidecar_authentication_failed")
    return _authenticated_remote_recovery_nonce_floor(envelope, selected)


def _remote_recovery_nonce_authority_absent(*, include_lock):
    paths = _remote_recovery_nonce_paths()
    candidates = [paths["state"], paths["history"], paths["head"]]
    if include_lock:
        lock_path = _DURABILITY_PATHS[
            "recoveryNonceState"] + ".reservation.lock"
        candidates.extend((lock_path, lock_path + ".anchor"))
    return not any(os.path.lexists(path) for path in candidates)


def _mint_remote_recovery_nonce_genesis_capability(
        checkpoint_blob, configured, pinned_ledger):
    """Mint the one activation proof only for canonical sealed legacy state."""
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if configured.get("status") != "configured" or not isinstance(
            current, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_key_invalid")
    if _validated_recovery_required_marker(checkpoint_blob) is not None or \
            os.path.lexists(_REMOTE_RECOVERY_FILE) or not \
            _remote_recovery_nonce_authority_absent(include_lock=False):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_not_clean")
    if not argus_persistent_storage.verify_checkpoint(
            checkpoint_blob, require_seal=True):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_checkpoint_unsealed")
    path = os.path.abspath(_OSINT_PERSIST_FILE)
    try:
        before = os.stat(path, follow_symlinks=False)
        if not stat.S_ISREG(before.st_mode) or os.path.islink(path):
            raise OSError("recovery_nonce_genesis_checkpoint_invalid")
        reread = argus_persistent_storage.load_checkpoint(
            path, require_seal=True)
        after = os.stat(path, follow_symlinks=False)
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_checkpoint_unreadable") from exc
    if _remote_recovery_file_identity(before) != \
            _remote_recovery_file_identity(after) or reread != \
            checkpoint_blob:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_checkpoint_changed")
    return _RemoteRecoveryNonceGenesisCapability(
        path, argus_persistent_storage._canonical_sha256(checkpoint_blob),
        _remote_recovery_file_identity(after),
        _remote_recovery_nonce_domain(current["key"]),
        str(pinned_ledger.get("commitSha") or "").lower())


def _activate_remote_recovery_nonce_genesis(capability, configured):
    """Consume a clean-ledger capability and create generation zero."""
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if not isinstance(capability, _RemoteRecoveryNonceGenesisCapability) or \
            capability._token is not _REMOTE_RECOVERY_GENESIS_PROCESS_TOKEN or \
            capability._consumed or not isinstance(current, dict) or \
            not hmac.compare_digest(
                capability._key_domain,
                _remote_recovery_nonce_domain(current.get("key"))):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_capability_invalid")
    capability._consumed = True
    lock_handle = None
    try:
        path = capability._checkpoint_path
        metadata = os.stat(path, follow_symlinks=False)
        checkpoint = argus_persistent_storage.load_checkpoint(
            path, require_seal=True)
        if _remote_recovery_file_identity(metadata) != \
                capability._checkpoint_identity or \
                argus_persistent_storage._canonical_sha256(checkpoint) != \
                capability._checkpoint_hash or \
                _validated_recovery_required_marker(checkpoint) is not None or \
                os.path.lexists(_REMOTE_RECOVERY_FILE):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_genesis_checkpoint_changed")
        nonce_path = _DURABILITY_PATHS["recoveryNonceState"]
        lock_handle = _acquire_remote_recovery_nonce_lock(nonce_path)
        locked_metadata = os.stat(path, follow_symlinks=False)
        locked_checkpoint = argus_persistent_storage.load_checkpoint(
            path, require_seal=True)
        if _remote_recovery_file_identity(locked_metadata) != \
                capability._checkpoint_identity or \
                argus_persistent_storage._canonical_sha256(
                    locked_checkpoint) != capability._checkpoint_hash or \
                _validated_recovery_required_marker(
                    locked_checkpoint) is not None or \
                os.path.lexists(_REMOTE_RECOVERY_FILE):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_genesis_checkpoint_changed")
        reused_empty_lock = not bool(
            getattr(lock_handle, "_argus_nonce_lock_created", False))
        activate = (
            os.fstat(lock_handle.fileno()).st_size == 0 and
            _remote_recovery_nonce_lock_anchor(lock_handle) is None and
            _remote_recovery_nonce_authority_absent(include_lock=False) and
            (not reused_empty_lock or configured.get("previous") is None))
        history, _head, _state = _load_remote_recovery_nonce_authority(
            lock_handle, configured, allow_activation=activate)
        return history
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_genesis_failed") from exc
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _verify_remote_recovery_nonce_authority(configured):
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(
            _DURABILITY_PATHS["recoveryNonceState"])
        return _load_remote_recovery_nonce_authority(
            lock_handle, configured, allow_activation=False)[0]
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _prepare_keyed_local_recovery_nonce_boot(
        checkpoint_blob, configured, pinned_ledger, *, evidence_handoff=None,
        restore_token=None):
    """Reconcile local authority with immutable remote truth before restore."""
    if evidence_handoff is not None and (
            not isinstance(evidence_handoff, list) or evidence_handoff):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_pinned_evidence_handoff_invalid")
    remote_evidence = _probe_pinned_remote_recovery_nonce_floor(
        configured, pinned_ledger, restore_token=restore_token)
    if remote_evidence is None and not _pinned_recovery_path_never_existed(
            pinned_ledger):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_history_exists")
    try:
        local_floor = _authenticated_installed_recovery_nonce_floor(
            configured)
    except argus_remote_recovery.RecoveryBundleError:
        # An invalid local sidecar is never a nonce floor.  A fully
        # authenticated remote floor can still recover the machine; without
        # one, do not reinterpret the local bytes as genesis.
        if remote_evidence is None:
            raise
        local_floor = None
    if local_floor is not None:
        _seed_authenticated_remote_recovery_nonce_floor(
            local_floor, configured)
    if isinstance(
            remote_evidence, _AuthenticatedRemoteRecoveryNonceAuthority):
        _seed_authenticated_remote_recovery_nonce_authority(
            remote_evidence, configured)
    elif isinstance(remote_evidence, _AuthenticatedRemoteRecoveryNonceFloor):
        # Compatibility for a process-private pre-map caller.  Immutable
        # production probes always return the full authenticated authority.
        _seed_authenticated_remote_recovery_nonce_floor(
            remote_evidence, configured)
    elif isinstance(
            remote_evidence, _AuthenticatedPinnedLegacyReadbackEvidence):
        # The compact-only legacy head has no nonce floor to import.  Keep its
        # exact immutable proof for the subsequent local-authority decision.
        _validated_pinned_legacy_readback_evidence(
            remote_evidence, pinned_ledger, restore_token=restore_token)
    elif remote_evidence is not None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_remote_probe_invalid")
    if isinstance(remote_evidence, (
            _AuthenticatedPinnedRemoteRecoveryEvidence,
            _AuthenticatedPinnedLegacyReadbackEvidence)) and \
            evidence_handoff is not None:
        evidence_handoff.append(remote_evidence)
    if local_floor is not None or isinstance(remote_evidence, (
            _AuthenticatedRemoteRecoveryNonceAuthority,
            _AuthenticatedRemoteRecoveryNonceFloor)):
        return {"status": "seeded", "pinnedCommitSha":
                pinned_ledger["commitSha"]}
    if not _remote_recovery_nonce_authority_absent(include_lock=False):
        _verify_remote_recovery_nonce_authority(configured)
        return {"status": "verified_existing", "pinnedCommitSha":
                pinned_ledger["commitSha"]}
    if _validated_recovery_required_marker(checkpoint_blob) is not None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_authority_missing")
    capability = _mint_remote_recovery_nonce_genesis_capability(
        checkpoint_blob, configured, pinned_ledger)
    _activate_remote_recovery_nonce_genesis(capability, configured)
    return {"status": "activated_genesis", "pinnedCommitSha":
            pinned_ledger["commitSha"]}


def _authenticated_remote_recovery_nonce_floor(envelope, selected):
    """Create a private floor only after the caller authenticated the pair."""
    verified = argus_remote_recovery.validate_envelope(envelope)
    if not isinstance(selected, dict) or selected.get("keyId") != \
            verified["keyId"] or not isinstance(selected.get("key"), bytes) or \
            len(selected["key"]) != 32:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_key_invalid")
    nonce = argus_remote_recovery._b64_decode(
        verified["nonce"], "recovery_nonce_invalid")
    counter = int.from_bytes(nonce, "big")
    if len(nonce) != 12 or counter <= 0 or \
            counter > _REMOTE_RECOVERY_NONCE_MAX:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_invalid")
    return _AuthenticatedRemoteRecoveryNonceFloor(
        selected["key"], counter)


def _authenticated_remote_recovery_nonce_authority(
        envelope, authenticated_payload, configured, selected):
    """Mint one private capability for the full authenticated floor map.

    The caller must pass the payload returned by ``validate_pair``.  The
    encrypted carry-forward map retains every bounded material counter.  The
    envelope itself must still have selected exactly one configured
    current/previous key ID; the map never authorizes another decrypt key.
    """
    payload = argus_remote_recovery.validate_payload(authenticated_payload)
    authority = argus_remote_recovery.validate_nonce_authority(
        payload.get("nonceAuthority"))
    available = [candidate for candidate in (
        configured.get("current"), configured.get("previous"))
        if isinstance(candidate, dict)] if isinstance(configured, dict) else []
    if not any(candidate.get("keyId") == selected.get("keyId") and
               isinstance(candidate.get("key"), bytes) and
               hmac.compare_digest(candidate["key"], selected.get("key"))
               for candidate in available):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_key_unavailable")
    counters = dict(authority["keyMaterialCounters"])
    envelope_floor = _authenticated_remote_recovery_nonce_floor(
        envelope, selected)
    envelope_domain = _remote_recovery_nonce_domain(selected["key"])
    if int(counters.get(envelope_domain) or 0) < \
            envelope_floor._remote_counter:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_authority_binding_invalid")
    return _AuthenticatedRemoteRecoveryNonceAuthority(counters)


def _validated_remote_recovery_nonce_floor(floor, configured, *, seeded):
    if not isinstance(floor, _AuthenticatedRemoteRecoveryNonceFloor) or \
            not isinstance(floor._key, bytes) or len(floor._key) != 32 or \
            isinstance(floor._remote_counter, bool) or not isinstance(
                floor._remote_counter, int) or floor._remote_counter <= 0 or \
            floor._remote_counter > _REMOTE_RECOVERY_NONCE_MAX:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_invalid")
    available = [candidate for candidate in (
        configured.get("current"), configured.get("previous"))
        if isinstance(candidate, dict) and isinstance(
            candidate.get("key"), bytes)]
    if not any(hmac.compare_digest(
            floor._key, candidate["key"]) for candidate in available):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_key_unavailable")
    if seeded:
        if isinstance(floor._seeded_counter, bool) or not isinstance(
                floor._seeded_counter, int) or \
                floor._seeded_counter < floor._remote_counter or \
                floor._seeded_counter > _REMOTE_RECOVERY_NONCE_MAX:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_bootstrap_unseeded")
        counter = floor._seeded_counter
    else:
        counter = floor._remote_counter
    return _remote_recovery_nonce_domain(floor._key), counter


def _verify_installed_remote_recovery_nonce_floor(authority, configured):
    floor = _installed_remote_recovery_nonce_floor(configured)
    if floor is None:
        return
    floor_domain, floor_counter = floor
    recorded_floor = authority["keyMaterialCounters"].get(floor_domain)
    if recorded_floor is None or recorded_floor < floor_counter:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_state_rollback")


def _seed_authenticated_remote_recovery_nonce_floor(floor, configured):
    """Durably import an authenticated cross-host floor before re-encryption."""
    domain, remote_counter = _validated_remote_recovery_nonce_floor(
        floor, configured, seeded=False)
    path = _DURABILITY_PATHS["recoveryNonceState"]
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(path)
        history, _head, _state = _load_remote_recovery_nonce_authority(
            lock_handle, configured, allow_activation=True,
            verify_installed_floor=False)
        counters = dict(history["keyMaterialCounters"])
        if domain not in counters and len(counters) >= \
                _REMOTE_RECOVERY_NONCE_MAX_DOMAINS:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_domain_capacity_exceeded")
        seeded_counter = max(int(counters.get(domain) or 0), remote_counter)
        if int(counters.get(domain) or 0) == seeded_counter:
            floor._seeded_counter = seeded_counter
            return floor
        counters[domain] = seeded_counter
        verified = _commit_remote_recovery_nonce_authority(
            lock_handle, history, counters)
        if verified["keyMaterialCounters"].get(domain) != seeded_counter:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_unverified")
        floor._seeded_counter = seeded_counter
        return floor
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except (OSError, TypeError, ValueError,
            argus_persistent_storage.PersistentStorageError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_failed") from exc
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _validated_remote_recovery_nonce_authority(authority, *, seeded):
    if not isinstance(
            authority, _AuthenticatedRemoteRecoveryNonceAuthority) or \
            authority._token is not _REMOTE_RECOVERY_AUTHORITY_PROCESS_TOKEN:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_authority_invalid")
    counters = argus_remote_recovery.validate_nonce_authority({
        "schemaVersion": argus_remote_recovery.NONCE_AUTHORITY_SCHEMA,
        "keyMaterialCounters": authority._key_material_counters,
    })["keyMaterialCounters"]
    if not counters:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_authority_invalid")
    if not seeded:
        return counters
    durable = authority._seeded_counters
    if not isinstance(durable, dict) or any(
            int(durable.get(domain) or 0) < counter
            for domain, counter in counters.items()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_unseeded")
    return counters


def _seed_authenticated_remote_recovery_nonce_authority(
        authority, configured):
    """Atomically merge every floor from one AES-authenticated latest pair."""
    remote_counters = _validated_remote_recovery_nonce_authority(
        authority, seeded=False)
    path = _DURABILITY_PATHS["recoveryNonceState"]
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(path)
        history, _head, _state = _load_remote_recovery_nonce_authority(
            lock_handle, configured, allow_activation=True,
            verify_installed_floor=False)
        counters = dict(history["keyMaterialCounters"])
        if len(set(counters) | set(remote_counters)) > \
                _REMOTE_RECOVERY_NONCE_MAX_DOMAINS:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_domain_capacity_exceeded")
        merged = dict(counters)
        for domain, counter in remote_counters.items():
            merged[domain] = max(int(merged.get(domain) or 0), counter)
        if merged == counters:
            verified = history
        else:
            verified = _commit_remote_recovery_nonce_authority(
                lock_handle, history, merged)
        if any(int(verified["keyMaterialCounters"].get(domain) or 0) <
               counter for domain, counter in remote_counters.items()):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_unverified")
        authority._seeded_counters = {
            domain: verified["keyMaterialCounters"][domain]
            for domain in remote_counters
        }
        return authority
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except (OSError, TypeError, ValueError,
            argus_persistent_storage.PersistentStorageError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_failed") from exc
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _reserve_remote_recovery_nonce(
        key_id, *, authenticated_remote_floor=None):
    """Durably reserve a nonce and snapshot its committed private authority.

    The material-derived domain survives a key-ID rename.  The lock spans the
    complete read/installed-sidecar check/modify/fsync/replace/final-readback
    transaction.  A crash may consume a counter, but cannot return a nonce
    before its reservation is durable.
    """
    identifier = argus_remote_recovery.validate_key_id(key_id)
    configured = argus_remote_recovery.configured_keys()
    current = configured.get("current") if isinstance(configured, dict) else None
    if configured.get("status") != "configured" or not isinstance(
            current, dict) or current.get("keyId") != identifier:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_current_key_required")
    key = current.get("key")
    domain = _remote_recovery_nonce_domain(key)
    if authenticated_remote_floor is None:
        supplied = []
    elif isinstance(authenticated_remote_floor, (
            _AuthenticatedRemoteRecoveryNonceFloor,
            _AuthenticatedRemoteRecoveryNonceAuthority)):
        supplied = [authenticated_remote_floor]
    elif isinstance(authenticated_remote_floor, (list, tuple)) and all(
            isinstance(item, (
                _AuthenticatedRemoteRecoveryNonceFloor,
                _AuthenticatedRemoteRecoveryNonceAuthority))
            for item in authenticated_remote_floor):
        supplied = list(authenticated_remote_floor)
    else:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_bootstrap_invalid")
    bootstraps = [
        _validated_remote_recovery_nonce_floor(
            floor, configured, seeded=True)
        for floor in supplied
        if isinstance(floor, _AuthenticatedRemoteRecoveryNonceFloor)
    ]
    authority_bootstraps = [
        _validated_remote_recovery_nonce_authority(
            authority, seeded=True)
        for authority in supplied
        if isinstance(authority, _AuthenticatedRemoteRecoveryNonceAuthority)
    ]
    path = _DURABILITY_PATHS["recoveryNonceState"]
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(path)
        history, _head, _state = _load_remote_recovery_nonce_authority(
            lock_handle, configured, allow_activation=False)
        for bootstrap in bootstraps:
            bootstrap_domain, bootstrap_counter = bootstrap
            recorded_floor = history["keyMaterialCounters"].get(
                bootstrap_domain)
            if recorded_floor is None or recorded_floor < bootstrap_counter:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_nonce_bootstrap_rollback")
        for authority_counters in authority_bootstraps:
            if any(int(history["keyMaterialCounters"].get(domain) or 0) <
                   counter for domain, counter in
                   authority_counters.items()):
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_nonce_bootstrap_rollback")

        counters = dict(history["keyMaterialCounters"])
        if domain not in counters and len(counters) >= \
                _REMOTE_RECOVERY_NONCE_MAX_DOMAINS:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_domain_capacity_exceeded")
        counter = int(counters.get(domain) or 0)
        if counter >= _REMOTE_RECOVERY_NONCE_MAX:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_exhausted")
        counter += 1
        counters[domain] = counter
        reserved = _commit_remote_recovery_nonce_authority(
            lock_handle, history, counters)
        if reserved["keyMaterialCounters"].get(domain) != counter:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_state_unverified")
        return _RemoteRecoveryNonceReservation(
            counter.to_bytes(12, "big"),
            reserved["keyMaterialCounters"])
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except (OSError, TypeError, ValueError,
            argus_persistent_storage.PersistentStorageError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_nonce_reservation_failed") from exc
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _next_remote_recovery_nonce(
        key_id, *, authenticated_remote_floor=None):
    """Return only the nonce from one durable private reservation."""
    return _reserve_remote_recovery_nonce(
        key_id,
        authenticated_remote_floor=authenticated_remote_floor)._nonce


class _RemoteRecoveryCheckpointError(RuntimeError):
    """Payload-free fail-closed classification for recovery persistence."""


_POST_GENESIS_CHECKPOINT_PROCESS_TOKEN = object()


class _PostGenesisCheckpointCapability:
    """Single-use authority for one ordinary keyed pair transaction.

    The capability never enters durable state or diagnostics.  It binds the
    installed current-key authenticated pair, the exact sealed candidate,
    configured key domains, selected ledger base, and both WAL floors before
    any durable nonce is reserved.
    """

    __slots__ = (
        "_token", "_canonical_checkpoint_path", "_canonical_identity",
        "_source_checkpoint_path", "_source_checkpoint_identity",
        "_sidecar_path", "_sidecar_identity", "_pair_identity",
        "_key_configuration", "_candidate_checkpoint_hash",
        "_candidate_checkpoint_id", "_previous_target_wal",
        "_candidate_wal", "_ledger_base", "_binding_hash", "_consumed",
    )

    def __init__(
            self, *, canonical_checkpoint_path, canonical_identity,
            source_checkpoint_path, source_checkpoint_identity,
            sidecar_path, sidecar_identity, pair_identity,
            key_configuration, candidate_checkpoint_hash,
            candidate_checkpoint_id, previous_target_wal, candidate_wal,
            ledger_base):
        self._token = _POST_GENESIS_CHECKPOINT_PROCESS_TOKEN
        self._canonical_checkpoint_path = canonical_checkpoint_path
        self._canonical_identity = copy.deepcopy(canonical_identity)
        self._source_checkpoint_path = source_checkpoint_path
        self._source_checkpoint_identity = copy.deepcopy(
            source_checkpoint_identity)
        self._sidecar_path = sidecar_path
        self._sidecar_identity = copy.deepcopy(sidecar_identity)
        self._pair_identity = copy.deepcopy(pair_identity)
        self._key_configuration = copy.deepcopy(key_configuration)
        self._candidate_checkpoint_hash = candidate_checkpoint_hash
        self._candidate_checkpoint_id = candidate_checkpoint_id
        self._previous_target_wal = previous_target_wal
        self._candidate_wal = candidate_wal
        self._ledger_base = ledger_base
        self._binding_hash = \
            _post_genesis_checkpoint_capability_hash(self)
        self._consumed = False


def _post_genesis_checkpoint_file_identity(path):
    """Return a bounded regular-file identity without exposing file bytes."""
    target = os.path.abspath(path)
    try:
        metadata = os.stat(target, follow_symlinks=False)
    except OSError as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_invalid") from exc
    if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_invalid")
    return {
        "path": target,
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "mode": stat.S_IMODE(metadata.st_mode),
        "bytes": metadata.st_size,
        "mtimeNs": metadata.st_mtime_ns,
        "ctimeNs": metadata.st_ctime_ns,
    }


def _post_genesis_checkpoint_key_configuration(configured):
    """Bind key identities to material domains without retaining key bytes."""
    if not isinstance(configured, dict) or configured.get(
            "status") != "configured":
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_key_invalid")

    def bind(slot, *, required=False):
        value = configured.get(slot)
        if value is None and not required:
            return None
        if not isinstance(value, dict) or not isinstance(
                value.get("key"), bytes) or len(value["key"]) != 32:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_checkpoint_key_invalid")
        key_id = str(value.get("keyId") or "")
        if not argus_remote_recovery.KEY_ID_RE.fullmatch(key_id):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_checkpoint_key_invalid")
        return {
            "keyId": key_id,
            "keyMaterialDomain": _remote_recovery_nonce_domain(value["key"]),
        }

    return {"current": bind("current", required=True),
            "previous": bind("previous")}


def _post_genesis_checkpoint_pair_identity(authority):
    """Project only exact non-secret identity from one authenticated pair."""
    if not isinstance(authority, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_invalid")
    checkpoint = authority.get("checkpoint")
    sidecar = authority.get("sidecar")
    payload = authority.get("payload")
    envelope = sidecar.get("recovery") if isinstance(sidecar, dict) else None
    marker = _validated_recovery_required_marker(checkpoint)
    if not isinstance(checkpoint, dict) or not isinstance(payload, dict) or \
            not isinstance(envelope, dict) or marker is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_invalid")
    checkpoint_hash = argus_persistent_storage._canonical_sha256(checkpoint)
    identity = {
        "sourceCheckpointHash": payload.get("sourceCheckpointHash"),
        "checkpointId": payload.get("checkpointId"),
        "generationId": envelope.get("generationId"),
        "bundleHash": envelope.get("bundleHash"),
        "keyId": envelope.get("keyId"),
        "ledgerBaseCommitSha": payload.get("ledgerBaseCommitSha"),
        "targetWalSequence": payload.get("targetWalSequence"),
        "compactReceiptHash": payload.get("compactReceiptHash"),
        "checkpointObjectHash": checkpoint_hash,
        "sidecarObjectHash":
            argus_persistent_storage._canonical_sha256(sidecar),
    }
    if identity["sourceCheckpointHash"] != checkpoint_hash or \
            identity["checkpointId"] != marker["checkpointId"] or \
            identity["keyId"] != marker["keyId"] or not re.fullmatch(
                r"[0-9a-f]{64}", str(identity["sourceCheckpointHash"] or "")) or \
            not re.fullmatch(
                r"rcp-[0-9a-f]{32}", str(identity["checkpointId"] or "")) or \
            not re.fullmatch(
                r"rrg-[0-9a-f]{32}", str(identity["generationId"] or "")) or \
            not re.fullmatch(
                r"[0-9a-f]{64}", str(identity["bundleHash"] or "")) or \
            not re.fullmatch(
                r"[0-9a-f]{40}", str(identity["ledgerBaseCommitSha"] or "")) or \
            isinstance(identity["targetWalSequence"], bool) or not \
            isinstance(identity["targetWalSequence"], int) or \
            identity["targetWalSequence"] <= 0:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_invalid")
    return identity


def _post_genesis_checkpoint_capability_hash(capability):
    return argus_persistent_storage._canonical_sha256({
        "canonicalCheckpointPath": capability._canonical_checkpoint_path,
        "canonicalIdentity": capability._canonical_identity,
        "sourceCheckpointPath": capability._source_checkpoint_path,
        "sourceCheckpointIdentity": capability._source_checkpoint_identity,
        "sidecarPath": capability._sidecar_path,
        "sidecarIdentity": capability._sidecar_identity,
        "pairIdentity": capability._pair_identity,
        "keyConfiguration": capability._key_configuration,
        "candidateCheckpointHash": capability._candidate_checkpoint_hash,
        "candidateCheckpointId": capability._candidate_checkpoint_id,
        "previousTargetWalSequence": capability._previous_target_wal,
        "candidateWalSequence": capability._candidate_wal,
        "ledgerBaseCommitSha": capability._ledger_base,
    })


def _post_genesis_cycle_is_exactly_unstarted(checkpoint_blob):
    cycle = checkpoint_blob.get("remoteJournalCycle") \
        if isinstance(checkpoint_blob, dict) else None
    return isinstance(cycle, dict) and \
        cycle.get("remoteDurabilityState") == "not_started" and \
        cycle.get("readBackVerified") in (False, None) and \
        cycle.get("walReadBackVerified") in (False, None) and \
        cycle.get("remoteWalAppliedSequence") in (0, None) and \
        cycle.get("verifiedWalSequence") in (0, None) and \
        all(cycle.get(key) in (None, "") for key in (
            "remoteCommitSha", "receiptCommitSha", "expectedHash",
            "actualHash", "compactReceiptHash", "errorClass",
            "walErrorClass", "receiptErrorClass"))


def _mint_post_genesis_checkpoint_capability(
        ordinary_authority, canonical_checkpoint_path, candidate_checkpoint,
        configured, candidate_wal):
    """Mint one exact current-pair proof before candidate disk staging."""
    key_configuration = _post_genesis_checkpoint_key_configuration(configured)
    current_key_id = key_configuration["current"]["keyId"]
    if not isinstance(candidate_checkpoint, dict) or not \
            argus_persistent_storage.verify_checkpoint(
                candidate_checkpoint, require_seal=True):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_candidate_invalid")
    marker = _validated_recovery_required_marker(candidate_checkpoint)
    durability = candidate_checkpoint.get("missionTickDurability")
    if marker is None or marker["keyId"] != current_key_id or not \
            isinstance(durability, dict) or isinstance(candidate_wal, bool) or \
            not isinstance(candidate_wal, int) or candidate_wal <= 0 or \
            durability.get("walAppliedSequence") != candidate_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_candidate_invalid")

    canonical_path = os.path.abspath(canonical_checkpoint_path)
    canonical = argus_persistent_storage.load_checkpoint(
        canonical_path, require_seal=True)
    resolved = _resolve_authoritative_local_recovery_checkpoint(
        canonical, canonical_path, configured)
    expected_pair = _post_genesis_checkpoint_pair_identity(
        ordinary_authority)
    resolved_pair = _post_genesis_checkpoint_pair_identity(resolved)
    if expected_pair != resolved_pair or os.path.abspath(str(
            ordinary_authority.get("path") or "")) != os.path.abspath(
                str(resolved.get("path") or "")) or \
            resolved_pair["keyId"] != current_key_id:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_changed")
    previous_target_wal = resolved_pair["targetWalSequence"]
    if candidate_wal < previous_target_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_wal_downgrade")

    try:
        ledger_base = _recovery_ledger_base(candidate_checkpoint)
        cycle = candidate_checkpoint["remoteJournalCycle"]
        if int(cycle.get("remoteWalAppliedSequence") or 0) > candidate_wal:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_checkpoint_wal_downgrade")
    except ValueError as exc:
        if str(exc) != "recovery_ledger_base_unverified" or not \
                _post_genesis_cycle_is_exactly_unstarted(
                    candidate_checkpoint):
            raise
        ledger_base = resolved_pair["ledgerBaseCommitSha"]

    source_path = os.path.abspath(resolved["path"])
    sidecar_path = os.path.abspath(_REMOTE_RECOVERY_FILE)
    return _PostGenesisCheckpointCapability(
        canonical_checkpoint_path=canonical_path,
        canonical_identity=_post_genesis_checkpoint_file_identity(
            canonical_path),
        source_checkpoint_path=source_path,
        source_checkpoint_identity=_post_genesis_checkpoint_file_identity(
            source_path),
        sidecar_path=sidecar_path,
        sidecar_identity=_post_genesis_checkpoint_file_identity(sidecar_path),
        pair_identity=resolved_pair,
        key_configuration=key_configuration,
        candidate_checkpoint_hash=
            argus_persistent_storage._canonical_sha256(candidate_checkpoint),
        candidate_checkpoint_id=marker["checkpointId"],
        previous_target_wal=previous_target_wal,
        candidate_wal=candidate_wal,
        ledger_base=ledger_base)


def _consume_post_genesis_checkpoint_capability(
        capability, checkpoint_blob, compact, configured):
    """Consume an exact ordinary-pair proof before nonce reservation."""
    if not isinstance(capability, _PostGenesisCheckpointCapability) or \
            capability._token is not \
            _POST_GENESIS_CHECKPOINT_PROCESS_TOKEN or \
            capability._consumed or not hmac.compare_digest(
                capability._binding_hash,
                _post_genesis_checkpoint_capability_hash(capability)):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_capability_invalid")
    capability._consumed = True

    if _post_genesis_checkpoint_key_configuration(configured) != \
            capability._key_configuration:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_changed")
    canonical = argus_persistent_storage.load_checkpoint(
        capability._canonical_checkpoint_path, require_seal=True)
    resolved = _resolve_authoritative_local_recovery_checkpoint(
        canonical, capability._canonical_checkpoint_path, configured)
    if _post_genesis_checkpoint_file_identity(
            capability._canonical_checkpoint_path) != \
            capability._canonical_identity or os.path.abspath(
                str(resolved.get("path") or "")) != \
            capability._source_checkpoint_path or \
            _post_genesis_checkpoint_file_identity(
                capability._source_checkpoint_path) != \
            capability._source_checkpoint_identity or \
            _post_genesis_checkpoint_file_identity(
                capability._sidecar_path) != capability._sidecar_identity or \
            _post_genesis_checkpoint_pair_identity(resolved) != \
            capability._pair_identity:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_authority_changed")

    marker = _validated_recovery_required_marker(checkpoint_blob)
    durability = checkpoint_blob.get("missionTickDurability") \
        if isinstance(checkpoint_blob, dict) else None
    if not isinstance(checkpoint_blob, dict) or not \
            argus_persistent_storage.verify_checkpoint(
                checkpoint_blob, require_seal=True) or not \
            hmac.compare_digest(
                argus_persistent_storage._canonical_sha256(checkpoint_blob),
                capability._candidate_checkpoint_hash) or marker is None or \
            marker["checkpointId"] != capability._candidate_checkpoint_id or \
            marker["keyId"] != capability._key_configuration[
                "current"]["keyId"] or not isinstance(durability, dict) or \
            durability.get("walAppliedSequence") != capability._candidate_wal or \
            capability._candidate_wal < capability._previous_target_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_candidate_changed")
    compact_durability = compact.get("missionTickDurability") \
        if isinstance(compact, dict) else None
    if not isinstance(compact, dict) or not \
            argus_remote_journal.verify_strict_compact_readback_snapshot(
                compact) or not isinstance(compact_durability, dict) or \
            compact_durability.get("walAppliedSequence") != \
            capability._candidate_wal or compact_durability.get(
                "remoteWalAppliedSequence") != capability._candidate_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_checkpoint_projection_changed")
    return capability._ledger_base


def _persist_remote_recovery_sidecar_once(
        checkpoint, *, checkpoint_path=None,
        authenticated_remote_floor=None,
        legacy_ledger_base_capability=None, restore_token=None,
        sidecar_path=None, ledger_base_capability=None,
        post_genesis_capability=None,
        transactional_boundaries=False):
    """Encrypt the exact verified checkpoint projection before WAL compaction."""
    keys = argus_remote_recovery.configured_keys()
    if keys["status"] == "not_configured":
        result = {"status": "not_configured"}
        _DURABLE_STATE["remoteRecoverySidecar"] = result
        return result
    if not isinstance(checkpoint, dict) or checkpoint.get("verified") is not True or \
            checkpoint.get("readBackVerified") is not True:
        raise ValueError("recovery_checkpoint_not_verified")
    snapshot_hash = str(checkpoint.get("snapshotHash") or "").lower()
    verified_at = str(checkpoint.get("verifiedAt") or "")
    target_wal = checkpoint.get("includedWalSequence")
    if not re.fullmatch(r"[0-9a-f]{64}", snapshot_hash) or \
            isinstance(target_wal, bool) or not isinstance(target_wal, int) or \
            target_wal <= 0:
        raise ValueError("recovery_checkpoint_proof_invalid")
    checkpoint_blob = argus_persistent_storage.load_checkpoint(
        checkpoint_path or _OSINT_PERSIST_FILE, require_seal=True)
    if argus_persistent_storage._canonical_sha256(
            checkpoint_blob) != snapshot_hash:
        raise ValueError("recovery_checkpoint_hash_mismatch")
    durable = copy.deepcopy(checkpoint_blob.get("missionTickDurability") or {})
    if durable.get("walAppliedSequence") != target_wal:
        raise ValueError("recovery_checkpoint_wal_mismatch")
    durable["remoteWalAppliedSequence"] = target_wal
    marker = _validated_recovery_required_marker(checkpoint_blob)
    if marker is None or marker["keyId"] != keys["current"]["keyId"]:
        raise ValueError("recovery_checkpoint_marker_mismatch")
    journal = argus_remote_journal.snapshot_journal_section(
        events=checkpoint_blob.get("opsJournal") or [],
        meta=checkpoint_blob.get("opsJournalMeta") or {},
        compacted=checkpoint_blob.get("opsJournalCompacted") or [],
        now_iso=verified_at)
    identity = {"appVersion": _semantic_app_version(),
                "buildSha": _backend_exact_sha()}
    compact = argus_remote_journal.build_compact_readback_snapshot(
        schema_version=argus_remote_journal.SCHEMA_V3,
        generated_at=verified_at, as_of=verified_at,
        build_identity=identity, ops_journal=journal["opsJournal"],
        integrity_manifest=journal["integrityManifest"],
        outcomes=checkpoint_blob.get("outcomes") or [],
        mission_tick_durability=durable,
        market_ledger_state_hash=checkpoint_blob.get(
            "marketLedgerStateHash"),
        chart_intelligence_state_hash=checkpoint_blob.get(
            "chartIntelligenceStateHash"),
        today_intelligence_state_hash=checkpoint_blob.get(
            "todayIntelligenceStateHash"),
        market_replay_state_hash=checkpoint_blob.get(
            "marketReplayStateHash"))
    current = keys["current"]
    if (legacy_ledger_base_capability is None) != (restore_token is None):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_capability_invalid")
    if sum(value is not None for value in (
            legacy_ledger_base_capability, ledger_base_capability,
            post_genesis_capability)) > 1:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_base_capability_ambiguous")
    if legacy_ledger_base_capability is not None:
        ledger_base_commit_sha = \
            _consume_legacy_recovery_ledger_base_capability(
                legacy_ledger_base_capability, checkpoint_blob, compact,
                keys, restore_token)
    elif ledger_base_capability is not None:
        ledger_base_commit_sha = \
            _consume_post_genesis_mismatch_repair_capability(
                ledger_base_capability, checkpoint_blob, compact, keys)
    elif post_genesis_capability is not None:
        ledger_base_commit_sha = \
            _consume_post_genesis_checkpoint_capability(
                post_genesis_capability, checkpoint_blob, compact, keys)
    else:
        ledger_base_commit_sha = _recovery_ledger_base(checkpoint_blob)
    if transactional_boundaries:
        _remote_recovery_crash_boundary("before_nonce_reservation")
    reservation = _reserve_remote_recovery_nonce(
        current["keyId"],
        authenticated_remote_floor=authenticated_remote_floor)
    if transactional_boundaries:
        _remote_recovery_crash_boundary("after_nonce_reservation")
    nonce_authority = {
        "schemaVersion": argus_remote_recovery.NONCE_AUTHORITY_SCHEMA,
        "keyMaterialCounters": reservation._key_material_counters,
    }
    payload = argus_remote_recovery.build_payload(
        compact_readback=compact,
        targets=_checkpoint_recovery_targets(checkpoint_blob, durable),
        generated_at=verified_at, build_identity=identity,
        source_checkpoint_hash=snapshot_hash,
        checkpoint_id=marker["checkpointId"],
        checkpoint_verified_at=verified_at,
        ledger_base_commit_sha=ledger_base_commit_sha,
        nonce_authority=nonce_authority)
    envelope = argus_remote_recovery.encrypt_payload(
        payload, current["key"], key_identifier=current["keyId"],
        nonce=reservation._nonce)
    sidecar = argus_remote_recovery.build_sidecar(compact, envelope)

    def _verify_exact_sidecar(value):
        try:
            verified = argus_remote_recovery.validate_sidecar(value)
            if verified != sidecar:
                return False
            argus_remote_recovery.validate_pair(
                verified["readback"], verified["recovery"], current["key"],
                key_identifier=current["keyId"])
            return True
        except argus_remote_recovery.RecoveryBundleError:
            return False

    target_sidecar = os.path.abspath(
        sidecar_path or _REMOTE_RECOVERY_FILE)
    if transactional_boundaries:
        _remote_recovery_crash_boundary("before_candidate_sidecar_write")
    write = argus_persistent_storage.atomic_write_json(
        target_sidecar, sidecar,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=_verify_exact_sidecar,
        temp_label="recovery",
        maximum_bytes=argus_remote_recovery.MAX_SIDECAR_BYTES)
    if transactional_boundaries:
        _remote_recovery_crash_boundary("after_candidate_sidecar_write")
        _remote_recovery_crash_boundary("after_candidate_sidecar_fsync")
    if write.get("readBackVerified") is not True:
        raise ValueError("recovery_sidecar_readback_unverified")
    installed = _read_local_recovery_sidecar(target_sidecar)
    if not _verify_exact_sidecar(installed):
        raise ValueError("recovery_sidecar_installed_pair_invalid")
    _remote_recovery_crash_boundary("after_encrypted_sidecar_creation")
    result = {
        "status": "verified", "generationId": envelope["generationId"],
        "keyId": envelope["keyId"],
        "ledgerBaseCommitSha": envelope["ledgerBaseCommitSha"],
        "targetWalSequence": envelope["targetWalSequence"],
        "compactReceiptHash": envelope["compactReceiptHash"],
        "bundleHash": envelope["bundleHash"],
        "readBackVerified": True,
    }
    _DURABLE_STATE["remoteRecoverySidecar"] = result
    return result


def _persist_remote_recovery_sidecar(
        checkpoint, *, checkpoint_path=None,
        authenticated_remote_floor=None,
        legacy_ledger_base_capability=None, restore_token=None,
        sidecar_path=None, ledger_base_capability=None,
        post_genesis_capability=None,
        transactional_boundaries=False):
    """Make configured recovery failures terminal for checkpoint callers."""
    _DURABLE_STATE["remoteRecoverySidecar"] = {"status": "generating"}
    try:
        return _persist_remote_recovery_sidecar_once(
            checkpoint, checkpoint_path=checkpoint_path,
            authenticated_remote_floor=authenticated_remote_floor,
            legacy_ledger_base_capability=legacy_ledger_base_capability,
            restore_token=restore_token, sidecar_path=sidecar_path,
            ledger_base_capability=ledger_base_capability,
            post_genesis_capability=post_genesis_capability,
            transactional_boundaries=transactional_boundaries)
    except Exception as exc:
        _DURABLE_STATE["remoteRecoverySidecar"] = {
            "status": "failed", "errorClass": type(exc).__name__}
        raise _RemoteRecoveryCheckpointError(
            "remote_recovery_sidecar_failed") from exc


def _acquire_recovery_checkpoint_transaction_lock(path):
    """Hold the canonical checkpoint writer inode across a staged pair swap."""
    lock_path = os.path.abspath(path) + ".writer.lock"
    descriptor = None
    handle = None
    try:
        descriptor = os.open(
            lock_path,
            os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
        handle = os.fdopen(descriptor, "a+b")
        descriptor = None
        metadata = os.fstat(handle.fileno())
        if not stat.S_ISREG(metadata.st_mode) or \
                stat.S_IMODE(metadata.st_mode) & 0o077:
            raise argus_persistent_storage.PersistentStorageError(
                "checkpoint_writer_lock_invalid")
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        installed = os.stat(lock_path, follow_symlinks=False)
        if (metadata.st_dev, metadata.st_ino) != \
                (installed.st_dev, installed.st_ino):
            raise argus_persistent_storage.PersistentStorageError(
                "checkpoint_writer_lock_changed")
        return handle
    except BlockingIOError as exc:
        if handle is not None:
            handle.close()
            handle = None
        raise argus_persistent_storage.PersistentStorageError(
            "checkpoint_writer_busy") from exc
    except Exception:
        if handle is not None:
            handle.close()
        elif descriptor is not None:
            os.close(descriptor)
        raise


def _release_recovery_checkpoint_transaction_lock(handle):
    if handle is None:
        return
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    except OSError:
        pass
    handle.close()


def _checkpoint_wal_result(
        checkpoint, *, wal_path, included_sequence, allow_wal_compaction,
        compaction_sequence, job_id, build_sha, mission_window_id):
    """Compact only after the canonical checkpoint/sidecar pair is complete."""
    if not wal_path:
        return None
    if allow_wal_compaction:
        covered_sequence = min(
            int(included_sequence),
            int(compaction_sequence if compaction_sequence is not None
                else included_sequence))
        return argus_tick_durability.compact_verified_wal(
            wal_path, included_sequence=covered_sequence,
            receipt={
                "jobId": job_id,
                "verifiedAt": checkpoint["verifiedAt"],
                "snapshotHash": checkpoint["snapshotHash"],
                "includedWalSequence": covered_sequence,
                "buildSha": build_sha,
                "missionWindowId": mission_window_id,
            })
    wal_state = argus_tick_durability.read_valid_wal(wal_path)
    return {
        "deferred": True,
        "reason": "remote_receipt_not_verified",
        "compactedThrough": 0,
        "remainingRecords": len(wal_state["records"]),
        "receiptSequence": int(included_sequence),
        "bytes": wal_state["bytes"],
    }


def _verified_checkpoint_preserving_legacy_until_pair(
        path, blob, *, job_id, wal_path, included_sequence,
        allow_wal_compaction, compaction_sequence, build_sha,
        mission_window_id):
    """Commit keyed checkpoint/sidecar pairs through one sidecar switch.

    A legacy or absent canonical checkpoint retains its activation staging.
    After genesis, the previous authenticated pair stays authoritative until
    a complete hash-named checkpoint generation and candidate sidecar have
    both survived durable readback and exact pair verification.
    """
    configured = argus_remote_recovery.configured_keys()
    if configured.get("status") != "configured":
        return argus_tick_durability.verified_checkpoint(
            path, blob, job_id=job_id, wal_path=wal_path,
            included_sequence=included_sequence,
            allow_wal_compaction=allow_wal_compaction,
            compaction_sequence=compaction_sequence, build_sha=build_sha,
            post_verify=_persist_remote_recovery_sidecar,
            mission_window_id=mission_window_id)

    transaction_lock = None
    staged_checkpoint = None
    staged_lock = None
    staged_sidecar = None
    staged_sidecar_lock = None
    authority_switched = False
    use_staging = False
    ordinary_authority = None
    post_genesis_capability = None
    transaction_lock = _acquire_recovery_checkpoint_transaction_lock(path)
    try:
        try:
            canonical = argus_persistent_storage.load_checkpoint(
                path, require_seal=True)
        except FileNotFoundError:
            canonical = None
        if canonical is None or \
                _validated_recovery_required_marker(canonical) is None:
            use_staging = True
        else:
            # The authenticated sidecar, not the compatibility checkpoint
            # path, selects the committed generation after genesis.
            ordinary_authority = \
                _resolve_authoritative_local_recovery_checkpoint(
                    canonical, path, configured)
            post_genesis_capability = \
                _mint_post_genesis_checkpoint_capability(
                    ordinary_authority, path, blob, configured,
                    included_sequence)
    except Exception:
        _release_recovery_checkpoint_transaction_lock(transaction_lock)
        raise

    if not use_staging:
        try:
            _remote_recovery_crash_boundary(
                "before_candidate_checkpoint_staging")
            staged_checkpoint = os.path.join(
                _DURABILITY_PATHS["tempDirectory"],
                (f"{os.path.basename(path)}.{os.getpid()}."
                 f"{os.urandom(16).hex()}.recovery-pair-checkpoint"))
            staged_lock = staged_checkpoint + ".writer.lock"
            checkpoint = argus_tick_durability.verified_checkpoint(
                staged_checkpoint, blob, job_id=job_id,
                included_sequence=included_sequence,
                allow_wal_compaction=False, build_sha=build_sha,
                mission_window_id=mission_window_id)
            _remote_recovery_crash_boundary("after_checkpoint_staging")
            staged_sidecar = os.path.join(
                _DURABILITY_PATHS["tempDirectory"],
                (f"{os.path.basename(_REMOTE_RECOVERY_FILE)}.{os.getpid()}."
                 f"{os.urandom(16).hex()}.candidate"))
            staged_sidecar_lock = staged_sidecar + ".writer.lock"
            checkpoint["postVerify"] = _persist_remote_recovery_sidecar(
                checkpoint, checkpoint_path=staged_checkpoint,
                sidecar_path=staged_sidecar,
                post_genesis_capability=post_genesis_capability,
                transactional_boundaries=True)
            _DURABLE_STATE["remoteRecoverySidecar"] = {
                **checkpoint["postVerify"], "status": "candidate_verified"}
            candidate_sidecar = _read_local_recovery_sidecar(staged_sidecar)
            staged = argus_persistent_storage.load_checkpoint(
                staged_checkpoint, require_seal=True)
            _verify_local_recovery_sidecar(
                staged, allow_legacy_migration=False,
                sidecar_value=candidate_sidecar)
            _remote_recovery_crash_boundary(
                "after_candidate_pair_verification")

            prior_hash = ordinary_authority["payload"][
                "sourceCheckpointHash"]
            candidate_hash = checkpoint["snapshotHash"]
            _install_recovery_checkpoint_generation(
                ordinary_authority["path"], path, prior_hash)
            _install_recovery_checkpoint_generation(
                staged_checkpoint, path, candidate_hash)
            _remote_recovery_crash_boundary(
                "before_pair_authority_switch")
            os.replace(staged_sidecar, _REMOTE_RECOVERY_FILE)
            staged_sidecar = None
            authority_switched = True
            argus_persistent_storage._fsync_directory(
                os.path.dirname(os.path.abspath(_REMOTE_RECOVERY_FILE)))
            _remote_recovery_crash_boundary("after_pair_authority_switch")

            # This path is a compatibility projection only.  Once the
            # sidecar switch above is durable, restart resolves the immutable
            # candidate generation even if this projection did not complete.
            os.replace(staged_checkpoint, path)
            staged_checkpoint = None
            argus_persistent_storage._fsync_directory(
                os.path.dirname(os.path.abspath(path)))
            installed = argus_persistent_storage.load_checkpoint(
                path, require_seal=True)
            resolved = _resolve_authoritative_local_recovery_checkpoint(
                installed, path, configured)
            if resolved["payload"]["sourceCheckpointHash"] != candidate_hash:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_pair_authority_switch_unverified")
            _DURABLE_STATE["remoteRecoverySidecar"] = {
                **checkpoint["postVerify"], "status": "verified"}
            checkpoint["path"] = os.path.abspath(path)
            _remote_recovery_crash_boundary("before_pair_cleanup")
            _cleanup_recovery_checkpoint_generations(
                path, (prior_hash, candidate_hash))
            checkpoint["walCompaction"] = _checkpoint_wal_result(
                checkpoint, wal_path=wal_path,
                included_sequence=included_sequence,
                allow_wal_compaction=allow_wal_compaction,
                compaction_sequence=compaction_sequence, job_id=job_id,
                build_sha=build_sha,
                mission_window_id=mission_window_id)
            return checkpoint
        finally:
            if not authority_switched and _DURABLE_STATE.get(
                    "remoteRecoverySidecar", {}).get("status") == \
                    "candidate_verified":
                _DURABLE_STATE["remoteRecoverySidecar"] = {
                    "status": "candidate_failed_preserved_previous",
                    "errorClass": "candidate_not_committed",
                }
            for candidate in (
                    staged_sidecar, staged_sidecar_lock,
                    staged_checkpoint, staged_lock):
                if candidate:
                    try:
                        os.unlink(candidate)
                    except FileNotFoundError:
                        pass
                    except OSError:
                        pass
            _release_recovery_checkpoint_transaction_lock(transaction_lock)
            transaction_lock = None

    try:
        staged_checkpoint = os.path.join(
            _DURABILITY_PATHS["tempDirectory"],
            (f"{os.path.basename(path)}.{os.getpid()}."
             f"{os.urandom(16).hex()}.recovery-pair-checkpoint"))
        staged_lock = staged_checkpoint + ".writer.lock"
        checkpoint = argus_tick_durability.verified_checkpoint(
            staged_checkpoint, blob, job_id=job_id,
            included_sequence=included_sequence,
            allow_wal_compaction=False, build_sha=build_sha,
            mission_window_id=mission_window_id)
        _remote_recovery_crash_boundary(
            "after_marker_candidate_checkpoint")
        checkpoint["postVerify"] = _persist_remote_recovery_sidecar(
            checkpoint, checkpoint_path=staged_checkpoint)
        staged = argus_persistent_storage.load_checkpoint(
            staged_checkpoint, require_seal=True)
        _verify_local_recovery_sidecar(
            staged, allow_legacy_migration=False)
        os.replace(staged_checkpoint, path)
        staged_checkpoint = None
        argus_persistent_storage._fsync_directory(
            os.path.dirname(os.path.abspath(path)))
        installed = argus_persistent_storage.load_checkpoint(
            path, require_seal=True)
        _verify_local_recovery_sidecar(
            installed, allow_legacy_migration=False)
        checkpoint["path"] = os.path.abspath(path)
        _remote_recovery_crash_boundary("after_complete_pair")
        checkpoint["walCompaction"] = _checkpoint_wal_result(
            checkpoint, wal_path=wal_path,
            included_sequence=included_sequence,
            allow_wal_compaction=allow_wal_compaction,
            compaction_sequence=compaction_sequence, job_id=job_id,
            build_sha=build_sha, mission_window_id=mission_window_id)
        return checkpoint
    finally:
        for candidate in (staged_checkpoint, staged_lock):
            if candidate:
                try:
                    os.unlink(candidate)
                except FileNotFoundError:
                    pass
                except OSError:
                    pass
        _release_recovery_checkpoint_transaction_lock(transaction_lock)


def _osint_persist():
    _recovery_phase_a_abandon_checkpoint()
    token = _memory_operation_begin(
        "internal", "checkpoint_persist", known=True)
    try:
        with _DURABLE_CHECKPOINT_LOCK:
            _memory_attribution_path_capture(
                "M21", "checkpoint_lock_acquired")
            result = _osint_persist_locked()
    except Exception as exc:
        _recovery_phase_a_abandon_checkpoint()
        _memory_operation_complete(
            token, {"result": "error", "errorClass": type(exc).__name__})
        raise
    _memory_operation_complete(
        token, {"result": "verified" if result.get("verified") else "error",
                "errorClass": result.get("errorClass")})
    # Mission ticks hold an outer recursive authority lock. Their scalar
    # handoff is finalized only after that outer level releases.
    if not _mission_tick_context_active():
        _recovery_phase_a_finalize_checkpoint(result)
    return result


def _osint_persist_locked():
    attempt_at = _ai_now_iso()
    stage = "source_snapshot_construction"
    _DURABLE_STATE["lastAttemptAt"] = attempt_at
    _DURABLE_STATE["writeCount"] = int(
        _DURABLE_STATE.get("writeCount") or 0) + 1
    try:
        pre_wal_sample = _memory_attribution_scalar_snapshot()
        _memory_attribution_path_capture(
            "M22", "final_wal_read_start", sample=pre_wal_sample)
        _memory_attribution_source_capture(
            "S0", "checkpoint_source_entry", {
                "wholeStateRepresentations": 0,
                "outerWalRepresentationAlive": True,
            }, sample=pre_wal_sample)
        wal_state = argus_tick_durability.read_valid_wal(_MISSION_WAL_FILE)
        included_wal_sequence = int(wal_state.get("maximumSequence") or 0)
        _MISSION_BATCH_STATE["walAppliedSequence"] = included_wal_sequence
        post_wal_sample = _memory_attribution_scalar_snapshot()
        _memory_attribution_source_capture("S1", "wal_cursor_read", {
            "walRecordCount": len(wal_state.get("records") or []),
            "walBytes": wal_state.get("bytes"),
            "includedWalSequence": included_wal_sequence,
            "wholeStateRepresentations": 0,
        }, sample=post_wal_sample)
        _memory_attribution_path_capture(
            "M23", "final_wal_read_complete", {
                "walRecordCount": len(wal_state.get("records") or []),
                "walBytes": wal_state.get("bytes"),
            }, sample=post_wal_sample)

        recovery_keys = argus_remote_recovery.configured_keys()
        if recovery_keys.get("status") == "configured":
            # Convert the unbounded historical per-aggregate map into the
            # complete bounded allocator state before this keyed checkpoint is
            # sealed.  The high-water scalar prevents sequence/idempotency
            # reuse if an evicted aggregate identifier later reappears.
            _bound_ops_sequence_allocator_state()

        # S2 preserves the exact pre-diagnostic reference/slice/copy semantics.
        # List slices and shallow dictionaries coexist with their authoritative
        # stores; only the canary/Soak controls are deliberately deep-copied.
        blob = {
            "termOverlay": _OSINT_TERM_OVERLAY,
            "memory": _OSINT_MEMORY[-_OSINT_MEMORY_MAX:],
            "urlCache": dict(list(
                _OSINT_URL_CACHE.items())[-_OSINT_URL_CACHE_MAX:]),
            # caos-scan runs the backup tick and canary job in parallel.
            # Freeze only this small, proven concurrent section.
            "canaryLast": copy.deepcopy(_OSINT_CANARY_LAST),
            "rpsHistory": _OSINT_RPS_HISTORY[-40:],
            "baselineRuns": _OSINT_BASELINE_RUNS[-24:],
            "benchmarkRuns": _OSINT_BENCHMARK_RUNS[-20:],
            "schemaVersion": _DURABLE_STATE["schemaVersion"],
            "checkpointFailureHistory":
                _checkpoint_failure_history_projection(),
            "soak": copy.deepcopy(_SOAK),
            "soakHistory": copy.deepcopy(_SOAK_HISTORY[-8:]),
            "soakControl": dict(_SOAK_CONTROL),
            "checkpointV2Stage1Control": copy.deepcopy(
                _CHECKPOINT_V2_STAGE1_CONTROL),
            "missions": _MISSIONS[-300:],
            "missionWindows": _MISSION_WINDOWS[-240:],
            "forecasts": _FORECAST_LEDGER[-200:],
            "outcomes": _OUTCOME_LEDGER[-200:],
            "incidents": _INCIDENTS[-20:],
            "opsJournal": _OPS_JOURNAL[-400:],
            "opsJournalMeta": dict(_OPS_JOURNAL_META),
            "opsJournalCompacted": _OPS_JOURNAL_COMPACT[-40:],
            "opsSequenceByAggregate": dict(_OPS_SEQ),
            "postmortems": copy.deepcopy(_POSTMORTEMS[-30:]),
            "periodicReports": copy.deepcopy(_PERIODIC_REPORTS[-12:]),
            "challengerRuns": copy.deepcopy(_CHALLENGER_RUNS[-8:]),
            "agentQueue": copy.deepcopy(_OSINT_AGENT_QUEUE),
            "remoteAck": dict(_REMOTE_ACK),
            "remoteJournalCycle": dict(_REMOTE_CYCLE),
        }
        if recovery_keys.get("status") == "configured":
            # This marker is sealed into the checkpoint before it can become
            # authoritative.  It contains no key material; it prevents a
            # keyed checkpoint from being reclassified as legacy if the
            # encrypted sidecar or key configuration is later removed.
            blob["remoteRecoveryRequired"] = {
                "schemaVersion": argus_remote_recovery.SIDECAR_SCHEMA,
                "mode": "encrypted_required",
                "keyId": recovery_keys["current"]["keyId"],
                "checkpointId": f"rcp-{os.urandom(16).hex()}",
            }
        _memory_attribution_source_capture("S2", "reference_sections_assembled", {
            "topLevelKeys": len(blob),
            "directReferenceSectionCount": 1,
            "shallowSliceSectionCount": 11,
            "shallowDictionaryCopySectionCount": 5,
            "deepCopySectionCount": 4,
            "newProjectionOrScalarSectionCount": 2,
            "wholeStateRepresentations": 1,
        })

        blob.update({
            "formalResearchBenchmark": _memory_operation_run(
                "internal", "source.formal_benchmark.normalize",
                argus_research_benchmark.normalize_state, _FORMAL_BENCHMARK),
            "formalResearchBenchmarkV2": _memory_operation_run(
                "internal", "source.formal_benchmark_v2.normalize",
                argus_research_benchmark_v2.normalize_state,
                _FORMAL_BENCHMARK_V2),
            "foundationJobs": _memory_operation_run(
                "internal", "source.foundation_jobs.normalize",
                argus_foundation_jobs.normalize_state, _FOUNDATION_JOBS),
            "costPolicy": _memory_operation_run(
                "internal", "source.cost_policy.normalize",
                argus_cost_policy.normalize_state, _COST_POLICY),
        })
        _memory_attribution_source_capture("S3", "control_states_normalized", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 4,
            "wholeStateRepresentations": 5,
        })

        blob["marketLedger"] = _memory_operation_run(
            "internal", "source.market_ledger.normalize",
            argus_market_ledger.normalize_state, _MARKET_LEDGER)
        blob["marketLedgerStateHash"] = _memory_operation_run(
            "internal", "source.market_ledger.hash_with_transient_normalize",
            argus_market_ledger.state_hash, _MARKET_LEDGER)
        _memory_attribution_source_capture("S4", "market_ledger_normalize_hash", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 5,
            "transientHashNormalizationCount": 1,
            "peakSimultaneousRepresentations": 3,
        })

        blob["chartIntelligence"] = _memory_operation_run(
            "internal", "source.chart_intelligence.normalize",
            argus_chart_intelligence.normalize_state, _CHART_INTELLIGENCE)
        blob["chartIntelligenceStateHash"] = _memory_operation_run(
            "internal", "source.chart_intelligence.hash_with_transient_normalize",
            argus_chart_intelligence.state_hash, _CHART_INTELLIGENCE)
        _memory_attribution_source_capture("S5", "chart_state_normalize_hash", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 6,
            "transientHashNormalizationCount": 1,
            "peakSimultaneousRepresentations": 3,
        })

        blob["todayIntelligence"] = _memory_operation_run(
            "internal", "source.today_intelligence.normalize",
            argus_today_intelligence.normalize_state, _TODAY_INTELLIGENCE)
        blob["todayIntelligenceStateHash"] = _memory_operation_run(
            "internal", "source.today_intelligence.hash_with_transient_normalize",
            argus_today_intelligence.state_hash, _TODAY_INTELLIGENCE)
        blob["marketReplay"] = _memory_operation_run(
            "internal", "source.market_replay.normalize",
            argus_market_replay.normalize_state, _MARKET_REPLAY)
        blob["marketReplayStateHash"] = _memory_operation_run(
            "internal", "source.market_replay.hash_with_transient_normalize",
            argus_market_replay.state_hash, _MARKET_REPLAY)
        _memory_attribution_source_capture("S6", "decision_states_normalize_hash", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 8,
            "transientHashNormalizationCount": 2,
            "peakSimultaneousRepresentations": 3,
        })

        _memory_attribution_source_capture(
            "S7V0", "verified_snapshots_normalize_start", {
                "authoritativeAlive": True,
                "blobNormalizedAlive": False,
            })

        def _verified_normalize_complete(normalized):
            _memory_attribution_source_capture(
                "S7V1", "verified_snapshots_normalize_complete", {
                    "authoritativeAlive": True,
                    "blobNormalizedAlive": False,
                    "normalizedResultAlive": True,
                    "blobAssignmentPending": True,
                    "currentCount": len(normalized.get("current") or {}),
                    "historyCount": len(normalized.get("history") or []),
                })

        _verified_normalized = _memory_operation_run(
            "internal", "source.verified_snapshots.normalize",
            argus_verified_snapshot.normalize_store, _VERIFIED_VIEW_SNAPSHOTS,
            _attribution_after_callback=_verified_normalize_complete)
        blob["verifiedViewSnapshots"] = _verified_normalized
        _verified_normalized_hash_counts = {
            "normalizedHashFastPathCount": 0,
            "normalizedHashFallbackCount": 0,
        }

        def _verified_hash_complete(_state_hash):
            _fallback_count = _verified_normalized_hash_counts[
                "normalizedHashFallbackCount"]
            _memory_attribution_source_capture(
                "S7V7", "verified_snapshots_hash_returned", {
                    "authoritativeAlive": True,
                    "blobNormalizedAlive": True,
                    "hashTemporariesReleased": True,
                    "peakWholeStateRepresentations": (
                        4 if _fallback_count else 3),
                    **_verified_normalized_hash_counts,
                })

        blob["verifiedViewSnapshotsStateHash"] = _memory_operation_run(
            "internal", "source.verified_snapshots.hash_normalized",
            argus_verified_snapshot.state_hash_normalized,
            _verified_normalized,
            diagnostic_observer=_memory_state_hash_observer(
                "verified", _verified_normalized_hash_counts),
            _attribution_after_callback=_verified_hash_complete)
        _memory_attribution_source_capture(
            "S7A0", "asset_chart_reports_normalize_start", {
                "authoritativeAlive": True,
                "blobNormalizedAlive": False,
            })

        def _asset_normalize_complete(normalized):
            _memory_attribution_source_capture(
                "S7A1", "asset_chart_reports_normalize_complete", {
                    "authoritativeAlive": True,
                    "blobNormalizedAlive": False,
                    "normalizedResultAlive": True,
                    "blobAssignmentPending": True,
                    "recordCount": len(normalized.get("records") or {}),
                    "currentCount": len(normalized.get("current") or {}),
                })

        _asset_normalized = _memory_operation_run(
            "internal", "source.asset_chart_reports.normalize",
            argus_asset_chart_cache.normalize_store, _ASSET_CHART_REPORTS,
            _attribution_after_callback=_asset_normalize_complete)
        blob["assetChartReports"] = _asset_normalized
        _asset_normalized_hash_counts = {
            "normalizedHashFastPathCount": 0,
            "normalizedHashFallbackCount": 0,
        }

        def _asset_hash_complete(_state_hash):
            _fallback_count = _asset_normalized_hash_counts[
                "normalizedHashFallbackCount"]
            _memory_attribution_source_capture(
                "S7A7", "asset_chart_reports_hash_returned", {
                    "authoritativeAlive": True,
                    "blobNormalizedAlive": True,
                    "hashTemporariesReleased": True,
                    "peakWholeStateRepresentations": (
                        3 if _fallback_count else 2),
                    **_asset_normalized_hash_counts,
                })

        blob["assetChartReportsStateHash"] = _memory_operation_run(
            "internal", "source.asset_chart_reports.hash_normalized",
            argus_asset_chart_cache.state_hash_normalized,
            _asset_normalized,
            diagnostic_observer=_memory_state_hash_observer(
                "asset", _asset_normalized_hash_counts),
            _attribution_after_callback=_asset_hash_complete)
        _normalized_hash_fast_path_count = (
            _verified_normalized_hash_counts["normalizedHashFastPathCount"]
            + _asset_normalized_hash_counts["normalizedHashFastPathCount"])
        _normalized_hash_fallback_count = (
            _verified_normalized_hash_counts["normalizedHashFallbackCount"]
            + _asset_normalized_hash_counts["normalizedHashFallbackCount"])
        _verified_peak_representations = (
            4 if _verified_normalized_hash_counts[
                "normalizedHashFallbackCount"] else 3)
        _asset_peak_representations = (
            3 if _asset_normalized_hash_counts[
                "normalizedHashFallbackCount"] else 2)
        _memory_attribution_source_capture("S7", "public_stores_normalize_hash", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 10,
            "transientHashNormalizationCount": _normalized_hash_fallback_count,
            "normalizedHashFastPathCount": _normalized_hash_fast_path_count,
            "normalizedHashFallbackCount": _normalized_hash_fallback_count,
            "peakWholeStateRepresentations": max(
                _verified_peak_representations,
                _asset_peak_representations),
            "verifiedPeakWholeStateRepresentations": (
                _verified_peak_representations),
            "assetPeakWholeStateRepresentations": _asset_peak_representations,
            "canonicalStringMaterializations": 2,
            "utf8ByteMaterializations": 2,
            "verifiedSnapshotCurrentCount": len(
                _VERIFIED_VIEW_SNAPSHOTS.get("current") or {}),
            "verifiedSnapshotHistoryCount": len(
                _VERIFIED_VIEW_SNAPSHOTS.get("history") or []),
            "assetChartRecordCount": len(
                _ASSET_CHART_REPORTS.get("records") or {}),
        })

        blob["missionTickDurability"] = _mission_tick_durability_snapshot()
        blob["soakLastPersistAt"] = _ai_now_iso()
        _memory_attribution_source_capture("S8", "persistent_source_ready", {
            "topLevelKeys": len(blob),
            "retainedNormalizedStateCount": 10,
            "transientHashNormalizationCount": (
                4 + _normalized_hash_fallback_count),
            "normalizedHashFastPathCount": _normalized_hash_fast_path_count,
            "normalizedHashFallbackCount": _normalized_hash_fallback_count,
            "wholeStateRepresentations": 11,
        })
        _memory_attribution_capture(
            "T1", {"sourceStateConstructed": True,
                   "sourceTopLevelKeys": len(blob)})
        job_id = str(_MISSION_TICK_CONTEXT.get("jobId") or
                     f"checkpoint-{os.getpid()}")
        stage = "source_snapshot_seal"
        record_id = _memory_attribution_record_id()
        if record_id:
            _MEMORY_ATTRIBUTION.update_metadata(
                record_id, {"legacyCheckpointAttempted": True})
        _memory_attribution_capture("T2")
        seal_started_ns = time.monotonic_ns()
        sealed_blob = argus_persistent_storage.seal_checkpoint(blob)
        _recovery_phase_a_prepare_checkpoint(
            sealed_blob,
            seal_duration_micros=_recovery_phase_a_elapsed_micros(
                seal_started_ns),
            wal_bytes=wal_state.get("bytes"),
            wal_records=len(wal_state.get("records") or []),
            wal_high_water=included_wal_sequence)
        verified_wal_sequence = _verified_persistent_wal_sequence()
        allow_wal_compaction = bool(
            _REMOTE_CYCLE.get("readBackVerified") is True and
            verified_wal_sequence > 0)
        stage = "source_integrity_and_atomic_write"
        checkpoint = _verified_checkpoint_preserving_legacy_until_pair(
            _OSINT_PERSIST_FILE, sealed_blob, job_id=job_id,
            wal_path=_MISSION_WAL_FILE,
            included_sequence=included_wal_sequence,
            # Compact only through the WAL cursor explicitly read back from a
            # matching Remote Journal receipt. Newer local records remain.
            allow_wal_compaction=allow_wal_compaction,
            compaction_sequence=verified_wal_sequence,
            build_sha=os.environ.get("RENDER_GIT_COMMIT") or _backend_sha(),
            mission_window_id=(
                _MISSION_TICK_CONTEXT.get("missionWindowId")))
        _memory_attribution_capture(
            "T3", {"legacyCheckpointVerified": bool(
                checkpoint.get("verified"))})
        _memory_attribution_capture(
            "T4", {"legacyReadBackVerified": bool(
                checkpoint.get("verified"))})
        # The sealed top-level mapping owns checkpoint-normalized archive
        # copies after the authoritative legacy write.  Drop the redundant
        # unsealed owner before the V2 writer consumes each section so large
        # transient arenas can be returned at the true lifecycle boundary.
        del blob
        stage = "durability_metadata"
        metadata = _persist_durability_metadata()
        checkpoint["metadata"] = metadata
        # Stage 1 is deliberately non-authoritative. The already-verified
        # legacy checkpoint remains the sole restore source and WAL semantics
        # are unchanged. A V2 write failure is surfaced, never promoted into a
        # false legacy failure or an automatic restore cutover.
        # The V2 child independently reloads this verified file.  Release the
        # parent's final generation-sized legacy reference before spawning it;
        # no checkpoint payload crosses the process boundary.
        del sealed_blob
        stage = "checkpoint_v2_disabled_adapter"
        _memory_attribution_capture("T5", {
            "stage1EffectiveState": (
                "enabled" if _CHECKPOINT_V2_STAGE1_ENABLED else "disabled")})
        checkpoint["checkpointV2"] = _checkpoint_v2_dual_write(checkpoint)
        _DURABLE_STATE["lastWriteAt"] = _ai_now_iso()
        _DURABLE_STATE["lastKnownGoodAt"] = _DURABLE_STATE["lastWriteAt"]
        _DURABLE_STATE["lastSuccessAt"] = _DURABLE_STATE["lastWriteAt"]
        _DURABLE_STATE["successCount"] = int(
            _DURABLE_STATE.get("successCount") or 0) + 1
        _DURABLE_STATE["consecutiveFailureCount"] = 0
        _DURABLE_STATE["integrityStatus"] = "ok"
        _DURABLE_STATE["lastCheckpointError"] = None
        _DURABLE_STATE["lastCheckpoint"] = checkpoint
        _DURABLE_STORAGE_STATUS["lastCheckpointVerification"] = \
            checkpoint.get("verifiedAt")
        _DURABLE_STORAGE_STATUS["checkpointBytes"] = checkpoint.get(
            "snapshotBytes")
        _DURABLE_STORAGE_STATUS["walBytes"] = (
            checkpoint.get("walCompaction") or {}).get("bytes")
        if _mission_tick_context_active():
            _MISSION_TICK_CONTEXT["checkpoint"] = checkpoint
            _MISSION_TICK_CONTEXT["walSequence"] = int(
                (checkpoint.get("walCompaction") or {}).get(
                    "receiptSequence") or included_wal_sequence)
        migration = _DURABLE_STATE.get("legacyCheckpointMigration")
        if isinstance(migration, dict) and \
                migration.get("status") == "verified":
            migration.update({
                "status": "converted_to_embedded_seal",
                "requiresSealedRewrite": False,
                "convertedAt": _DURABLE_STATE["lastWriteAt"],
            })
        return checkpoint
    except Exception as exc:
        failure_at = _ai_now_iso()
        safe_message = _checkpoint_failure_safe_message(
            type(exc).__name__, str(exc))
        _DURABLE_STATE["integrityStatus"] = "write_failed"
        _DURABLE_STATE["lastCheckpointError"] = type(exc).__name__
        _DURABLE_STATE["lastFailureAt"] = failure_at
        _DURABLE_STATE["lastFailureClass"] = type(exc).__name__
        _DURABLE_STATE["lastFailureMessage"] = safe_message
        _DURABLE_STATE["lastFailureStage"] = stage
        _DURABLE_STATE["failureCount"] = int(
            _DURABLE_STATE.get("failureCount") or 0) + 1
        _DURABLE_STATE["consecutiveFailureCount"] = int(
            _DURABLE_STATE.get("consecutiveFailureCount") or 0) + 1
        add_log(
            "[legacy-checkpoint] write failed "
            f"stage={stage} errorClass={type(exc).__name__} "
            f"error={safe_message}")
        if isinstance(exc, _RemoteRecoveryCheckpointError):
            raise
        return {"verified": False, "errorClass": type(exc).__name__}


def _checkpoint_v2_dual_write(legacy_checkpoint):
    global _CHECKPOINT_V2_STATUS, _CHECKPOINT_V2_STAGE1_CONTROL
    if not _CHECKPOINT_V2_STAGE1_ENABLED:
        _memory_attribution_not_applicable(
            ("T6", "T7", "T8", "T9", "T10"),
            "checkpoint_v2_disabled")
        _CHECKPOINT_V2_STATUS = {
            "schemaVersion": argus_checkpoint_v2.SCHEMA,
            "state": "disabled",
            "isolatedWriter": {
                "writerMode": argus_checkpoint_v2_isolated.WRITER_MODE,
                "jobState": "disabled",
                "acceptanceBlocker": "checkpoint_v2_disabled",
            },
        }
        return dict(_CHECKPOINT_V2_STATUS)
    try:
        trigger_source = str(
            _MISSION_TICK_CONTEXT.get("triggerSource") or "manual")
        mission_window_id = _MISSION_TICK_CONTEXT.get("missionWindowId")
        result = argus_checkpoint_v2_isolated.launch_isolated_generation(
            _CHECKPOINT_V2_ROOT,
            source_path=_OSINT_PERSIST_FILE,
            legacy_checkpoint=legacy_checkpoint,
            wal_path=_MISSION_WAL_FILE,
            wal_upper_sequence=int(
                legacy_checkpoint.get("includedWalSequence") or 0),
            backend_build_sha=_backend_exact_sha() or _backend_sha() or
                "unknown",
            backend_boot_id=str(_RUNTIME.get("bootId") or "unknown"),
            mission_window_id=mission_window_id,
            trigger_source=trigger_source,
            formal_soak_state=_CHECKPOINT_V2_STAGE1_CONTROL.get(
                "formalSoakState") or "not_started",
            diagnostic_callback=_memory_attribution_isolated_hook)
        _CHECKPOINT_V2_STAGE1_CONTROL = \
            argus_checkpoint_v2_stage1.record_generation(
                _CHECKPOINT_V2_STAGE1_CONTROL, result,
                trigger_source=trigger_source,
                mission_window_id=mission_window_id)
        _CHECKPOINT_V2_STATUS = {
            **argus_checkpoint_v2.public_status(_CHECKPOINT_V2_ROOT),
            "lastWriteVerified": bool(result.get("verified")),
            "resourceTelemetry": copy.deepcopy(
                result.get("resourceTelemetry") or {}),
            "validationWindowCount": int(
                _CHECKPOINT_V2_STAGE1_CONTROL.get(
                    "validationWindowCount") or 0),
            "generationCount": int(
                _CHECKPOINT_V2_STAGE1_CONTROL.get("generationCount") or 0),
            "lastErrorClass": None,
            "isolatedWriter": argus_checkpoint_v2_isolated.public_telemetry(
                result),
            "formalSoakArmed": bool(
                _CHECKPOINT_V2_STAGE1_CONTROL.get("formalSoakArmed")),
            "formalSoakState": _CHECKPOINT_V2_STAGE1_CONTROL.get(
                "formalSoakState"),
            "authorityPromotionBlocked": bool(
                _CHECKPOINT_V2_STAGE1_CONTROL.get(
                    "authorityPromotionBlocked")),
        }
    except (argus_checkpoint_v2.CheckpointV2Error,
            argus_checkpoint_v2_isolated.IsolatedWriterError) as exc:
        _CHECKPOINT_V2_STAGE1_CONTROL = \
            argus_checkpoint_v2_stage1.record_failure(
                _CHECKPOINT_V2_STAGE1_CONTROL, exc.classification,
                exc.details)
        _CHECKPOINT_V2_STATUS = {
            "schemaVersion": argus_checkpoint_v2.SCHEMA,
            "state": "validation_failed",
            "lastWriteVerified": False,
            "lastErrorClass": exc.classification,
            "lastErrorDetails": dict(exc.details),
            "isolatedWriter": {
                "writerMode": argus_checkpoint_v2_isolated.WRITER_MODE,
                "jobState": "failed",
                "childExitClassification": exc.classification,
                "acceptanceBlocker": exc.classification,
            },
            "formalSoakArmed": False,
            "formalSoakState": "not_started",
            "authorityPromotionBlocked": True,
        }
    except Exception as exc:
        _CHECKPOINT_V2_STAGE1_CONTROL = \
            argus_checkpoint_v2_stage1.record_failure(
                _CHECKPOINT_V2_STAGE1_CONTROL, type(exc).__name__)
        _CHECKPOINT_V2_STATUS = {
            "schemaVersion": argus_checkpoint_v2.SCHEMA,
            "state": "validation_failed",
            "lastWriteVerified": False,
            "lastErrorClass": type(exc).__name__,
            "formalSoakArmed": False,
            "formalSoakState": "not_started",
            "authorityPromotionBlocked": True,
        }
    return dict(_CHECKPOINT_V2_STATUS)


def _foundation_jobs_persist():
    """Fsync only bounded job metadata; never serialize the full market ledger."""
    payload = argus_foundation_job_checkpoint.envelope(
        _FOUNDATION_JOBS, saved_at=_ai_now_iso())
    return argus_persistent_storage.atomic_write_json(
        _FOUNDATION_JOBS_FILE, payload,
        temp_directory=_DURABILITY_PATHS["tempDirectory"],
        validator=argus_foundation_job_checkpoint.verify,
        temp_label="foundation-jobs")


def _foundation_jobs_restore_sidecar():
    try:
        if os.path.lexists(_FOUNDATION_JOBS_FILE) and os.path.islink(
                _FOUNDATION_JOBS_FILE):
            raise ValueError("foundation_job_checkpoint_symlink_rejected")
        if not os.path.exists(_FOUNDATION_JOBS_FILE):
            return None
        if os.path.getsize(_FOUNDATION_JOBS_FILE) > 8 * 1024 * 1024:
            raise ValueError("foundation_job_checkpoint_oversized")
        with open(_FOUNDATION_JOBS_FILE, encoding="utf-8") as handle:
            payload = json.load(handle)
        restored = argus_foundation_job_checkpoint.restored_state(
            payload, _FOUNDATION_JOBS)
        _FOUNDATION_JOBS.clear()
        _FOUNDATION_JOBS.update(restored)
        return payload.get("savedAt")
    except FileNotFoundError:
        return None
    except Exception as exc:
        _DURABLE_STATE["foundationJobsRestoreError"] = type(exc).__name__
        return None


def _replace_record(records, incoming, key):
    value = incoming.get(key)
    if value is None:
        return
    existing = next((row for row in records
                     if isinstance(row, dict) and row.get(key) == value), None)
    if existing is None:
        records.append(copy.deepcopy(incoming))
    else:
        existing.clear()
        existing.update(copy.deepcopy(incoming))


def _apply_mission_wal_record(record):
    payload = record.get("payload") or {}
    journal_event = payload.get("journalEvent")
    if isinstance(journal_event, dict):
        known = {str(row.get("idempotencyKey")) for row in _OPS_JOURNAL}
        if str(journal_event.get("idempotencyKey")) not in known and \
                argus_state_journal.append(_OPS_JOURNAL, journal_event):
            _OPS_JOURNAL_META["totalObserved"] += 1
        key = (f"{journal_event.get('aggregateType')}:"
               f"{journal_event.get('aggregateId')}")
        _OPS_SEQ[key] = max(
            int(_OPS_SEQ.get(key) or 0),
            int(journal_event.get("sequence") or 0))
        high_water_field = \
            argus_remote_journal.OPS_SEQUENCE_HIGH_WATER_FIELD
        if high_water_field in _OPS_JOURNAL_META:
            _OPS_JOURNAL_META[high_water_field] = max(
                int(_OPS_JOURNAL_META.get(high_water_field) or 0),
                _OPS_SEQ[key])
    patch = payload.get("aggregatePatch") or {}
    patch_type = patch.get("type")
    patch_record = patch.get("record")
    if isinstance(patch_record, dict):
        if patch_type == "mission":
            _replace_record(_MISSIONS, patch_record, "missionId")
        elif patch_type == "outcome":
            _replace_record(_OUTCOME_LEDGER, patch_record, "forecastId")
        elif patch_type == "forecast":
            _replace_record(_FORECAST_LEDGER, patch_record, "id")
        elif patch_type == "incident":
            _replace_record(_INCIDENTS, patch_record, "id")
        elif patch_type == "soak":
            # Same-build WAL may advance a soak, but never erase interruptions.
            if (not _SOAK.get("buildSha") or
                    _SOAK.get("buildSha") == patch_record.get("buildSha")):
                interruptions = list(_SOAK.get("interruptions") or [])
                _SOAK.update(copy.deepcopy(patch_record))
                for interruption in interruptions:
                    if interruption not in _SOAK.setdefault("interruptions", []):
                        _SOAK["interruptions"].append(interruption)
    transition = payload.get("transitionState")
    if isinstance(transition, dict):
        mission = transition.get("mission")
        if isinstance(mission, dict):
            _replace_record(_MISSIONS, mission, "missionId")
        for key, target in (
                ("postmortems", _POSTMORTEMS),
                ("periodicReports", _PERIODIC_REPORTS),
                ("challengerRuns", _CHALLENGER_RUNS)):
            values = transition.get(key)
            if isinstance(values, list):
                target[:] = copy.deepcopy(values)
        agent_queue = transition.get("agentQueue")
        if isinstance(agent_queue, dict):
            _OSINT_AGENT_QUEUE.clear()
            _OSINT_AGENT_QUEUE.update(copy.deepcopy(agent_queue))
        batch = transition.get("batch")
        if isinstance(batch, dict):
            _MISSION_BATCH_STATE.update(batch)
    _MISSION_BATCH_STATE["walAppliedSequence"] = max(
        int(_MISSION_BATCH_STATE.get("walAppliedSequence") or 0),
        int(record.get("sequence") or 0))


def _restore_mission_wal(after_sequence=0):
    state = argus_tick_durability.read_valid_wal(
        _MISSION_WAL_FILE, after_sequence=int(after_sequence or 0))
    for record in state["records"]:
        if record.get("kind") != "checkpoint_verified":
            _apply_mission_wal_record(record)
    if argus_remote_journal.OPS_SEQUENCE_HIGH_WATER_FIELD in \
            _OPS_JOURNAL_META:
        _bound_ops_sequence_allocator_state()
    _DURABLE_STATE["missionWalCorrupt"] = state["corruptCount"]
    _DURABLE_STATE["missionWalReplayed"] = len([
        row for row in state["records"]
        if row.get("kind") != "checkpoint_verified"])
    _DURABLE_STATE["missionWalBytes"] = state["bytes"]
    return state


class _RemoteRecoveryRestoreError(ValueError):
    """Safe, payload-free classification for cold-bootstrap failures."""


def _remote_recovery_restore_failure(classification):
    value = str(classification or "remote_recovery_invalid")
    if not re.fullmatch(r"[a-z][a-z0-9_]{0,95}", value):
        value = "remote_recovery_invalid"
    _DURABLE_STATE["remoteRecoveryError"] = value
    raise _RemoteRecoveryRestoreError(value)


def _response_bounded_json(response, maximum_bytes, classification):
    encoded = bytearray()
    try:
        for chunk in response.iter_content(chunk_size=16 * 1024):
            if not chunk:
                continue
            if len(encoded) + len(chunk) > maximum_bytes:
                _remote_recovery_restore_failure(classification)
            encoded.extend(chunk)
        return json.loads(encoded.decode("utf-8"))
    except _RemoteRecoveryRestoreError:
        raise
    except (TypeError, UnicodeError, json.JSONDecodeError, RecursionError):
        _remote_recovery_restore_failure(classification)


def _github_ledger_repository(raw_base):
    """Return the exact GitHub repository named by one raw-content base."""
    matched = re.fullmatch(
        r"https://raw\.githubusercontent\.com/"
        r"([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)(?:/[A-Za-z0-9_./-]+)?",
        str(raw_base or "").rstrip("/"))
    if not matched:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_repository_invalid")
    return matched.group(1), matched.group(2)


def _bounded_ledger_commit_metadata(owner, repository, commit_sha):
    """Fetch one immutable Git commit object with a strict response cap."""
    commit = str(commit_sha or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", commit):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_commit_invalid")
    response = None
    try:
        response = requests.get(
            f"https://api.github.com/repos/{owner}/{repository}/git/commits/"
            f"{commit}", timeout=(6, 15), stream=True,
            headers={"Accept": "application/vnd.github+json"})
        if response.status_code != 200:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_metadata_http_error")
        encoded = bytearray()
        for chunk in response.iter_content(chunk_size=4096):
            if not chunk:
                continue
            if len(encoded) + len(chunk) > \
                    _LEDGER_COMMIT_METADATA_MAX_BYTES:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_commit_metadata_oversized")
            encoded.extend(chunk)
        try:
            value = json.loads(encoded.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_metadata_invalid") from exc
        if not isinstance(value, dict) or str(value.get("sha") or "").lower() \
                != commit or not isinstance(value.get("parents"), list):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_metadata_invalid")
        parents = []
        for parent in value["parents"]:
            parent_sha = (str(parent.get("sha") or "").lower()
                          if isinstance(parent, dict) else "")
            if not re.fullmatch(r"[0-9a-f]{40}", parent_sha):
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_commit_metadata_invalid")
            parents.append(parent_sha)
        return {"sha": commit, "parents": parents}
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_commit_metadata_transport_error") from exc
    finally:
        if response is not None:
            response.close()


def _bounded_ledger_compare(owner, repository, base_commit_sha,
                            exact_commit_sha):
    """Prove one complete linear ancestry segment in a bounded response.

    GitHub's unpaginated comparison is capped at 250 commits.  Requiring its
    declared distance to equal the complete returned parent chain preserves
    the existing no-merge rule without one network request per commit.  A
    longer or truncated comparison is ambiguous and remains fail-closed.
    """
    owner = str(owner or "")
    repository = str(repository or "")
    base = str(base_commit_sha or "").lower()
    exact = str(exact_commit_sha or "").lower()
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", owner) or not re.fullmatch(
            r"[A-Za-z0-9_.-]+", repository):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_repository_invalid")
    if not re.fullmatch(r"[0-9a-f]{40}", base) or not re.fullmatch(
            r"[0-9a-f]{40}", exact):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_commit_invalid")

    request_url = (
        f"https://api.github.com/repos/{owner}/{repository}/compare/"
        f"{base}...{exact}")
    response = None
    try:
        response = requests.get(
            request_url, timeout=(6, 15), stream=True,
            allow_redirects=False,
            headers={
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
            })
        if response.status_code != 200:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_http_error")
        encoded = bytearray()
        for chunk in response.iter_content(chunk_size=16 * 1024):
            if not chunk:
                continue
            if len(encoded) + len(chunk) > \
                    _LEDGER_COMPARE_RESPONSE_MAX_BYTES:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_compare_oversized")
            encoded.extend(chunk)
        try:
            value = json.loads(encoded.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_invalid") from exc

        commit_url = (
            f"https://api.github.com/repos/{owner}/{repository}/commits/")
        base_value = value.get("base_commit") \
            if isinstance(value, dict) else None
        merge_base = value.get("merge_base_commit") \
            if isinstance(value, dict) else None
        commits = value.get("commits") if isinstance(value, dict) else None
        ahead = value.get("ahead_by") if isinstance(value, dict) else None
        behind = value.get("behind_by") if isinstance(value, dict) else None
        total = value.get("total_commits") \
            if isinstance(value, dict) else None
        status = value.get("status") if isinstance(value, dict) else None
        if not isinstance(value, dict) or value.get("url") != request_url or \
                not isinstance(base_value, dict) or \
                base_value.get("sha") != base or \
                base_value.get("url") != commit_url + base or \
                not isinstance(merge_base, dict) or \
                merge_base.get("sha") != base or \
                merge_base.get("url") != commit_url + base or \
                type(ahead) is not int or type(behind) is not int or \
                type(total) is not int or not isinstance(commits, list):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_invalid")

        if base == exact:
            if status != "identical" or ahead != 0 or behind != 0 or \
                    total != 0 or commits:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_compare_invalid")
            return {
                "status": "verified", "ledgerBaseCommitSha": base,
                "exactCommitSha": exact, "distance": 0,
            }

        if status in ("behind", "diverged"):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_nonancestor")
        if status != "ahead" or behind != 0 or ahead <= 0 or \
                total != ahead:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_invalid")
        if ahead > _LEDGER_COMPARE_MAX_COMMITS or len(commits) != ahead:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_incomplete")

        previous = base
        visited = {base}
        for commit in commits:
            commit_sha = str(
                commit.get("sha") if isinstance(commit, dict) else ""
            ).lower()
            parents = commit.get("parents") \
                if isinstance(commit, dict) else None
            if not re.fullmatch(r"[0-9a-f]{40}", commit_sha) or \
                    commit_sha in visited or commit.get("url") != \
                    commit_url + commit_sha or not isinstance(parents, list):
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_compare_invalid")
            if len(parents) > 1:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_commit_multiparent")
            if len(parents) != 1:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_commit_nonancestor")
            parent = parents[0]
            parent_sha = str(
                parent.get("sha") if isinstance(parent, dict) else ""
            ).lower()
            if parent_sha != previous or not isinstance(parent, dict) or \
                    parent.get("url") != commit_url + parent_sha:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_ledger_commit_nonancestor")
            visited.add(commit_sha)
            previous = commit_sha
        if previous != exact:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_compare_invalid")
        return {
            "status": "verified", "ledgerBaseCommitSha": base,
            "exactCommitSha": exact, "distance": ahead,
        }
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_compare_transport_error") from exc
    finally:
        if response is not None:
            response.close()


def _verify_authenticated_ledger_commit_path(
        ledger_base_commit_sha, exact_commit_sha, *, owner, repository):
    """Prove authenticated base C is on one bounded linear path to exact X.

    ``ledger_base_commit_sha`` is accepted only after AES-GCM pair validation
    by each caller.  Short paths use exact immutable Git objects.  Longer paths
    use one bounded, complete GitHub comparison.  Both reject merge commits so
    a sibling cannot be smuggled in through second-parent ancestry.
    """
    base = str(ledger_base_commit_sha or "").lower()
    exact = str(exact_commit_sha or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", base) or not re.fullmatch(
            r"[0-9a-f]{40}", exact):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_commit_invalid")
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", str(owner or "")) or not \
            re.fullmatch(r"[A-Za-z0-9_.-]+", str(repository or "")):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_ledger_repository_invalid")
    current = exact
    visited = set()
    for distance in range(_LEDGER_ANCESTRY_FAST_PATH_COMMITS):
        if current in visited:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_metadata_invalid")
        visited.add(current)
        metadata = _bounded_ledger_commit_metadata(
            owner, repository, current)
        parents = metadata["parents"]
        if len(parents) > 1:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_multiparent")
        if current == base:
            return {
                "status": "verified", "ledgerBaseCommitSha": base,
                "exactCommitSha": exact, "distance": distance,
            }
        if not parents:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_ledger_commit_nonancestor")
        if distance + 1 >= _LEDGER_ANCESTRY_FAST_PATH_COMMITS:
            return _bounded_ledger_compare(
                owner, repository, base, exact)
        current = parents[0]
    return _bounded_ledger_compare(owner, repository, base, exact)


def _pinned_ledger_restore_base():
    """Resolve the moving ledger ref once and return its immutable base+SHA."""
    raw = str(_LEDGER_RAW_BASE or "").rstrip("/")
    matched = re.fullmatch(
        r"https://raw\.githubusercontent\.com/"
        r"([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)/"
        r"([A-Za-z0-9_.-]+)(/[A-Za-z0-9_./-]+)?",
        raw)
    if not matched:
        _remote_recovery_restore_failure("ledger_raw_base_invalid")
    owner, repository, ref, suffix = matched.groups()
    if re.fullmatch(r"[0-9a-fA-F]{40}", ref):
        sha = ref.lower()
    else:
        response = None
        try:
            request_url = (
                f"https://api.github.com/repos/{owner}/{repository}/git/ref/"
                f"heads/{ref}")
            response = requests.get(
                request_url, timeout=(6, 15), stream=True,
                allow_redirects=False,
                headers={
                    "Accept": "application/vnd.github+json",
                    "X-GitHub-Api-Version": "2022-11-28",
                })
            if response.status_code != 200:
                _remote_recovery_restore_failure(
                    "ledger_ref_resolution_http_error")
            value = _response_bounded_json(
                response, _LEDGER_REF_RESPONSE_MAX_BYTES,
                "ledger_ref_resolution_unreadable")
            expected_ref = f"refs/heads/{ref}"
            expected_ref_url = (
                f"https://api.github.com/repos/{owner}/{repository}/git/refs/"
                f"heads/{ref}")
            target = value.get("object") if isinstance(value, dict) else None
            sha = str(
                target.get("sha") if isinstance(target, dict) else "").lower()
            expected_commit_url = (
                f"https://api.github.com/repos/{owner}/{repository}/git/"
                f"commits/{sha}")
            if not isinstance(value, dict) or value.get("ref") != expected_ref or \
                    value.get("url") != expected_ref_url or not \
                    isinstance(target, dict) or target.get("type") != "commit" or \
                    not re.fullmatch(r"[0-9a-f]{40}", sha) or \
                    target.get("url") != expected_commit_url:
                _remote_recovery_restore_failure(
                    "ledger_ref_resolution_invalid")
        except _RemoteRecoveryRestoreError:
            raise
        except Exception:
            _remote_recovery_restore_failure(
                "ledger_ref_resolution_transport_error")
        finally:
            if response is not None:
                response.close()
    return {
        "base": (f"https://raw.githubusercontent.com/{owner}/{repository}/{sha}"
                 f"{suffix or ''}"),
        "commitSha": sha,
        "owner": owner,
        "repository": repository,
        "pathPrefix": str(suffix or "").strip("/"),
    }


def _fetch_pinned_recovery_object(url, maximum_bytes, name):
    """Fetch one optional immutable object without deciding pair semantics."""
    response = None
    try:
        try:
            response = requests.get(
                url, timeout=_DURABLE_RESTORE_HTTP_TIMEOUT, stream=True)
        except Exception:
            return {"status": "transport_error", "value": None}
        if response.status_code == 404:
            return {"status": "absent", "value": None}
        if response.status_code != 200:
            return {"status": "http_error", "value": None}
        try:
            value = _response_bounded_json(
                response, maximum_bytes,
                f"remote_{name}_unreadable_or_oversized")
        except _RemoteRecoveryRestoreError as exc:
            # This fetch also runs before a healthy local keyed checkpoint can
            # become authority. Keep malformed remote evidence in the recovery
            # domain so the caller fails closed without quarantining local
            # checkpoint bytes as though they were corrupt.
            raise argus_remote_recovery.RecoveryBundleError(str(exc)) from exc
        return {"status": "present", "value": value}
    finally:
        if response is not None:
            response.close()


def _recovery_key_for_envelope(envelope, configured):
    """Select only the key named by authenticated envelope metadata."""
    verified = argus_remote_recovery.validate_envelope(envelope)
    identifier = verified["keyId"]
    for slot in ("current", "previous"):
        candidate = configured.get(slot)
        if isinstance(candidate, dict) and candidate.get("keyId") == identifier:
            return candidate
    raise argus_remote_recovery.RecoveryBundleError(
        "recovery_key_id_unavailable")


def _read_local_recovery_sidecar(path=None):
    """Read one bounded local sidecar without exposing encrypted contents."""
    target = os.path.abspath(path or _REMOTE_RECOVERY_FILE)
    descriptor = None
    try:
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(target, flags)
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_size > \
                argus_remote_recovery.MAX_SIDECAR_BYTES:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_local_sidecar_invalid")
        encoded = bytearray()
        while True:
            chunk = os.read(descriptor, 64 * 1024)
            if not chunk:
                break
            if len(encoded) + len(chunk) > \
                    argus_remote_recovery.MAX_SIDECAR_BYTES:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_local_sidecar_invalid")
            encoded.extend(chunk)
        after = os.fstat(descriptor)
        if (before.st_dev, before.st_ino, before.st_size,
                before.st_mtime_ns, before.st_ctime_ns) != (
                after.st_dev, after.st_ino, after.st_size,
                after.st_mtime_ns, after.st_ctime_ns):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_local_sidecar_changed")
        sidecar = json.loads(encoded.decode("utf-8"))
        return argus_remote_recovery.validate_sidecar(sidecar)
    except FileNotFoundError as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_sidecar_missing") from exc
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except (OSError, TypeError, ValueError, json.JSONDecodeError,
            RecursionError) as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_sidecar_unreadable") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def _recovery_checkpoint_generation_path(checkpoint_path, checkpoint_hash):
    """Return a deterministic private path for one immutable generation."""
    normalized = str(checkpoint_hash or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", normalized):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_generation_hash_invalid")
    canonical = os.path.abspath(checkpoint_path)
    return canonical + ".recovery-generation-" + normalized


def _verify_recovery_checkpoint_generation(path, expected_hash):
    """Load one regular sealed generation and verify its exact object hash."""
    target = os.path.abspath(path)
    try:
        metadata = os.stat(target, follow_symlinks=False)
        if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(
                metadata.st_mode):
            raise OSError("generation_not_regular")
        checkpoint = argus_persistent_storage.load_checkpoint(
            target, require_seal=True)
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_generation_invalid") from exc
    if not hmac.compare_digest(
            argus_persistent_storage._canonical_sha256(checkpoint),
            str(expected_hash or "").lower()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_generation_hash_mismatch")
    return checkpoint


def _install_recovery_checkpoint_generation(
        source_path, checkpoint_path, expected_hash):
    """Install an immutable-by-name checkpoint generation without overwrite."""
    source = os.path.abspath(source_path)
    target = _recovery_checkpoint_generation_path(
        checkpoint_path, expected_hash)
    checkpoint = _verify_recovery_checkpoint_generation(
        source, expected_hash)
    try:
        os.link(source, target, follow_symlinks=False)
        argus_persistent_storage._fsync_directory(os.path.dirname(target))
    except FileExistsError:
        pass
    except OSError as exc:
        if exc.errno not in (errno.EXDEV, errno.EPERM, errno.EACCES,
                             errno.ENOTSUP):
            raise
        descriptor = None
        try:
            descriptor = os.open(
                target, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
                getattr(os, "O_NOFOLLOW", 0), 0o600)
            with open(source, "rb") as reader, os.fdopen(
                    descriptor, "wb", buffering=0) as writer:
                descriptor = None
                shutil.copyfileobj(reader, writer, length=1024 * 1024)
                os.fsync(writer.fileno())
            argus_persistent_storage._fsync_directory(
                os.path.dirname(target))
        except FileExistsError:
            pass
        finally:
            if descriptor is not None:
                os.close(descriptor)
    installed = _verify_recovery_checkpoint_generation(
        target, expected_hash)
    if installed != checkpoint:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_generation_changed")
    return target


def _cleanup_recovery_checkpoint_generations(
        checkpoint_path, retained_hashes):
    """Remove only superseded hash-named generations; authority is untouched."""
    canonical = os.path.abspath(checkpoint_path)
    directory = os.path.dirname(canonical)
    prefix = os.path.basename(canonical) + ".recovery-generation-"
    retained = {str(value or "").lower() for value in retained_hashes}
    if not retained or any(not re.fullmatch(
            r"[0-9a-f]{64}", value) for value in retained):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_generation_retention_invalid")
    _remote_recovery_crash_boundary("during_pair_cleanup")
    for name in os.listdir(directory):
        if not name.startswith(prefix):
            continue
        suffix = name[len(prefix):]
        if not re.fullmatch(r"[0-9a-f]{64}", suffix) or suffix in retained:
            continue
        candidate = os.path.join(directory, name)
        metadata = os.stat(candidate, follow_symlinks=False)
        if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(
                metadata.st_mode):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_checkpoint_generation_cleanup_invalid")
        os.unlink(candidate)
    argus_persistent_storage._fsync_directory(directory)


def _validated_recovery_required_marker(checkpoint_blob):
    """Return an exact sealed feature marker, or ``None`` for true legacy."""
    marker = checkpoint_blob.get("remoteRecoveryRequired")
    if marker is None:
        return None
    if not isinstance(marker, dict) or set(marker) != {
            "schemaVersion", "mode", "keyId", "checkpointId"} or marker.get(
                "schemaVersion") != argus_remote_recovery.SIDECAR_SCHEMA or \
            marker.get("mode") != "encrypted_required":
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_invalid")
    identifier = argus_remote_recovery.validate_key_id(marker.get("keyId"))
    checkpoint_id = str(marker.get("checkpointId") or "")
    if not argus_remote_recovery.CHECKPOINT_ID_RE.fullmatch(checkpoint_id):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_invalid")
    return {
        "schemaVersion": argus_remote_recovery.SIDECAR_SCHEMA,
        "mode": "encrypted_required",
        "keyId": identifier,
        "checkpointId": checkpoint_id,
    }


def _migrate_legacy_local_recovery(
        checkpoint_blob, configured, *, authenticated_local_handoff=None,
        pinned_legacy_evidence=None, pinned_ledger=None,
        restore_token=None):
    """One-time sealed legacy -> encrypted-required local migration.

    The rewritten checkpoint is never returned to the restore applicator until
    its current-key sidecar has survived atomic replacement, read-back, tag
    verification, and exact checkpoint projection verification.
    """
    current = configured.get("current")
    if not isinstance(current, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_current_key_unavailable")
    migration_handoff = (
        pinned_legacy_evidence, pinned_ledger, restore_token)
    if any(value is not None for value in migration_handoff) and not all(
            value is not None for value in migration_handoff):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_handoff_invalid")
    if pinned_legacy_evidence is not None:
        try:
            canonical = argus_persistent_storage.load_checkpoint(
                _OSINT_PERSIST_FILE, require_seal=True)
        except Exception as exc:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_legacy_ledger_base_checkpoint_invalid") from exc
        if canonical != checkpoint_blob or not \
                argus_persistent_storage.verify_checkpoint(
                    checkpoint_blob, require_seal=True) or \
                _validated_recovery_required_marker(
                    checkpoint_blob) is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_legacy_ledger_base_checkpoint_invalid")
    staged_checkpoint = None
    staged_lock = None
    try:
        migrated = copy.deepcopy(checkpoint_blob)
        migrated_sequences, migrated_meta = \
            argus_remote_journal.bounded_sequence_allocator_state(
                sequences=migrated.get("opsSequenceByAggregate") or {},
                events=migrated.get("opsJournal") or [],
                meta=migrated.get("opsJournalMeta") or {})
        migrated["opsSequenceByAggregate"] = migrated_sequences
        migrated["opsJournalMeta"] = migrated_meta
        migrated["remoteRecoveryRequired"] = {
            "schemaVersion": argus_remote_recovery.SIDECAR_SCHEMA,
            "mode": "encrypted_required",
            "keyId": current["keyId"],
            "checkpointId": f"rcp-{os.urandom(16).hex()}",
        }
        durability = migrated.get("missionTickDurability")
        target_wal = (durability.get("walAppliedSequence")
                      if isinstance(durability, dict) else None)
        if isinstance(target_wal, bool) or not isinstance(target_wal, int) or \
                target_wal <= 0:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_legacy_migration_wal_invalid")
        # Build and authenticate the new generation away from the canonical
        # checkpoint first.  The encrypted sidecar is installed before the
        # final checkpoint rename, so a crash can leave only either the old
        # legacy authority or the complete new checkpoint/sidecar pair.  An
        # interrupted sidecar-first attempt is safe to overwrite on the next
        # migration because nonce reservation authenticates its installed
        # floor before allocating a new value.
        staged_checkpoint = os.path.join(
            _DURABILITY_PATHS["tempDirectory"],
            (f"{os.path.basename(_OSINT_PERSIST_FILE)}.{os.getpid()}."
             f"{os.urandom(16).hex()}.recovery-migration-checkpoint"))
        staged_lock = staged_checkpoint + ".writer.lock"
        write = argus_persistent_storage.write_checkpoint(
            staged_checkpoint, migrated,
            temp_directory=_DURABILITY_PATHS["tempDirectory"])
        staged = argus_persistent_storage.load_checkpoint(
            staged_checkpoint, require_seal=True)
        ledger_base_capability = None
        if pinned_legacy_evidence is not None:
            ledger_base_capability = \
                _mint_legacy_recovery_ledger_base_capability(
                    staged, configured, pinned_ledger,
                    pinned_legacy_evidence, restore_token)
        _persist_remote_recovery_sidecar({
            **write,
            "verified": True,
            "readBackVerified": write.get("readBackVerified") is True,
            "includedWalSequence": target_wal,
        }, checkpoint_path=staged_checkpoint,
            legacy_ledger_base_capability=ledger_base_capability,
            restore_token=(restore_token
                           if ledger_base_capability is not None else None))
        staged = argus_persistent_storage.load_checkpoint(
            staged_checkpoint, require_seal=True)
        _verify_local_recovery_sidecar(
            staged, allow_legacy_migration=False)
        os.replace(staged_checkpoint, _OSINT_PERSIST_FILE)
        staged_checkpoint = None
        argus_persistent_storage._fsync_directory(
            os.path.dirname(os.path.abspath(_OSINT_PERSIST_FILE)))
        installed = argus_persistent_storage.load_checkpoint(
            _OSINT_PERSIST_FILE, require_seal=True)
        verified = _verify_local_recovery_sidecar(
            installed, allow_legacy_migration=False,
            authenticated_local_handoff=authenticated_local_handoff)
    except argus_remote_recovery.RecoveryBundleError:
        raise
    except Exception as exc:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_migration_failed") from exc
    finally:
        for candidate in (staged_checkpoint, staged_lock):
            if candidate:
                try:
                    os.unlink(candidate)
                except FileNotFoundError:
                    pass
                except OSError:
                    # A leftover staging generation is never authoritative;
                    # startup only reads the canonical checkpoint path.
                    pass
    _DURABLE_STATE["remoteRecoveryMigration"] = {
        "status": "verified", "keyId": current["keyId"],
        "targetWalSequence": target_wal,
    }
    return verified


def _verify_local_recovery_sidecar(
        checkpoint_blob, *, allow_legacy_migration=True,
        authenticated_local_handoff=None, pinned_legacy_evidence=None,
        pinned_ledger=None, restore_token=None, sidecar_value=None):
    """Authenticate a keyed local checkpoint before it becomes authority."""
    if authenticated_local_handoff is not None and (
            not isinstance(authenticated_local_handoff, list) or
            authenticated_local_handoff):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_handoff_invalid")
    migration_handoff = (
        pinned_legacy_evidence, pinned_ledger, restore_token)
    if any(value is not None for value in migration_handoff) and not all(
            value is not None for value in migration_handoff):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_legacy_ledger_base_handoff_invalid")
    marker = _validated_recovery_required_marker(checkpoint_blob)
    configured = argus_remote_recovery.configured_keys()
    if configured.get("status") == "not_configured":
        if os.path.lexists(_REMOTE_RECOVERY_FILE) or marker is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_key_not_configured")
        _DURABLE_STATE["remoteRecoveryLocal"] = {
            "status": "not_configured_legacy"}
        return checkpoint_blob
    if marker is None:
        if not allow_legacy_migration:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_required_marker_missing")
        return _migrate_legacy_local_recovery(
            checkpoint_blob, configured,
            authenticated_local_handoff=authenticated_local_handoff,
            pinned_legacy_evidence=pinned_legacy_evidence,
            pinned_ledger=pinned_ledger, restore_token=restore_token)
    sidecar = (_read_local_recovery_sidecar()
               if sidecar_value is None else
               argus_remote_recovery.validate_sidecar(sidecar_value))
    envelope = sidecar["recovery"]
    if marker["keyId"] != envelope.get("keyId"):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_key_mismatch")
    if marker["checkpointId"] != envelope.get("checkpointId"):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_checkpoint_mismatch")
    selected = _recovery_key_for_envelope(envelope, configured)
    payload = argus_remote_recovery.validate_pair(
        sidecar["readback"], envelope, selected["key"],
        key_identifier=selected["keyId"])
    checkpoint_hash = argus_persistent_storage._canonical_sha256(
        checkpoint_blob)
    if payload.get("sourceCheckpointHash") != checkpoint_hash:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_checkpoint_hash_mismatch")
    if payload.get("checkpointId") != marker["checkpointId"]:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_checkpoint_identity_mismatch")
    raw_durability = checkpoint_blob.get("missionTickDurability")
    target_wal = payload["targetWalSequence"]
    if not isinstance(raw_durability, dict) or \
            raw_durability.get("walAppliedSequence") != target_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_checkpoint_wal_mismatch")
    export_durability = copy.deepcopy(raw_durability)
    export_durability["remoteWalAppliedSequence"] = target_wal
    exported_targets = _checkpoint_recovery_targets(
        checkpoint_blob, export_durability)
    for target in argus_remote_recovery.TARGET_KEYS:
        if exported_targets[target] != payload["targets"][target]:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_local_checkpoint_target_mismatch")
    prior_provenance = checkpoint_blob.get("remoteRecoveryProvenance")
    cycle = checkpoint_blob.get("remoteJournalCycle")
    ledger_commit = (
        prior_provenance.get("ledgerCommitSha")
        if isinstance(prior_provenance, dict) else None)
    if not re.fullmatch(r"[0-9a-f]{40}", str(ledger_commit or "").lower()):
        remote_commit = (cycle.get("remoteCommitSha")
                         if isinstance(cycle, dict) else None)
        receipt_commit = (cycle.get("receiptCommitSha")
                          if isinstance(cycle, dict) else None)
        normalized_remote = str(remote_commit or "").lower()
        ledger_commit = (normalized_remote
                         if remote_commit == receipt_commit and re.fullmatch(
                             r"[0-9a-f]{40}", normalized_remote) else None)
    if ledger_commit is not None and not re.fullmatch(
            r"[0-9a-f]{40}", str(ledger_commit).lower()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_ledger_commit_invalid")
    if authenticated_local_handoff is not None:
        authenticated_local_handoff.append(_AuthenticatedLocalRecoveryPair(
            sidecar["readback"], payload, envelope, selected,
            str(ledger_commit).lower() if ledger_commit is not None else None))
    verified = copy.deepcopy(checkpoint_blob)
    verified["remoteRecoveryProvenance"] = {
        "schemaVersion": envelope["schemaVersion"],
        "restoreKind": "local_sidecar",
        "buildIdentity": copy.deepcopy(payload["buildIdentity"]),
        "targetWalSequence": payload["targetWalSequence"],
        "compactReceiptHash": payload["compactReceiptHash"],
        "sourceCheckpointHash": payload["sourceCheckpointHash"],
        "checkpointVerifiedAt": payload["checkpointVerifiedAt"],
        "checkpointId": payload["checkpointId"],
        "bundleHash": envelope["bundleHash"],
        "generationId": envelope["generationId"],
        "keyId": envelope["keyId"],
        "ledgerBaseCommitSha": envelope["ledgerBaseCommitSha"],
        "ledgerCommitSha": (str(ledger_commit).lower()
                            if ledger_commit is not None else None),
        "walAllocatorFloor": payload["targetWalSequence"],
    }
    _DURABLE_STATE["remoteRecoveryLocal"] = {
        "status": "verified", "keyId": envelope["keyId"],
        "generationId": envelope["generationId"],
        "targetWalSequence": payload["targetWalSequence"],
    }
    return verified


def _resolve_authoritative_local_recovery_checkpoint(
        canonical_checkpoint, checkpoint_path, configured):
    """Resolve the exact checkpoint selected by the authenticated sidecar.

    The sidecar is the only pair authority selector.  The canonical path is a
    compatibility projection and may lag an already-committed sidecar switch
    after a crash.  A lagging projection is accepted only when an immutable
    hash-named generation verifies against the authenticated payload.
    """
    if configured.get("status") != "configured" or not isinstance(
            canonical_checkpoint, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_checkpoint_resolution_invalid")
    sidecar = _read_local_recovery_sidecar()
    envelope = sidecar["recovery"]
    selected = _recovery_key_for_envelope(envelope, configured)
    payload = argus_remote_recovery.validate_pair(
        sidecar["readback"], envelope, selected["key"],
        key_identifier=selected["keyId"])
    canonical_marker = _validated_recovery_required_marker(
        canonical_checkpoint)
    if canonical_marker is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_missing")
    if canonical_marker["keyId"] != envelope.get("keyId"):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_required_marker_key_mismatch")
    expected_hash = payload["sourceCheckpointHash"]
    canonical_hash = argus_persistent_storage._canonical_sha256(
        canonical_checkpoint)
    if hmac.compare_digest(canonical_hash, expected_hash):
        verified = _verify_local_recovery_sidecar(
            canonical_checkpoint, allow_legacy_migration=False,
            sidecar_value=sidecar)
        return {
            "checkpoint": canonical_checkpoint,
            "verifiedCheckpoint": verified,
            "path": os.path.abspath(checkpoint_path),
            "sidecar": sidecar,
            "payload": payload,
            "projectionCurrent": True,
        }
    generation_path = _recovery_checkpoint_generation_path(
        checkpoint_path, expected_hash)
    generation = _verify_recovery_checkpoint_generation(
        generation_path, expected_hash)
    verified = _verify_local_recovery_sidecar(
        generation, allow_legacy_migration=False, sidecar_value=sidecar)
    return {
        "checkpoint": generation,
        "verifiedCheckpoint": verified,
        "path": generation_path,
        "sidecar": sidecar,
        "payload": payload,
        "projectionCurrent": False,
    }


_PARTIAL_ACTIVATION_REPAIR_SCHEMA = \
    "argus-recovery-partial-activation-repair-v1"
_CANONICAL_ABSENT_PARTIAL_ACTIVATION_REPAIR_SCHEMA = \
    "argus-recovery-partial-activation-canonical-absent-v1"
_CANONICAL_ABSENT_REPAIR_RESULT_SCHEMA = \
    "argus-recovery-canonical-absent-repair-result-v1"
_POST_GENESIS_PAIR_REPAIR_SCHEMA = \
    "argus-recovery-post-genesis-pair-repair-v1"
_POST_GENESIS_PAIR_REPAIR_RESULT_SCHEMA = \
    "argus-recovery-post-genesis-pair-repair-result-v1"
_POST_GENESIS_PAIR_REPAIR_PROCESS_TOKEN = object()


class _PostGenesisMismatchRepairCapability:
    __slots__ = (
        "_token", "_checkpoint_path", "_checkpoint_hash",
        "_checkpoint_identity", "_sidecar_path", "_sidecar_hash",
        "_sidecar_identity", "_key_id", "_key_domain", "_payload",
        "_ledger_base", "_consumed")

    def __init__(self, *, checkpoint_path, checkpoint_hash,
                 checkpoint_identity, sidecar_path, sidecar_hash,
                 sidecar_identity, key_id, key_domain, payload,
                 ledger_base):
        self._token = _POST_GENESIS_PAIR_REPAIR_PROCESS_TOKEN
        self._checkpoint_path = checkpoint_path
        self._checkpoint_hash = checkpoint_hash
        self._checkpoint_identity = checkpoint_identity
        self._sidecar_path = sidecar_path
        self._sidecar_hash = sidecar_hash
        self._sidecar_identity = sidecar_identity
        self._key_id = key_id
        self._key_domain = key_domain
        self._payload = copy.deepcopy(payload)
        self._ledger_base = ledger_base
        self._consumed = False


def _remote_recovery_file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _post_genesis_repair_file_identity(path):
    target = os.path.abspath(path)
    metadata = os.stat(target, follow_symlinks=False)
    if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_artifact_invalid")
    return {
        "path": target,
        "sha256": _remote_recovery_file_sha256(target),
        "bytes": metadata.st_size,
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "mode": stat.S_IMODE(metadata.st_mode),
        "mtimeNs": metadata.st_mtime_ns,
        "ctimeNs": metadata.st_ctime_ns,
    }


def _read_only_remote_recovery_nonce_authority(configured):
    """Verify every nonce mirror and anchor without repairing any mirror."""
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(
            _DURABILITY_PATHS["recoveryNonceState"], blocking=False,
            create=False)
        paths = _remote_recovery_nonce_paths()
        history = _read_remote_recovery_nonce_history(
            paths["history"], missing_ok=False)
        head = _read_remote_recovery_nonce_history_head(
            paths["head"], missing_ok=False)
        state = _read_remote_recovery_nonce_state(
            paths["state"], missing_ok=False)
        anchor = _remote_recovery_nonce_lock_anchor(lock_handle)
        if anchor is None or head != \
                _build_remote_recovery_nonce_history_head(history) or \
                state != {
                    "schemaVersion": _REMOTE_RECOVERY_NONCE_STATE_SCHEMA,
                    "historyGeneration": history["generation"],
                    "historyRecordHash": history["recordHash"],
                    "keyMaterialCounters": history[
                        "keyMaterialCounters"],
                } or anchor["generation"] != history["generation"] or \
                not hmac.compare_digest(
                    anchor["recordHash"], history["recordHash"]):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_repair_nonce_invalid")
        _verify_installed_remote_recovery_nonce_floor(history, configured)
        return history
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)


def _post_genesis_repair_nonce_artifacts():
    paths = _remote_recovery_nonce_paths()
    lock_path = _DURABILITY_PATHS[
        "recoveryNonceState"] + ".reservation.lock"
    epoch_path = lock_path + ".anchor"
    return {
        "state": _post_genesis_repair_file_identity(paths["state"]),
        "history": _post_genesis_repair_file_identity(paths["history"]),
        "head": _post_genesis_repair_file_identity(paths["head"]),
        "anchor": _post_genesis_repair_file_identity(
            epoch_path if os.path.lexists(epoch_path) else lock_path),
    }


def _find_matching_recovery_checkpoint_artifacts(checkpoint_hash):
    """Boundedly locate exact sealed artifacts matching one sidecar hash."""
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    maximum = argus_persistent_storage._maximum_checkpoint_bytes()
    matches = []
    examined = 0

    def fail_scan(exc):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_artifact_scan_ambiguous") from exc

    for directory, names, files in os.walk(
            root, followlinks=False, onerror=fail_scan):
        names[:] = [name for name in names if not os.path.islink(
            os.path.join(directory, name))]
        for name in files:
            examined += 1
            if examined > 512:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_post_genesis_repair_artifact_scan_unbounded")
            path = os.path.join(directory, name)
            try:
                metadata = os.stat(path, follow_symlinks=False)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_post_genesis_repair_artifact_scan_ambiguous") \
                    from exc
            if not stat.S_ISREG(metadata.st_mode) or \
                    metadata.st_size <= 0 or metadata.st_size > maximum:
                continue
            try:
                digest = _remote_recovery_file_sha256(path)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_post_genesis_repair_artifact_scan_ambiguous") \
                    from exc
            if not hmac.compare_digest(digest, checkpoint_hash):
                continue
            try:
                checkpoint = argus_persistent_storage.load_checkpoint(
                    path, require_seal=True)
            except Exception as exc:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_post_genesis_repair_matching_artifact_invalid") \
                    from exc
            if not hmac.compare_digest(
                    argus_persistent_storage._canonical_sha256(checkpoint),
                    checkpoint_hash):
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_post_genesis_repair_matching_artifact_invalid")
            matches.append(_post_genesis_repair_file_identity(path))
    return matches


def _plan_post_genesis_pair_repair(expected):
    """Read-only exact-state plan for the current nonce-present mismatch."""
    required = {
        "schemaVersion", "liveBuildSha", "currentCheckpoint",
        "currentSidecar", "currentKeyId", "previousKeyAbsent",
        "nonceAuthority", "writersFenced", "activeWriters",
        "ec2TimerDisabled", "ec2TimerInactive", "recoveryReadback",
        "previousMatchingCheckpointArtifact", "forensicBackupDirectory",
    }
    if not isinstance(expected, dict) or set(expected) != required or \
            expected.get("schemaVersion") != \
            _POST_GENESIS_PAIR_REPAIR_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_contract_invalid")
    if expected.get("writersFenced") is not True or \
            expected.get("activeWriters") != 0 or \
            expected.get("ec2TimerDisabled") is not True or \
            expected.get("ec2TimerInactive") is not True or \
            expected.get("recoveryReadback") != \
            "UNAVAILABLE_PAIR_MISMATCH" or \
            expected.get("previousMatchingCheckpointArtifact") != \
            "NOT_PROVEN":
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_fence_unproven")
    build_sha = str(expected.get("liveBuildSha") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", build_sha) or \
            not hmac.compare_digest(_backend_exact_sha(), build_sha):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_build_mismatch")
    configured = argus_remote_recovery.configured_keys()
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if configured.get("status") != "configured" or not isinstance(
            current, dict) or current.get("keyId") != expected.get(
                "currentKeyId") or expected.get(
                "previousKeyAbsent") is not True or \
            configured.get("previous") is not None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_key_mismatch")

    checkpoint_expected = expected.get("currentCheckpoint")
    sidecar_expected = expected.get("currentSidecar")
    if not isinstance(checkpoint_expected, dict) or set(
            checkpoint_expected) != {
                "path", "sha256", "bytes", "wal", "sealValid",
                "checkpointId"} or not isinstance(
                    sidecar_expected, dict) or set(sidecar_expected) != {
                "path", "sha256", "bytes", "boundCheckpointSha256",
                "boundCheckpointId"}:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_artifact_contract_invalid")
    checkpoint_path = os.path.abspath(_OSINT_PERSIST_FILE)
    sidecar_path = os.path.abspath(_REMOTE_RECOVERY_FILE)
    if os.path.abspath(str(checkpoint_expected.get("path") or "")) != \
            checkpoint_path or os.path.abspath(str(
                sidecar_expected.get("path") or "")) != sidecar_path:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_path_mismatch")
    checkpoint_identity = _post_genesis_repair_file_identity(
        checkpoint_path)
    sidecar_identity = _post_genesis_repair_file_identity(sidecar_path)
    if any(checkpoint_identity[name] != checkpoint_expected[name]
           for name in ("sha256", "bytes")) or any(
               sidecar_identity[name] != sidecar_expected[name]
               for name in ("sha256", "bytes")):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_artifact_mismatch")
    checkpoint = argus_persistent_storage.load_checkpoint(
        checkpoint_path, require_seal=True)
    if checkpoint_expected.get("sealValid") is not True or not \
            argus_persistent_storage.verify_checkpoint(
                checkpoint, require_seal=True) or not hmac.compare_digest(
                    argus_persistent_storage._canonical_sha256(checkpoint),
                    checkpoint_identity["sha256"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_checkpoint_invalid")
    marker = _validated_recovery_required_marker(checkpoint)
    durability = checkpoint.get("missionTickDurability")
    if marker is None or marker["keyId"] != current["keyId"] or \
            marker["checkpointId"] != checkpoint_expected.get(
                "checkpointId") or not isinstance(durability, dict) or \
            durability.get("walAppliedSequence") != checkpoint_expected.get(
                "wal"):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_checkpoint_state_mismatch")

    sidecar = _read_local_recovery_sidecar(sidecar_path)
    envelope = sidecar["recovery"]
    selected = _recovery_key_for_envelope(envelope, configured)
    payload = argus_remote_recovery.validate_pair(
        sidecar["readback"], envelope, selected["key"],
        key_identifier=selected["keyId"])
    if selected["keyId"] != current["keyId"] or \
            payload["sourceCheckpointHash"] != sidecar_expected.get(
                "boundCheckpointSha256") or payload["checkpointId"] != \
            sidecar_expected.get("boundCheckpointId") or \
            payload["targetWalSequence"] != checkpoint_expected.get(
                "wal") or (payload["sourceCheckpointHash"] ==
                    checkpoint_identity["sha256"] and payload[
                        "checkpointId"] == marker["checkpointId"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_sidecar_state_mismatch")
    export_durability = copy.deepcopy(durability)
    export_durability["remoteWalAppliedSequence"] = payload[
        "targetWalSequence"]
    targets = _checkpoint_recovery_targets(checkpoint, export_durability)
    if any(targets[name] != payload["targets"][name]
           for name in argus_remote_recovery.TARGET_KEYS):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_projection_mismatch")

    history = _read_only_remote_recovery_nonce_authority(configured)
    current_domain = _remote_recovery_nonce_domain(current["key"])
    maximum_counter = max(history["keyMaterialCounters"].values())
    nonce_expected = expected.get("nonceAuthority")
    artifacts = _post_genesis_repair_nonce_artifacts()
    if not isinstance(nonce_expected, dict) or set(nonce_expected) != {
            "generation", "maximumCounter", "artifacts"} or \
            nonce_expected.get("generation") != history["generation"] or \
            nonce_expected.get("maximumCounter") != maximum_counter or \
            nonce_expected.get("artifacts") != artifacts or \
            history["generation"] < 33 or maximum_counter < 33 or \
            int(history["keyMaterialCounters"].get(current_domain) or 0) != \
            maximum_counter:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_nonce_mismatch")
    previous_matches = _find_matching_recovery_checkpoint_artifacts(
        payload["sourceCheckpointHash"])
    if previous_matches:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_previous_checkpoint_found")

    backup_directory = os.path.abspath(str(
        expected.get("forensicBackupDirectory") or ""))
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    if os.path.dirname(backup_directory) != root or not \
            os.path.basename(backup_directory).startswith(
                "argus-recovery-post-genesis-forensic-") or \
            os.path.lexists(backup_directory):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_backup_path_invalid")
    if _post_genesis_repair_file_identity(checkpoint_path) != \
            checkpoint_identity or \
            _post_genesis_repair_file_identity(sidecar_path) != \
            sidecar_identity or \
            _post_genesis_repair_nonce_artifacts() != artifacts:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_state_changed")
    return {
        "schemaVersion": _POST_GENESIS_PAIR_REPAIR_SCHEMA,
        "status": "DRY_RUN_PASS",
        "mutationAuthorized": False,
        "liveBuildSha": build_sha,
        "currentKeyId": current["keyId"],
        "previousKeyAbsent": True,
        "checkpoint": checkpoint_identity,
        "checkpointId": marker["checkpointId"],
        "walSequence": checkpoint_expected["wal"],
        "sidecar": sidecar_identity,
        "sidecarBoundCheckpointSha256": payload[
            "sourceCheckpointHash"],
        "sidecarBoundCheckpointId": payload["checkpointId"],
        "ledgerBaseCommitSha": envelope["ledgerBaseCommitSha"],
        "nonceGeneration": history["generation"],
        "nonceMaximumCounter": maximum_counter,
        "nonceArtifacts": artifacts,
        "previousMatchingCheckpointArtifact": "NOT_PROVEN",
        "projectionEquality": "PROVEN",
        "forensicBackupDirectory": backup_directory,
        "repairStrategy": (
            "authenticate_previous_sidecar_then_exact_projection_rebind_"
            "current_checkpoint_with_new_nonce_and_atomic_sidecar_switch"),
    }


def _mint_post_genesis_mismatch_repair_capability(plan, checkpoint, payload):
    configured = argus_remote_recovery.configured_keys()
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if plan.get("status") != "DRY_RUN_PASS" or not isinstance(
            current, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_capability_invalid")
    checkpoint_identity = _post_genesis_repair_file_identity(
        plan["checkpoint"]["path"])
    sidecar_identity = _post_genesis_repair_file_identity(
        plan["sidecar"]["path"])
    if checkpoint_identity["sha256"] != plan["checkpoint"]["sha256"] or \
            sidecar_identity["sha256"] != plan["sidecar"]["sha256"]:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_capability_changed")
    return _PostGenesisMismatchRepairCapability(
        checkpoint_path=plan["checkpoint"]["path"],
        checkpoint_hash=plan["checkpoint"]["sha256"],
        checkpoint_identity=checkpoint_identity,
        sidecar_path=plan["sidecar"]["path"],
        sidecar_hash=plan["sidecar"]["sha256"],
        sidecar_identity=sidecar_identity,
        key_id=current["keyId"],
        key_domain=_remote_recovery_nonce_domain(current["key"]),
        payload=payload, ledger_base=plan["ledgerBaseCommitSha"])


def _consume_post_genesis_mismatch_repair_capability(
        capability, checkpoint_blob, compact, keys):
    """Consume one private exact-state ledger-base exception for repair."""
    current = keys.get("current") if isinstance(keys, dict) else None
    if not isinstance(capability, _PostGenesisMismatchRepairCapability) or \
            capability._token is not \
            _POST_GENESIS_PAIR_REPAIR_PROCESS_TOKEN or \
            capability._consumed or not isinstance(current, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_capability_invalid")
    capability._consumed = True
    if current.get("keyId") != capability._key_id or not \
            hmac.compare_digest(
                _remote_recovery_nonce_domain(current.get("key")),
                capability._key_domain) or \
            _post_genesis_repair_file_identity(
                capability._checkpoint_path) != \
            capability._checkpoint_identity or \
            _post_genesis_repair_file_identity(capability._sidecar_path) != \
            capability._sidecar_identity or not hmac.compare_digest(
                _remote_recovery_file_sha256(capability._checkpoint_path),
                capability._checkpoint_hash) or not hmac.compare_digest(
                    _remote_recovery_file_sha256(capability._sidecar_path),
                    capability._sidecar_hash) or \
            argus_persistent_storage._canonical_sha256(checkpoint_blob) != \
            capability._checkpoint_hash:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_capability_changed")
    durability = checkpoint_blob.get("missionTickDurability")
    if not isinstance(durability, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_capability_changed")
    export_durability = copy.deepcopy(durability)
    export_durability["remoteWalAppliedSequence"] = capability._payload[
        "targetWalSequence"]
    targets = _checkpoint_recovery_targets(
        checkpoint_blob, export_durability)
    if capability._payload["targetWalSequence"] != durability.get(
            "walAppliedSequence") or any(
                targets[name] != capability._payload["targets"][name]
                for name in argus_remote_recovery.TARGET_KEYS) or not \
            isinstance(compact, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_post_genesis_repair_projection_changed")
    return capability._ledger_base


def _execute_post_genesis_pair_repair(expected, *, execute=False):
    """Apply the exact mismatch repair only with an explicit owner action."""
    plan = _plan_post_genesis_pair_repair(expected)
    if execute is not True:
        return plan
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    staging = tempfile.mkdtemp(
        prefix=".argus-recovery-post-genesis-forensic-", dir=root)
    candidate_sidecar = None
    candidate_sidecar_lock = None
    try:
        artifacts = [
            ("checkpoint.json", plan["checkpoint"]),
            ("sidecar.json", plan["sidecar"]),
        ] + [(f"nonce-{name}", identity) for name, identity in sorted(
            plan["nonceArtifacts"].items())]
        manifest_artifacts = []
        for name, identity in artifacts:
            destination = os.path.join(staging, name)
            _write_canonical_absent_forensic_copy(
                identity["path"], destination, identity)
            manifest_artifacts.append({
                "role": name, "sourcePath": identity["path"],
                "backupFile": name, "sha256": identity["sha256"],
                "bytes": identity["bytes"], "mtimeNs": identity[
                    "mtimeNs"], "ctimeNs": identity["ctimeNs"],
            })
        manifest = {
            "schemaVersion":
                "argus-recovery-post-genesis-forensic-backup-v1",
            "liveBuildSha": plan["liveBuildSha"],
            "currentKeyId": plan["currentKeyId"],
            "previousKeyAbsent": True,
            "walSequence": plan["walSequence"],
            "checkpointId": plan["checkpointId"],
            "sidecarBoundCheckpointSha256": plan[
                "sidecarBoundCheckpointSha256"],
            "sidecarBoundCheckpointId": plan[
                "sidecarBoundCheckpointId"],
            "nonceGeneration": plan["nonceGeneration"],
            "nonceMaximumCounter": plan["nonceMaximumCounter"],
            "artifacts": manifest_artifacts,
        }
        manifest_path = os.path.join(staging, "manifest.json")
        manifest_write = argus_persistent_storage.atomic_write_json(
            manifest_path, manifest, temp_directory=staging,
            validator=lambda value: value == manifest,
            temp_label="post-genesis-forensic", file_mode=0o600)
        if manifest_write.get("readBackVerified") is not True:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_repair_backup_invalid")
        digest = _remote_recovery_file_sha256(manifest_path)
        digest_path = os.path.join(staging, "manifest.sha256")
        descriptor = os.open(
            digest_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
            getattr(os, "O_NOFOLLOW", 0), 0o600)
        with os.fdopen(descriptor, "wb", buffering=0) as handle:
            handle.write((digest + "  manifest.json\n").encode("ascii"))
            os.fsync(handle.fileno())
        argus_persistent_storage._fsync_directory(staging)
        _plan_post_genesis_pair_repair(expected)
        os.replace(staging, plan["forensicBackupDirectory"])
        staging = None
        argus_persistent_storage._fsync_directory(root)

        checkpoint = argus_persistent_storage.load_checkpoint(
            plan["checkpoint"]["path"], require_seal=True)
        sidecar = _read_local_recovery_sidecar(plan["sidecar"]["path"])
        configured = argus_remote_recovery.configured_keys()
        selected = _recovery_key_for_envelope(
            sidecar["recovery"], configured)
        payload = argus_remote_recovery.validate_pair(
            sidecar["readback"], sidecar["recovery"], selected["key"],
            key_identifier=selected["keyId"])
        _install_recovery_checkpoint_generation(
            plan["checkpoint"]["path"], plan["checkpoint"]["path"],
            plan["checkpoint"]["sha256"])
        capability = _mint_post_genesis_mismatch_repair_capability(
            plan, checkpoint, payload)
        candidate_sidecar = os.path.join(
            root, f".{os.path.basename(_REMOTE_RECOVERY_FILE)}."
            f"{os.getpid()}.{os.urandom(16).hex()}.repair-candidate")
        candidate_sidecar_lock = candidate_sidecar + ".writer.lock"
        receipt = {
            "verified": True,
            "readBackVerified": True,
            "snapshotHash": plan["checkpoint"]["sha256"],
            "verifiedAt": _ai_now_iso(),
            "includedWalSequence": plan["walSequence"],
        }
        result = _persist_remote_recovery_sidecar(
            receipt, checkpoint_path=plan["checkpoint"]["path"],
            sidecar_path=candidate_sidecar,
            ledger_base_capability=capability)
        candidate = _read_local_recovery_sidecar(candidate_sidecar)
        _verify_local_recovery_sidecar(
            checkpoint, allow_legacy_migration=False,
            sidecar_value=candidate)
        os.replace(candidate_sidecar, _REMOTE_RECOVERY_FILE)
        candidate_sidecar = None
        argus_persistent_storage._fsync_directory(
            os.path.dirname(os.path.abspath(_REMOTE_RECOVERY_FILE)))
        installed = _resolve_authoritative_local_recovery_checkpoint(
            checkpoint, _OSINT_PERSIST_FILE, configured)
        history = _read_only_remote_recovery_nonce_authority(configured)
        maximum_counter = max(history["keyMaterialCounters"].values())
        if installed["payload"]["sourceCheckpointHash"] != \
                plan["checkpoint"]["sha256"] or maximum_counter <= \
                plan["nonceMaximumCounter"]:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_post_genesis_repair_post_verify_failed")
        return {
            "schemaVersion": _POST_GENESIS_PAIR_REPAIR_RESULT_SCHEMA,
            "status": "REPAIR_APPLIED_KEYED_PAIR_VERIFIED",
            "liveBuildSha": plan["liveBuildSha"],
            "checkpointSha256": plan["checkpoint"]["sha256"],
            "checkpointId": plan["checkpointId"],
            "targetWalSequence": plan["walSequence"],
            "keyId": plan["currentKeyId"],
            "bundleHash": result["bundleHash"],
            "nonceGeneration": history["generation"],
            "nonceMaximumCounter": maximum_counter,
            "forensicBackupDirectory": plan[
                "forensicBackupDirectory"],
        }
    finally:
        if candidate_sidecar is not None:
            try:
                os.unlink(candidate_sidecar)
            except OSError:
                pass
        if candidate_sidecar_lock is not None:
            try:
                os.unlink(candidate_sidecar_lock)
            except OSError:
                pass
        if staging is not None:
            shutil.rmtree(staging, ignore_errors=True)


def _plan_partial_activation_repair(expected):
    """Validate, without mutation, the one owner-gated production repair.

    The returned plan is deliberately non-executable.  It binds a later owner
    action to exact forensic identities while leaving the marker checkpoint,
    legacy quarantine, stable lock inode, nonce authority, and sidecar bytes
    untouched during candidate proof.
    """
    if isinstance(expected, dict) and expected.get("schemaVersion") == \
            _CANONICAL_ABSENT_PARTIAL_ACTIVATION_REPAIR_SCHEMA:
        return _plan_canonical_absent_partial_activation_repair(expected)
    if isinstance(expected, dict) and expected.get("schemaVersion") == \
            _POST_GENESIS_PAIR_REPAIR_SCHEMA:
        return _plan_post_genesis_pair_repair(expected)
    required = {
        "schemaVersion", "buildSha", "currentKeyId", "checkpointId",
        "currentCheckpointSha256", "currentCheckpointBytes",
        "legacyCheckpointPath", "legacyCheckpointSha256",
        "legacyCheckpointBytes", "walSequence", "lockIdentity",
        "writersFenced", "ec2TimerDisabled", "activeRecoveryWriterCount",
        "operationalVerification", "immutableRecoveryPath",
    }
    if not isinstance(expected, dict) or set(expected) != required or \
            expected.get("schemaVersion") != \
            _PARTIAL_ACTIVATION_REPAIR_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_contract_invalid")
    if expected.get("writersFenced") is not True or \
            expected.get("ec2TimerDisabled") is not True or \
            expected.get("activeRecoveryWriterCount") != 0 or \
            expected.get("operationalVerification") is not False:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_fence_unproven")
    build_sha = str(expected.get("buildSha") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", build_sha) or \
            _backend_exact_sha() != build_sha:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_build_mismatch")
    configured = argus_remote_recovery.configured_keys()
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if configured.get("status") != "configured" or not isinstance(
            current, dict) or current.get("keyId") != \
            expected.get("currentKeyId") or not isinstance(
                current.get("key"), bytes) or len(current["key"]) != 32 or \
            configured.get("previous") is not None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_key_mismatch")
    immutable = expected.get("immutableRecoveryPath")
    if not isinstance(immutable, dict) or set(immutable) != {
            "status", "historyQueryStatus", "path", "pinnedCommitSha"} or \
            immutable.get("status") != "absent" or \
            immutable.get("historyQueryStatus") != "never_existed" or \
            immutable.get("path") != _REMOTE_RECOVERY_PATH or not \
            re.fullmatch(
                r"[0-9a-f]{40}",
                str(immutable.get("pinnedCommitSha") or "").lower()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_remote_absence_unproven")

    checkpoint_path = os.path.abspath(_OSINT_PERSIST_FILE)
    legacy_path = os.path.abspath(str(expected.get(
        "legacyCheckpointPath") or ""))
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    if os.path.islink(checkpoint_path) or os.path.islink(legacy_path) or \
            os.path.commonpath((root, os.path.realpath(legacy_path))) != root or \
            legacy_path == checkpoint_path or \
            ".quarantine-" not in os.path.basename(legacy_path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_path_invalid")
    checkpoint_stat = os.stat(checkpoint_path, follow_symlinks=False)
    legacy_stat = os.stat(legacy_path, follow_symlinks=False)
    if not stat.S_ISREG(checkpoint_stat.st_mode) or not \
            stat.S_ISREG(legacy_stat.st_mode):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_artifact_invalid")
    checkpoint_hash = _remote_recovery_file_sha256(checkpoint_path)
    legacy_hash = _remote_recovery_file_sha256(legacy_path)
    if checkpoint_stat.st_size != expected.get("currentCheckpointBytes") or \
            legacy_stat.st_size != expected.get("legacyCheckpointBytes") or \
            not hmac.compare_digest(
                checkpoint_hash,
                str(expected.get("currentCheckpointSha256") or "")) or \
            not hmac.compare_digest(
                legacy_hash,
                str(expected.get("legacyCheckpointSha256") or "")):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_artifact_mismatch")
    current_checkpoint = argus_persistent_storage.load_checkpoint(
        checkpoint_path, require_seal=True)
    legacy_checkpoint = argus_persistent_storage.load_checkpoint(
        legacy_path, require_seal=True)
    marker = _validated_recovery_required_marker(current_checkpoint)
    wal = expected.get("walSequence")
    current_durability = current_checkpoint.get("missionTickDurability")
    legacy_durability = legacy_checkpoint.get("missionTickDurability")
    if isinstance(wal, bool) or not isinstance(wal, int) or wal <= 0 or \
            marker is None or marker.get("keyId") != current["keyId"] or \
            marker.get("checkpointId") != expected.get("checkpointId") or \
            _validated_recovery_required_marker(legacy_checkpoint) is not None or \
            not isinstance(current_durability, dict) or \
            not isinstance(legacy_durability, dict) or \
            current_durability.get("walAppliedSequence") != wal or \
            legacy_durability.get("walAppliedSequence") != wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_checkpoint_state_mismatch")
    if os.path.lexists(_REMOTE_RECOVERY_FILE) or not \
            _remote_recovery_nonce_authority_absent(include_lock=False):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_authority_present")

    lock_path = _DURABILITY_PATHS[
        "recoveryNonceState"] + ".reservation.lock"
    anchor_path = lock_path + ".anchor"
    if not os.path.lexists(lock_path) or os.path.lexists(anchor_path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_partial_repair_lock_state_mismatch")
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(
            _DURABILITY_PATHS["recoveryNonceState"], blocking=False,
            create=False)
        lock_stat = os.fstat(lock_handle.fileno())
        lock_identity = {
            "device": lock_stat.st_dev,
            "inode": lock_stat.st_ino,
            "mode": stat.S_IMODE(lock_stat.st_mode),
            "size": lock_stat.st_size,
            "mtimeNs": lock_stat.st_mtime_ns,
            "ctimeNs": lock_stat.st_ctime_ns,
        }
        if lock_identity != expected.get("lockIdentity") or \
                lock_stat.st_size != 0 or \
                _remote_recovery_nonce_lock_anchor(lock_handle) is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_partial_repair_lock_state_mismatch")
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)

    return {
        "schemaVersion": _PARTIAL_ACTIVATION_REPAIR_SCHEMA,
        "status": "DRY_RUN_PASS",
        "mutationAuthorized": False,
        "buildSha": build_sha,
        "currentKeyId": current["keyId"],
        "currentKeyUnchanged": True,
        "previousKeyAbsent": True,
        "walSequence": wal,
        "nonceReuseRisk": "NONE",
        "forensicArtifacts": [
            {"role": "marker_only_checkpoint", "path": checkpoint_path,
             "sha256": checkpoint_hash, "bytes": checkpoint_stat.st_size},
            {"role": "seal_valid_legacy_checkpoint", "path": legacy_path,
             "sha256": legacy_hash, "bytes": legacy_stat.st_size},
            {"role": "stable_empty_reservation_lock", "path": lock_path,
             **lock_identity},
        ],
        "proposedMutations": [
            "create_immutable_forensic_backup_set",
            "atomically_restore_exact_legacy_checkpoint_to_canonical_path",
            "retain_stable_empty_reservation_lock_inode",
        ],
        "rollback": (
            "atomically_restore_the_exact_marker_checkpoint_backup_before_"
            "any_keyed_nonce_authority_or_sidecar_is_established"),
        "expectedPostRepairState": {
            "canonicalCheckpointSha256": legacy_hash,
            "remoteRecoveryRequired": "absent",
            "sidecar": "absent",
            "nonceAuthority": "absent",
            "reservationLock": "same_empty_inode",
            "walSequence": wal,
        },
    }


def _canonical_absent_artifact_identity(expected, *, role, current_key_id):
    required = {
        "role", "path", "sha256", "bytes", "device", "inode",
        "walSequence", "sealValid", "marker", "checkpointId", "keyId",
    }
    if not isinstance(expected, dict) or set(expected) != required or \
            expected.get("role") != role or expected.get(
                "sealValid") is not True:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_artifact_contract_invalid")
    path = os.path.abspath(str(expected.get("path") or ""))
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    if not path or os.path.islink(path) or \
            os.path.commonpath((root, os.path.realpath(path))) != root or \
            ".quarantine-" not in os.path.basename(path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_artifact_path_invalid")
    before = os.stat(path, follow_symlinks=False)
    if not stat.S_ISREG(before.st_mode) or \
            before.st_dev != expected.get("device") or \
            before.st_ino != expected.get("inode") or \
            before.st_size != expected.get("bytes"):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_artifact_identity_mismatch")
    digest = _remote_recovery_file_sha256(path)
    checkpoint = argus_persistent_storage.load_checkpoint(
        path, require_seal=True)
    after = os.stat(path, follow_symlinks=False)
    if _remote_recovery_file_identity(before) != \
            _remote_recovery_file_identity(after) or not \
            re.fullmatch(r"[0-9a-f]{64}", str(
                expected.get("sha256") or "")) or not hmac.compare_digest(
                    digest, str(expected.get("sha256") or "")):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_artifact_identity_mismatch")
    durability = checkpoint.get("missionTickDurability")
    wal = expected.get("walSequence")
    if isinstance(wal, bool) or not isinstance(wal, int) or wal <= 0 or \
            not isinstance(durability, dict) or \
            durability.get("walAppliedSequence") != wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_artifact_wal_mismatch")
    marker = _validated_recovery_required_marker(checkpoint)
    if role == "legacy_checkpoint":
        if marker is not None or expected.get("marker") != "ABSENT" or \
                expected.get("checkpointId") is not None or \
                expected.get("keyId") is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_legacy_marker_mismatch")
    elif marker is None or expected.get("marker") != "encrypted_required" or \
            marker.get("checkpointId") != expected.get("checkpointId") or \
            marker.get("keyId") != current_key_id or \
            expected.get("keyId") != current_key_id:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_marker_mismatch")
    return {
        "role": role,
        "path": path,
        "sha256": digest,
        "bytes": after.st_size,
        "device": after.st_dev,
        "inode": after.st_ino,
        "walSequence": wal,
        "sealValid": True,
        "marker": expected.get("marker"),
        "checkpointId": expected.get("checkpointId"),
        "keyId": expected.get("keyId"),
    }, checkpoint


def _canonical_absent_competing_legacy_paths(
        checkpoint_path, admitted_paths, wal_sequence):
    directory = os.path.dirname(checkpoint_path)
    prefix = os.path.basename(checkpoint_path) + ".quarantine-"
    competing = []
    with os.scandir(directory) as entries:
        for entry in entries:
            path = os.path.abspath(entry.path)
            if not entry.name.startswith(prefix) or path in admitted_paths:
                continue
            try:
                if entry.is_symlink() or not entry.is_file(
                        follow_symlinks=False):
                    continue
                candidate = argus_persistent_storage.load_checkpoint(
                    path, require_seal=True)
                durability = candidate.get("missionTickDurability")
                if isinstance(durability, dict) and durability.get(
                        "walAppliedSequence") == wal_sequence and \
                        _validated_recovery_required_marker(candidate) is None:
                    competing.append(path)
            except (OSError, ValueError, UnicodeDecodeError,
                    json.JSONDecodeError,
                    argus_persistent_storage.PersistentStorageError,
                    argus_remote_recovery.RecoveryBundleError):
                continue
    return sorted(competing)


def _plan_canonical_absent_partial_activation_repair(expected):
    """Admit only the exact owner-captured canonical-absent Recovery state."""
    required = {
        "schemaVersion", "buildSha", "currentKeyId", "previousKeyAbsent",
        "canonicalPath", "canonicalStatus", "legacyCheckpoint", "markerA",
        "markerB", "lockIdentity", "nonceAuthority", "sidecarStatus",
        "immutableRecoveryPath", "operationalVerification", "writersFenced",
        "activeRecoveryWriterCount", "ec2TimerDisabled", "ec2TimerInactive",
        "remoteReadback", "competingAuthenticatedWalAuthority",
        "forensicBackupDirectory",
    }
    if not isinstance(expected, dict) or set(expected) != required or \
            expected.get("schemaVersion") != \
            _CANONICAL_ABSENT_PARTIAL_ACTIVATION_REPAIR_SCHEMA:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_contract_invalid")
    if expected.get("previousKeyAbsent") is not True or \
            expected.get("canonicalStatus") != "ABSENT" or \
            expected.get("writersFenced") is not True or \
            expected.get("activeRecoveryWriterCount") != 0 or \
            expected.get("ec2TimerDisabled") is not True or \
            expected.get("ec2TimerInactive") is not True or \
            expected.get("operationalVerification") is not False or \
            expected.get("sidecarStatus") != "ABSENT" or \
            expected.get("competingAuthenticatedWalAuthority") is not False:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_fence_unproven")
    build_sha = str(expected.get("buildSha") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{40}", build_sha) or \
            _backend_exact_sha() != build_sha:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_build_mismatch")
    configured = argus_remote_recovery.configured_keys()
    current = configured.get("current") if isinstance(configured, dict) \
        else None
    if configured.get("status") != "configured" or not isinstance(
            current, dict) or current.get("keyId") != expected.get(
                "currentKeyId") or not isinstance(current.get("key"), bytes) or \
            len(current["key"]) != 32 or configured.get("previous") is not None:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_key_mismatch")

    checkpoint_path = os.path.abspath(_OSINT_PERSIST_FILE)
    if os.path.abspath(str(expected.get("canonicalPath") or "")) != \
            checkpoint_path or os.path.lexists(checkpoint_path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_checkpoint_present")
    artifacts = []
    for field, role in (("legacyCheckpoint", "legacy_checkpoint"),
                        ("markerA", "marker_a"),
                        ("markerB", "marker_b")):
        identity, _checkpoint = _canonical_absent_artifact_identity(
            expected.get(field), role=role,
            current_key_id=current["keyId"])
        artifacts.append(identity)
    if len({row["path"] for row in artifacts}) != 3 or len(
            {row["checkpointId"] for row in artifacts[1:]}) != 2 or len(
                {row["sha256"] for row in artifacts}) != 3:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_lineage_ambiguous")
    wal = artifacts[0]["walSequence"]
    if any(row["walSequence"] != wal for row in artifacts[1:]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_wal_mismatch")

    nonce = expected.get("nonceAuthority")
    if not isinstance(nonce, dict) or set(nonce) != {
            "history", "state", "head", "anchor"} or any(
                value != "ABSENT" for value in nonce.values()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_nonce_contract_invalid")
    nonce_paths = _remote_recovery_nonce_paths()
    lock_path = _DURABILITY_PATHS[
        "recoveryNonceState"] + ".reservation.lock"
    anchor_path = lock_path + ".anchor"
    if any(os.path.lexists(path) for path in (
            nonce_paths["history"], nonce_paths["state"],
            nonce_paths["head"], anchor_path)) or \
            os.path.lexists(_REMOTE_RECOVERY_FILE):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_authority_present")

    lock_expected = expected.get("lockIdentity")
    lock_required = {
        "path", "device", "inode", "mode", "size", "mtimeNs", "ctimeNs",
        "holder",
    }
    if not isinstance(lock_expected, dict) or set(lock_expected) != \
            lock_required or os.path.abspath(str(
                lock_expected.get("path") or "")) != lock_path or \
            lock_expected.get("holder") != "NONE" or \
            lock_expected.get("size") != 0 or not os.path.lexists(lock_path) or \
            os.path.islink(lock_path):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_lock_contract_invalid")
    lock_handle = None
    try:
        lock_handle = _acquire_remote_recovery_nonce_lock(
            _DURABILITY_PATHS["recoveryNonceState"], blocking=False,
            create=False)
        lock_stat = os.fstat(lock_handle.fileno())
        lock_identity = {
            "path": lock_path,
            "device": lock_stat.st_dev,
            "inode": lock_stat.st_ino,
            "mode": stat.S_IMODE(lock_stat.st_mode),
            "size": lock_stat.st_size,
            "mtimeNs": lock_stat.st_mtime_ns,
            "ctimeNs": lock_stat.st_ctime_ns,
            "holder": "NONE",
        }
        if lock_identity != lock_expected or \
                _remote_recovery_nonce_lock_anchor(lock_handle) is not None:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_lock_identity_mismatch")
    finally:
        _release_remote_recovery_nonce_lock(lock_handle)

    immutable = expected.get("immutableRecoveryPath")
    if not isinstance(immutable, dict) or set(immutable) != {
            "status", "historyQueryStatus", "path", "pinnedCommitSha"} or \
            immutable.get("status") != "absent" or \
            immutable.get("historyQueryStatus") != "never_existed" or \
            immutable.get("path") != _REMOTE_RECOVERY_PATH or not \
            re.fullmatch(r"[0-9a-f]{40}", str(
                immutable.get("pinnedCommitSha") or "").lower()):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_remote_absence_unproven")
    readback = expected.get("remoteReadback")
    if not isinstance(readback, dict) or set(readback) != {
            "status", "walSequence", "recoveryStatus", "pinnedCommitSha"} or \
            readback.get("status") != "VERIFIED" or \
            readback.get("recoveryStatus") != "ABSENT" or \
            readback.get("pinnedCommitSha") != immutable.get(
                "pinnedCommitSha") or isinstance(
                    readback.get("walSequence"), bool) or not isinstance(
                        readback.get("walSequence"), int) or \
            readback.get("walSequence") <= 0 or \
            readback.get("walSequence") >= wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_remote_readback_invalid")
    admitted_paths = {row["path"] for row in artifacts}
    if _canonical_absent_competing_legacy_paths(
            checkpoint_path, admitted_paths, wal):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_competing_legacy_authority")

    backup_directory = os.path.abspath(str(
        expected.get("forensicBackupDirectory") or ""))
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    if os.path.commonpath((root, os.path.realpath(backup_directory))) != root or \
            os.path.dirname(backup_directory) != root or \
            not os.path.basename(backup_directory).startswith(
                "argus-recovery-forensic-") or \
            os.path.lexists(backup_directory):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_backup_path_invalid")
    return {
        "schemaVersion":
            _CANONICAL_ABSENT_PARTIAL_ACTIVATION_REPAIR_SCHEMA,
        "stateMode": "PARTIAL_ACTIVATION_CANONICAL_ABSENT",
        "status": "DRY_RUN_PASS",
        "mutationAuthorized": False,
        "buildSha": build_sha,
        "currentKeyId": current["keyId"],
        "currentKeyUnchanged": True,
        "previousKeyAbsent": True,
        "canonicalCheckpoint": "ABSENT",
        "walSequence": wal,
        "remoteReadbackWalSequence": readback["walSequence"],
        "remoteReadbackLag": wal - readback["walSequence"],
        "remoteReadbackDecision": "PRESERVE_LOCAL_NO_DOWNGRADE",
        "noCompetingAuthenticatedWalAuthority": True,
        "nonceReuseRisk": "NONE",
        "forensicBackupDirectory": backup_directory,
        "forensicArtifacts": artifacts + [{**lock_identity,
                                             "role": "reservation_lock"}],
        "proposedMutations": [
            "create_integrity_verified_forensic_backup_set",
            "atomically_restore_exact_legacy_checkpoint_to_canonical_path",
            "preserve_marker_a_and_marker_b_quarantines",
            "retain_stable_empty_reservation_lock_inode",
        ],
        "rollbackBoundary": (
            "remove_only_the_exact_restored_canonical_before_any_nonce_"
            "authority_or_authenticated_sidecar_pair_exists"),
        "expectedPostRepairState": {
            "canonicalCheckpointSha256": artifacts[0]["sha256"],
            "remoteRecoveryRequired": "ABSENT",
            "markerA": "PRESERVED",
            "markerB": "PRESERVED",
            "sidecar": "ABSENT",
            "nonceAuthority": "ABSENT_BEFORE_GENESIS",
            "reservationLock": "SAME_EMPTY_INODE",
            "walSequence": wal,
        },
    }


def _write_canonical_absent_forensic_copy(source, destination, expected):
    descriptor = os.open(
        destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
        getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        with open(source, "rb") as reader, os.fdopen(
                descriptor, "wb", buffering=0) as writer:
            descriptor = None
            shutil.copyfileobj(reader, writer, length=1024 * 1024)
            os.fsync(writer.fileno())
    finally:
        if descriptor is not None:
            os.close(descriptor)
    if os.path.getsize(destination) != expected["bytes"] or not \
            hmac.compare_digest(
                _remote_recovery_file_sha256(destination),
                expected["sha256"]):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_canonical_absent_backup_verification_failed")


def _execute_canonical_absent_partial_activation_repair(
        expected, *, execute=False):
    """Apply the owner-gated repair only after two exact-state recaptures.

    Production callers must pass ``execute=True`` explicitly.  The default is
    the mutation-free planner.  This function never creates nonce authority or
    an encrypted sidecar; corrected genesis remains a later normal boot step.
    """
    plan = _plan_canonical_absent_partial_activation_repair(expected)
    if execute is not True:
        return plan
    root = os.path.realpath(_DURABILITY_PATHS["root"])
    canonical = os.path.abspath(_OSINT_PERSIST_FILE)
    legacy = plan["forensicArtifacts"][0]
    backup_directory = plan["forensicBackupDirectory"]
    staging = tempfile.mkdtemp(
        prefix=".argus-recovery-forensic-staging-", dir=root)
    restore_temp = None
    canonical_installed = False
    try:
        backup_rows = []
        for artifact, name in zip(
                plan["forensicArtifacts"][:3],
                ("legacy-checkpoint.json", "marker-a.json", "marker-b.json")):
            destination = os.path.join(staging, name)
            _write_canonical_absent_forensic_copy(
                artifact["path"], destination, artifact)
            backup_rows.append({
                "role": artifact["role"],
                "sourcePath": artifact["path"],
                "backupFile": name,
                "sha256": artifact["sha256"],
                "bytes": artifact["bytes"],
                "device": artifact["device"],
                "inode": artifact["inode"],
            })
        manifest = {
            "schemaVersion":
                "argus-recovery-canonical-absent-forensic-backup-v1",
            "buildSha": plan["buildSha"],
            "currentKeyId": plan["currentKeyId"],
            "previousKeyAbsent": True,
            "canonicalInitialState": "ABSENT",
            "walSequence": plan["walSequence"],
            "remoteReadbackWalSequence": plan[
                "remoteReadbackWalSequence"],
            "remoteReadbackDecision": plan["remoteReadbackDecision"],
            "artifacts": backup_rows,
            "reservationLock": plan["forensicArtifacts"][3],
            "nonceAuthority": "ABSENT",
            "sidecar": "ABSENT",
            "immutableEncryptedRecovery": "ABSENT",
            "operationalVerification": False,
            "writersFenced": True,
            "activeRecoveryWriterCount": 0,
            "ec2TimerDisabled": True,
            "ec2TimerInactive": True,
        }
        manifest_path = os.path.join(staging, "manifest.json")
        descriptor = os.open(
            manifest_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
            getattr(os, "O_NOFOLLOW", 0), 0o600)
        try:
            with os.fdopen(descriptor, "wb", buffering=0) as handle:
                descriptor = None
                handle.write(json.dumps(
                    manifest, ensure_ascii=False, sort_keys=True,
                    separators=(",", ":")).encode("utf-8"))
                os.fsync(handle.fileno())
        finally:
            if descriptor is not None:
                os.close(descriptor)
        manifest_digest = _remote_recovery_file_sha256(manifest_path)
        digest_path = os.path.join(staging, "manifest.sha256")
        descriptor = os.open(
            digest_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL |
            getattr(os, "O_NOFOLLOW", 0), 0o600)
        try:
            with os.fdopen(descriptor, "wb", buffering=0) as handle:
                descriptor = None
                handle.write((manifest_digest + "  manifest.json\n").encode(
                    "ascii"))
                os.fsync(handle.fileno())
        finally:
            if descriptor is not None:
                os.close(descriptor)
        argus_persistent_storage._fsync_directory(staging)

        # Re-capture every predicate after the potentially long forensic copy
        # and before the first authoritative mutation.
        _plan_canonical_absent_partial_activation_repair(expected)
        os.replace(staging, backup_directory)
        staging = None
        argus_persistent_storage._fsync_directory(root)

        descriptor, restore_temp = tempfile.mkstemp(
            prefix=".argus-recovery-canonical-restore-", dir=root)
        try:
            os.fchmod(descriptor, 0o600)
            with open(legacy["path"], "rb") as reader, os.fdopen(
                    descriptor, "wb", buffering=0) as writer:
                descriptor = None
                shutil.copyfileobj(reader, writer, length=1024 * 1024)
                os.fsync(writer.fileno())
        finally:
            if descriptor is not None:
                os.close(descriptor)
        if os.path.getsize(restore_temp) != legacy["bytes"] or not \
                hmac.compare_digest(
                    _remote_recovery_file_sha256(restore_temp),
                    legacy["sha256"]):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_restore_staging_mismatch")
        staged = argus_persistent_storage.load_checkpoint(
            restore_temp, require_seal=True)
        if _validated_recovery_required_marker(staged) is not None or \
                os.path.lexists(canonical):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_state_changed_before_restore")
        os.replace(restore_temp, canonical)
        restore_temp = None
        canonical_installed = True
        argus_persistent_storage._fsync_directory(root)
        restored = argus_persistent_storage.load_checkpoint(
            canonical, require_seal=True)
        if not hmac.compare_digest(
                _remote_recovery_file_sha256(canonical), legacy["sha256"]) or \
                _validated_recovery_required_marker(restored) is not None or \
                (restored.get("missionTickDurability") or {}).get(
                    "walAppliedSequence") != plan["walSequence"]:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_post_restore_invalid")
        for artifact in plan["forensicArtifacts"][1:3]:
            metadata = os.stat(artifact["path"], follow_symlinks=False)
            if metadata.st_dev != artifact["device"] or \
                    metadata.st_ino != artifact["inode"] or \
                    metadata.st_size != artifact["bytes"] or not \
                    hmac.compare_digest(
                        _remote_recovery_file_sha256(artifact["path"]),
                        artifact["sha256"]):
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_canonical_absent_forensic_artifact_changed")
        lock = plan["forensicArtifacts"][3]
        lock_stat = os.stat(lock["path"], follow_symlinks=False)
        if (lock_stat.st_dev, lock_stat.st_ino, lock_stat.st_size) != (
                lock["device"], lock["inode"], 0):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_lock_changed")
        if os.path.lexists(_REMOTE_RECOVERY_FILE) or not \
                _remote_recovery_nonce_authority_absent(include_lock=False):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_canonical_absent_keyed_authority_race")
        return {
            "schemaVersion": _CANONICAL_ABSENT_REPAIR_RESULT_SCHEMA,
            "status": "REPAIR_APPLIED_PRE_GENESIS",
            "buildSha": plan["buildSha"],
            "canonicalCheckpointSha256": legacy["sha256"],
            "walSequence": plan["walSequence"],
            "forensicBackupDirectory": backup_directory,
            "markerA": "PRESERVED",
            "markerB": "PRESERVED",
            "reservationLock": "SAME_EMPTY_INODE",
            "nonceAuthority": "ABSENT_BEFORE_GENESIS",
            "sidecar": "ABSENT_BEFORE_GENESIS",
            "rollbackBoundary": plan["rollbackBoundary"],
        }
    except Exception as exc:
        if canonical_installed:
            keyed_authority = os.path.lexists(_REMOTE_RECOVERY_FILE) or not \
                _remote_recovery_nonce_authority_absent(include_lock=False)
            if keyed_authority:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_canonical_absent_rollback_blocked_keyed_authority"
                ) from exc
            try:
                if os.path.isfile(canonical) and hmac.compare_digest(
                        _remote_recovery_file_sha256(canonical),
                        legacy["sha256"]):
                    os.unlink(canonical)
                    argus_persistent_storage._fsync_directory(root)
                else:
                    raise OSError("canonical_identity_changed")
            except Exception as rollback_exc:
                raise argus_remote_recovery.RecoveryBundleError(
                    "recovery_canonical_absent_rollback_failed") \
                    from rollback_exc
        raise
    finally:
        if restore_temp is not None:
            try:
                os.unlink(restore_temp)
            except OSError:
                pass
        if staging is not None:
            shutil.rmtree(staging, ignore_errors=True)


def _validated_local_recovery_pair(evidence, checkpoint_blob, configured):
    """Validate a process-private local pair handed off by exact restore."""
    if not isinstance(evidence, _AuthenticatedLocalRecoveryPair) or \
            evidence._token is not _LOCAL_RECOVERY_PAIR_PROCESS_TOKEN or not \
            isinstance(checkpoint_blob, dict):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_invalid")
    selected = evidence._selected
    available = [candidate for candidate in (
        configured.get("current"), configured.get("previous"))
        if isinstance(candidate, dict)] if isinstance(configured, dict) else []
    if not isinstance(selected, dict) or not any(
            candidate.get("keyId") == selected.get("keyId") and
            isinstance(candidate.get("key"), bytes) and
            isinstance(selected.get("key"), bytes) and
            hmac.compare_digest(candidate["key"], selected["key"])
            for candidate in available):
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_key_unavailable")
    payload = argus_remote_recovery.validate_pair(
        evidence._readback, evidence._envelope,
        selected["key"], key_identifier=selected["keyId"])
    if payload != evidence._payload:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_changed")
    target_wal = payload["targetWalSequence"]
    durability = checkpoint_blob.get("missionTickDurability")
    if not isinstance(durability, dict) or durability.get(
            "walAppliedSequence") != target_wal:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_wal_mismatch")
    exported_durability = copy.deepcopy(durability)
    exported_durability["remoteWalAppliedSequence"] = target_wal
    if _checkpoint_recovery_targets(
            checkpoint_blob, exported_durability) != payload["targets"]:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_target_mismatch")
    provenance = checkpoint_blob.get("remoteRecoveryProvenance")
    if not isinstance(provenance, dict) or provenance.get(
            "targetWalSequence") != target_wal or provenance.get(
                "ledgerBaseCommitSha") != payload["ledgerBaseCommitSha"]:
        raise argus_remote_recovery.RecoveryBundleError(
            "recovery_local_evidence_provenance_invalid")
    return evidence


def _local_recovery_pair_has_pinned_provenance(
        local_evidence, remote_evidence, pinned_ledger):
    """Prove local authenticated base is on the already-pinned ledger line."""
    local_base = local_evidence._payload["ledgerBaseCommitSha"]
    ledger_commit = local_evidence._ledger_commit
    # A checkpoint-derived commit is stronger corroborating evidence when it
    # exists and must keep matching the authenticated sidecar base exactly.
    # Some already-keyed checkpoints predate that durable projection, however,
    # so absence alone cannot outrank the sidecar's authenticated base.  In
    # that narrow case the complete bounded ancestry proof below remains the
    # provenance authority; every pair/key/checkpoint/WAL predicate has already
    # been revalidated by the selector before this helper is reached.
    if ledger_commit is not None and ledger_commit != local_base:
        return False
    if isinstance(remote_evidence, _AuthenticatedPinnedRemoteRecoveryEvidence) \
            and local_base == remote_evidence._payload[
                "ledgerBaseCommitSha"]:
        return True
    try:
        _verify_authenticated_ledger_commit_path(
            local_base, pinned_ledger["commitSha"],
            owner=pinned_ledger["owner"],
            repository=pinned_ledger["repository"])
        return True
    except argus_remote_recovery.RecoveryBundleError:
        return False


def _select_keyed_recovery_boot_authority(
        checkpoint_blob, local_evidence, remote_evidence, pinned_ledger,
        configured, *, restore_token=None):
    """Deterministically select local or exact pinned authority by WAL target."""
    local = _validated_local_recovery_pair(
        local_evidence, checkpoint_blob, configured)
    if isinstance(remote_evidence, _AuthenticatedPinnedLegacyReadbackEvidence):
        legacy = _validated_pinned_legacy_readback_evidence(
            remote_evidence, pinned_ledger, restore_token=restore_token)
        if not _local_recovery_pair_has_pinned_provenance(
                local, legacy, pinned_ledger):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_local_authority_provenance_invalid")
        local_wal = local._payload["targetWalSequence"]
        legacy_wal = (legacy._readback.get(
            "missionTickDurability") or {}).get("walAppliedSequence")
        if legacy_wal > local_wal:
            # The current immutable public ledger is ahead, but it has no
            # encrypted private target map.  Never resurrect the older local
            # checkpoint or fall back to the plaintext full snapshot.
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_pinned_legacy_newer_than_local")
        if legacy_wal == local_wal and legacy._readback.get(
                "receiptHash") != local._payload.get("compactReceiptHash"):
            # Same-WAL, different compact identities are split-brain evidence;
            # neither timestamp nor local availability breaks the tie.
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_pinned_legacy_receipt_mismatch")
        return "local"
    remote = _validated_pinned_remote_recovery_evidence(
        remote_evidence, pinned_ledger, configured)
    local_wal = local._payload["targetWalSequence"]
    remote_wal = remote._payload["targetWalSequence"]
    if remote_wal > local_wal:
        return "remote"
    coherent = _local_recovery_pair_has_pinned_provenance(
        local, remote, pinned_ledger)
    if local_wal > remote_wal:
        if not coherent:
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_local_authority_provenance_invalid")
        return "local"
    if not coherent:
        return "remote"
    # At one WAL target, prefer local only for the exact same authenticated
    # recovery state.  Different same-sequence bodies are split-brain evidence;
    # the immutable remote pair wins deterministically.
    if local._payload["targetStateHash"] == remote._payload[
            "targetStateHash"] and local._payload["targets"] == \
            remote._payload["targets"] and local._payload[
                "compactReceiptHash"] == remote._payload[
                    "compactReceiptHash"]:
        return "local"
    return "remote"


def _overlay_remote_recovery(
        full_blob, pinned_base, pinned_commit_sha, *,
        ledger_owner=None, ledger_repository=None,
        nonce_floor_handoff=None, authenticated_pinned_evidence=None):
    """Overlay a verified bounded recovery bundle onto a verified full blob.

    A missing bundle preserves the legacy full-only bootstrap contract.  Once
    the recovery object exists, every transport, size, JSON, and proof error is
    terminal for this remote bootstrap: falling back to the older full object
    could resurrect state behind an already acknowledged WAL cursor.
    """
    try:
        if nonce_floor_handoff is not None and (
                not isinstance(nonce_floor_handoff, list) or
                nonce_floor_handoff):
            raise argus_remote_recovery.RecoveryBundleError(
                "recovery_nonce_bootstrap_handoff_invalid")
        configured = argus_remote_recovery.configured_keys()
        if ledger_owner is None or ledger_repository is None:
            ledger_owner, ledger_repository = \
                _github_ledger_repository(pinned_base)
        if authenticated_pinned_evidence is not None:
            if configured.get("status") != "configured":
                _remote_recovery_restore_failure(
                    "recovery_key_not_configured")
            evidence = _validated_pinned_remote_recovery_evidence(
                authenticated_pinned_evidence, {
                    "base": pinned_base, "commitSha": pinned_commit_sha,
                    "owner": ledger_owner, "repository": ledger_repository,
                }, configured)
            readback = evidence._readback
            bundle = evidence._envelope
            selected = evidence._selected
            authenticated_payload = evidence._payload
            ancestry = evidence._ancestry
            authenticated_nonce_authority = evidence
        else:
            readback_result = _fetch_pinned_recovery_object(
                f"{pinned_base}{_REMOTE_READBACK_PATH}",
                _DURABLE_READBACK_MAX_BYTES, "readback")
            recovery_result = _fetch_pinned_recovery_object(
                f"{pinned_base}{_REMOTE_RECOVERY_PATH}",
                _DURABLE_RECOVERY_MAX_BYTES, "recovery")

            if recovery_result["status"] == "absent":
                if configured.get("status") == "not_configured":
                    status = "absent_legacy_full_only"
                else:
                    _remote_recovery_restore_failure(
                        "remote_recovery_missing_for_readback")
                _DURABLE_STATE["remoteRecoveryOverlay"] = {"status": status}
                return full_blob

            if recovery_result["status"] != "present":
                _remote_recovery_restore_failure(
                    f"remote_recovery_{recovery_result['status']}")
            if configured.get("status") != "configured":
                _remote_recovery_restore_failure(
                    "recovery_key_not_configured")
            if readback_result["status"] != "present":
                _remote_recovery_restore_failure(
                    f"remote_recovery_pair_readback_"
                    f"{readback_result['status']}")

            remote_sidecar = recovery_result["value"]
            readback = readback_result["value"]
            if not isinstance(remote_sidecar, dict) or remote_sidecar.get(
                    "schemaVersion") != argus_remote_recovery.SIDECAR_SCHEMA:
                _remote_recovery_restore_failure("recovery_sidecar_required")
            sidecar = argus_remote_recovery.validate_sidecar(remote_sidecar)
            if sidecar["readback"] != readback:
                _remote_recovery_restore_failure(
                    "recovery_pair_readback_mismatch")
            bundle = sidecar["recovery"]
            selected = _recovery_key_for_envelope(bundle, configured)
            authenticated_payload = argus_remote_recovery.validate_pair(
                readback, bundle, selected["key"],
                key_identifier=selected["keyId"])
            ancestry = _verify_authenticated_ledger_commit_path(
                authenticated_payload["ledgerBaseCommitSha"],
                pinned_commit_sha, owner=ledger_owner,
                repository=ledger_repository)
            authenticated_nonce_authority = \
                _authenticated_remote_recovery_nonce_authority(
                    bundle, authenticated_payload, configured, selected)
        merged = argus_remote_recovery.overlay_verified_bundle(
            full_blob, bundle, selected["key"],
            key_identifier=selected["keyId"],
            ledger_commit_sha=pinned_commit_sha)
        # These compact hashes describe the producer checkpoint, but their
        # corresponding large state bodies are intentionally outside the
        # recovery payload.  Keep each stale full body paired with its own
        # hash; applying only a newer hash would manufacture a false verified
        # body/hash pair.
        merged["remoteRecoveryRequired"] = {
            "schemaVersion": argus_remote_recovery.SIDECAR_SCHEMA,
            "mode": "encrypted_required",
            # A remote bundle may legitimately decrypt with the previous key.
            # The newly sealed local checkpoint is paired below with a freshly
            # encrypted sidecar, which always uses current.
            "keyId": configured["current"]["keyId"],
            "checkpointId": f"rcp-{os.urandom(16).hex()}",
        }
        provenance = merged.get("remoteRecoveryProvenance") or {}
        provenance.update({
            "keyId": bundle.get("keyId"),
            "generationId": bundle.get("generationId"),
            "ledgerBaseCommitSha": bundle.get("ledgerBaseCommitSha"),
            "ledgerCommitDistance": ancestry["distance"],
            "readbackReceiptHash": readback.get("receiptHash"),
            "restoreKind": "pinned_remote_pair",
            "walAllocatorFloor": bundle.get("targetWalSequence"),
        })
        merged["remoteRecoveryProvenance"] = provenance
        restored_at = _ai_now_iso()
        manifest_hash = (readback.get("integrityManifest") or {}).get(
            "manifestHash")
        events = readback.get("opsJournal") or []
        outcomes = readback.get("outcomes") or []
        merged["remoteJournalCycle"] = {
            **copy.deepcopy(merged.get("remoteJournalCycle") or {}),
            "remoteCommitSha": pinned_commit_sha,
            "committedAt": readback.get("generatedAt") or readback.get("asOf"),
            "readBackAt": restored_at,
            "readBackVerified": True,
            "walReadBackVerified": True,
            "expectedHash": manifest_hash,
            "actualHash": manifest_hash,
            "remoteWalAppliedSequence": bundle.get("targetWalSequence"),
            "verifiedWalSequence": bundle.get("targetWalSequence"),
            "compactReceiptHash": readback.get("receiptHash"),
            "pendingCount": 0,
            "acknowledgedCount": len(events),
            "remoteDurabilityState": "verified",
            "receiptCommitSha": pinned_commit_sha,
            "receiptCreatedAt": readback.get("generatedAt") or
            readback.get("asOf"),
            "receiptVerifiedAt": restored_at,
            "receiptAgeSeconds": 0,
            "receiptAttempts": 1,
            "receiptErrorClass": None,
            "errorClass": None,
            "walErrorClass": None,
        }
        merged["remoteAck"] = {
            **copy.deepcopy(merged.get("remoteAck") or {}),
            "ackedKeys": [str(row.get("idempotencyKey")) for row in events
                           if row.get("idempotencyKey")][-800:],
            "lastVerifiedRemoteAckAt": restored_at if events else None,
            "lastReceiptStatus": "verified",
            "remoteGeneratedAt": readback.get("generatedAt") or
            readback.get("asOf"),
            "legacyRemote": False,
            "readbackFailures": 0,
            "outcomeAckedIds": [str(row.get("id")) for row in outcomes
                                if row.get("id")][-400:],
            "lastVerifiedOutcomeReadBackAt": (
                restored_at if outcomes else None),
        }
        target_wal = bundle.get("targetWalSequence")
        # The pinned envelope has passed exact-pair AES-GCM authentication.
        # Atomically import every carried material-domain counter before the
        # new local checkpoint or current-key ciphertext can become
        # authoritative.  Only this process-private capability crosses into
        # the producer; no domain/counter enters restored public state.
        _seed_authenticated_remote_recovery_nonce_authority(
            authenticated_nonce_authority, configured)
        if nonce_floor_handoff is not None:
            nonce_floor_handoff.append(authenticated_nonce_authority)
        _DURABLE_STATE["remoteRecoveryOverlay"] = {
            "status": "verified",
            "schemaVersion": bundle.get("schemaVersion"),
            "targetWalSequence": target_wal,
            "ledgerCommitSha": pinned_commit_sha,
            "keyId": bundle.get("keyId"),
        }
        _DURABLE_STATE.pop("remoteRecoveryError", None)
        return merged
    except argus_remote_recovery.RecoveryBundleError as exc:
        _remote_recovery_restore_failure(exc.classification)


_RESTORE_TRANSACTION_GLOBALS = (
    "_OSINT_TERM_OVERLAY", "_OSINT_MEMORY", "_OSINT_URL_CACHE",
    "_OSINT_CANARY_LAST", "_OSINT_RPS_HISTORY", "_OSINT_BASELINE_RUNS",
    "_OSINT_BENCHMARK_RUNS", "_FORMAL_BENCHMARK",
    "_FORMAL_BENCHMARK_V2", "_FOUNDATION_JOBS", "_SOAK_HISTORY",
    "_SOAK_CONTROL", "_CHECKPOINT_V2_STAGE1_CONTROL", "_STARTUP", "_SOAK",
    "_MISSIONS", "_MISSION_WINDOWS", "_FORECAST_LEDGER",
    "_OUTCOME_LEDGER", "_INCIDENTS", "_POSTMORTEMS",
    "_PERIODIC_REPORTS", "_CHALLENGER_RUNS", "_OSINT_AGENT_QUEUE",
    "_COST_POLICY", "_MARKET_LEDGER", "_CHART_INTELLIGENCE",
    "_TODAY_INTELLIGENCE", "_MARKET_REPLAY", "_VERIFIED_VIEW_SNAPSHOTS",
    "_ASSET_CHART_REPORTS", "_OPS_JOURNAL", "_OPS_JOURNAL_META",
    "_OPS_JOURNAL_COMPACT", "_OPS_SEQ", "_REMOTE_ACK", "_REMOTE_CYCLE",
    "_MISSION_BATCH_STATE", "_REMOTE_RECEIPT_QUEUE", "_DURABLE_STATE",
)


def _restore_transaction_snapshot():
    return {name: copy.deepcopy(globals()[name])
            for name in _RESTORE_TRANSACTION_GLOBALS}


def _restore_transaction_rollback(snapshot):
    for name, saved in snapshot.items():
        current = globals().get(name)
        if isinstance(current, list) and isinstance(saved, list):
            current[:] = saved
        elif isinstance(current, dict) and isinstance(saved, dict):
            current.clear()
            current.update(saved)
        else:
            globals()[name] = saved


def _rollback_remote_recovery_wal_floor(change):
    """Undo only the exact cold-recovery anchor appended by this restore."""
    if not isinstance(change, dict) or change.get("appended") is not True:
        return True
    path = _MISSION_WAL_FILE
    before_bytes = int(change.get("beforeBytes") or 0)
    after_bytes = int(change.get("afterBytes") or 0)
    try:
        if not os.path.isfile(path) or os.path.getsize(path) != after_bytes:
            raise OSError("recovery_wal_changed_before_rollback")
        state = argus_tick_durability.read_valid_wal(path)
        matches = [row for row in (state.get("records") or [])
                   if row.get("recordHash") == change.get("anchorHash") and
                   int(row.get("sequence") or 0) ==
                   int(change.get("targetWalSequence") or 0)]
        if int(state.get("corruptCount") or 0) != 0 or len(matches) != 1 or \
                int(state.get("maximumSequence") or 0) != int(
                    change.get("targetWalSequence") or 0):
            raise OSError("recovery_wal_anchor_not_exclusive")
        if change.get("beforeExists") is True:
            with open(path, "r+b") as handle:
                handle.truncate(before_bytes)
                handle.flush()
                os.fsync(handle.fileno())
        else:
            os.unlink(path)
        argus_persistent_storage._fsync_directory(
            os.path.dirname(os.path.abspath(path)))
        if change.get("beforeExists") is True:
            restored = argus_tick_durability.read_valid_wal(path)
            if int(restored.get("bytes") or 0) != before_bytes or \
                    int(restored.get("corruptCount") or 0) != 0 or \
                    int(restored.get("maximumSequence") or 0) != int(
                        change.get("beforeMaximum") or 0):
                raise OSError("recovery_wal_rollback_readback_failed")
        elif os.path.exists(path):
            raise OSError("recovery_wal_rollback_unlink_failed")
        return True
    except Exception as exc:
        raise _RemoteRecoveryRestoreError(
            "recovery_wal_floor_rollback_failed") from exc


def _seed_remote_recovery_wal_floor(blob):
    """Materialize an authenticated allocator floor on a cold empty disk."""
    provenance = blob.get("remoteRecoveryProvenance")
    if not isinstance(provenance, dict):
        return None
    target = provenance.get("targetWalSequence")
    durability = blob.get("missionTickDurability") or {}
    if isinstance(target, bool) or not isinstance(target, int) or target <= 0 or \
            durability.get("walAppliedSequence") != target:
        raise _RemoteRecoveryRestoreError("recovery_wal_floor_invalid")
    state = argus_tick_durability.read_valid_wal(_MISSION_WAL_FILE)
    sequences = [int(row.get("sequence") or 0)
                 for row in (state.get("records") or [])]
    if int(state.get("corruptCount") or 0) != 0 or \
            len(sequences) != len(set(sequences)):
        raise _RemoteRecoveryRestoreError("recovery_wal_floor_corrupt")
    maximum = int(state.get("maximumSequence") or 0)
    anchor_hash = None
    change = {
        "appended": False,
        "targetWalSequence": target,
        "allocatorFloor": maximum,
    }
    if maximum < target:
        receipt_hash = str(provenance.get("compactReceiptHash") or "")
        bundle_hash = str(provenance.get("bundleHash") or "")
        if not re.fullmatch(r"[0-9a-f]{16}", receipt_hash) or not \
                re.fullmatch(r"[0-9a-f]{64}", bundle_hash):
            raise _RemoteRecoveryRestoreError("recovery_wal_floor_proof_invalid")
        change.update({
            "beforeExists": os.path.exists(_MISSION_WAL_FILE),
            "beforeBytes": int(state.get("bytes") or 0),
            "beforeMaximum": maximum,
        })
        try:
            anchor = argus_tick_durability.append_wal(
                _MISSION_WAL_FILE, sequence=target, kind="checkpoint_verified",
                payload={
                    "schemaVersion": "argus-cold-recovery-anchor-v1",
                    "includedWalSequence": target,
                    "compactReceiptHash": receipt_hash,
                    "bundleHash": bundle_hash,
                    "ledgerCommitSha": provenance.get("ledgerCommitSha"),
                },
                job_id="cold-recovery",
                transition_id=f"cold-recovery:{bundle_hash}:{target}",
                occurred_at=str(provenance.get("checkpointVerifiedAt") or
                                _ai_now_iso()),
                build_sha=(provenance.get("buildIdentity") or {}).get(
                    "buildSha"),
            )
            anchor_hash = anchor.get("recordHash")
            change.update({
                "appended": True,
                "anchorHash": anchor_hash,
                "afterBytes": os.path.getsize(_MISSION_WAL_FILE),
            })
            state = argus_tick_durability.read_valid_wal(_MISSION_WAL_FILE)
            maximum = int(state.get("maximumSequence") or 0)
            matches = [row for row in (state.get("records") or [])
                       if int(row.get("sequence") or 0) == target and
                       row.get("recordHash") == anchor_hash]
            if len(matches) != 1:
                raise _RemoteRecoveryRestoreError(
                    "recovery_wal_floor_readback_failed")
        except Exception:
            # ``append_wal`` fsyncs the record before fsyncing its parent.  If
            # that final durability call raises, the append can exist even
            # though the helper did not return its record.  Detect only our
            # exact transition and restore the prior byte boundary.
            if change.get("appended") is not True and os.path.isfile(
                    _MISSION_WAL_FILE) and os.path.getsize(
                        _MISSION_WAL_FILE) > change["beforeBytes"]:
                partial = argus_tick_durability.read_valid_wal(
                    _MISSION_WAL_FILE)
                expected_transition = f"cold-recovery:{bundle_hash}:{target}"
                matches = [row for row in (partial.get("records") or [])
                           if row.get("transitionId") == expected_transition and
                           int(row.get("sequence") or 0) == target]
                if len(matches) == 1:
                    change.update({
                        "appended": True,
                        "anchorHash": matches[0].get("recordHash"),
                        "afterBytes": os.path.getsize(_MISSION_WAL_FILE),
                    })
            if change.get("appended") is True:
                _rollback_remote_recovery_wal_floor(change)
            raise
    sequences = [int(row.get("sequence") or 0)
                 for row in (state.get("records") or [])]
    if int(state.get("corruptCount") or 0) != 0 or maximum < target or \
            len(sequences) != len(set(sequences)):
        if change.get("appended") is True:
            _rollback_remote_recovery_wal_floor(change)
        raise _RemoteRecoveryRestoreError("recovery_wal_floor_readback_failed")
    _DURABLE_STATE["remoteRecoveryWalFloor"] = {
        "status": "verified", "targetWalSequence": target,
        "allocatorFloor": maximum,
    }
    change["allocatorFloor"] = maximum
    return change


_LOCAL_CHECKPOINT_CORRUPTION_REASONS = frozenset({
    "local_checkpoint_integrity_invalid",
    "local_checkpoint_symlink_rejected",
    "legacy_checkpoint_symlink_rejected",
    "legacy_checkpoint_seal_symlink_rejected",
    "legacy_checkpoint_seal_missing",
    "legacy_checkpoint_seal_oversized",
    "legacy_checkpoint_seal_invalid",
    "legacy_checkpoint_file_hash_mismatch",
})


def _restore_error_class(exc):
    if isinstance(exc, argus_remote_recovery.RecoveryBundleError):
        return exc.classification
    if isinstance(exc, argus_persistent_storage.PersistentStorageError):
        return exc.reason
    if isinstance(exc, _RemoteRecoveryRestoreError):
        value = str(exc)
        if re.fullmatch(r"[a-z][a-z0-9_]{0,95}", value):
            return value
    return type(exc).__name__


def _record_restore_decision(*, stage, error_class, local_validity,
                             remote_failure_class, quarantine_decision,
                             quarantine_reason):
    """Record one redacted, deterministic restore/quarantine decision."""
    decision = {
        "RESTORE_STAGE": str(stage),
        "ERROR_CLASS": str(error_class),
        "LOCAL_VALIDITY": str(local_validity),
        "REMOTE_FAILURE_CLASS": (
            str(remote_failure_class)
            if remote_failure_class is not None else None),
        "QUARANTINE_DECISION": str(quarantine_decision),
        "QUARANTINE_REASON": (
            str(quarantine_reason)
            if quarantine_reason is not None else None),
    }
    _DURABLE_STATE["restoreDecision"] = decision
    print(json.dumps({
        "event": "recovery_restore_decision", **decision,
    }, ensure_ascii=True, sort_keys=True), flush=True)
    return decision


def _proven_local_checkpoint_corruption(exc, path):
    """Return a reason only when canonical-local corruption is proven."""
    if isinstance(exc, argus_persistent_storage.PersistentStorageError) and \
            exc.reason in _LOCAL_CHECKPOINT_CORRUPTION_REASONS:
        return exc.reason
    if isinstance(exc, json.JSONDecodeError):
        return "local_checkpoint_json_invalid"
    if isinstance(exc, UnicodeDecodeError):
        return "local_checkpoint_encoding_invalid"
    try:
        metadata = os.lstat(path)
    except OSError:
        return None
    if stat.S_ISLNK(metadata.st_mode):
        return "local_checkpoint_symlink_rejected"
    if not stat.S_ISREG(metadata.st_mode):
        return "local_checkpoint_not_regular"
    return None


def _osint_restore_once():
    """Restore a sealed local checkpoint or verified Remote Journal snapshot."""
    if _OSINT_PERSIST_STATE.get("restored"):
        return _DURABLE_STATE.get("restoreSource")
    blob = None
    source = None
    pinned_ledger = None
    pinned_remote_evidence = None
    restore_token = object()
    local_validity = "NOT_EVALUATED"
    restore_stage = "LOCAL_CHECKPOINT_LOAD"
    try:
        if _DURABILITY_PRODUCTION:
            blob = argus_persistent_storage.load_checkpoint(
                _OSINT_PERSIST_FILE, require_seal=True,
                allow_legacy_file_seal=True)
            local_validity = "VALID"
            restore_stage = "REMOTE_NONCE_BOOT"
            nonce_keys = argus_remote_recovery.configured_keys()
            if nonce_keys.get("status") == "configured":
                if _validated_recovery_required_marker(blob) is not None and \
                        os.path.lexists(_REMOTE_RECOVERY_FILE):
                    resolved_local = \
                        _resolve_authoritative_local_recovery_checkpoint(
                            blob, _OSINT_PERSIST_FILE, nonce_keys)
                    blob = resolved_local["checkpoint"]
                    _DURABLE_STATE["remoteRecoveryCheckpointResolution"] = {
                        "status": "verified",
                        "projectionCurrent": resolved_local[
                            "projectionCurrent"],
                        "sourceCheckpointHash": resolved_local["payload"][
                            "sourceCheckpointHash"],
                    }
                remote_evidence_handoff = []
                try:
                    # Resolve the moving ref once.  If the local generation is
                    # rejected later, cold restore reuses this same immutable
                    # commit rather than observing a second moving head.
                    pinned_ledger = _pinned_ledger_restore_base()
                    _DURABLE_STATE["remoteRecoveryNonceBoot"] = \
                        _prepare_keyed_local_recovery_nonce_boot(
                            blob, nonce_keys, pinned_ledger,
                            evidence_handoff=remote_evidence_handoff,
                            restore_token=restore_token)
                except argus_remote_recovery.RecoveryBundleError as exc:
                    _DURABLE_STATE["remoteRecoveryError"] = \
                        exc.classification
                    _DURABLE_STATE["remoteRecoveryLocalError"] = \
                        exc.classification
                    _record_restore_decision(
                        stage=restore_stage,
                        error_class=exc.classification,
                        local_validity=local_validity,
                        remote_failure_class=exc.classification,
                        quarantine_decision="PRESERVE",
                        quarantine_reason=None)
                    _DURABLE_STATE["restoreSource"] = "none_available"
                    return None
                if len(remote_evidence_handoff) > 1:
                    raise argus_remote_recovery.RecoveryBundleError(
                        "recovery_pinned_evidence_handoff_invalid")
                pinned_remote_evidence = (
                    remote_evidence_handoff[0]
                    if remote_evidence_handoff else None)
            local_evidence_handoff = []
            restore_stage = "LOCAL_RECOVERY_PAIR_VERIFICATION"
            blob = _verify_local_recovery_sidecar(
                blob, authenticated_local_handoff=(
                    local_evidence_handoff
                    if nonce_keys.get("status") == "configured" else None),
                pinned_legacy_evidence=(
                    pinned_remote_evidence if isinstance(
                        pinned_remote_evidence,
                        _AuthenticatedPinnedLegacyReadbackEvidence) else None),
                pinned_ledger=(pinned_ledger if isinstance(
                    pinned_remote_evidence,
                    _AuthenticatedPinnedLegacyReadbackEvidence) else None),
                restore_token=(restore_token if isinstance(
                    pinned_remote_evidence,
                    _AuthenticatedPinnedLegacyReadbackEvidence) else None))
            if pinned_remote_evidence is not None:
                if len(local_evidence_handoff) != 1:
                    raise argus_remote_recovery.RecoveryBundleError(
                        "recovery_local_evidence_handoff_invalid")
                try:
                    authority = _select_keyed_recovery_boot_authority(
                        blob, local_evidence_handoff[0],
                        pinned_remote_evidence, pinned_ledger, nonce_keys,
                        restore_token=restore_token)
                except argus_remote_recovery.RecoveryBundleError as exc:
                    _DURABLE_STATE["remoteRecoveryError"] = \
                        exc.classification
                    _DURABLE_STATE["remoteRecoveryLocalError"] = \
                        exc.classification
                    _record_restore_decision(
                        stage="REMOTE_AUTHORITY_SELECTION",
                        error_class=exc.classification,
                        local_validity=local_validity,
                        remote_failure_class=exc.classification,
                        quarantine_decision="PRESERVE",
                        quarantine_reason=None)
                    _DURABLE_STATE["restoreSource"] = "none_available"
                    return None
                _DURABLE_STATE["remoteRecoveryNonceBoot"] = {
                    **_DURABLE_STATE.get("remoteRecoveryNonceBoot", {}),
                    "authority": ("pinned_remote" if authority == "remote"
                                  else "local"),
                }
                if authority == "remote":
                    blob = None
                elif "localCheckpointIntegrity" in blob:
                    source = "persistent_local"
                else:
                    source = "persistent_local_legacy_verified"
            elif "localCheckpointIntegrity" in blob:
                source = "persistent_local"
            else:
                source = "persistent_local_legacy_verified"
            if source == "persistent_local_legacy_verified":
                _DURABLE_STATE["legacyCheckpointMigration"] = {
                    "status": "verified",
                    "schemaVersion":
                        argus_persistent_storage.LEGACY_FILE_SEAL_SCHEMA,
                    "requiresSealedRewrite": True,
                }
        else:
            with open(_OSINT_PERSIST_FILE, encoding="utf-8") as handle:
                blob = json.load(handle)
            source = "tmp"
    except FileNotFoundError as exc:
        if local_validity == "VALID":
            _record_restore_decision(
                stage=restore_stage,
                error_class=type(exc).__name__,
                local_validity=local_validity,
                remote_failure_class=type(exc).__name__,
                quarantine_decision="PRESERVE",
                quarantine_reason=None)
            _DURABLE_STATE["restoreSource"] = "none_available"
            return None
        local_validity = "ABSENT"
        _record_restore_decision(
            stage="LOCAL_CHECKPOINT_LOAD",
            error_class="FileNotFoundError",
            local_validity=local_validity,
            remote_failure_class=None,
            quarantine_decision="NOT_APPLICABLE",
            quarantine_reason=None)
        if _DURABILITY_PRODUCTION and os.path.lexists(
                _REMOTE_RECOVERY_FILE):
            try:
                orphan_keys = argus_remote_recovery.configured_keys()
            except argus_remote_recovery.RecoveryBundleError as exc:
                _DURABLE_STATE["remoteRecoveryError"] = exc.classification
                _DURABLE_STATE["remoteRecoveryLocalError"] = \
                    exc.classification
                _record_restore_decision(
                    stage="ORPHAN_SIDECAR_KEY_VALIDATION",
                    error_class=exc.classification,
                    local_validity=local_validity,
                    remote_failure_class=exc.classification,
                    quarantine_decision="NOT_APPLICABLE",
                    quarantine_reason=None)
                _DURABLE_STATE["restoreSource"] = "none_available"
                return None
            if orphan_keys.get("status") != "configured":
                _DURABLE_STATE["remoteRecoveryError"] = \
                    "recovery_key_not_configured"
                _DURABLE_STATE["remoteRecoveryLocalError"] = \
                    "recovery_key_not_configured"
                _record_restore_decision(
                    stage="ORPHAN_SIDECAR_KEY_VALIDATION",
                    error_class="recovery_key_not_configured",
                    local_validity=local_validity,
                    remote_failure_class="recovery_key_not_configured",
                    quarantine_decision="NOT_APPLICABLE",
                    quarantine_reason=None)
                _DURABLE_STATE["restoreSource"] = "none_available"
                return None
            _DURABLE_STATE["remoteRecoveryLocalError"] = \
                "recovery_local_checkpoint_missing"
        blob = None
    except Exception as exc:
        error_class = _restore_error_class(exc)
        _DURABLE_STATE["localCheckpointError"] = type(exc).__name__
        if isinstance(exc, argus_remote_recovery.RecoveryBundleError):
            _DURABLE_STATE["remoteRecoveryError"] = exc.classification
            _DURABLE_STATE["remoteRecoveryLocalError"] = exc.classification
        corruption_reason = (
            _proven_local_checkpoint_corruption(exc, _OSINT_PERSIST_FILE)
            if local_validity != "VALID" else None)
        if local_validity == "VALID" or corruption_reason is None:
            _record_restore_decision(
                stage=restore_stage,
                error_class=error_class,
                local_validity=(local_validity if local_validity == "VALID"
                                else "UNPROVEN"),
                remote_failure_class=(
                    error_class if local_validity == "VALID" else None),
                quarantine_decision="PRESERVE",
                quarantine_reason=None)
            _DURABLE_STATE["restoreSource"] = "none_available"
            return None
        local_validity = "INVALID"
        try:
            _DURABLE_STATE["quarantinedCheckpoint"] = \
                argus_persistent_storage.quarantine(_OSINT_PERSIST_FILE)
            _record_restore_decision(
                stage="LOCAL_CHECKPOINT_LOAD",
                error_class=error_class,
                local_validity=local_validity,
                remote_failure_class=None,
                quarantine_decision="QUARANTINED",
                quarantine_reason=corruption_reason)
        except Exception as quarantine_exc:
            _DURABLE_STATE["quarantineError"] = type(
                quarantine_exc).__name__
            _record_restore_decision(
                stage="LOCAL_CHECKPOINT_QUARANTINE",
                error_class=type(quarantine_exc).__name__,
                local_validity=local_validity,
                remote_failure_class=None,
                quarantine_decision="FAILED_PRESERVE",
                quarantine_reason=corruption_reason)
            _DURABLE_STATE["restoreSource"] = "none_available"
            return None
        blob = None
    if blob is None:
        restore_stage = "REMOTE_COLD_RESTORE"
        try:
            if pinned_ledger is None:
                pinned_ledger = _pinned_ledger_restore_base()
            pinned_ledger_base = pinned_ledger["base"]
            # The five-year breadth snapshot is intentionally kept outside the
            # web process and is currently tens of MB. A six-second read
            # timeout made a healthy ledger look like ``no_prior_state`` during
            # a cold deploy. Keep connection failure bounded while allowing a
            # large, continuously streaming snapshot enough time to arrive.
            r = requests.get(
                f"{pinned_ledger_base}/osint/memory.json",
                timeout=_DURABLE_RESTORE_HTTP_TIMEOUT,
                stream=True,
            )
            if r.status_code == 200:
                restore_path = None
                try:
                    with tempfile.NamedTemporaryFile(
                            mode="wb", prefix="argus-durable-restore-",
                            suffix=".json",
                            dir=_DURABILITY_PATHS["tempDirectory"],
                            delete=False) as tmp:
                        restore_path = tmp.name
                        received = 0
                        for chunk in r.iter_content(chunk_size=1024 * 1024):
                            if not chunk:
                                continue
                            received += len(chunk)
                            if received > _DURABLE_RESTORE_MAX_BYTES:
                                raise ValueError("durable_snapshot_too_large")
                            tmp.write(chunk)
                    with open(restore_path, encoding="utf-8") as f:
                        blob = json.load(f)
                    if _DURABILITY_PRODUCTION:
                        parsed_remote = \
                            argus_remote_journal.parse_remote_snapshot(blob)
                        if blob.get("schemaVersion") != "argus-durable-v3" or \
                                parsed_remote.get("status") != "ok":
                            raise ValueError("remote_snapshot_not_verified")
                        remote_nonce_floor_handoff = []
                        blob = _overlay_remote_recovery(
                            blob, pinned_ledger_base,
                            pinned_ledger["commitSha"],
                            ledger_owner=pinned_ledger["owner"],
                            ledger_repository=pinned_ledger["repository"],
                            nonce_floor_handoff=
                                remote_nonce_floor_handoff,
                            authenticated_pinned_evidence=
                                pinned_remote_evidence)
                        if isinstance(
                                blob.get("remoteRecoveryProvenance"), dict) and \
                                len(remote_nonce_floor_handoff) != 1:
                            raise _RemoteRecoveryRestoreError(
                                "recovery_nonce_bootstrap_handoff_missing")
                        source = "remote_journal_verified"
                        # The new disk is not accepted until a sealed local
                        # checkpoint survives fsync, read-back and replacement.
                        bootstrap = argus_persistent_storage.write_checkpoint(
                            _OSINT_PERSIST_FILE, blob,
                            temp_directory=_DURABILITY_PATHS["tempDirectory"])
                        _DURABLE_STATE["bootstrapCheckpoint"] = bootstrap
                        if isinstance(
                                blob.get("remoteRecoveryProvenance"), dict):
                            _persist_remote_recovery_sidecar({
                                **bootstrap,
                                "verified": True,
                                "readBackVerified": True,
                                "includedWalSequence": int(
                                    (blob.get("missionTickDurability") or {})
                                    .get("walAppliedSequence") or 0),
                            }, authenticated_remote_floor=(
                                remote_nonce_floor_handoff[0]
                                if remote_nonce_floor_handoff else None))
                        blob = argus_persistent_storage.load_checkpoint(
                            _OSINT_PERSIST_FILE, require_seal=True)
                        if isinstance(
                                blob.get("remoteRecoveryRequired"), dict):
                            blob = _verify_local_recovery_sidecar(
                                blob, allow_legacy_migration=False)
                    else:
                        source = "ledger"
                finally:
                    if restore_path:
                        try:
                            os.unlink(restore_path)
                        except OSError:
                            pass
                    r.close()
            else:
                r.close()
        except Exception as exc:
            error_class = _restore_error_class(exc)
            _DURABLE_STATE["remoteRestoreError"] = error_class
            if isinstance(exc, argus_remote_recovery.RecoveryBundleError):
                _DURABLE_STATE["remoteRecoveryError"] = exc.classification
            if local_validity != "INVALID":
                _record_restore_decision(
                    stage=restore_stage,
                    error_class=error_class,
                    local_validity=local_validity,
                    remote_failure_class=error_class,
                    quarantine_decision=(
                        "PRESERVE" if local_validity == "VALID"
                        else "NOT_APPLICABLE"),
                    quarantine_reason=None)
            blob = None
    if blob is None:
        _DURABLE_STATE["restoreSource"] = "none_available"
        return None     # empty production disk must remain empty/fail closed
    if not isinstance(blob, dict):
        # 壊れた状態を信頼しない。productionはreadyへ進めず、local/testも
        # last-known-goodを上書きしない。
        _DURABLE_STATE["integrityStatus"] = "corrupt_ignored"
        return None
    _restore_snapshot = _restore_transaction_snapshot()
    _wal_floor_change = None
    try:
        _restore_checkpoint_failure_history(
            blob.get("checkpointFailureHistory"))
        for k, v in (blob.get("termOverlay") or {}).items():
            if isinstance(v, list):
                cur = _OSINT_TERM_OVERLAY.get(k) or []
                _OSINT_TERM_OVERLAY[k] = (cur + [t for t in v if t not in cur])[:12]
        for rec in (blob.get("memory") or [])[:_OSINT_MEMORY_MAX]:
            if isinstance(rec, dict) and rec.get("privacyLevel") == "public_safe":
                _OSINT_MEMORY.append(rec)
        for k, v in (blob.get("urlCache") or {}).items():
            _OSINT_URL_CACHE[k] = v
        cl = blob.get("canaryLast")
        if isinstance(cl, dict) and cl.get("data") and not _OSINT_CANARY_LAST.get("data"):
            _OSINT_CANARY_LAST.update(cl)
        for h in (blob.get("rpsHistory") or [])[-40:]:
            if isinstance(h, dict) and not any(
                    x.get("at") == h.get("at") and x.get("symbol") == h.get("symbol")
                    for x in _OSINT_RPS_HISTORY):
                _OSINT_RPS_HISTORY.append(h)
        for h in (blob.get("baselineRuns") or [])[-24:]:
            if isinstance(h, dict) and not any(
                    x.get("at") == h.get("at") and x.get("case") == h.get("case")
                    for x in _OSINT_BASELINE_RUNS):
                _OSINT_BASELINE_RUNS.append(h)
        for h in (blob.get("benchmarkRuns") or [])[-20:]:
            if isinstance(h, dict) and not any(
                    x.get("id") == h.get("id") for x in _OSINT_BENCHMARK_RUNS):
                _OSINT_BENCHMARK_RUNS.append(h)
        _formal = blob.get("formalResearchBenchmark")
        if isinstance(_formal, dict):
            restored = argus_research_benchmark.normalize_state(_formal)
            # append-only: remote may add a completed result, never erase local.
            merged_results = list(_FORMAL_BENCHMARK.get("results") or [])
            known = {r.get("benchmarkId") for r in merged_results}
            for result in restored.get("results", []):
                if result.get("benchmarkId") not in known:
                    merged_results.append(result)
                    known.add(result.get("benchmarkId"))
            if restored.get("lastCompletedAt") and str(
                    restored.get("lastCompletedAt")) > str(
                    _FORMAL_BENCHMARK.get("lastCompletedAt") or ""):
                _FORMAL_BENCHMARK.update(restored)
            # A started formal run is permanently counted even if the process
            # restarts before a final result.  Never let an older/local default
            # reopen the one-shot benchmark or consume the holdout twice.
            if int(restored.get("executionCount") or 0) > int(
                    _FORMAL_BENCHMARK.get("executionCount") or 0):
                _FORMAL_BENCHMARK["executionCount"] = restored["executionCount"]
                _FORMAL_BENCHMARK["firstStartedAt"] = restored.get("firstStartedAt")
                _FORMAL_BENCHMARK["status"] = (
                    "interrupted" if restored.get("runningBenchmarkId")
                    else restored.get("status") or "not_run")
                _FORMAL_BENCHMARK["mode"] = "DETERMINISTIC"
                _FORMAL_BENCHMARK["runningBenchmarkId"] = None
            if restored.get("holdoutConsumedBy") and not \
                    _FORMAL_BENCHMARK.get("holdoutConsumedBy"):
                _FORMAL_BENCHMARK["holdoutConsumedBy"] = \
                    restored["holdoutConsumedBy"]
            _FORMAL_BENCHMARK["results"] = merged_results
        _formal_v2 = blob.get("formalResearchBenchmarkV2")
        if isinstance(_formal_v2, dict):
            restored_v2 = argus_research_benchmark_v2.normalize_state(_formal_v2)
            local_v2 = argus_research_benchmark_v2.normalize_state(
                _FORMAL_BENCHMARK_V2)
            merged_v2_results = list(local_v2.get("results") or [])
            known_v2 = {x.get("benchmarkId") for x in merged_v2_results}
            merged_v2_results.extend(
                x for x in (restored_v2.get("results") or [])
                if x.get("benchmarkId") not in known_v2)
            merged_v2_receipts = list(local_v2.get("remoteReceipts") or [])
            known_receipts = {x.get("receiptId") for x in merged_v2_receipts}
            merged_v2_receipts.extend(
                x for x in (restored_v2.get("remoteReceipts") or [])
                if x.get("receiptId") not in known_receipts)
            if str(restored_v2.get("lastCompletedAt") or "") > str(
                    local_v2.get("lastCompletedAt") or ""):
                local_v2.update(restored_v2)
            if restored_v2.get("holdoutConsumedBy") and not \
                    local_v2.get("holdoutConsumedBy"):
                local_v2["holdoutConsumedBy"] = restored_v2["holdoutConsumedBy"]
            if restored_v2.get("v1Closure") and not local_v2.get("v1Closure"):
                local_v2["v1Closure"] = restored_v2["v1Closure"]
            local_v2["results"] = merged_v2_results[-4:]
            local_v2["remoteReceipts"] = merged_v2_receipts[-8:]
            if restored_v2.get("runningBenchmarkId"):
                local_v2.update({"mode": "DETERMINISTIC", "status": "interrupted",
                                 "runningBenchmarkId": None})
            _FORMAL_BENCHMARK_V2.clear()
            _FORMAL_BENCHMARK_V2.update(local_v2)
        _jobs = blob.get("foundationJobs")
        if isinstance(_jobs, dict):
            restored_jobs = argus_foundation_jobs.normalize_state(_jobs)
            known_jobs = {x.get("jobId") for x in _FOUNDATION_JOBS.get("jobs", [])}
            _FOUNDATION_JOBS.setdefault("jobs", []).extend(
                x for x in restored_jobs.get("jobs", []) if x.get("jobId") not in known_jobs)
            # A process restart interrupts a running in-memory worker, but its
            # checkpoint remains resumable and its history is never deleted.
            for job in _FOUNDATION_JOBS.get("jobs", []):
                if job.get("status") in ("queued", "running"):
                    job["status"] = "failed"
                    job["errorClass"] = "process_restarted_resume_required"
                    job["completedAt"] = _ai_now_iso()
            _FOUNDATION_JOBS["activeJobId"] = None
        _DURABLE_STATE["foundationJobsSidecarRestoredAt"] = \
            _foundation_jobs_restore_sidecar()
        for archived in (blob.get("soakHistory") or [])[-8:]:
            if isinstance(archived, dict) and archived.get("soakId") and \
                    not any(row.get("soakId") == archived.get("soakId")
                            for row in _SOAK_HISTORY):
                _SOAK_HISTORY.append(copy.deepcopy(archived))
        restored_control = blob.get("soakControl")
        if isinstance(restored_control, dict) and \
                restored_control.get("armed") is True:
            _SOAK_CONTROL.update({
                key: restored_control.get(key)
                for key in _SOAK_CONTROL})
        restored_stage1 = blob.get("checkpointV2Stage1Control")
        if _CHECKPOINT_V2_STAGE1_ENABLED and isinstance(
                restored_stage1, dict):
            globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = \
                argus_checkpoint_v2_stage1.normalize(
                    restored_stage1, _backend_exact_sha() or None)
            # The V2 manifest is the authoritative provenance for the most
            # recently promoted generation, which can be newer than the
            # legacy blob that initiated that dual-write.
            _v2_public = argus_checkpoint_v2.public_status(
                _CHECKPOINT_V2_ROOT)
            for _row in _v2_public.get("generationHistory") or []:
                globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = \
                    argus_checkpoint_v2_stage1.record_generation(
                        _CHECKPOINT_V2_STAGE1_CONTROL,
                        {"verified": True,
                         "generationId": _row.get("generationId"),
                         "createdAt": _row.get("createdAt"),
                         "databaseBytes": _row.get("databaseBytes"),
                         "sourceSerializedBytes": _row.get(
                             "sourceSerializedBytes"),
                         "resourceTelemetry": _row.get(
                             "resourceTelemetry")},
                        trigger_source=str(
                            _row.get("triggerSource") or "unknown"),
                        mission_window_id=_row.get("missionWindowId"))
        sk = blob.get("soak")
        if isinstance(sk, dict) and sk.get("startedAt") and not _SOAK["startedAt"]:
            # v12.2.9 build-scoped: 同一SHAのredeployでsoakをリセットしない
            # (中断として記録)。別SHA/不明SHAは旧soak時計を継承しない —
            # 新buildのstartedAtがDeploy liveより前に遡る欠陥の根治。
            _dec = argus_runtime.soak_restore_decision(
                persisted=sk,
                current_build_sha=_backend_exact_sha() or _backend_sha(),
                boot_iso=_RUNTIME["processBootedAt"],
                last_persist_at=blob.get("soakLastPersistAt")
                or _DURABLE_STATE.get("lastKnownGoodAt"),
                current_boot_id=_RUNTIME.get("bootId"),
                planned_restart_marker=(restored_control or {}).get(
                    "plannedRestartMarker"))
            _STARTUP["soakRestoreAction"] = _dec.get("action")
            if _dec.get("action") == "inherit_with_interruption":
                for _k in ("soakId", "buildSha", "buildShaFull",
                           "appVersion", "processBootId",
                           "processBootedAt", "startedAt",
                           "startReason", "startTimeSource", "heartbeats",
                           "startedBy", "firstMissionWindowId",
                           "completed72h", "interruptionCount",
                           "state", "lastHeartbeatAt", "lastHeartbeatSource",
                           "previousSoak"):
                    _SOAK[_k] = sk.get(_k)
                if not isinstance(_SOAK.get("heartbeats"), list):
                    _SOAK["heartbeats"] = []
                _SOAK["state"] = _SOAK.get("state") or "not_started"
                _SOAK["interruptions"] = (list(sk.get("interruptions") or [])
                                          + [_dec["interruption"]])
                _SOAK["interruptionCount"] = len(_SOAK["interruptions"])
            elif _dec.get("action") == "terminalize_interrupted":
                terminal = copy.deepcopy(_dec.get("terminalSoak") or sk)
                if not any(
                        row.get("soakId") == terminal.get("soakId") and
                        row.get("startedAt") == terminal.get("startedAt")
                        for row in _SOAK_HISTORY):
                    _SOAK_HISTORY.append(terminal)
                    del _SOAK_HISTORY[:-8]
                _SOAK["previousSoak"] = _dec.get("previousSoakSummary")
            else:
                # Preserve the complete prior record by value before a
                # different build creates its own active Soak. Never mutate an
                # archived row into a success.
                if not any(
                        row.get("soakId") == sk.get("soakId") and
                        row.get("startedAt") == sk.get("startedAt")
                        for row in _SOAK_HISTORY):
                    _SOAK_HISTORY.append(copy.deepcopy(sk))
                    del _SOAK_HISTORY[:-8]
                _SOAK["previousSoak"] = _dec.get("previousSoakSummary")
        if isinstance(sk, dict):
            _previous = (_SOAK.get("previousSoak") or
                         sk.get("previousSoak"))
            _normalized_previous = \
                argus_runtime.normalize_previous_soak_summary(
                    previous=_previous, history=_SOAK_HISTORY,
                    current_build_sha=_backend_exact_sha() or _backend_sha(),
                    boot_iso=_RUNTIME["processBootedAt"])
            if _normalized_previous is not None:
                _SOAK["previousSoak"] = _normalized_previous
        for h in (blob.get("missions") or [])[-300:]:
            if isinstance(h, dict) and not any(
                    x.get("idempotencyKey") == h.get("idempotencyKey")
                    for x in _MISSIONS):
                _MISSIONS.append(h)
        for h in (blob.get("missionWindows") or [])[-240:]:
            if isinstance(h, dict) and h.get("missionWindowId") and not any(
                    x.get("missionWindowId") == h.get("missionWindowId")
                    for x in _MISSION_WINDOWS):
                _MISSION_WINDOWS.append(h)
        for h in (blob.get("forecasts") or [])[-200:]:
            if isinstance(h, dict) and not any(
                    x.get("id") == h.get("id") for x in _FORECAST_LEDGER):
                _FORECAST_LEDGER.append(h)
        for h in (blob.get("outcomes") or [])[-200:]:
            if not isinstance(h, dict):
                continue
            existing = next((x for x in _OUTCOME_LEDGER
                             if x.get("forecastId") == h.get("forecastId")), None)
            if existing is None:
                _OUTCOME_LEDGER.append(h)
            elif _outcome_restore_is_newer(existing, h):
                existing.clear()
                existing.update(h)
        for h in (blob.get("incidents") or [])[-20:]:
            if isinstance(h, dict) and h not in _INCIDENTS:
                _INCIDENTS.append(h)
        # A recovery bundle is an exact projection of every collection that a
        # transitionState WAL record can replace.  These four targets were not
        # part of the historical full snapshot restore path; consume them only
        # when present and keep their runtime bounds unchanged.
        for _key, _target, _limit in (
                ("postmortems", _POSTMORTEMS, 30),
                ("periodicReports", _PERIODIC_REPORTS, 12),
                ("challengerRuns", _CHALLENGER_RUNS, 8)):
            _incoming = blob.get(_key)
            if isinstance(_incoming, list):
                _target[:] = copy.deepcopy(_incoming[-_limit:])
        _agent_queue = blob.get("agentQueue")
        if isinstance(_agent_queue, dict):
            _OSINT_AGENT_QUEUE.clear()
            _OSINT_AGENT_QUEUE.update(copy.deepcopy(_agent_queue))
        _cp = blob.get("costPolicy")
        if isinstance(_cp, dict):
            _restored_cp = argus_cost_policy.normalize_state(_cp)
            # Runtime mode is an operator policy; persisted usage/events are restored,
            # but an old snapshot cannot silently re-enable automatic AI.
            _restored_cp["mode"] = _COST_POLICY["mode"]
            _restored_cp["eventOptIn"] = _COST_POLICY["eventOptIn"]
            _COST_POLICY.clear()
            _COST_POLICY.update(_restored_cp)
        _ml = blob.get("marketLedger")
        if isinstance(_ml, dict):
            _restored_ml = argus_market_ledger.merge_restored_state(
                _MARKET_LEDGER, _ml)
            _MARKET_LEDGER.clear()
            _MARKET_LEDGER.update(_restored_ml)
        _ci = blob.get("chartIntelligence")
        if isinstance(_ci, dict):
            _restored_ci = argus_chart_intelligence.normalize_state(_ci)
            # Phase 2 history is append-only.  A remote snapshot can only add
            # deterministic records; it cannot remove newer local detections.
            for _key in ("snapshots", "zones", "turningPoints",
                         "reactionAnomalies", "relationshipBreaks", "invalidations"):
                def _ci_restore_key(_record):
                    if _key == "snapshots":
                        return _record.get("id")
                    if _key == "invalidations":
                        return (_record.get("symbol"), _record.get("market"),
                                _record.get("turningPointId"))
                    return (_record.get("symbol"), _record.get("market"),
                            _record.get("id"))
                _seen = {_ci_restore_key(x)
                         for x in _CHART_INTELLIGENCE.get(_key, [])}
                _CHART_INTELLIGENCE.setdefault(_key, []).extend(
                    x for x in _restored_ci.get(_key, [])
                    if _ci_restore_key(x) not in _seen)
            _CHART_INTELLIGENCE["lastUpdatedAt"] = max(
                str(_CHART_INTELLIGENCE.get("lastUpdatedAt") or ""),
                str(_restored_ci.get("lastUpdatedAt") or "")) or None
        _ti = blob.get("todayIntelligence")
        if isinstance(_ti, dict):
            _restored_ti = argus_today_intelligence.merge_state(
                _TODAY_INTELLIGENCE, _ti)
            _TODAY_INTELLIGENCE.clear()
            _TODAY_INTELLIGENCE.update(_restored_ti)
        _mr = blob.get("marketReplay")
        if isinstance(_mr, dict):
            _restored_mr = argus_market_replay.merge_state(_MARKET_REPLAY, _mr)
            _MARKET_REPLAY.clear()
            _MARKET_REPLAY.update(_restored_mr)
        _vvs = blob.get("verifiedViewSnapshots")
        if isinstance(_vvs, dict):
            # Restore is monotonic per pointer: a remote/ephemeral older view
            # can add a missing key but cannot roll back a newer local view.
            for _snapshot in argus_verified_snapshot.normalize_store(
                    _vvs).get("current", {}).values():
                _restored_vvs, _ = argus_verified_snapshot.publish_atomic(
                    _VERIFIED_VIEW_SNAPSHOTS, _snapshot, now_iso=_ai_now_iso())
                _VERIFIED_VIEW_SNAPSHOTS.clear()
                _VERIFIED_VIEW_SNAPSHOTS.update(_restored_vvs)
        _asset_reports = blob.get("assetChartReports")
        if isinstance(_asset_reports, dict):
            _restored_asset_reports = \
                argus_asset_chart_cache.merge_restored(
                    _ASSET_CHART_REPORTS, _asset_reports)
            _ASSET_CHART_REPORTS.clear()
            _ASSET_CHART_REPORTS.update(_restored_asset_reports)
        _jr = argus_state_journal.load_valid(blob.get("opsJournal") or [])
        for h in _jr["events"]:
            argus_state_journal.append(_OPS_JOURNAL, h)
        _DURABLE_STATE["journalCorrupt"] = _jr["corruptCount"]
        _jm = blob.get("opsJournalMeta") or {}
        _OPS_JOURNAL_META["totalObserved"] = max(
            _OPS_JOURNAL_META["totalObserved"],
            int(_jm.get("totalObserved") or 0), len(_OPS_JOURNAL))
        # v12.2.10: compactバッチ+検証済みackレシートの復元(冪等マージ)
        global _OPS_JOURNAL_COMPACT
        _OPS_JOURNAL_COMPACT = argus_remote_journal.merge_compacted(
            _OPS_JOURNAL_COMPACT,
            [b for b in (blob.get("opsJournalCompacted") or [])
             if isinstance(b, dict)])
        _recovery_exact = isinstance(
            blob.get("remoteRecoveryProvenance"), dict)
        if _recovery_exact:
            if _jr.get("corruptCount"):
                raise _RemoteRecoveryRestoreError(
                    "recovery_journal_corrupt")
            for _key, _target in (
                    ("missions", _MISSIONS),
                    ("missionWindows", _MISSION_WINDOWS),
                    ("forecasts", _FORECAST_LEDGER),
                    ("outcomes", _OUTCOME_LEDGER),
                    ("incidents", _INCIDENTS),
                    ("postmortems", _POSTMORTEMS),
                    ("periodicReports", _PERIODIC_REPORTS),
                    ("challengerRuns", _CHALLENGER_RUNS)):
                _target[:] = copy.deepcopy(blob[_key])
            _SOAK.clear()
            _SOAK.update(copy.deepcopy(blob["soak"]))
            _OSINT_AGENT_QUEUE.clear()
            _OSINT_AGENT_QUEUE.update(copy.deepcopy(blob["agentQueue"]))
            _OPS_JOURNAL[:] = copy.deepcopy(_jr["events"])
            _OPS_JOURNAL_META.clear()
            _OPS_JOURNAL_META.update(copy.deepcopy(blob["opsJournalMeta"]))
            _OPS_JOURNAL_COMPACT[:] = copy.deepcopy(
                blob["opsJournalCompacted"])
            _OPS_SEQ.clear()
            _OPS_SEQ.update(copy.deepcopy(blob["opsSequenceByAggregate"]))
        _ra = blob.get("remoteAck")
        if isinstance(_ra, dict) and isinstance(_ra.get("ackedKeys"), list):
            merged_keys = list(_REMOTE_ACK["ackedKeys"])
            for k in _ra["ackedKeys"]:
                if k not in set(merged_keys):
                    merged_keys.append(k)
            _REMOTE_ACK["ackedKeys"] = merged_keys[-800:]
            if _ra.get("lastVerifiedRemoteAckAt") and \
                    not _REMOTE_ACK["lastVerifiedRemoteAckAt"]:
                _REMOTE_ACK["lastVerifiedRemoteAckAt"] = \
                    _ra["lastVerifiedRemoteAckAt"]
            for oid in (_ra.get("outcomeAckedIds") or []):
                if oid not in _REMOTE_ACK["outcomeAckedIds"]:
                    _REMOTE_ACK["outcomeAckedIds"].append(oid)
            _REMOTE_ACK["outcomeAckedIds"] = \
                _REMOTE_ACK["outcomeAckedIds"][-400:]
            if _ra.get("lastVerifiedOutcomeReadBackAt") and \
                    not _REMOTE_ACK["lastVerifiedOutcomeReadBackAt"]:
                _REMOTE_ACK["lastVerifiedOutcomeReadBackAt"] = \
                    _ra["lastVerifiedOutcomeReadBackAt"]
        _rc = blob.get("remoteJournalCycle")
        if isinstance(_rc, dict):
            _REMOTE_CYCLE.update({k: _rc.get(k) for k in _REMOTE_CYCLE})
        _mt = blob.get("missionTickDurability")
        if isinstance(_mt, dict):
            _MISSION_BATCH_STATE.update({
                key: _mt.get(key) for key in _MISSION_BATCH_STATE
                if key in _mt})
        if _DURABILITY_PRODUCTION:
            _restore_persistent_remote_receipt()
        _restore_remote_receipt_queue()
        if "opsJournal" not in blob:
            _REMOTE_ACK["legacyRemote"] = True   # v2 snapshot=journal未同乗
        if not _recovery_exact:
            for h in _OPS_JOURNAL:
                k = f"{h.get('aggregateType')}:{h.get('aggregateId')}"
                _OPS_SEQ[k] = max(
                    _OPS_SEQ.get(k, 0), int(h.get("sequence") or 0))
        # Legacy local/test blobs predate mission WAL cursors. Replaying an
        # unrelated process WAL into them would cross-contaminate state.
        if _DURABILITY_PRODUCTION or isinstance(_mt, dict):
            _restore_mission_wal(
                after_sequence=int(_MISSION_BATCH_STATE.get(
                    "walAppliedSequence") or 0))
        # Persist the allocator anchor only after all payload mutations and WAL
        # replay have succeeded.  If a later metadata write fails, the exact
        # append is rolled back together with the in-memory transaction.
        _wal_floor_change = _seed_remote_recovery_wal_floor(blob)
        _persist_durability_metadata()
        _DURABLE_STATE["lastRestoreAt"] = _ai_now_iso()
        _DURABLE_STATE["restoreSource"] = source
        _OSINT_PERSIST_STATE["restored"] = True
        return source
    except Exception as exc:
        if isinstance(_wal_floor_change, dict) and \
                _wal_floor_change.get("appended") is True:
            try:
                _rollback_remote_recovery_wal_floor(_wal_floor_change)
            except Exception:
                exc = _RemoteRecoveryRestoreError(
                    "recovery_wal_floor_rollback_failed")
        _restore_transaction_rollback(_restore_snapshot)
        _DURABLE_STATE["integrityStatus"] = "corrupt_ignored"
        _DURABLE_STATE["restoreApplyError"] = type(exc).__name__
        if isinstance(exc, _RemoteRecoveryRestoreError):
            _DURABLE_STATE["remoteRecoveryError"] = str(exc)
        return None


def _osint_fetch_url_meta(url):
    """v12.1.1 Part C: 未知URLの公開メタデータ(title/日付)を安全に実取得。
    admin worker経路のみから呼ばれる(公開GET/POSTからは呼ばない)。ペイウォール
    本文は取らない — <title>とmetaのみ。失敗はinaccessible(捏造なし)。"""
    key = argus_osint_engine._norm_url(url)
    hit = _OSINT_URL_CACHE.get(key)
    if hit:
        return hit
    meta = {"status": "inaccessible", "title": None, "publishedAt": None,
            "domain": None, "at": _ai_now_iso()}
    try:
        m = re.match(r"^https?://([\w.\-]+)/", str(url).strip() + "/")
        if not m:
            _OSINT_URL_CACHE[key] = meta
            return meta
        meta["domain"] = m.group(1)[:60]
        r = requests.get(url, timeout=8, headers={"User-Agent": "Mozilla/5.0 (ARGUS OSINT verifier)"},
                         stream=True)
        if r.status_code != 200:
            meta["status"] = "inaccessible"
        else:
            head = r.raw.read(40000, decode_content=True) or b""
            txt = head.decode(r.encoding or "utf-8", errors="replace")
            t = re.search(r"<title[^>]*>(.*?)</title>", txt, re.S | re.I)
            og = re.search(r'property=["\']og:title["\'][^>]*content=["\']([^"\']+)', txt, re.I) or \
                re.search(r'content=["\']([^"\']+)["\'][^>]*property=["\']og:title', txt, re.I)
            dt = re.search(r'(?:article:published_time|datePublished)["\']?\s*(?:content=|:)\s*["\']([\dT:+\-Z.]{8,32})', txt, re.I)
            title = (og.group(1) if og else (t.group(1) if t else "")).strip()[:160]
            if title:
                meta["status"] = "metadata_only"
                meta["title"] = title
                if dt:
                    meta["publishedAt"] = dt.group(1)
    except Exception:
        meta["status"] = "inaccessible"
    _OSINT_URL_CACHE[key] = meta
    while len(_OSINT_URL_CACHE) > _OSINT_URL_CACHE_MAX:
        _OSINT_URL_CACHE.pop(next(iter(_OSINT_URL_CACHE)), None)
    return meta


def _osint_live_upgrade(vs, claim, now_iso, sym="GLOBAL"):
    """未検証claim(URLあり)をライブメタ取得で昇格: 取得titleがclaim titleと
    十分重なればverified、取得できたがズレるならmetadata_only(実取得titleを表示)。"""
    url = claim.get("url")
    if not url or vs.get("verificationStatus") == "verified":
        return vs
    meta = _osint_fetch_url_meta(url)
    if meta.get("status") == "inaccessible":
        vs["labelJa"] = "未検証(参照不能/ペイウォール)"
        return vs
    fetched = str(meta.get("title") or "")
    claimed = str(claim.get("titleJa") or claim.get("title") or "")
    # 日本語は分かち書きが無いため文字bigramで類似判定(トークン比較は破綻する)
    def _grams(t):
        t2 = re.sub(r"[\s\W]+", "", t.lower())
        return {t2[i:i + 2] for i in range(len(t2) - 1)} if len(t2) >= 2 else set()
    g1, g2 = _grams(claimed), _grams(fetched)
    overlap = (len(g1 & g2) / max(1, len(g1))) if g1 else 0.0
    vs = dict(vs)
    vs["fetchedTitle"] = fetched[:160] or None
    if fetched and overlap >= 0.35:
        domain = str(meta.get("domain") or "")[:60] or None
        source_type = argus_osint_engine.industry_source_type(
            domain or "", fetched) or "unknown"
        trusted_index = argus_osint_engine.build_known_index([{
            "titleJa": fetched,
            "canonicalUrl": url,
            # Only publication metadata actually extracted from the fetched
            # page may supply time authority.  The scout claim and the earlier
            # unverified projection cannot fill this field.
            "publishedAt": meta.get("publishedAt"),
            "sourceName": domain,
            "provider": domain,
            "sourceType": source_type,
            # A matching page title proves identity, not company directness.
            "directness": "unsupported",
        }])
        verified = argus_osint_engine.verify_source(
            claim, trusted_index, now_iso)
        verified["fetchedTitle"] = fetched[:160]
        if verified.get("verificationStatus") == "verified":
            verified["labelJa"] = "検証済み(ライブ取得)"
        # 恒久メモリ+今後のindexに載せる(公開安全メタのみ) — v12.1.3: useCase付きv2
            rec = argus_osint_engine.memory_record_v2(
                symbol=sym, use_case="source_discovery", source_url=url,
                source_title=fetched, learned_from="gemini", verified=True,
                now_iso=now_iso)
            if rec:
                _OSINT_MEMORY.append(rec)
        return verified
    else:
        vs["verificationStatus"] = "metadata_only"
        vs["labelJa"] = "未検証(ライブtitle不一致)" if fetched else vs["labelJa"]
    return vs


def _osint_pool_items(cap=400):
    """検証インデックス/canary用の既知メタデータプール(cached-only)。"""
    pool = list(_INTEL_STORE)[:cap]
    try:
        mn = get_market_news()
        if isinstance(mn, dict):
            for n in (mn.get("items") or [])[:60]:
                pool.append({"title": n.get("headline"), "titleJa": n.get("headlineJa"),
                             "url": n.get("url"), "publishedAt": n.get("datetime")})
    except Exception:
        pass
    return pool


def _osint_retrieve(symu, market, plan):
    """決定論収集: 銘柄の cause-attribution ニュース + プール内のクエリ語ヒット。
    fetchなし(cached-only) — 公開POSTから呼ばれても安全。"""
    cands, counts = [], {"direct": 0, "official": 0, "sector": 0, "valueChain": 0,
                         "globalNews": 0, "jaNews": 0}
    try:
        st = get_cause_attribution(symu, market)
        for n in (st.get("news") or [])[:12]:
            t = n.get("displayTitleJa") or n.get("titleJa") or ""
            if not t:
                continue
            src = str(n.get("source") or "")
            cands.append({"titleJa": t, "title": n.get("titleOriginal"),
                          "url": n.get("url"), "sourceName": src,
                          "publishedAt": n.get("time"),
                          "directness": "direct_company" if n.get("cls") == "CONFIRMED"
                          else "sector_theme"})
            counts["direct"] += 1
            if "tdnet" in src.lower() or "edgar" in src.lower():
                counts["official"] += 1
        flow_hint = (st.get("flowAttribution") or {}).get("flowClass")
    except Exception:
        flow_hint = None
    # プール内クエリヒット(テーマ/バリューチェーン/海外)
    pool = _osint_pool_items()
    vs = [w.lower() for w in (plan.get("valueChain") or []) + (plan.get("globalCatalyst") or [])]
    ss = [w.lower() for w in (plan.get("sector") or [])]
    seen = set()
    for it in pool:
        t = str(it.get("titleJa") or it.get("title") or "")
        tl = t.lower()
        if not t or t in seen:
            continue
        hit_v = any(any(tok in tl for tok in q.split()[:2]) for q in vs[:12]) if vs else False
        hit_s = any(any(tok in tl for tok in q.split()[:1]) for q in ss[:8]) if ss else False
        if not (hit_v or hit_s):
            continue
        seen.add(t)
        cands.append({"titleJa": t, "url": it.get("canonicalUrl") or it.get("url"),
                      "sourceName": it.get("sourceId") or it.get("source"),
                      "publishedAt": it.get("publishedAt"),
                      "directness": "value_chain" if hit_v else "sector_theme"})
        counts["valueChain" if hit_v else "sector"] += 1
        if re.search(r"[A-Za-z]{4,}", t):
            counts["globalNews"] += 1
        else:
            counts["jaNews"] += 1
        if len(cands) >= 24:
            break
    return cands, counts, flow_hint


_OSINT_SCOUT_SYS = ("あなたはOSINT調査員。出力は必ず指定JSONのみ。ソースの捏造禁止。"
                    "根拠のない断定禁止。投資助言・売買指示はしない。")


def _gemini_osint(prompt, benchmark=False, model_override=None,
                  diagnostic_context=None):
    """Gemini scout(検索グラウンディング付き・admin経路のみから呼ばれる)。"""
    if not _cost_policy_authorize(
            "gemini", "research_benchmark" if benchmark else "osint_research",
            automatic=not benchmark, confirmation=benchmark,
            estimated_cost_usd=0.10, estimated_tokens=8000)["allowed"]:
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "deterministic_mode",
                                       "errorClass": "authorization_blocked"})
        return None, "deterministic_mode"
    if not google_genai or not GEMINI_API_KEY:
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "disabled",
                                       "errorClass": "provider_not_configured"})
        return None, "disabled"
    try:
        client = google_genai.Client(api_key=GEMINI_API_KEY)
        cfg = None
        try:
            from google.genai import types as _gt
            benchmark_kwargs = {
                "tools": [_gt.Tool(google_search=_gt.GoogleSearch())],
                "temperature": 0,
                "max_output_tokens": _BENCHMARK_MAX_OUTPUT_TOKENS}
            try:
                benchmark_kwargs["thinking_config"] = _gt.ThinkingConfig(
                    thinking_level="low")
            except (AttributeError, TypeError, ValueError):
                pass
            cfg = (_gt.GenerateContentConfig(**benchmark_kwargs)
                if benchmark else _gt.GenerateContentConfig(
                    tools=[_gt.Tool(google_search=_gt.GoogleSearch())]))
        except Exception:
            cfg = None
        selected_model = model_override or _GEMINI_JUDGE_MODEL
        resp = (client.models.generate_content(model=selected_model,
                                               contents=prompt, config=cfg)
                if cfg else client.models.generate_content(model=selected_model,
                                                           contents=prompt))
        txt = getattr(resp, "text", None) or ""
        out, warns = argus_osint_engine.parse_scout_output(txt)   # v12.1.1 頑健パーサ
        out["parserWarnings"] = warns
        if benchmark:
            usage = _gemini_usage_tokens(resp) or (0, 0)
            out["_providerMeta"] = {
                "provider": "gemini", "apiEndpoint": "models.generateContent",
                "requestedModel": selected_model,
                "responseModel": (getattr(resp, "model_version", None)
                                  or getattr(resp, "model", None)),
                "responseId": getattr(resp, "response_id", None),
                "usage": {"inputTokens": usage[0], "outputTokens": usage[1]},
                "createdAt": _ai_now_iso(),
                "pricingVersion": _BENCHMARK_PRICING_VERSION,
            }
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({
                "status": "ok", "errorClass": None,
                "requestedModel": selected_model,
                "responseModel": ((out.get("_providerMeta") or {})
                                  .get("responseModel")),
                "usage": ((out.get("_providerMeta") or {}).get("usage"))})
        return out, "ok"
    except Exception as e:
        add_log(f"[osint] gemini scout failed: {type(e).__name__}")
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "failed",
                                       "errorClass": type(e).__name__[:80]})
        return None, "failed"


def _gpt_osint(prompt, benchmark=False, diagnostic_context=None):
    """GPT scout(web_search付き・admin経路のみ)。"""
    if not _OPENAI_API_KEY:
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "disabled",
                                       "errorClass": "provider_not_configured"})
        return None, "disabled"
    try:
        full_prompt = prompt + "\n出力は必ず上記JSONを含めること(前置きの説明文があってもよい)。"
        if benchmark:
            txt, execution = _openai_research_ex(
                full_prompt, role="standard", benchmark=True)
            if not txt or execution.get("status") != "ok":
                if isinstance(diagnostic_context, dict):
                    diagnostic_context.update({
                        "status": execution.get("status") or "failed",
                        "errorClass": execution.get("failureReasonRedacted"),
                        "requestedModel": execution.get("requestedModel"),
                        "responseModel": execution.get("responseModel"),
                        "providerResponseStatus": execution.get(
                            "providerResponseStatus")})
                return None, "failed"
        else:
            txt, execution = _openai_research(full_prompt), None
        if not txt:
            return None, "failed"
        out, warns = argus_osint_engine.parse_scout_output(txt)   # v12.1.1 頑健パーサ
        out["parserWarnings"] = warns
        if benchmark:
            out["_providerMeta"] = {
                "provider": "openai", "apiEndpoint": "responses",
                "requestedModel": execution.get("requestedModel"),
                "responseModel": execution.get("responseModel"),
                "responseId": execution.get("responseId"),
                "usage": execution.get("usage"),
                "createdAt": execution.get("completedAt"),
                "pricingVersion": _BENCHMARK_PRICING_VERSION,
            }
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({
                "status": "ok", "errorClass": None,
                "requestedModel": ((out.get("_providerMeta") or {})
                                   .get("requestedModel")),
                "responseModel": ((out.get("_providerMeta") or {})
                                  .get("responseModel")),
                "usage": ((out.get("_providerMeta") or {}).get("usage"))})
        return out, "ok"
    except Exception as e:
        add_log(f"[osint] gpt scout failed: {type(e).__name__}")
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "failed",
                                       "errorClass": type(e).__name__[:80]})
        return None, "failed"


def _osint_agent_run(provider, status, out, now_iso, privacy_mode):
    claims = []
    for c in ((out or {}).get("claims") or [])[:10]:
        if isinstance(c, dict):
            claims.append({k: c.get(k) for k in
                           ("titleJa", "title", "url", "sourceName", "publishedAt",
                            "directness", "summaryJa")})
    return {"provider": provider,
            "modelName": (_GEMINI_JUDGE_MODEL if provider == "gemini" else _OPENAI_MODEL)
            if status == "ok" else None,
            "promptType": "osint_scout", "startedAt": now_iso, "completedAt": now_iso,
            "status": status, "claims": claims,
            "parserWarnings": (out or {}).get("parserWarnings") or [],
            "citedSources": [c.get("url") or c.get("sourceName") for c in claims if c],
            "missingEvidence": (out or {}).get("notFoundJa") or [],
            "failureReasonRedacted": None if status in ("ok", "disabled") else "provider_error",
            "privacyMode": privacy_mode}


def _osint_build(symu, market, mode, privacy_mode, trigger, agent_runs, now_iso):
    prof = _osint_profile(symu, market)
    extra = _OSINT_TERM_OVERLAY.get(symu) or []
    q = get_japan_watchlist_snapshot() if market == "JP" else get_us_watchlist_snapshot()
    chg = None
    for st in (q.get("stocks") or []):
        if str(st.get("symbol", "")).upper() == symu:
            usable = _decision_usable_watch_quote_row(
                st, market, require_latest_completed=True)
            chg = (usable or {}).get("changePct")
            break
    plan = argus_osint_engine.build_query_plan(prof, move_pct=chg, extra_terms=extra)
    cands, counts, flow_hint = _osint_retrieve(symu, market, plan)
    _osint_restore_once()
    pool = _osint_pool_items()
    # 恒久メモリの検証済み公開メタも既知indexへ(過去に回収したGemini-onlyは即verified)
    pool += [{"titleJa": m.get("sourceTitle"), "url": m.get("sourceUrl"),
              "publishedAt": None} for m in _OSINT_MEMORY if m.get("verified")]
    idx = argus_osint_engine.build_known_index(pool)
    verified = [argus_osint_engine.verify_source(c, idx, now_iso) for c in cands]
    # 外部AIの主張も検証(LLM出力は検証まで証拠でない)
    for r in agent_runs:
        for c in (r.get("claims") or []):
            v = argus_osint_engine.verify_source(c, idx, now_iso)
            c["verified"] = v["verificationStatus"] == "verified"
            c["_freshness"] = v["freshness"]
            verified.append(v)
    bench = argus_osint_engine.compare_benchmark(
        [c.get("titleJa") or "" for c in cands], agent_runs)
    inv = argus_osint_engine.build_investigation(
        symbol=symu, asset_name=prof["nameJa"], as_of=now_iso, mode=mode,
        trigger=trigger, privacy_mode=privacy_mode, plan=plan,
        retrieved_counts=counts, verified=verified, agent_runs=agent_runs,
        benchmark=bench, flow_hint=flow_hint,
        canary_degraded=bool((_OSINT_CANARY_LAST.get("data") or {}).get("degraded")))
    # v12.1.2 Part A/G: ギャップ台帳(全ての未回収に理由)+優位性v2
    argus_clusters = argus_osint_engine.cluster_sources(cands)
    theme_ents = set()
    for t in (prof.get("themes") or []) + (prof.get("valueChain") or []) + [prof.get("nameJa") or "", symu]:
        theme_ents |= argus_osint_engine._entities(str(t))
    gap_ledger = []
    for r in agent_runs:
        if r.get("provider") not in ("gemini", "gpt") or r.get("status") != "ok":
            continue
        for c in (r.get("claims") or []):
            t = str(c.get("titleJa") or c.get("title") or "")
            if not t:
                continue
            # v12.1.5 Phase 2: SEAJ型claimの特化解決(公式=industry_forecast)
            ifr = argus_osint_engine.resolve_industry_forecast(
                c, live_meta=_OSINT_URL_CACHE.get(
                    argus_osint_engine._norm_url(c.get("url") or "")) if c.get("url") else None)
            if ifr["matched"]:
                if ifr["sourceType"]:
                    c["sourceType"] = ifr["sourceType"]
                cur = _OSINT_TERM_OVERLAY.get(symu) or []
                _OSINT_TERM_OVERLAY[symu] = (cur + [q for q in ifr["queries"][:4]
                                                    if q not in cur])[:12]
            # v12.1.5 Phase 3: 製品/ニュースclaimは企業ニュースルーム経路で追撃
            elif not c.get("verified") and any(w in t for w in ("発売", "製品", "新型",
                                                                "launch", "release")):
                nq = argus_osint_engine.company_newsroom_queries(c, prof)
                if nq:
                    cur = _OSINT_TERM_OVERLAY.get(symu) or []
                    _OSINT_TERM_OVERLAY[symu] = (cur + [q for q in nq[:3]
                                                        if q not in cur])[:12]
            gap_ledger.append(argus_osint_engine.resolve_gap(
                c, r["provider"], argus_clusters,
                symbol=symu, investigation_id=inv["id"], now_iso=now_iso,
                live_meta=_OSINT_URL_CACHE.get(argus_osint_engine._norm_url(c.get("url") or "")) if c.get("url") else None,
                verification_attempts=int(c.get("_attempts") or 0),
                cap_reached=bool(c.get("_capReached")),
                theme_entities=theme_ents))
    inv["gapLedger"] = gap_ledger[:24]
    # ── v12.1.4 Phase 3: 参照不能ソースの代替回収(合法的な公開経路のみ) ──
    for g in gap_ledger:
        if g.get("resolutionStatus") == "inaccessible":
            th = argus_osint_engine._title_hash(g.get("sourceTitle") or "")
            if th not in _OSINT_INACCESSIBLE_TITLES:
                _OSINT_INACCESSIBLE_TITLES.add(th)
                _OSINT_BLOCKED_RECOVERY["attempted"] += 1
                rq = argus_osint_engine.blocked_source_recovery_queries(
                    g, company_ja=prof.get("nameJa") or "",
                    company_en=prof.get("nameEn") or "")
                if rq:
                    cur = _OSINT_TERM_OVERLAY.get(symu) or []
                    _OSINT_TERM_OVERLAY[symu] = (cur + [t for t in rq if t not in cur])[:12]
        elif g.get("resolutionStatus") == "verified_integrated":
            th = argus_osint_engine._title_hash(g.get("sourceTitle") or "")
            if th in _OSINT_INACCESSIBLE_TITLES:
                _OSINT_INACCESSIBLE_TITLES.discard(th)
                _OSINT_BLOCKED_RECOVERY["recovered"] += 1
    while len(_OSINT_INACCESSIBLE_TITLES) > 60:
        _OSINT_INACCESSIBLE_TITLES.pop()
    # ── v12.1.4 Phase 4: 予備状態の明示(検証前候補は決定的原因になれない) ──
    fresh_candidates = 0
    for v in verified:
        v["preliminaryStatus"] = argus_osint_engine.preliminary_status(v)
        if v["preliminaryStatus"] == "fresh_candidate":
            fresh_candidates += 1
    inv["freshCandidateCount"] = fresh_candidates
    inv["freshCandidateAlertJa"] = (argus_osint_engine.FRESH_CANDIDATE_ALERT_JA
                                    if fresh_candidates else None)
    ver_list = [v for v in verified if v.get("verificationStatus") == "verified"]
    vrate = (len(ver_list) / len(verified)) if verified else 0.0
    ctx_adv = []
    if any(v.get("directness") == "direct_company" and v.get("primaryEligible") for v in verified):
        ctx_adv.append("公式/直接ソース")
    if flow_hint:
        ctx_adv.append("Flow文脈")
    if counts.get("official"):
        ctx_adv.append("公式開示カバレッジ")
    a_keys = {argus_osint_engine._title_hash(c.get("titleJa") or "") for c in cands}
    agent_keys = {argus_osint_engine._title_hash(str(c.get("titleJa") or c.get("title") or ""))
                  for r in agent_runs if r.get("provider") in ("gemini", "gpt") and r.get("status") == "ok"
                  for c in (r.get("claims") or [])}
    ver_keys = {argus_osint_engine._title_hash(v.get("titleJa") or "") for v in ver_list}
    agents_ok = any(r.get("provider") in ("gemini", "gpt") and r.get("status") == "ok"
                    for r in agent_runs)
    sup2 = argus_osint_engine.superiority_v2(
        gap_ledger, agents_ok=agents_ok,
        argus_only_verified=len((a_keys - agent_keys) & ver_keys),
        verified_overlap=len(a_keys & agent_keys & ver_keys),
        context_advantages=ctx_adv,
        coverage_total=inv["coverageScore"]["totalCoverage"],
        verification_rate=vrate)
    # 旧メトリクス(件数系)は残しつつ、判定はv2で上書き
    legacy = argus_osint_engine.superiority_metrics(
        verified, agent_runs, bench, inv["coverageScore"],
        argus_titles=[c.get("titleJa") or "" for c in cands],
        context_added=bool(ctx_adv))
    legacy.update(sup2)
    legacy["argusMissedImportantCount"] = sup2["unresolvedImportant"]
    inv["superiority"] = legacy
    inv["budget"] = dict(argus_osint_engine.OSINT_BUDGETS.get(mode, {}))
    # ── v12.1.3 Phase 2-7: Research Power / 矛盾規律 / 価値連鎖 / ユニバース ──
    try:
        if _supply_demand_signal_for(symu, market).get("level") not in (None, "", "unknown"):
            ctx_adv.append("需給文脈")
    except Exception:
        pass
    try:
        if _official_events_by_symbol(symu):
            ctx_adv.append("イベント文脈")
    except Exception:
        pass
    vc = argus_osint_engine.value_chain_context(
        " ".join((prof.get("themes") or []) + (prof.get("valueChain") or [])))
    if vc:
        ctx_adv.append("バリューチェーン規則")
        # Phase 7: テーマ規則の適用実績を学習(銘柄→テーマの再利用可能な紐付け)
        if not any(m.get("symbol") == symu and m.get("useCase") == "theme_rule"
                   for m in _OSINT_MEMORY):
            rec = argus_osint_engine.memory_record_v2(
                symbol=symu, use_case="theme_rule", theme=vc["labelJa"],
                learned_from="deterministic", verified=True, now_iso=now_iso)
            if rec:
                _OSINT_MEMORY.append(rec)
    inv["valueChainContext"] = vc
    contr = argus_osint_engine.contradiction_report(
        verified, agent_runs, flow_only=bool(flow_hint) and not ver_list)
    # 注意: 既存contradictionReport(string[]・FEが.mapする)とは別キーにする
    inv["contradictionReportV2"] = contr
    learning_updated = any(m.get("symbol") == symu for m in _OSINT_MEMORY)
    agents_configured = bool(_OPENAI_API_KEY or (google_genai and GEMINI_API_KEY))
    universe = argus_osint_engine.source_universe_status(agents_configured=agents_configured)
    missing_n = sum(1 for u in universe if u["availability"] in ("unavailable", "agents_not_configured"))
    inv["sourceUniverse"] = universe
    # Phase 3差分: この調査で実際に見たカテゴリ(checkedの捏造なし)+主張ガード
    # macro_calendarは公式イベントパイプラインが常時稼働のためchecked
    src_cov = argus_osint_engine.investigation_source_coverage(
        counts, verified, agent_runs, events_checked=True)
    inv["sourceCoverage"] = src_cov
    inv["coverageGuardsJa"] = argus_osint_engine.coverage_claim_guards(src_cov)
    cov_missing = sum(1 for r in src_cov if r["coverageImpact"] == "lowers_score")
    # Phase 4差分: バリューチェーングラフ(不完全は正直表示・保有情報なし)
    inv["valueChainGraph"] = argus_osint_engine.value_chain_graph(prof)
    # v12.1.5 Phase 5: 因果関連度(検証済み=真実であって主因ではない)
    relevances = []
    for v in verified:
        rel = argus_osint_engine.causal_relevance(
            v, theme_entities=theme_ents, flow_hint=flow_hint,
            event_near="イベント文脈" in ctx_adv)
        v["causalRelevance"] = rel["relevance"]
        v["causalReasonJa"] = rel["ownerReadableReasonJa"]
        relevances.append(rel)
    causal_sum = argus_osint_engine.causal_relevance_summary(relevances)
    inv["causalRelevanceSummary"] = causal_sum
    # v12.1.5 Phase 1: 一次ソース取得チェック+不在主張ガード
    pchecks = argus_osint_engine.primary_source_checks(
        prof, plan, verified, counts, events_checked=True)
    pguards = argus_osint_engine.primary_absence_guards(pchecks)
    inv["primarySourceChecks"] = pchecks
    inv["primaryAbsenceGuardsJa"] = pguards
    # v12.1.5 Phase 6: ソース取得レポート
    inv["sourceAcquisitionReport"] = argus_osint_engine.source_acquisition_report(
        pchecks, src_cov, pguards + inv.get("coverageGuardsJa", []))
    # ── v12.2.0 Phase 5: 公式文書/SEAJ v3/ペアリング/開示/ウォーム ──
    official_docs, pairings = [], 0
    all_claims = list(cands) + [c for r in agent_runs
                                for c in (r.get("claims") or [])]
    for c in all_claims:
        u = c.get("url")
        if not u:
            continue
        rec = argus_osint_engine.official_document_record(
            url=u, title=c.get("titleJa") or c.get("title") or "",
            published_at=c.get("publishedAt"), now_iso=now_iso,
            live_meta=_OSINT_URL_CACHE.get(argus_osint_engine._norm_url(u)),
            theme_entities=theme_ents)
        if rec:
            official_docs.append(rec)
    inv["officialDocuments"] = official_docs[:10]
    seaj_pairs = []
    for r in agent_runs:
        for c in (r.get("claims") or []):
            t = str(c.get("titleJa") or c.get("title") or "")
            if argus_osint_engine.industry_forecast_claim_match(t):
                sr = argus_osint_engine.seaj_official_resolve(c, all_claims, now_iso)
                if sr.get("pairing") and sr["pairing"].get("supportsClaim"):
                    seaj_pairs.append(sr["pairing"])
                    pairings += 1
                if sr.get("sourceType"):
                    c["sourceType"] = sr["sourceType"]
    inv["sourcePairings"] = seaj_pairs[:6]
    try:
        ev = _official_events_by_symbol(symu) or []
        inv["disclosureCheck"] = argus_osint_engine.disclosure_check_record(
            status="checked", result_count=len(ev),
            latest_date=(ev[0].get("date") if ev else None),
            relevant_count=len(ev))
    except Exception:
        inv["disclosureCheck"] = argus_osint_engine.disclosure_check_record(
            status="unavailable")
    try:
        _pool_n = len(_osint_pool_items())
        _intel_age = None
        _ts = (_INTEL_LAST or {}).get("ts")
        if _ts:
            _intel_age = max(0.0, (time.time() - float(_ts)) / 60.0)
        inv["storeWarmth"] = argus_osint_engine.warmth_status(
            pool_count=_pool_n, intel_age_min=_intel_age,
            memory_count=len(_OSINT_MEMORY))
    except Exception:
        inv["storeWarmth"] = argus_osint_engine.warmth_status(
            pool_count=0, intel_age_min=None, memory_count=0)
    rps = argus_osint_engine.research_power_score(
        verified=verified, agent_runs=agent_runs, gap_ledger=gap_ledger,
        coverage=inv["coverageScore"], contradiction=contr,
        context_advantages=ctx_adv,
        source_universe_missing=min(3, missing_n // 3) + min(2, cov_missing),
        learning_updated=learning_updated,
        kwargs_recovery={"attempted": _OSINT_BLOCKED_RECOVERY["attempted"],
                         "recovered": _OSINT_BLOCKED_RECOVERY["recovered"],
                         "freshCandidates": fresh_candidates},
        causal_summary=causal_sum, primary_checks=pchecks,
        baseline_info=argus_osint_engine.baseline_from_runs(_baseline_current_epoch()),
        warmth=inv["storeWarmth"], official_docs=official_docs,
        pairings=pairings)
    inv["researchPower"] = rps
    # v12.1.5 Phase 7: オーナー結論(曖昧な原因未特定を出さない)
    inv["ownerConclusion"] = argus_osint_engine.owner_conclusion(
        verified=verified, relevances=relevances, rps=rps,
        gap_summary=argus_osint_engine.gap_ledger_summary(gap_ledger),
        context_advantages=ctx_adv, agent_runs=agent_runs)
    # Phase 7差分: Research Powerスコア履歴(公開安全・有界・スナップショット同乗)
    if rps.get("status") != "insufficient_data":
        _OSINT_RPS_HISTORY.append({
            "symbol": symu, "at": now_iso, "status": rps["status"],
            "argusScore": rps["argusScore"],
            "geminiBaselineScore": rps["geminiBaselineScore"],
            "epochId": _current_epoch_id(),
            "warm": (inv.get("storeWarmth") or {}).get("storeWarmth"),
            "ratio": rps.get("argusVsGeminiRatio")})
        while len(_OSINT_RPS_HISTORY) > 40:
            _OSINT_RPS_HISTORY.pop(0)
    _osint_persist()
    # missed-by-argus → 探索語オーバーレイに自動追加(有界)
    if bench.get("missedByArgusCount"):
        terms = argus_osint_engine.extract_expansion_terms(agent_runs, cap=4)
        cur = _OSINT_TERM_OVERLAY.get(symu) or []
        _OSINT_TERM_OVERLAY[symu] = (cur + [t for t in terms if t not in cur])[:12]
    _OSINT_STORE[symu] = inv
    while len(_OSINT_STORE) > _OSINT_STORE_MAX:
        _OSINT_STORE.pop(next(iter(_OSINT_STORE)), None)
    return inv


def _osint_next_cron_eta_min():
    """caos-scan cron(毎時:00/:30)までの分数 — 「いつ反映されるか」を正直に出す。"""
    try:
        now = datetime.now(pytz.utc)
        mins = now.minute
        nxt = 30 if mins < 30 else 60
        return max(1, nxt - mins)
    except Exception:
        return None


@app.route("/api/argus/osint/deep-dive", methods=["POST"])
def api_argus_osint_deep_dive():
    """公開POST: 決定論OSINT(計画+cached収集+検証+採点)のみ実行し、
    Gemini/GPTスカウトはキューに積むだけ(外部AIはここから絶対に呼ばれない)。"""
    body = request.get_json(silent=True) or {}
    sym = str(body.get("symbol") or "").strip().upper()
    if not sym:
        return jsonify({"error": "symbol_required"}), 400
    mkt = str(body.get("market") or ("JP" if sym[:1].isdigit() else "US")).upper()
    mode = body.get("mode") if body.get("mode") in argus_osint_engine.MODES else "deep"
    priv = body.get("privacyMode") if body.get("privacyMode") in argus_osint_engine.PRIVACY_MODES else "redacted"
    now_iso = _ai_now_iso()
    queued = [{"provider": p, "status": "queued"} for p in ("gemini", "gpt")]
    agent_runs = [_osint_agent_run("deterministic", "ok", None, now_iso, priv)]
    for qr in queued:
        agent_runs.append({**_osint_agent_run(qr["provider"], "disabled", None, now_iso, priv),
                           "status": ("queued" if (_OPENAI_API_KEY if qr["provider"] == "gpt"
                                                   else (google_genai and GEMINI_API_KEY))
                                      else "disabled")})
    # v12.1.1 Part E: 二重実行防止 — 既にキュー済み/実行中なら新規jobを作らない
    pr = _OSINT_PROGRESS.get(sym) or {}
    if sym in _OSINT_AGENT_QUEUE or pr.get("stage") in (
            "planning", "gemini_scout", "gpt_scout", "verification", "research_loop"):
        pos = (list(_OSINT_AGENT_QUEUE.keys()).index(sym) + 1
               if sym in _OSINT_AGENT_QUEUE else 0)
        return jsonify({"ok": True, "investigation": _OSINT_STORE.get(sym),
                        "duplicate": True, "progress": pr,
                        "queuePosition": pos, "nextCronEtaMin": _osint_next_cron_eta_min(),
                        "agentNoteJa": "すでに調査ジョブが進行中です(二重実行はしません)。"})
    inv = _osint_build(sym, mkt, mode, priv, "owner_request", agent_runs, now_iso)
    if len(_OSINT_AGENT_QUEUE) < _OSINT_QUEUE_MAX:
        _OSINT_AGENT_QUEUE[sym] = {"market": mkt, "mode": mode,
                                   "privacyMode": priv, "queuedAt": now_iso}
    _osint_set_progress(sym, "queued_for_agents", 0,
                        _OSINT_LOOP_BUDGET.get(mode, 2),
                        "決定論調査は完了。Gemini/GPTスカウトは管理側cronで実行されます。")
    _OSINT_LAST["deepAt"] = now_iso
    return jsonify({"ok": True, "investigation": inv,
                    "progress": _OSINT_PROGRESS.get(sym),
                    "queuePosition": list(_OSINT_AGENT_QUEUE.keys()).index(sym) + 1,
                    "nextCronEtaMin": _osint_next_cron_eta_min(),
                    "agentNoteJa": "Gemini/GPTスカウトはキュー済み(管理側の定期実行で反映・"
                                   "公開画面から外部AIは起動しません)。"})


def _public_scalar_fields(source, names):
    """Copy only named JSON scalars for a public product DTO."""
    row = source if isinstance(source, dict) else {}
    return {
        name: row.get(name) if isinstance(
            row.get(name), (str, int, float, bool, type(None))) else None
        for name in names
    }


def _public_string_list(value, limit=24):
    return [item[:500] for item in (value if isinstance(value, list) else [])
            if isinstance(item, str)][:limit]


def _public_osint_source(row):
    if not isinstance(row, dict):
        return None
    return _public_scalar_fields(row, (
        "titleJa", "url", "sourceName", "publishedAt", "ageHours",
        "freshness", "directness", "verificationStatus", "labelJa",
        "primaryEligible", "supportStrength", "sourceType",
        "causalRelevance",
    ))


def _public_osint_investigation(investigation):
    """Fixed public product projection; private/future fields fail closed.

    The internal investigation may contain owner terms, raw agent claims,
    private-mode markers, and future model metadata.  This route preserves the
    verified public market-research product while constructing every nested
    response family from an explicit key list.
    """
    if not isinstance(investigation, dict):
        return None
    inv = investigation
    out = _public_scalar_fields(inv, (
        "schemaVersion", "id", "symbol", "assetName", "asOf", "mode",
        "modeJa", "investigationQuestionJa", "ownerReadableSummaryJa",
        "freshCandidateCount", "freshCandidateAlertJa", "costLabelJa",
        "complianceNote",
    ))

    query = inv.get("queryPlan") if isinstance(inv.get("queryPlan"), dict) else {}
    out["queryPlan"] = {
        "queryCount": query.get("queryCount") if isinstance(
            query.get("queryCount"), int) and not isinstance(
                query.get("queryCount"), bool) else 0,
        **{key: _public_string_list(query.get(key), 32)
           for key in ("direct", "sector", "valueChain", "globalCatalyst",
                       "negative")},
    }

    # Agent status is public product health; raw claims/model output are not.
    out["agentRuns"] = [
        _public_scalar_fields(row, ("provider", "status"))
        for row in (inv.get("agentRuns") or [])[:4] if isinstance(row, dict)
    ]
    out["verifiedSources"] = [projected for projected in (
        _public_osint_source(row) for row in (inv.get("verifiedSources") or [])[:10]
    ) if projected is not None]
    # Unverified agent claims are deliberately not a public product payload.
    out["rejectedSources"] = []

    verdict = inv.get("catalystVerdict")
    out["catalystVerdict"] = _public_scalar_fields(verdict, (
        "verdict", "verdictJa", "primaryCauseJa", "confidence",
        "sourceDiversity", "directEvidencePresent", "ownerReadableJa",
        "whyThisMightBeWrongJa",
    ))
    verdict = verdict if isinstance(verdict, dict) else {}
    for key in ("secondaryCausesJa", "rejectedCausesJa", "missingEvidenceJa"):
        out["catalystVerdict"][key] = _public_string_list(verdict.get(key), 8)

    out["contradictionReport"] = _public_string_list(
        inv.get("contradictionReport"), 12)
    out["missingAreasJa"] = _public_string_list(inv.get("missingAreasJa"), 12)
    # Expansion terms can originate in raw model/owner input; keep them private.
    out["nextResearchJa"] = []

    out["coverageScore"] = _public_scalar_fields(inv.get("coverageScore"), (
        "directCompanyCoverage", "officialDisclosureCoverage",
        "sectorCoverage", "valueChainCoverage", "globalNewsCoverage",
        "japaneseNewsCoverage", "agentCoverage", "totalCoverage",
        "totalCoverageJa",
    ))
    out["reliabilityScore"] = _public_scalar_fields(
        inv.get("reliabilityScore"), (
            "sourceFreshness", "sourceDiversity", "verificationRate",
            "directEvidence", "contradictionPenalty", "dataQualityPenalty",
            "overall", "overallJa",
        ))
    benchmark = inv.get("benchmark")
    out["benchmark"] = _public_scalar_fields(benchmark, (
        "argusCount", "geminiCount", "gptCount", "overlapCount",
        "geminiOnlyCount", "gptOnlyCount", "argusOnlyCount",
        "missedByArgusCount",
    ))
    benchmark = benchmark if isinstance(benchmark, dict) else {}
    out["benchmark"]["notesJa"] = _public_string_list(
        benchmark.get("notesJa"), 12)

    superiority = inv.get("superiority")
    out["superiority"] = _public_scalar_fields(superiority, (
        "superiorityStatus", "superiorityJa", "ownerReadableVerdictJa",
        "unresolvedImportant", "argusOnlyVerifiedCount",
        "verifiedOverlapCount", "sourceVerificationRate", "contextEdgeJa",
    )) if isinstance(superiority, dict) else None
    if isinstance(out["superiority"], dict):
        out["superiority"]["gapProgressLinesJa"] = _public_string_list(
            superiority.get("gapProgressLinesJa"), 12)

    power = inv.get("researchPower")
    out["researchPower"] = _public_scalar_fields(power, (
        "geminiBaselineScore", "gptBaselineScore",
        "bestExternalBaselineScore", "argusScore", "argusVsGeminiRatio",
        "argusVsBestExternalRatio", "status", "statusJa", "displayJa",
        "ownerReadableVerdictJa", "baselineType", "baselineLabelJa",
        "baselineConfidence", "baselineRunCount", "ratioConfidence",
        "ratioLabelJa", "publicResearchRatio",
    )) if isinstance(power, dict) else None
    if isinstance(out["researchPower"], dict):
        out["researchPower"]["blockersJa"] = _public_string_list(
            power.get("blockersJa"), 8)
        out["researchPower"]["strengthsJa"] = _public_string_list(
            power.get("strengthsJa"), 8)

    out["gapLedger"] = []
    for gap in (inv.get("gapLedger") or [])[:24]:
        if not isinstance(gap, dict):
            continue
        projected = _public_scalar_fields(gap, (
            "id", "claimType", "resolutionStatus", "resolutionStatusJa",
            "providedBy", "verificationAttempts", "confidenceImpact",
        ))
        # Do not expose raw agent title, URL, claim, or owner-readable reason.
        projected.update({"sourceTitle": "非公開候補", "sourceUrl": None,
                          "resolutionReasonJa": "詳細は運用診断で確認"})
        out["gapLedger"].append(projected)

    out["sourceCoverage"] = [
        _public_scalar_fields(row, (
            "key", "labelJa", "state", "resultCount", "coverageImpact"))
        for row in (inv.get("sourceCoverage") or [])[:32]
        if isinstance(row, dict)
    ]
    out["coverageGuardsJa"] = _public_string_list(
        inv.get("coverageGuardsJa"), 12)
    graph = inv.get("valueChainGraph")
    out["valueChainGraph"] = _public_scalar_fields(graph, (
        "symbol", "company", "sector", "incomplete", "incompleteNoteJa",
    )) if isinstance(graph, dict) else None
    if isinstance(out["valueChainGraph"], dict):
        for key in ("products", "technologies", "competitors",
                    "adjacentThemes", "globalRelatedCompanies",
                    "macroSensitivities", "queryExpansions"):
            out["valueChainGraph"][key] = _public_string_list(graph.get(key), 24)
    context = inv.get("valueChainContext")
    out["valueChainContext"] = _public_scalar_fields(context, (
        "theme", "labelJa", "cautionJa",
    )) if isinstance(context, dict) else None
    if isinstance(out["valueChainContext"], dict):
        out["valueChainContext"]["queryExpansions"] = _public_string_list(
            context.get("queryExpansions"), 20)
    report = inv.get("contradictionReportV2")
    out["contradictionReportV2"] = _public_scalar_fields(report, (
        "directEvidenceAbsent", "themeInferenceOnly", "priceOnlyNarrativeRisk",
        "agentDisagreement", "staleEvidencePresent", "unsupportedClaims",
    )) if isinstance(report, dict) else None
    if isinstance(out["contradictionReportV2"], dict):
        out["contradictionReportV2"]["ownerReadableWarningsJa"] = \
            _public_string_list(report.get("ownerReadableWarningsJa"), 12)
    out["sourceUniverse"] = [
        _public_scalar_fields(row, ("key", "labelJa", "availability", "noteJa"))
        for row in (inv.get("sourceUniverse") or [])[:32]
        if isinstance(row, dict)
    ]
    out["primarySourceChecks"] = [
        _public_scalar_fields(row, (
            "sourceCategory", "sourceCategoryJa", "status", "resultCount",
            "verifiedResultCount", "ownerReadableJa"))
        for row in (inv.get("primarySourceChecks") or [])[:32]
        if isinstance(row, dict)
    ]
    out["primaryAbsenceGuardsJa"] = _public_string_list(
        inv.get("primaryAbsenceGuardsJa"), 12)
    causal = inv.get("causalRelevanceSummary")
    out["causalRelevanceSummary"] = _public_scalar_fields(causal, (
        "hasHighRelevance", "weakCausalOnly", "ownerReadableJa",
    )) if isinstance(causal, dict) else None
    # OwnerConclusion and private-mode/source-acquisition detail remain internal.
    out["ownerConclusion"] = None
    out["budget"] = _public_scalar_fields(inv.get("budget"), (
        "maxUrls", "maxLoops", "maxSeconds", "maxCostLabel",
    )) if isinstance(inv.get("budget"), dict) else None
    return out


def _public_osint_progress(progress):
    if not isinstance(progress, dict):
        return None
    out = _public_scalar_fields(progress, ("stage", "loop", "maxLoops", "at"))
    out["notesJa"] = []
    autopilot = progress.get("autopilot")
    out["autopilot"] = _public_scalar_fields(autopilot, (
        "doneCount", "totalStages", "status",
    )) if isinstance(autopilot, dict) else None
    return out


@app.route("/api/argus/osint/investigation")
def api_argus_osint_investigation():
    """公開GET: 最新のOSINT調査(cached-only・redacted設計)。無ければ正直にnone。"""
    sym = str(request.args.get("symbol") or "").strip().upper()
    _osint_restore_once()
    inv = _OSINT_STORE.get(sym)
    return jsonify({"status": "live" if inv else "none", "symbol": sym or None,
                    "investigation": _public_osint_investigation(inv),
                    "progress": _public_osint_progress(_OSINT_PROGRESS.get(sym)),
                    "queuePosition": (list(_OSINT_AGENT_QUEUE.keys()).index(sym) + 1
                                      if sym in _OSINT_AGENT_QUEUE else None),
                    "nextCronEtaMin": _osint_next_cron_eta_min() if sym in _OSINT_AGENT_QUEUE else None,
                    "noteJa": None if inv else "深掘りOSINTは未実行です。"})


@app.route("/api/argus/osint/terms", methods=["POST"])
def api_argus_osint_terms():
    """公開POST(enqueueのみ): オーナー貼り戻しから抽出した探索語の追加。
    本文は受け取らない — 語(≤8個・各≤40字)だけ。私的情報はここに来ない設計。"""
    body = request.get_json(silent=True) or {}
    sym = str(body.get("symbol") or "").strip().upper()
    if not sym or not _JP_SYM_RE.match(sym) and not _US_SYM_RE.match(sym):
        return jsonify({"error": "symbol_invalid"}), 400
    terms = []
    for t in (body.get("terms") or [])[:8]:
        w = str(t).strip()[:40]
        if w and not w.lower().startswith("http") and len(w) >= 2:
            terms.append(w)
    cur = _OSINT_TERM_OVERLAY.get(sym) or []
    _OSINT_TERM_OVERLAY[sym] = (cur + [t for t in terms if t not in cur])[:12]
    while len(_OSINT_TERM_OVERLAY) > 16:
        _OSINT_TERM_OVERLAY.pop(next(iter(_OSINT_TERM_OVERLAY)), None)
    return jsonify({"ok": True, "storedTerms": _OSINT_TERM_OVERLAY[sym],
                    "noteJa": "今後の探索語に追加しました(貼り戻し本文はサーバーに保存しません)。"})


def _osint_set_progress(sym, stage, loop=0, max_loops=0, note=None):
    pr = _OSINT_PROGRESS.setdefault(sym, {"notesJa": []})
    pr.update({"stage": stage, "loop": loop, "maxLoops": max_loops, "at": _ai_now_iso()})
    if note:
        pr["notesJa"] = (pr.get("notesJa") or [])[-4:] + [note]


def _osint_autopilot_mark(sym, *keys):
    """v12.1.3 Phase 5: Autopilot 14段階の完了マーク(進捗はGET investigationで可視)。"""
    pr = _OSINT_PROGRESS.setdefault(sym, {"notesJa": []})
    done = pr.setdefault("autopilotDone", [])
    for k in keys:
        if k not in done:
            done.append(k)
    pr["autopilot"] = argus_osint_engine.autopilot_progress(done)


def _osint_autopilot_fail(sym, stage_key, reason_ja):
    pr = _OSINT_PROGRESS.setdefault(sym, {"notesJa": []})
    pr["autopilot"] = argus_osint_engine.autopilot_progress(
        pr.get("autopilotDone") or [], failed_stage=stage_key,
        fail_reason_ja=reason_ja)


def _osint_agents_worker(syms):
    """バックグラウンドでGemini/GPTスカウト→検証→再探索ループを実行。
    v12.1.1: Gemini-onlyの未回収claimに追撃クエリ+URLライブ検証で回収を試み、
    昇格件数/未回収件数を進捗として正直に出す。"""
    results = []
    try:
        for sym in syms:
            now_iso = _ai_now_iso()
            meta = _OSINT_AGENT_QUEUE.pop(sym, None) or {
                "market": "JP" if sym[:1].isdigit() else "US",
                "mode": "deep", "privacyMode": "redacted"}
            max_loops = _OSINT_LOOP_BUDGET.get(meta.get("mode"), 2)
            _osint_set_progress(sym, "planning", 0, max_loops)
            _OSINT_PROGRESS.setdefault(sym, {"notesJa": []})["autopilotDone"] = []
            prof = _osint_profile(sym, meta["market"])
            _osint_autopilot_mark(sym, "profile")
            plan = argus_osint_engine.build_query_plan(
                prof, extra_terms=_OSINT_TERM_OVERLAY.get(sym) or [])
            _osint_autopilot_mark(sym, "query_plan")
            runs = [_osint_agent_run("deterministic", "ok", None, now_iso,
                                     meta["privacyMode"])]
            for prov, caller in (("gemini", _gemini_osint), ("gpt", _gpt_osint)):
                _osint_set_progress(sym, f"{prov}_scout", 0, max_loops)
                prompt = argus_osint_engine.build_scout_prompt(
                    prov, prof, plan, move_pct=None,
                    privacy_mode=meta["privacyMode"])
                out, status = caller(prompt)
                run_rec = _osint_agent_run(prov, status, out, now_iso,
                                           meta["privacyMode"])
                runs.append(run_rec)
                _osint_autopilot_mark(sym, f"scout_{prov}")
                # v12.1.6: Gemini基準run記録(同一ルーブリック採点・public-safe)
                if prov == "gemini" and status == "ok":
                    _OSINT_BASELINE_RUNS.append({
                        "score": argus_osint_engine.external_rubric_score(
                            run_rec.get("claims") or []),
                        "case": sym, "symbol": sym, "at": _ai_now_iso(),
                        "promptVersion": argus_osint_engine.SCOUT_PROMPT_VERSION,
                        "epochId": argus_ai_gate.model_epoch_id(
                            provider="gemini", model=GEMINI_MODEL_ID,
                            prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
                            tool_mode="grounding"),
                        "privacyMode": meta["privacyMode"]})
                    while len(_OSINT_BASELINE_RUNS) > 24:
                        _OSINT_BASELINE_RUNS.pop(0)
            _osint_autopilot_mark(sym, "parse_normalize")
            try:
                _OSINT_PARSER_HEALTH["lastWarnings"] = [
                    w for r in runs for w in (r.get("parserWarnings") or [])]
                _OSINT_PARSER_HEALTH["at"] = now_iso
            except Exception:
                pass
            _osint_set_progress(sym, "verification", 0, max_loops)
            inv = _osint_build(sym, meta["market"], meta["mode"],
                               meta["privacyMode"], "admin_agents_run", runs, now_iso)
            _osint_autopilot_mark(sym, "internal_retrieval", "clustering",
                                  "gap_resolution")

            # ── v12.1.1 Part D: 反復再探索(未回収Gemini/GPT-onlyの回収) ──
            for loop_i in range(1, max_loops + 1):
                argus_titles = [v.get("titleJa") or "" for v in inv["evidenceLedger"]]
                unresolved = argus_osint_engine.unresolved_agent_claims(runs, argus_titles)
                if not unresolved:
                    break
                _osint_set_progress(sym, "research_loop", loop_i, max_loops,
                                    f"再探索{loop_i}/{max_loops}: Gemini-onlyニュースを回収中(未回収: {len(unresolved)}件)")
                promoted = 0
                budget = argus_osint_engine.OSINT_BUDGETS.get(meta.get("mode"), {})
                max_urls = int(budget.get("maxUrls") or 4)
                # ①URLライブ検証で昇格を試みる(公開メタのみ・ペイウォール本文なし)
                # v12.1.2: モード別予算(war_room=20) — 上限到達は「未回収」でなく明示
                with_url = [c for c in unresolved if c.get("url")]
                for c in with_url[:max_urls]:
                    vtmp = argus_osint_engine.verify_source(
                        c, argus_osint_engine.build_known_index([]), _ai_now_iso())
                    v2 = _osint_live_upgrade(vtmp, c, _ai_now_iso(), sym=sym)
                    c["_attempts"] = int(c.get("_attempts") or 0) + 1
                    if v2.get("verificationStatus") == "verified":
                        c["verified"] = True
                        promoted += 1
                if len(with_url) > max_urls:
                    for c in with_url[max_urls:]:
                        c["_capReached"] = True
                    _OSINT_CAP_REACHED["count"] += len(with_url) - max_urls
                    _osint_set_progress(sym, "research_loop", loop_i, max_loops,
                                        f"検証上限到達: 残り{len(with_url) - max_urls}件(予算 maxUrls={max_urls})")
                # ①b オーナー依頼のURL検証キューも同予算内で消化
                while _OSINT_URL_QUEUE and max_urls > 0:
                    qurl = _OSINT_URL_QUEUE.pop(0)
                    _osint_fetch_url_meta(qurl)
                    max_urls -= 1
                # ②追撃語で決定論再探索(学習語にも積む)
                follow = argus_osint_engine.followup_queries(unresolved)
                if follow:
                    cur = _OSINT_TERM_OVERLAY.get(sym) or []
                    _OSINT_TERM_OVERLAY[sym] = (cur + [t for t in follow if t not in cur])[:12]
                    # Phase 7: 追撃語の学習(query_expansion・有界)
                    for t in follow[:2]:
                        rec = argus_osint_engine.memory_record_v2(
                            symbol=sym, use_case="query_expansion", query_term=t,
                            learned_from="deterministic", verified=False,
                            now_iso=_ai_now_iso())
                        if rec and not any(m.get("id") == rec["id"] for m in _OSINT_MEMORY):
                            _OSINT_MEMORY.append(rec)
                inv = _osint_build(sym, meta["market"], meta["mode"],
                                   meta["privacyMode"], "admin_agents_run", runs,
                                   _ai_now_iso())
                still = inv["superiority"]["argusMissedImportantCount"]
                _osint_set_progress(sym, "research_loop", loop_i, max_loops,
                                    f"検証済みに昇格: {promoted}件 / 未回収: {still}件")
                _osint_autopilot_mark(sym, "url_verification", "re_search")
                if promoted == 0 and not follow:
                    break
            _osint_set_progress(sym, "synthesis", max_loops, max_loops)
            _osint_autopilot_mark(sym, "url_verification", "re_search",
                                  "contradiction_check", "context_integration",
                                  "scoring", "report")
            _osint_set_progress(sym, "complete", max_loops, max_loops,
                                inv["superiority"]["ownerReadableVerdictJa"])
            results.append(sym)
            add_log(f"[osint] agents done {sym}: {inv['superiority']['superiorityStatus']}")
        _OSINT_LAST["agentsAt"] = _ai_now_iso()
        _OSINT_LAST["agentsStatus"] = "ok" if results else "empty"
        _osint_persist()
    except Exception as e:
        _OSINT_LAST["agentsStatus"] = f"failed:{type(e).__name__}"
        for sym in syms:
            _osint_set_progress(sym, "failed", 0, 0, f"スカウト実行失敗({type(e).__name__})")
            # v12.1.3 Phase 5: failed_safe — 途中結果は保持・嘘の完了は返さない
            pr = _OSINT_PROGRESS.get(sym) or {}
            done = pr.get("autopilotDone") or []
            nxt = next((k for k, _ in argus_osint_engine.AUTOPILOT_STAGES
                        if k not in done), "report")
            _osint_autopilot_fail(sym, nxt, f"実行失敗({type(e).__name__}) — 途中結果は保持")
        add_log(f"[osint] agents worker failed: {type(e).__name__}")


@app.route("/api/argus/admin/osint/agents-run", methods=["POST"])
def api_argus_admin_osint_agents_run():
    """Admin/cron: キュー済み銘柄のGemini/GPTスカウトを実行(予算: 1回3銘柄まで)。
    外部AI呼び出しはこの経路だけ。v12.1.0実測でGemini+GPT逐次は180秒超になり
    HTTPが切られたため非同期(202)実行 — 完了はDQ osintHealth.lastAgentsRunAtと
    /osint/investigationで確認。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    skipped = _scheduled_ai_skip("gemini", "osint_research")
    if skipped:
        _OSINT_LAST["agentsStatus"] = "deterministic_mode"
        return jsonify(skipped)
    try:
        body = request.get_json(silent=True) or {}
        target = str(body.get("symbol") or "").strip().upper()
        syms = [target] if target else list(_OSINT_AGENT_QUEUE.keys())[:3]
        if not syms:
            _OSINT_LAST["agentsStatus"] = "empty"
            return jsonify({"ok": True, "started": [], "queuedRemaining": 0,
                            "noteJa": "キューは空(外部AIは呼ばれていません)。"})
        _OSINT_LAST["agentsStatus"] = "running"
        import threading
        threading.Thread(
            target=_memory_operation_run,
            args=("background", "osint_agents_worker",
                  _osint_agents_worker, syms), daemon=True).start()
        return jsonify({"ok": True, "started": syms,
                        "queuedRemaining": max(0, len(_OSINT_AGENT_QUEUE) - len(syms)),
                        "noteJa": "バックグラウンドで実行中(結果は/osint/investigationに反映)。"}), 202
    except Exception as e:
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {str(e)[:120]}"}), 200


_FORECAST_LEDGER = []                  # v12.2.0 不変予測台帳(append-only・有界200)
_OUTCOME_LEDGER = []                   # 成果レコード(append-only・有界200)
_DL_JOBS = []                          # 24x365ジョブ台帳(有界60)


def _current_epoch_id():
    return argus_ai_gate.model_epoch_id(
        provider="gemini", model=GEMINI_MODEL_ID,
        prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
        tool_mode="grounding")


def _baseline_current_epoch():
    """v12.2.2: 基準runを現行エポックに限定 — 旧エポック(v12.1.7の0.92x等)は
    legacy履歴であり現行比に混入させない。"""
    return argus_ai_gate.filter_runs_to_epoch(
        _OSINT_BASELINE_RUNS, _current_epoch_id())


def _baseline_legacy_runs():
    cur = _current_epoch_id()
    return [r for r in _OSINT_BASELINE_RUNS if r.get("epochId") != cur]


_MISSIONS = []                          # v12.2.1 永続ミッション台帳(有界300)
_MISSION_WINDOWS = []                   # v12.3.1 30分tick冪等window(有界240)
_POSTMORTEMS = []                       # 日次ポストモーテム(有界30)
_PERIODIC_REPORTS = []                  # 週次/月次レポート(有界12)
_CHALLENGER_RUNS = []                   # shadow challenger評価(有界8)
# v12.2.9: build-scoped soak — 新build SHAは旧buildのsoak時計を継承しない。
# startedAtは自然EC2 mission windowのscheduledAtと一致し、
# boot/復元完了より前のwindowはsoak_start_decisionが拒否する。
_SOAK = {"soakId": None, "buildSha": None, "buildShaFull": None,
         "appVersion": None, "processBootId": None,
         "processBootedAt": None,
         "startedAt": None, "startReason": None, "startTimeSource": None,
         "startedBy": None, "firstMissionWindowId": None,
         "completed72h": False, "interruptionCount": 0,
         "interruptions": [], "previousSoak": None, "heartbeats": [],
         "state": "not_started", "lastHeartbeatAt": None,
         "lastHeartbeatSource": None}
_SOAK_HISTORY = []                     # archived copies; never edited in place
_SOAK_CONTROL = {"armed": False, "armedAt": None, "armedBuildSha": None,
                 "armId": None, "reason": None,
                 "plannedRestartMarker": None}
_INCIDENTS = []                         # 見逃し/回収インシデント(有界20)
def _semantic_app_version():
    """Backendのセマンティック版。frontend package版から独立させる。"""
    return argus_release_identity.backend_version()


def _frontend_semantic_version():
    """同じcheckoutに同梱されたfrontend版。live Pages SHAはCI証拠を正本とする。"""
    return argus_release_identity.frontend_version()


_OPS_JOURNAL = []                       # v12.2.7 運用イベントジャーナル(有界400)
_OPS_SEQ = {}                           # aggregate毎の単調sequence


_OPS_JOURNAL_META = {"totalObserved": 0}   # v12.2.9: compact後も歴代件数を失わない
_OPS_JOURNAL_COMPACT = []                  # v12.2.10: 非critical・ack済みの決定論バッチ
# v12.2.10: 検証済みread-back ack(復元時刻プロキシの廃止) — remote_committedは
# 「ledgerから読み戻したsnapshotに当該冪等キー+一致hashが存在」した場合のみ。
_REMOTE_ACK = {"ackedKeys": [], "lastVerifiedRemoteAckAt": None,
               "lastReceiptStatus": None, "remoteGeneratedAt": None,
               "legacyRemote": False, "maxObservedLagSec": 0,
               "readbackFailures": 0, "outcomeAckedIds": [],
               "lastVerifiedOutcomeReadBackAt": None}
_REMOTE_CYCLE = {"remoteCommitSha": None, "committedAt": None,
                 "readBackAt": None, "readBackVerified": False,
                 "walReadBackVerified": False,
                 "expectedHash": None, "actualHash": None,
                 "remoteWalAppliedSequence": 0,
                 "verifiedWalSequence": 0,
                 "compactReceiptHash": None,
                 "pendingCount": 0, "acknowledgedCount": 0,
                 "remoteDurabilityState": "not_started",
                 "receiptCommitSha": None, "receiptCreatedAt": None,
                 "receiptVerifiedAt": None, "receiptAgeSeconds": None,
                 "receiptAttempts": 0, "receiptErrorClass": None,
                 "errorClass": None, "walErrorClass": None}

# Outcome再解決ポリシー。intervalは環境変数で調整可。期限は既存ポリシーが
# 無かったため既定0=失効無効。運用合意後のみ正数へ設定する。
def _outcome_policy_seconds(name, default, minimum):
    try:
        return max(minimum, int(os.environ.get(name, "") or default))
    except (TypeError, ValueError):
        return default


def _outcome_restore_is_newer(existing, incoming):
    """復元側の古いunresolvedでローカルresolvedを巻き戻さない。"""
    if existing.get("status") == "resolved":
        return False
    if incoming.get("status") == "resolved":
        return True
    return (int(incoming.get("retryCount") or 0) >
            int(existing.get("retryCount") or 0) or
            str(incoming.get("lastRetryAt") or "") >
            str(existing.get("lastRetryAt") or ""))


_OUTCOME_RETRY_INTERVAL_SECONDS = max(
    60, _outcome_policy_seconds("ARGUS_OUTCOME_RETRY_INTERVAL_SECONDS", 1800, 60))
_OUTCOME_RETRY_EXPIRE_SECONDS = _outcome_policy_seconds(
    "ARGUS_OUTCOME_RETRY_EXPIRE_SECONDS", 0, 0)


def _journal_aggregate_patch(agg_type, agg_id, payload):
    record = None
    if agg_type == "mission":
        record = next((row for row in _MISSIONS
                       if str(row.get("missionId")) == str(agg_id)), None)
    elif agg_type == "outcome":
        record = next((row for row in _OUTCOME_LEDGER
                       if str(row.get("forecastId")) == str(agg_id)), None)
    elif agg_type == "forecast":
        outcome_id = str((payload or {}).get("outcomeId") or "")
        record = next((row for row in reversed(_FORECAST_LEDGER)
                       if str(row.get("id")) == outcome_id), None)
        if record is None:
            symbol = str((payload or {}).get("symbol") or "")
            target = str((payload or {}).get("targetType") or "")
            record = next((row for row in reversed(_FORECAST_LEDGER)
                           if str(row.get("symbol")) == symbol and
                           str(row.get("targetType")) == target), None)
    elif agg_type == "incident":
        record = next((row for row in _INCIDENTS
                       if str(row.get("id")) == str(agg_id)), None)
    elif agg_type == "soak":
        record = _SOAK
    return ({"type": agg_type, "record": copy.deepcopy(record)}
            if isinstance(record, dict) else None)


def _append_tick_wal(kind, payload):
    if not _mission_tick_context_active():
        return None
    sequence = int(_MISSION_TICK_CONTEXT.get("walSequence") or 0) + 1
    measurement = _recovery_phase_a_begin_wal_observation(kind)
    started = time.monotonic()
    record = argus_tick_durability.append_wal(
        _MISSION_WAL_FILE, sequence=sequence, kind=kind,
        payload=payload, job_id=str(_MISSION_TICK_CONTEXT.get("jobId") or
                                    "mission-tick"),
        mission_window_id=_MISSION_TICK_CONTEXT.get("missionWindowId"),
        build_sha=os.environ.get("RENDER_GIT_COMMIT") or _backend_sha())
    append_elapsed_ms = (time.monotonic() - started) * 1000
    measurement = _recovery_phase_a_complete_wal_observation(
        measurement, sequence)
    try:
        _MISSION_TICK_CONTEXT["walSequence"] = sequence
        _MISSION_TICK_CONTEXT["walEventCount"] = int(
            _MISSION_TICK_CONTEXT.get("walEventCount") or 0) + 1
        _MISSION_TICK_CONTEXT["walAppendMs"] = round(
            float(_MISSION_TICK_CONTEXT.get("walAppendMs") or 0) +
            append_elapsed_ms, 3)
        lease = _MISSION_TICK_CONTEXT.get("lease")
        if lease is not None:
            lease.heartbeat()
    finally:
        _recovery_phase_a_finish_wal_observation(measurement, sequence)
    return record


def _persist_mission_transition(mission, cursor=None):
    """Fsync a small replayable transition before the request acknowledges it."""
    def _persist_transition():
        if cursor is not None:
            _MISSION_BATCH_STATE["cursor"] = max(
                int(_MISSION_BATCH_STATE.get("cursor") or 0), int(cursor))
        _append_tick_wal("mission_transition", {
            "transitionState": {
                "mission": copy.deepcopy(mission),
                "postmortems": copy.deepcopy(_POSTMORTEMS[-30:]),
                "periodicReports": copy.deepcopy(_PERIODIC_REPORTS[-12:]),
                "challengerRuns": copy.deepcopy(_CHALLENGER_RUNS[-8:]),
                "agentQueue": copy.deepcopy(_OSINT_AGENT_QUEUE),
                "batch": dict(_MISSION_BATCH_STATE),
            }})

    return _memory_operation_run(
        "internal", "mission.persist_transition", _persist_transition)


def _bound_ops_sequence_allocator_state():
    """Install one deterministic bounded allocator projection in memory."""
    bounded, meta = argus_remote_journal.bounded_sequence_allocator_state(
        sequences=_OPS_SEQ, events=_OPS_JOURNAL, meta=_OPS_JOURNAL_META)
    _OPS_SEQ.clear()
    _OPS_SEQ.update(bounded)
    _OPS_JOURNAL_META.clear()
    _OPS_JOURNAL_META.update(meta)
    return bounded


def _next_ops_sequence(aggregate_key):
    """Allocate without reuse after encrypted recovery bounding is active."""
    high_water_field = argus_remote_journal.OPS_SEQUENCE_HIGH_WATER_FIELD
    if high_water_field not in _OPS_JOURNAL_META:
        sequence = int(_OPS_SEQ.get(aggregate_key) or 0) + 1
        _OPS_SEQ[aggregate_key] = sequence
        return sequence
    high_water = _OPS_JOURNAL_META.get(high_water_field)
    sequence = argus_remote_journal.next_bounded_ops_sequence(
        aggregate_key=aggregate_key, sequences=_OPS_SEQ,
        meta=_OPS_JOURNAL_META)
    _OPS_SEQ[aggregate_key] = sequence
    _OPS_JOURNAL_META[high_water_field] = max(high_water, sequence)
    if len(_OPS_SEQ) > \
            argus_remote_journal.OPS_SEQUENCE_BY_AGGREGATE_LIMIT:
        _bound_ops_sequence_allocator_state()
    return sequence


def _journal(event_type, agg_type, agg_id, payload, origin="scheduler"):
    """クリティカル遷移の即時ジャーナル(ローカル即時+30分ledger flush)。
    遷移コードからのみ呼ぶ — Data Quality等の公開GETからは呼ばない。"""
    measurement = _recovery_phase_a_begin_journal_observation()
    authority_completed = False
    sequence = None
    try:
        key = f"{agg_type}:{agg_id}"
        sequence = _next_ops_sequence(key)
        ev = argus_state_journal.event(
            event_type=event_type, aggregate_type=agg_type,
            aggregate_id=agg_id, sequence=sequence,
            occurred_at=_ai_now_iso(), payload=payload, origin=origin)
        if argus_state_journal.append(_OPS_JOURNAL, ev):
            _OPS_JOURNAL_META["totalObserved"] += 1
            if _mission_tick_context_active():
                _append_tick_wal("journal_transition", {
                    "journalEvent": copy.deepcopy(ev),
                    "aggregatePatch": _journal_aggregate_patch(
                        agg_type, agg_id, payload)})
                authority_completed = True
            else:
                checkpoint = _osint_persist()
                authority_completed = bool(
                    isinstance(checkpoint, dict) and
                    checkpoint.get("verified") is True)
    except Exception:
        if _mission_tick_context_active():
            raise
    if authority_completed:
        _recovery_phase_a_finish_journal_observation(
            measurement, sequence)


# ── v12.2.9 Runtime Truth: 起動アイデンティティ/即時復元/readyz ────────────────

def _backend_sha():
    return os.environ.get("RENDER_GIT_COMMIT", "")[:7] or None


def _backend_exact_sha():
    value = os.environ.get("RENDER_GIT_COMMIT", "").strip().lower()
    return value if re.fullmatch(r"[0-9a-f]{40}", value) else None


def _recovery_phase_a_instance():
    """Initialize the optional adapter once; never affect runtime authority."""
    global _RECOVERY_PHASE_A_ADAPTER
    current = _RECOVERY_PHASE_A_ADAPTER
    if current is _RECOVERY_PHASE_A_UNAVAILABLE:
        return None
    if current is not None:
        return current
    with _RECOVERY_PHASE_A_INIT_LOCK:
        current = _RECOVERY_PHASE_A_ADAPTER
        if current is _RECOVERY_PHASE_A_UNAVAILABLE:
            return None
        if current is not None:
            return current
        try:
            current = argus_recovery_phase_a_adapter.RecoveryPhaseAAdapter(
                producer_build_sha=_backend_exact_sha(),
                started_at=datetime.now(pytz.utc),
                feature_flag_value=os.environ.get(
                    argus_recovery_phase_a_adapter.FEATURE_FLAG_NAME))
        except Exception:
            _RECOVERY_PHASE_A_ADAPTER = _RECOVERY_PHASE_A_UNAVAILABLE
            return None
        _RECOVERY_PHASE_A_ADAPTER = current
        return current


def _recovery_phase_a_null_proof():
    """Obtain only the adapter's no-input, fail-closed proof document."""
    fallback = {"status": "NOT_PROVEN", "hardRpoClaimPermitted": False}
    try:
        result = argus_recovery_phase_a_adapter.null_recovery_proof_document()
        if type(result) is dict and set(result) == set(fallback) and \
                result.get("status") == "NOT_PROVEN" and \
                result.get("hardRpoClaimPermitted") is False:
            return dict(result)
    except Exception:
        pass
    return fallback


def _recovery_phase_a_bind_null_proof(payload):
    """Reapply null truth to an existing fixed-shape diagnostics DTO."""
    try:
        if type(payload) is not dict:
            return payload
        result = None
        for container_name in ("recovery", "features"):
            target = payload.get(container_name)
            if type(target) is not dict:
                continue
            if "exactColdRecovery" in target:
                result = result or _recovery_phase_a_null_proof()
                target["exactColdRecovery"] = result["status"]
            if "hardRpoClaimPermitted" in target:
                result = result or _recovery_phase_a_null_proof()
                target["hardRpoClaimPermitted"] = \
                    result["hardRpoClaimPermitted"]
    except Exception:
        pass
    return payload


def _recovery_phase_a_scalar(value):
    return value if type(value) is int and 0 <= value <= (1 << 53) - 1 \
        else None


def _recovery_phase_a_peak_rss_bytes():
    """Return ru_maxrss in bytes (Darwin reports bytes; Linux reports KiB)."""
    try:
        raw = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        if type(raw) not in (int, float) or isinstance(raw, bool) or raw < 0:
            return None
        value = int(raw) if sys.platform == "darwin" else int(raw * 1024)
        return _recovery_phase_a_scalar(value)
    except Exception:
        return None


def _recovery_phase_a_datetime(value):
    if type(value) is datetime and value.tzinfo is not None:
        return value
    if type(value) is not str or len(value) > 40:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None else None


def _recovery_phase_a_elapsed_micros(started_ns):
    if type(started_ns) is not int:
        return 0
    return min((1 << 53) - 1,
               max(0, (time.monotonic_ns() - started_ns) // 1000))


def _recovery_phase_a_file_size(path):
    try:
        size = os.path.getsize(path)
    except OSError:
        return None
    return _recovery_phase_a_scalar(size)


def _recovery_phase_a_pre_authority_observer_enabled():
    """Pure gate: never acquire an optional diagnostics lock before authority."""
    try:
        adapter = _RECOVERY_PHASE_A_ADAPTER
        return bool(
            adapter is not None and
            adapter is not _RECOVERY_PHASE_A_UNAVAILABLE and
            os.environ.get(
                argus_recovery_phase_a_adapter.FEATURE_FLAG_NAME) ==
            argus_recovery_phase_a_adapter.FEATURE_FLAG_ENABLED_VALUE and
            _backend_exact_sha() is not None)
    except Exception:
        return False


def _recovery_phase_a_begin_wal_observation(kind):
    """Prepare an optional scalar observation without touching WAL authority."""
    try:
        mutation_class_id = {
            "mission_transition": "core.mission_transition",
            "batch_cursor": "core.batch_cursor",
        }.get(kind)
        if mutation_class_id is None or not \
                _recovery_phase_a_pre_authority_observer_enabled():
            return None
        cursor_sequence = _recovery_phase_a_scalar(
            _MISSION_TICK_CONTEXT.get("recoveryMeasurementWalSequence"))
        current_sequence = _recovery_phase_a_scalar(
            _MISSION_TICK_CONTEXT.get("walSequence"))
        before_bytes = _recovery_phase_a_scalar(
            _MISSION_TICK_CONTEXT.get("recoveryMeasurementWalBytes")) \
            if cursor_sequence == current_sequence else None
        return (mutation_class_id,
                before_bytes,
                time.monotonic_ns())
    except Exception:
        return None


def _recovery_phase_a_complete_wal_observation(observation, sequence):
    """Freeze append-only scalars immediately after WAL authority returns."""
    try:
        if type(observation) is not tuple or len(observation) != 3:
            return None
        mutation_class_id, before_bytes, started_ns = observation
        completed_ns = time.monotonic_ns()
        after_bytes = _recovery_phase_a_file_size(_MISSION_WAL_FILE)
        if after_bytes is not None:
            _MISSION_TICK_CONTEXT["recoveryMeasurementWalBytes"] = after_bytes
            _MISSION_TICK_CONTEXT["recoveryMeasurementWalSequence"] = sequence
        estimated_bytes = max(0, after_bytes - before_bytes) if \
            before_bytes is not None and after_bytes is not None else 0
        latency_micros = min(
            (1 << 53) - 1, max(0, (completed_ns - started_ns) // 1000))
        return mutation_class_id, estimated_bytes, latency_micros
    except Exception:
        return None


def _recovery_phase_a_finish_wal_observation(observation, sequence):
    """Record only after the existing WAL path has completed successfully."""
    try:
        if type(observation) is not tuple or len(observation) != 3:
            return
        mutation_class_id, estimated_bytes, latency_micros = observation
        if mutation_class_id not in (
                "core.mission_transition", "core.batch_cursor"):
            return
        _recovery_phase_a_record(
            mutation_class_id,
            estimated_plaintext_bytes=estimated_bytes,
            record_count=1,
            latency_micros=latency_micros,
            observed_at=datetime.now(pytz.utc),
            local_sequence=sequence)
    except Exception:
        pass


def _recovery_phase_a_begin_journal_observation():
    try:
        if not _recovery_phase_a_pre_authority_observer_enabled():
            return None
        return time.monotonic_ns()
    except Exception:
        return None


def _recovery_phase_a_finish_journal_observation(started_ns, sequence=None):
    try:
        if type(started_ns) is not int:
            return
        _recovery_phase_a_record(
            "core.ops_journal_transition",
            estimated_plaintext_bytes=0, record_count=1,
            latency_micros=_recovery_phase_a_elapsed_micros(started_ns),
            observed_at=datetime.now(pytz.utc),
            local_sequence=_recovery_phase_a_scalar(sequence))
    except Exception:
        pass


def _recovery_phase_a_record(
        mutation_class_id, *, estimated_plaintext_bytes=0, record_count=1,
        latency_micros=0, observed_at=None, local_sequence=None):
    """Send bounded scalars after authority; swallow every adapter failure."""
    try:
        adapter = _recovery_phase_a_instance()
        if adapter is None:
            return
        observed = observed_at or datetime.now(pytz.utc)
        if _recovery_phase_a_datetime(observed) is None:
            return
        adapter.record_mutation_after_authority(
            mutation_class_id,
            estimated_plaintext_bytes=estimated_plaintext_bytes,
            record_count=record_count, latency_micros=latency_micros,
            observed_at=observed, local_sequence=local_sequence)
    except Exception:
        pass


def _recovery_phase_a_take_checkpoint():
    try:
        return _RECOVERY_PHASE_A_CHECKPOINT_LOCAL.__dict__.pop(
            "pending", None)
    except Exception:
        return None


def _recovery_phase_a_abandon_checkpoint():
    pending = _recovery_phase_a_take_checkpoint()
    if type(pending) is not tuple or not pending:
        return
    try:
        adapter = _recovery_phase_a_instance()
        if adapter is not None:
            adapter.abandon_checkpoint(pending[0])
    except Exception:
        pass


def _recovery_phase_a_prepare_checkpoint(
        sealed_checkpoint, *, seal_duration_micros,
        wal_bytes, wal_records, wal_high_water):
    """Account the exact live sealed mapping and retain scalar results only."""
    _recovery_phase_a_abandon_checkpoint()
    adapter = None
    sampling = None
    try:
        jp_boundary = _MISSION_TICK_CONTEXT.get(
            "recoveryMeasurementJPPostSession") is True
        us_boundary = _MISSION_TICK_CONTEXT.get(
            "recoveryMeasurementUSPostSession") is True
        owner_authorized = _MISSION_TICK_CONTEXT.get(
            "recoveryMeasurementOwnerAuthorized") is True
        _MISSION_TICK_CONTEXT["recoveryMeasurementJPPostSession"] = False
        _MISSION_TICK_CONTEXT["recoveryMeasurementUSPostSession"] = False
        _MISSION_TICK_CONTEXT["recoveryMeasurementOwnerAuthorized"] = False
        adapter = _recovery_phase_a_instance()
        if adapter is None:
            return
        observed = datetime.now(pytz.utc)
        sampling = adapter.checkpoint_sampling_decision(
            observed_at=observed,
            jp_session_boundary=jp_boundary,
            us_session_boundary=us_boundary,
            owner_authorized=owner_authorized)
        if sampling.generation_id is None:
            return
        accounting = adapter.account_checkpoint(
            sealed_checkpoint, sampling) if sampling.requested else None
        bounded = tuple(
            value if _recovery_phase_a_scalar(value) is not None else 0
            for value in (
                seal_duration_micros, wal_bytes,
                wal_records, wal_high_water))
        _RECOVERY_PHASE_A_CHECKPOINT_LOCAL.pending = (
            sampling, accounting, *bounded)
    except Exception:
        _recovery_phase_a_take_checkpoint()
        try:
            if adapter is not None and sampling is not None:
                adapter.abandon_checkpoint(sampling)
        except Exception:
            pass


def _recovery_phase_a_finalize_checkpoint(checkpoint):
    """Persist diagnostics only after existing checkpoint authority unlocks."""
    pending = _recovery_phase_a_take_checkpoint()
    if type(pending) is not tuple or len(pending) != 6:
        return
    sampling, accounting, seal_micros, pre_wal_bytes, \
        pre_wal_records, pre_wal_high_water = pending
    adapter = None
    try:
        adapter = _recovery_phase_a_instance()
        if adapter is None or type(checkpoint) is not dict or \
                checkpoint.get("verified") is not True:
            return
        snapshot_bytes = _recovery_phase_a_scalar(
            checkpoint.get("snapshotBytes"))
        if snapshot_bytes is None:
            return
        wal = checkpoint.get("walCompaction")
        if type(wal) is dict:
            local_wal_bytes = _recovery_phase_a_scalar(wal.get("bytes"))
            local_wal_records = _recovery_phase_a_scalar(
                wal.get("remainingRecords"))
            local_wal_high_water = _recovery_phase_a_scalar(
                wal.get("receiptSequence"))
        else:
            local_wal_bytes = local_wal_records = local_wal_high_water = None
        local_wal_bytes = pre_wal_bytes if local_wal_bytes is None \
            else local_wal_bytes
        local_wal_records = pre_wal_records if local_wal_records is None \
            else local_wal_records
        local_wal_high_water = pre_wal_high_water \
            if local_wal_high_water is None else local_wal_high_water
        observed = datetime.now(pytz.utc)
        ack_sequence = _recovery_phase_a_scalar(
            _REMOTE_CYCLE.get("verifiedWalSequence"))
        ack_at = _recovery_phase_a_datetime(
            _REMOTE_ACK.get("lastVerifiedRemoteAckAt"))
        if _REMOTE_CYCLE.get("readBackVerified") is not True or \
                ack_sequence is None or ack_at is None or \
                ack_sequence > local_wal_high_water or ack_at > observed:
            ack_sequence = None
            ack_at = None
        peak_rss = _recovery_phase_a_peak_rss_bytes()
        adapter.record_checkpoint_after_authority(
            observed_at=observed, sampling=sampling,
            accounting=accounting,
            checkpoint_serialized_bytes=snapshot_bytes,
            serialization_duration_micros=(
                argus_recovery_phase_a_adapter.UNOBSERVED_DURATION_MICROS),
            write_seal_duration_micros=seal_micros,
            fsync_readback_duration_micros=(
                argus_recovery_phase_a_adapter
                .UNOBSERVED_FSYNC_READBACK_DURATION_MICROS),
            peak_rss_bytes=peak_rss,
            local_wal_bytes=local_wal_bytes,
            local_wal_records=local_wal_records,
            local_wal_high_water=local_wal_high_water,
            legacy_remote_ack_sequence=ack_sequence,
            legacy_remote_ack_at=ack_at)
    except Exception:
        pass
    finally:
        # Success consumes the token in the adapter; every other return or
        # exception is explicitly released. Abandon-after-consume is a
        # bounded no-op.
        try:
            if adapter is not None:
                adapter.abandon_checkpoint(sampling)
        except Exception:
            pass


def _recovery_phase_a_mark_post_session(mission):
    """Mark only an already-persisted JP/US post-session mission."""
    try:
        if type(mission) is not dict or \
                mission.get("missionType") != "post_session_snapshot":
            return
        market = mission.get("market")
        if market == "JP":
            _MISSION_TICK_CONTEXT["recoveryMeasurementJPPostSession"] = True
        elif market == "US":
            _MISSION_TICK_CONTEXT["recoveryMeasurementUSPostSession"] = True
    except Exception:
        pass


def _recovery_phase_a_record_verified_receipt(result, observed_at):
    """Observe only the already-completed verified receipt-drain boundary."""
    try:
        if type(result) is not dict or result.get("status") != "verified":
            return
        record_count = _recovery_phase_a_scalar(
            result.get("coalescedReceiptCount"))
        duration_ms = result.get("flushDurationMs")
        latency_micros = 0
        if type(duration_ms) in (int, float) and \
                not isinstance(duration_ms, bool) and \
                math.isfinite(duration_ms) and duration_ms >= 0:
            latency_micros = min(
                (1 << 53) - 1, int(round(duration_ms * 1000)))
        _recovery_phase_a_record(
            "durability.receipt_ack", estimated_plaintext_bytes=0,
            record_count=record_count if record_count is not None else 0,
            latency_micros=latency_micros,
            observed_at=_recovery_phase_a_datetime(observed_at) or
                datetime.now(pytz.utc),
            local_sequence=_recovery_phase_a_scalar(
                result.get("verifiedWalSequence")))
    except Exception:
        pass


def _recovery_phase_a_owner_sampling_authorized(body, admin_authorized):
    """Require the existing server-side admin gate and exact build pin."""
    try:
        if admin_authorized is not True or type(body) is not dict or \
                body.get("diagnostic") is not True:
            return False
        expected = str(body.get("expectedBuildSha") or "").lower()
        return bool(re.fullmatch(r"[0-9a-f]{40}", expected) and
                    expected == str(_backend_exact_sha() or "").lower())
    except Exception:
        return False


def _recovery_phase_a_record_startup_if_ready():
    global _RECOVERY_PHASE_A_STARTUP_RECORDED
    if _STARTUP.get("state") not in ("ready", "ready_degraded"):
        return
    with _RECOVERY_PHASE_A_INIT_LOCK:
        if _RECOVERY_PHASE_A_STARTUP_RECORDED:
            return
        _RECOVERY_PHASE_A_STARTUP_RECORDED = True
    duration_ms = _recovery_phase_a_scalar(
        _STARTUP.get("restoreDurationMs"))
    duration_micros = min(
        (1 << 53) - 1, (duration_ms or 0) * 1000)
    observed = _recovery_phase_a_datetime(
        _STARTUP.get("restoreCompletedAt")) or datetime.now(pytz.utc)
    sequence = _recovery_phase_a_scalar(
        _MISSION_BATCH_STATE.get("walAppliedSequence"))
    _recovery_phase_a_record(
        "startup.restore_transition", estimated_plaintext_bytes=0,
        record_count=1, latency_micros=duration_micros,
        observed_at=observed, local_sequence=sequence)


_RUNTIME = {"processBootedAt": datetime.now(TZ_JST).isoformat(),
            "bootId": os.urandom(4).hex(),
            "firstHealthAt": None, "firstReadyAt": None,
            "buildFirstObservedAt": None}
_STARTUP = {"state": "bootstrapping", "restoreStartedAt": None,
            "restoreCompletedAt": None, "restoreDurationMs": None,
            "restoreOutcome": None, "soakRestoreAction": None,
            "blockerJa": None}
_SERVER_RUNTIME = {"serverType": "unknown", "workers": None, "threads": None,
                   "startupMode": "lazy_first_request"}
_SHUTDOWN = {"done": False, "requested": False, "requestedAt": None,
             "signal": None, "walSynced": False, "cursorSaved": False}


def _validate_durable_storage():
    global _DURABLE_STORAGE_STATUS
    try:
        _DURABLE_STORAGE_STATUS = argus_persistent_storage.validate_storage(
            _DURABILITY_PATHS, production=_DURABILITY_PRODUCTION,
            approved_root=("/var/data" if _DURABILITY_PRODUCTION else None))
        reconciliation = _DURABLE_STORAGE_STATUS.get(
            "abandonedTempReconciliation") or {}
        if int(reconciliation.get("removedCount") or 0) > 0:
            print(json.dumps({
                "event": "abandoned_checkpoint_temp_reconciled",
                "removedCount": reconciliation.get("removedCount"),
                "retainedCount": reconciliation.get("retainedCount"),
                "entries": [
                    {key: row.get(key) for key in (
                        "name", "writerPid", "bytes", "device", "inode",
                        "mtimeNs", "ctimeNs", "writerHasOpenInode",
                        "exclusiveLockAcquired", "removed")}
                    for row in (reconciliation.get("entries") or [])
                    if row.get("removed")
                ],
            }, sort_keys=True), flush=True)
        return True
    except argus_persistent_storage.PersistentStorageError as exc:
        _DURABLE_STORAGE_STATUS = {
            "valid": False,
            "errorClass": exc.error_class,
            "errorReason": exc.reason,
            "runtimeVerified": False,
        }
        return False
    except Exception as exc:
        _DURABLE_STORAGE_STATUS = {
            "valid": False,
            "errorClass": "persistent_storage_unavailable",
            "errorReason": type(exc).__name__,
            "runtimeVerified": False,
        }
        return False


def _startup_bootstrap():
    """プロセス起動毎に1回の決定論的復元(30分cronを待たない)。冪等 —
    2回目以降・繰り返しGETは状態を変えない。復元不能でもローカル
    last-known-goodを破壊しない。"""
    if _STARTUP["state"] != "bootstrapping":
        return
    _recovery_phase_a_instance()
    _STARTUP["state"] = "loading_local"
    _STARTUP["restoreStartedAt"] = _ai_now_iso()
    if not _RUNTIME["buildFirstObservedAt"]:
        _RUNTIME["buildFirstObservedAt"] = _STARTUP["restoreStartedAt"]
    storage_valid = _validate_durable_storage()
    if _DURABILITY_PRODUCTION and not storage_valid:
        _STARTUP.update({
            "state": "failed_safe",
            "restoreOutcome": "persistent_storage_unavailable",
            "blockerJa": "永続ストレージ検証失敗 — mission tick停止",
            "restoreCompletedAt": _ai_now_iso(),
        })
        return
    try:
        _STARTUP["state"] = "loading_remote"
        _osint_restore_once()
        # Event state is part of process bootstrap, never an incidental public
        # status-read side effect. The restore also warms _EVENT_SNAP_META.
        _events_restore_once()
        if _AI_JUDGE_ENABLED and (_OPENAI_API_KEY or GEMINI_API_KEY):
            _ai_cached_result()
        _STARTUP["state"] = "reconciling"      # 冪等キー照合は復元内で実施済み
    except Exception:
        pass
    _STARTUP["restoreCompletedAt"] = _ai_now_iso()
    try:
        _STARTUP["restoreDurationMs"] = int(
            (datetime.fromisoformat(
                _STARTUP["restoreCompletedAt"].replace("Z", "+00:00"))
             - datetime.fromisoformat(
                 _STARTUP["restoreStartedAt"].replace("Z", "+00:00")))
            .total_seconds() * 1000)
    except Exception:
        pass
    integ = _DURABLE_STATE.get("integrityStatus")
    if _DURABLE_STATE.get("lastRestoreAt"):
        _STARTUP["restoreOutcome"] = "restored"
        if integ == "unknown":          # 復元成功(parse+journal検証済み)=ok
            _DURABLE_STATE["integrityStatus"] = "ok"
        _STARTUP["state"] = "ready"
    elif integ == "corrupt_ignored" and not _DURABILITY_PRODUCTION:
        _STARTUP["restoreOutcome"] = "corrupt_last_known_good"
        _STARTUP["blockerJa"] = "復元snapshotが破損 — last-known-goodで稼働(degraded)"
        _STARTUP["state"] = "ready_degraded"
    else:
        _STARTUP["restoreOutcome"] = "no_prior_state"
        if _DURABILITY_PRODUCTION:
            _STARTUP["state"] = "failed_safe"
            _STARTUP["blockerJa"] = (
                "検証済みRemote Journal snapshotなし — 空状態を作らず停止")
        else:
            _STARTUP["state"] = "ready"
    if not _RUNTIME["firstReadyAt"]:
        _RUNTIME["firstReadyAt"] = _STARTUP["restoreCompletedAt"]
    if _STARTUP.get("soakRestoreAction") in (
            "inherit_with_interruption", "terminalize_interrupted"):
        _journal("soak_interrupted", "soak",
                 _SOAK.get("soakId") or
                 (_SOAK.get("previousSoak") or {}).get("soakId") or
                 "soak-unscoped",
                 {"detectedAt": _RUNTIME["processBootedAt"],
                  "buildSha": _SOAK.get("buildSha") or
                  (_SOAK.get("previousSoak") or {}).get("buildSha") or
                  "unknown"})
    _recovery_phase_a_record_startup_if_ready()


@app.before_request
def _bootstrap_hook():
    """最初のリクエストで起動復元を確定(Renderのhealthcheckで即時発火)。
    2回目以降はフラグ確認のみ — GETは復元を再実行/変更しない。"""
    # Export endpoints are deliberately not startup triggers.  Their route
    # handlers return a bounded 503 until WSGI/health boot has installed
    # authority, so unauthenticated proof probes cannot initiate cold restore.
    if request.path in {
            "/api/argus/osint/remote-readback",
            "/api/argus/admin/remote-journal/recovery-sidecar"}:
        return None
    if _STARTUP["state"] == "bootstrapping":
        _startup_bootstrap()


def _formal_soak_is_active(soak=None):
    candidate = soak if isinstance(soak, dict) else _SOAK
    state = str(candidate.get("terminalState") or
                candidate.get("state") or "not_started")
    return bool(candidate.get("soakId") and candidate.get("startedAt") and
                state not in ("interrupted", "completed", "failed",
                              "superseded", "operationally_verified"))


def _formal_soak_public_projection():
    """Return bounded control/runtime/history truth without changing state."""
    active = _formal_soak_is_active()
    decision = argus_checkpoint_v2_stage1.formal_soak_start_eligibility(
        _CHECKPOINT_V2_STAGE1_CONTROL,
        checkpoint_v2_enabled=_CHECKPOINT_V2_STAGE1_ENABLED,
        trigger_source="none", qualified_natural_tick=False,
        mission_window_id=None,
        current_build_sha=_backend_exact_sha() or None,
        expected_build_sha=_backend_exact_sha() or None,
        active_soak_exists=active,
        active_soak_id=_SOAK.get("soakId"))
    history = []
    for row in _SOAK_HISTORY[-8:]:
        if not isinstance(row, dict):
            continue
        history.append({
            "soakId": row.get("soakId"),
            "startedAt": row.get("startedAt"),
            "state": (row.get("terminalState") or row.get("state")),
            "completed72h": bool(row.get("completed72h")),
        })
    arm_state = (_CHECKPOINT_V2_STAGE1_CONTROL.get("formalSoakState") or
                 "not_started")
    runtime_state = ((_SOAK.get("terminalState") or _SOAK.get("state"))
                     if _SOAK.get("soakId") else "not_started")
    return {
        "checkpointMode": (
            _CHECKPOINT_V2_STAGE1_CONTROL.get("checkpointMode")
            if _CHECKPOINT_V2_STAGE1_ENABLED else "legacy_only"),
        "armed": bool(_CHECKPOINT_V2_STAGE1_CONTROL.get(
            "formalSoakArmed")),
        "armState": arm_state,
        "activeRuntime": {
            "active": active,
            "soakId": _SOAK.get("soakId"),
            "state": runtime_state,
            "startedAt": _SOAK.get("startedAt"),
            "completed72h": bool(_SOAK.get("completed72h")),
        },
        "history": history,
        "eligible": decision["eligible"],
        "blockers": decision["blockers"],
        "eligibilityEvidence": decision["evidence"],
    }


@app.route("/readyz")
def readyz():
    """Minimal public readiness/build identity with unchanged 200/503 truth."""
    now_iso = _ai_now_iso()
    ready, reason_code = _diagnostic_readiness_truth()
    code = 200 if ready else 503
    try:
        payload = argus_diagnostics_contract.build_public_readiness(
            generated_at=now_iso,
            backend_version=_semantic_app_version(),
            build_sha=_backend_exact_sha(), ready=ready,
            reason_code=reason_code)
    except Exception:
        payload = {
            "schemaVersion": "argus-public-readiness-v1",
            "generatedAt": now_iso,
            "ready": False,
            "status": "not_ready",
            "reasonCode": "NOT_READY",
            "backendVersion": "unknown",
            "buildSha": None,
        }
        code = 503
    return jsonify(payload), code


# v12.2.9 Phase 8: オーナー設定の真実性 — 手動確認はowner_attested(期限90日)。
# runtime_verifiedとは主張しない(サーバから外部管理設定を検証できない)。
# 恒久ハードコード真実にしない: 期限切れで自動的に再確認要求へ落ちる。
# 再確認時は環境変数 ARGUS_ATTEST_*(ISO日時)で更新可能(本タスクでは未設定)。
_OWNER_ATTESTATIONS = {
    "github_branch_ruleset": "2026-07-14T00:00:00+09:00",
    "render_after_ci_checks": "2026-07-14T00:00:00+09:00",
}


def _owner_controls_status():
    out = []
    for _c, _default in _OWNER_ATTESTATIONS.items():
        _at = os.environ.get("ARGUS_ATTEST_" + _c.upper()) or _default
        out.append(argus_runtime.owner_control_status(
            control=_c, attested_at=_at, ttl_days=90, now_iso=_ai_now_iso(),
            evidence_ref="owner-manual-confirmation(v12.2.9タスク申告)"))
    return out


# ── v12.2.10: 検証済みread-back ack+compaction(tick=30分cron文脈から実行) ──

def _remote_commit_readback_url(commit_sha):
    """Return immutable GitHub raw URL; a moving branch is never evidence."""
    if not re.fullmatch(r"[0-9a-f]{40}", str(commit_sha or "").lower()):
        return None
    repository = os.environ.get(
        "LEDGER_RAW_REPOSITORY_BASE",
        "https://raw.githubusercontent.com/mitsugue/argus").rstrip("/")
    return (f"{repository}/{str(commit_sha).lower()}"
            f"/ledger{_REMOTE_READBACK_PATH}")


def _remote_readback_ack(now_iso=None, blob=None):
    """ledgerへ実際にコミットされたsnapshotを読み戻し、ローカルWALイベントの
    冪等キー+整合hashを照合してackを導出する。復元時刻・HTTP書込成功は
    ackにならない。冪等 — 再実行してもackは重複しない。"""
    now_iso = now_iso or _ai_now_iso()
    commit_sha = str(_REMOTE_CYCLE.get("remoteCommitSha") or "").lower()
    attempts_used = 0
    if blob is None:
        url = _remote_commit_readback_url(commit_sha)
        if url is None:
            _REMOTE_CYCLE.update({
                "readBackAt": now_iso, "readBackVerified": False,
                "remoteDurabilityState": "receipt_missing",
                "receiptAttempts": 0,
                "receiptErrorClass": "receipt_commit_sha_missing",
                "errorClass": "commit_receipt_missing"})
            return None
        for attempt in range(1, 3):
            attempts_used = attempt
            try:
                r = requests.get(url, timeout=(3, 6))
                if r.status_code == 200:
                    blob = r.json()
                    break
                if r.status_code >= 500:
                    receipt_error = f"http_{int(r.status_code)}"
                elif r.status_code == 404:
                    receipt_error = "exact_commit_not_available"
                else:
                    receipt_error = f"http_{int(r.status_code)}"
            except requests.Timeout:
                receipt_error = "timeout"
            except (requests.ConnectionError, requests.RequestException):
                receipt_error = "network_error"
            except (ValueError, TypeError):
                receipt_error = "invalid_json"
            if attempt < 2:
                time.sleep(0.25)
        if blob is None:
            _REMOTE_ACK["readbackFailures"] += 1
            _REMOTE_CYCLE.update({
                "readBackAt": now_iso, "readBackVerified": False,
                "remoteDurabilityState": "transient_failure",
                "receiptCommitSha": commit_sha or None,
                "receiptAttempts": attempts_used,
                "receiptErrorClass": receipt_error,
                "errorClass": "remote_unreachable"})
            return None
    if blob is None:
        _REMOTE_ACK["readbackFailures"] += 1
        _REMOTE_CYCLE.update({"readBackAt": now_iso,
                              "readBackVerified": False,
                              "remoteDurabilityState": "transient_failure",
                              "receiptAttempts": attempts_used,
                              "receiptErrorClass": "remote_unreachable",
                              "errorClass": "remote_unreachable"})
        return None
    if not isinstance(blob, dict):
        _REMOTE_ACK["readbackFailures"] += 1
        _REMOTE_CYCLE.update({"readBackAt": now_iso,
                              "readBackVerified": False,
                              "remoteDurabilityState": "integrity_failure",
                              "receiptAttempts": attempts_used,
                              "receiptErrorClass": "remote_invalid_json",
                              "errorClass": "remote_invalid_json"})
        return None
    if blob.get("receiptSchemaVersion") and not \
            argus_remote_journal.verify_compact_readback_snapshot(blob):
        _REMOTE_ACK["readbackFailures"] += 1
        _REMOTE_CYCLE.update({"readBackAt": now_iso,
                              "readBackVerified": False,
                              "remoteDurabilityState": "integrity_failure",
                              "receiptAttempts": attempts_used,
                              "receiptErrorClass": "compact_receipt_invalid",
                              "errorClass": "compact_receipt_invalid"})
        return None
    rec = argus_remote_journal.read_back_receipt(
        remote_blob=blob, local_events=_OPS_JOURNAL,
        remote_commit_sha=_REMOTE_CYCLE.get("remoteCommitSha"),
        read_back_at=now_iso)
    outcome_rec = argus_remote_journal.outcome_read_back_receipt(
        remote_blob=blob, local_outcomes=_OUTCOME_LEDGER,
        read_back_at=now_iso)
    _REMOTE_ACK["lastReceiptStatus"] = rec["verificationStatus"]
    _REMOTE_ACK["remoteGeneratedAt"] = rec.get("remoteGeneratedAt")
    if rec["verificationStatus"] == "legacy_snapshot":
        _REMOTE_ACK["legacyRemote"] = True
        return rec
    _REMOTE_ACK["legacyRemote"] = False
    new_keys = [k for k in rec.get("ackedIdempotencyKeys") or []
                if k not in set(_REMOTE_ACK["ackedKeys"])]
    if new_keys:
        _REMOTE_ACK["ackedKeys"] = (_REMOTE_ACK["ackedKeys"] + new_keys)[-800:]
    if rec.get("ackedIdempotencyKeys"):
        _REMOTE_ACK["lastVerifiedRemoteAckAt"] = now_iso
        g = argus_remote_journal._ep(rec.get("remoteGeneratedAt"))
        n = argus_remote_journal._ep(now_iso)
        if g and n:
            _REMOTE_ACK["maxObservedLagSec"] = max(
                int(_REMOTE_ACK.get("maxObservedLagSec") or 0),
                int(max(0, n - g)))
    new_outcomes = [oid for oid in outcome_rec.get("ackedOutcomeIds") or []
                    if oid not in set(_REMOTE_ACK["outcomeAckedIds"])]
    if new_outcomes:
        _REMOTE_ACK["outcomeAckedIds"] = (
            _REMOTE_ACK["outcomeAckedIds"] + new_outcomes)[-400:]
    if outcome_rec.get("ackedOutcomeIds"):
        _REMOTE_ACK["lastVerifiedOutcomeReadBackAt"] = now_iso
    actual_hash = rec.get("manifestHash")
    expected_hash = _REMOTE_CYCLE.get("expectedHash")
    cycle_verified = bool(
        expected_hash and actual_hash and expected_hash == actual_hash and
        rec.get("verificationStatus") == "verified")
    if cycle_verified:
        cycle_error = None
    elif expected_hash and actual_hash and expected_hash != actual_hash:
        cycle_error = "receipt_hash_mismatch"
    elif not expected_hash:
        cycle_error = "commit_receipt_missing"
    else:
        cycle_error = rec.get("verificationStatus") or "read_back_unverified"
    previous_verified_wal_sequence = int(
        _REMOTE_CYCLE.get("verifiedWalSequence") or 0)
    verified_wal_sequence = previous_verified_wal_sequence
    remote_wal_applied_sequence = int(
        _REMOTE_CYCLE.get("remoteWalAppliedSequence") or 0)
    compact_receipt_hash = _REMOTE_CYCLE.get("compactReceiptHash")
    wal_cycle_verified = False
    wal_cycle_error = None
    remote_tick_state = blob.get("missionTickDurability") or {}
    if cycle_verified and blob.get("receiptSchemaVersion") and \
            isinstance(remote_tick_state, dict):
        try:
            exported_local_sequence = int(
                remote_tick_state.get("walAppliedSequence") or 0)
            candidate_remote_sequence = int(
                remote_tick_state.get("remoteWalAppliedSequence"))
        except (TypeError, ValueError):
            wal_cycle_error = "remote_wal_sequence_missing"
        else:
            if candidate_remote_sequence < 0 or \
                    candidate_remote_sequence != exported_local_sequence:
                wal_cycle_error = "remote_wal_manifest_mismatch"
            elif candidate_remote_sequence < previous_verified_wal_sequence:
                wal_cycle_error = "remote_wal_sequence_regression"
            else:
                remote_wal_applied_sequence = candidate_remote_sequence
                verified_wal_sequence = candidate_remote_sequence
                compact_receipt_hash = blob.get("receiptHash")
                wal_cycle_verified = True
    elif cycle_verified:
        wal_cycle_error = "remote_wal_sequence_missing"
    _REMOTE_CYCLE.update({
        "readBackAt": now_iso,
        "readBackVerified": cycle_verified,
        "walReadBackVerified": wal_cycle_verified,
        "actualHash": actual_hash,
        "remoteWalAppliedSequence": remote_wal_applied_sequence,
        "verifiedWalSequence": verified_wal_sequence,
        "compactReceiptHash": compact_receipt_hash,
        "pendingCount": max(0, len(_OPS_JOURNAL) -
                            len(rec.get("ackedIdempotencyKeys") or [])),
        "acknowledgedCount": len(rec.get("ackedIdempotencyKeys") or []),
        "errorClass": cycle_error,
        "walErrorClass": wal_cycle_error,
        "remoteDurabilityState": (
            "verified" if cycle_verified and wal_cycle_verified else
            "integrity_failure" if cycle_error == "receipt_hash_mismatch"
            or wal_cycle_error in ("remote_wal_manifest_mismatch",
                                   "remote_wal_sequence_regression") else
            "verification_pending"),
        "receiptCommitSha": commit_sha or None,
        "receiptCreatedAt": _REMOTE_CYCLE.get("committedAt"),
        "receiptVerifiedAt": (
            now_iso if cycle_verified and wal_cycle_verified else None),
        "receiptAgeSeconds": (
            max(0, int(argus_remote_journal._ep(now_iso) -
                       argus_remote_journal._ep(
                           _REMOTE_CYCLE.get("committedAt"))))
            if argus_remote_journal._ep(now_iso) is not None and
            argus_remote_journal._ep(
                _REMOTE_CYCLE.get("committedAt")) is not None else None),
        "receiptAttempts": attempts_used,
        "receiptErrorClass": cycle_error or wal_cycle_error,
    })
    try:
        _persist_remote_wal_receipt(now_iso)
    except Exception as exc:
        if wal_cycle_verified:
            _REMOTE_CYCLE.update({
                "walReadBackVerified": False,
                "remoteWalAppliedSequence": int(
                    _REMOTE_CYCLE.get("remoteWalAppliedSequence") or 0),
                "verifiedWalSequence": previous_verified_wal_sequence,
                "compactReceiptHash": None,
                "walErrorClass":
                    f"remote_receipt_persist_failed:{type(exc).__name__}",
            })
    remote_ledger = blob.get("marketLedger") if isinstance(blob, dict) else None
    remote_ledger_hash = (blob.get("marketLedgerStateHash")
                          if isinstance(blob, dict) else None)
    if isinstance(remote_ledger, dict) and argus_market_ledger.read_back_verified(
            _MARKET_LEDGER, remote_ledger):
        _MARKET_LEDGER_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_ledger_hash and remote_ledger_hash == \
            argus_market_ledger.state_hash(_MARKET_LEDGER):
        _MARKET_LEDGER_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_ledger, dict) or remote_ledger_hash:
        _MARKET_LEDGER_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _MARKET_LEDGER_REMOTE["verificationStatus"] = "not_present"
    remote_chart = blob.get("chartIntelligence") if isinstance(blob, dict) else None
    remote_chart_hash = (blob.get("chartIntelligenceStateHash")
                         if isinstance(blob, dict) else None)
    if isinstance(remote_chart, dict) and argus_chart_intelligence.read_back_verified(
            _CHART_INTELLIGENCE, remote_chart):
        _CHART_INTELLIGENCE_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_chart_hash and remote_chart_hash == \
            argus_chart_intelligence.state_hash(_CHART_INTELLIGENCE):
        _CHART_INTELLIGENCE_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_chart, dict) or remote_chart_hash:
        _CHART_INTELLIGENCE_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _CHART_INTELLIGENCE_REMOTE["verificationStatus"] = "not_present"
    remote_today = blob.get("todayIntelligence") if isinstance(blob, dict) else None
    remote_today_hash = (blob.get("todayIntelligenceStateHash")
                         if isinstance(blob, dict) else None)
    if isinstance(remote_today, dict) and argus_today_intelligence.read_back_verified(
            _TODAY_INTELLIGENCE, remote_today):
        _TODAY_INTELLIGENCE_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_today_hash and remote_today_hash == \
            argus_today_intelligence.state_hash(_TODAY_INTELLIGENCE):
        _TODAY_INTELLIGENCE_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_today, dict) or remote_today_hash:
        _TODAY_INTELLIGENCE_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _TODAY_INTELLIGENCE_REMOTE["verificationStatus"] = "not_present"
    remote_replay = blob.get("marketReplay") if isinstance(blob, dict) else None
    remote_replay_hash = (blob.get("marketReplayStateHash")
                          if isinstance(blob, dict) else None)
    if isinstance(remote_replay, dict) and argus_market_replay.read_back_verified(
            _MARKET_REPLAY, remote_replay):
        _MARKET_REPLAY_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_replay_hash and remote_replay_hash == \
            argus_market_replay.state_hash(_MARKET_REPLAY):
        _MARKET_REPLAY_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_replay, dict) or remote_replay_hash:
        _MARKET_REPLAY_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _MARKET_REPLAY_REMOTE["verificationStatus"] = "not_present"
    remote_views = (blob.get("verifiedViewSnapshots")
                    if isinstance(blob, dict) else None)
    remote_views_hash = (blob.get("verifiedViewSnapshotsStateHash")
                         if isinstance(blob, dict) else None)
    if isinstance(remote_views, dict) and \
            argus_verified_snapshot.read_back_verified(
                _VERIFIED_VIEW_SNAPSHOTS, remote_views):
        _VERIFIED_VIEW_SNAPSHOT_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_views_hash and remote_views_hash == \
            argus_verified_snapshot.state_hash(_VERIFIED_VIEW_SNAPSHOTS):
        _VERIFIED_VIEW_SNAPSHOT_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_views, dict) or remote_views_hash:
        _VERIFIED_VIEW_SNAPSHOT_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _VERIFIED_VIEW_SNAPSHOT_REMOTE["verificationStatus"] = "not_present"
    remote_asset_reports = (blob.get("assetChartReports")
                            if isinstance(blob, dict) else None)
    remote_asset_reports_hash = (
        blob.get("assetChartReportsStateHash")
        if isinstance(blob, dict) else None)
    if isinstance(remote_asset_reports, dict) and \
            argus_asset_chart_cache.read_back_verified(
                _ASSET_CHART_REPORTS, remote_asset_reports):
        _ASSET_CHART_REPORTS_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif remote_asset_reports_hash and remote_asset_reports_hash == \
            argus_asset_chart_cache.state_hash(_ASSET_CHART_REPORTS):
        _ASSET_CHART_REPORTS_REMOTE.update({
            "lastVerifiedReadBackAt": now_iso,
            "verificationStatus": "verified"})
    elif isinstance(remote_asset_reports, dict) or remote_asset_reports_hash:
        _ASSET_CHART_REPORTS_REMOTE["verificationStatus"] = "hash_mismatch"
    else:
        _ASSET_CHART_REPORTS_REMOTE["verificationStatus"] = "not_present"
    rec["outcomeReadBack"] = outcome_rec
    rec["marketLedgerReadBack"] = dict(_MARKET_LEDGER_REMOTE)
    rec["chartIntelligenceReadBack"] = dict(_CHART_INTELLIGENCE_REMOTE)
    rec["todayIntelligenceReadBack"] = dict(_TODAY_INTELLIGENCE_REMOTE)
    rec["marketReplayReadBack"] = dict(_MARKET_REPLAY_REMOTE)
    rec["verifiedViewSnapshotsReadBack"] = dict(
        _VERIFIED_VIEW_SNAPSHOT_REMOTE)
    rec["assetChartReportsReadBack"] = dict(_ASSET_CHART_REPORTS_REMOTE)
    return rec


def _remote_receipt_failure_is_permanent(error_class):
    return str(error_class or "") in {
        "receipt_hash_mismatch", "compact_receipt_invalid",
        "remote_wal_manifest_mismatch", "remote_wal_sequence_regression",
        "remote_wal_sequence_mismatch", "remote_invalid_json",
        "remote_receipt_compact_identity_mismatch",
        "remote_receipt_recovery_pair_mismatch",
        "remote_receipt_recovery_metadata_mismatch",
        "remote_receipt_artifact_mode_invalid",
        "remote_receipt_legacy_rejected",
        "recovery_sidecar_schema_invalid", "recovery_sidecar_oversized",
        "recovery_sidecar_required",
        "recovery_pair_mismatch", "recovery_pair_readback_invalid",
        "recovery_bundle_hash_mismatch", "recovery_ciphertext_hash_mismatch",
        "recovery_authentication_failed", "recovery_envelope_binding_mismatch",
        "recovery_ledger_repository_invalid",
        "recovery_ledger_commit_invalid",
        "recovery_ledger_commit_metadata_invalid",
        "recovery_ledger_commit_metadata_oversized",
        "recovery_ledger_commit_multiparent",
        "recovery_ledger_commit_nonancestor",
        "recovery_ledger_commit_stale_replay",
        "recovery_ledger_compare_invalid",
        "recovery_ledger_compare_oversized",
        "recovery_ledger_compare_incomplete",
    }


def _remote_commit_recovery_url(commit_sha):
    if not re.fullmatch(r"[0-9a-f]{40}", str(commit_sha or "").lower()):
        return None
    repository = os.environ.get(
        "LEDGER_RAW_REPOSITORY_BASE",
        "https://raw.githubusercontent.com/mitsugue/argus").rstrip("/")
    return (f"{repository}/{str(commit_sha).lower()}"
            f"/ledger{_REMOTE_RECOVERY_PATH}")


def _verified_remote_receipt_artifact(selected):
    """Read one exact commit and authenticate its declared artifact pair."""
    commit = str(selected.get("remoteCommitSha") or "").lower()
    readback_url = _remote_commit_readback_url(commit)
    if readback_url is None:
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_artifact_mode_invalid")
    readback_result = _fetch_pinned_recovery_object(
        readback_url, _DURABLE_READBACK_MAX_BYTES, "receipt_readback")
    if readback_result.get("status") != "present":
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_readback_" + str(readback_result.get("status")))
    readback = readback_result.get("value")
    if not isinstance(readback, dict) or not \
            argus_remote_journal.verify_compact_readback_snapshot(readback):
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_compact_identity_mismatch")
    exact_receipt = selected.get("expectedReceiptHash")
    if exact_receipt is not None and readback.get("receiptHash") != exact_receipt:
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_compact_identity_mismatch")
    mode = str(selected.get("artifactMode") or "legacy_full")
    configured = argus_remote_recovery.configured_keys()
    if mode == "legacy_full":
        if configured.get("status") != "not_configured":
            raise argus_remote_recovery.RecoveryBundleError(
                "remote_receipt_legacy_rejected")
        return readback
    if mode != "encrypted_recovery_v1":
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_artifact_mode_invalid")
    if configured.get("status") != "configured":
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_recovery_key_unavailable")
    recovery_url = _remote_commit_recovery_url(commit)
    recovery_result = _fetch_pinned_recovery_object(
        recovery_url, _DURABLE_RECOVERY_MAX_BYTES, "receipt_recovery")
    if recovery_result.get("status") != "present":
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_recovery_" + str(recovery_result.get("status")))
    sidecar = argus_remote_recovery.validate_sidecar(
        recovery_result.get("value"))
    if sidecar["readback"] != readback:
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_recovery_pair_mismatch")
    envelope = sidecar["recovery"]
    expected_metadata = {
        "bundleHash": selected.get("recoveryBundleHash"),
        "generationId": selected.get("recoveryGenerationId"),
        "keyId": selected.get("recoveryKeyId"),
        "ledgerBaseCommitSha": selected.get("ledgerBaseCommitSha"),
        "targetWalSequence": selected.get("targetWalSequence"),
        "compactReceiptHash": selected.get("expectedReceiptHash"),
    }
    if any(envelope.get(key) != value
           for key, value in expected_metadata.items()):
        raise argus_remote_recovery.RecoveryBundleError(
            "remote_receipt_recovery_metadata_mismatch")
    selected_key = _recovery_key_for_envelope(envelope, configured)
    authenticated_payload = argus_remote_recovery.validate_pair(
        readback, envelope, selected_key["key"],
        key_identifier=selected_key["keyId"])
    raw_repository = os.environ.get(
        "LEDGER_RAW_REPOSITORY_BASE",
        "https://raw.githubusercontent.com/mitsugue/argus")
    owner, repository = _github_ledger_repository(raw_repository)
    _verify_authenticated_ledger_commit_path(
        authenticated_payload["ledgerBaseCommitSha"], commit,
        owner=owner, repository=repository)
    return readback


def _prepare_remote_receipt_drain(
        now_iso=None, *,
        batch_limit=argus_remote_receipt_queue.MAX_RECEIPTS):
    """Verify one bounded immutable intent batch; do not checkpoint.

    The caller must pass the returned plan to
    ``_complete_remote_receipt_drain`` immediately after its already-required
    mission checkpoint. Legacy snapshots are cumulative and may coalesce a
    frozen batch; keyed recovery pairs retain oldest-exact FIFO verification.
    This keeps a natural tick to one full checkpoint.
    """
    now_iso = now_iso or _ai_now_iso()
    started = time.monotonic()
    if not _REMOTE_RECEIPT_FLUSH_LOCK.acquire(blocking=False):
        return {"status": "writer_lock_contended", "lockHeld": False,
                "checkpointCreated": False, "flushDurationMs": 0}
    plan = {"status": "noop", "lockHeld": True,
            "checkpointCreated": False, "startedMonotonic": started}
    try:
        with _REMOTE_RECEIPT_QUEUE_LOCK:
            queue_before = argus_remote_receipt_queue.summary(
                _REMOTE_RECEIPT_QUEUE, now_iso=now_iso)["pendingCount"]
            # The queue is already hard-bounded and integrity-sealed at
            # MAX_RECEIPTS.  Freezing every currently eligible legacy intent
            # removes a second, arbitrary throughput cap without increasing
            # network fetches or checkpoints: one highest cumulative immutable
            # readback still proves the whole frozen set.  Keyed mode below
            # deliberately continues to select only the oldest exact pair.
            # This proves batch capacity only; the 1,800-second wall-clock SLO
            # remains a runtime admission over natural cadence and duration.
            bounded_limit = max(1, min(
                argus_remote_receipt_queue.MAX_RECEIPTS, int(batch_limit)))
            eligible = argus_remote_receipt_queue.pending_receipts(
                _REMOTE_RECEIPT_QUEUE, now_iso=now_iso,
                limit=bounded_limit)
            if not eligible:
                plan.update({"queueBefore": queue_before,
                             "queueAfter": queue_before})
                return plan
            recovery_keys = argus_remote_recovery.configured_keys()
            legacy_coalescing = (
                recovery_keys.get("status") == "not_configured" and
                all(str(row.get("artifactMode") or "legacy_full") ==
                    "legacy_full" for row in eligible))
            selected = eligible[-1] if legacy_coalescing else eligible[0]
            coalescing_operation_ids = (
                [str(row.get("operationId")) for row in eligible]
                if legacy_coalescing else [])
            attempted = argus_remote_receipt_queue.record_attempt(
                _REMOTE_RECEIPT_QUEUE, selected["operationId"],
                attempted_at=now_iso)
            _persist_remote_receipt_queue(attempted)

        target = int(selected.get("targetWalSequence") or 0)
        plan.update({
            "status": "verifying",
            "operationId": selected.get("operationId"),
            "queueBefore": queue_before,
            "targetWalSequence": target,
            "remoteCommitSha": selected.get("remoteCommitSha"),
            "migrationLowerBound": bool(selected.get("migrationLowerBound")),
            "coalescingOperationIds": coalescing_operation_ids,
        })
        # A receipt accepted during this verification remains in the sidecar.
        # Only a sequence covered by this immutable commit is eligible below.
        _REMOTE_CYCLE.update({
            "remoteCommitSha": selected.get("remoteCommitSha"),
            "committedAt": selected.get("acceptedAt"),
            "readBackAt": None,
            "readBackVerified": False,
            "walReadBackVerified": False,
            "expectedHash": selected.get("expectedHash"),
            "actualHash": None,
            "compactReceiptHash": None,
            "remoteDurabilityState": "verification_pending",
            "receiptCommitSha": selected.get("remoteCommitSha"),
            "receiptCreatedAt": selected.get("acceptedAt"),
            "receiptVerifiedAt": None,
            "receiptAgeSeconds": 0,
            "receiptErrorClass": None,
            "errorClass": None,
            "walErrorClass": None,
        })
        if selected.get("expectedReceiptHash") is None and \
                recovery_keys.get("status") == "not_configured":
            # Deterministic compatibility for a pre-v13.4.13 fsynced intent.
            # The strengthened POST contract can no longer create this shape,
            # and a keyed runtime may never use it to bypass pair validation.
            receipt = _remote_readback_ack(now_iso)
        elif selected.get("expectedReceiptHash") is None:
            raise argus_remote_recovery.RecoveryBundleError(
                "remote_receipt_legacy_rejected")
        else:
            exact_artifact = _verified_remote_receipt_artifact(selected)
            receipt = _remote_readback_ack(now_iso, blob=exact_artifact)
        verified_sequence = int(
            _REMOTE_CYCLE.get("verifiedWalSequence") or 0)
        readback_ok = bool(
            receipt and _REMOTE_CYCLE.get("readBackVerified") is True and
            _REMOTE_CYCLE.get("walReadBackVerified") is True and
            (selected.get("expectedReceiptHash") is None and
             recovery_keys.get("status") == "not_configured" or
             _REMOTE_CYCLE.get("compactReceiptHash") == selected.get(
                 "expectedReceiptHash")))
        sequence_ok = (
            verified_sequence == target or
            (selected.get("migrationLowerBound") is True and
             verified_sequence >= target))
        if not readback_ok or not sequence_ok:
            error_class = (
                "remote_wal_sequence_mismatch" if readback_ok else
                _REMOTE_CYCLE.get("receiptErrorClass") or
                _REMOTE_CYCLE.get("walErrorClass") or
                _REMOTE_CYCLE.get("errorClass") or
                "remote_verification_pending")
            with _REMOTE_RECEIPT_QUEUE_LOCK:
                retried = argus_remote_receipt_queue.record_retry(
                    _REMOTE_RECEIPT_QUEUE, selected["operationId"],
                    now_iso=now_iso, error_class=error_class,
                    permanent=_remote_receipt_failure_is_permanent(
                        error_class))
                _persist_remote_receipt_queue(retried)
            plan.update({
                "status": "failed" if _remote_receipt_failure_is_permanent(
                    error_class) else "pending_retry",
                "errorClass": error_class,
                "verifiedWalSequence": verified_sequence,
                "readBackVerified": readback_ok,
            })
            return plan
        # The drain owns the immediately following checkpoint.  Deferring the
        # standalone compaction persist prevents an event-triggered receipt
        # drain from creating two full checkpoints for one immutable proof.
        _journal_compact(now_iso, defer_persist=True)
        plan.update({
            "status": "verified_checkpoint_pending",
            "verifiedWalSequence": verified_sequence,
            "readBackVerified": True,
        })
        return plan
    except Exception as exc:
        safe_error = (exc.classification if isinstance(
            exc, argus_remote_recovery.RecoveryBundleError)
            else type(exc).__name__)
        operation_id = plan.get("operationId")
        if operation_id:
            try:
                with _REMOTE_RECEIPT_QUEUE_LOCK:
                    retried = argus_remote_receipt_queue.record_retry(
                        _REMOTE_RECEIPT_QUEUE, operation_id,
                        now_iso=now_iso,
                        error_class=safe_error,
                        permanent=_remote_receipt_failure_is_permanent(
                            safe_error))
                    _persist_remote_receipt_queue(retried)
            except Exception:
                pass
        plan.update({
            "status": ("failed" if _remote_receipt_failure_is_permanent(
                safe_error) else "pending_retry"),
            "errorClass": safe_error})
        return plan


def _complete_remote_receipt_drain(plan, checkpoint, now_iso=None):
    """Acknowledge an exact intent and its frozen legacy coverage batch."""
    now_iso = now_iso or _ai_now_iso()
    result = dict(plan or {})
    try:
        operation_id = result.get("operationId")
        if result.get("status") != "verified_checkpoint_pending":
            return result
        if not isinstance(checkpoint, dict) or checkpoint.get("verified") is not True:
            with _REMOTE_RECEIPT_QUEUE_LOCK:
                retried = argus_remote_receipt_queue.record_retry(
                    _REMOTE_RECEIPT_QUEUE, operation_id,
                    now_iso=now_iso, error_class="checkpoint_persist_failed")
                _persist_remote_receipt_queue(retried)
            result.update({"status": "pending_retry",
                           "errorClass": "checkpoint_persist_failed"})
            return result
        with _REMOTE_RECEIPT_QUEUE_LOCK:
            verified_queue, covered = \
                argus_remote_receipt_queue.mark_intent_verified(
                    _REMOTE_RECEIPT_QUEUE,
                    operation_id=str(operation_id),
                    verified_sequence=int(result["verifiedWalSequence"]),
                    remote_commit_sha=str(result["remoteCommitSha"]),
                    verified_at=now_iso,
                    allow_sequence_floor=bool(
                        result.get("migrationLowerBound")))
            coalescing_ids = result.get("coalescingOperationIds")
            if type(coalescing_ids) is list and coalescing_ids:
                verified_queue, cumulative_covered = \
                    argus_remote_receipt_queue.mark_selected_covered_verified(
                        verified_queue,
                        operation_ids=coalescing_ids,
                        verified_sequence=int(result["verifiedWalSequence"]),
                        remote_commit_sha=str(result["remoteCommitSha"]),
                        verified_at=now_iso)
                covered.extend(cumulative_covered)
            queue_after = argus_remote_receipt_queue.summary(
                verified_queue, now_iso=now_iso)["pendingCount"]
            result.update({
                "status": "verified",
                "coalescedReceiptCount": len(covered),
                "coveredReceiptIds": covered,
                "queueAfter": queue_after,
                "checkpointCreated": True,
                "remoteCommitSha": result.get("remoteCommitSha"),
                "flushDurationMs": round(
                    (time.monotonic() - float(result["startedMonotonic"]))
                    * 1000, 3),
            })
            verified_queue["lastFlush"] = {
                key: result.get(key) for key in (
                    "status", "coalescedReceiptCount", "targetWalSequence",
                    "verifiedWalSequence", "queueBefore", "queueAfter",
                    "checkpointCreated", "remoteCommitSha",
                    "readBackVerified", "flushDurationMs")
            }
            _persist_remote_receipt_queue(verified_queue)
        return result
    finally:
        result.pop("startedMonotonic", None)
        result.pop("coveredReceiptIds", None)
        result.pop("coalescingOperationIds", None)
        if result.get("lockHeld"):
            result["lockHeld"] = False
            _REMOTE_RECEIPT_FLUSH_LOCK.release()


def _persist_with_remote_receipt_drain(
        now_iso=None, *, checkpoint_required=True):
    """One bounded drainer plus at most one checkpoint.

    Natural lifecycle callers retain their already-required checkpoint even
    when the queue is empty.  An authenticated publisher trigger passes
    ``checkpoint_required=False`` so lock contention, retry backoff, and noop
    paths cannot create an unrelated checkpoint.
    """
    now_iso = now_iso or _ai_now_iso()
    _memory_attribution_path_capture(
        "M18", "remote_receipt_prepare_start")
    plan = _memory_operation_run(
        "journal", "remote_receipt_prepare",
        _prepare_remote_receipt_drain, now_iso)
    _memory_attribution_path_capture(
        "M19", "remote_receipt_prepare_complete", {
            "queueBefore": plan.get("queueBefore"),
        })
    try:
        if plan.get("status") == "verified_checkpoint_pending" or \
                checkpoint_required:
            _memory_attribution_path_capture(
                "M20", "checkpoint_adapter_entry")
            checkpoint = _osint_persist()
        else:
            checkpoint = {"verified": False, "checkpointCreated": False}
        # Receipt verification becomes authoritative only after the exact
        # checkpoint has completed.  Never backdate the durable ACK to the
        # drain-start timestamp: that would make a long checkpoint look like
        # zero verification latency and could falsely satisfy the 1,800-second
        # contract.
        completed_at = _ai_now_iso()
        result = _memory_operation_run(
            "journal", "remote_receipt_complete",
            _complete_remote_receipt_drain, plan, checkpoint, completed_at)
    except Exception:
        if plan.get("lockHeld"):
            _REMOTE_RECEIPT_FLUSH_LOCK.release()
            plan["lockHeld"] = False
        raise
    _recovery_phase_a_record_verified_receipt(
        result, datetime.now(pytz.utc))
    checkpoint["remoteReceiptFlush"] = result
    return checkpoint


def _journal_compact(now_iso=None, *, defer_persist=False):
    """非critical・検証済みack済みイベントの決定論compaction。criticalは
    ack前に絶対compactしない。歴代件数は_OPS_JOURNAL_METAが保持(ゼロ化なし)。"""
    now_iso = now_iso or _ai_now_iso()
    keep, batches = argus_remote_journal.compact_events(
        events=_OPS_JOURNAL, acked_keys=_REMOTE_ACK["ackedKeys"],
        now_iso=now_iso)
    if not batches:
        return 0
    global _OPS_JOURNAL_COMPACT
    _OPS_JOURNAL_COMPACT = argus_remote_journal.merge_compacted(
        _OPS_JOURNAL_COMPACT, batches)
    removed = len(_OPS_JOURNAL) - len(keep)
    _OPS_JOURNAL[:] = keep
    if not _mission_tick_context_active() and not defer_persist:
        _osint_persist()
    return removed


def _remote_journal_diagnostics(now_iso=None):
    now_iso = now_iso or _ai_now_iso()
    receipt_queue = argus_remote_receipt_queue.summary(
        _REMOTE_RECEIPT_QUEUE, now_iso=now_iso)
    acked = set(_REMOTE_ACK.get("ackedKeys") or [])
    pending = [
        row for row in _OPS_JOURNAL
        if str(row.get("idempotencyKey") or "") not in acked]
    oldest_seconds = None
    ages = []
    if pending:
        try:
            current = datetime.fromisoformat(
                str(now_iso).replace("Z", "+00:00"))
            oldest = min(
                datetime.fromisoformat(str(row.get("occurredAt")).replace(
                    "Z", "+00:00"))
                for row in pending if row.get("occurredAt"))
            oldest_seconds = max(0, int((current - oldest).total_seconds()))
            ages = [max(0, int((current - datetime.fromisoformat(
                str(row.get("occurredAt")).replace("Z", "+00:00")))
                .total_seconds())) for row in pending if row.get("occurredAt")]
        except (TypeError, ValueError):
            oldest_seconds = None
            ages = []
    stage1_started = _CHECKPOINT_V2_STAGE1_CONTROL.get(
        "stage1EpochStartedAt")
    previous_started = (_SOAK.get("previousSoak") or {}).get("startedAt")

    def _epoch_max(start, end=None):
        start_ep = argus_runtime._ep(start)
        end_ep = argus_runtime._ep(end)
        selected = []
        now_ep = argus_runtime._ep(now_iso)
        if start_ep is None or now_ep is None:
            return None
        for row in pending:
            occurred_ep = argus_runtime._ep(row.get("occurredAt"))
            if occurred_ep is None or occurred_ep < start_ep:
                continue
            if end_ep is not None and occurred_ep >= end_ep:
                continue
            selected.append(max(0, int(now_ep - occurred_ep)))
        return max(selected) if selected else 0

    sequence = int(_REMOTE_CYCLE.get("verifiedWalSequence") or 0)
    exact_receipt = bool(
        _REMOTE_CYCLE.get("remoteDurabilityState") == "verified" and
        _REMOTE_CYCLE.get("readBackVerified") is True and
        _REMOTE_CYCLE.get("walReadBackVerified") is True and
        sequence > 0 and sequence == int(
            _REMOTE_CYCLE.get("remoteWalAppliedSequence") or 0) and
        re.fullmatch(r"[0-9a-f]{40}", str(
            _REMOTE_CYCLE.get("receiptCommitSha") or "").lower()) and
        receipt_queue["pendingCount"] == 0 and
        receipt_queue["failedCount"] == 0)
    lifetime = max(
        [int(_REMOTE_ACK.get("maxObservedLagSec") or 0)] + ages)
    return {
        "pendingCount": len(pending),
        "oldestPendingAgeSeconds": oldest_seconds,
        "lifetimeMaxPendingAgeSeconds": lifetime,
        "interruptedSoakMaxPendingAgeSeconds": _epoch_max(
            previous_started, stage1_started),
        "checkpointV2Stage1MaxPendingAgeSeconds": _epoch_max(
            stage1_started),
        "currentPendingAgeSeconds": oldest_seconds,
        "currentPendingCount": len(pending),
        "currentRemoteDurabilityState": (
            "failed" if receipt_queue["failedCount"] else
            "pending" if receipt_queue["pendingCount"] else
            _REMOTE_CYCLE.get("remoteDurabilityState") or "unknown"),
        "exactReceiptVerified": exact_receipt,
        "localSequencePosition": int(
            _OPS_JOURNAL_META.get("totalObserved") or 0),
        "remoteSequencePosition": int(
            _REMOTE_CYCLE.get("acknowledgedCount") or 0),
        "readBackVerified": bool(_REMOTE_CYCLE.get("readBackVerified")),
        "receiptQueue": receipt_queue,
    }


def _ffl_receipts():
    """FFLゲート用の耐久レシート: forecast_issuedイベントが検証済みリモート
    ackを持つ予測のみremote_committed(snapshotに予測レコードが載っている
    だけでは不十分 — journalイベントのack必須)。"""
    ak = set(_REMOTE_ACK["ackedKeys"])
    ev_by_agg = {}
    for e in _OPS_JOURNAL:
        if e.get("eventType") == "forecast_issued":
            ev_by_agg[str(e.get("aggregateId"))] = \
                str(e.get("idempotencyKey")) in ak
    out = {}
    for f in _FORECAST_LEDGER:
        if f.get("origin") != "forward_live":
            continue
        agg = (f"{f.get('symbol')}:{str(f.get('issuedAt', ''))[:10]}:"
               f"{f.get('targetType')}")
        if ev_by_agg.get(agg):
            out[str(f.get("id"))] = "remote_committed"
    return out


def _deployment_pipeline_status():
    """デプロイパイプラインの実測状態(smoke-test.ymlの実トリガから判定 —
    主張ではなくファイルの事実)。"""
    mode, cycle = "unknown", "unknown"
    try:
        txt = open(os.path.join(os.path.dirname(__file__), ".github",
                                "workflows", "smoke-test.yml"),
                   encoding="utf-8").read()
        on_sec = txt.split("\non:", 1)[1].split("\njobs:", 1)[0]
        has_push = "push:" in on_sec
        cycle = "detected" if has_push else "clear"
        mode = ("push_and_wait(循環リスク)" if has_push
                else "schedule_and_manual(post-deploy)")
    except Exception:
        pass
    return {"preDeployRequiredChecks": ["backend-rules", "frontend", "gate"],
            "postDeploySmokeMode": mode,
            "cycleStatus": cycle,
            "ownerReadableJa": {
                "clear": ("smokeはmain pushのcheckではない — Render After-CIは"
                          "backend-rules/frontend/gateのみを待つ(循環なし)"),
                "detected": ("smokeがmain pushトリガ — Renderと相互待ちの"
                             "循環リスクあり"),
                "unknown": "workflowファイル未確認(デプロイ環境に非同梱等)",
            }[cycle]}


def _graceful_shutdown():
    """Flush recovery evidence without waiting for process teardown."""
    if _SHUTDOWN["done"]:
        return
    _SHUTDOWN["done"] = True
    try:
        argus_tick_durability.sync_wal(_MISSION_WAL_FILE)
        _SHUTDOWN["walSynced"] = True
    except Exception:
        pass
    try:
        _persist_durability_metadata()
        _SHUTDOWN["cursorSaved"] = True
    except Exception:
        pass
    try:
        # An active tick already has every completed transition in the fsynced
        # WAL.  Avoid a second full-state serialization while it is stopping.
        if (_STARTUP["state"] in ("ready", "ready_degraded") and
                not _MISSION_TICK_CONTEXT.get("active")):
            _osint_persist()
    except Exception:
        pass


def _handle_termination(signum, _frame=None, *, exit_process=True):
    """SIGTERM/SIGINT: reject new work and leave a replayable safe boundary."""
    _SHUTDOWN.update({
        "requested": True,
        "requestedAt": _ai_now_iso(),
        "signal": int(signum),
    })
    lease = _MISSION_TICK_CONTEXT.get("lease")
    if lease is not None:
        lease.expire()
    _graceful_shutdown()
    if exit_process:
        raise SystemExit(0)
    return dict(_SHUTDOWN)


import atexit as _atexit  # noqa: E402
_atexit.register(_graceful_shutdown)
if threading.current_thread() is threading.main_thread():
    signal.signal(signal.SIGTERM, _handle_termination)
    signal.signal(signal.SIGINT, _handle_termination)


def _missions_persist_blob():
    return {"missions": _MISSIONS[-300:], "postmortems": _POSTMORTEMS[-30:],
            "missionWindows": _MISSION_WINDOWS[-240:],
            "forecasts": _FORECAST_LEDGER[-200:], "outcomes": _OUTCOME_LEDGER[-200:],
            "remoteJournalCycle": dict(_REMOTE_CYCLE)}


def _market_ledger_tick(now_iso):
    """Rebuild derived rows and turning points without network or AI calls."""
    if not argus_market_ledger.rebuild_required(_MARKET_LEDGER):
        return {"changed": False,
                "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER),
                "rebuildSkipped": True}
    before = argus_market_ledger.state_hash(_MARKET_LEDGER)
    rebuilt = argus_market_ledger.rebuild(_MARKET_LEDGER, now_iso)
    after = argus_market_ledger.state_hash(rebuilt)
    _MARKET_LEDGER.clear()
    _MARKET_LEDGER.update(rebuilt)
    if before != after:
        _journal("market_ledger_updated", "market_ledger", "phase1",
                 {"stateHash": after,
                  "observationCount": len(_MARKET_LEDGER["observations"]),
                  "turningPointCount": len(_MARKET_LEDGER["turningPoints"])})
    return {"changed": before != after, "stateHash": after,
            "rebuildSkipped": False}


def _dl_resolve_matured(now_iso, max_records=None, return_stats=False,
                         deadline_monotonic=None):
    """成熟成果を同一Outcomeで再解決。cached価格のみ・0値採点なし・冪等。"""
    resolved = 0
    processed = 0
    try:
        now_utc = datetime.fromisoformat(
            str(now_iso).replace("Z", "+00:00")).astimezone(pytz.utc)
    except (TypeError, ValueError):
        now_utc = datetime.now(pytz.utc)

    def _candidate(fc):
        fid = fc.get("id")
        issued_date = str(fc.get("issuedAt") or "")[:10]
        if not fid or fc.get("mockData"):
            return False
        # next_session成熟: 発行日より後の営業日終値が観測できたら解決対象
        if not issued_date or issued_date >= now_iso[:10]:
            return False                 # 成熟前/legacy時刻不明は解決しない
        market_code = str(fc.get("market") or "").upper()
        asset_market = (
            argus_market_clock.JP_EQUITY if market_code == "JP"
            else argus_market_clock.US_EQUITY if market_code == "US"
            else argus_market_clock.asset_market(str(fc.get("symbol") or "")))
        market_closed = (
            asset_market in (
                argus_market_clock.JP_EQUITY,
                argus_market_clock.US_EQUITY)
            and not argus_market_clock.market_session(
                asset_market, now_utc)["isTradingDay"])
        if market_closed:
            return False                  # 休場日は終値未確定 — retry/採点しない
        existing = next((o for o in _OUTCOME_LEDGER
                         if o.get("forecastId") == fid), None)
        if existing and existing.get("status") == "resolved":
            return False                  # 解決済みは絶対に再計算しない
        if existing and not argus_decision_ledger.outcome_retry_due(
                existing, now_iso=now_iso):
            return False                  # 同一tick/interval内は再試行しない
        return True

    candidates = [fc for fc in _FORECAST_LEDGER if _candidate(fc)]
    limit = (len(candidates) if max_records is None else
             max(0, int(max_records)))
    for fc in candidates[:limit]:
        if _SHUTDOWN.get("requested"):
            break
        if deadline_monotonic is not None and \
                time.monotonic() >= float(deadline_monotonic):
            break
        fid = fc.get("id")
        issued_date = str(fc.get("issuedAt") or "")[:10]
        existing = next((o for o in _OUTCOME_LEDGER
                         if o.get("forecastId") == fid), None)
        processed += 1
        sym = fc.get("symbol")
        try:
            hist = _price_history_cached(sym) if "_price_history_cached" in globals() else None
        except Exception:
            hist = None
        start = end = None
        if isinstance(hist, list) and len(hist) >= 2:
            closes = [(h.get("date"), h.get("close")) for h in hist
                      if h.get("close") is not None]
            before = [c for d, c in closes if d and d <= issued_date]
            after = [c for d, c in closes if d and d > issued_date]
            start = before[-1] if before else None
            end = after[0] if after else None
        event_origin = (fc.get("origin") if fc.get("origin") in
                        ("forward_live", "historical_replay") else "scheduler")
        if existing is None:
            o = argus_decision_ledger.outcome_record(
                forecast=fc, outcome_as_of=now_iso, start_price=start,
                end_price=end, now_iso=now_iso)
            if o.get("status") == "unresolved":
                o = argus_decision_ledger.schedule_outcome_retry(
                    o, now_iso=now_iso,
                    retry_interval_seconds=_OUTCOME_RETRY_INTERVAL_SECONDS)
            _OUTCOME_LEDGER.append(o)
            ev_type = ("outcome_resolved" if o.get("status") == "resolved"
                       else "outcome_unresolved")
            _journal(ev_type, "outcome", str(fid),
                     {"status": o.get("status"),
                      "resolutionState": o.get("resolutionState"),
                      "outcomeId": o.get("id")}, origin=event_origin)
        else:
            old_state = existing.get("resolutionState") or existing.get("status")
            o = argus_decision_ledger.retry_outcome_record(
                existing=existing, forecast=fc, outcome_as_of=now_iso,
                start_price=start, end_price=end, now_iso=now_iso,
                retry_interval_seconds=_OUTCOME_RETRY_INTERVAL_SECONDS,
                expire_after_seconds=_OUTCOME_RETRY_EXPIRE_SECONDS)
            if o == existing:
                continue
            existing.clear()
            existing.update(o)           # ID/list位置を維持、重複生成なし
            ev_type = ("outcome_resolved" if o.get("status") == "resolved"
                       else "outcome_expired"
                       if o.get("resolutionState") == "unresolved_expired"
                       else "outcome_retry_scheduled")
            _journal(ev_type, "outcome", str(fid),
                     {"status": o.get("status"), "fromState": old_state,
                      "resolutionState": o.get("resolutionState"),
                      "outcomeId": o.get("id"),
                      "retryCount": o.get("retryCount")}, origin=event_origin)
        if o.get("status") == "resolved":
            resolved += 1
    while len(_OUTCOME_LEDGER) > 200:
        _OUTCOME_LEDGER.pop(0)
    if return_stats:
        remaining = max(0, len(candidates) - processed)
        return {"processed": processed, "resolved": resolved,
                "remaining": remaining}
    return resolved


def _activate_formal_soak(start_decision, window, *, rollover_armed):
    """Archive the old Soak by value and activate exactly one new clock."""
    previous_summary = _SOAK.get("previousSoak")
    archived = None
    if rollover_armed and _SOAK.get("startedAt"):
        archived = copy.deepcopy(_SOAK)
        if not any(row.get("soakId") == archived.get("soakId")
                   for row in _SOAK_HISTORY):
            _SOAK_HISTORY.append(archived)
            del _SOAK_HISTORY[:-8]
        previous_summary = {
            "soakId": archived.get("soakId"),
            "buildSha": archived.get("buildSha"),
            "buildShaFull": archived.get("buildShaFull"),
            "startedAt": archived.get("startedAt"),
            "state": archived.get("state"),
            "inherited": False,
            "reason": "owner_authorized_same_sha_rollover",
            "archiveImmutable": True,
        }
    window_digest = hashlib.sha256(
        window["missionWindowId"].encode("utf-8")).hexdigest()[:8]
    activated = {
        "soakId": (f"soak-{(_backend_sha() or 'local')[:7]}"
                   f"-{window_digest}"),
        "buildSha": _backend_sha(),
        "buildShaFull": _backend_exact_sha(),
        "appVersion": _semantic_app_version() or None,
        "processBootId": _RUNTIME.get("bootId"),
        "processBootedAt": _RUNTIME.get("processBootedAt"),
        "startedAt": start_decision["startedAt"],
        "startedBy": start_decision["startedBy"],
        "firstMissionWindowId": start_decision["firstMissionWindowId"],
        "startReason": start_decision["startReason"],
        "startTimeSource": start_decision["startTimeSource"],
        "completed72h": False, "interruptionCount": 0,
        "interruptions": [], "previousSoak": previous_summary,
        "heartbeats": [], "state": "not_started",
        "lastHeartbeatAt": None, "lastHeartbeatSource": None,
    }
    # Publish the complete record in one mutation; a partial Soak is never
    # visible if construction fails before this point.
    _SOAK.clear()
    _SOAK.update(activated)
    _SOAK_CONTROL.update({
        "armed": False, "armedAt": None, "armedBuildSha": None,
        "armId": None, "reason": None,
        "plannedRestartMarker": None})
    return {"archived": archived is not None,
            "soakId": _SOAK["soakId"]}


@app.route("/api/argus/admin/soak/arm", methods=["POST"])
def api_argus_admin_soak_arm():
    """Persist one explicit owner arm; never starts a Soak itself."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    current_sha = str(_backend_exact_sha() or "").lower()
    requested_sha = str(body.get("buildSha") or "").lower()
    if body.get("confirm") is not True:
        return jsonify({"ok": False,
                        "error": "explicit_confirmation_required"}), 400
    if not re.fullmatch(r"[0-9a-f]{40}", requested_sha) or \
            requested_sha != current_sha:
        return jsonify({"ok": False,
                        "error": "exact_current_build_sha_required"}), 409
    if not _CHECKPOINT_V2_STAGE1_ENABLED:
        return jsonify({"ok": False, "error": "stage1_not_enabled"}), 409
    before = copy.deepcopy(_CHECKPOINT_V2_STAGE1_CONTROL)
    try:
        armed = argus_checkpoint_v2_stage1.arm(
            before, build_sha=current_sha, armed_at=_ai_now_iso(),
            requested_by_class="owner_admin")
    except argus_checkpoint_v2_stage1.Stage1ControlError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 409
    globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = armed
    checkpoint = _osint_persist()
    if checkpoint.get("verified") is not True or \
            _CHECKPOINT_V2_STATUS.get("lastWriteVerified") is not True:
        globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = before
        return jsonify({"ok": False,
                        "error": "stage1_arm_persist_failed"}), 503
    return jsonify({
        "ok": True, "status": "armed",
        "armId": armed.get("armId"), "startsNow": False,
        "heartbeatCreated": False, "soakCreated": False,
        "startAuthority": "next_qualified_natural_ec2_mission_window",
    })


@app.route("/api/argus/admin/checkpoint-v2/stage1/accept", methods=["POST"])
def api_argus_admin_checkpoint_v2_stage1_accept():
    """Record reviewed evidence; never promotes or starts a Soak itself."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    if not _CHECKPOINT_V2_STAGE1_ENABLED:
        return jsonify({"ok": False, "error": "stage1_not_enabled"}), 409
    body = request.get_json(silent=True) or {}
    current_sha = str(_backend_exact_sha() or "").lower()
    requested_sha = str(body.get("buildSha") or "").lower()
    if body.get("confirm") is not True or requested_sha != current_sha or \
            not re.fullmatch(r"[0-9a-f]{40}", requested_sha):
        return jsonify({"ok": False,
                        "error": "exact_confirmed_build_sha_required"}), 409
    evidence_fields = (
        "resourceEvidenceId", "diskEvidenceId", "isolatedRestoreGenerationId")
    if any(not str(body.get(key) or "").strip() for key in evidence_fields):
        return jsonify({"ok": False,
                        "error": "stage1_evidence_ids_required"}), 400
    generation_ids = {
        row.get("generationId") for row in
        _CHECKPOINT_V2_STAGE1_CONTROL.get("naturalGenerations") or []}
    if body.get("isolatedRestoreGenerationId") not in generation_ids:
        return jsonify({"ok": False,
                        "error": "isolated_restore_generation_not_natural"}), 409
    resource_gate = argus_checkpoint_v2_stage1.resource_acceptance(
        _CHECKPOINT_V2_STAGE1_CONTROL)
    journal_gate = _remote_journal_diagnostics(_ai_now_iso())
    if resource_gate.get("passed") is not True:
        return jsonify({"ok": False,
                        "error": "stage1_resource_gate_failed",
                        "blockers": resource_gate.get("blockers")}), 409
    if journal_gate.get("currentPendingCount") != 0 or \
            journal_gate.get("exactReceiptVerified") is not True or \
            journal_gate.get(
                "checkpointV2Stage1MaxPendingAgeSeconds") is None or \
            int(journal_gate.get(
                "checkpointV2Stage1MaxPendingAgeSeconds") or 0) > 1800:
        return jsonify({
            "ok": False, "error": "stage1_remote_journal_gate_failed",
            "currentPendingCount": journal_gate.get("currentPendingCount"),
            "exactReceiptVerified": journal_gate.get(
                "exactReceiptVerified"),
            "checkpointV2Stage1MaxPendingAgeSeconds": journal_gate.get(
                "checkpointV2Stage1MaxPendingAgeSeconds"),
        }), 409
    before = copy.deepcopy(_CHECKPOINT_V2_STAGE1_CONTROL)
    try:
        accepted = argus_checkpoint_v2_stage1.record_acceptance(
            before,
            resource_accepted=(body.get("resourceAccepted") is True and
                               resource_gate.get("passed") is True),
            disk_accepted=body.get("diskAccepted") is True,
            isolated_restore_verified=(
                body.get("isolatedRestoreVerified") is True),
            restore_authority_approved=(
                body.get("restoreAuthorityApproved") is True))
    except argus_checkpoint_v2_stage1.Stage1ControlError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 409
    if accepted.get("authorityPromotionBlocked") is not False:
        return jsonify({"ok": False,
                        "error": "all_stage1_acceptance_flags_required"}), 409
    accepted["acceptanceEvidence"] = {
        key: str(body.get(key))[:160] for key in evidence_fields}
    accepted["resourceEvidence"] = resource_gate
    accepted["remoteJournalEvidence"] = {
        key: journal_gate.get(key) for key in (
            "lifetimeMaxPendingAgeSeconds",
            "interruptedSoakMaxPendingAgeSeconds",
            "checkpointV2Stage1MaxPendingAgeSeconds",
            "currentPendingAgeSeconds", "currentPendingCount",
            "currentRemoteDurabilityState", "exactReceiptVerified")}
    accepted["acceptedAt"] = _ai_now_iso()
    globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = accepted
    checkpoint = _osint_persist()
    if checkpoint.get("verified") is not True or \
            _CHECKPOINT_V2_STATUS.get("lastWriteVerified") is not True:
        globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = before
        return jsonify({"ok": False,
                        "error": "stage1_acceptance_persist_failed"}), 503
    return jsonify({"ok": True, "status": "accepted",
                    "formalSoakArmed": False,
                    "formalSoakState": "not_started",
                    "soakCreated": False, "heartbeatCreated": False})


@app.route("/api/argus/admin/memory-attribution", methods=["GET"])
def api_argus_admin_memory_attribution():
    """Owner-only scalar phase history; never exposes checkpoint payloads."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    payload = _MEMORY_ATTRIBUTION.view()
    payload["operationAttribution"] = _MEMORY_OPERATIONS.view()
    # v13.5.60: `?threads=1` adds the secret-free thread-location dump (owner
    # stall diagnostics) to this existing owner-only route — no new route, so
    # the route catalog (a Recovery payload) is untouched.
    if str(request.args.get("threads") or "").lower() in ("1", "true", "yes"):
        payload["runtimeThreads"] = _runtime_thread_dump()
    return jsonify(payload)


def _runtime_thread_dump(max_threads=64, max_frames=18):
    """Secret-free snapshot of every thread's Python stack (owner diagnostics).

    v13.5.60: the production stall of the heavier public documents could not
    be attributed from outside the process. This returns thread names and
    frame locations (repository-relative file, line, function) only — no
    locals, no arguments, no environment — so the owner can see WHERE a
    request thread is waiting the next time a route stops answering."""
    import traceback
    root = os.path.dirname(os.path.abspath(__file__))
    frames = sys._current_frames()
    threads = []
    for thread in list(threading.enumerate())[:max_threads]:
        frame = frames.get(thread.ident)
        stack = []
        if frame is not None:
            for summary in traceback.extract_stack(frame)[-max_frames:]:
                filename = summary.filename or ""
                if filename.startswith(root):
                    filename = os.path.relpath(filename, root)
                else:
                    filename = os.path.basename(filename)
                stack.append({"file": filename[:120], "line": int(summary.lineno or 0),
                              "function": str(summary.name or "")[:80]})
        threads.append({"name": str(thread.name)[:80], "daemon": bool(thread.daemon),
                        "alive": bool(thread.is_alive()), "frames": stack})
    return {
        "schemaVersion": "argus-runtime-thread-dump-v1",
        "generatedAt": _ai_now_iso(),
        "threadCount": threading.active_count(),
        "singleFlight": _single_flight_status(),
        "decisionEvidenceCacheSize": len(_DECISION_EVIDENCE_CACHE),
        "threads": threads,
    }


@app.route("/api/argus/admin/missions/tick", methods=["POST"])
def api_argus_admin_missions_tick():
    _prelude_samples = {"P0": _memory_attribution_scalar_snapshot()}
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    if _SHUTDOWN.get("requested") or (
            _DURABILITY_PRODUCTION and
            (not _DURABLE_STORAGE_STATUS.get("valid") or
             _STARTUP.get("state") not in ("ready", "ready_degraded"))):
        return jsonify({
            "ok": False,
            "status": "failed",
            "error": "persistent_storage_unavailable",
            "errorClass": "persistent_storage_unavailable",
            "ready": False,
        }), 503
    body = request.get_json(silent=True) or {}
    if isinstance(body, dict) and body.get("releaseSnapshotSeed") is True:
        # Release seeding is a narrow, causally acknowledged producer path.
        # It serializes on the existing durability lock but does not open a
        # scheduler window, advance Recovery, or accept a busy/duplicate tick
        # as evidence that any business snapshot was produced.
        return _release_seed_verified_market_views(body)
    source = (str(body.get("triggerSource") or "manual")
              if isinstance(body, dict) else "manual")
    lease = argus_tick_durability.TickLease(
        _MISSION_LEASE_FILE,
        build_sha=(os.environ.get("RENDER_GIT_COMMIT") or _backend_sha()),
        owner=source,
        boot_id=_RUNTIME.get("bootId"),
        ttl_seconds=_outcome_policy_seconds(
            "ARGUS_MISSION_LEASE_SECONDS", 240, 30))
    _prelude_samples["P1"] = _memory_attribution_scalar_snapshot()
    if not lease.acquire():
        active = lease.metadata or {}
        return jsonify({
            "ok": True,
            "status": "expected_skip",
            "result": "busy",
            "reason": "mission_tick_single_flight",
            "jobId": active.get("jobId"),
            "lease": {
                "owner": active.get("owner"),
                "acquiredAt": active.get("acquiredAt"),
                "expiresAt": active.get("expiresAt"),
                "heartbeatAt": active.get("heartbeatAt"),
                "renewedAt": active.get("renewedAt"),
                "buildSha": active.get("buildSha"),
            },
        })
    _prelude_samples["P2"] = _memory_attribution_scalar_snapshot()
    if not _DURABLE_CHECKPOINT_LOCK.acquire(timeout=5.0):
        # A durability flush may briefly own the in-process checkpoint lock.
        # Never let a scheduled HTTP caller wait past its transport deadline;
        # the mission remains untouched and the next schedule retries it.
        lease.release()
        return jsonify({
            "ok": True,
            "status": "expected_skip",
            "result": "busy",
            "reason": "durable_checkpoint_lock_busy",
        })
    _prelude_samples["P3"] = _memory_attribution_scalar_snapshot()
    try:
        wal = argus_tick_durability.read_valid_wal(_MISSION_WAL_FILE)
        _prelude_samples["P4"] = _memory_attribution_scalar_snapshot()
        _t0_sample = _prelude_samples["P4"]
        _MISSION_TICK_CONTEXT.update({
            "active": True,
            "jobId": lease.job_id,
            "lease": lease,
            "walSequence": int(wal.get("maximumSequence") or 0),
            "walEventCount": 0,
            "checkpoint": None,
            "startedMonotonic": time.monotonic(),
            "startedCpu": time.process_time(),
            "rssBeforeBytes": argus_tick_durability.current_rss_bytes(),
            "memoryAttributionT0": _t0_sample,
            "memoryAttributionPrelude": _prelude_samples,
            "memoryAttributionRecordId": None,
            "walAppendMs": 0,
            "ownerThread": threading.get_ident(),
            "recoveryMeasurementJPPostSession": False,
            "recoveryMeasurementUSPostSession": False,
            "recoveryMeasurementOwnerAuthorized": False,
            "recoveryMeasurementWalBytes": _recovery_phase_a_scalar(
                wal.get("bytes")),
            "recoveryMeasurementWalSequence": _recovery_phase_a_scalar(
                wal.get("maximumSequence")),
        })
        try:
            result = _api_argus_admin_missions_tick_impl()
        except Exception as exc:
            _memory_attribution_not_applicable(
                tuple(f"M{number}" for number in range(24)),
                f"mission_exception:{type(exc).__name__}")
            _memory_attribution_finish_mission(
                mission_complete=False, error_class=type(exc).__name__)
            raise
        _memory_attribution_finish_mission(mission_complete=True)
        return result
    finally:
        measurement_checkpoint = _MISSION_TICK_CONTEXT.get("checkpoint")
        record_id = _memory_attribution_record_id()
        _MISSION_TICK_CONTEXT["active"] = False
        _MISSION_TICK_CONTEXT["lease"] = None
        _memory_attribution_capture(
            "T12", {"sampleClass": "bounded_post_mission_no_wait"})
        if record_id:
            _memory_attribution_complete(record_id)
        _MISSION_TICK_CONTEXT["missionWindowId"] = None
        _MISSION_TICK_CONTEXT["triggerSource"] = None
        _MISSION_TICK_CONTEXT["scheduledFor"] = None
        _MISSION_TICK_CONTEXT["ownerThread"] = None
        _MISSION_TICK_CONTEXT["memoryAttributionRecordId"] = None
        _MISSION_TICK_CONTEXT["memoryAttributionT0"] = None
        _MISSION_TICK_CONTEXT["memoryAttributionPrelude"] = None
        _MISSION_TICK_CONTEXT["recoveryMeasurementJPPostSession"] = False
        _MISSION_TICK_CONTEXT["recoveryMeasurementUSPostSession"] = False
        _MISSION_TICK_CONTEXT["recoveryMeasurementOwnerAuthorized"] = False
        _MISSION_TICK_CONTEXT["recoveryMeasurementWalBytes"] = None
        _MISSION_TICK_CONTEXT["recoveryMeasurementWalSequence"] = None
        lease.release()
        _DURABLE_CHECKPOINT_LOCK.release()
        _recovery_phase_a_finalize_checkpoint(measurement_checkpoint)


def _api_argus_admin_missions_tick_impl():
    """Admin/cron: セッション対応ミッションの冪等生成+lease実行+見逃し回収。
    公開ルートからは不可。重複実行しても予測/成果は重複しない。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    if not isinstance(body, dict):
        body = {}
    _MISSION_TICK_CONTEXT["recoveryMeasurementOwnerAuthorized"] = \
        _recovery_phase_a_owner_sampling_authorized(body, ok)
    batch_started = time.monotonic()
    cursor_before = int(_MISSION_BATCH_STATE.get("cursor") or 0)
    max_missions = min(50, _outcome_policy_seconds(
        "ARGUS_MISSION_BATCH_MAX_EVENTS", 12, 1))
    max_outcomes = min(50, _outcome_policy_seconds(
        "ARGUS_OUTCOME_BATCH_MAX_EVENTS", 12, 1))
    time_budget_seconds = min(120, _outcome_policy_seconds(
        "ARGUS_MISSION_BATCH_MAX_SECONDS", 45, 5))
    now = datetime.now(TZ_JST)
    now_iso = now.isoformat()
    requested_source = str(body.get("triggerSource") or "manual")
    trigger_source = argus_scheduler.normalize_trigger_source(requested_source)
    if trigger_source is None:
        return jsonify({"ok": False, "status": "failed",
                        "error": "invalid_trigger_source"}), 400
    window = argus_scheduler.mission_window(
        observed_at=now_iso, trigger_source=trigger_source,
        scheduled_for=(str(body.get("scheduledFor"))
                       if body.get("scheduledFor") else None))
    if window is None:
        return jsonify({"ok": False, "status": "failed",
                        "error": "invalid_mission_window"}), 400
    _MISSION_TICK_CONTEXT["triggerSource"] = trigger_source
    _MISSION_TICK_CONTEXT["scheduledFor"] = window["scheduledFor"]
    _MISSION_TICK_CONTEXT["missionWindowId"] = window["missionWindowId"]
    supplied_window_id = str(body.get("missionWindowId") or "")
    if supplied_window_id and supplied_window_id != window["missionWindowId"]:
        return jsonify({"ok": False, "status": "failed",
                        "error": "mission_window_id_mismatch"}), 400
    if trigger_source == "manual":
        # workflow_dispatch/legacy admin検証は自然scheduleを抑止しない。
        # GitHub run内の再送だけは同じrunIdで冪等になる。
        run_id = str(body.get("runId") or f"local-{time.time_ns()}")[:80]
        window.update({"missionWindowId": f"mw-manual-{run_id}",
                       "delaySeconds": 0, "delayClassification": "on_time"})
    _memory_attribution_begin(window, now_iso)
    window = argus_scheduler.apply_window_history(window, _MISSION_WINDOWS)
    prior_windows = [r for r in _MISSION_WINDOWS
                     if r.get("triggerSource") != "manual" and
                     r.get("scheduledFor") < window["scheduledFor"]]
    window_record, should_run = argus_scheduler.begin_mission_window(
        _MISSION_WINDOWS, window=window, build_sha=_backend_sha(),
        started_at=now_iso, runtime_version=_semantic_app_version())
    _memory_attribution_path_capture(
        "M1", "window_history_and_begin_complete",
        {"duplicateSuppressed": not should_run})
    if not should_run:
        _memory_attribution_not_applicable(
            tuple(f"M{number}" for number in range(2, 18)),
            "duplicate_suppressed")
        checkpoint = _persist_with_remote_receipt_drain(now_iso)
        return jsonify({"ok": True, "status": "expected_skip",
                        "result": "caught_up",
                        "reason": "duplicate_suppressed",
                        "jobId": _MISSION_TICK_CONTEXT.get("jobId"),
                        "checkpointCreated": bool(checkpoint.get("verified")),
                        "missionWindow": window_record})
    last_scheduled = max((r.get("scheduledFor") for r in prior_windows
                          if r.get("scheduledFor")), default=None)
    window_record["boundedCatchUpCandidates"] = \
        argus_scheduler.bounded_catchup_windows(
            last_scheduled_for=last_scheduled,
            current_scheduled_for=window["scheduledFor"])
    window_record["catchUpExecuted"] = 0  # 過去windowを現在として実行しない
    session_date = now.strftime("%Y-%m-%d")
    epoch = argus_ai_gate.model_epoch_id(
        provider="gemini", model=GEMINI_MODEL_ID,
        prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
        tool_mode="grounding")
    now_utc = now.astimezone(pytz.utc)
    calendar_states = _market_calendar_states(now_utc)
    jp_session = calendar_states["JP"]
    us_session = calendar_states["US"]
    jp_holiday = not jp_session["isTradingDay"]
    _memory_attribution_path_capture("M2", "calendar_complete")
    ledger_tick = _market_ledger_tick(now_iso)
    _memory_attribution_path_capture("M3", "market_ledger_complete")
    daily_short_tick = {"status": "expected_skip", "reason": "outside_publication_window",
                        "rowCount": len(_TODAY_INTELLIGENCE.get("shortSellingHistory") or [])}
    # J-Quants publishes this close-based aggregate after the JP session.  The
    # natural scheduler owns the bounded provider refresh; public chart GETs
    # remain cache/read-only and therefore cannot create provider cost.
    _needs_daily_short_seed = not bool(
        _TODAY_INTELLIGENCE.get("shortSellingHistory") or [])
    if _needs_daily_short_seed or (
            jp_session.get("isTradingDay") and (now.hour, now.minute) >= (16, 30)):
        try:
            _daily_short_rows = _jp_daily_short_history(cached_only=False)
            daily_short_tick = {
                "status": _JP_DAILY_SHORT_CACHE.get("status") or
                ("live" if _daily_short_rows else "missing"),
                "reason": _JP_DAILY_SHORT_CACHE.get("errorClass"),
                "rowCount": len(_daily_short_rows),
                "latestDate": (_daily_short_rows[-1].get("date")
                               if _daily_short_rows else None),
                "initialSeed": _needs_daily_short_seed,
            }
        except Exception as _short_exc:
            daily_short_tick = {"status": "degraded",
                                "reason": type(_short_exc).__name__,
                                "rowCount": len(_TODAY_INTELLIGENCE.get(
                                    "shortSellingHistory") or [])}
    _memory_attribution_path_capture(
        "M4", "daily_short_complete",
        {"dailyShortRowCount": daily_short_tick.get("rowCount")})
    _chart_before_hash = argus_chart_intelligence.state_hash(_CHART_INTELLIGENCE)
    _replay_before_hash = argus_market_replay.state_hash(_MARKET_REPLAY)
    _view_before_hash = argus_verified_snapshot.state_hash(
        _VERIFIED_VIEW_SNAPSHOTS)
    _memory_attribution_path_capture("M5", "pre_view_hashes_complete")
    _chart_reports = []
    _view_publications = []
    _view_phase_specs = (
        ("M6", "jp_primary", "1321", "JP"),
        ("M7", "jp_secondary", "1306", "JP"),
        ("M8", "us_primary", "SPY", "US"),
        ("M9", "us_secondary", "QQQ", "US"),
    )
    _view_phase_index = 0
    try:
        for _view_phase_index, (
                _view_phase, _view_slot, _market_symbol,
                _market_code) in enumerate(_view_phase_specs):
            _chart_report, _view_publication = \
                _precompute_verified_market_view(
                    _market_symbol, _market_code,
                    market_scope=_market_symbol == "1321")
            _chart_reports.append(_chart_report)
            _view_publications.append({
                "instrument": _market_symbol, **_view_publication})
            _memory_attribution_path_capture(
                _view_phase,
                f"verified_market_view_{_view_slot}_complete", {
                    "market": _market_code,
                    "viewSlot": _view_slot,
                })
        _view_phase_index = len(_view_phase_specs)
        _chart_after_hash = argus_chart_intelligence.state_hash(_CHART_INTELLIGENCE)
        _replay_after_hash = argus_market_replay.state_hash(_MARKET_REPLAY)
        _view_after_hash = argus_verified_snapshot.state_hash(
            _VERIFIED_VIEW_SNAPSHOTS)
        _chart_changed = _chart_before_hash != _chart_after_hash
        _replay_changed = _replay_before_hash != _replay_after_hash
        _view_changed = _view_before_hash != _view_after_hash
        chart_tick = {
            "changed": _chart_changed, "replayChanged": _replay_changed,
            "verifiedViewsChanged": _view_changed,
            # Preserve the pre-v13.2 primary report fields for operations
            # consumers while exposing all four cache results additively.
            "reportId": _chart_reports[0].get("reportId"),
            "status": _chart_reports[0].get("status"),
            "reportIds": [row.get("reportId") for row in _chart_reports],
            "statuses": [row.get("status") for row in _chart_reports],
            "stateHash": _chart_after_hash,
            "replayStateHash": _replay_after_hash,
            "verifiedViewsStateHash": _view_after_hash,
            "viewPublications": _view_publications,
        }
        if _chart_changed or _replay_changed or _view_changed:
            _journal("market_context_replay_updated", "market_replay",
                     _replay_after_hash,
                     {"chartStateHash": _chart_after_hash,
                      "replayStateHash": _replay_after_hash,
                      "verifiedViewsStateHash": _view_after_hash,
                      "methodVersion": argus_market_replay.METHOD_VERSION,
                      "instrumentCount": 4})
        _memory_attribution_path_capture(
            "M10", "post_view_hashes_and_journal_complete", {
                "viewCount": len(_view_publications),
                "journalUpdated": bool(
                    _chart_changed or _replay_changed or _view_changed),
            })
    except Exception as _chart_exc:
        if _view_phase_index < len(_view_phase_specs):
            _failed_phase, _failed_slot, _failed_symbol, _failed_market = \
                _view_phase_specs[_view_phase_index]
            _memory_attribution_path_capture(
                _failed_phase,
                f"verified_market_view_{_failed_slot}_exception", {
                    "market": _failed_market,
                    "viewSlot": _failed_slot,
                    "errorClass": type(_chart_exc).__name__,
                })
            _memory_attribution_not_applicable(
                tuple(row[0] for row in _view_phase_specs[
                    _view_phase_index + 1:]),
                f"prior_view_exception:{type(_chart_exc).__name__}")
        chart_tick = {"changed": False, "status": "degraded",
                      "reason": type(_chart_exc).__name__}
        _memory_attribution_path_capture(
            "M10", "post_view_hashes_or_journal_exception", {
                "viewCount": len(_view_publications),
                "errorClass": type(_chart_exc).__name__,
            })
    try:
        asset_chart_tick = _precompute_asset_chart_tick(
            deadline_monotonic=batch_started + time_budget_seconds)
    except Exception as _asset_chart_exc:
        asset_chart_tick = {
            "status": "degraded", "generated": False,
            "reason": type(_asset_chart_exc).__name__,
            "stateHash": argus_asset_chart_cache.state_hash(
                _ASSET_CHART_REPORTS),
        }
    _memory_attribution_path_capture(
        "M11", "asset_chart_complete",
        {"generated": asset_chart_tick.get("generated")})
    # v13.4.2: Remote Journal read-back runs through the fsynced receipt-intent
    # queue immediately before the already-required natural checkpoint below.
    # Public GETs and the receipt-acceptance POST never invoke the drainer.
    created = argus_scheduler.generate_daily_missions(
        session_date=session_date, now_iso=now_iso,
        jp_holiday=jp_holiday,
        us_holiday=not us_session["isTradingDay"],
        existing=_MISSIONS, model_epoch=epoch,
        rubric_version=argus_decision_ledger.RUBRIC_VERSION)
    created += argus_scheduler.generate_periodic_missions(
        session_date=session_date, weekday=now.weekday(),
        day_of_month=now.day, existing=_MISSIONS + created,
        model_epoch=epoch,
        rubric_version=argus_decision_ledger.RUBRIC_VERSION)
    _MISSIONS.extend(created)
    executed, recovered = [], 0
    # v12.2.3: コールド時に消費された当日予測ミッションの回収発行
    # (実調査がストアに存在し、当日のforward-live予測がゼロの場合のみ・冪等)
    if _OSINT_STORE and not any(
            f.get("origin") == "forward_live" and
            str(f.get("issuedAt", ""))[:10] == session_date
            for f in _FORECAST_LEDGER):
        warm_consumed = any(m.get("checkpoint") == "warmup_queued"
                            for m in _MISSIONS
                            if m.get("sessionDate") == session_date)
        rk = f"recovery_issuance:{session_date}"
        if warm_consumed and not any(m.get("idempotencyKey") == rk
                                     for m in _MISSIONS):
            rm = argus_scheduler.mission(
                mission_type="missed_mission_recovery", market="ALL",
                session_date=session_date, scheduled_for=now_iso,
                model_epoch=epoch,
                rubric_version=argus_decision_ledger.RUBRIC_VERSION)
            rm["idempotencyKey"] = rk
            rm["missionId"] = f"m-{rk}"
            _MISSIONS.append(rm)
    # v12.2.3: 週次/月次の検証実行(validation_run — 本番実行のふりをしない)
    _validate = str(body.get("validate") or "")
    if _validate in ("weekly", "monthly"):
        rep = {"type": ("WEEKLY LEARNING REVIEW" if _validate == "weekly"
                        else "MONTHLY AGENT REVIEW"),
               "sessionDate": session_date, "origin": "validation_run",
               "resolvedSamples": sum(1 for o in _OUTCOME_LEDGER
                                      if o.get("status") == "resolved"),
               "ownerReadableJa": ("検証実行(validation_run) — 定期実行ではない。"
                                   "解決サンプル不足時は学習主張なし")}
        if not any(r.get("sessionDate") == session_date and
                   r.get("type") == rep["type"] and
                   r.get("origin") == "validation_run"
                   for r in _PERIODIC_REPORTS):
            _PERIODIC_REPORTS.append(rep)
    _memory_attribution_path_capture(
        "M12", "mission_generation_complete",
        {"createdMissionCount": len(created)})
    # 見逃し検知→回収対象へ
    missed = argus_scheduler.detect_missed(
        _MISSIONS, now_iso, max_records=max_missions)
    for _mm in missed:
        _inc_id = f"inc-{_mm.get('missionId')}"
        if any(i.get("id") == _inc_id for i in _INCIDENTS):
            continue                    # 冪等: 同一インシデントを重複起票しない
        _INCIDENTS.append({"id": _inc_id,
                           "severity": "warning", "component": "scheduler",
                           "detectedAt": now_iso, "status": "open",
                           "missionType": _mm.get("missionType"),
                           "ownerImpactJa": "ミッション見逃し — 回収を試行",
                           "resolvedAt": None})
        # v12.2.9: incident開始を運用ジャーナルへ(遷移コードから — GETからではない)
        _journal("incident_opened", "incident", _inc_id,
                 {"component": "scheduler", "severity": "warning",
                  "missionType": _mm.get("missionType") or "unknown"})
    while len(_INCIDENTS) > 20:
        _INCIDENTS.pop(0)
    _memory_attribution_path_capture(
        "M13", "missed_incidents_complete",
        {"missedCount": len(missed)})
    # unresolved Outcomeは日次missionだけに閉じ込めず、各有効windowで再評価。
    # 同一window重複は上のleaseでここへ到達せず、Outcome ID/intervalも二重防御。
    outcome_retry_candidates = sum(
        1 for o in _OUTCOME_LEDGER
        if argus_decision_ledger.outcome_retry_due(o, now_iso=now_iso))
    outcome_stats = _memory_operation_run(
        "internal", "mission.outcome_resolution",
        _dl_resolve_matured, now_iso, max_records=max_outcomes,
        return_stats=True,
        deadline_monotonic=batch_started + time_budget_seconds)
    outcome_resolved_this_tick = outcome_stats["resolved"]
    if outcome_stats["processed"]:
        _MISSION_BATCH_STATE["cursor"] = (
            cursor_before + int(outcome_stats["processed"]))
        _append_tick_wal("batch_cursor", {
            "transitionState": {
                "batch": dict(_MISSION_BATCH_STATE)}})
    _memory_attribution_path_capture(
        "M14", "outcome_resolution_complete",
        {"processedOutcomeCount": int(outcome_stats["processed"])})
    failed_in_tick = 0
    processed_missions = 0
    mission_operation_names = {
        "pre_session_forecast": "mission.execute.pre_session_forecast",
        "post_session_snapshot": "mission.execute.post_session_snapshot",
        "missed_mission_recovery": "mission.execute.missed_mission_recovery",
        "forecast_outcome_resolution":
            "mission.execute.forecast_outcome_resolution",
        "daily_postmortem": "mission.execute.daily_postmortem",
        "weekly_learning_review": "mission.execute.weekly_learning_review",
        "monthly_model_review": "mission.execute.monthly_model_review",
        "benchmark_calibration": "mission.execute.benchmark_calibration",
    }
    for m in _MISSIONS:
        if _SHUTDOWN.get("requested"):
            break
        if argus_scheduler.batch_limit_reached(
                processed=processed_missions, max_events=max_missions,
                elapsed_seconds=time.monotonic() - batch_started,
                max_seconds=time_budget_seconds):
            break
        if m.get("status") not in ("scheduled", "retry_wait", "missed"):
            continue
        if m.get("status") != "missed" and str(m.get("scheduledFor", "")) > now_iso:
            continue                      # 未到来
        _was_missed = m.get("status") == "missed"
        if not argus_scheduler.claim(m, now_iso):
            continue
        mission_operation_token = None
        try:
            mt = m["missionType"]
            mission_operation_token = _memory_operation_begin(
                "internal", mission_operation_names.get(
                    mt, "mission.execute.other"), known=True,
                metadata={"missionType": str(mt)[:80]})
            if mt in ("pre_session_forecast", "post_session_snapshot",
                      "missed_mission_recovery"):
                # v12.2.2 Phase 2: プリフライト — コールド/調査ゼロなら発行せず
                # 決定論ウォームアップ(deep-diveキュー・外部AIなし・無料)を仕込む
                if not _OSINT_STORE:
                    for wsym in ("6965", "5803"):
                        if wsym not in _OSINT_AGENT_QUEUE and                                 len(_OSINT_AGENT_QUEUE) < _OSINT_QUEUE_MAX:
                            _OSINT_AGENT_QUEUE[wsym] = {
                                "market": "JP", "mode": "deep",
                                "privacyMode": "redacted",
                                "queuedAt": now_iso}
                    m["checkpoint"] = "warmup_queued"
                    argus_scheduler.complete(m, now_iso)
                    _persist_mission_transition(
                        m, cursor=int(_MISSION_BATCH_STATE.get(
                            "cursor") or 0) + 1)
                    executed.append(m["missionId"])
                    processed_missions += 1
                    _memory_operation_complete(
                        mission_operation_token, {"result": "ok"})
                    continue
                # 不変予測発行(成果を知る前・冪等はミッションキーで保証)
                for sym, inv in list(_OSINT_STORE.items())[:8]:
                    rec = argus_decision_ledger.forecast_record(
                        symbol=sym, market=m["market"],
                        issued_at=now_iso, horizon="next_session",
                        target_type="catalyst_verdict",
                        forecast_value=(inv.get("catalystVerdict") or {}).get(
                            "verdict", "unknown"),
                        primary_stance=(inv.get("ownerConclusion") or {}).get(
                            "statusJa", ""),
                        research_mission_id=inv.get("id") or "",
                        model_epoch=epoch,
                        prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
                        data_quality_status=(inv.get("storeWarmth") or {}).get(
                            "storeWarmth", "unknown"),
                        confidence=(inv.get("researchPower") or {}).get(
                            "statusJa", ""),
                        now_iso=now_iso)
                    # 冪等: 同一symbol×セッション日×targetTypeは1日1回
                    # (rec idは発行時刻を含むためcron毎に変わる — idでは重複を防げない)
                    if rec and not any(
                            f.get("symbol") == rec["symbol"] and
                            str(f.get("issuedAt", ""))[:10] == session_date and
                            f.get("targetType") == rec["targetType"]
                            for f in _FORECAST_LEDGER):
                        rec["origin"] = "forward_live"
                        _FORECAST_LEDGER.append(rec)
                        _journal("forecast_issued", "forecast",
                                 f"{rec['symbol']}:{session_date}:{rec['targetType']}",
                                 {"symbol": rec["symbol"],
                                  "targetType": rec["targetType"],
                                  "horizon": rec["forecastHorizon"]},
                                 origin="forward_live")
                while len(_FORECAST_LEDGER) > 200:
                    _FORECAST_LEDGER.pop(0)
            elif mt == "forecast_outcome_resolution":
                pass  # bounded retry pass already ran once for this HTTP batch
            elif mt == "daily_postmortem":
                resolved = [o for o in _OUTCOME_LEDGER
                            if o.get("status") == "resolved"]
                pm = {"sessionDate": session_date,
                      "forecastsIssued": len(_FORECAST_LEDGER),
                      "forecastsResolved": len(resolved),
                      "unresolvedCount": sum(
                          1 for f in _FORECAST_LEDGER
                          if not any(o.get("forecastId") == f.get("id") and
                                     o.get("status") == "resolved"
                                     for o in _OUTCOME_LEDGER)),
                      "ownerReadableSummaryJa": (
                          f"予測{len(_FORECAST_LEDGER)}件・解決{len(resolved)}件。"
                          + ("解決サンプルなし — 学習主張はしません。"
                             if not resolved else "")),
                      "origin": "forward_live"}
                if not any(x.get("sessionDate") == session_date
                           for x in _POSTMORTEMS):
                    _POSTMORTEMS.append(pm)
                while len(_POSTMORTEMS) > 30:
                    _POSTMORTEMS.pop(0)
            elif mt == "weekly_learning_review":
                rep = {"type": "WEEKLY LEARNING REVIEW",
                       "sessionDate": session_date,
                       "resolvedSamples": sum(1 for o in _OUTCOME_LEDGER
                                              if o.get("status") == "resolved"),
                       "ownerReadableJa": ("週次レビュー: 解決サンプル"
                                           f"{sum(1 for o in _OUTCOME_LEDGER if o.get('status') == 'resolved')}件"
                                           " — 不足時は学習主張なし"),
                       "origin": "forward_live"}
                if not any(r.get("sessionDate") == session_date and
                           r.get("type") == rep["type"] for r in _PERIODIC_REPORTS):
                    _PERIODIC_REPORTS.append(rep)
                # v12.2.2 Phase 7: 低リスクproposalのshadow challenger走行
                prop = argus_decision_ledger.learning_proposal(
                    proposal_type="query_expansion",
                    proposed_change="週次: 未回収由来の追撃語を検証",
                    sample_count=len(_OSINT_TERM_OVERLAY))
                if prop and prop["canAutoPromote"]:
                    _CHALLENGER_RUNS.append(
                        argus_decision_ledger.challenger_evaluation(
                            proposal=prop, champion_version="prod",
                            challenger_version="shadow-qx",
                            sample_count=len(_OUTCOME_LEDGER),
                            metric_before=None, metric_after=None,
                            now_iso=now_iso))
                    while len(_CHALLENGER_RUNS) > 8:
                        _CHALLENGER_RUNS.pop(0)
            elif mt in ("monthly_model_review", "benchmark_calibration"):
                rep = {"type": "MONTHLY AGENT REVIEW", "sessionDate": session_date,
                       "epochId": epoch,
                       "ownerReadableJa": "月次: エポック/校正/ドリフトの点検対象を記録",
                       "origin": "forward_live"}
                if not any(r.get("sessionDate") == session_date and
                           r.get("type") == rep["type"] for r in _PERIODIC_REPORTS):
                    _PERIODIC_REPORTS.append(rep)
                while len(_PERIODIC_REPORTS) > 12:
                    _PERIODIC_REPORTS.pop(0)
            # それ以外(OSINT等)は既存cronが担う — ここでは完了マークのみ
            if _was_missed:
                m["status"] = "recovered"
                m["completedAt"] = now_iso
                recovered += 1
                _journal("mission_recovered", "mission",
                         str(m.get("missionId")),
                         {"missionType": m.get("missionType") or "unknown"})
                for inc in _INCIDENTS:
                    if inc.get("id") == f"inc-{m.get('missionId')}" and                             inc.get("status") == "open":
                        inc["status"] = "resolved"
                        inc["resolvedAt"] = now_iso
                        # v12.2.9: open→resolved遷移時のみ発火(再解決は冪等)
                        _journal("incident_resolved", "incident",
                                 str(inc.get("id")),
                                 {"component": "scheduler",
                                  "missionType": inc.get("missionType")
                                  or "unknown"})
            else:
                argus_scheduler.complete(m, now_iso)
            _persist_mission_transition(
                m, cursor=int(_MISSION_BATCH_STATE.get("cursor") or 0) + 1)
            _recovery_phase_a_mark_post_session(m)
            executed.append(m["missionId"])
            processed_missions += 1
            _memory_operation_complete(
                mission_operation_token, {"result": "ok"})
        except Exception as e:
            _memory_operation_complete(
                mission_operation_token,
                {"result": "error", "errorClass": type(e).__name__})
            argus_scheduler.fail(m, now_iso, type(e).__name__)
            _persist_mission_transition(
                m, cursor=int(_MISSION_BATCH_STATE.get("cursor") or 0) + 1)
            processed_missions += 1
            failed_in_tick += 1
    while len(_MISSIONS) > 300:
        _MISSIONS.pop(0)
    while len(_MISSION_WINDOWS) > 240:
        _MISSION_WINDOWS.pop(0)
    _memory_attribution_path_capture(
        "M15", "mission_execution_complete",
        {"processedMissionCount": processed_missions,
         "failedMissionCount": failed_in_tick})

    # Formal Soak is an explicit acceptance operation.  Ordinary checkpoint
    # success, elapsed time, or a disabled Stage 1 never grants start authority.
    heartbeat_at = _ai_now_iso()
    expected_build_sha = str(body.get("expectedBuildSha") or "").lower()
    current_build_sha = str(_backend_exact_sha() or "").lower()
    qualified_natural_tick = bool(
        requested_source == "ec2_systemd" and
        trigger_source == "ec2_systemd" and
        re.fullmatch(r"[0-9a-f]{40}", expected_build_sha) and
        expected_build_sha == current_build_sha and
        str(window.get("missionWindowId") or "").startswith("mw-") and
        not str(window.get("missionWindowId") or "").startswith(
            "mw-manual-") and
        body.get("diagnostic") is not True and
        body.get("retrospective") is not True and
        body.get("replay") is not True)
    formal_soak_eligibility = \
        argus_checkpoint_v2_stage1.formal_soak_start_eligibility(
            _CHECKPOINT_V2_STAGE1_CONTROL,
            checkpoint_v2_enabled=_CHECKPOINT_V2_STAGE1_ENABLED,
            trigger_source=trigger_source,
            qualified_natural_tick=qualified_natural_tick,
            mission_window_id=window.get("missionWindowId"),
            current_build_sha=current_build_sha,
            expected_build_sha=expected_build_sha,
            active_soak_exists=_formal_soak_is_active(),
            active_soak_id=_SOAK.get("soakId"))
    if formal_soak_eligibility["eligible"]:
        _sk_dec = argus_runtime.soak_start_decision(
            now_iso=heartbeat_at, scheduled_for=window["scheduledFor"],
            trigger_source=trigger_source,
            mission_window_id=window["missionWindowId"],
            build_sha=_backend_sha() or None,
            app_version=_semantic_app_version() or "",
            process_booted_at=_RUNTIME["processBootedAt"],
            restore_completed_at=_STARTUP.get("restoreCompletedAt"),
            startup_state=_STARTUP["state"],
            integrity_ok=_DURABLE_STATE.get("integrityStatus")
            in ("ok", "unknown") or _STARTUP.get("restoreOutcome")
            in ("no_prior_state", "test_mode"),
            public_leak_safe=True, scheduler_ready=True)
        if _sk_dec["allowed"]:
            consumed_control = argus_checkpoint_v2_stage1.consume_arm(
                _CHECKPOINT_V2_STAGE1_CONTROL,
                consumed_at=heartbeat_at,
                mission_window_id=window["missionWindowId"],
                arm_id=_CHECKPOINT_V2_STAGE1_CONTROL.get("armId"))
            _activate_formal_soak(
                _sk_dec, window, rollover_armed=False)
            globals()["_CHECKPOINT_V2_STAGE1_CONTROL"] = consumed_control
            _journal("soak_started", "soak", _SOAK["soakId"],
                     {"buildSha": _SOAK["buildSha"] or "unknown",
                      "startTimeSource": _SOAK["startTimeSource"],
                      "firstMissionWindowId":
                      _SOAK["firstMissionWindowId"]})
    workflow_sha = str(body.get("expectedBuildSha") or "")[:7]
    build_matches = not workflow_sha or workflow_sha == (_backend_sha() or "")
    journal_status = (_REMOTE_ACK.get("lastReceiptStatus") or
                      _REMOTE_CYCLE.get("errorClass") or "pending")
    hb = (argus_runtime.soak_heartbeat(
        soak_id=_SOAK.get("soakId") or "", build_sha=_backend_sha(),
        runtime_version=_semantic_app_version() or "unknown",
        expected_at=window["scheduledFor"], observed_at=heartbeat_at,
        source=trigger_source,
        health_status=("ok" if build_matches else "build_mismatch"),
        ready_status=("ready" if _STARTUP["state"] in
                      ("ready", "ready_degraded") else "not_ready"),
        restore_outcome=_STARTUP.get("restoreOutcome"),
        durable_integrity=_DURABLE_STATE.get("integrityStatus") or "unknown",
        journal_status=journal_status,
        read_back_verified=bool(_REMOTE_CYCLE.get("readBackVerified")),
        scheduler_delay_seconds=argus_scheduler.observed_window_delay_seconds(
            window),
        evidence_type="scheduled_mission", now_iso=heartbeat_at)
          if trigger_source != "manual" else None)
    heartbeat_added = argus_runtime.append_soak_heartbeat(_SOAK, hb)
    if heartbeat_added:
        _journal("soak_heartbeat", "soak", _SOAK.get("soakId") or "unknown",
                 {"buildSha": _SOAK.get("buildSha") or "unknown",
                  "evidenceType": "scheduled_mission",
                  "stateHash": hb.get("stateHash")})
    soak_state = argus_runtime.build_soak_state(
        soak=_SOAK, now_iso=heartbeat_at,
        current_build_sha=_backend_sha(), required_hours=72)
    _SOAK["state"] = soak_state["state"]
    remaining_missions = sum(
        1 for mission in _MISSIONS
        if mission.get("status") in ("scheduled", "retry_wait", "missed") and
        (mission.get("status") == "missed" or
         str(mission.get("scheduledFor", "")) <= now_iso))
    remaining_count = remaining_missions + int(outcome_stats["remaining"])
    has_more = remaining_count > 0
    result = ("failed" if failed_in_tick else
              "partial" if has_more else "caught_up")
    _closure_remote_cycle = dict(_REMOTE_CYCLE)
    _receipt_queue_gate = argus_remote_receipt_queue.summary(
        _REMOTE_RECEIPT_QUEUE, now_iso=heartbeat_at)
    if _receipt_queue_gate["pendingCount"] or \
            _receipt_queue_gate["failedCount"]:
        _closure_remote_cycle.update({
            "remoteDurabilityState": (
                "failed" if _receipt_queue_gate["failedCount"] else
                "verification_pending"),
            "readBackVerified": False,
            "walReadBackVerified": False,
        })
    formal_closure = argus_runtime.formal_soak_closure(
        soak_state=soak_state, mission_result=result,
        remote_cycle=_closure_remote_cycle)
    _SOAK["completed72h"] = formal_closure["completed72h"]
    _SOAK["interruptionCount"] = len(
        _SOAK.get("interruptions") or [])
    terminal = ("failed" if failed_in_tick else
                "partial" if has_more else "completed")
    cursor_after = int(_MISSION_BATCH_STATE.get("cursor") or cursor_before)
    _MISSION_BATCH_STATE.update({
        "cursor": cursor_after,
        "remainingCount": remaining_count,
        "lastJobId": _MISSION_TICK_CONTEXT.get("jobId"),
        "lastResult": result,
        "lastCompletedAt": heartbeat_at,
    })
    _memory_attribution_path_capture(
        "M16", "soak_and_batch_bookkeeping_complete",
        {"formalSoakState": _SOAK.get("state"),
         "remainingCount": remaining_count})
    argus_scheduler.finish_mission_window(
        window_record, completed_at=heartbeat_at, status=terminal,
        error_class=("mission_execution_failed" if failed_in_tick else None))
    _memory_attribution_path_capture(
        "M17", "mission_window_finalized",
        {"windowStatus": terminal})
    checkpoint = _persist_with_remote_receipt_drain(heartbeat_at)
    if not checkpoint.get("verified"):
        terminal = "failed"
        result = "failed"
        window_record["status"] = "failed"
        window_record["finalStatus"] = "failed"
        window_record["errorClass"] = "checkpoint_verification_failed"
    elapsed_ms = round((time.monotonic() - batch_started) * 1000)
    cpu_ms = round((time.process_time() - float(
        _MISSION_TICK_CONTEXT.get("startedCpu") or time.process_time())) * 1000)
    response = {"ok": terminal != "failed",
                    "status": ("degraded" if result == "partial" else terminal),
                    "result": result,
                    "jobId": _MISSION_TICK_CONTEXT.get("jobId"),
                    "buildSha": os.environ.get("RENDER_GIT_COMMIT") or
                    _backend_sha(),
                    "processedCount": processed_missions +
                    int(outcome_stats["processed"]),
                    "processedMissionCount": processed_missions,
                    "processedOutcomeCount": int(outcome_stats["processed"]),
                    "remainingCount": remaining_count,
                    "hasMore": has_more,
                    "cursorBefore": cursor_before,
                    "cursorAfter": cursor_after,
                    "checkpointCreated": bool(checkpoint.get("verified")),
                    "checkpoint": {
                        "snapshotBytes": checkpoint.get("snapshotBytes"),
                        "serializationMs": checkpoint.get("serializationMs"),
                        "checkpointMs": checkpoint.get("checkpointMs"),
                        "includedWalSequence": checkpoint.get(
                            "includedWalSequence"),
                        "walBytes": ((checkpoint.get("walCompaction") or {})
                                     .get("bytes")),
                    },
                    "metrics": {
                        "elapsedMs": elapsed_ms,
                        "cpuMs": cpu_ms,
                        "rssBeforeBytes": _MISSION_TICK_CONTEXT.get(
                            "rssBeforeBytes"),
                        "rssAfterBytes": argus_tick_durability.current_rss_bytes(),
                        "rssMaxRaw": resource.getrusage(
                            resource.RUSAGE_SELF).ru_maxrss,
                        "walEventCount": int(_MISSION_TICK_CONTEXT.get(
                            "walEventCount") or 0),
                        "walAppendMs": _MISSION_TICK_CONTEXT.get("walAppendMs"),
                        "checkpointCount": 1 if checkpoint.get("verified") else 0,
                        "checkpointMs": checkpoint.get("checkpointMs"),
                        "eventLimit": max_missions + max_outcomes,
                        "timeBudgetSeconds": time_budget_seconds,
                    },
                    "created": len(created),
                    "executed": executed[:12], "missedDetected": len(missed),
                    "recovered": recovered,
                    "marketLedger": ledger_tick,
                    "chartIntelligence": chart_tick,
                    "assetChartCache": asset_chart_tick,
                    "dailyShortSelling": daily_short_tick,
                    "missionWindow": window_record,
                    "outcomeRetry": {
                        "evaluated": outcome_retry_candidates,
                        "resolved": outcome_resolved_this_tick,
                        "processed": outcome_stats["processed"],
                        "remaining": outcome_stats["remaining"],
                        "outcomeCount": len(_OUTCOME_LEDGER),
                        "duplicateCount": (len([
                            row for row in _OUTCOME_LEDGER
                            if isinstance(row, dict) and row.get("forecastId")
                        ]) - len({str(row.get("forecastId"))
                                  for row in _OUTCOME_LEDGER
                                  if isinstance(row, dict)
                                  and row.get("forecastId")}))},
                    "soakHeartbeatAdded": heartbeat_added,
                    "soak": soak_state,
                    "formalSoakEligibility": formal_soak_eligibility,
                    "formalSoakClosure": formal_closure,
                    "remoteJournal": {
                        **dict(_REMOTE_CYCLE),
                        **_remote_journal_diagnostics(heartbeat_at)},
                    "costPolicy": {
                        "mode": _COST_POLICY.get("mode"),
                        "automaticAiEnabled": bool(
                            _COST_POLICY.get("automaticAiEnabled")),
                        "automaticAiExecutions": (0 if not _COST_POLICY.get(
                            "automaticAiEnabled") else None)},
                    "ops": argus_scheduler.ops_summary(_MISSIONS)}
    return (jsonify(response), 500) if terminal == "failed" else jsonify(response)


@app.route("/api/argus/admin/decision-ledger/snapshot", methods=["POST"])
def api_argus_admin_dl_snapshot():
    """Admin/cron: 当日判断の不変スナップショット(成果を知る前に発行)。
    冪等キーで重複発行を防止。公開ルートからは発行不可。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    now_iso = _ai_now_iso()
    idem = f"dl-{now_iso[:10]}-{str(body.get('session') or 'daily')}"
    if argus_decision_ledger.is_duplicate_job(_DL_JOBS, idem):
        return jsonify({"ok": True, "duplicate": True,
                        "noteJa": "本日分は発行済み(冪等)。"})
    _DL_JOBS.append(argus_decision_ledger.job_record(
        job_id=idem, mission_type="forecast_snapshot", scheduled_at=now_iso,
        idempotency_key=idem, status="complete"))
    made = 0
    for sym, inv in list(_OSINT_STORE.items())[:12]:
        rp = inv.get("researchPower") or {}
        rec = argus_decision_ledger.forecast_record(
            symbol=sym, market=("JP" if sym[:1].isdigit() else "US"),
            issued_at=now_iso, horizon="next_session",
            target_type="catalyst_verdict",
            forecast_value=(inv.get("catalystVerdict") or {}).get("verdict", "unknown"),
            primary_stance=(inv.get("ownerConclusion") or {}).get("statusJa", ""),
            research_mission_id=inv.get("id") or "",
            model_epoch=argus_ai_gate.model_epoch_id(
                provider="gemini", model=GEMINI_MODEL_ID,
                prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
                tool_mode="grounding"),
            prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
            data_quality_status=(inv.get("storeWarmth") or {}).get("storeWarmth",
                                                                   "unknown"),
            confidence=rp.get("statusJa") or "",
            mock_data=False, now_iso=now_iso)
        if rec:
            _FORECAST_LEDGER.append(rec)
            made += 1
    while len(_FORECAST_LEDGER) > 200:
        _FORECAST_LEDGER.pop(0)
    while len(_DL_JOBS) > 60:
        _DL_JOBS.pop(0)
    return jsonify({"ok": True, "issued": made,
                    "ledgerSize": len(_FORECAST_LEDGER),
                    "noteJa": "予測は発行後に編集不可(成果は別レコードで解決)。"})


def _osint_benchmark_worker(case_ids):
    """v12.1.7: ベンチケースのGemini基準run実行(admin/cron専用・redacted固定)。
    外部AI不在はskipped/insufficient_data — 偽passを作らない。"""
    try:
        for cid in case_ids:
            case = next((c for c in argus_osint_engine.GEMINI_BENCHMARK_SUITE
                         if (c.get("id") or c.get("case")) == cid), None)
            if case is None:
                continue
            now_iso = _ai_now_iso()
            rec = {"id": f"bench-{cid}-{int(time.time())}", "caseId": cid,
                   "caseName": case.get("name"), "startedAt": now_iso,
                   "completedAt": None, "status": "running",
                   "mode": "calibration", "privacyMode": "redacted",
                   "geminiRuns": [], "gptRun": None, "scores": None,
                   "weakPillars": [], "blockersJa": [], "ownerReadableJa": None}
            if not (google_genai and GEMINI_API_KEY):
                rec["status"] = "skipped"
                rec["ownerReadableJa"] = "Gemini未設定 — insufficient_data(偽passなし)"
                rec["completedAt"] = _ai_now_iso()
                _OSINT_BENCHMARK_RUNS.append(rec)
                continue
            prompt = argus_osint_engine.benchmark_prompt(case)
            out, status = _gemini_osint(prompt)
            grun = _osint_agent_run("gemini", status, out, now_iso, "redacted")
            claims = grun.get("claims") or []
            gscore = argus_osint_engine.external_rubric_score(claims) if claims else 0
            rec["geminiRuns"].append({"score": gscore, "status": status,
                                      "claimCount": len(claims)})
            if status == "ok" and gscore:
                _OSINT_BASELINE_RUNS.append({
                    "score": gscore, "case": cid, "symbol": cid, "at": _ai_now_iso(),
                    "promptVersion": argus_osint_engine.SCOUT_PROMPT_VERSION,
                    "epochId": argus_ai_gate.model_epoch_id(
                        provider="gemini", model=GEMINI_MODEL_ID,
                        prompt_version=argus_osint_engine.SCOUT_PROMPT_VERSION,
                        tool_mode="grounding"),
                    "privacyMode": "redacted"})
                while len(_OSINT_BASELINE_RUNS) > 24:
                    _OSINT_BASELINE_RUNS.pop(0)
            # ARGUS側: ケース関連銘柄の最新調査RPSがあれば比較(なければ判定材料不足)
            argus_rps = None
            if cid == "hamamatsu_seaj_optical":
                argus_rps = (_OSINT_STORE.get("6965") or {}).get("researchPower")
            cs = argus_osint_engine.benchmark_case_score(case, claims, argus_rps)
            rec["scores"] = cs
            rec["weakPillars"] = cs.get("weakPillars") or []
            rec["status"] = ("complete" if status == "ok" else "failed_safe")
            rec["ownerReadableJa"] = cs.get("ownerReadableJa")
            rec["completedAt"] = _ai_now_iso()
            _OSINT_BENCHMARK_RUNS.append(rec)
            while len(_OSINT_BENCHMARK_RUNS) > 20:
                _OSINT_BENCHMARK_RUNS.pop(0)
        _osint_persist()
        add_log(f"[osint] benchmark done: {case_ids}")
    except Exception as e:
        add_log(f"[osint] benchmark failed: {type(e).__name__}")
    finally:
        _OSINT_BENCH_STATE["running"] = False
        _OSINT_BENCH_STATE["lastAt"] = _ai_now_iso()


def _ai_capability_probe(model, *, confirmation=False, expected_text="ok",
                         purpose="manual_api"):
    """v12.2.0: モデル能力プローブ(admin/cron専用・私的文脈なし・秘密非出力)。"""
    out = {"model": model, "requestedModel": model, "responseModel": None,
           "apiEndpoint": "responses", "accessible": False,
           "responsesSupported": False,
           "structuredOutputsSupported": "unknown", "webSearchSupported": "unknown",
           "usageReturned": False, "usage": None,
           "pricingVersion": _BENCHMARK_PRICING_VERSION,
           "createdAt": _ai_now_iso(), "errorClass": None,
           "matchedExpectedText": False, "responseTextPresent": False}
    if not _cost_policy_authorize(
            "openai", purpose, automatic=False, confirmation=confirmation,
            estimated_cost_usd=0.001, estimated_tokens=50)["allowed"]:
        out["errorClass"] = "cost_policy_blocked"
        return out
    if not _OPENAI_API_KEY:
        out["errorClass"] = "no_api_key"
        return out
    try:
        import openai
        client = openai.OpenAI(api_key=_OPENAI_API_KEY)
        r = client.responses.create(
            model=model, input=f"Reply exactly {expected_text}",
            timeout=30, store=False, max_output_tokens=64)
        _cost_policy_record("openai", purpose, estimated_cost_usd=0.001)
        output_text = str(getattr(r, "output_text", None) or "").strip()
        out["matchedExpectedText"] = output_text == expected_text
        # Availability is a transport/response property. Exact instruction
        # following remains diagnostic evidence, but must not turn a successful,
        # non-empty Responses API call into a false provider outage.
        out["responseTextPresent"] = bool(output_text)
        out["accessible"] = out["responseTextPresent"]
        out["responsesSupported"] = True
        u = _usage_tokens(r)
        out["usageReturned"] = bool(u and (u[0] or u[1]))
        out["usage"] = {"inputTokens": (u or (0, 0))[0],
                        "outputTokens": (u or (0, 0))[1]}
        out["responseModel"] = getattr(r, "model", None)
    except Exception as e:
        out["errorClass"] = type(e).__name__[:40]
    return out


def _gemini_enum(value):
    if value is None:
        return None
    name = getattr(value, "name", None)
    return str(name or value).split(".")[-1]


def _gemini_response_metadata(response, requested_model, expected_text=None):
    """Extract only provider/control metadata; never retain prompts or response text."""
    candidates_out = []
    all_text = []
    for candidate in (getattr(response, "candidates", None) or []):
        parts = list(getattr(getattr(candidate, "content", None), "parts", None) or [])
        part_types = []
        text_count = 0
        nonempty_count = 0
        for part in parts:
            part_type = "unknown"
            text_value = getattr(part, "text", None)
            if text_value is not None:
                part_type = "text"
                text_count += 1
                if str(text_value):
                    nonempty_count += 1
                    all_text.append(str(text_value))
            elif getattr(part, "function_call", None) is not None:
                part_type = "function_call"
            elif getattr(part, "inline_data", None) is not None:
                part_type = "inline_data"
            elif getattr(part, "file_data", None) is not None:
                part_type = "file_data"
            if getattr(part, "thought", False):
                part_type += ":thought"
            part_types.append(part_type)
        safety = []
        for rating in (getattr(candidate, "safety_ratings", None) or []):
            safety.append({"category": _gemini_enum(getattr(rating, "category", None)),
                           "probability": _gemini_enum(getattr(
                               rating, "probability", None)),
                           "blocked": bool(getattr(rating, "blocked", False))})
        candidates_out.append({
            "finishReason": _gemini_enum(getattr(candidate, "finish_reason", None)),
            "finishMessage": str(getattr(candidate, "finish_message", None) or "")[:240] or None,
            "partsCount": len(parts), "partTypes": part_types,
            "textPartCount": text_count,
            "nonEmptyTextPartCount": nonempty_count,
            "safetyRatings": safety})
    feedback = getattr(response, "prompt_feedback", None)
    prompt_safety = []
    for rating in (getattr(feedback, "safety_ratings", None) or []):
        prompt_safety.append({"category": _gemini_enum(getattr(rating, "category", None)),
                              "probability": _gemini_enum(getattr(
                                  rating, "probability", None)),
                              "blocked": bool(getattr(rating, "blocked", False))})
    usage = getattr(response, "usage_metadata", None)
    token_counts = {
        "promptTokenCount": int(getattr(usage, "prompt_token_count", 0) or 0),
        "thoughtsTokenCount": int(getattr(usage, "thoughts_token_count", 0) or 0),
        "candidatesTokenCount": int(getattr(usage, "candidates_token_count", 0) or 0),
        "totalTokenCount": int(getattr(usage, "total_token_count", 0) or 0),
    }
    joined = "".join(all_text).strip()
    return {"model": requested_model, "requestedModel": requested_model,
            "responseModel": (getattr(response, "model_version", None)
                              or getattr(response, "model", None)),
            "modelVersion": getattr(response, "model_version", None),
            "responseId": getattr(response, "response_id", None),
            "apiEndpoint": "models.generateContent",
            "candidateCount": len(candidates_out), "candidates": candidates_out,
            "partsCount": sum(x["partsCount"] for x in candidates_out),
            "textPartExists": any(x["textPartCount"] > 0 for x in candidates_out),
            "nonEmptyTextPartExists": any(
                x["nonEmptyTextPartCount"] > 0 for x in candidates_out),
            "matchedExpectedText": (joined == expected_text if expected_text else None),
            "promptFeedback": {
                "blockReason": _gemini_enum(getattr(feedback, "block_reason", None)),
                "blockReasonMessage": str(getattr(
                    feedback, "block_reason_message", None) or "")[:240] or None,
                "safetyRatings": prompt_safety},
            "tokenCounts": token_counts,
            "usageReturned": any(token_counts.values()),
            "usage": {"inputTokens": token_counts["promptTokenCount"],
                      "outputTokens": (token_counts["candidatesTokenCount"]
                                       + token_counts["thoughtsTokenCount"])},
            "pricingVersion": _BENCHMARK_PRICING_VERSION,
            "createdAt": _ai_now_iso(), "errorClass": None}


def _gemini_probe_config():
    if not genai_types:
        return None
    kwargs = {"temperature": 0, "max_output_tokens": 1024,
              "candidate_count": 1, "response_mime_type": "text/plain"}
    try:
        kwargs["thinking_config"] = genai_types.ThinkingConfig(
            thinking_level="low")
    except (AttributeError, TypeError, ValueError):
        pass
    return genai_types.GenerateContentConfig(**kwargs)


def _gemini_capability_probe(model, *, confirmation=False, max_attempts=1,
                             purpose="manual_api"):
    base = {"model": model, "requestedModel": model, "responseModel": None,
            "apiEndpoint": "models.generateContent", "accessible": False,
            "usageReturned": False, "usage": None, "attempts": [],
            "pricingVersion": _BENCHMARK_PRICING_VERSION,
            "createdAt": _ai_now_iso(), "errorClass": None,
            "classification": None}
    if not _cost_policy_authorize(
            "gemini", purpose, automatic=False, confirmation=confirmation,
            estimated_cost_usd=0.01, estimated_tokens=1200)["allowed"]:
        base["errorClass"] = "cost_policy_blocked"
        base["classification"] = "malformed_request"
        return base
    if not google_genai or not GEMINI_API_KEY:
        base["errorClass"] = "no_api_key"
        base["classification"] = "malformed_request"
        return base
    client = google_genai.Client(api_key=GEMINI_API_KEY)
    expected = "ARGUS_GEMINI_OK"
    for attempt in range(1, max(1, min(int(max_attempts), 3)) + 1):
        try:
            response = client.models.generate_content(
                model=model, contents="Reply with exactly: ARGUS_GEMINI_OK",
                config=_gemini_probe_config())
            row = _gemini_response_metadata(response, model, expected)
            _cost_policy_record("gemini", purpose, estimated_cost_usd=0.01)
        except Exception as exc:
            row = {**base, "attempts": None,
                   "errorClass": type(exc).__name__[:80]}
        row["attempt"] = attempt
        row["classification"] = argus_foundation_jobs.classify_gemini_preflight(
            row, expected_text=expected)
        row["accessible"] = row["classification"] == "success"
        base["attempts"].append(row)
        base.update({k: v for k, v in row.items() if k != "attempts"})
        if row["accessible"] or row["classification"] in {
                "safety_block", "malformed_request", "recitation"}:
            break
        if attempt < max_attempts:
            time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                attempt, seed=f"gemini-preflight:{model}:{attempt}"))
    return base


def _gemini_models_proof():
    out = {"modelsApiAccessible": False, "models": [], "errorClass": None}
    if not google_genai or not GEMINI_API_KEY:
        out["errorClass"] = "no_api_key"
        return out
    try:
        client = google_genai.Client(api_key=GEMINI_API_KEY)
        for model in client.models.list():
            name = str(getattr(model, "name", None) or "")
            if "gemini" not in name.lower() or "pro" not in name.lower():
                continue
            actions = (getattr(model, "supported_actions", None)
                       or getattr(model, "supported_generation_methods", None) or [])
            out["models"].append({
                "name": name, "displayName": getattr(model, "display_name", None),
                "stage": _gemini_enum(getattr(model, "stage", None)),
                "inputTokenLimit": getattr(model, "input_token_limit", None),
                "outputTokenLimit": getattr(model, "output_token_limit", None),
                "supportedActions": [str(x) for x in actions]})
        out["modelsApiAccessible"] = True
    except Exception as exc:
        out["errorClass"] = type(exc).__name__[:80]
    return out


def _gemini_preflight_value():
    preview = _gemini_capability_probe(
        "gemini-3.1-pro-preview", confirmation=True, max_attempts=3)
    models = _gemini_models_proof()
    stable_id = argus_foundation_jobs.select_latest_stable_gemini_pro(
        models.get("models") or [])
    stable = None
    preview_attempts = preview.get("attempts") or []
    defect_classes = {"max_tokens", "no_text_part", "preview_empty_output",
                      "transient_provider_error"}
    preview_defect = (len(preview_attempts) == 3 and all(
        x.get("classification") in defect_classes for x in preview_attempts))
    if not preview.get("accessible") and stable_id:
        stable = _gemini_capability_probe(
            stable_id, confirmation=True, max_attempts=1)
    stable_path = bool(preview_defect and stable and stable.get("accessible"))
    selected = ("gemini-3.1-pro-preview" if preview.get("accessible")
                else stable_id if stable_path else None)
    return {"status": "verified" if selected else "failed",
            "preview": preview, "modelsApi": models,
            "stable": stable, "stableModel": stable_id,
            "previewProviderDefect": preview_defect,
            "stableProviderPath": stable_path,
            "selectedBaselineModel": selected,
            "baselineSwapReason": ("preview_provider_defect"
                                   if stable_path else None)}


def _gemini_preflight_worker(job_id):
    try:
        _foundation_job_update(job_id, status="running")
        if _COST_POLICY.get("mode") not in _COST_POLICY_IDLE_MODES:
            raise RuntimeError("normal_mode_not_deterministic")
        manual = argus_cost_policy.configure(
            _COST_POLICY, mode="MANUAL", event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(manual)
        try:
            result = _gemini_preflight_value()
        finally:
            restored = argus_cost_policy.configure(
                _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
            _COST_POLICY.clear()
            _COST_POLICY.update(restored)
        if result.get("status") != "verified":
            raise RuntimeError("gemini_preflight_failed")
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        restored = argus_cost_policy.configure(
            _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(restored)
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        _foundation_job_update(job_id, status="failed",
                               error_class=error_class[:80])


@app.route("/api/argus/admin/ai/capability-probe", methods=["POST"])
def api_argus_admin_ai_capability_probe():
    """Admin専用: GPT-5.6等の可用性プローブ。仮定で昇格しない — 実測のみ。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    if (_COST_POLICY.get("mode") == "MANUAL"
            and (body.get("confirm") is not True
                 or not str(body.get("reason") or "").strip())):
        return jsonify({"ok": False,
                        "error": "explicit_confirmation_and_reason_required"}), 400
    models = body.get("models") or [m for m in {
        _OPENAI_MODEL_ROLES.get("extract"), _OPENAI_MODEL_ROLES.get("standard"),
        _OPENAI_MODEL_ROLES.get("war_room"), _OPENAI_SHADOW.get("candidate")} if m]
    results = [_ai_capability_probe(str(m)[:60], confirmation=True)
               for m in models[:5]]
    gemini_models = body.get("geminiModels") or []
    gemini_results = [_gemini_capability_probe(str(m)[:80], confirmation=True)
                      for m in gemini_models[:3]]
    return jsonify({"ok": True,
                    "provider": "multi", "estimatedCostUsdPerModel": 0.001,
                    "reason": str(body.get("reason"))[:160], "results": results,
                    "geminiResults": gemini_results,
                    "noteJa": "実測プローブのみ — 可用性を仮定した昇格はしない。"})


def _formal_benchmark_prompt(case):
    return (
        f"調査質問: {case['question']}\n"
        f"asOf/information cutoff: {case['informationCutoff']}\n"
        f"許可ソース種別: {', '.join(case['permittedSources'])}\n"
        "時点後の情報は禁止。不明は不明と回答する。投資助言・売買指示は禁止。"
        "出力はJSONのみ: {\"claims\":[{\"titleJa\",\"url\",\"publishedAt\","
        "\"sourceName\",\"directness\",\"whyRelevant\",\"confidence\"}]}。")


def _formal_claims(out, case=None):
    rows = []
    permitted = set((case or {}).get("permittedSources") or [])
    for c in ((out or {}).get("claims") or [])[:20]:
        if not isinstance(c, dict):
            continue
        source = str(c.get("sourceName") or "").strip().lower()
        url = str(c.get("url") or "")[:600] or None
        url_valid = bool(url and re.match(r"^https://[^\s/]+(?:/|$)", url))
        source_valid = bool(source and (not permitted or source in permitted))
        rows.append({"titleJa": str(c.get("titleJa") or c.get("title") or "")[:300],
                     "url": url,
                     "publishedAt": c.get("publishedAt"),
                     "sourceId": source[:80] or None,
                     "sourceValidated": bool(url_valid and source_valid),
                     "directness": str(c.get("directness") or "unknown")[:40],
                     "fabricated": c.get("fabricated") is True})
    return rows


def _formal_blind_evaluate(case, benchmark_id, claims_by_provider,
                           diagnostic_context=None):
    """One OpenAI evaluator call, provider names hidden; no retry/fallback."""
    order = argus_research_benchmark.blind_order(benchmark_id, case["caseId"])
    answers = {label: claims_by_provider[provider] for label, provider in order.items()}
    policy = _cost_policy_authorize(
        "openai", "research_benchmark", automatic=False, confirmation=True,
        estimated_cost_usd=0.10, estimated_tokens=8000)
    if not policy["allowed"] or not _OPENAI_API_KEY:
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "provider_blocked",
                                       "errorClass": "authorization_blocked"})
        return None, "provider_blocked", None
    prompt = (
        "固定rubricでA/Bを独立採点。提供元を推測せず、各軸0-100。JSONのみ。"
        f"質問={case['question']} cutoff={case['informationCutoff']} "
        f"rubric={json.dumps(argus_research_benchmark.RUBRIC_WEIGHTS, sort_keys=True)} "
        f"answers={json.dumps(answers, ensure_ascii=False, sort_keys=True)} "
        "形式={\"A\":{rubric各キー},\"B\":{rubric各キー}}")
    # Dry-run assumes at most 6,000 input tokens. A UTF-8 byte ceiling is a
    # conservative fail-closed guard and prevents an unexpectedly large source
    # payload from escaping the fixed per-call budget.
    if len(prompt.encode("utf-8")) > 24_000:
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "input_budget_exceeded",
                                       "errorClass": "input_budget_exceeded"})
        return None, "input_budget_exceeded", None
    try:
        import openai
        client = openai.OpenAI(api_key=_OPENAI_API_KEY)
        evaluator_model = _openai_model_for("referee")
        response = client.responses.create(
            model=evaluator_model, input=prompt, timeout=90, store=False,
            reasoning={"effort": _BENCHMARK_REASONING_EFFORT},
            max_output_tokens=_BENCHMARK_MAX_OUTPUT_TOKENS)
        parsed = safe_json(getattr(response, "output_text", "") or "")
        if not isinstance(parsed, dict) or not all(
                isinstance(parsed.get(k), dict) for k in ("A", "B")):
            if isinstance(diagnostic_context, dict):
                diagnostic_context.update({
                    "status": "invalid_evaluator_json",
                    "errorClass": "invalid_evaluator_json",
                    "responseStatus": str(
                        getattr(response, "status", None) or "unknown")[:40]})
            return None, "invalid_evaluator_json", None
        usage = _usage_tokens(response) or (0, 0)
        meta = {"provider": "openai", "apiEndpoint": "responses",
                "requestedModel": evaluator_model,
                "responseModel": getattr(response, "model", None),
                "usage": {"inputTokens": usage[0], "outputTokens": usage[1]},
                "createdAt": _ai_now_iso(),
                "pricingVersion": _BENCHMARK_PRICING_VERSION}
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({
                "status": "ok", "errorClass": None,
                "requestedModel": evaluator_model,
                "responseModel": meta.get("responseModel"),
                "usage": meta.get("usage")})
        return {"A": parsed["A"], "B": parsed["B"]}, "ok", meta
    except Exception as exc:
        add_log(f"[formal-benchmark] evaluator failed: {type(exc).__name__}")
        if isinstance(diagnostic_context, dict):
            diagnostic_context.update({"status": "provider_failed",
                                       "errorClass": type(exc).__name__[:80]})
        return None, "provider_failed", None


def _benchmark_usage_cost_jpy(calls, usd_jpy):
    total_usd = 0.0
    for call in calls:
        requested = str(call.get("requestedModel") or "")
        usage = call.get("usage") or {}
        inp = max(0, int(usage.get("inputTokens") or 0))
        out = max(0, int(usage.get("outputTokens") or 0))
        if requested == "gemini-3.1-pro-preview" and inp > 200000:
            in_rate, out_rate = 4.0, 18.0
        else:
            rate = _AI_PRICING.get(requested) or {}
            in_rate, out_rate = float(rate.get("in") or 0), float(rate.get("out") or 0)
        total_usd += (inp * in_rate + out * out_rate) / 1_000_000
        if call.get("provider") == "gemini":
            total_usd += max(0.0, float(_AI_GROUNDING_USD))
    return round(total_usd * float(usd_jpy), 2), round(total_usd, 6)


def _formal_benchmark_worker(benchmark_id, dry_run, availability_proof=None,
                             gemini_model=None):
    """Frozen calibration then one-shot holdout. Always returns to the idle mode."""
    results = []
    provider_calls = []
    failure = None
    diagnostic = {"failureStage": None, "failureCaseId": None,
                  "provider": {}}
    try:
        for case in argus_research_benchmark.execution_plan():
            if case["phase"] == "holdout" and not \
                    _FORMAL_BENCHMARK.get("holdoutConsumedBy"):
                consumed = argus_research_benchmark.consume_holdout(
                    _FORMAL_BENCHMARK, benchmark_id=benchmark_id)
                if not consumed["allowed"]:
                    failure = consumed["status"]
                    break
                _FORMAL_BENCHMARK.clear()
                _FORMAL_BENCHMARK.update(consumed["state"])
                _osint_persist()
            prompt = _formal_benchmark_prompt(case)
            baseline_diag = {}
            baseline_out, baseline_status = _gemini_osint(
                prompt, benchmark=True, model_override=gemini_model,
                diagnostic_context=baseline_diag)
            diagnostic["provider"]["geminiBaseline"] = baseline_diag
            if baseline_status != "ok":
                failure = "provider_blocked" if baseline_status in (
                    "disabled", "deterministic_mode") else "provider_failed"
                diagnostic.update({"failureStage": "gemini_baseline",
                                   "failureCaseId": case.get("caseId")})
                break
            provider_calls.append(dict((baseline_out or {}).get("_providerMeta") or {}))
            # ARGUS platform comparison: same question/cutoff, two scouts plus
            # deterministic source/temporal checks. Tool asymmetry is recorded.
            argus_gemini_diag, argus_gpt_diag = {}, {}
            argus_gemini, ag_status = _gemini_osint(
                prompt, benchmark=True, model_override=gemini_model,
                diagnostic_context=argus_gemini_diag)
            argus_gpt, ao_status = _gpt_osint(
                prompt, benchmark=True,
                diagnostic_context=argus_gpt_diag)
            diagnostic["provider"]["argusGemini"] = argus_gemini_diag
            diagnostic["provider"]["argusOpenAI"] = argus_gpt_diag
            if ag_status != "ok" or ao_status != "ok":
                failure = "provider_blocked" if "disabled" in (ag_status, ao_status) \
                    else "provider_failed"
                diagnostic.update({
                    "failureStage": ("argus_gemini" if ag_status != "ok"
                                     else "argus_openai"),
                    "failureCaseId": case.get("caseId")})
                break
            provider_calls.append(dict((argus_gemini or {}).get("_providerMeta") or {}))
            provider_calls.append(dict((argus_gpt or {}).get("_providerMeta") or {}))
            claims = {"gemini": _formal_claims(baseline_out, case),
                      "argus": (_formal_claims(argus_gemini, case)
                                + _formal_claims(argus_gpt, case))[:30]}
            referee_diag = {}
            axes, eval_status, evaluator_meta = _formal_blind_evaluate(
                case, benchmark_id, claims,
                diagnostic_context=referee_diag)
            diagnostic["provider"]["referee"] = referee_diag
            if eval_status != "ok":
                failure = eval_status
                diagnostic.update({"failureStage": "referee",
                                   "failureCaseId": case.get("caseId")})
                break
            provider_calls.append(dict(evaluator_meta or {}))
            results.append(argus_research_benchmark.case_result(
                benchmark_id=benchmark_id, case=case,
                evaluator_axes_by_label=axes, claims_by_provider=claims))
        if failure:
            failed_state = argus_research_benchmark.fail_closed(
                _FORMAL_BENCHMARK, status=failure, completed_at=_ai_now_iso())
            _FORMAL_BENCHMARK.clear()
            _FORMAL_BENCHMARK.update(failed_state)
            _journal("research_benchmark_failed", "research_benchmark",
                     benchmark_id, {"status": failure}, origin="admin_validation")
        else:
            missing_model_evidence = [x for x in provider_calls
                                      if not x.get("requestedModel")
                                      or not x.get("responseModel")]
            argus_response_models = {x.get("responseModel") for x in provider_calls
                                     if x.get("requestedModel") ==
                                     (_OPENAI_MODEL_ROLES.get("standard") or _OPENAI_MODEL)}
            evaluator_response_models = {x.get("responseModel") for x in provider_calls
                                         if x.get("requestedModel") ==
                                         _openai_model_for("referee")}
            if missing_model_evidence:
                raise RuntimeError("model_evidence_missing")
            if len(argus_response_models) != 1 or len(evaluator_response_models) != 1:
                raise RuntimeError("response_model_inconsistent")
            if argus_response_models == evaluator_response_models:
                raise RuntimeError("evaluator_not_independent")
            gemini_response_models = {x.get("responseModel") for x in provider_calls
                                      if x.get("provider") == "gemini"}
            if len(gemini_response_models) != 1:
                raise RuntimeError("gemini_response_model_inconsistent")
            fx = _float_env("ARGUS_BENCHMARK_USDJPY_CEILING", 160.0)
            actual_cost_jpy, actual_cost_usd = _benchmark_usage_cost_jpy(
                provider_calls, fx)
            if actual_cost_jpy > argus_research_benchmark.HARD_BUDGET_JPY:
                raise RuntimeError("actual_budget_exceeded")
            completed = argus_research_benchmark.finalize(
                state=_FORMAL_BENCHMARK, benchmark_id=benchmark_id,
                research_epoch=_current_epoch_id(), code_sha=_backend_sha() or "local",
                models={"gemini": next(iter(gemini_response_models)),
                        "argus": next(iter(argus_response_models)),
                        "evaluator": next(iter(evaluator_response_models)),
                        "argusVersion": _semantic_app_version()},
                provider_settings={"temperature": {"gemini": 0,
                                   "openai": "provider_default",
                                   "evaluator": "provider_default"},
                                   "reasoningEffort": {
                                       "openai": _BENCHMARK_REASONING_EFFORT,
                                       "evaluator": _BENCHMARK_REASONING_EFFORT,
                                       "gemini": "low"},
                                   "maximumOutputTokensPerCall":
                                       _BENCHMARK_MAX_OUTPUT_TOKENS,
                                   "baselineTools": ["google_search"],
                                   "argusTools": ["google_search", "web_search",
                                                  "deterministic_source_checks"],
                                   "costStatus": "estimated_from_provider_usage",
                                   "pricingVersion": _BENCHMARK_PRICING_VERSION,
                                   "pricingCatalog": _BENCHMARK_PRICING_CATALOG,
                                   "modelAvailabilityProof": availability_proof or {},
                                   "providerCalls": provider_calls,
                                   "actualCostUsd": actual_cost_usd,
                                   "usdJpyCeiling": fx,
                                   "implementationFrozen": True,
                                   "rubricFrozen": True,
                                   "providerModelsFrozen": True},
                total_cost_jpy=actual_cost_jpy,
                case_results=results, completed_at=_ai_now_iso(),
                limitations=["基盤込み比較: ARGUS側は複数scoutと決定論検証を使用",
                             "費用はprovider usageとgrounding上限から算出。請求書確定額ではない"])
            _FORMAL_BENCHMARK.clear()
            _FORMAL_BENCHMARK.update(completed["state"])
            _journal("research_benchmark_completed", "research_benchmark",
                     benchmark_id,
                     {"classification": completed["status"],
                      "twoXClaimAllowed": bool(
                          completed.get("result", {}).get("twoXClaimAllowed")),
                      "datasetHash": argus_research_benchmark.DATASET_HASH[:16]},
                     origin="admin_validation")
    except Exception as exc:
        add_log(f"[formal-benchmark] failed: {type(exc).__name__}")
        failed_state = argus_research_benchmark.fail_closed(
            _FORMAL_BENCHMARK, status="invalid", completed_at=_ai_now_iso())
        _FORMAL_BENCHMARK.clear()
        _FORMAL_BENCHMARK.update(failed_state)
    finally:
        # A benchmark can never leave benchmark-mode AI enabled afterwards.
        restored = argus_cost_policy.configure(
            _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(restored)
        _osint_persist()
    diagnostic["completedCaseCount"] = len(results)
    diagnostic["holdoutConsumed"] = bool(
        _FORMAL_BENCHMARK.get("holdoutConsumedBy"))
    diagnostic["finalStatus"] = _FORMAL_BENCHMARK.get("status")
    return diagnostic


def _v2_dry_run_value():
    """Three calls/case: Gemini baseline, ARGUS Sol, independent Terra referee."""
    fx = _float_env("ARGUS_BENCHMARK_USDJPY_CEILING", 160.0)
    models = {"gemini": "gemini-3.1-pro-preview",
              "argus": "gpt-5.6-sol", "referee": "gpt-5.6-terra"}
    input_tokens, output_tokens = 6000, 1800
    per_case_usd = 0.0
    for model in models.values():
        rate = _AI_PRICING.get(model) or {}
        per_case_usd += (input_tokens * float(rate.get("in") or 0)
                         + output_tokens * float(rate.get("out") or 0)) / 1_000_000
    per_case_usd += max(0.0, float(_AI_GROUNDING_USD))
    estimated_usd = per_case_usd * (
        argus_research_benchmark_v2.CALIBRATION_CASES
        + argus_research_benchmark_v2.HOLDOUT_CASES)
    estimated_jpy = estimated_usd * fx
    body = {"status": ("ready" if estimated_jpy <=
                       argus_research_benchmark_v2.HARD_BUDGET_JPY
                       else "budget_blocked"),
            "models": models, "caseCount": 18, "callsPerCase": 3,
            "maximumCallsWithoutRetry": 54,
            "inputTokensPerCall": input_tokens,
            "outputTokensPerCall": output_tokens,
            "cacheAssumed": False, "groundingUsdPerGeminiCall": _AI_GROUNDING_USD,
            "usdJpyCeiling": fx, "estimatedCostUsd": round(estimated_usd, 6),
            "estimatedCostJpy": round(estimated_jpy, 2),
            "hardBudgetJpy": argus_research_benchmark_v2.HARD_BUDGET_JPY,
            "pricingVersion": _BENCHMARK_PRICING_VERSION,
            "pricingCatalog": _BENCHMARK_PRICING_CATALOG}
    body["confirmationHash"] = argus_research_benchmark_v2.digest(body)
    return body


def _v2_source_access(manifest):
    urls = sorted({str(source.get("url")) for phase in ("calibration", "holdout")
                   for case in (manifest.get(phase) or [])
                   for source in (case.get("primarySourceDocuments") or [])
                   if source.get("url")})
    access, proof = {}, []
    headers = {"User-Agent": "A.R.G.U.S. research benchmark evidence validator "
                             "admin@argus.invalid"}
    for url in urls:
        last_error = None
        status = None
        for attempt in range(1, 4):
            try:
                response = requests.get(url, headers=headers, timeout=20,
                                        allow_redirects=True)
                status = int(response.status_code)
                if 200 <= status < 400 and bool(response.content):
                    access[url] = True
                    last_error = None
                    break
                last_error = f"http_{status}"
                if status not in (408, 425, 429) and status < 500:
                    break
            except requests.RequestException as exc:
                last_error = type(exc).__name__[:80]
            if attempt < 3:
                time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                    attempt, seed=f"v2-source:{url}:{attempt}"))
        access.setdefault(url, False)
        proof.append({"urlHash": hashlib.sha256(url.encode()).hexdigest()[:16],
                      "accessible": access[url], "httpStatus": status,
                      "errorClass": last_error})
    return access, proof


def _v2_prompt(case):
    sources = [{k: source.get(k) for k in (
        "sourceId", "title", "url", "sourcePublishedAt", "availableFrom")}
        for source in (case.get("primarySourceDocuments") or [])]
    return (
        f"調査質問: {case['ownerQuestion']}\n"
        f"asOf/evidence cutoff: {case['allowedEvidenceCutoff']}\n"
        f"一次資料package: {json.dumps(sources, ensure_ascii=False, sort_keys=True)}\n"
        "時点後の情報は禁止。一次資料を優先し、事実・解釈・不明を分ける。"
        "投資助言・売買指示は禁止。JSONのみ: "
        "{\"claims\":[{\"titleJa\",\"url\",\"publishedAt\","
        "\"sourceName\",\"directness\",\"whyRelevant\",\"confidence\"}]}。")


def _v2_blind_evaluate(case, run_id, claims_by_provider):
    order = argus_research_benchmark_v2.blind_order(run_id, case["caseId"])
    answers = {label: claims_by_provider[provider]
               for label, provider in order.items()}
    policy = _cost_policy_authorize(
        "openai", "research_benchmark", automatic=False, confirmation=True,
        estimated_cost_usd=0.10, estimated_tokens=8000)
    if not policy["allowed"] or not _OPENAI_API_KEY:
        return None, "provider_blocked", None
    prompt = (
        "A/Bの提供元を推測せず、各品質軸を0-100で独立採点する。"
        "弱い回答もtransport/parse成功なら採点し、case無効にはしない。JSONのみ。"
        f"question={case['ownerQuestion']} cutoff={case['allowedEvidenceCutoff']} "
        f"rubric={json.dumps(argus_research_benchmark_v2.QUALITY_WEIGHTS, sort_keys=True)} "
        f"answers={json.dumps(answers, ensure_ascii=False, sort_keys=True)} "
        "format={\"A\":{rubric各キー},\"B\":{rubric各キー}}")
    if len(prompt.encode("utf-8")) > 24_000:
        return None, "input_budget_exceeded", None
    try:
        import openai
        client = openai.OpenAI(api_key=_OPENAI_API_KEY)
        model = _openai_model_for("referee")
        response = client.responses.create(
            model=model, input=prompt, timeout=90, store=False,
            reasoning={"effort": _BENCHMARK_REASONING_EFFORT},
            max_output_tokens=_BENCHMARK_MAX_OUTPUT_TOKENS)
        parsed = safe_json(getattr(response, "output_text", "") or "")
        if not isinstance(parsed, dict) or not all(
                isinstance(parsed.get(label), dict) for label in ("A", "B")):
            return None, "invalid_evaluator_json", None
        usage = _usage_tokens(response) or (0, 0)
        meta = {"provider": "openai", "apiEndpoint": "responses",
                "requestedModel": model, "responseModel": getattr(response, "model", None),
                "responseId": getattr(response, "id", None),
                "usage": {"inputTokens": usage[0], "outputTokens": usage[1]},
                "pricingVersion": _BENCHMARK_PRICING_VERSION,
                "createdAt": _ai_now_iso()}
        return {"A": parsed["A"], "B": parsed["B"]}, "ok", meta
    except Exception as exc:
        add_log(f"[formal-benchmark-v2] evaluator failed: {type(exc).__name__}")
        return None, "provider_failed", {"errorClass": type(exc).__name__[:80]}


def _v2_evaluate_with_retry(case, run_id, claims_by_provider):
    last_axes, last_status, last_meta = None, "provider_failed", None
    for attempt in range(1, 3):
        last_axes, last_status, last_meta = _v2_blind_evaluate(
            case, run_id, claims_by_provider)
        if last_status == "ok":
            return last_axes, last_status, last_meta, attempt
        if last_status in ("provider_blocked", "invalid_evaluator_json",
                           "input_budget_exceeded"):
            break
        if attempt < 2:
            time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                attempt, seed=f"v2-referee:{case['caseId']}:{attempt}"))
    return last_axes, last_status, last_meta, attempt


def _v2_provider_evidence(meta, *, attempts):
    """Persist audit metadata only; provider text, prompts and credentials are excluded."""
    value = meta if isinstance(meta, dict) else {}
    usage = value.get("usage") if isinstance(value.get("usage"), dict) else {}
    return {"provider": value.get("provider"),
            "apiEndpoint": value.get("apiEndpoint"),
            "requestedModel": value.get("requestedModel"),
            "responseModel": value.get("responseModel"),
            "responseId": value.get("responseId"),
            "usage": {"inputTokens": int(usage.get("inputTokens") or 0),
                      "cachedInputTokens": int(usage.get("cachedInputTokens") or 0),
                      "outputTokens": int(usage.get("outputTokens") or 0),
                      "reasoningTokens": int(usage.get("reasoningTokens") or 0)},
            "createdAt": value.get("createdAt"),
            "pricingVersion": value.get("pricingVersion"),
            "attempts": int(attempts)}


def _v2_exact_model_match(meta):
    value = meta if isinstance(meta, dict) else {}
    requested = str(value.get("requestedModel") or "")
    response = str(value.get("responseModel") or "")
    return bool(requested and response and
                (response == requested or response.startswith(requested + "-")))


def _v2_capability_probe_passed(meta):
    """Provider availability contract used before any calibration is scored."""
    value = meta if isinstance(meta, dict) else {}
    if value.get("apiEndpoint") == "models.generateContent":
        candidates = value.get("candidates") or []
        response_ok = bool(value.get("nonEmptyTextPartExists") is True
                           and candidates
                           and all(row.get("finishReason") == "STOP"
                                   for row in candidates)
                           and not (value.get("promptFeedback") or {}).get(
                               "blockReason"))
    else:
        response_ok = value.get("responseTextPresent") is True
    return bool(response_ok and value.get("usageReturned") is True
                and value.get("responseModel")
                and value.get("errorClass") is None)


def _v2_next_calibration_attempt(state):
    """Count actual calibration attempts, not failures before case execution."""
    value = state if isinstance(state, dict) else {}
    preflight_only = (value.get("status") == "v2_provider_preflight_failed"
                      and not value.get("calibrationRuns")
                      and not value.get("frozenRun")
                      and not value.get("holdoutConsumedBy"))
    current = 0 if preflight_only else int(
        value.get("calibrationAttemptCount") or 0)
    return current + 1


def _v2_call_with_retry(call):
    last_out, last_status = None, "provider_failed"
    for attempt in range(1, 3):
        out, status = call()
        last_out, last_status = out, status
        if status == "ok":
            return out, status, attempt
        if status in ("disabled", "deterministic_mode", "budget_limited",
                      "unavailable", "invalid_evaluator_json",
                      "input_budget_exceeded"):
            break
        if attempt < 2:
            time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                attempt, seed=f"v2-provider:{status}:{attempt}"))
    return last_out, last_status, attempt


def _v2_remote_journal_verified(cycle=None):
    value = cycle if isinstance(cycle, dict) else _REMOTE_CYCLE
    expected = value.get("expectedHash")
    return bool(value.get("readBackVerified") is True
                and value.get("remoteCommitSha")
                and expected
                and expected == value.get("actualHash"))


def _v2_protocol_gates(*, exact_models, budget_ok, append_only):
    return {"frozenDatasetHash": True, "unusedHoldout": True,
            "exactProviderModel": bool(exact_models), "responseReceived": True,
            "parseSuccess": True, "blindLabelRandomization": True,
            "noFutureLeakage": True, "noDuplicateCase": True,
            "noCaseSpecificTuning": True, "evaluatorIndependent": True,
            "deterministicScorerExecuted": True,
            "budgetCompliance": bool(budget_ok), "oneTimeHoldout": True,
            "appendOnlyResult": bool(append_only),
            "remoteJournalReadBack": _v2_remote_journal_verified()}


def _research_benchmark_v2_job_worker(job_id):
    global _FORMAL_BENCHMARK_V2
    provider_calls = []
    source_proof = []
    preflight = {"sourceAccess": source_proof}
    try:
        _foundation_job_update(job_id, status="running")
        latest_v1 = ((_FORMAL_BENCHMARK.get("results") or [None])[-1] or {})
        if not latest_v1 or latest_v1.get("resultClassification") != "invalid":
            raise RuntimeError("v1_invalid_result_not_available")
        closed_state = argus_research_benchmark_v2.close_v1(
            _FORMAL_BENCHMARK_V2, latest_v1, closed_at=_ai_now_iso(),
            remote_receipt={"remoteCommitSha": _REMOTE_CYCLE.get("remoteCommitSha"),
                            "readBackVerified": _REMOTE_CYCLE.get("readBackVerified")})
        _FORMAL_BENCHMARK_V2.clear()
        _FORMAL_BENCHMARK_V2.update(closed_state)
        if _FORMAL_BENCHMARK_V2.get("holdoutConsumedBy"):
            raise RuntimeError("v2_holdout_already_consumed")
        code_sha = _backend_sha() or "local"
        manifest = argus_research_benchmark_v2.frozen_manifest(code_sha)
        source_access, source_proof = _v2_source_access(manifest)
        v1_ids = [x.get("caseId") for x in argus_research_benchmark.FORMAL_DATASET]
        v1_questions = [x.get("question") for x in
                        argus_research_benchmark.FORMAL_DATASET]
        validation = argus_research_benchmark_v2.validate_manifest(
            manifest, v1_case_ids=v1_ids, v1_questions=v1_questions,
            source_access=source_access)
        if not validation["valid"] or validation["validatedCaseCount"] != 18:
            raise RuntimeError("v2_manifest_validation_failed")
        _FORMAL_BENCHMARK_V2["manifest"] = manifest
        dry = _v2_dry_run_value()
        if dry["status"] != "ready" or dry["estimatedCostJpy"] > 2000:
            raise RuntimeError("v2_budget_blocked")
        if (_openai_model_for("standard") != "gpt-5.6-sol" or
                _openai_model_for("referee") != "gpt-5.6-terra"):
            raise RuntimeError("v2_exact_model_configuration_mismatch")
        enabled = argus_cost_policy.configure(
            _COST_POLICY, mode="RESEARCH_BENCHMARK", event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(enabled)
        gemini_probe = _gemini_capability_probe(
            "gemini-3.1-pro-preview", confirmation=True, max_attempts=3,
            purpose="research_benchmark")
        def openai_probe(model, expected):
            latest = None
            for attempt in range(1, 4):
                latest = _ai_capability_probe(
                    model, confirmation=True, expected_text=expected,
                    purpose="research_benchmark")
                if latest.get("accessible"):
                    break
                if attempt < 3:
                    time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                        attempt, seed=f"v2-probe:{model}:{attempt}"))
            return latest or {}
        sol_probe = openai_probe("gpt-5.6-sol", "ARGUS_SOL_OK")
        terra_probe = openai_probe("gpt-5.6-terra", "ARGUS_TERRA_OK")
        preflight = {"gemini": gemini_probe, "sol": sol_probe,
                     "terra": terra_probe, "sourceAccess": source_proof}
        if not all(_v2_capability_probe_passed(probe) for probe in
                   (gemini_probe, sol_probe, terra_probe)):
            raise RuntimeError("v2_provider_preflight_failed")
        if not all(_v2_exact_model_match(probe) for probe in
                   (gemini_probe, sol_probe, terra_probe)):
            raise RuntimeError("v2_provider_response_model_mismatch")
        if sol_probe.get("responseModel") == terra_probe.get("responseModel"):
            raise RuntimeError("v2_evaluator_not_independent")
        calibration_attempt = _v2_next_calibration_attempt(
            _FORMAL_BENCHMARK_V2)
        if calibration_attempt > 3:
            raise RuntimeError("v2_calibration_retry_limit_reached")
        _FORMAL_BENCHMARK_V2["calibrationAttemptCount"] = calibration_attempt
        _osint_persist()
        def run_cases(cases, run_id, holdout=False):
            rows = []
            for case in cases:
                prompt = _v2_prompt(case)
                baseline, baseline_status, baseline_attempts = _v2_call_with_retry(lambda:
                    _gemini_osint(prompt, benchmark=True,
                                  model_override="gemini-3.1-pro-preview"))
                if baseline_status != "ok":
                    raise RuntimeError("v2_gemini_transport_failed")
                argus_out, argus_status, argus_attempts = _v2_call_with_retry(lambda:
                    _gpt_osint(prompt, benchmark=True))
                if argus_status != "ok":
                    raise RuntimeError("v2_argus_transport_failed")
                provider_calls.extend([
                    dict((baseline or {}).get("_providerMeta") or {}),
                    dict((argus_out or {}).get("_providerMeta") or {})])
                claims = {"gemini": _formal_claims(baseline),
                          "argus": _formal_claims(argus_out)}
                axes, eval_status, referee_meta, referee_attempts = \
                    _v2_evaluate_with_retry(case, run_id, claims)
                if eval_status != "ok":
                    raise RuntimeError(f"v2_referee_{eval_status}")
                provider_calls.append(dict(referee_meta or {}))
                actual_jpy, _ = _benchmark_usage_cost_jpy(
                    provider_calls, dry["usdJpyCeiling"])
                case_provider_meta = [
                    dict((baseline or {}).get("_providerMeta") or {}),
                    dict((argus_out or {}).get("_providerMeta") or {}),
                    dict(referee_meta or {})]
                case_cost_jpy, case_cost_usd = _benchmark_usage_cost_jpy(
                    case_provider_meta, dry["usdJpyCeiling"])
                gates = _v2_protocol_gates(
                    exact_models=all(_v2_exact_model_match(x)
                                     for x in case_provider_meta),
                    budget_ok=actual_jpy <= 2000,
                    append_only=not any(x.get("benchmarkId") == run_id for x in
                                        (_FORMAL_BENCHMARK_V2.get("results") or [])))
                row = argus_research_benchmark_v2.score_case(
                    run_id=run_id, case=case, axes_by_label=axes,
                    claims_by_provider=claims, protocol_gates=gates)
                row["providerEvidence"] = {
                    "gemini": _v2_provider_evidence(
                        (baseline or {}).get("_providerMeta"),
                        attempts=baseline_attempts),
                    "argus": _v2_provider_evidence(
                        (argus_out or {}).get("_providerMeta"),
                        attempts=argus_attempts),
                    "referee": _v2_provider_evidence(
                        referee_meta, attempts=referee_attempts),
                }
                row["scoredAt"] = _ai_now_iso()
                row["usageCost"] = {
                    "actualFromProviderUsageUsd": case_cost_usd,
                    "actualFromProviderUsageJpy": case_cost_jpy,
                    "usdJpyCeiling": dry["usdJpyCeiling"],
                    "pricingVersion": _BENCHMARK_PRICING_VERSION,
                }
                rows.append(row)
                _foundation_job_update(
                    job_id, progress={"completedUnits": len(provider_calls) // 3,
                                      "totalUnits": 18,
                                      "percent": round((len(provider_calls) // 3)
                                                       / 18 * 100, 2)},
                    checkpoint={"phase": "holdout" if holdout else "calibration",
                                "lastCaseId": case["caseId"]})
            return rows

        calibration_id = "v2-cal-" + argus_research_benchmark_v2.digest(
            manifest["datasetHash"] + _ai_now_iso())[:16]
        calibration_rows = run_cases(manifest["calibration"], calibration_id)
        implementation_hash = argus_research_benchmark_v2.digest({
            "codeSha": code_sha, "rubric": argus_research_benchmark_v2.RUBRIC_VERSION,
            "models": dry["models"], "prompt": "v2-evidence-package"})
        calibrated_state = argus_research_benchmark_v2.record_calibration(
            _FORMAL_BENCHMARK_V2, run_id=calibration_id,
            rows=calibration_rows, completed_at=_ai_now_iso(),
            models=dry["models"], implementation_hash=implementation_hash)
        _FORMAL_BENCHMARK_V2.clear()
        _FORMAL_BENCHMARK_V2.update(calibrated_state)
        _FORMAL_BENCHMARK_V2["manifest"] = manifest
        if not _FORMAL_BENCHMARK_V2.get("frozenRun"):
            raise RuntimeError("v2_calibration_not_6_of_6")
        holdout_id = "v2-hold-" + argus_research_benchmark_v2.digest(
            manifest["datasetHash"] + implementation_hash)[:16]
        consumed = argus_research_benchmark_v2.consume_holdout(
            _FORMAL_BENCHMARK_V2, run_id=holdout_id)
        if not consumed["allowed"]:
            raise RuntimeError(consumed["status"])
        _FORMAL_BENCHMARK_V2.clear()
        _FORMAL_BENCHMARK_V2.update(consumed["state"])
        _osint_persist()
        holdout_rows = run_cases(manifest["holdout"], holdout_id, holdout=True)
        requested_models = {
            "gemini": {x.get("responseModel") for x in provider_calls
                        if x.get("requestedModel") == "gemini-3.1-pro-preview"},
            "argus": {x.get("responseModel") for x in provider_calls
                      if x.get("requestedModel") == "gpt-5.6-sol"},
            "referee": {x.get("responseModel") for x in provider_calls
                        if x.get("requestedModel") == "gpt-5.6-terra"}}
        if any(len(values) != 1 for values in requested_models.values()):
            raise RuntimeError("v2_response_model_inconsistent")
        exact_models = {key: next(iter(values)) for key, values in requested_models.items()}
        if exact_models["argus"] == exact_models["referee"]:
            raise RuntimeError("v2_evaluator_not_independent")
        actual_jpy, actual_usd = _benchmark_usage_cost_jpy(
            provider_calls, dry["usdJpyCeiling"])
        completed = argus_research_benchmark_v2.finalize(
            _FORMAL_BENCHMARK_V2, run_id=holdout_id, rows=holdout_rows,
            models=exact_models, provider_proof=preflight,
            pricing={"version": _BENCHMARK_PRICING_VERSION,
                     "catalog": _BENCHMARK_PRICING_CATALOG,
                     "estimatedCostJpy": dry["estimatedCostJpy"],
                     "actualCostUsd": actual_usd,
                     "usdJpyCeiling": dry["usdJpyCeiling"]},
            actual_cost_jpy=actual_jpy, completed_at=_ai_now_iso())
        _FORMAL_BENCHMARK_V2.clear()
        _FORMAL_BENCHMARK_V2.update(completed["state"])
        _journal("research_benchmark_v2_completed", "research_benchmark_v2",
                 holdout_id, {"status": completed["status"],
                              "twoXClaimAllowed": completed["result"][
                                  "twoXClaimAllowed"],
                              "datasetHash": manifest["datasetHash"][:16]},
                 origin="admin_validation")
        _osint_persist()
        _foundation_job_update(job_id, status="completed", result={
            "status": completed["status"], "benchmarkId": holdout_id,
            "dryRun": dry, "manifestValidation": validation,
            "providerPreflight": preflight,
            "formalResult": argus_research_benchmark_v2.public_status(
                _FORMAL_BENCHMARK_V2)})
    except Exception as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        _FORMAL_BENCHMARK_V2["mode"] = "DETERMINISTIC"
        _FORMAL_BENCHMARK_V2["runningBenchmarkId"] = None
        _FORMAL_BENCHMARK_V2["status"] = error_class[:80]
        _foundation_job_update(job_id, status="failed",
                               result={"sourceAccess": source_proof,
                                       "providerPreflight": preflight},
                               error_class=error_class[:80])
    finally:
        restored = argus_cost_policy.configure(
            _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(restored)
        _osint_persist()


@app.route("/api/argus/research-benchmark")
def api_argus_research_benchmark_status():
    """Public-safe result summary. GET never starts or resumes a benchmark."""
    legacy = argus_research_benchmark.public_status(_FORMAL_BENCHMARK)
    legacy["protocolV1Closure"] = dict(
        _FORMAL_BENCHMARK_V2.get("v1Closure") or {})
    legacy["protocolV2"] = argus_research_benchmark_v2.public_status(
        _FORMAL_BENCHMARK_V2)
    return jsonify(legacy)


@app.route("/api/argus/admin/research-benchmark/dry-run", methods=["POST"])
def api_argus_admin_research_benchmark_dry_run():
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    if body.get("triggerSource") != "manual":
        return jsonify({"ok": False, "status": "scheduled_execution_rejected"}), 400
    dry = _formal_benchmark_dry_run_value()
    _store_formal_dry_run(dry)
    _osint_persist()
    return jsonify({"ok": dry["status"] == "ready", **dry})


def _store_formal_dry_run(dry):
    """Persist confirmation data without erasing a recoverable terminal state."""
    _FORMAL_BENCHMARK["dryRun"] = dry
    if int(_FORMAL_BENCHMARK.get("executionCount") or 0) == 0:
        _FORMAL_BENCHMARK["status"] = dry["status"]


def _formal_benchmark_dry_run_value(gemini_model=None):
    evaluator = _openai_model_for("referee")
    pricing = dict(_AI_PRICING)
    if evaluator not in pricing and _OPENAI_MODEL in pricing:
        pricing[evaluator] = dict(pricing[_OPENAI_MODEL])
    fx = max(1.0, _float_env("ARGUS_BENCHMARK_USDJPY_CEILING", 160.0))
    # The owner-approved formal-run ceiling is independent of the ordinary
    # daily generated-AI budget.  This does not alter scheduled/interactive AI
    # guards; only this frozen one-shot estimate receives the explicit JPY cap.
    benchmark_budget_usd = argus_research_benchmark.HARD_BUDGET_JPY / fx
    dry = argus_research_benchmark.estimate_cost(
        gemini_model=gemini_model or _GEMINI_BENCHMARK_MODEL,
        argus_model=_OPENAI_MODEL_ROLES.get("standard") or _OPENAI_MODEL,
        evaluator_model=evaluator, pricing=pricing,
        usd_jpy_ceiling=fx,
        output_tokens_per_call=_BENCHMARK_MAX_OUTPUT_TOKENS,
        grounding_usd_per_call=_AI_GROUNDING_USD,
        existing_budget_usd=benchmark_budget_usd,
        providers_configured=bool(google_genai and GEMINI_API_KEY
                                  and _OPENAI_API_KEY))
    dry["pricingVersion"] = _BENCHMARK_PRICING_VERSION
    dry["pricingCatalog"] = _BENCHMARK_PRICING_CATALOG
    dry["cacheApplied"] = False
    dry["comparisonType"] = "Gemini baseline vs ARGUS research system"
    # Added fields are part of the confirmation contract.
    dry["dryRunHash"] = argus_research_benchmark.digest(
        {k: v for k, v in dry.items() if k != "dryRunHash"})
    return dry


@app.route("/api/argus/admin/research-benchmark/execute", methods=["POST"])
def api_argus_admin_research_benchmark_execute():
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    dry = _FORMAL_BENCHMARK.get("dryRun") or {}
    if body.get("dryRunHash") != dry.get("dryRunHash"):
        return jsonify({"ok": False, "status": "dry_run_hash_mismatch"}), 409
    if _COST_POLICY.get("mode") not in _COST_POLICY_IDLE_MODES:
        return jsonify({"ok": False, "status": "normal_mode_not_deterministic"}), 409
    benchmark_id = "gemini-2x-" + argus_research_benchmark.digest({
        "datasetHash": argus_research_benchmark.DATASET_HASH,
        "startedAt": _ai_now_iso()})[:16]
    decision = argus_research_benchmark.begin(
        _FORMAL_BENCHMARK, dry_run=dry, benchmark_id=benchmark_id,
        trigger_source=str(body.get("triggerSource") or ""),
        confirmed=body.get("confirm") is True, started_at=_ai_now_iso())
    if not decision["allowed"]:
        return jsonify({"ok": False, "status": decision["status"]}), 409
    _FORMAL_BENCHMARK.clear()
    _FORMAL_BENCHMARK.update(decision["state"])
    enabled = argus_cost_policy.configure(
        _COST_POLICY, mode="RESEARCH_BENCHMARK", event_opt_in=False)
    _COST_POLICY.clear()
    _COST_POLICY.update(enabled)
    threading.Thread(
        target=_memory_operation_run,
        args=("background", "formal_benchmark_worker",
              _formal_benchmark_worker, benchmark_id, dry),
        daemon=True).start()
    return jsonify({"ok": True, "status": "running",
                    "benchmarkId": benchmark_id,
                    "datasetHash": argus_research_benchmark.DATASET_HASH}), 202


def _research_pipeline_preflight_worker(job_id):
    """Exercise each formal provider path without touching benchmark state.

    This is a paid but bounded connectivity/contract check: one Gemini search,
    one OpenAI search, and one Terra referee call.  It never scores a dataset
    case, consumes the holdout, or persists provider text/claims.
    """
    result = {"status": "failed", "caseId": None, "stages": {},
              "holdoutConsumed": bool(
                  _FORMAL_BENCHMARK.get("holdoutConsumedBy"))}
    try:
        _foundation_job_update(job_id, status="running")
        if _COST_POLICY.get("mode") not in _COST_POLICY_IDLE_MODES:
            raise RuntimeError("normal_mode_not_deterministic")
        prior_preflight = next((
            (x.get("result") or {}) for x in reversed(
                _FOUNDATION_JOBS.get("jobs", []))
            if x.get("jobType") == "GEMINI_PREFLIGHT"
            and x.get("status") == "completed"
            and (x.get("result") or {}).get("status") == "verified"
            and (x.get("result") or {}).get("selectedBaselineModel")), None)
        gemini_model = (prior_preflight or {}).get("selectedBaselineModel")
        if not gemini_model:
            raise RuntimeError("gemini_preflight_required")
        case = argus_research_benchmark.execution_plan()[0]
        result["caseId"] = case.get("caseId")
        result["baselineModel"] = gemini_model
        prompt = _formal_benchmark_prompt(case)
        enabled = argus_cost_policy.configure(
            _COST_POLICY, mode="RESEARCH_BENCHMARK", event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(enabled)
        try:
            gemini_diag, openai_diag, referee_diag = {}, {}, {}
            gemini_out, gemini_status = _gemini_osint(
                prompt, benchmark=True, model_override=gemini_model,
                diagnostic_context=gemini_diag)
            result["stages"]["geminiSearch"] = gemini_diag
            if gemini_status != "ok":
                raise RuntimeError("gemini_search_failed")
            openai_out, openai_status = _gpt_osint(
                prompt, benchmark=True, diagnostic_context=openai_diag)
            result["stages"]["openaiSearch"] = openai_diag
            if openai_status != "ok":
                raise RuntimeError("openai_search_failed")
            claims = {
                "gemini": _formal_claims(gemini_out, case),
                "argus": (_formal_claims(gemini_out, case)
                          + _formal_claims(openai_out, case))[:30]}
            _, referee_status, _ = _formal_blind_evaluate(
                case, "pipeline-preflight", claims,
                diagnostic_context=referee_diag)
            result["stages"]["referee"] = referee_diag
            if referee_status != "ok":
                raise RuntimeError(referee_status)
        finally:
            restored = argus_cost_policy.configure(
                _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
            _COST_POLICY.clear()
            _COST_POLICY.update(restored)
            _osint_persist()
        result.update({"status": "verified", "reasoningEffort":
                       _BENCHMARK_REASONING_EFFORT,
                       "maximumOutputTokens": _BENCHMARK_MAX_OUTPUT_TOKENS})
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        restored = argus_cost_policy.configure(
            _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(restored)
        _osint_persist()
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        result["errorClass"] = error_class[:80]
        _foundation_job_update(job_id, status="failed", result=result,
                               error_class=error_class[:80])


def _research_benchmark_job_worker(job_id):
    proof = {"openai": [], "geminiPreflight": None}
    try:
        _foundation_job_update(job_id, status="running")
        if _COST_POLICY.get("mode") not in _COST_POLICY_IDLE_MODES:
            raise RuntimeError("normal_mode_not_deterministic")
        manual = argus_cost_policy.configure(
            _COST_POLICY, mode="MANUAL", event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(manual)
        try:
            proof["openai"] = [
                _ai_capability_probe("gpt-5.6-sol", confirmation=True),
                _ai_capability_probe("gpt-5.6-terra", confirmation=True),
            ]
            prior_preflight = next((
                (x.get("result") or {}) for x in reversed(
                    _FOUNDATION_JOBS.get("jobs", []))
                if x.get("jobType") == "GEMINI_PREFLIGHT"
                and x.get("status") == "completed"
                and (x.get("result") or {}).get("status") == "verified"
                and (x.get("result") or {}).get("selectedBaselineModel")), None)
            proof["geminiPreflight"] = prior_preflight or _gemini_preflight_value()
        finally:
            restored = argus_cost_policy.configure(
                _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
            _COST_POLICY.clear()
            _COST_POLICY.update(restored)
        if not all(x.get("accessible") and x.get("usageReturned")
                   and x.get("errorClass") is None and x.get("responseModel")
                   for x in proof["openai"]):
            raise RuntimeError("model_availability_probe_failed")
        preflight = proof["geminiPreflight"] or {}
        gemini_model = preflight.get("selectedBaselineModel")
        if preflight.get("status") != "verified" or not gemini_model:
            raise RuntimeError("gemini_preflight_failed")
        if proof["openai"][0]["responseModel"] == proof["openai"][1]["responseModel"]:
            raise RuntimeError("evaluator_not_independent")
        dry = _formal_benchmark_dry_run_value(gemini_model)
        if dry.get("status") != "ready" or float(
                dry.get("estimatedCostJpy") or 999999) > 2000:
            raise RuntimeError(str(dry.get("status") or "dry_run_blocked"))
        _store_formal_dry_run(dry)
        benchmark_id = "gemini-2x-" + argus_research_benchmark.digest({
            "datasetHash": argus_research_benchmark.DATASET_HASH,
            "startedAt": _ai_now_iso()})[:16]
        decision = argus_research_benchmark.begin(
            _FORMAL_BENCHMARK, dry_run=dry, benchmark_id=benchmark_id,
            trigger_source="manual", confirmed=True, started_at=_ai_now_iso())
        if not decision["allowed"]:
            raise RuntimeError(decision["status"])
        _FORMAL_BENCHMARK.clear()
        _FORMAL_BENCHMARK.update(decision["state"])
        enabled = argus_cost_policy.configure(
            _COST_POLICY, mode="RESEARCH_BENCHMARK", event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(enabled)
        _osint_persist()
        benchmark_diagnostic = _formal_benchmark_worker(
            benchmark_id, dry, proof, gemini_model)
        final_status = str(_FORMAL_BENCHMARK.get("status") or "invalid")
        latest = ((_FORMAL_BENCHMARK.get("results") or [None])[-1] or {})
        result = {"benchmarkId": benchmark_id, "status": final_status,
                  "datasetHash": argus_research_benchmark.DATASET_HASH,
                  "dryRun": dry, "modelAvailabilityProof": proof,
                  "formalBaselineModel": gemini_model,
                  "resultClassification": latest.get("resultClassification"),
                  "twoXClaimAllowed": bool(latest.get("twoXClaimAllowed")),
                  "totalCostJpy": latest.get("totalCostJpy"),
                  "pipelineDiagnostic": benchmark_diagnostic}
        if final_status not in ("achieved", "not_achieved"):
            raise RuntimeError(final_status)
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        restored = argus_cost_policy.configure(
            _COST_POLICY, mode=_COST_POLICY_BASELINE_MODE, event_opt_in=False)
        _COST_POLICY.clear()
        _COST_POLICY.update(restored)
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        _foundation_job_update(job_id, status="failed",
                               result={"modelAvailabilityProof": proof,
                                       "pipelineDiagnostic": locals().get(
                                           "benchmark_diagnostic")},
                               error_class=error_class[:80])


def _foundation_job_dispatch(job_id):
    job = _foundation_job(job_id) or {}
    job_type = job.get("jobType")
    if job_type in ("JQUANTS_BREADTH_BACKFILL", "JQUANTS_BREADTH_INCREMENTAL"):
        _jquants_breadth_worker(job_id)
    elif job_type == "JQUANTS_REQUEST_MATRIX":
        _jquants_request_matrix_worker(job_id)
    elif job_type == "GEMINI_PREFLIGHT":
        _gemini_preflight_worker(job_id)
    elif job_type == "RESEARCH_PIPELINE_PREFLIGHT":
        _research_pipeline_preflight_worker(job_id)
    elif job_type == "RESEARCH_BENCHMARK":
        _research_benchmark_job_worker(job_id)
    elif job_type == "RESEARCH_BENCHMARK_V2":
        _research_benchmark_v2_job_worker(job_id)
    elif job_type == "JOURNAL_REVERIFY":
        _journal_reverify_worker(job_id)
    else:
        _foundation_job_update(job_id, status="failed",
                               error_class="unknown_job_type")


def _foundation_closeout_status():
    """Evidence-derived v12 implementation/observation split; no mutable claim flag."""
    breadth = next((job for job in reversed(_FOUNDATION_JOBS.get("jobs", []))
                    if job.get("jobType") == "JQUANTS_BREADTH_BACKFILL"
                    and job.get("status") == "completed"
                    and (((job.get("result") or {}).get("stage") == "full_5y")
                         or ((job.get("result") or {}).get("providerProof")
                             or {}).get("finalizeOnly") is True)), None)
    breadth_result = (breadth or {}).get("result") or {}
    benchmark = _FORMAL_BENCHMARK_V2.get("holdoutResult") or {}
    receipts = [row for row in (_FORMAL_BENCHMARK_V2.get("remoteReceipts") or [])
                if row.get("readBackVerified") is True]
    requirements = {
        "productionFiveYearBreadthCompleted": bool(
            breadth and int(breadth_result.get("observationCount") or 0) > 0
            and breadth_result.get("contractScope")
            == argus_foundation_jobs.PRODUCTION_SCOPE
            and breadth_result.get("archiveBackfillStatus") == "deferred"
            and breadth_result.get("coreRequired") is False
            and breadth_result.get("executionMode") in (
                "independent_os_process",
                "independent_spawned_os_process",
            )
            and int(breadth_result.get("backendRestartCountDuringJob") or 0) == 0
            and int(breadth_result.get("checkpointPending") or 0) == 0
            and int(breadth_result.get("duplicateCount") or 0) == 0
            and not (breadth_result.get("permanentFailures") or [])
            and breadth_result.get("spotCheckPassed") is True
            and set((breadth_result.get("backtests") or {}).keys())
            == {"first_section", "prime", "all"}),
        "benchmarkV1ClosedInvalid": (
            (_FORMAL_BENCHMARK_V2.get("v1Closure") or {}).get("status")
            == "closed_invalid"),
        "benchmarkV2FormallyClosed": benchmark.get("status") in (
            "achieved", "not_achieved"),
        "benchmarkRemoteReadBackVerified": bool(receipts),
        "remoteJournalVerified": _REMOTE_CYCLE.get("readBackVerified") is True,
    }
    closed = all(requirements.values())
    soak_running = bool(_SOAK.get("startedAt") and _SOAK.get("state")
                        not in ("operationally_verified", "failed"))
    return {
        "foundationImplementationStatus": "CLOSED" if closed else "CLOSEOUT_RUNNING",
        "operationalObservationStatus": (
            "SOAK_RUNNING" if soak_running else
            "OPERATIONALLY_VERIFIED" if _SOAK.get("state") == "operationally_verified"
            else "SOAK_NOT_STARTED"),
        "requirements": requirements,
        "remainingImplementationTasks": 0 if closed else sum(
            value is not True for value in requirements.values()),
        "allowedV12Changes": ["critical_bug_fix", "security_fix",
                              "data_correction", "soak_observation"],
        "nextDevelopmentTheme": "V13 PRODUCT REDUCTION AND INTERFACE REBUILD",
    }


@app.route("/api/argus/foundation-jobs")
def api_argus_foundation_jobs():
    """Public-safe, read-only progress. Never exposes keys or provider rows."""
    status = argus_foundation_jobs.public_status(
        _FOUNDATION_JOBS, request.args.get("jobId"))
    status["foundationCloseout"] = _foundation_closeout_status()
    return jsonify(status)


def _breadth_resume_candidate(job_type, requested_stage):
    """Return only a failed checkpoint from the same production stage."""
    for candidate in reversed(_FOUNDATION_JOBS.get("jobs", [])):
        if candidate.get("jobType") != job_type or candidate.get(
                "status") not in ("failed", "cancelled"):
            continue
        if not (candidate.get("checkpoint") or {}).get("lastCommittedDate"):
            continue
        if job_type == "JQUANTS_BREADTH_BACKFILL":
            candidate_stage = str(
                (candidate.get("parameters") or {}).get("stage")
                or (candidate.get("result") or {}).get("stage")
                or (candidate.get("checkpoint") or {}).get("stage")
                or "full_5y")
            if candidate_stage != requested_stage:
                continue
        return candidate
    return None


@app.route("/api/argus/admin/foundation-jobs", methods=["POST"])
def api_argus_admin_foundation_jobs_start():
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    job_type = str(body.get("jobType") or "").upper()
    if job_type not in argus_foundation_jobs.JOB_TYPES:
        return jsonify({"ok": False, "error": "unknown_job_type"}), 400
    if body.get("confirm") is not True:
        return jsonify({"ok": False, "error": "explicit_confirmation_required"}), 400
    if job_type in ("RESEARCH_BENCHMARK", "RESEARCH_BENCHMARK_V2") and \
            body.get("triggerSource") != "manual":
        return jsonify({"ok": False, "error": "scheduled_execution_rejected"}), 400
    params = body.get("parameters") if isinstance(body.get("parameters"), dict) else {}
    if job_type == "JQUANTS_BREADTH_BACKFILL":
        params.setdefault("stage", "full_5y")
        try:
            argus_foundation_jobs.staged_production_range(
                params["stage"], latest_confirmed_date=str(
                    params.get("to") or
                    datetime.now(TZ_JST).strftime("%Y-%m-%d"))[:10])
        except (TypeError, ValueError):
            return jsonify({"ok": False,
                            "error": "invalid_breadth_stage"}), 400
    if job_type in ("JQUANTS_BREADTH_BACKFILL", "JQUANTS_BREADTH_INCREMENTAL") \
            and body.get("resume") is True and not params.get("from"):
        prior = _breadth_resume_candidate(job_type, str(
            params.get("stage") or "full_5y"))
        if prior:
            params["from"] = argus_foundation_jobs.next_day(
                prior["checkpoint"]["lastCommittedDate"])
            params["resumedFromJobId"] = prior.get("jobId")
    if job_type == "JQUANTS_BREADTH_INCREMENTAL" and not params.get("from"):
        periods = [str(x.get("periodEnd") or "") for x in
                   (_MARKET_LEDGER.get("observations") or [])
                   if str(x.get("seriesId") or "").startswith("breadth.all.")]
        params["from"] = (argus_foundation_jobs.next_day(max(periods))
                          if periods else
                          argus_foundation_jobs.production_calendar_start(
                              datetime.now(TZ_JST).strftime("%Y-%m-%d")))
    try:
        started = argus_foundation_jobs.start_job(
            _FOUNDATION_JOBS, job_type=job_type, now_iso=_ai_now_iso(),
            parameters=params)
    except ValueError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 409
    _FOUNDATION_JOBS.clear()
    _FOUNDATION_JOBS.update(started["state"])
    # Persist the small control-plane state before acknowledging. The full
    # 100+ MiB durable checkpoint is written once, after the child exits.
    _foundation_jobs_persist()
    job = started["job"]
    if started["created"]:
        threading.Thread(
            target=_memory_operation_run,
            args=("background", "foundation_job_dispatch",
                  _foundation_job_dispatch, job["jobId"]), daemon=True).start()
    return jsonify({"ok": True, "created": started["created"],
                    "job": argus_foundation_jobs.public_status(
                        _FOUNDATION_JOBS, job["jobId"])["jobs"][0]}), 202


@app.route("/api/argus/admin/foundation-jobs/<job_id>/cancel", methods=["POST"])
def api_argus_admin_foundation_jobs_cancel(job_id):
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    if body.get("confirm") is not True:
        return jsonify({"ok": False, "error": "explicit_confirmation_required"}), 400
    try:
        updated = argus_foundation_jobs.request_cancel(
            _FOUNDATION_JOBS, job_id, now_iso=_ai_now_iso())
    except ValueError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 404
    _FOUNDATION_JOBS.clear()
    _FOUNDATION_JOBS.update(updated)
    _foundation_jobs_persist()
    return jsonify({"ok": True, "jobId": job_id, "cancelRequested": True})


@app.route("/api/argus/admin/osint/benchmark-run", methods=["POST"])
def api_argus_admin_osint_benchmark_run():
    """Admin/cron専用: 固定ベンチスイートのGemini基準run実行(校正の加速)。
    公開ルートからは絶対に起動しない・重複実行は既存jobを返す・予算可視。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    skipped = _scheduled_ai_skip("gemini", "osint_benchmark")
    if skipped:
        return jsonify(skipped)
    try:
        body = request.get_json(silent=True) or {}
        if _OSINT_BENCH_STATE["running"]:
            return jsonify({"ok": True, "duplicate": True,
                            "noteJa": "ベンチ実行中 — 既存jobを再利用します。",
                            "budget": _OSINT_BENCH_BUDGET}), 202
        target = str(body.get("caseId") or "").strip()
        if target:
            case_ids = [target]
        else:
            # run数が最少のケースからround-robin(予算内)
            counts = {}
            for r in _OSINT_BASELINE_RUNS:
                counts[r.get("case")] = counts.get(r.get("case"), 0) + 1
            ordered = sorted(argus_osint_engine.GEMINI_BENCHMARK_SUITE,
                             key=lambda c: counts.get(c.get("id") or c.get("case"), 0))
            case_ids = [(c.get("id") or c.get("case"))
                        for c in ordered[:_OSINT_BENCH_BUDGET["maxCasesPerInvocation"]]]
        _OSINT_BENCH_STATE["running"] = True
        import threading
        threading.Thread(
            target=_memory_operation_run,
            args=("background", "osint_benchmark_worker",
                  _osint_benchmark_worker, case_ids), daemon=True).start()
        return jsonify({"ok": True, "started": case_ids,
                        "budget": _OSINT_BENCH_BUDGET,
                        "noteJa": "バックグラウンド実行(結果はDQのベンチ欄へ)。"}), 202
    except Exception as e:
        _OSINT_BENCH_STATE["running"] = False
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {str(e)[:120]}"}), 200


@app.route("/api/argus/admin/osint/canary-run", methods=["POST"])
def api_argus_admin_osint_canary_run():
    """Admin/cron: canary(既知トピックを取りこぼしていないか)を評価。"""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    try:
        pool = _osint_pool_items()
        titles = " ".join(str(it.get("titleJa") or it.get("title") or "") for it in pool).lower()

        def found(kws):
            return any(str(k).lower() in titles for k in kws)
        agent_found = {}
        for sym, inv in _OSINT_STORE.items():
            for r in inv.get("agentRuns") or []:
                if r.get("provider") not in ("gemini", "gpt") or r.get("status") != "ok":
                    continue
                blob = " ".join(str(c.get("titleJa") or "") for c in (r.get("claims") or [])).lower()
                for t in _OSINT_CANARY_TOPICS:
                    if any(str(k).lower() in blob for k in t["expectedKeywords"]):
                        agent_found.setdefault(t["topic"], {})[r["provider"]] = True
        res = argus_osint_engine.evaluate_canary(_OSINT_CANARY_TOPICS, found, agent_found)
        _OSINT_CANARY_LAST["data"] = res
        _OSINT_CANARY_LAST["at"] = _ai_now_iso()
        return jsonify({"ok": True, **res})
    except Exception as e:
        return jsonify({"ok": False, "error": f"{type(e).__name__}: {str(e)[:120]}"}), 200


@app.route("/api/argus/osint/verify-gaps", methods=["POST"])
def api_argus_osint_verify_gaps():
    """公開POST(決定論のみ): 保存済み調査のギャップ台帳を今すぐ再判定 —
    重複クラスタ/stale/無関係は即時解決できる(外部AI・URL fetchはしない)。
    URLライブ検証が必要な分はworker予算で消化される。"""
    body = request.get_json(silent=True) or {}
    sym = str(body.get("symbol") or "").strip().upper()
    inv = _OSINT_STORE.get(sym)
    if not inv:
        return jsonify({"ok": False, "error": "no_investigation",
                        "noteJa": "先に深掘りOSINTを実行してください。"}), 200
    meta = {"market": "JP" if sym[:1].isdigit() else "US",
            "mode": inv.get("mode") or "deep", "privacyMode": inv.get("privacyMode") or "redacted"}
    runs = inv.get("agentRuns") or []
    inv2 = _osint_build(sym, meta["market"], meta["mode"], meta["privacyMode"],
                        "owner_verify_gaps", runs, _ai_now_iso())
    # 標的クエリを学習語へ(次回の決定論探索が拾えるように)
    for g in (inv2.get("gapLedger") or []):
        if g["resolutionStatus"] == "still_unresolved_important":
            cur = _OSINT_TERM_OVERLAY.get(sym) or []
            _OSINT_TERM_OVERLAY[sym] = (cur + [t for t in g.get("followUpQueries") or []
                                               if t not in cur])[:12]
    return jsonify({"ok": True, "investigation": inv2,
                    "noteJa": "重複/古い/無関係の即時解決を実行。URL検証が必要な分は次のスカウト実行(worker予算)で消化されます。"})


@app.route("/api/argus/osint/url-verify", methods=["POST"])
def api_argus_osint_url_verify():
    """公開POST(enqueueのみ): オーナー指定URLの検証依頼。fetchはworker(admin経路)
    だけが行う — 公開経路からサーバーに任意URLを踏ませない(SSRF防止)。"""
    body = request.get_json(silent=True) or {}
    url = str(body.get("url") or "").strip()[:200]
    if not re.match(r"^https?://[\w.\-]+/", url + "/"):
        return jsonify({"error": "url_invalid"}), 400
    if url not in _OSINT_URL_QUEUE:
        _OSINT_URL_QUEUE.append(url)
        del _OSINT_URL_QUEUE[:-12]
    return jsonify({"ok": True, "queued": len(_OSINT_URL_QUEUE),
                    "noteJa": "検証キューに追加しました(次のスカウト実行で取得・公開経路からは取得しません)。"})


