    _journal("cost_policy_configured", "cost_policy", "central",
             {"mode": _COST_POLICY["mode"],
              "eventOptIn": _COST_POLICY["eventOptIn"]}, origin="admin")
    _osint_persist()
    return jsonify({"ok": True, **argus_cost_policy.public_status(
        _COST_POLICY, _ai_now_iso())})


