def _history_cache_known_at(cache, ttl):
    """Exact/conservative acquisition time for one provider-cache revision."""
    if not isinstance(cache, dict):
        return None
    exact = str(cache.get("acquiredAt") or "").strip()
    if exact:
        try:
            parsed = datetime.fromisoformat(exact.replace("Z", "+00:00"))
            if parsed.tzinfo is not None:
                return parsed.astimezone(pytz.utc).strftime(
                    "%Y-%m-%dT%H:%M:%S.%fZ")
        except (TypeError, ValueError):
            pass
    try:
        acquired = float(cache.get("expires")) - float(ttl)
        if acquired > 0:
            return datetime.fromtimestamp(acquired, pytz.utc).strftime(
                "%Y-%m-%dT%H:%M:%S.%fZ")
    except (TypeError, ValueError, OverflowError, OSError):
        pass
    return None


def _chart_rows_from_history(history, *, market, provider, known_at,
                             dataset_id):
    """Convert a provider-cache revision without backdating its knowledge.

    Historical bars imported in one response are first knowable to ARGUS when
    that response/cache revision was acquired.  Their market dates are not
    silently reused as publication timestamps.
    """
    if not isinstance(history, dict):
        return []
    dates = history.get("dates") or []
    opens = history.get("opens") or []
    highs = history.get("highs") or []
    lows = history.get("lows") or []
    closes = history.get("closes") or []
    volumes = history.get("volumes") or []
    adjusted = history.get("adjusted") or []
    revision = _canonical_truth_revision(known_at) if known_at else 0
    out = []
    for i, date in enumerate(dates):
        if i >= len(closes):
            break
        observed_at = _canonical_truth_iso(
            date, market, date_means_close=True)
        out.append({"date": date, "open": opens[i] if i < len(opens) else None,
                    "high": highs[i] if i < len(highs) else None,
                    "low": lows[i] if i < len(lows) else None,
                    "close": closes[i], "volume": volumes[i] if i < len(volumes) else None,
                    "adjusted": adjusted[i] if i < len(adjusted) else False,
                    "source": provider,
                    "sourceId": f"price:{provider}:{date}",
                    "datasetId": dataset_id,
                    "observedAt": observed_at,
                    "knownAt": known_at,
                    "revision": revision,
                    # Retained for legacy display only; PIT admission uses the
                    # exact knownAt above, never this date-only label.
                    "availableFrom": str(date)[:10]})
    return out


def _chart_weekly_rows(rows):
    """Aggregate daily OHLCV to ISO weeks without using future observations."""
    weekly = {}
    for row in sorted(rows, key=lambda x: str(x.get("date") or "")):
        try:
            dt = datetime.strptime(str(row.get("date"))[:10], "%Y-%m-%d")
        except (TypeError, ValueError):
            continue
        key = f"{dt.isocalendar().year}-W{dt.isocalendar().week:02d}"
        item = weekly.get(key)
        if item is None:
            item = dict(row)
            item["sourceId"] = f"price-week:{key}"
            weekly[key] = item
        else:
            item["date"] = row["date"]
            item["high"] = max(item.get("high") or row.get("high"), row.get("high") or item.get("high"))
            item["low"] = min(item.get("low") or row.get("low"), row.get("low") or item.get("low"))
            item["close"] = row.get("close")
            item["volume"] = (item.get("volume") or 0) + (row.get("volume") or 0)
            item["availableFrom"] = row.get("availableFrom") or row.get("date")
            item["knownAt"] = max(str(item.get("knownAt") or ""),
                                  str(row.get("knownAt") or "")) or None
            item["observedAt"] = row.get("observedAt")
            item["revision"] = max(int(item.get("revision") or 0),
                                   int(row.get("revision") or 0))
    return list(weekly.values())


def _chart_history(symbol, market):
    if market == "JP":
        history = _jq_price_history(symbol[:4])
        cache = _JQ_HISTORY_CACHE.get(symbol[:4])
        known_at = _history_cache_known_at(cache, _JQ_HISTORY_TTL)
        return _chart_rows_from_history(
            history, market="JP", provider="jquants", known_at=known_at,
            dataset_id=f"jquants:{symbol}:{known_at or 'unknown'}")
    history = _td_price_history(symbol)
    cache = _TD_HISTORY_CACHE.get(symbol)
    known_at = _history_cache_known_at(cache, _TD_HISTORY_TTL)
    return _chart_rows_from_history(
        history, market="US", provider="twelvedata", known_at=known_at,
        dataset_id=f"twelvedata:{symbol}:{known_at or 'unknown'}")


def _chart_history_cached(symbol, market):
    """Return only a fresh provider cache entry; scheduled ticks never fetch."""
    now = time.time()
    cache = (_JQ_HISTORY_CACHE.get(symbol[:4]) if market == "JP"
             else _TD_HISTORY_CACHE.get(symbol))
    if not isinstance(cache, dict) or now >= float(cache.get("expires") or 0):
        return []
    ttl = _JQ_HISTORY_TTL if market == "JP" else _TD_HISTORY_TTL
    provider = "jquants" if market == "JP" else "twelvedata"
    known_at = _history_cache_known_at(cache, ttl)
    return _chart_rows_from_history(
        cache.get("data"), market=market, provider=provider,
        known_at=known_at,
        dataset_id=f"{provider}:{symbol}:{known_at or 'unknown'}")


_JP_DAILY_SHORT_CACHE = {"rows": None, "expires": 0.0,
                         "status": "not_loaded", "errorClass": None}
_MARKET_PUBLIC_REPORT_CACHE = {}
_ASSET_CHART_SOURCE_CACHE = {}
_VERIFIED_VIEW_METHOD_VERSION = (
    f"{argus_verified_snapshot.METHOD_VERSION}:"
    f"{argus_chart_intelligence.METHOD_VERSION}:"
    f"{argus_market_replay.METHOD_VERSION}:"
    # v13.5.14: the forecast engine version participates so an engine change
    # (SHO conditioning) regenerates published snapshots instead of serving
    # the old calibration until the bars happen to change (「古いまま」根絶).
    f"{argus_today_intelligence.METHOD_VERSION}"
)


def _verified_market_snapshot(symbol, horizon):
    key = argus_verified_snapshot.snapshot_key(
        "market-chart", symbol, f"{int(horizon)}D")
    snapshot = (_VERIFIED_VIEW_SNAPSHOTS.get("current") or {}).get(key)
    ok, _ = argus_verified_snapshot.verify_snapshot(
        snapshot, expected_kind="market-chart",
        expected_instrument=symbol, expected_horizon=f"{int(horizon)}D",
        expected_method_version=_VERIFIED_VIEW_METHOD_VERSION)
    return copy.deepcopy(snapshot) if ok else None


def _publish_verified_market_views(
        report, symbol, now_iso, *, release_binding=None):
    """Publish all horizon pointers only after each complete report validates."""
    normalized = argus_market_intelligence.normalize_public_names(report)
    replay = normalized.get("marketReplay") or {}
    contexts = replay.get("contexts") or {}
    published = []
    for horizon in argus_market_replay.HORIZONS:
        context = contexts.get(str(horizon))
        if not isinstance(context, dict):
            raise ValueError(f"replay_context_missing_{horizon}")
        status = str(normalized.get("status") or "partial")
        indicator_status = str(
            (normalized.get("indicators") or {}).get("status") or "missing")
        quality = ("live" if status in {"complete", "live", "ok"}
                   and indicator_status not in {"missing", "error", "mock"}
                   else "partial")
        candidate = argus_verified_snapshot.build_snapshot(
            payload=normalized, kind="market-chart", instrument=symbol,
            horizon=f"{horizon}D",
            dataset_hash=str(context.get("datasetHash") or ""),
            method_version=_VERIFIED_VIEW_METHOD_VERSION,
            as_of=str(context.get("asOf") or normalized.get("asOf") or
                      normalized.get("periodEnd") or ""),
            generated_at=now_iso, quality=quality,
            source_status={
                "chart": status,
                "indicators": indicator_status,
                "replay": str(replay.get("cacheStatus") or "updated"),
                "durableReadBack": str(
                    _VERIFIED_VIEW_SNAPSHOT_REMOTE.get(
                        "verificationStatus") or "not_verified"),
            }, release_binding=release_binding)
        next_store, publication = argus_verified_snapshot.publish_atomic(
            _VERIFIED_VIEW_SNAPSHOTS, candidate, now_iso=now_iso)
        if publication not in {"published", "unchanged"}:
            raise ValueError(f"verified_snapshot_{publication}")
        _VERIFIED_VIEW_SNAPSHOTS.clear()
        _VERIFIED_VIEW_SNAPSHOTS.update(next_store)
        published.append({
            "horizon": horizon, "snapshotId": candidate["snapshotId"],
            "publication": publication,
        })
    _MARKET_PUBLIC_REPORT_CACHE[
        ("market", symbol, "daily")] = copy.deepcopy(normalized)
    return published


def _precompute_verified_market_view(
        symbol, market, *, market_scope=False, release_binding=None):
    """Natural-tick producer; unchanged verified datasets never re-run analysis."""
    daily_rows = _chart_history(symbol, market)
    dataset_hash = argus_market_replay.dataset_hash(daily_rows)
    if not daily_rows or not dataset_hash:
        raise ValueError("price_history_unavailable")
    needs = list(argus_market_replay.HORIZONS) if release_binding else [
        horizon for horizon in argus_market_replay.HORIZONS
        if argus_verified_snapshot.needs_generation(
            _VERIFIED_VIEW_SNAPSHOTS, kind="market-chart",
            instrument=symbol, horizon=f"{horizon}D",
            dataset_hash=dataset_hash,
            method_version=_VERIFIED_VIEW_METHOD_VERSION)
    ]
    if not needs:
        existing = _verified_market_snapshot(symbol, 5)
        if not existing:
            raise ValueError("verified_snapshot_pointer_missing")
        _MARKET_PUBLIC_REPORT_CACHE[
            ("market", symbol, "daily")] = copy.deepcopy(existing["payload"])
        return existing["payload"], {
            "status": "unchanged", "generated": False,
            "datasetHash": dataset_hash, "horizons": [],
        }

    flight_key = (
        f"market-chart:{symbol}:{dataset_hash}:"
        f"{_VERIFIED_VIEW_METHOD_VERSION}"
    )
    if release_binding:
        flight_key += (
            f":release:{release_binding.get('expectedBuildSha')}:"
            f"{release_binding.get('producerTriggerId')}"
        )

    def _produce():
        report = _chart_public_report(
            symbol, market, "daily", market_scope=market_scope,
            cached_only=False, precompute_replay=True,
            daily_rows_override=daily_rows)
        published = _publish_verified_market_views(
            report, symbol, _ai_now_iso(), release_binding=release_binding)
        return report, published

    report, published = _VERIFIED_VIEW_SINGLEFLIGHT.run(flight_key, _produce)
    return report, {
        "status": "published", "generated": True,
        "datasetHash": dataset_hash, "horizons": published,
    }


def _release_seed_verified_market_views(body):
    """Produce and durably bind the exact release-required 4x3 matrix."""
    expected_sha = str(body.get("expectedBuildSha") or "").strip().lower()
    current_sha = str(_backend_exact_sha() or "").strip().lower()
    trigger_id = str(body.get("runId") or "").strip()[:120]
    if not re.fullmatch(r"[0-9a-f]{40}", expected_sha):
        return jsonify({"ok": False, "status": "failed",
                        "error": "release_snapshot_expected_sha_invalid"}), 400
    if expected_sha != current_sha:
        return jsonify({"ok": False, "status": "failed",
                        "error": "release_snapshot_build_mismatch",
                        "expectedBuildSha": expected_sha,
                        "actualBuildSha": current_sha}), 409
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,120}", trigger_id):
        return jsonify({"ok": False, "status": "failed",
                        "error": "release_snapshot_trigger_id_invalid"}), 400
    triggered_at = _ai_now_iso()
    release_binding = {
        "expectedBuildSha": expected_sha,
        "producerTriggerId": trigger_id,
        "triggeredAt": triggered_at,
    }
    phase_specs = (
        ("1321", "JP", True),
        ("1306", "JP", False),
        ("SPY", "US", False),
        ("QQQ", "US", False),
    )
    observations = []
    try:
        with _DURABLE_CHECKPOINT_LOCK:
            duplicate_count = sum(
                1
                for symbol, _, _ in phase_specs
                for horizon in argus_market_replay.HORIZONS
                if ((_verified_market_snapshot(symbol, horizon) or {}).get(
                    "releaseBinding") or {}).get(
                        "producerTriggerId") == trigger_id
            )
            if duplicate_count:
                return jsonify({
                    "ok": False,
                    "status": "duplicate",
                    "error": "release_snapshot_trigger_duplicate",
                    "producerTriggerId": trigger_id,
                    "snapshotExpected": 12,
                    "snapshotReady": duplicate_count,
                }), 409
            for symbol, market, market_scope in phase_specs:
                _, publication = _precompute_verified_market_view(
                    symbol, market, market_scope=market_scope,
                    release_binding=release_binding)
                published = publication.get("horizons") or []
                if len(published) != len(argus_market_replay.HORIZONS):
                    raise ValueError(
                        f"release_snapshot_publication_incomplete_{symbol}")
                for horizon in argus_market_replay.HORIZONS:
                    snapshot = _verified_market_snapshot(symbol, horizon)
                    if not snapshot or snapshot.get("releaseBinding") != \
                            release_binding:
                        raise ValueError(
                            f"release_snapshot_readback_invalid_{symbol}_{horizon}D")
                    observations.append({
                        "identity": argus_verified_snapshot.snapshot_key(
                            "market-chart", symbol, f"{horizon}D"),
                        "market": market,
                        "instrument": symbol,
                        "horizon": f"{horizon}D",
                        "snapshotId": snapshot.get("snapshotId"),
                        "generatedAt": snapshot.get("generatedAt"),
                        "verificationStatus": snapshot.get(
                            "verificationStatus"),
                        "releaseBinding": snapshot.get("releaseBinding"),
                    })
            checkpoint = _osint_persist()
            if checkpoint.get("verified") is not True or \
                    checkpoint.get("readBackVerified") is not True:
                raise ValueError("release_snapshot_persistence_unverified")
    except Exception as exc:
        return jsonify({
            "ok": False,
            "status": "failed",
            "error": "release_snapshot_seed_failed",
            "errorClass": type(exc).__name__,
            # Bounded detail so a failed seed names itself in the producer
            # evidence instead of hiding behind the class name alone.
            "errorDetail": str(exc)[:200],
            "producerTriggerId": trigger_id,
            "snapshotExpected": 12,
            "snapshotReady": len(observations),
        }), 503
    return jsonify({
        "ok": True,
        "status": "completed",
        "schemaVersion": "argus-release-snapshot-seed-v1",
        "producer": "scanner._precompute_verified_market_view",
        "producerTriggerId": trigger_id,
        "expectedBuildSha": expected_sha,
        "triggeredAt": triggered_at,
        "completedAt": _ai_now_iso(),
        "snapshotExpected": 12,
        "snapshotReady": len(observations),
        "snapshots": observations,
        "persistence": {
            "verified": checkpoint.get("verified") is True,
            "readBackVerified": checkpoint.get("readBackVerified") is True,
        },
        "recoveryAuthorityChanged": False,
    })


_ASSET_CHART_METHOD_VERSION = (
    f"{argus_chart_intelligence.METHOD_VERSION}:"
    f"{argus_market_intelligence.METHOD_VERSION}"
)


def _asset_chart_targets():
    """Public-safe bounded universe; owner holdings never leave the device."""
    targets = [("5803", "JP")]
    targets.extend(
        (str(item["symbol"]).upper(), "JP")
        for item in _JP_WATCHLIST
        if str(item.get("symbol") or "").upper() != "5803"
    )
    targets.extend(
        (str(item["symbol"]).upper(), "US")
        for item in _US_WATCHLIST
    )
    return targets


def _asset_chart_provider_history(symbol, market):
    """One-instrument bounded provider seed; never called from a public GET."""
    now = time.time()
    key = f"{market}:{symbol}"
    cached = _ASSET_CHART_SOURCE_CACHE.get(key)
    if isinstance(cached, dict) and now < float(cached.get("expires") or 0):
        return list(cached.get("rows") or []), {
            "source": "asset_chart_source_cache",
            "status": cached.get("status"),
            "errorClass": cached.get("errorClass"),
        }
    try:
        if market == "JP":
            if not _JQUANTS_API_KEY:
                raise RuntimeError("jquants_not_configured")
            start = (
                datetime.now(TZ_JST) - timedelta(days=800)
            ).strftime("%Y-%m-%d")
            raw = _jquants_paginated(
                "/equities/bars/daily",
                {"code": symbol[:4], "from": start},
                max_pages=2,
                request_timeout=8,
            )

            def _number(row, names):
                for name in names:
                    value = row.get(name)
                    if value not in (None, ""):
                        try:
                            return float(value)
                        except (TypeError, ValueError):
                            continue
                return None

            rows = []
            for item in raw:
                close = _number(item, ("AdjC", "C", "Close"))
                date = str(item.get("Date") or "")[:10]
                if close is None or not date:
                    continue
                rows.append({
                    "date": date, "availableFrom": date,
                    "open": _number(item, ("AdjO", "O", "Open")),
                    "high": _number(item, ("AdjH", "H", "High")),
                    "low": _number(item, ("AdjL", "L", "Low")),
                    "close": close,
                    "volume": int(_number(item, ("Vo", "Volume")) or 0),
                    "adjusted": item.get("AdjC") is not None,
                    "sourceId": f"price:{market}:{symbol}:{date}",
                })
        else:
            if not _TWELVEDATA_API_KEY:
                raise RuntimeError("twelvedata_not_configured")
            response = requests.get(
                _TWELVEDATA_TS,
                params={
                    "symbol": symbol,
                    "interval": "1day",
                    "outputsize": 600,
                    "apikey": _TWELVEDATA_API_KEY,
                },
                timeout=10,
            )
            response.raise_for_status()
            body = response.json()
            if not isinstance(body, dict) or \
                    str(body.get("status") or "").lower() == "error":
                raise RuntimeError("twelvedata_error_response")
            raw = body.get("values")
            if not isinstance(raw, list):
                raise RuntimeError("twelvedata_invalid_schema")

            def _number(row, name):
                try:
                    value = row.get(name)
                    return float(value) if value not in (None, "") else None
                except (TypeError, ValueError):
                    return None

            rows = []
            for item in raw:
                close = _number(item, "close")
                date = str(item.get("datetime") or "")[:10]
                if close is None or not date:
                    continue
                rows.append({
                    "date": date, "availableFrom": date,
                    "open": _number(item, "open"),
                    "high": _number(item, "high"),
                    "low": _number(item, "low"),
                    "close": close,
                    "volume": int(_number(item, "volume") or 0),
                    "adjusted": False,
                    "sourceId": f"price:{market}:{symbol}:{date}",
                })
        acquired_at = _ai_now_iso()
        provider = "jquants" if market == "JP" else "twelvedata"
        revision = _canonical_truth_revision(acquired_at)
        dataset_id = f"{provider}:{symbol}:{acquired_at}"
        for row in rows:
            row.update({
                "source": provider,
                "sourceId": f"price:{provider}:{symbol}:{row.get('date')}",
                "datasetId": dataset_id,
                "observedAt": _canonical_truth_iso(
                    row.get("date"), market, date_means_close=True),
                "knownAt": acquired_at,
                "revision": revision,
            })
        rows.sort(key=lambda row: str(row.get("date") or ""))
        if len(rows) < 20:
            raise RuntimeError("asset_chart_history_insufficient")
        _ASSET_CHART_SOURCE_CACHE[key] = {
            "rows": rows,
            "expires": now + 6 * 3600,
            "status": "live",
            "errorClass": None,
        }
        return list(rows), {
            "source": "bounded_provider_seed",
            "status": "live",
            "errorClass": None,
        }
    except Exception as exc:
        _ASSET_CHART_SOURCE_CACHE[key] = {
            "rows": [],
            "expires": now + (600 if market == "JP" else 150),
            "status": "degraded",
            "errorClass": type(exc).__name__,
        }
        return [], {
            "source": "bounded_provider_seed",
            "status": "degraded",
            "errorClass": type(exc).__name__,
        }


def _precompute_asset_chart_tick(deadline_monotonic=None):
    """Publish one changed public-watchlist instrument from warm provider data.

    Existing admin-collector cache is preferred.  If it is absent and at least
    20 seconds remain, one tightly bounded provider seed is allowed.  Work is
    still limited to one symbol, single-flight, and daily/weekly payloads derive
    from the same daily dataset.
    """
    targets = _asset_chart_targets()
    if not targets:
        return {"status": "expected_skip", "reason": "empty_target_universe",
                "generated": False, "targetCount": 0}
    cursor = int(_ASSET_CHART_REPORTS.get("cursor") or 0) % len(targets)
    symbol, market = targets[cursor]
    _ASSET_CHART_REPORTS["cursor"] = (cursor + 1) % len(targets)
    daily_rows = _memory_operation_run(
        "provider", "asset_chart.provider_cache_history",
        _chart_history_cached, symbol, market)
    source = {"source": "shared_provider_cache",
              "status": "live" if daily_rows else "missing",
              "errorClass": None}
    provider_attempted = False
    if not daily_rows:
        remaining = (
            float(deadline_monotonic) - time.monotonic()
            if deadline_monotonic is not None else 60.0
        )
        if remaining >= 20:
            provider_attempted = True
            daily_rows, source = _memory_operation_run(
                "provider", "asset_chart.provider_history",
                _asset_chart_provider_history, symbol, market)
    if not daily_rows:
        return {
            "status": "expected_skip",
            "reason": (
                "insufficient_tick_time"
                if not provider_attempted
                else "provider_history_unavailable"
            ),
            "generated": False,
            "instrument": symbol,
            "market": market,
            "source": source,
            "cursor": _ASSET_CHART_REPORTS["cursor"],
            "targetCount": len(targets),
        }
    dataset_hash = _memory_operation_run(
        "internal", "asset_chart.dataset_hash",
        argus_market_replay.dataset_hash, daily_rows)
    existing = [
        argus_asset_chart_cache.current(
            _ASSET_CHART_REPORTS, market, symbol, timeframe)
        for timeframe in ("daily", "weekly")
    ]
    if all(
            record
            and record.get("datasetHash") == dataset_hash
            and record.get("methodVersion") == _ASSET_CHART_METHOD_VERSION
            for record in existing):
        return {
            "status": "unchanged",
            "generated": False,
            "instrument": symbol,
            "market": market,
            "datasetHash": dataset_hash,
            "methodVersion": _ASSET_CHART_METHOD_VERSION,
            "cursor": _ASSET_CHART_REPORTS["cursor"],
            "targetCount": len(targets),
            "stateHash": _memory_operation_run(
                "internal", "asset_chart.final_state_hash",
                argus_asset_chart_cache.state_hash,
                _ASSET_CHART_REPORTS),
            "source": source,
        }
    flight_key = (
        f"asset-chart:{market}:{symbol}:{dataset_hash}:"
        f"{_ASSET_CHART_METHOD_VERSION}"
    )

    def _produce():
        publications = []
        reports = []
        candidate_store = _memory_operation_run(
            "internal", "asset_chart.normalize",
            argus_asset_chart_cache.normalize_store,
            _ASSET_CHART_REPORTS)
        for timeframe in ("daily", "weekly"):
            report = _memory_operation_run(
                "internal", f"asset_chart.report.{timeframe}",
                _chart_public_report,
                symbol, market, timeframe, market_scope=False,
                cached_only=False, precompute_replay=False,
                daily_rows_override=daily_rows)
            next_store, publication = _memory_operation_run(
                "internal", f"asset_chart.publish.{timeframe}",
                argus_asset_chart_cache.publish, candidate_store,
                market=market, symbol=symbol, timeframe=timeframe,
                dataset_hash=dataset_hash,
                method_version=_ASSET_CHART_METHOD_VERSION,
                report=report, published_at=_ai_now_iso())
            if publication not in {"published", "unchanged"}:
                raise ValueError(
                    f"asset_chart_publication_{publication}")
            candidate_store = next_store
            publications.append({
                "timeframe": timeframe, "status": publication,
                "reportId": report.get("reportId"),
            })
            reports.append(report)
        _ASSET_CHART_REPORTS.clear()
        _ASSET_CHART_REPORTS.update(candidate_store)
        return reports, publications

    _, publications = _memory_operation_run(
        "internal", "asset_chart.singleflight_produce",
        _ASSET_CHART_SINGLEFLIGHT.run, flight_key, _produce)
    generated = any(
        item["status"] == "published" for item in publications)
    if generated:
        state_hash = _memory_operation_run(
            "internal", "asset_chart.updated_state_hash",
            argus_asset_chart_cache.state_hash, _ASSET_CHART_REPORTS)
        _journal(
            "asset_chart_cache_updated", "asset_chart_cache",
            f"{market}:{symbol}",
            {"stateHash": state_hash, "datasetHash": dataset_hash,
             "methodVersion": _ASSET_CHART_METHOD_VERSION,
             "timeframes": ["daily", "weekly"]},
        )
    return {
        "status": "published" if generated else "unchanged",
        "generated": generated,
        "instrument": symbol,
        "market": market,
        "datasetHash": dataset_hash,
        "methodVersion": _ASSET_CHART_METHOD_VERSION,
        "publications": publications,
        "cursor": _ASSET_CHART_REPORTS["cursor"],
        "targetCount": len(targets),
        "source": source,
        "stateHash": _memory_operation_run(
            "internal", "asset_chart.final_state_hash",
            argus_asset_chart_cache.state_hash, _ASSET_CHART_REPORTS),
    }


def _jp_daily_short_history(cached_only=False):
    """Five-year TSE aggregate daily short-selling turnover (S33=0050).

    The Standard-plan series is distinct from weekly credit balances and from
    threshold-reported institutional short positions.  A chart GET may reuse a
    six-hour cache; scheduled cached-only ticks never make a provider request.
    """
    now = time.time()
    if isinstance(_JP_DAILY_SHORT_CACHE.get("rows"), list) and \
            now < float(_JP_DAILY_SHORT_CACHE.get("expires") or 0):
        return list(_JP_DAILY_SHORT_CACHE["rows"])
    durable_rows = list(_TODAY_INTELLIGENCE.get("shortSellingHistory") or [])
    if cached_only or not _JQUANTS_API_KEY:
        return durable_rows
    today = datetime.now(TZ_JST).date()
    try:
        start = today.replace(year=today.year - 5)
    except ValueError:
        start = today.replace(year=today.year - 5, day=28)
    try:
        raw = _jquants_paginated(
            "/markets/short-ratio",
            {"s33": "0050", "from": start.isoformat(), "to": today.isoformat()},
            max_pages=10)
        observed = _ai_now_iso()
        rows = argus_today_intelligence.normalize_short_history([
            {**item, "source": "J-Quants /markets/short-ratio S33=0050",
             "availableFrom": str(item.get("Date") or "")[:10],
             "observedAt": _canonical_truth_iso(
                 str(item.get("Date") or "")[:10], "JP",
                 date_means_close=True),
             "knownAt": observed,
             "sourceId": (f"jquants:short-ratio:"
                          f"{str(item.get('Date') or '')[:10]}"),
             "datasetId": f"jquants:short-ratio:{observed}",
             "revision": _canonical_truth_revision(observed)}
            for item in raw if isinstance(item, dict)
        ])
        if rows:
            _JP_DAILY_SHORT_CACHE.update({"rows": rows, "expires": now + 18 * 3600,
                                          "status": "live", "errorClass": None})
            return rows
        _JP_DAILY_SHORT_CACHE.update({"rows": durable_rows,
                                      "expires": now + 30 * 60,
                                      "status": "missing",
                                      "errorClass": "empty_provider_response"})
    except Exception as exc:
        _JP_DAILY_SHORT_CACHE.update({"rows": durable_rows,
                                      "expires": now + 30 * 60,
                                      "status": "degraded",
                                      "errorClass": type(exc).__name__})
    return durable_rows


def _breadth_lag_trading_days():
    """JP breadth freshness vs the latest completed JP session, in trading days.

    Measured from the Market Ledger's newest breadth periodEnd against
    argus_market_clock's latest completed session. None whenever either side is
    unprovable — the probability-truth gate reads None as unverified, never as
    fresh (owner spec 2026-08-22 §2: UNKNOWN is not FALSE)."""
    try:
        by_series = argus_market_ledger.latest_by_series(
            _MARKET_LEDGER, _ai_now_iso())
        # Only the count series the calibration display actually stands on;
        # freshness is the OLDEST of them, so one fresh derived proxy (e.g.
        # breadth.topixProxyClose) can never mask stale advancers/decliners.
        core_newest = []
        for series_id, rows in (by_series or {}).items():
            name = str(series_id)
            if not (name.endswith(".advancers") or name.endswith(".decliners")
                    or name == "breadth.advancers"
                    or name == "breadth.decliners"):
                continue
            if rows:
                period_end = str(rows[-1].get("periodEnd") or "")[:10]
                if len(period_end) == 10:
                    core_newest.append(period_end)
        newest = min(core_newest) if core_newest else None
        if not newest:
            return None
        try:
            target = argus_market_clock.latest_completed_session_date(
                argus_market_clock.JP_EQUITY, datetime.now(timezone.utc))
        except argus_market_clock.CalendarUnavailableError:
            return None
        cursor = datetime.strptime(newest, "%Y-%m-%d").date()
        if cursor >= target:
            return 0
        lag = 0
        while cursor < target and lag <= 30:
            cursor += timedelta(days=1)
            if argus_market_clock.is_trading_day(
                    argus_market_clock.JP_EQUITY, cursor):
                lag += 1
        return lag
    except Exception:
        return None


def _chart_public_report(symbol, market, timeframe="daily", market_scope=False,
                         cached_only=False, precompute_replay=False,
                         daily_rows_override=None):
    now_iso = _ai_now_iso()
    history = _chart_history_cached if cached_only else _chart_history
    daily_rows = (list(daily_rows_override)
                  if isinstance(daily_rows_override, list)
                  else history(symbol, market))
    reference_history = (
        _chart_history_cached
        if isinstance(daily_rows_override, list)
        else history
    )
    if cached_only and not daily_rows:
        return {
            "reportId": None,
            "status": "expected_skip",
            "automaticAiCalls": 0,
            "costPolicyMode": _COST_POLICY.get("mode"),
            "stateUpdate": {
                "status": "expected_skip",
                "reason": "price_cache_unavailable",
            },
            "persistence": {
                "stateHash": argus_chart_intelligence.state_hash(
                    _CHART_INTELLIGENCE),
                "todayIntelligenceStateHash": argus_today_intelligence.state_hash(
                    _TODAY_INTELLIGENCE),
                "marketReplayStateHash": argus_market_replay.state_hash(
                    _MARKET_REPLAY),
                **_CHART_INTELLIGENCE_REMOTE,
            },
        }
    rows = daily_rows
    if timeframe == "weekly":
        rows = _chart_weekly_rows(rows)
    ledger = argus_market_ledger.public_view(_MARKET_LEDGER, now_iso)
    _effective = {x.get("id"): x for x in
                  argus_market_ledger.effective_observations(_MARKET_LEDGER, now_iso)}
    ledger["valuationHistory"] = []
    for _eps in argus_market_ledger.derived_history(
            _MARKET_LEDGER, now_iso).get("valuation.eps", []):
        _inputs = [_effective.get(_oid) for _oid in _eps.get("inputObservationIds", [])]
        _available = max([str(x.get("availableFrom") or "") for x in _inputs if x]
                         or [str(_eps.get("asOf") or "")])
        ledger["valuationHistory"].append({**_eps, "availableFrom": _available})
    try:
        event_doc = get_events_snapshot()
        events = event_doc.get("events") if isinstance(event_doc, dict) else []
    except Exception:
        events = []
    # Reuse only the already-assembled catalyst cache: opening a chart must not
    # trigger Finnhub/J-Quants/SEC work.  Earnings and disclosure dates become
    # markers; a beat/miss classification is used only when actual + estimate
    # were already present in the cache.
    _catalyst_snapshot = _CAT_CACHE.get("data") if isinstance(_CAT_CACHE, dict) else None
    _catalyst_item = next((x for x in ((_catalyst_snapshot or {}).get("items") or [])
                             if str(x.get("symbol") or "").upper() == symbol.upper()), None)
    if _catalyst_item:
        events = list(events or [])
        _earnings = _catalyst_item.get("earnings") or {}
        _earnings_date = str(_earnings.get("date") or "")[:10]
        if _earnings_date:
            _actual, _estimate = _earnings.get("epsActual"), _earnings.get("epsEstimate")
            _classification = "earnings"
            try:
                if _actual is not None and _estimate is not None:
                    _classification = ("earnings_beat" if float(_actual) >= float(_estimate)
                                       else "earnings_miss")
            except (TypeError, ValueError):
                _classification = "earnings"
            events.append({"id": f"earnings:{symbol}:{_earnings_date}",
                           "date": _earnings_date, "availableFrom": _earnings_date,
                           "knownAt": now_iso,
                           "titleJa": f"{symbol} 決算", "kind": "earnings",
                           "classification": _classification})
        for _kind, _items in (("filing", _catalyst_item.get("filings") or []),
                              ("disclosure", _catalyst_item.get("disclosures") or [])):
            for _item in _items[:5]:
                _date = str(_item.get("filingDate") or _item.get("date") or "")[:10]
                if _date:
                    events.append({"id": f"{_kind}:{symbol}:{_date}", "date": _date,
                                   "availableFrom": _date,
                                   "knownAt": now_iso,
                                   "titleJa": str(_item.get("title") or _item.get("form") or
                                                  f"{symbol} 公式開示")[:100],
                                   "kind": _kind, "classification": "unconfirmed"})
    sector_rows = (reference_history("1306", "JP")
                   if market == "JP" and symbol != "1306" else [])
    report = argus_chart_intelligence.analyze(
        symbol, market, rows, now_iso=now_iso, market_ledger=ledger,
        events=events, sector_rows=sector_rows)
    # Canonical instrument metadata comes from the existing calibrated universe.
    # The UI must never relabel an ETF proxy as the cash index it follows.
    report["displayNameJa"] = argus_calibration.DISPLAY_NAMES.get(
        str(symbol).upper(), str(symbol).upper())
    report["eventMarkers"] = [{
        "id": str(e.get("eventId") or e.get("id") or e.get("eventCode") or ""),
        "date": str(e.get("availableFrom") or e.get("date") or e.get("eventDate") or "")[:10],
        "labelJa": str(e.get("titleJa") or e.get("title") or e.get("eventCode") or "重要イベント")[:100],
        "kind": str(e.get("eventCode") or e.get("kind") or "event")[:40],
    } for e in (events or []) if str(e.get("availableFrom") or e.get("date") or e.get("eventDate") or "")[:10]]
    report["timeframe"] = timeframe
    report["reportId"] = f"{report['reportId']}-{timeframe}"
    report["automaticAiCalls"] = 0
    report["costPolicyMode"] = _COST_POLICY.get("mode")
    _comparison_symbol = ("1306" if market == "JP" and symbol != "1306" else
                          "1321" if market == "JP" else
                          "QQQ" if symbol != "QQQ" else "SPY")
    _comparison_rows = reference_history(_comparison_symbol, market)
    # Public chart GETs only consume a verified cache/durable snapshot.  Provider
    # refresh is owned by the natural scheduled tick below, never UI interaction.
    _short_rows = _jp_daily_short_history(cached_only=True) if market == "JP" else []
    # SHO conditioning context (owner spec 2026-08-22): the ten-year corpus is
    # joined per-day to the credit / VIX / relative-strength state SHO reads.
    # Every source is PIT-stamped; assembly failure degrades to the pure
    # price-action engine rather than blocking the chart.
    try:
        _sho_context = {
            "creditRows": (_jpx_credit_rows_effective()
                           if market == "JP" else []),
            "vixRows": _fred_vix_history_dated(),
            "usRows": (reference_history("SPY", "US")
                       if str(symbol).upper() != "SPY" else []),
            # v13.5.36: misconfiguration is REPORTED, never silently identical
            # to an honest data gap (the vix dimension would otherwise just
            # vanish from currentFeatureKeys with no visible cause).
            "sourceIssues": ([] if _FRED_API_KEY
                             else ["vix_provider_key_missing"]),
        }
    except Exception:
        _sho_context = None
    _today_intel = argus_today_intelligence.analyze(
        daily_rows, symbol=symbol, market=market,
        short_history=_short_rows, comparison_rows=_comparison_rows,
        sho_context=_sho_context,
        as_of=now_iso)
    # The pure engine cannot measure breadth freshness (no ledger access), so
    # the serving layer injects the measured JP lag here. None stays None —
    # the display gate reads it as unverified, never as fresh.
    if market == "JP":
        _breadth_lag = _breadth_lag_trading_days()
        if _breadth_lag is not None:
            for _cal_h in ((_today_intel.get("calibration") or {})
                           .get("horizons") or {}).values():
                _cal_ev = _cal_h.get("probabilityTruthEvidence")
                if isinstance(_cal_ev, dict):
                    _cal_ev["breadthLagTradingDays"] = _breadth_lag
    report["todayIntelligence"] = _today_intel
    # Every Replay instrument keeps an isolated relative-price series.  The JP
    # primary view later adds the full cross-market matrix.
    report["relativeStrength"] = {
        f"{symbol.lower()}_{_comparison_symbol.lower()}":
            argus_chart_intelligence.relative_strength(
                f"{symbol.lower()}_{_comparison_symbol.lower()}",
                daily_rows, _comparison_rows, classification="derived")
    }
    _instrument_id = f"{market}:{symbol}:ETF"
    _replay_dataset_hash = argus_market_replay.dataset_hash(daily_rows)
    _existing_replay = argus_market_replay.latest_contexts(
        _MARKET_REPLAY, _instrument_id)
    _replay_cache_hit = bool(daily_rows) and all(
        str(_horizon) in _existing_replay
        and _existing_replay[str(_horizon)].get("methodVersion")
        == argus_market_replay.METHOD_VERSION
        and _existing_replay[str(_horizon)].get("datasetHash")
        == _replay_dataset_hash
        for _horizon in argus_market_replay.HORIZONS
    )
    if precompute_replay and timeframe == "daily" and not _replay_cache_hit:
        _replay_ledger = {**ledger, "table": list(ledger.get("table") or [])}
        if market == "JP" and _short_rows:
            _replay_ledger["table"].append({
                "seriesId": "daily_short.ratio",
                "labelJa": "日次空売り比率", "unit": "percent",
                "latestValue": _short_rows[-1].get("totalShortRatio"),
                "source": _short_rows[-1].get("source"),
                "history": [{
                    "periodEnd": row.get("date"),
                    "availableFrom": row.get("availableFrom") or row.get("date"),
                    "knownAt": row.get("knownAt") or now_iso,
                    "observedAt": row.get("observedAt") or row.get("date"),
                    "revision": int(row.get("revision") or 0),
                    "value": row.get("totalShortRatio"), "unit": "percent",
                } for row in _short_rows],
            })
        for _relative_id, _relative_row in (report.get("relativeStrength") or {}).items():
            _replay_ledger["table"].append({
                "seriesId": f"relative.{_relative_id}",
                "labelJa": _relative_id, "unit": "ratio",
                "latestValue": _relative_row.get("latestValue"),
                "history": [{
                    "periodEnd": point.get("date"),
                    "availableFrom": point.get("date"),
                    # Relative history is assembled from the current provider
                    # revision. It is first known now, not on each old bar date.
                    "knownAt": now_iso,
                    "observedAt": point.get("date"),
                    "revision": 0,
                    "value": point.get("value"), "unit": "ratio",
                } for point in (_relative_row.get("history") or [])],
            })
        try:
            _replay_chart_input = argus_market_replay.seal_auxiliary_input(
                report, kind="chart_report", known_at=now_iso)
        except (TypeError, ValueError, OverflowError):
            _replay_chart_input = {}
        try:
            _replay_calibration_input = \
                argus_market_replay.seal_auxiliary_input(
                    _today_intel.get("calibration") or {},
                    kind="calibration", known_at=now_iso)
        except (TypeError, ValueError, OverflowError):
            _replay_calibration_input = {}
        for _replay_horizon in argus_market_replay.HORIZONS:
            _replay_context = argus_market_replay.build_context(
                daily_rows, symbol=symbol, market=market,
                horizon=_replay_horizon, chart_report=_replay_chart_input,
                ledger=_replay_ledger,
                calibration=_replay_calibration_input,
                now_iso=now_iso)
            _replay_merged = argus_market_replay.merge_context(
                _MARKET_REPLAY, _replay_context, now_iso)
            _MARKET_REPLAY.clear()
            _MARKET_REPLAY.update(_replay_merged)
    report["marketReplay"] = {
        "schemaVersion": argus_market_replay.SCHEMA_VERSION,
        "methodVersion": argus_market_replay.METHOD_VERSION,
        "instrumentId": _instrument_id,
        "contexts": argus_market_replay.latest_contexts(
            _MARKET_REPLAY, _instrument_id),
        "stateHash": argus_market_replay.state_hash(_MARKET_REPLAY),
        "readBack": dict(_MARKET_REPLAY_REMOTE),
        "automaticAiCalls": 0,
        "computationMode": "deterministic_background_cache",
        "cacheStatus": ("hit" if _replay_cache_hit else
                        "updated" if precompute_replay and timeframe == "daily"
                        else "read_only"),
    }
    report["shortDataAudit"] = argus_today_intelligence.data_source_audit(
        _today_intel.get("shortSelling") or {},
        "available_per_symbol_via_jpx_disclosure" if market == "JP" else
        "not_connected_for_us")
    _instrument_type = "ETF" if symbol in {"1321", "1306", "SPY", "QQQ"} else "EQUITY"
    report["instrumentMetadata"] = {
        "instrumentId": f"{market}:{symbol}:{_instrument_type}",
        "symbol": symbol, "market": market, "assetType": _instrument_type,
        "displayNameJa": report["displayNameJa"],
        "source": report.get("source"),
        "availableFrom": (daily_rows[0].get("date") if daily_rows else None),
        "observedAt": now_iso, "revision": 0,
        "proxyFor": "Nikkei 225" if symbol == "1321" else None,
        "licenseStatus": "license_unverified" if symbol == "1321" else "not_applicable",
    }
    if symbol == "1321":
        report["displayNameJa"] = "日経225 ETF"
        report["proxyDisclosureJa"] = (
            "ETF PROXY — 日経平均の現物指数値ではなく、日経225連動ETF（1321）を表示。"
        )
        report["instrumentMetadata"]["displayNameJa"] = "日経225 ETF"
    report["turningPointPage"] = {
        "totalStoredCount": len([point for point in
                                 _CHART_INTELLIGENCE.get("turningPoints", [])
                                 if point.get("symbol") == symbol and
                                 point.get("market") == market]),
        "apiReturnCount": len(report.get("turningPoints") or []),
        "uiDisplayLimit": 3,
        "activeCount": len([point for point in report.get("turningPoints") or []
                            if point.get("status") in ("candidate", "confirmed")]),
        "confirmedCount": len([point for point in report.get("turningPoints") or []
                               if point.get("status") == "confirmed"]),
        "periodFilter": None, "limit": None, "nextCursor": None,
    }
    report["ledgerTurningPoints"] = []
    if market_scope:
        histories = {
            "nikkei": rows,
            "topix": history("1306", "JP"),
            "semiconductor": history("2644", "JP"),
            "growth": history("2516", "JP"),
            "sp500": history("SPY", "US"),
            "usdjpy": history("USD/JPY", "US"),
        }
        definitions = {
            "nikkei_sp500": ("nikkei", "sp500", "argus_heuristic"),
            "nikkei_usdjpy": ("nikkei", "usdjpy", "derived"),
            "topix_nikkei": ("topix", "nikkei", "derived"),
            "semiconductor_topix": ("semiconductor", "topix", "derived"),
            "growth_topix": ("growth", "topix", "derived"),
            "dollar_nikkei": ("nikkei", "usdjpy", "derived"),
        }
        relative = {key: argus_chart_intelligence.relative_strength(
            key, histories[left], histories[right], classification=classification)
                    for key, (left, right, classification) in definitions.items()}
        rotation_inputs = {
            "TOPIX": histories["topix"], "日経平均": histories["nikkei"],
            "グロース": histories["growth"], "半導体": histories["semiconductor"],
            "バリュー": [], "高配当": [], "ディフェンシブ": [], "金融": [],
            "自動車": [], "電線": [], "AI": [], "REIT": [], "金": [], "暗号資産": [],
        }
        report["relativeStrength"] = relative
        report["rotationMap"] = argus_chart_intelligence.rotation_map(rotation_inputs)
        report["turningPoints"] = (report.get("turningPoints") or []) + \
            argus_chart_intelligence.relative_strength_turning_points(relative)
        report["ledgerTurningPoints"] = list(ledger.get("turningPoints") or [])
        report["relationshipBreaks"] = argus_chart_intelligence.relationship_breaks(
            ledger_summary=ledger.get("summary"), relative=relative,
            eps_change=(ledger.get("valuationSummary") or {}).get("eps5Change"),
            per_change=(ledger.get("valuationSummary") or {}).get("per21ChangeFromPeak"))
    try:
        _chart_now_utc = datetime.fromisoformat(
            now_iso.replace("Z", "+00:00")).astimezone(pytz.utc)
    except (TypeError, ValueError):
        _chart_now_utc = datetime.now(pytz.utc)
    _chart_market = (argus_market_clock.JP_EQUITY
                     if market == "JP" else argus_market_clock.US_EQUITY)
    _chart_calendar = argus_market_clock.market_session(
        _chart_market, _chart_now_utc)
    report["marketCalendar"] = _chart_calendar
    if not _chart_calendar["isTradingDay"]:
        report["stateUpdate"] = {
            "status": "expected_skip", "reason": "market_holiday"}
        report["persistence"] = {
            "stateHash": argus_chart_intelligence.state_hash(
                _CHART_INTELLIGENCE),
            "todayIntelligenceStateHash": argus_today_intelligence.state_hash(
                _TODAY_INTELLIGENCE),
            "todayIntelligenceReadBack": dict(_TODAY_INTELLIGENCE_REMOTE),
            "marketReplayStateHash": argus_market_replay.state_hash(
                _MARKET_REPLAY),
            "marketReplayReadBack": dict(_MARKET_REPLAY_REMOTE),
            **_CHART_INTELLIGENCE_REMOTE,
        }
        return report
    merged = argus_chart_intelligence.merge_report(
        _CHART_INTELLIGENCE, report, now_iso)
    _CHART_INTELLIGENCE.clear()
    _CHART_INTELLIGENCE.update(merged)
    _today_merged = argus_today_intelligence.merge_analysis(
        _TODAY_INTELLIGENCE, _today_intel,
        daily_rows[-1] if daily_rows else None, _short_rows, now_iso)
    _TODAY_INTELLIGENCE.clear()
    _TODAY_INTELLIGENCE.update(_today_merged)
    _total_points = [point for point in _CHART_INTELLIGENCE.get("turningPoints", [])
                     if point.get("symbol") == symbol and point.get("market") == market]
    report["turningPointPage"]["totalStoredCount"] = len(_total_points)
    report["stateUpdate"] = {"status": "updated", "reason": None}
    report["persistence"] = {"stateHash": argus_chart_intelligence.state_hash(
        _CHART_INTELLIGENCE),
        "todayIntelligenceStateHash": argus_today_intelligence.state_hash(
            _TODAY_INTELLIGENCE),
        "todayIntelligenceReadBack": dict(_TODAY_INTELLIGENCE_REMOTE),
        "marketReplayStateHash": argus_market_replay.state_hash(
            _MARKET_REPLAY),
        "marketReplayReadBack": dict(_MARKET_REPLAY_REMOTE),
        **_CHART_INTELLIGENCE_REMOTE}
    return report


@app.route("/api/argus/chart-intelligence")
def api_argus_chart_intelligence():
    """Deterministic GET-only chart facts.  No generated-AI call occurs here."""
    scope = (request.args.get("scope") or "asset").strip().lower()
    timeframe = (request.args.get("timeframe") or "daily").strip().lower()
    if timeframe not in ("daily", "weekly"):
        return jsonify({"error": "invalid_timeframe"}), 400
    if scope == "market":
        symbol = (request.args.get("symbol") or "1321").strip().upper()
        if symbol not in {"1321", "1306", "SPY", "QQQ"}:
            return jsonify({"error": "unsupported_market_instrument"}), 400
        market = "JP" if symbol in {"1321", "1306"} else "US"
        horizon = (request.args.get("horizon") or "5D").strip().upper()
        if horizon not in {"1D", "5D", "20D"}:
            return jsonify({"error": "invalid_horizon"}), 400
        verified = _verified_market_snapshot(
            symbol, int(horizon.removesuffix("D")))
        if request.args.get("snapshot") == "verified":
            if not verified:
                response = jsonify({
                    "status": "not_ready", "reason": "verified_snapshot_missing",
                    "instrument": symbol, "horizon": horizon,
                    "automaticAiCalls": 0,
                })
                response.status_code = 503
                response.headers["Cache-Control"] = "private, no-store"
                return response
            etag = f'"{verified["snapshotId"]}"'
            supplied = request.headers.get("If-None-Match", "")
            # RFC 9110 uses weak comparison for If-None-Match on GET. Render's
            # edge may legitimately rewrite our strong validator as W/"...".
            # Compare the opaque tag after removing only that weakness marker.
            supplied_tags = []
            for part in supplied.split(","):
                candidate = part.strip()
                if candidate[:2].lower() == "w/":
                    candidate = candidate[2:].strip()
                supplied_tags.append(candidate)
            if "*" in supplied_tags or etag in supplied_tags:
                response = make_response("", 304)
            else:
                response = jsonify(verified)
            response.headers["ETag"] = etag
            response.headers["Cache-Control"] = \
                "private, max-age=0, must-revalidate"
            response.headers["Vary"] = "If-None-Match"
            try:
                generated = datetime.fromisoformat(
                    str(verified["generatedAt"]).replace(
                        "Z", "+00:00")).astimezone(pytz.utc)
                response.headers["Last-Modified"] = generated.strftime(
                    "%a, %d %b %Y %H:%M:%S GMT")
            except (TypeError, ValueError):
                pass
            response.headers["X-ARGUS-Snapshot-Id"] = verified["snapshotId"]
            response.headers["X-ARGUS-Compute-Mode"] = "read-only"
            return response
        # This provider-free GET boundary is backend-sensitive. Scheduled ticks
        # alone refresh the cache before public acceptance starts.
        # 1321 is explicitly a Nikkei-linked ETF proxy, not the cash index.
        _public_cache_key = ("market", symbol, timeframe)
        _public_cached = _MARKET_PUBLIC_REPORT_CACHE.get(_public_cache_key)
        _public_cache_hit = isinstance(_public_cached, dict)
        report = (copy.deepcopy(_public_cached) if _public_cache_hit
                  else copy.deepcopy(verified["payload"])
                  if verified and timeframe == "daily"
                  # Backward-compatible raw route only. The v13.3 frontend
                  # never calls this path: it requests snapshot=verified,
                  # whose missing branch above is strict not_ready and cannot
                  # invoke this deterministic legacy assembler.
                  else _chart_public_report(
                      symbol, market, timeframe,
                      market_scope=symbol == "1321", cached_only=True))
        # The cached report records how the scheduler produced its replay
        # ("updated").  At this GET boundary the contract is instead whether
        # the immutable scheduled report was reused without recomputation.
        if isinstance(report.get("marketReplay"), dict):
            report["marketReplay"]["cacheStatus"] = "hit"
        report["displayNameJa"] = argus_calibration.DISPLAY_NAMES.get(symbol, symbol)
        if symbol == "1321":
            report["proxyDisclosureJa"] = (
                "現物日経平均そのものではなく、既存の公式日足経路で取得する連動ETFを使用。")
        return jsonify(argus_market_intelligence.normalize_public_names(report))
    symbol = (request.args.get("symbol") or "").strip().upper()
    market = (request.args.get("market") or ("JP" if symbol[:1].isdigit() else "US")).upper()
    if market == "JP" and not _JP_SYM_RE.match(symbol):
        return jsonify({"error": "bad_symbol"}), 400
    if market == "US" and not _US_SYM_RE.match(symbol):
        return jsonify({"error": "bad_symbol"}), 400
    cached_asset = argus_asset_chart_cache.current(
        _ASSET_CHART_REPORTS, market, symbol, timeframe)
    if cached_asset:
        report = copy.deepcopy(cached_asset["payload"])
        report["assetChartCache"] = {
            "status": "hit",
            "datasetHash": cached_asset.get("datasetHash"),
            "methodVersion": cached_asset.get("methodVersion"),
            "publishedAt": cached_asset.get("publishedAt"),
            "readBack": dict(_ASSET_CHART_REPORTS_REMOTE),
        }
        return jsonify(
            argus_market_intelligence.normalize_public_names(report))
    if (symbol, market) in set(_asset_chart_targets()):
        return jsonify({
            "reportId": None,
            "status": "expected_skip",
            "automaticAiCalls": 0,
            "costPolicyMode": _COST_POLICY.get("mode"),
            "stateUpdate": {
                "status": "expected_skip",
                "reason": "price_cache_unavailable",
            },
            "assetChartCache": {
                "status": "miss",
                "methodVersion": _ASSET_CHART_METHOD_VERSION,
                "readBack": dict(_ASSET_CHART_REPORTS_REMOTE),
            },
        })
    return jsonify(argus_market_intelligence.normalize_public_names(
        _chart_public_report(
            symbol, market, timeframe, market_scope=False, cached_only=True)))


# v13.5.50: the owner asked for the indices themselves (SHO reasons about
# the Nikkei 225, not the 1321 ETF).  Cached-only public GET over the Yahoo
# index OHLCV cache the SHO warm already fills; the verified snapshots
# (1321/1306/SPY/QQQ) remain the decision anchor.  Never fetches here.
_INDEX_CHART_SOURCES = {
    "N225": {"yahoo": ("^N225",), "market": "JP", "instrumentId": "NIKKEI_225_INDEX",
             "displayNameJa": "日経平均株価(指数)"},
    "TOPIX": {"yahoo": ("^TPX", "998405.T"), "market": "JP", "instrumentId": "TOPIX_INDEX",
              "displayNameJa": "TOPIX(指数)"},
    "SPX": {"yahoo": ("^GSPC",), "market": "US", "instrumentId": "SP500_INDEX",
            "displayNameJa": "S&P 500(指数)"},
    "NDX": {"yahoo": ("^IXIC",), "market": "US", "instrumentId": "NASDAQ_COMPOSITE_INDEX",
            "displayNameJa": "ナスダック総合(指数)"},
}
_INDEX_CHART_DISCLOSURE_JA = ("指数そのもの(Yahoo Finance 日足・参考表示)。売買判断の正本は"
                              "検証済みスナップショット(1321/1306/SPY/QQQ)のままです。")


@app.route("/api/argus/index-chart")
def api_argus_index_chart():
    """PUBLIC cached-only: deterministic chart facts for a real index."""
    index = (request.args.get("index") or "N225").strip().upper()
    spec = _INDEX_CHART_SOURCES.get(index)
    if spec is None:
        return jsonify({"error": "unsupported_index",
                        "supported": sorted(_INDEX_CHART_SOURCES)}), 400
    timeframe = (request.args.get("timeframe") or "daily").strip().lower()
    if timeframe not in ("daily", "weekly"):
        return jsonify({"error": "invalid_timeframe"}), 400
    rows, yahoo_used = None, None
    for yahoo_symbol in spec["yahoo"]:
        cached = _SHO_INDEX_OHLCV_CACHE.get(yahoo_symbol)
        data = cached.get("data") if isinstance(cached, dict) else None
        if isinstance(data, list) and len(data) >= 30:
            rows, yahoo_used = data, yahoo_symbol
            break
    if not rows:
        return jsonify({
            "reportId": None, "status": "expected_skip", "automaticAiCalls": 0,
            "index": index, "displayNameJa": spec["displayNameJa"],
            "stateUpdate": {"status": "expected_skip", "reason": "index_cache_cold"},
            "noteJa": "指数日足はまだ取得されていません(起動後の巡回で自動取得されます)。",
        })
    known_at = _ai_now_iso()
    history = {
        "dates": [str(row.get("date"))[:10] for row in rows],
        "opens": [row.get("open") for row in rows],
        "highs": [row.get("high") for row in rows],
        "lows": [row.get("low") for row in rows],
        "closes": [row.get("close") for row in rows],
        "volumes": [row.get("volume") for row in rows],
        "adjusted": [False] * len(rows),
    }
    chart_rows = _chart_rows_from_history(
        history, market=spec["market"], provider="yahoo_index",
        known_at=known_at, dataset_id=f"yahoo_index:{yahoo_used}:{known_at}")
    report = _chart_public_report(
        index, spec["market"], timeframe, market_scope=False,
        cached_only=True, daily_rows_override=chart_rows)
    report["index"] = index
    report["displayNameJa"] = spec["displayNameJa"]
    report["proxyDisclosureJa"] = None
    report["indexDisclosureJa"] = _INDEX_CHART_DISCLOSURE_JA
    metadata = report.get("instrumentMetadata")
    if isinstance(metadata, dict):
        metadata.update({
            "instrumentId": f"INDEX:{spec['instrumentId']}", "assetType": "INDEX",
            "displayNameJa": spec["displayNameJa"], "source": "yahoo_index_ohlcv",
            "proxyFor": None, "licenseStatus": "display_reference",
            "sourceSymbol": yahoo_used,
        })
    return jsonify(argus_market_intelligence.normalize_public_names(report))


@app.route("/api/argus/today-headline")
def api_argus_today_headline():
    """Compact Today bootstrap derived from the verified market snapshots.

    Read-only GET: every value is copied from the already-published canonical
    verified snapshots, so this cannot become a second decision authority.
    The heavy per-instrument snapshot route stays authoritative for full
    history and evidence; this response exists so Today can show prices, four
    compact charts, and canonical probabilities without transporting ~13 MB.
    """
    snapshots = {
        symbol: _verified_market_snapshot(symbol, 5)
        for symbol in argus_today_headline.HEADLINE_INSTRUMENTS
    }
    document = argus_today_headline.build_today_headline(
        snapshots, now_iso=datetime.now(pytz.utc).strftime(
            "%Y-%m-%dT%H:%M:%SZ"))
    etag = f'"{document["headlineSetId"]}"'
    supplied_tags = []
    for part in request.headers.get("If-None-Match", "").split(","):
        candidate = part.strip()
        if candidate[:2].lower() == "w/":
            candidate = candidate[2:].strip()
        supplied_tags.append(candidate)
    if "*" in supplied_tags or etag in supplied_tags:
        response = make_response("", 304)
    else:
        # An all-unavailable document is itself the truthful state (every
        # instrument entry carries an explicit unavailable reason), so this
        # public read stays HTTP 200 like the other cached product GETs.
        response = jsonify(document)
    response.headers["ETag"] = etag
    response.headers["Cache-Control"] = "private, max-age=0, must-revalidate"
    response.headers["Vary"] = "If-None-Match"
    response.headers["X-ARGUS-Compute-Mode"] = "read-only"
    response.headers["X-ARGUS-Headline-Set-Id"] = document["headlineSetId"]
    return response


# ── V13.5.13 Decision Evidence — canonical artifact references for the SDA ─────
# The device-side Single Decision Authority deliberately refuses plain-object
# AVAILABLE references (canonical_artifact_resolver_unavailable). This block is
# the reviewed backend half of that resolver boundary: per subject it builds
# the three canonical artifacts from already-cached quote/clock state, runs the
# same verifiers verify_decision_evidence recomputes, and publishes the
# resulting reference dicts. No owner data is read, no action is produced, and
# every failure fails closed to MISSING/STALE references with the reason kept.

_DECISION_EVIDENCE_CACHE = {}
_DECISION_EVIDENCE_TTL_SEC = 120
_DECISION_EVIDENCE_MAX_SYMBOLS = 8
_DECISION_EVIDENCE_DEFAULT_SYMBOLS = ("1321", "1306", "SPY", "QQQ")

# v13.5.60 (production 2026-09-07): the heavier public documents
# (decision-evidence, events, important-events, dashboard-events) stalled past
# every client timeout while the cheap cached routes kept answering. Several
# owner devices plus the acceptance engine poll the same documents every
# 15-30 s, and every request recomputed the same result concurrently — a
# thundering herd on one Render CPU. Single-flight: one computation per key at
# a time; concurrent callers join the in-progress result instead of adding
# work. A caller that cannot get a result within the wait budget receives a
# bounded 503 `busy` (a truthful transient state) instead of a hung socket.
_SINGLE_FLIGHT_LOCK = threading.Lock()
_SINGLE_FLIGHT = {}   # key -> {"event", "result", "error", "startedAt"}
_SINGLE_FLIGHT_WAIT_SEC = 45.0


def _single_flight(key, compute, *, wait_sec=_SINGLE_FLIGHT_WAIT_SEC):
    """Run `compute()` once per key at a time.

    Returns (result, mode): mode is "computed" for the leader, "joined" for a
    follower that received the leader's result, "busy" (result None) for a
    follower whose wait budget expired. The leader's exception propagates to
    the leader and to every follower that joined it."""
    with _SINGLE_FLIGHT_LOCK:
        entry = _SINGLE_FLIGHT.get(key)
        leader = entry is None
        if leader:
            entry = {"event": threading.Event(), "result": None,
                     "error": None, "startedAt": time.time()}
            _SINGLE_FLIGHT[key] = entry
    if leader:
        try:
            entry["result"] = compute()
        except BaseException as exc:  # re-raised below; followers see it too
            entry["error"] = exc
        finally:
            with _SINGLE_FLIGHT_LOCK:
                if _SINGLE_FLIGHT.get(key) is entry:
                    _SINGLE_FLIGHT.pop(key, None)
            entry["event"].set()
        if entry["error"] is not None:
            raise entry["error"]
        return entry["result"], "computed"
    if not entry["event"].wait(wait_sec):
        return None, "busy"
    if entry["error"] is not None:
        raise entry["error"]
    return entry["result"], "joined"


def _single_flight_status():
    """Secret-free view of in-flight computations (keys are route names)."""
    now = time.time()
    with _SINGLE_FLIGHT_LOCK:
        return [{"key": str(key)[:80],
                 "ageSec": round(now - float(entry.get("startedAt") or now), 1)}
                for key, entry in _SINGLE_FLIGHT.items()]


def _busy_response(route_key, started):
    """Bounded 503 for a single-flight wait that exceeded its budget."""
    response = jsonify({"error": "busy", "reason": "single_flight_wait_exceeded",
                        "route": route_key, "retryAfterSec": 5,
                        "elapsedMs": int((time.time() - started) * 1000)})
    response.headers["Retry-After"] = "5"
    response.headers["X-ARGUS-Flight"] = "busy"
    return response, 503


def _single_flight_json(route_key, compute):
    """jsonify(compute()) under single-flight, with elapsed/flight headers."""
    started = time.time()
    result, mode = _single_flight(route_key, compute)
    if mode == "busy":
        return _busy_response(route_key, started)
    response = jsonify(result)
    response.headers["X-ARGUS-Elapsed-Ms"] = str(int((time.time() - started) * 1000))
    response.headers["X-ARGUS-Flight"] = mode
    return response


def _decision_evidence_watch_row(symbol, market):
    try:
        # Public GET contract: cache-only, never a provider fetch — a cold
        # cache degrades to the EOD history fallback / MISSING references
        # instead of burning provider budget from unauthenticated polling.
        if market == "JP":
            snapshot = get_japan_watchlist_snapshot(
                allow_provider_fetch=False, record_requested_symbols=False)
        else:
            snapshot = get_us_watchlist_snapshot(allow_provider_fetch=False)
    except Exception:
        return None, None
    if not isinstance(snapshot, dict):
        return None, None
    for row in snapshot.get("stocks") or []:
        if str(row.get("symbol") or "").upper() == symbol:
            return row, snapshot.get("provider")
    return None, None


def _latest_close_date(closes):
    """Newest bar date in a close list, or "" when there is none."""
    return max((str(row.get("date"))[:10] for row in closes), default="")


def _verified_snapshot_closes(symbol):
    """Daily closes from the published verified market snapshot, or []."""
    try:
        snapshot = _verified_market_snapshot(symbol, 5)
        bars = (((snapshot or {}).get("payload") or {})
                .get("indicators") or {}).get("bars") or []
    except Exception:
        return []
    return [row for row in bars if isinstance(row, dict)
            and isinstance(row.get("close"), (int, float))
            and row.get("date")]


def _decision_evidence_history_row(symbol, market):
    """EOD fallback quote row from the cached daily history.

    The four Today headline instruments are not members of the owner watch
    snapshots, so the watch-row source alone reported quote_row_unavailable in
    production. The cached daily close is legitimate delayed/stale evidence:
    the observation freshness classifier downgrades it honestly (DELAYED
    within 36h, else STALE → STALE reference, never a fabricated AVAILABLE).
    """
    try:
        rows = _chart_history_cached(symbol, market) or []
    except Exception:
        rows = []
    closes = [row for row in rows if isinstance(row, dict)
              and isinstance(row.get("close"), (int, float))
              and row.get("date")]
    # v13.5.54 (owner 2026-09-04, 「まだ完全ではない」).  The provider history cache
    # was the ONLY source here, and it fails in BOTH directions: it is empty
    # after every restart, and it holds the previous session for up to six
    # hours after a close (a pure time TTL with no session-boundary
    # invalidation).  Both were measured in production on 2026-09-04:
    #
    #   08:47Z  cache held 09-03 while the latest completed JP session was
    #           09-04  -> marketTruth STALE  (subject_selection_not_fresh)
    #   19:53Z  cache empty minutes after a deploy
    #           -> marketTruth MISSING
    #
    # Either way the owner saw a chart drawn from evidence the decision
    # claimed not to have, and every subject data-gated to WAIT.
    #
    # The verified market snapshot is the SAME canonical evidence the headline
    # bootstrap already publishes; reading it is an in-memory lookup behind its
    # own signature check — no provider call, no new authority.  So take
    # whichever source carries the LATER close: that fixes the empty cache and
    # the stale cache with one rule, and can never pick older evidence than
    # before.  The freshness classifier still downgrades the winner honestly,
    # so this can only ever produce DELAYED/STALE, never a fabricated
    # AVAILABLE.
    snapshot_closes = _verified_snapshot_closes(symbol)
    if snapshot_closes and _latest_close_date(snapshot_closes) > _latest_close_date(closes):
        closes = snapshot_closes
    if not closes:
        return None, None
    # v13.5.36 PRODUCTION BUG: the cached history arrives newest-first in
    # production (ascending in the local repro), so closes[-1] picked the
    # OLDEST bar (2016-09-06 observed live) — the daily-authority check then
    # honestly rejected it as stale and every evening decision data-gated.
    # Order-independent selection: the latest date wins, always.
    closes.sort(key=lambda row: str(row.get("date"))[:10])
    last = closes[-1]
    change_pct = None
    if len(closes) >= 2:
        prev = closes[-2].get("close")
        if isinstance(prev, (int, float)) and prev > 0:
            change_pct = round((float(last["close"]) / float(prev) - 1.0)
                               * 100.0, 4)
    quote = {"symbol": symbol, "status": "delayed",
             "price": float(last["close"]), "date": str(last["date"])[:10],
             # Provenance stays visible; the PROVIDER is the true upstream of
             # the cached daily series (authority ranking is per real
             # provider — v13.5.36 fix: the synthetic "history-cache" label
             # had rank None, so the whole weekend/holiday EOD path was
             # provider_not_authoritative and every subject data-gated).
             "sourceRef": f"history-cache:{symbol}:{str(last['date'])[:10]}"}
    if change_pct is not None:
        quote["changePct"] = change_pct
    return quote, ("jquants" if market == "JP" else "twelvedata")


def _decision_evidence_market_artifact(symbol, market, cutoff, build_identity):
    row, provider = _decision_evidence_watch_row(symbol, market)
    if not isinstance(row, dict):
        row, provider = _decision_evidence_history_row(symbol, market)
    if not isinstance(row, dict):
        return None, "quote_row_unavailable"
    observations = _canonical_quote_observations(
        [(market, provider, row)], cutoff, bare_instrument_ids=True)
    if not observations:
        return None, "no_admissible_quote_observation"
    try:
        artifact = argus_market_data_truth.build_decision_snapshot(
            observations,
            requests=[{"instrumentId": symbol, "market": market,
                       "factType": "QUOTE",
                       "currency": "JPY" if market == "JP" else "USD",
                       "required": True}],
            decision_at=cutoff, generated_at=cutoff,
            build_identity=build_identity)
    except (TypeError, ValueError, OverflowError):
        return None, "snapshot_build_failed"
    return artifact, None


def _decision_evidence_prediction_artifact(symbol, market, cutoff,
                                           market_artifact, build_identity):
    """Ephemeral forward-live decision context bound to the same snapshot.

    This is a CONTEXT record for the SDA's predictionLedger reference (same
    builder + seal as durable records); the durable append-only ledger on the
    ledger branch remains the only issued-decision archive."""
    try:
        selections = [row for row in market_artifact.get("selections", [])
                      if row.get("instrumentId") == symbol]
        if len(selections) != 1:
            return None, "subject_selection_missing"
        observation = (selections[0].get("selected") or {}).get("observation")
        if not isinstance(observation, dict):
            return None, "selected_observation_missing"
        values = observation.get("values") or {}
        change = values.get("changePct")
        if not isinstance(change, (int, float)) or isinstance(change, bool) \
                or not math.isfinite(float(change)):
            return None, "change_pct_unavailable"
        maturity = _canonical_target_contract(symbol, cutoff, "5d")
        if not maturity:
            return None, "maturity_contract_unavailable"
        band_pct = 2.0
        scenario_pairs = _scenarios_scaled(float(change), band_pct)
        scenario_map = {label: float(probability) / 100.0
                        for label, probability in scenario_pairs}
        if set(scenario_map) != set(argus_calibration.CLASSES):
            return None, "scenario_classes_invalid"
        probabilities = [scenario_map[label]
                         for label in argus_calibration.CLASSES]
        distribution = argus_decision_ledger.forecast_distribution(
            class_labels=list(argus_calibration.CLASSES),
            probabilities=probabilities,
            class_order_version=(f"{argus_calibration.SCHEMA_VERSION}:"
                                 f"{argus_calibration.BAND_VERSION}"))
        if distribution is None:
            return None, "forecast_distribution_invalid"
        winner_index = max(range(len(probabilities)),
                           key=lambda index: probabilities[index])
        truth_ref = argus_decision_ledger.point_in_time_truth_ref(
            snapshot_id=market_artifact["snapshotId"],
            source_id=observation.get("observationId"),
            as_of=observation.get("observedAt"),
            known_at=observation.get("knownAt"),
            content_hash=observation.get("observationId"),
            observation_kind="decision_quote",
            observed_fields=sorted((observation.get("values") or {}).keys()),
            provider=(observation.get("source") or {}).get("providerKey") or "",
            revision=str(observation.get("revision") or ""))
        if not truth_ref:
            return None, "truth_ref_invalid"
        _, evaluation_policy = _canonical_scenario_policy(
            band_pct=band_pct, horizon="5d")
        record = argus_decision_ledger.prediction_record_v2(
            mode="forward_live", symbol=symbol, market=market,
            issued_at=cutoff, horizon="5d", target_type="scenario",
            forecast_value=argus_calibration.CLASSES[winner_index],
            forecast_distribution=distribution,
            truth_ref=truth_ref, maturity=maturity,
            engine_id="argus-decision-evidence-context",
            engine_version="decision-evidence-v1",
            build_sha=build_identity,
            evaluation_policy=evaluation_policy, now_iso=cutoff,
            confidence=float(probabilities[winner_index]),
            candidate_action="",
            evidence_refs=[observation.get("observationId")])
        if not record:
            return None, "prediction_record_invalid"
        return record, None
    except (TypeError, ValueError, OverflowError, KeyError):
        return None, "prediction_context_failed"


# ━━━ v13.5.36 SHO CORE production inputs (external review item B) ━━━
# The read-only audit confirmed evaluate_d01_d07 was never called from any
# production path and the live reversal artifact ran on zero rows. This block
# wires the feeds the process already holds — JPX credit CSV+ledger, J-Quants
# 1570 weekly margin, ETF-proxy relative strength from the verified chart
# caches, Market Ledger foreign flow, and Yahoo ^VIX/^N225 complete OHLCV —
# into the canonical SHO engines. Every row carries an explicit availableFrom
# (PIT); the public decision-evidence GET stays strictly cached-only (fetch is
# passed ONLY by the 30-min collect cron warm). A cold feed leaves its family
# MISSING/LICENSE_BLOCKED — absence is reported, never impersonated.
_SHO_INDEX_OHLCV_CACHE = {}
_SHO_INDEX_OHLCV_TTL_SEC = 1800
_SHO_PIT_INPUT_MEMO = {"ts": 0.0, "data": None}
_SHO_MARKET_VIEW_MEMO = {"ts": 0.0, "view": None}


def _yahoo_index_ohlcv(yahoo_symbol, instrument_id, *, fetch=False,
                       available_hour_utc=None, next_day_available=False):
    """Complete OHLCV rows for one index from the public Yahoo v8 chart API.

    Rows are shaped for argus_sho.normalize_complete_ohlcv with an explicit
    per-bar availableFrom, which keeps the current in-progress session OUT of
    evidence until after its close. Volume is passed through exactly as the
    source reports it (0 for ^VIX) and bars with any null component are
    dropped, never filled. Cache-only unless fetch=True (cron warm); a stale
    cache still serves (its rows carry their own PIT stamps)."""
    now = time.time()
    cached = _SHO_INDEX_OHLCV_CACHE.get(yahoo_symbol)
    if cached and (not fetch or now < cached["expires"]):
        return cached["data"]
    if not fetch:
        return []
    rows = []
    try:
        r = requests.get(
            f"https://query1.finance.yahoo.com/v8/finance/chart/{yahoo_symbol}",
            params={"interval": "1d", "range": "2y"},
            headers={"User-Agent": "Mozilla/5.0 (argus)"}, timeout=15)
        result = ((r.json() or {}).get("chart") or {}).get("result") or []
        meta = (result[0].get("meta") or {}) if result else {}
        offset = int(meta.get("gmtoffset") or 0)
        quote = (((result[0].get("indicators") or {}).get("quote")
                  or [{}])[0]) if result else {}
        stamps = (result[0].get("timestamp") or []) if result else []
        by_date = {}
        for position, stamp in enumerate(stamps):
            values = {}
            for key in ("open", "high", "low", "close", "volume"):
                series = quote.get(key) or []
                values[key] = (series[position]
                               if position < len(series) else None)
            if any(not isinstance(values[key], (int, float))
                   or isinstance(values[key], bool) for key in values):
                continue                   # incomplete source bar — never fill
            date = datetime.utcfromtimestamp(int(stamp) + offset).date()
            if next_day_available:
                available = (date + timedelta(days=1)).isoformat() \
                    + "T00:00:00Z"
            else:
                available = (date.isoformat()
                             + f"T{int(available_hour_utc):02d}:00:00Z")
            by_date[date.isoformat()] = {
                "instrumentId": instrument_id, "date": date.isoformat(),
                **{key: float(values[key]) for key in
                   ("open", "high", "low", "close", "volume")},
                "availableFrom": available, "adjusted": False,
                "sourceRef": f"yahoo:chart:{yahoo_symbol}",
            }
        rows = [by_date[key] for key in sorted(by_date)]
    except Exception:
        rows = []
    _SHO_INDEX_OHLCV_CACHE[yahoo_symbol] = {
        "data": rows,
        "expires": now + (_SHO_INDEX_OHLCV_TTL_SEC if rows else 300)}
    return rows


def _sho_margin_1570_rows(*, fetch=False):
    """1570 weekly margin ratio as PIT rows for SHO D02.

    J-Quants publishes weekly margin interest during the following week, so
    availableFrom = period + 7 days keeps the join conservative. Cache-only
    unless the cron warm passes fetch."""
    if fetch:
        data = _jq_weekly_margin("1570")
    else:
        cached = _JQ_MARGIN_CACHE.get("1570")
        data = cached.get("data") if isinstance(cached, dict) else None
    rows = []
    for row in data or []:
        try:
            date = str(row.get("date") or "")[:10]
            long_volume = float(row.get("longVol"))
            short_volume = float(row.get("shortVol"))
        except (TypeError, ValueError):
            continue
        if len(date) != 10 or short_volume <= 0:
            continue
        try:
            available = (datetime.strptime(date, "%Y-%m-%d").date()
                         + timedelta(days=7)).isoformat() + "T00:00:00Z"
        except ValueError:
            continue
        rows.append({"instrumentId": "1570", "field": "margin_ratio",
                     "date": date,
                     "value": round(long_volume / short_volume, 6),
                     "availableFrom": available})
    return rows


def _sho_relative_strength_proxy():
    """20-session relative strength of 1321 vs SPY (verified chart caches).

    One PIT row for SHO D03's explicit ETF-proxy lane (ARGUS_CANDIDATE
    lineage is assigned by the evaluator itself). availableFrom is after the
    15:30 JST close of the row's session; cached-only, None when cold."""
    try:
        def twenty_day_return(rows):
            ordered = sorted((rows or []),
                             key=lambda row: str(row.get("date") or ""))
            closes = [float(row["close"]) for row in ordered
                      if isinstance(row.get("close"), (int, float))
                      and not isinstance(row.get("close"), bool)]
            if len(closes) < 21 or closes[-21] <= 0:
                return None, None
            date = str(ordered[-1].get("date") or "")[:10]
            return closes[-1] / closes[-21] - 1, date
        jp_return, jp_date = twenty_day_return(
            _chart_history_cached("1321", "JP"))
        us_return, _us_date = twenty_day_return(
            _chart_history_cached("SPY", "US"))
        if jp_return is None or us_return is None or len(jp_date or "") != 10:
            return None
        return {"instrumentId": "1321",
                "seriesId": "relative_strength_20d", "date": jp_date,
                "value": round(jp_return - us_return, 6),
                "availableFrom": jp_date + "T07:00:00Z"}
    except Exception:
        return None


def _sho_foreign_flow_rows():
    """flow.foreign observations from the Market Ledger for SHO D05."""
    rows = []
    try:
        by_series = argus_market_ledger.latest_by_series(
            _MARKET_LEDGER, _ai_now_iso())
        for row in by_series.get("flow.foreign", []) or []:
            period = str(row.get("periodEnd") or "")[:10]
            value = row.get("value")
            available = str(row.get("availableFrom") or "")
            if (len(period) == 10 and available
                    and isinstance(value, (int, float))
                    and not isinstance(value, bool)):
                rows.append({"seriesId": "flow.foreign", "periodEnd": period,
                             "availableFrom": available,
                             "value": float(value)})
    except Exception:
        pass
    return rows


def _sho_vix_rows(*, fetch=False):
    """VIX rows for D06 + the reversal VIX axis, with an explicit source tag.

    Yahoo complete OHLCV is preferred (enables the MACD axis); the FRED
    close-only series is the fallback (D06 still evaluates; the reversal VIX
    axis stays honestly data-gated on close-only rows). The FRED-key-missing
    state is REPORTED, closing the silent-dropout the external review found."""
    yahoo = _yahoo_index_ohlcv("^VIX", "VIX", fetch=fetch,
                               next_day_available=True)
    if yahoo:
        return yahoo, "yahoo_ohlcv"
    try:
        dated = (_fred_vix_history_dated() if fetch
                 else (_VIX_HIST_DATED_CACHE.get("data") or []))
    except Exception:
        dated = []
    rows = [{"instrumentId": "VIX", "seriesId": "close", "date": row["date"],
             "value": row["value"], "close": row["value"],
             "availableFrom": row["availableFrom"]} for row in dated or []]
    if rows:
        return rows, "fred_close_only"
    return [], ("fred_key_missing" if not _FRED_API_KEY else "cold_cache")


# ── SHO D07 supply: earnings disclosures (v13.5.36) ─────────────────────────
# J-Quants /fins/statements is the authoritative TDnet-derived disclosure
# record (DisclosedDate/Time = official publication). PIT is carried on the
# EVENT via knownAt; the first tradable session comes from the canonical
# trading calendar (v13.5.36 — weekday-agnostic, conservative on gaps).
# No consensus dataset is contracted → epsEstimate stays None and beat/miss
# is never synthesized. Unknown provider schema → honest MISSING, never a
# guessed mapping.
_SHO_STATEMENTS_CACHE = {"rows": [], "fetchedAt": None, "expires": 0.0,
                         "source": "cold", "schemaSample": None}
_SHO_STATEMENTS_TTL_SEC = 6 * 3600
_SHO_STATEMENTS_WINDOW_DAYS = 14


def _stmt_field(row, *names):
    for name in names:
        value = row.get(name)
        if value not in (None, ""):
            return value
    return None


def _sho_statements_rows(*, warm=False):
    """Recent fins/statements rows for the tracked JP universe (cache-only on
    the public path; warm=True refreshes on the collect cron)."""
    now = time.time()
    cache = _SHO_STATEMENTS_CACHE
    if not warm or (cache["rows"] and now < cache["expires"]):
        return cache["rows"]
    if not _JQUANTS_API_KEY:
        cache["source"] = "missing_key"
        return cache["rows"]
    universe = {str(s.get("symbol"))[:4] for s in _JP_WATCHLIST}
    fetched = []
    try:
        for back in range(_SHO_STATEMENTS_WINDOW_DAYS):
            day = (datetime.now(TZ_JST) - timedelta(days=back)).strftime(
                "%Y-%m-%d")
            try:
                # v13.5.48: J-Quants V2 path (V1 /fins/statements was
                # discontinued 2026-06-01 and answers 403; the feed had been
                # silently empty since then).
                rows = _jquants_paginated("/fins/summary", {"date": day})
            except RuntimeError:
                continue
            for row in rows or []:
                if not isinstance(row, dict):
                    continue
                code = str(_stmt_field(row, "LocalCode", "Code",
                                       "code") or "")[:4]
                if code in universe:
                    fetched.append(row)
        cache["rows"] = fetched
        cache["fetchedAt"] = _ai_now_iso()
        cache["expires"] = now + _SHO_STATEMENTS_TTL_SEC
        cache["source"] = ("jquants_fins_statements" if fetched
                           else "no_universe_disclosures")
        if fetched and cache["schemaSample"] is None:
            cache["schemaSample"] = sorted(fetched[0].keys())[:24]
    except Exception as exc:
        cache["source"] = f"fetch_failed:{type(exc).__name__}"
    return cache["rows"]


def _sho_first_tradable_session(disclosed_date, disclosed_time):
    """(first_tradable_iso, flags) from the canonical calendar. Conservative:
    unknown time → treated as after-close; calendar gap → (None, reason)."""
    flags = {}
    try:
        base = datetime.strptime(disclosed_date, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None, {"reason": "invalid_disclosure_date"}
    time_known = bool(re.fullmatch(r"\d{2}:\d{2}(:\d{2})?",
                                   str(disclosed_time or "")))
    if not time_known:
        flags["publicationTimePrecision"] = "date_only_conservative"
    try:
        same_day_trading = argus_market_clock.canonical_trading_day(
            argus_market_clock.JP_EQUITY, base)
        hhmm = str(disclosed_time)[:5] if time_known else ""
        if same_day_trading and time_known and hhmm < "15:30":
            if hhmm >= "09:00":
                # During-session disclosure: the daily bar mixes pre/post
                # disclosure trading — flag the resolution limit honestly.
                flags["intradayDisclosureDailyResolutionLimited"] = True
            return base.isoformat(), flags
        probe = base
        for _ in range(20):
            probe = probe + timedelta(days=1)
            if argus_market_clock.canonical_trading_day(
                    argus_market_clock.JP_EQUITY, probe):
                return probe.isoformat(), flags
        return None, {"reason": "no_next_session_within_20d"}
    except argus_market_clock.CalendarUnavailableError:
        return None, {"reason": "calendar_unavailable"}


def _sho_earnings_event():
    """Latest ORIGINAL supported disclosure for the tracked universe as a
    PIT earnings event (corrections never overwrite the original's state)."""
    rows = _SHO_STATEMENTS_CACHE["rows"]
    if not rows:
        return None, _SHO_STATEMENTS_CACHE["source"]
    candidates = {}
    unrecognized = 0
    for row in rows:
        code = str(_stmt_field(row, "LocalCode", "Code", "code") or "")[:4]
        disclosed_date = str(_stmt_field(
            row, "DisclosedDate", "DiscDate", "disclosedDate") or "")[:10]
        disclosed_time = str(_stmt_field(
            row, "DisclosedTime", "DiscTime", "disclosedTime") or "")[:8]
        doc_type = str(_stmt_field(
            row, "TypeOfDocument", "DocType", "typeOfDocument") or "")
        period_end = str(_stmt_field(
            row, "CurrentPeriodEndDate", "CurPerEn", "CurPerEnDt",
            "currentPeriodEndDate") or "")[:10]
        if not (code and len(disclosed_date) == 10):
            unrecognized += 1
            continue
        identity = (code, doc_type, period_end)
        stamp = f"{disclosed_date}T{disclosed_time or '99:99'}"
        row_view = {"code": code, "disclosedDate": disclosed_date,
                    "disclosedTime": disclosed_time, "docType": doc_type,
                    "periodEnd": period_end, "raw": row, "stamp": stamp}
        current = candidates.get(identity)
        if current is None or stamp < current["stamp"]:
            # earliest disclosure for the identity = the ORIGINAL; later
            # rows for the same identity are corrections.
            if current is not None:
                row_view["correctionCount"] = (
                    current.get("correctionCount", 0) + 1)
            candidates[identity] = {**row_view,
                                    "correctionCount": row_view.get(
                                        "correctionCount",
                                        (current or {}).get(
                                            "correctionCount", 0))}
        else:
            current["correctionCount"] = current.get("correctionCount", 0) + 1
    if not candidates:
        return None, ("schema_unrecognized" if unrecognized
                      else "no_supported_disclosures")
    originals = sorted(candidates.values(), key=lambda c: c["stamp"])
    chosen = originals[-1]
    first_tradable, flags = _sho_first_tradable_session(
        chosen["disclosedDate"], chosen["disclosedTime"])
    if first_tradable is None:
        return None, f"first_session_{flags.get('reason', 'unknown')}"
    time_known = "publicationTimePrecision" not in flags
    if time_known:
        known_at = _canonical_truth_iso(
            f"{chosen['disclosedDate']}T{chosen['disclosedTime'] or '15:30:00'}+09:00",
            "JP")
    else:
        # date-only: conservatively knowable only from end of that day JST.
        known_at = _canonical_truth_iso(
            f"{chosen['disclosedDate']}T23:59:00+09:00", "JP")
    if not known_at:
        return None, "disclosure_timestamp_invalid"
    raw = chosen["raw"]
    eps_actual = _stmt_field(raw, "EarningsPerShare", "EPS", "Eps")
    try:
        eps_actual = float(eps_actual) if eps_actual is not None else None
    except (TypeError, ValueError):
        eps_actual = None
    reported = {}
    for out_key, names in (
            ("netSales", ("NetSales", "Sales")),
            ("operatingProfit", ("OperatingProfit", "OpProfit")),
            ("ordinaryProfit", ("OrdinaryProfit", "OrdProfit")),
            ("profit", ("Profit", "NetIncome")),
            ("forecastEps", ("ForecastEarningsPerShare", "FEPS", "FcstEPS")),
            ("forecastDividendAnnual",
             ("ForecastDividendPerShareAnnual", "FcstDivAnnual"))):
        value = _stmt_field(raw, *names)
        if value not in (None, ""):
            reported[out_key] = value
    event = {
        "instrumentId": chosen["code"],
        "date": first_tradable,               # reaction anchor session
        "knownAt": known_at,
        "availableFrom": known_at,
        "sourcePublishedAt": known_at,
        "fiscalPeriodEnd": chosen["periodEnd"] or None,
        "docType": chosen["docType"] or None,
        "epsActual": eps_actual,
        "epsEstimate": None,                  # no consensus dataset contracted
        "reportedFacts": reported or None,
        "correctionCountWithinWindow": chosen.get("correctionCount", 0),
        "provenance": "JQUANTS_FINS_STATEMENTS",
        **flags,
    }
    return event, "jquants_fins_statements"


def _sho_earnings_bars(symbol):
    """Complete OHLCV rows for the event instrument with per-bar PIT stamps
    (J-Quants daily publication ≈ evening; conservative 19:00 JST)."""
    rows = _chart_history_cached(str(symbol)[:4], "JP") or []
    out = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        date = str(row.get("date") or "")[:10]
        if len(date) != 10:
            continue
        values = {k: row.get(k) for k in
                  ("open", "high", "low", "close", "volume")}
        if any(not isinstance(v, (int, float)) or isinstance(v, bool)
               for v in values.values()):
            continue
        out.append({"instrumentId": str(symbol)[:4], "date": date,
                    **values,
                    "availableFrom": f"{date}T10:00:00Z"})
    out.sort(key=lambda r: r["date"])
    return out


def _sho_pit_inputs(*, warm=False):
    """Market-level SHO CORE inputs (D01-D07 + reversal axes).

    Cached-only on the public path; warm=True (collect cron) refreshes the
    underlying caches. sourceStatus names each feed's live state so a cold or
    key-less feed is visible instead of silently absent."""
    now = time.time()
    memo = _SHO_PIT_INPUT_MEMO
    if not warm and memo["data"] is not None and now - memo["ts"] < 120:
        return memo["data"]
    vix_rows, vix_source = _sho_vix_rows(fetch=warm)
    nikkei_rows = _yahoo_index_ohlcv(
        "^N225", "NIKKEI_225_INDEX", fetch=warm, available_hour_utc=7)
    try:
        credit_rows = _jpx_credit_rows_effective()
    except Exception:
        credit_rows = []
    margin_rows = _sho_margin_1570_rows(fetch=warm)
    rs_proxy = _sho_relative_strength_proxy()
    flow_rows = _sho_foreign_flow_rows()
    _sho_statements_rows(warm=warm)
    earnings_event, earnings_source = _sho_earnings_event()
    earnings_bars = (_sho_earnings_bars(earnings_event["instrumentId"])
                     if earnings_event else [])
    data = {
        "creditRows": credit_rows, "margin1570Rows": margin_rows,
        "rsProxy": rs_proxy, "flowRows": flow_rows,
        "vixRows": vix_rows, "nikkeiRows": nikkei_rows,
        "earningsEvent": earnings_event, "earningsBars": earnings_bars,
        "sourceStatus": {
            "credit": "csv_ledger" if credit_rows else "missing",
            "margin1570": "jquants_weekly" if margin_rows else "cold_cache",
            "relativeStrength": "etf_proxy_20d" if rs_proxy else "cold_cache",
            "foreignFlow": "market_ledger" if flow_rows else "missing",
            "vix": vix_source,
            "nikkei": "yahoo_ohlcv" if nikkei_rows else "cold_cache",
            "earnings": earnings_source,
        },
    }
    memo["ts"], memo["data"] = now, data
    return data


def _sho_market_view():
    """Document-level SHO MARKET VIEW projection (external review item A).

    The reviewer's central principle: MARKET VIEW belongs to SHO, ACTION
    belongs to SDA. This read-only consumer projection (D01-D07 family states
    + the two reversal axes) carries zero action authority by construction
    (project_today_sda_safe) and rides the decision-evidence document for the
    Today display. 120s memo keeps the public GET cheap."""
    now = time.time()
    memo = _SHO_MARKET_VIEW_MEMO
    if memo["view"] is not None and now - memo["ts"] < 120:
        return memo["view"]
    cutoff = _ai_now_iso()
    try:
        inputs = _sho_pit_inputs()
        evidence = argus_sho.evaluate_d01_d07(
            cutoff=cutoff, two_market_rows=inputs["creditRows"],
            margin_1570_rows=inputs["margin1570Rows"],
            relative_strength_proxy=inputs["rsProxy"],
            foreign_flow_rows=inputs["flowRows"],
            vix_rows=inputs["vixRows"],
            earnings_event=inputs.get("earningsEvent"),
            earnings_bars=inputs.get("earningsBars") or (),
            comparison_index_bars=inputs.get("nikkeiRows") or ())
        reversal = argus_sho.build_reversal_engine(
            cutoff=cutoff, analysis_instrument="NIKKEI_225_INDEX",
            downside_background="MIXED",
            nikkei_rows=inputs["nikkeiRows"], vix_rows=inputs["vixRows"])
        projection = argus_sho.project_today_sda_safe(
            cutoff=cutoff, evidence=evidence, reversal=reversal)
        view = {
            "schemaVersion": "argus-sho-market-view-v1",
            "informationCutoff": cutoff,
            "projection": projection,
            "sourceStatus": dict(inputs["sourceStatus"]),
            "actionAuthority": False,
            "automaticAiCalls": 0,
        }
    except Exception as exc:
        view = {
            "schemaVersion": "argus-sho-market-view-v1",
            "informationCutoff": cutoff, "projection": None,
            "sourceStatus": {
                "error": f"market_view_failed:{type(exc).__name__}"},
            "actionAuthority": False, "automaticAiCalls": 0,
        }
    memo["ts"], memo["view"] = now, view
    return view


def _decision_evidence_sho_artifact(symbol, cutoff):
    """Per-subject SHO reversal artifact from real PIT inputs (v13.5.36).

    Both reversal axes now evaluate production feeds (^N225/^VIX complete
    OHLCV); cold feeds leave factors MISSING and the axis DATA_GATED — the
    artifact reports absence, never fabricates it. Input assembly failure
    degrades to the zero-input artifact (fail closed), exactly the pre-wiring
    behavior. The downside background stays MIXED, the least-claiming state,
    until the downside layer is wired as a PIT input.
    """
    try:
        inputs = _sho_pit_inputs()
    except Exception:
        inputs = None
    try:
        return argus_sho.build_reversal_engine(
            cutoff=cutoff, analysis_instrument=symbol,
            downside_background="MIXED",
            nikkei_rows=(inputs or {}).get("nikkeiRows") or (),
            vix_rows=(inputs or {}).get("vixRows") or ()), None
    except (TypeError, ValueError) as exc:
        return None, f"sho_artifact_failed:{type(exc).__name__}"


def _build_decision_evidence_subject(symbol, market, cutoff, build_identity):
    subject = {"kind": "ASSET", "instrumentId": symbol, "market": market,
               "horizon": "FIVE_DAY"}
    reasons = {}
    market_artifact, market_reason = _decision_evidence_market_artifact(
        symbol, market, cutoff, build_identity)
    if market_reason:
        reasons["marketTruth"] = market_reason
    prediction_artifact = None
    if market_artifact is not None:
        prediction_artifact, prediction_reason = \
            _decision_evidence_prediction_artifact(
                symbol, market, cutoff, market_artifact, build_identity)
        if prediction_reason:
            reasons["predictionLedger"] = prediction_reason
    sho_artifact, sho_reason = _decision_evidence_sho_artifact(symbol, cutoff)
    if sho_reason:
        reasons["sho"] = sho_reason
    references = argus_single_decision.canonical_artifact_references(
        subject=subject, cutoff=cutoff,
        market_truth_artifact=market_artifact,
        prediction_ledger_artifact=prediction_artifact,
        sho_artifact=sho_artifact)
    failures = dict(references.get("verificationFailures") or {})
    failures.update(reasons)
    statuses = {key: references[key]["status"]
                for key in ("marketTruth", "predictionLedger", "sho")}
    all_available = all(value == "AVAILABLE" for value in statuses.values())
    if all_available:
        quality = {"status": "COMPLETE", "freshness": "FRESH",
                   "missingReasonCodes": [], "conflictReasonCodes": []}
    else:
        prefixes = {"marketTruth": "market_truth",
                    "predictionLedger": "prediction_ledger", "sho": "sho"}
        codes = sorted({f"{prefixes[key]}_{value.lower()}"
                        for key, value in statuses.items()
                        if value != "AVAILABLE"})
        market_status = statuses["marketTruth"]
        quality = {
            "status": ("PARTIAL" if any(v == "AVAILABLE"
                                        for v in statuses.values())
                       else "MISSING"),
            "freshness": ("FRESH" if market_status == "AVAILABLE"
                          else "STALE" if market_status == "STALE"
                          else "UNKNOWN"),
            "missingReasonCodes": codes,
            "conflictReasonCodes": [],
        }
    return {
        "subject": subject,
        "informationCutoffAt": cutoff,
        "marketTruth": references["marketTruth"],
        "predictionLedger": references["predictionLedger"],
        "sho": references["sho"],
        "shoBuyEligible": bool(references.get("shoBuyEligible")),
        "quality": quality,
        "verificationFailures": failures,
    }


def _tachibana_live_evidence():
    """v13.5.38: the Tachibana LIVE evidence document for the decision-evidence
    route.  Isolation: any failure inside the provider boundary degrades to a
    fixed, content-free UNAVAILABLE document so the product route survives."""
    try:
        return argus_tachibana_live.current_evidence_safe()
    except Exception as exc:
        return {
            "schemaVersion": argus_tachibana_live.SCHEMA,
            "provider": argus_tachibana_live.PROVIDER,
            "authority": argus_tachibana_live.AUTHORITY,
            "status": "UNAVAILABLE",
            "enabled": False, "shadowOnly": True, "authoritative": False,
            "executionCapability": False,
            "lastErrorClass": type(exc).__name__,
            "symbols": {}, "symbolCount": 0,
        }


def _decision_evidence_document(symbols):
    now = time.time()
    generated_at = _ai_now_iso()
    build_identity = _backend_exact_sha()
    jp_symbols = {str(s.get("symbol") or "").upper() for s in _JP_WATCHLIST}
    us_symbols = {str(s.get("symbol") or "").upper() for s in _US_WATCHLIST}
    # Public input hygiene: bounded symbol shape and a bounded cache. Expired
    # entries are pruned on every build so arbitrary query churn cannot grow
    # the dict without limit.
    for cached_symbol in list(_DECISION_EVIDENCE_CACHE):
        if now - _DECISION_EVIDENCE_CACHE[cached_symbol].get("ts", 0) \
                > _DECISION_EVIDENCE_TTL_SEC:
            _DECISION_EVIDENCE_CACHE.pop(cached_symbol, None)
    subjects = {}
    for sym in symbols:
        if not re.fullmatch(r"[A-Z0-9.]{1,12}", sym or ""):
            subjects[str(sym)[:24]] = {"status": "unsupported_symbol"}
            continue
        market = ("JP" if (sym in jp_symbols
                           or re.fullmatch(r"\d[0-9A-Z]{3}", sym))
                  else "US" if (sym in us_symbols or sym.isalpha()) else None)
        if market is None:
            subjects[sym] = {"status": "unsupported_symbol"}
            continue
        cached = _DECISION_EVIDENCE_CACHE.get(sym)
        if cached and now - cached.get("ts", 0) <= _DECISION_EVIDENCE_TTL_SEC:
            subjects[sym] = cached["entry"]
            continue
        cutoff = _ai_now_iso()
        if not build_identity:
            entry = {
                "subject": {"kind": "ASSET", "instrumentId": sym,
                            "market": market, "horizon": "FIVE_DAY"},
                "informationCutoffAt": cutoff,
                "marketTruth": dict(
                    argus_single_decision.MISSING_MARKET_TRUTH_REFERENCE),
                "predictionLedger": dict(
                    argus_single_decision.MISSING_PREDICTION_LEDGER_REFERENCE),
                "sho": {**dict(
                    argus_single_decision.MISSING_SHO_REFERENCE),
                    "primitiveFactorIds": [], "targets": []},
                "shoBuyEligible": False,
                "quality": {"status": "MISSING", "freshness": "UNKNOWN",
                            "missingReasonCodes": [
                                "market_truth_missing",
                                "prediction_ledger_missing",
                                "sho_missing"],
                            "conflictReasonCodes": []},
                "verificationFailures": {
                    "build": "build_identity_unavailable"},
            }
        else:
            try:
                entry = _build_decision_evidence_subject(
                    sym, market, cutoff, build_identity)
            except Exception as exc:
                entry = {
                    "subject": {"kind": "ASSET", "instrumentId": sym,
                                "market": market},
                    "informationCutoffAt": cutoff,
                    "marketTruth": dict(
                        argus_single_decision.MISSING_MARKET_TRUTH_REFERENCE),
                    "predictionLedger": dict(
                        argus_single_decision
                        .MISSING_PREDICTION_LEDGER_REFERENCE),
                    "sho": {**dict(
                        argus_single_decision.MISSING_SHO_REFERENCE),
                        "primitiveFactorIds": [], "targets": []},
                    "shoBuyEligible": False,
                    "quality": {"status": "MISSING", "freshness": "UNKNOWN",
                                "missingReasonCodes": [
                                    "market_truth_missing",
                                    "prediction_ledger_missing",
                                    "sho_missing"],
                                "conflictReasonCodes": []},
                    "verificationFailures": {
                        "build": f"evidence_build_failed:{type(exc).__name__}"},
                }
        if len(_DECISION_EVIDENCE_CACHE) < 64:
            _DECISION_EVIDENCE_CACHE[sym] = {"ts": now, "entry": entry}
        subjects[sym] = entry
    return {
        "schemaVersion": "argus-decision-evidence-v1",
        "generatedAt": generated_at,
        "automaticAiCalls": 0,
        "authority": "CANONICAL_ARTIFACT_REFERENCES",
        "sdaAuthority": False,
        "actionAuthority": False,
        # v13.5.36 (review item A): document-level SHO MARKET VIEW — display
        # projection only, never an SDA input; the per-subject references
        # above remain the sole decision evidence.
        "marketView": _sho_market_view(),
        # v13.5.38: Tachibana LIVE evidence (argus_tachibana_live) — provenance
        # TACHIBANA, SHADOW_NON_AUTHORITATIVE, bounded and secret-free.  A
        # disabled or failed sensor yields a truthful status, never an error,
        # and never an SDA input.
        "japaneseLive": _tachibana_live_evidence(),
        "subjects": subjects,
    }


@app.route("/api/argus/decision-evidence")
def api_argus_decision_evidence():
    """Canonical artifact references for the device-side SDA (read-only GET).

    Serves per-subject marketTruth / predictionLedger / sho reference dicts
    verified by argus_single_decision.canonical_artifact_references. Values are
    derived from already-cached quote/clock state only — this route performs no
    provider fetch, reads no owner data, and publishes no action.
    """
    raw = str(request.args.get("symbols") or "")
    requested = [part.strip().upper() for part in raw.split(",")
                 if part.strip()][:_DECISION_EVIDENCE_MAX_SYMBOLS]
    if not requested:
        requested = list(_DECISION_EVIDENCE_DEFAULT_SYMBOLS)
    # v13.5.60: identical symbol sets share one computation (single-flight).
    flight_key = "decision-evidence:" + ",".join(sorted(requested))
    started = time.time()
    document, mode = _single_flight(
        flight_key, lambda: _decision_evidence_document(requested))
    if mode == "busy":
        return _busy_response("decision-evidence", started)
    response = jsonify(document)
    response.headers["X-ARGUS-Compute-Mode"] = "read-only"
    response.headers["X-ARGUS-Elapsed-Ms"] = str(int((time.time() - started) * 1000))
    response.headers["X-ARGUS-Flight"] = mode
    return response


@app.route("/api/argus/admin/market-ledger/import", methods=["POST"])
def api_argus_admin_market_ledger_import():
    """Validated append-only CSV import. Dry-run is the default."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    body = request.get_json(silent=True) or {}
    now_iso = _ai_now_iso()
    try:
        if body.get("action") == "rollback":
            updated = argus_market_ledger.rollback_import(
                _MARKET_LEDGER, str(body.get("importId") or ""), now_iso)
            _MARKET_LEDGER.clear()
            _MARKET_LEDGER.update(updated)
            _journal("market_ledger_import_rolled_back", "market_ledger",
                     str(body.get("importId") or "unknown"),
                     {"stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER)},
                     origin="admin")
            _osint_persist()
            return jsonify({"ok": True, "status": "rolled_back",
                            "importId": body.get("importId"),
                            "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER)})
        rows = argus_market_ledger.parse_csv(str(body.get("csv") or ""))
        result = argus_market_ledger.import_rows(
            _MARKET_LEDGER, rows, now_iso=now_iso,
            dry_run=body.get("dryRun") is not False)
        if result["ok"] and not result["dryRun"]:
            _MARKET_LEDGER.clear()
            _MARKET_LEDGER.update(result.pop("state"))
            _journal("market_ledger_import_committed", "market_ledger",
                     result["importId"],
                     {"rowCount": len(result["preview"]),
                      "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER)},
                     origin="admin")
            _osint_persist()
        else:
            result.pop("state", None)
        return jsonify(result), (200 if result["ok"] else 400)
    except ValueError as exc:
        return jsonify({"ok": False, "error": str(exc)}), 400


def _jquants_paginated(
        path, params, max_pages=40, request_timeout=None):
    """Fetch a bounded J-Quants v2 dataset without exposing auth or raw bodies."""
    rows, cursor = [], None
    for _ in range(max_pages):
        query = dict(params or {})
        if cursor:
            query["pagination_key"] = cursor
        response = requests.get(
            f"{_JQUANTS_BASE}{path}", headers={"x-api-key": _JQUANTS_API_KEY},
            params=query, timeout=(
                _DIAG_TIMEOUT
                if request_timeout is None else float(request_timeout)))
        if response.status_code != 200:
            raise RuntimeError(f"jquants_http_{response.status_code}")
        body = response.json()
        if not isinstance(body, dict):
            raise RuntimeError("jquants_invalid_json")
        page = body.get("data") or []
        if not isinstance(page, list):
            raise RuntimeError("jquants_invalid_schema")
        rows.extend(x for x in page if isinstance(x, dict))
        next_cursor = body.get("pagination_key")
        if not next_cursor or next_cursor == cursor:
            return rows
        cursor = str(next_cursor)
    raise RuntimeError("jquants_pagination_limit")


def _foundation_job(job_id):
    return next((x for x in _FOUNDATION_JOBS.get("jobs", [])
                 if x.get("jobId") == job_id), None)


def _foundation_job_update(job_id, *, status=None, progress=None,
                           checkpoint=None, result=None, error_class=None,
                           persist=True):
    global _FOUNDATION_JOBS
    with _FOUNDATION_JOB_LOCK:
        updated = argus_foundation_jobs.update_job(
            _FOUNDATION_JOBS, job_id, now_iso=_ai_now_iso(), status=status,
            progress=progress, checkpoint=checkpoint, result=result,
            error_class=error_class)
        _FOUNDATION_JOBS.clear()
        _FOUNDATION_JOBS.update(updated)
        row = _foundation_job(job_id)
    _foundation_jobs_persist()
    if persist:
        _osint_persist()
    return row


def _jquants_secure_page(path, params, *, proof, max_attempts=4):
    """Secret-safe J-Quants V2 request with bounded 429/5xx recovery."""
    query = argus_foundation_jobs.normalize_jquants_query(params)
    safe_query = {str(k): ("[present]" if k == "pagination_key" else v)
                  for k, v in query.items()}
    last_class = "request_failed"
    for attempt in range(1, max_attempts + 1):
        started = _ai_now_iso()
        started_monotonic = time.monotonic()
        try:
            # One foundation job is active at a time; retain an explicit,
            # configurable request floor so a historical run never becomes an
            # unbounded burst even when every response is successful.
            try:
                minimum_interval = max(0.0, min(5.0, float(os.environ.get(
                    "JQUANTS_FOUNDATION_MIN_REQUEST_INTERVAL_SECONDS", "0.35"))))
            except (TypeError, ValueError):
                minimum_interval = 0.35
            previous_at = getattr(_jquants_secure_page, "_last_request_at", 0.0)
            remaining = minimum_interval - (time.monotonic() - previous_at)
            if remaining > 0:
                time.sleep(remaining)
            response = requests.get(
                f"{_JQUANTS_BASE}{path}",
                headers={"x-api-key": _JQUANTS_API_KEY}, params=query,
                timeout=30)
            _jquants_secure_page._last_request_at = time.monotonic()
            response_headers = getattr(response, "headers", {}) or {}
            request_id = (response_headers.get("x-request-id")
                          or response_headers.get("x-amzn-requestid"))
            content_type = str(response_headers.get("content-type") or "").split(";")[0]
            request_proof = {"endpoint": path, "method": "GET",
                             "query": safe_query, "apiVersion": "v2",
                             "dateFormat": ("YYYYMMDD" if any(
                                 k in safe_query for k in ("date", "from", "to"))
                                            else None),
                             "codePresent": bool(query.get("code")),
                             "httpStatus": response.status_code,
                             "requestId": request_id,
                             "contentType": content_type or None,
                             "elapsedMs": round((time.monotonic()
                                                 - started_monotonic) * 1000, 2),
                             "attempt": attempt, "lastRequestAt": started,
                             "rateLimit": {
                                 "limit": response_headers.get("x-ratelimit-limit"),
                                 "remaining": response_headers.get(
                                     "x-ratelimit-remaining"),
                                 "reset": response_headers.get("x-ratelimit-reset"),
                                 "retryAfter": (response_headers.get("retry-after")
                                                or response_headers.get(
                                                    "Retry-After"))},
                             "secretConfigured": bool(_JQUANTS_API_KEY)}
            proof.update(request_proof)
            proof.setdefault("endpointSummary", {})[path] = dict(request_proof)
            if response.status_code == 200:
                try:
                    body = response.json()
                except ValueError as exc:
                    raise RuntimeError("jquants_invalid_json") from exc
                if not isinstance(body, dict) or not isinstance(body.get("data"), list):
                    raise RuntimeError("jquants_invalid_schema")
                proof.update({"errorClass": None,
                              "responseErrorCode": None,
                              "responseErrorMessage": None,
                              "planEntitlementError": False,
                              "lastSuccessfulRequestAt": _ai_now_iso()})
                proof["endpointSummary"][path].update({
                    "errorClass": None, "rows": len(body.get("data") or []),
                    "paginationKeyPresent": bool(body.get("pagination_key")),
                    "paginationKeyHash": (hashlib.sha256(str(
                        body.get("pagination_key")).encode()).hexdigest()[:16]
                        if body.get("pagination_key") else None),
                    "responseSchema": sorted(str(k) for k in body.keys()),
                    "lastSuccessfulRequestAt": proof["lastSuccessfulRequestAt"]})
                return body
            error_code = error_message = None
            try:
                error_body = response.json()
            except (ValueError, TypeError):
                error_body = None
            if isinstance(error_body, dict):
                error_code = (error_body.get("code") or error_body.get("errorCode")
                              or error_body.get("error_code"))
                raw_message = (error_body.get("message") or error_body.get("detail")
                               or error_body.get("error"))
                if isinstance(raw_message, dict):
                    error_code = error_code or raw_message.get("code")
                    raw_message = raw_message.get("message")
                if raw_message is not None:
                    error_message = str(raw_message)[:240]
            error_meta = {"responseErrorCode": (str(error_code)[:80]
                                                  if error_code is not None else None),
                          "responseErrorMessage": error_message,
                          "planEntitlementError": bool(
                              response.status_code == 403 or any(
                                  word in str(error_message or "").lower()
                                  for word in ("plan", "entitlement", "subscription")))}
            proof.update(error_meta)
            proof["endpointSummary"][path].update(error_meta)
            if response.status_code in (401, 403):
                raise RuntimeError(f"jquants_http_{response.status_code}")
            if response.status_code == 429 or 500 <= response.status_code < 600:
                last_class = f"jquants_http_{response.status_code}"
                if attempt < max_attempts:
                    wait = argus_foundation_jobs.bounded_backoff_seconds(
                        attempt, response_headers.get("Retry-After"),
                        f"{path}:{safe_query}:{attempt}")
                    time.sleep(wait)
                    continue
            raise RuntimeError(f"jquants_http_{response.status_code}")
        except requests.RequestException as exc:
            last_class = type(exc).__name__
            if attempt < max_attempts:
                time.sleep(argus_foundation_jobs.bounded_backoff_seconds(
                    attempt, seed=f"{path}:{safe_query}:{attempt}"))
                continue
        except RuntimeError:
            raise
    proof["errorClass"] = last_class[:80]
    raise RuntimeError(last_class)


def _jquants_secure_rows(path, params, *, proof, max_pages=200):
    rows, cursor = [], None
    for page in range(max_pages):
        query = dict(params or {})
        if cursor:
            query["pagination_key"] = cursor
        body = _jquants_secure_page(path, query, proof=proof)
        rows.extend(x for x in body.get("data", []) if isinstance(x, dict))
        next_cursor = body.get("pagination_key")
        if next_cursor:
            token_hash = hashlib.sha256(str(next_cursor).encode()).hexdigest()[:16]
            hashes = proof.setdefault("paginationTokenHashes", [])
            if token_hash not in hashes:
                hashes.append(token_hash)
        if not next_cursor or str(next_cursor) == str(cursor):
            proof["rows"] = len(rows)
            proof["pages"] = page + 1
            proof["paginationObserved"] = bool(
                proof.get("paginationTokenHashes"))
            return rows
        cursor = str(next_cursor)
    raise RuntimeError("jquants_pagination_limit")


def _jquants_calendar_dates(start_date, end_date, proof):
    rows = []
    # The production entitlement probe proves this endpoint with a seven-day
    # window.  Longer historical windows can return HTTP 400 even on the Premium
    # plan, so reuse that provider-confirmed contract instead of guessing a
    # larger range. Pagination is still followed within every bounded window.
    cursor = datetime.strptime(start_date, "%Y-%m-%d")
    end = datetime.strptime(end_date, "%Y-%m-%d")
    while cursor <= end:
        window_end = min(cursor + timedelta(days=6), end)
        frm = cursor.strftime("%Y-%m-%d")
        to = window_end.strftime("%Y-%m-%d")
        rows.extend(_jquants_secure_rows(
            "/markets/calendar", {"from": frm, "to": to}, proof=proof))
        cursor = window_end + timedelta(days=1)
    return argus_foundation_jobs.trading_dates(rows, start=start_date, end=end_date)


def _jquants_discover_entitlement_start(as_of_date, proof):
    """Find the first provider-accessible trading day at the rolling boundary."""
    boundary = argus_foundation_jobs.rolling_entitlement_start(as_of_date)
    cursor = datetime.strptime(boundary, "%Y-%m-%d")
    for offset in range(15):
        candidate = (cursor + timedelta(days=offset)).strftime("%Y-%m-%d")
        try:
            rows = _jquants_secure_rows(
                "/equities/bars/daily", {"date": candidate}, proof=proof,
                max_pages=200)
        except RuntimeError:
            if proof.get("planEntitlementError") is True:
                continue
            raise
        rows = _jquants_exact_date_rows(rows, candidate)
        if rows:
            proof["rollingCalendarBoundary"] = boundary
            proof["oldestSuccessfulDate"] = candidate
            return candidate, rows
    raise RuntimeError("jquants_entitlement_boundary_not_found")


def _jquants_discover_production_start(as_of_date, proof):
    """Find the first official session in the rolling five-year core window."""
    boundary = argus_foundation_jobs.production_calendar_start(as_of_date)
    cursor = datetime.strptime(boundary, "%Y-%m-%d")
    for offset in range(15):
        candidate = (cursor + timedelta(days=offset)).strftime("%Y-%m-%d")
        rows = _jquants_exact_date_rows(_jquants_secure_rows(
            "/equities/bars/daily", {"date": candidate}, proof=proof,
            max_pages=200), candidate)
        if rows:
            proof["productionCalendarBoundary"] = boundary
            proof["productionFiveYearStartDate"] = candidate
            return candidate, rows
    raise RuntimeError("jquants_production_boundary_not_found")


def _jquants_official_client_test(params):
    """Run the same request through J-Quants' official V2 client, secret-safe."""
    started = time.monotonic()
    result = {"client": "jquants-api-client", "clientVersion": None,
              "status": "failed", "rows": 0, "elapsedMs": None,
              "httpStatus": None, "contentType": None, "requestId": None,
              "errorClass": None, "responseErrorCode": None,
              "responseErrorMessage": None}
    try:
        import jquantsapi
        result["clientVersion"] = getattr(jquantsapi, "__version__", None)
        client = jquantsapi.ClientV2(api_key=_JQUANTS_API_KEY)
        official_params = {}
        if params.get("code"):
            official_params["code"] = str(params["code"])
        if params.get("date"):
            official_params["date_yyyymmdd"] = str(params["date"])
        if params.get("from"):
            official_params["from_yyyymmdd"] = str(params["from"])
        if params.get("to"):
            official_params["to_yyyymmdd"] = str(params["to"])
        frame = client.get_eq_bars_daily(**official_params)
        result.update({"status": "success", "rows": len(frame),
                       "httpStatus": 200,
                       "responseSchema": [str(x) for x in getattr(
                           frame, "columns", [])]})
    except Exception as exc:
        result["errorClass"] = type(exc).__name__[:80]
        response = getattr(exc, "response", None)
        if response is not None:
            result["httpStatus"] = getattr(response, "status_code", None)
            headers = getattr(response, "headers", {}) or {}
            result["contentType"] = str(headers.get("content-type") or "").split(";")[0] or None
            result["requestId"] = (headers.get("x-request-id")
                                   or headers.get("x-amzn-requestid"))
            try:
                body = response.json()
            except (ValueError, TypeError):
                body = None
            if isinstance(body, dict):
                result["responseErrorCode"] = str(
                    body.get("code") or body.get("errorCode")
                    or body.get("error_code") or "")[:80] or None
                message = body.get("message") or body.get("detail")
                if message is not None:
                    result["responseErrorMessage"] = str(message)[:240]
    finally:
        result["elapsedMs"] = round((time.monotonic() - started) * 1000, 2)
    return result


def _jquants_index_audit():
    """Secret-safe, read-only audit of the official J-Quants V2 index APIs."""
    result = {
        "status": "failed",
        "provider": "J-Quants",
        "providerConfigured": bool(_JQUANTS_API_KEY),
        "credentialLengthPositive": bool(len(_JQUANTS_API_KEY or "") > 0),
        "client": "jquants-api-client",
        "clientVersion": None,
        "baseUrl": "https://api.jquants.com/v2",
        "genericIndexEndpoint": "/indices/bars/daily",
        "topixEndpoint": "/indices/bars/daily/topix",
        "httpStatus": None,
        "requestId": None,
        "errorClass": None,
        "generic": None,
        "topix": None,
        "nikkeiIdentityStatus": "unverified",
        "officialCloseComparison": "not_performed_identity_unverified",
        "rawRowsPersisted": False,
        "ownerHoldingsTransmitted": False,
        "licenseAudit": {
            "dataAccessEntitlement": "Light_or_higher",
            "publicDisplayRight": "unverified",
            "nonDisplayProcessingRight": "unverified",
            "redistributionRight": "unverified",
            "decision": "keep_1321_etf_proxy",
        },
    }
    if not _JQUANTS_API_KEY:
        result["errorClass"] = "configured_in_other_runtime_or_missing"
        return result
    try:
        import jquantsapi
        result["clientVersion"] = getattr(jquantsapi, "__version__", None)
        client = jquantsapi.ClientV2(api_key=_JQUANTS_API_KEY)
        now_jst = datetime.now(TZ_JST)
        end = now_jst.strftime("%Y%m%d")
        start = (now_jst - timedelta(days=21)).strftime("%Y%m%d")
        # Without an index code the generic endpoint accepts a single date,
        # not an all-indices date range. Walk back over at most one week so
        # weekends/holidays do not turn a read-only audit into a false failure.
        generic = None
        generic_probe_date = None
        for offset in range(1, 8):
            probe_date = (now_jst - timedelta(days=offset)).strftime("%Y%m%d")
            candidate = client.get_idx_bars_daily(date_yyyymmdd=probe_date)
            generic = candidate
            if len(candidate):
                generic_probe_date = probe_date
                break
        topix = client.get_idx_bars_daily_topix(
            from_yyyymmdd=start, to_yyyymmdd=end)

        def _frame_audit(frame):
            columns = [str(column) for column in getattr(frame, "columns", [])]
            rows = int(len(frame))
            latest_date = None
            if rows and "Date" in columns:
                latest_date = str(frame["Date"].max())[:10]
            codes = []
            if rows and "Code" in columns:
                codes = sorted({str(value) for value in frame["Code"].dropna().tolist()})[:100]
            name_columns = [column for column in columns
                            if "name" in column.lower() or column.lower().endswith("nm")]
            names = []
            for column in name_columns:
                names.extend(str(value)[:100] for value in
                             frame[column].dropna().drop_duplicates().tolist()[:100])
            return {
                "rows": rows, "columns": columns, "latestDate": latest_date,
                "availableCodes": codes, "availableNames": sorted(set(names))[:100],
                "ohlcFieldsPresent": all(column in columns for column in ("O", "H", "L", "C")),
            }

        generic_audit = _frame_audit(generic)
        topix_audit = _frame_audit(topix)
        result["generic"] = generic_audit
        result["genericProbeDate"] = generic_probe_date
        result["topix"] = topix_audit
        nikkei_names = [name for name in generic_audit["availableNames"]
                         if "nikkei" in name.lower() or "日経" in name]
        result["nikkeiIdentityStatus"] = (
            "named_candidate_present" if nikkei_names else
            "not_identifiable_from_response_schema"
        )
        result["nikkeiNamedCandidates"] = nikkei_names
        result["status"] = "success"
        result["httpStatus"] = 200
    except Exception as exc:
        result["errorClass"] = type(exc).__name__[:80]
        response = getattr(exc, "response", None)
        if response is not None:
            result["httpStatus"] = getattr(response, "status_code", None)
            headers = getattr(response, "headers", {}) or {}
            result["requestId"] = (headers.get("x-request-id")
                                   or headers.get("x-amzn-requestid"))
    return result


@app.route("/api/argus/admin/jquants/index-audit", methods=["POST"])
def api_argus_admin_jquants_index_audit():
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    result = _jquants_index_audit()
    return jsonify(result), (200 if result.get("status") == "success" else 503)


def _jquants_request_matrix_worker(job_id):
    """Execute the frozen five-case V2 matrix without persisting provider rows."""
    try:
        _foundation_job_update(job_id, status="running")
        if not _JQUANTS_API_KEY:
            raise RuntimeError("jquants_not_configured_in_runtime")
        today = datetime.now(TZ_JST).strftime("%Y-%m-%d")
        recent_start = (datetime.now(TZ_JST) - timedelta(days=14)).strftime("%Y-%m-%d")
        calendar_proof = {}
        recent_dates = _jquants_calendar_dates(recent_start, today, calendar_proof)
        recent = None
        for candidate in reversed(recent_dates):
            recent_probe = {}
            recent_rows = _jquants_secure_rows(
                "/equities/bars/daily", {"code": "72030", "date": candidate},
                proof=recent_probe, max_pages=10)
            if recent_rows:
                recent = candidate
                break
        if not recent:
            raise RuntimeError("jquants_recent_confirmed_date_not_found")
        recent_compact = argus_foundation_jobs.normalize_jquants_query(
            {"date": recent})["date"]
        boundary_proof = {}
        entitlement_start, _ = _jquants_discover_entitlement_start(
            today, boundary_proof)
        entitlement_compact = argus_foundation_jobs.normalize_jquants_query(
            {"date": entitlement_start})["date"]
        cases = [
            ("official_sample", {"code": "86970", "date": "20230324"}),
            ("recent_confirmed_trading_day",
             {"code": "72030", "date": recent_compact}),
            ("entitlement_boundary_with_code",
             {"code": "72030", "date": entitlement_compact}),
            ("entitlement_boundary_date_only", {"date": entitlement_compact}),
            ("official_code_range",
             {"code": "86970", "from": "20230324", "to": "20230327"}),
        ]
        matrix = []
        for name, params in cases:
            direct_proof = {}
            direct = {"client": "argus-v2", "status": "failed", "rows": 0}
            try:
                rows = _jquants_secure_rows(
                    "/equities/bars/daily", params, proof=direct_proof,
                    max_pages=200)
                direct.update({"status": "success", "rows": len(rows)})
            except RuntimeError as exc:
                direct["errorClass"] = str(exc)[:80]
            direct.update({k: direct_proof.get(k) for k in (
                "endpoint", "method", "query", "dateFormat", "codePresent",
                "httpStatus", "requestId", "contentType", "elapsedMs",
                "responseErrorCode", "responseErrorMessage",
                "planEntitlementError", "pages")})
            endpoint = (direct_proof.get("endpointSummary") or {}).get(
                "/equities/bars/daily", {})
            direct["paginationKeyPresent"] = endpoint.get("paginationKeyPresent")
            direct["responseSchema"] = endpoint.get("responseSchema")
            matrix.append({"test": name, "params": dict(params),
                           "direct": direct,
                           "officialClient": _jquants_official_client_test(params)})
        direct_ok = all(x["direct"].get("status") == "success" for x in matrix)
        official_ok = all(x["officialClient"].get("status") == "success"
                          for x in matrix)
        old_ok = (matrix[2]["direct"].get("status") == "success"
                  and matrix[3]["direct"].get("status") == "success"
                  and int(matrix[3]["direct"].get("rows") or 0) > 0)
        result = {"status": ("verified" if direct_ok and official_ok else "diagnosed"),
                  "matrix": matrix, "recentConfirmedTradingDay": recent,
                  "directClientAllSuccessful": direct_ok,
                  "officialClientAllSuccessful": official_ok,
                  "oldestRequiredDateAccessible": old_ok,
                  "entitlementPlan": argus_foundation_jobs.ENTITLEMENT_PLAN,
                  "entitlementStartDate": entitlement_start,
                  "rollingCalendarBoundary": boundary_proof.get(
                      "rollingCalendarBoundary"),
                  "entitlementPolicy": "rolling_10_years",
                  "rootCause": ("standard_entitlement_boundary_confirmed"
                                if old_ok else "request_or_provider_rejection_persists"),
                  "correctedDateFormat": "YYYYMMDD",
                  "rawProviderRowsPersisted": False}
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        _foundation_job_update(job_id, status="failed",
                               error_class=error_class[:80])


def _breadth_commit_rows(rows, now_iso):
    existing = {(x.get("seriesId"), x.get("periodEnd"), x.get("availableFrom"),
                 x.get("value")) for x in (_MARKET_LEDGER.get("observations") or [])
                if isinstance(x, dict)}
    candidates = [x for x in rows if
                  (x.get("seriesId"), x.get("periodEnd"), x.get("availableFrom"),
                   x.get("value")) not in existing]
    if not candidates:
        return 0, 0, len(rows)
    prior_periods = {(x.get("seriesId"), x.get("periodEnd")) for x in
                     (_MARKET_LEDGER.get("observations") or [])
                     if isinstance(x, dict)}
    revisions = sum(1 for x in candidates if
                    (x.get("seriesId"), x.get("periodEnd")) in prior_periods)
    result = argus_market_ledger.import_rows(
        _MARKET_LEDGER, candidates, now_iso=now_iso, dry_run=False,
        rebuild_after_commit=False)
    if not result.get("ok"):
        errors = result.get("errors") or []
        raise RuntimeError(str((errors[0] if errors else {}).get("error")
                               or "breadth_import_failed"))
    _MARKET_LEDGER.clear()
    _MARKET_LEDGER.update(result.pop("state"))
    return len(candidates), revisions, len(rows) - len(candidates)


def _jquants_row_date(row):
    raw = str((row or {}).get("Date") or (row or {}).get("date") or "")
    digits = "".join(ch for ch in raw if ch.isdigit())[:8]
    if len(digits) != 8:
        return None
    return f"{digits[:4]}-{digits[4:6]}-{digits[6:8]}"


def _jquants_exact_date_rows(rows, date_text):
    """Fail closed when a date-filtered endpoint returns another session."""
    return [row for row in (rows or [])
            if _jquants_row_date(row) == str(date_text)[:10]]


def _breadth_daily_matches(effective, daily):
    """Compare one official recalculation with the current effective ledger."""
    date_text = str((daily or {}).get("date") or "")[:10]
    for universe_id, row in (daily.get("universes") or {}).items():
        if not argus_foundation_jobs.universe_active(universe_id, date_text):
            continue
        short = argus_foundation_jobs.UNIVERSES[universe_id]["short"]
        for name in ("advancers", "decliners", "unchanged", "unavailable"):
            stored = next((value for value in effective.get(
                f"breadth.{short}.{name}", [])
                if value.get("periodEnd") == date_text), None)
            if not stored or stored.get("value") != row["counts"].get(name):
                return False
    return True


def _breadth_reconciliation_candidates(effective, rows, correction_at):
    """Append current corrections even when the same value exists historically."""
    candidates = []
    for row in rows:
        series_id = str(row.get("seriesId") or "")
        period_end = str(row.get("periodEnd") or "")
        current = next((value for value in effective.get(series_id, [])
                        if value.get("periodEnd") == period_end), None)
        if current and current.get("value") == row.get("value"):
            continue
        revised = dict(row)
        revised["availableFrom"] = correction_at
        revised["observedAt"] = correction_at
        revised["metadata"] = {
            **dict(row.get("metadata") or {}),
            "reconciliation": "official_spot_check",
            "correctsAvailableFrom": (current or {}).get("availableFrom"),
        }
        candidates.append(revised)
    return candidates


def _scope_breadth_worker_ledger(production_start):
    """Release archive/non-breadth rows before the child performs a rebuild."""
    rows = [row for row in (_MARKET_LEDGER.get("observations") or [])
            if str(row.get("seriesId") or "").startswith("breadth.")
            and str(row.get("periodEnd") or "") >= production_start]
    scoped = argus_market_ledger.empty_state()
    scoped["observations"] = rows
    scoped["derivedStateDirty"] = True
    scoped["lastUpdatedAt"] = _MARKET_LEDGER.get("lastUpdatedAt")
    excluded = len(_MARKET_LEDGER.get("observations") or []) - len(rows)
    _MARKET_LEDGER.clear()
    _MARKET_LEDGER.update(scoped)
    gc.collect()
    return excluded


def _breadth_worker_seed_state(job_id):
    """Build the minimum restart-safe seed for a clean spawned worker.

    A fork inherits the Web process allocator arenas even after archive rows are
    released.  The spawned worker receives only breadth inputs around the
    rolling production window, so its memory limit measures worker data rather
    than the already-restored Web heap.
    """
    job = _foundation_job(job_id) or {}
    params = job.get("parameters") or {}
    end_date = str(params.get("to") or
                   datetime.now(TZ_JST).strftime("%Y-%m-%d"))[:10]
    production_boundary = argus_foundation_jobs.production_calendar_start(
        end_date)
    seed_boundary = (datetime.strptime(production_boundary, "%Y-%m-%d")
                     - timedelta(days=14)).strftime("%Y-%m-%d")
    seed = argus_market_ledger.empty_state()
    seed["observations"] = [row for row in
                            (_MARKET_LEDGER.get("observations") or [])
                            if str(row.get("seriesId") or "").startswith(
                                "breadth.")
                            and str(row.get("periodEnd") or "") >= seed_boundary]
    seed["rolledBackImports"] = list(
        _MARKET_LEDGER.get("rolledBackImports") or [])
    seed["derivedStateDirty"] = True
    seed["lastUpdatedAt"] = _MARKET_LEDGER.get("lastUpdatedAt")
    return seed


def _jquants_breadth_finalize_worker(job_id):
    """Correct the current boundary and verify the complete durable ledger."""
    proof = {"provider": "J-Quants", "baseUrl": _JQUANTS_BASE,
             "authentication": "x-api-key", "secretConfigured": bool(_JQUANTS_API_KEY),
             "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
             "contractScope": argus_foundation_jobs.PRODUCTION_SCOPE,
             "entitlementPolicy": argus_foundation_jobs.ENTITLEMENT_POLICY,
             "apiVersion": "v2",
             "finalizeOnly": True, "errorClass": None}
    try:
        _foundation_job_update(job_id, status="running",
                               checkpoint={"providerProof": proof})
        if not _JQUANTS_API_KEY:
            raise RuntimeError("jquants_not_configured_in_runtime")
        end_date = datetime.now(TZ_JST).strftime("%Y-%m-%d")
        entitlement_start, _ = _jquants_discover_entitlement_start(end_date, proof)
        calendar_start = (datetime.strptime(end_date, "%Y-%m-%d")
                          - timedelta(days=45)).strftime("%Y-%m-%d")
        calendar_dates = _jquants_calendar_dates(calendar_start, end_date, proof)
        live_bars = {}
        latest_confirmed = None
        for date_text in reversed(calendar_dates):
            rows = _jquants_secure_rows(
                "/equities/bars/daily", {"date": date_text}, proof=proof,
                max_pages=200)
            exact = _jquants_exact_date_rows(rows, date_text)
            if exact:
                latest_confirmed = date_text
                live_bars[date_text] = exact
                break
        if not latest_confirmed:
            raise RuntimeError("jquants_recent_confirmed_date_not_found")
        production_start, _ = _jquants_discover_production_start(
            latest_confirmed, proof)
        scope = argus_foundation_jobs.production_scope_metadata(
            latest_confirmed_date=latest_confirmed,
            production_start_date=production_start,
            entitlement_start_date=entitlement_start)

        # Preserve bad provider rows append-only, but supersede them with an
        # explicit exclusion revision proven by the official trading calendar.
        raw_rows = [row for row in (_MARKET_LEDGER.get("observations") or [])
                    if str(row.get("seriesId") or "").startswith("breadth.")]
        raw_latest = {}
        for row in raw_rows:
            key = (str(row.get("seriesId")), str(row.get("periodEnd")))
            if key not in raw_latest or int(row.get("revision") or 0) >= int(
                    raw_latest[key].get("revision") or 0):
                raw_latest[key] = row
        correction_at = _ai_now_iso()
        corrections = []
        for (series_id, period_end), row in raw_latest.items():
            if period_end <= latest_confirmed or (row.get("metadata") or {}).get(
                    "excludeFromEffective"):
                continue
            corrections.append({
                "seriesId": series_id, "periodEnd": period_end,
                "publishedAt": correction_at, "availableFrom": correction_at,
                "observedAt": correction_at, "value": None,
                "unit": row.get("unit") or argus_market_ledger.SERIES[series_id][0],
                "source": "J-Quants official trading calendar correction",
                "sourceKind": row.get("sourceKind") or "official",
                "status": "missing", "metadata": {
                    "excludeFromEffective": True,
                    "correctionReason": "non_trading_date_response",
                    "latestConfirmedTradingDate": latest_confirmed}})
        corrected_rows = 0
        if corrections:
            corrected_rows, _, _ = _breadth_commit_rows(corrections, correction_at)

        archive_excluded = _scope_breadth_worker_ledger(production_start)
        rebuilt = argus_market_ledger.rebuild(_MARKET_LEDGER, _ai_now_iso())
        _MARKET_LEDGER.clear()
        _MARKET_LEDGER.update(rebuilt)
        effective = argus_market_ledger.latest_by_series(
            _MARKET_LEDGER, _ai_now_iso())

        # Independent live recalculation: seed with one prior session, then
        # compare the following ten official sessions to the durable rows.
        # Adjusted historical bars can be revised for corporate actions.  Such
        # differences are appended as new official revisions, never overwritten.
        spot_dates = [day for day in calendar_dates
                      if day <= latest_confirmed][-11:]
        if len(spot_dates) != 11:
            raise RuntimeError("breadth_spot_check_dates_insufficient")
        previous = {}
        spot_daily = []
        reconciliation_rows = []
        for index, date_text in enumerate(spot_dates):
            bars = live_bars.get(date_text)
            if bars is None:
                bars = _jquants_exact_date_rows(_jquants_secure_rows(
                    "/equities/bars/daily", {"date": date_text}, proof=proof,
                    max_pages=200), date_text)
            master = _jquants_secure_rows(
                "/equities/master", {"date": date_text}, proof=proof,
                max_pages=100)
            if not bars or not master:
                raise RuntimeError("breadth_spot_check_provider_empty")
            daily = argus_foundation_jobs.calculate_daily(
                date=date_text, master_rows=master, bar_rows=bars,
                previous_adjusted_closes=previous)
            previous = daily["nextAdjustedCloses"]
            if index == 0:
                continue
            spot_daily.append(daily)
            reconciliation_rows.extend(argus_foundation_jobs.ledger_candidates(
                daily, calculated_at=_ai_now_iso(),
                entitlement_start_date=entitlement_start,
                production_start_date=production_start,
                latest_confirmed_date=latest_confirmed))
            topix_row = next((row for row in bars if str(
                row.get("Code") or row.get("code") or "").startswith("1306")), None)
            if topix_row and topix_row.get("AdjC") is not None:
                try:
                    topix_close = float(topix_row["AdjC"])
                    if topix_close > 0:
                        reconciliation_rows.append({
                            "seriesId": "breadth.topixProxyClose",
                            "periodEnd": date_text,
                            "publishedAt": f"{date_text}T17:00:00+09:00",
                            "availableFrom": f"{date_text}T17:00:00+09:00",
                            "observedAt": _ai_now_iso(), "value": topix_close,
                            "unit": "JPY", "source": (
                                "J-Quants V2 1306 adjusted close reconciliation"),
                            "sourceKind": "derived", "status": "live",
                            "metadata": {
                                "instrument": "1306 TOPIX-linked ETF proxy",
                                "officialIndexValue": False,
                                "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
                                "entitlementStartDate": entitlement_start,
                                "methodVersion": argus_foundation_jobs.METHOD_VERSION,
                                "reconciliation": "official_spot_check"}})
                except (TypeError, ValueError):
                    pass

        reconciled_rows, reconciliation_revisions = 0, 0
        if not all(_breadth_daily_matches(effective, daily)
                   for daily in spot_daily):
            correction_at = _ai_now_iso()
            reconciliation_rows = _breadth_reconciliation_candidates(
                effective, reconciliation_rows, correction_at)
            reconciled_rows, reconciliation_revisions, _ = _breadth_commit_rows(
                reconciliation_rows, correction_at)
            if reconciled_rows:
                rebuilt = argus_market_ledger.rebuild(
                    _MARKET_LEDGER, _ai_now_iso())
                _MARKET_LEDGER.clear()
                _MARKET_LEDGER.update(rebuilt)
                effective = argus_market_ledger.latest_by_series(
                    _MARKET_LEDGER, _ai_now_iso())
        spot_checks = [{"date": daily.get("date"),
                        "matches": _breadth_daily_matches(effective, daily)}
                       for daily in spot_daily]

        topix_prices = [{"date": row.get("periodEnd"), "close": row.get("value"),
                         "availableFrom": row.get("availableFrom")}
                        for row in effective.get("breadth.topixProxyClose", [])
                        if row.get("value") is not None
                        and str(row.get("periodEnd") or "") >= production_start]
        points = [row for row in (_MARKET_LEDGER.get("turningPoints") or [])
                  if row.get("ruleId") == "BREADTH_TURN"
                  and str(row.get("effectiveFrom") or "") >= production_start
                  and str(row.get("effectiveFrom") or "") <= latest_confirmed]
        backtests = {}
        for universe in ("first_section", "prime", "all"):
            universe_points = [row for row in points if str(
                row.get("direction") or "").startswith(universe + ":")]
            evaluated = argus_market_intelligence.walk_forward_backtest(
                universe_points, topix_prices)
            summary = {key: evaluated.get(key) for key in (
                "hitRate5d", "falsePositiveRate5d", "confidenceInterval95",
                "average1dPct", "average5dPct", "average20dPct",
                "maxRisePct", "maxDrawdownPct", "noFutureLeakage")}
            record = {"id": "bt-" + hashlib.sha256(json.dumps({
                          "universe": universe,
                          "methodVersion": evaluated.get("methodVersion"),
                          "signalIds": [row.get("id") for row in universe_points],
                          "topixFrom": (topix_prices[0]["date"] if topix_prices else None),
                          "topixTo": (topix_prices[-1]["date"] if topix_prices else None),
                          "summary": summary}, sort_keys=True).encode()).hexdigest()[:20],
                      "ruleId": "BREADTH_TURN", "universe": universe,
                      "calculatedAt": _ai_now_iso(),
                      "classification": evaluated.get("classification"),
                      "sampleSize": evaluated.get("sampleSize"),
                      "summary": summary,
                      "methodVersion": evaluated.get("methodVersion")}
            if not any(row.get("id") == record["id"] for row in
                       _MARKET_LEDGER.setdefault("backtests", [])):
                _MARKET_LEDGER["backtests"].append(record)
            backtests[universe] = record

        universe_counts, coverage, latest_counts = {}, {}, {}
        universe_observation_counts = {}
        for universe_id, definition in argus_foundation_jobs.UNIVERSES.items():
            short = definition["short"]
            total_rows = effective.get(
                f"breadth.{short}.totalUniverseCount", [])
            total_rows = [row for row in total_rows
                          if str(row.get("periodEnd") or "") >= production_start]
            eligible_by_date = {row.get("periodEnd"): row.get("value") for row in
                                effective.get(f"breadth.{short}.eligibleCount", [])
                                if str(row.get("periodEnd") or "") >= production_start}
            totals = [float(row.get("value") or 0) for row in total_rows]
            ratios = [round(float(eligible_by_date.get(row.get("periodEnd")) or 0)
                            / float(row.get("value")), 6)
                      for row in total_rows if float(row.get("value") or 0) > 0]
            universe_counts[universe_id] = {
                "minimum": min(totals) if totals else 0,
                "maximum": max(totals) if totals else 0,
                "latest": totals[-1] if totals else 0}
            coverage[universe_id] = {
                "minimum": min(ratios) if ratios else 0,
                "average": round(sum(ratios) / len(ratios), 6) if ratios else 0,
                "latest": ratios[-1] if ratios else 0}
            latest_date = (total_rows[-1].get("periodEnd") if total_rows else None)
            if latest_date:
                values = {}
                for name in ("advancers", "decliners", "unchanged", "unavailable",
                             "noTrade", "missingPrice", "eligibleCount",
                             "totalUniverseCount"):
                    row = next((value for value in effective.get(
                        f"breadth.{short}.{name}", [])
                        if value.get("periodEnd") == latest_date), None)
                    values[name] = row.get("value") if row else None
                latest_counts[universe_id] = values
            universe_observation_counts[short] = sum(
                sum(1 for row in rows
                    if str(row.get("periodEnd") or row.get("asOf") or "")
                    >= production_start)
                for series_id, rows in effective.items()
                if series_id.startswith(f"breadth.{short}.") )

        derived = argus_market_ledger.derived_history(
            _MARKET_LEDGER, _ai_now_iso())
        latest_ratios = {short: {str(window): (((derived.get(
            f"breadth.{short}.ratio{window}") or [{}])[-1]).get("value"))
            for window in (6, 10, 15, 25)}
            for short in ("first_section", "prime", "all")}
        all_dates = sorted({row.get("periodEnd") for row in
                            effective.get("breadth.all.advancers", [])
                            if row.get("periodEnd")
                            and str(row.get("periodEnd")) >= production_start})
        if not all_dates or all_dates[0] > production_start \
                or all_dates[-1] != latest_confirmed:
            raise RuntimeError("breadth_five_year_range_incomplete")
        raw_seen, duplicate_count = set(), 0
        validation_rows = [row for row in
                           (_MARKET_LEDGER.get("observations") or [])
                           if str(row.get("seriesId") or "").startswith("breadth.")
                           and str(row.get("periodEnd") or "") >= production_start]
        for row in validation_rows:
            key = (row.get("seriesId"), row.get("periodEnd"),
                   row.get("availableFrom"), row.get("value"))
            if key in raw_seen:
                duplicate_count += 1
            raw_seen.add(key)
        effective_breadth_count = sum(
            sum(1 for row in rows
                if str(row.get("periodEnd") or row.get("asOf") or "")
                >= production_start)
            for series_id, rows in effective.items()
            if series_id.startswith("breadth."))
        spot_passed = len(spot_checks) == 10 and all(
            row["matches"] for row in spot_checks)
        result = {
            "status": "completed", "rowCount": effective_breadth_count,
            "observationCount": effective_breadth_count,
            "oldestDate": all_dates[0], "newestDate": all_dates[-1],
            "tradingDateCount": len(all_dates), "missingDates": [],
            "duplicateCount": duplicate_count, "correctedRows": corrected_rows,
            "reconciledRows": reconciled_rows,
            "reconciliationRevisions": reconciliation_revisions,
            "revisionCount": sum(1 for row in validation_rows
                                 if int(row.get("revision") or 0) > 0),
            "failedRequestCount": 0, "checkpointPending": 0,
            "permanentFailures": [], "universeCounts": universe_counts,
            "coverage": coverage, "latestCounts": latest_counts,
            "latestRatios": latest_ratios,
            "universeObservationCounts": universe_observation_counts,
            "spotChecks": spot_checks, "spotCheckPassed": spot_passed,
            "turningPointCount": len(points), "backtests": backtests,
            "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER),
            "providerProof": proof,
            "methodVersion": argus_foundation_jobs.METHOD_VERSION,
            "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
            "planEntitlement": "standard_rolling_10_years_available",
            "entitlementStartDate": entitlement_start,
            "entitlementEndDate": latest_confirmed,
            "latestConfirmedTradingDate": latest_confirmed,
            "entitlementObservedAt": proof.get("entitlementObservedAt"),
            "providerResponseClass": "success", "apiVersion": "v2",
            "universeMethodology": {
                "firstSection": {"from": entitlement_start,
                                 "to": argus_foundation_jobs.FIRST_SECTION_END_DATE},
                "prime": {"from": argus_foundation_jobs.PRIME_START_DATE,
                          "to": latest_confirmed},
                "allMarket": {"from": entitlement_start,
                              "to": latest_confirmed},
                "primeBackProjected": False},
            "rawProviderRowsPersisted": False}
        result.update(scope)
        result["archiveObservationsExcludedFromWorkerMemory"] = archive_excluded
        result["universeMethodology"]["firstSection"]["from"] = production_start
        result["universeMethodology"]["allMarket"]["from"] = production_start
        if duplicate_count or not spot_passed or set(backtests) != {
                "first_section", "prime", "all"}:
            proof["validation"] = {
                "duplicateCount": duplicate_count,
                "spotChecks": spot_checks,
                "reconciledRows": reconciled_rows,
                "backtestUniverses": sorted(backtests)}
            raise RuntimeError("breadth_final_validation_failed")
        _journal("jquants_breadth_backfill_completed", "market_ledger", job_id,
                 {"rowCount": effective_breadth_count,
                  "oldestDate": all_dates[0], "newestDate": all_dates[-1],
                  "stateHash": result["stateHash"]},
                 origin="admin_background_job")
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        proof["errorClass"] = error_class[:80]
        _foundation_job_update(job_id, status="failed",
                               result={"providerProof": proof},
                               error_class=error_class[:80])


def _jquants_breadth_worker_process_body(job_id):
    job = _foundation_job(job_id) or {}
    params = job.get("parameters") or {}
    if params.get("finalizeOnly") is True:
        _jquants_breadth_finalize_worker(job_id)
        return
    requested_end_date = str(params.get("to") or
                             datetime.now(TZ_JST).strftime("%Y-%m-%d"))[:10]
    end_date = requested_end_date
    production_boundary = argus_foundation_jobs.production_calendar_start(end_date)
    stage = str(params.get("stage") or "full_5y").lower()
    staged_start, _ = argus_foundation_jobs.staged_production_range(
        stage, latest_confirmed_date=end_date,
        production_start_date=production_boundary)
    explicit_start = bool(params.get("from"))
    requested_start_date = str(params.get("from") or staged_start)[:10]
    start_date = max(requested_start_date, production_boundary)
    proof = {"provider": "J-Quants", "baseUrl": _JQUANTS_BASE,
             "authentication": "x-api-key", "secretConfigured": bool(_JQUANTS_API_KEY),
             "errorClass": None, "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
             "entitlementStartDate": start_date,
             "entitlementEndDate": end_date,
             "entitlementObservedAt": _ai_now_iso(),
             "entitlementPolicy": argus_foundation_jobs.ENTITLEMENT_POLICY,
             "contractScope": argus_foundation_jobs.PRODUCTION_SCOPE,
             "productionFiveYearStartDate": production_boundary,
             "stage": stage, "apiVersion": "v2",
             "requestedStartDate": requested_start_date,
             "effectiveStartDate": start_date}
    try:
        _foundation_job_update(job_id, status="running",
                               checkpoint={"providerProof": proof})
        if not _JQUANTS_API_KEY:
            raise RuntimeError("jquants_not_configured_in_runtime")
        recent_start = (datetime.strptime(requested_end_date, "%Y-%m-%d")
                        - timedelta(days=45)).strftime("%Y-%m-%d")
        recent_dates = _jquants_calendar_dates(
            recent_start, requested_end_date, proof)
        latest_confirmed = None
        for candidate in reversed(recent_dates):
            exact = _jquants_exact_date_rows(_jquants_secure_rows(
                "/equities/bars/daily", {"date": candidate}, proof=proof,
                max_pages=200), candidate)
            if exact:
                latest_confirmed = candidate
                break
        if not latest_confirmed:
            raise RuntimeError("jquants_recent_confirmed_date_not_found")
        end_date = latest_confirmed
        production_boundary = argus_foundation_jobs.production_calendar_start(
            end_date)
        staged_start, _ = argus_foundation_jobs.staged_production_range(
            stage, latest_confirmed_date=end_date,
            production_start_date=production_boundary)
        if not explicit_start:
            requested_start_date = staged_start
        proof["requestedEndDate"] = requested_end_date
        proof["latestConfirmedTradingDate"] = end_date
        entitlement_start, _ = _jquants_discover_entitlement_start(
            end_date, proof)
        production_start, boundary_rows = _jquants_discover_production_start(
            end_date, proof)
        start_date = max(requested_start_date, production_start)
        proof["entitlementStartDate"] = entitlement_start
        proof["productionFiveYearStartDate"] = production_start
        proof["effectiveStartDate"] = start_date
        scope = argus_foundation_jobs.production_scope_metadata(
            latest_confirmed_date=end_date,
            production_start_date=production_start,
            entitlement_start_date=entitlement_start)
        proof.update(scope)
        # Calendar V2 is probed in its production-confirmed current window. Its
        # history does not extend to the 2008 Premium price start, so historical
        # trading dates are proven by the existence of official adjusted daily
        # bars, not by inventing holiday rows or treating weekdays as trades.
        calendar_probe_start = (datetime.strptime(end_date, "%Y-%m-%d")
                                - timedelta(days=6)).strftime("%Y-%m-%d")
        _jquants_calendar_dates(calendar_probe_start, end_date, proof)
        candidate_dates = argus_foundation_jobs.weekday_candidates(
            start_date, end_date)
        if stage == "canary_5d":
            candidate_dates = _jquants_calendar_dates(
                start_date, end_date, proof)[-5:]
            if candidate_dates:
                start_date = candidate_dates[0]
                proof["effectiveStartDate"] = start_date
        dates = list(candidate_dates)
        if not dates:
            raise RuntimeError("jquants_no_trading_dates")
        previous = {}
        # A resumed slice must compare its first target session with the prior
        # official close.  Fetch a bounded look-back seed but never persist it
        # as a new observation or move the requested oldest boundary backward.
        if params.get("resumedFromJobId") or start_date > production_start:
            seed_start = (datetime.strptime(start_date, "%Y-%m-%d")
                          - timedelta(days=10)).strftime("%Y-%m-%d")
            seed_end = (datetime.strptime(start_date, "%Y-%m-%d")
                        - timedelta(days=1)).strftime("%Y-%m-%d")
            for seed_date in reversed(argus_foundation_jobs.weekday_candidates(
                    seed_start, seed_end)):
                seed_bars = _jquants_secure_rows(
                    "/equities/bars/daily", {"date": seed_date}, proof=proof,
                    max_pages=200)
                seed_bars = _jquants_exact_date_rows(seed_bars, seed_date)
                if seed_bars:
                    previous = {}
                    for seed_row in seed_bars:
                        try:
                            seed_close = float(seed_row.get("AdjC"))
                        except (TypeError, ValueError):
                            continue
                        if seed_close > 0:
                            previous[str(seed_row.get("Code")
                                         or seed_row.get("code") or "")] = seed_close
                    proof["resumeSeedDate"] = seed_date
                    break
        total = len(dates)
        trading_date_count = 0
        closed_or_no_bars = 0
        committed = 0
        duplicate_count = 0
        idempotent_skipped = 0
        revision_count = 0
        failed_requests = 0
        batch = []
        coverage = {uid: [] for uid in argus_foundation_jobs.UNIVERSES}
        issue_counts = {uid: [] for uid in argus_foundation_jobs.UNIVERSES}
        topix_prices = []
        spot_check_candidates = []
        latest_daily = None
        oldest = newest = None
        processing_dates = candidate_dates
        processed_target = 0
        for date_text in processing_dates:
            current = _foundation_job(job_id) or {}
            if current.get("cancelRequested"):
                _foundation_job_update(job_id, status="cancelled",
                                       result={"committedRows": committed,
                                               "lastDate": newest})
                return
            try:
                bars = _jquants_exact_date_rows(
                    (boundary_rows if date_text == production_start else
                     _jquants_secure_rows(
                            "/equities/bars/daily", {"date": date_text},
                            proof=proof, max_pages=200)), date_text)
            except RuntimeError:
                failed_requests += 1
                raise
            if not bars:
                if date_text >= start_date:
                    processed_target += 1
                    closed_or_no_bars += 1
                continue
            processed_target += 1
            trading_date_count += 1
            master = _jquants_secure_rows(
                "/equities/master", {"date": date_text}, proof=proof,
                max_pages=100)
            if not master:
                raise RuntimeError("jquants_historical_master_empty")
            daily = argus_foundation_jobs.calculate_daily(
                date=date_text, master_rows=master, bar_rows=bars,
                previous_adjusted_closes=previous)
            latest_daily = daily
            spot_check_candidates.append({
                "date": date_text,
                "universes": {uid: dict(row.get("counts") or {})
                              for uid, row in daily.get("universes", {}).items()
                              if argus_foundation_jobs.universe_active(
                                  uid, date_text)}})
            spot_check_candidates = spot_check_candidates[-10:]
            previous = daily["nextAdjustedCloses"]
            topix_row = next((x for x in bars if str(
                x.get("Code") or x.get("code") or "").startswith("1306")), None)
            if topix_row and topix_row.get("AdjC") is not None:
                try:
                    topix_close = float(topix_row["AdjC"])
                    if topix_close > 0:
                        topix_prices.append({"date": date_text,
                                             "close": topix_close,
                                             "availableFrom":
                                             f"{date_text}T17:00:00+09:00"})
                        batch.append({
                            "seriesId": "breadth.topixProxyClose",
                            "periodEnd": date_text,
                            "publishedAt": f"{date_text}T17:00:00+09:00",
                            "availableFrom": f"{date_text}T17:00:00+09:00",
                            "observedAt": _ai_now_iso(), "value": topix_close,
                            "unit": "JPY", "source": "J-Quants V2 1306 adjusted close",
                            "sourceKind": "derived", "status": "live",
                            "metadata": {
                                "instrument": "1306 TOPIX-linked ETF proxy",
                                "officialIndexValue": False,
                                "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
                                "entitlementStartDate": entitlement_start,
                                "productionFiveYearStartDate": production_start,
                                "contractScope": argus_foundation_jobs.PRODUCTION_SCOPE,
                                "methodVersion": argus_foundation_jobs.METHOD_VERSION}})
                except (TypeError, ValueError):
                    pass
            batch.extend(argus_foundation_jobs.ledger_candidates(
                daily, calculated_at=_ai_now_iso(),
                entitlement_start_date=entitlement_start,
                production_start_date=production_start,
                latest_confirmed_date=end_date))
            for uid, row in daily["universes"].items():
                if argus_foundation_jobs.universe_active(uid, date_text):
                    coverage[uid].append(row["coverageRatio"])
                    issue_counts[uid].append(row["issueCount"])
            oldest = oldest or date_text
            newest = date_text
            if len(batch) >= 200 or processed_target == total:
                before = len(_MARKET_LEDGER.get("observations") or [])
                added, revisions, skipped = _breadth_commit_rows(
                    batch, _ai_now_iso())
                committed += added
                revision_count += revisions
                idempotent_skipped += skipped
                batch = []
                percent = round(processed_target / total * 100.0, 2)
                _foundation_job_update(
                    job_id,
                    progress={"completedUnits": processed_target,
                              "totalUnits": total,
                              "percent": percent},
                    checkpoint={"lastCommittedDate": date_text,
                                "stage": stage,
                                "batchPolicy": "one_day_to_maximum_one_month",
                                "providerProof": dict(proof),
                                "marketLedgerRowsBeforeBatch": before,
                                "marketLedgerRowsAfterBatch": len(
                                    _MARKET_LEDGER.get("observations") or [])})
                gc.collect()
        # The requested end date may be a weekend/holiday (for example Marine
        # Day). Flush the final residue even when the last candidate has no bars.
        if batch:
            before = len(_MARKET_LEDGER.get("observations") or [])
            added, revisions, skipped = _breadth_commit_rows(
                batch, _ai_now_iso())
            committed += added
            revision_count += revisions
            idempotent_skipped += skipped
            batch = []
            _foundation_job_update(
                job_id,
                progress={"completedUnits": total, "totalUnits": total,
                          "percent": 100.0},
                checkpoint={"lastCommittedDate": newest,
                            "stage": stage,
                            "batchPolicy": "one_day_to_maximum_one_month",
                            "providerProof": dict(proof),
                            "marketLedgerRowsBeforeBatch": before,
                            "marketLedgerRowsAfterBatch": len(
                                _MARKET_LEDGER.get("observations") or [])})
            gc.collect()
        if trading_date_count == 0:
            raise RuntimeError("jquants_no_daily_bars_in_range")
        # Batch checkpoints defer the expensive pure rebuild.  Publish a fully
        # derived and integrity-hashed state once all official rows are present.
        archive_excluded = _scope_breadth_worker_ledger(production_start)
        rebuilt = argus_market_ledger.rebuild(_MARKET_LEDGER, _ai_now_iso())
        _MARKET_LEDGER.clear()
        _MARKET_LEDGER.update(rebuilt)
        effective_rows = argus_market_ledger.latest_by_series(
            _MARKET_LEDGER, _ai_now_iso())
        if stage == "full_5y":
            topix_prices = [
                {"date": row.get("periodEnd"), "close": row.get("value"),
                 "availableFrom": row.get("availableFrom")}
                for row in effective_rows.get("breadth.topixProxyClose", [])
                if row.get("value") is not None
                and str(row.get("periodEnd") or "") >= production_start]
        proof["entitlementEndDate"] = newest
        proof["providerResponseClass"] = "success"
        seen_breadth_rows = set()
        for row in (_MARKET_LEDGER.get("observations") or []):
            if not str(row.get("seriesId") or "").startswith("breadth."):
                continue
            key = (row.get("seriesId"), row.get("periodEnd"),
                   row.get("availableFrom"), row.get("value"))
            if key in seen_breadth_rows:
                duplicate_count += 1
            else:
                seen_breadth_rows.add(key)
        points = [x for x in (_MARKET_LEDGER.get("turningPoints") or [])
                  if x.get("ruleId") == "BREADTH_TURN"
                  and str(x.get("effectiveFrom") or "") >= production_start]
        backtests = {}
        for universe in ("first_section", "prime", "all"):
            universe_points = [x for x in points if str(
                x.get("direction") or "").startswith(universe + ":")]
            evaluated = argus_market_intelligence.walk_forward_backtest(
                universe_points, topix_prices)
            record = {"id": "bt-" + hashlib.sha256(json.dumps(
                          {"universe": universe,
                           "methodVersion": evaluated.get("methodVersion"),
                           "signalIds": [x.get("id") for x in universe_points]},
                          sort_keys=True).encode()).hexdigest()[:20],
                      "ruleId": "BREADTH_TURN", "universe": universe,
                      "calculatedAt": _ai_now_iso(),
                      "classification": evaluated.get("classification"),
                      "sampleSize": evaluated.get("sampleSize"),
                      "summary": {k: evaluated.get(k) for k in (
                          "hitRate5d", "falsePositiveRate5d", "confidenceInterval95",
                          "average1dPct", "average5dPct", "average20dPct",
                          "maxRisePct", "maxDrawdownPct", "noFutureLeakage")},
                      "methodVersion": evaluated.get("methodVersion")}
            if not any(x.get("id") == record["id"] for x in
                       _MARKET_LEDGER.setdefault("backtests", [])):
                _MARKET_LEDGER["backtests"].append(record)
            backtests[universe] = record
        derived = argus_market_ledger.derived_history(
            _MARKET_LEDGER, _ai_now_iso())
        latest_ratios = {}
        for universe in ("first_section", "prime", "all"):
            latest_ratios[universe] = {
                str(window): (((derived.get(
                    f"breadth.{universe}.ratio{window}") or [{}])[-1]).get("value"))
                for window in (6, 10, 15, 25)}
        latest_counts = {}
        if latest_daily:
            for universe_id, row in latest_daily.get("universes", {}).items():
                if not argus_foundation_jobs.universe_active(
                        universe_id, latest_daily.get("date")):
                    continue
                latest_counts[universe_id] = {
                    **dict(row.get("counts") or {}),
                    **dict(row.get("dataQuality") or {}),
                    "eligibleCount": row.get("eligibleCount"),
                    "totalUniverseCount": row.get("totalUniverseCount")}
        spot_checks = []
        for candidate in spot_check_candidates:
            matches = True
            for uid, counts in candidate["universes"].items():
                short = (argus_foundation_jobs.UNIVERSES.get(uid) or {}).get("short")
                for name in ("advancers", "decliners", "unchanged", "unavailable"):
                    stored = next((x for x in effective_rows.get(
                        f"breadth.{short}.{name}", [])
                        if x.get("periodEnd") == candidate["date"]), None)
                    matches = matches and bool(stored and stored.get("value") ==
                                               counts.get(name))
            spot_checks.append({"date": candidate["date"], "matches": matches})
        universe_observation_counts = {
            short: sum(1 for row in (_MARKET_LEDGER.get("observations") or [])
                       if str(row.get("seriesId") or "").startswith(
                           f"breadth.{short}.")
                       and str(row.get("periodEnd") or "") >= production_start)
            for short in ("first_section", "prime", "all")}
        effective_scope_start = (production_start
                                 if stage == "full_5y" else start_date)
        effective_stage_observation_count = sum(
            sum(1 for row in rows
                if effective_scope_start <= str(row.get("periodEnd") or
                                                row.get("asOf") or "") <= newest)
            for series_id, rows in effective_rows.items()
            if series_id.startswith("breadth."))
        active_all_dates = sorted({
            str(row.get("periodEnd")) for row in
            effective_rows.get("breadth.all.advancers", [])
            if effective_scope_start <= str(row.get("periodEnd") or "") <= newest})
        if stage == "full_5y" and (not active_all_dates
                                   or active_all_dates[0] > production_start
                                   or active_all_dates[-1] != newest):
            raise RuntimeError("breadth_five_year_range_incomplete")
        scope = argus_foundation_jobs.production_scope_metadata(
            latest_confirmed_date=newest,
            production_start_date=production_start,
            entitlement_start_date=entitlement_start)
        result = {
            "status": "completed",
            "rowCount": committed,
            "observationCount": effective_stage_observation_count,
            "oldestDate": (active_all_dates[0] if active_all_dates else oldest),
            "newestDate": (active_all_dates[-1] if active_all_dates else newest),
            "tradingDateCount": (len(active_all_dates) if active_all_dates
                                 else trading_date_count),
            "missingDates": [],
            "closedOrNoBarsCandidateCount": closed_or_no_bars,
            "duplicateCount": duplicate_count,
            "idempotentSkippedCount": idempotent_skipped,
            "revisionCount": revision_count,
            "failedRequestCount": failed_requests,
            "checkpointPending": 0,
            "permanentFailures": [],
            "universeCounts": {uid: {"minimum": min(vals) if vals else 0,
                                      "maximum": max(vals) if vals else 0,
                                      "latest": vals[-1] if vals else 0}
                               for uid, vals in issue_counts.items()},
            "coverage": {uid: {"minimum": min(vals) if vals else 0,
                                "average": (round(sum(vals) / len(vals), 6)
                                            if vals else 0),
                                "latest": vals[-1] if vals else 0}
                         for uid, vals in coverage.items()},
            "latestCounts": latest_counts,
            "latestRatios": latest_ratios,
            "universeObservationCounts": universe_observation_counts,
            "spotChecks": spot_checks,
            "spotCheckPassed": len(spot_checks) == 10 and all(
                x["matches"] for x in spot_checks),
            "turningPointCount": len(points),
            "backtests": backtests,
            "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER),
            "providerProof": proof,
            "methodVersion": argus_foundation_jobs.METHOD_VERSION,
            "plan": argus_foundation_jobs.ENTITLEMENT_PLAN,
            "planEntitlement": "standard_rolling_10_years_available",
            "entitlementStartDate": entitlement_start,
            "entitlementEndDate": newest,
            "latestConfirmedTradingDate": newest,
            "entitlementObservedAt": proof.get("entitlementObservedAt"),
            "providerResponseClass": proof.get("providerResponseClass"),
            "apiVersion": "v2",
            "universeMethodology": {
                "firstSection": {
                    "from": production_start,
                    "to": argus_foundation_jobs.FIRST_SECTION_END_DATE},
                "prime": {"from": argus_foundation_jobs.PRIME_START_DATE,
                          "to": newest},
                "allMarket": {"from": production_start,
                              "to": newest},
                "primeBackProjected": False},
            "rawProviderRowsPersisted": False,
        }
        result.update(scope)
        result.update({"stage": stage,
                       "batchPolicy": "one_day_to_maximum_one_month",
                       "checkpointPersistence": "each_batch",
                       "duplicateSafeResume": True,
                       "archiveObservationsExcludedFromWorkerMemory":
                       archive_excluded})
        _journal("jquants_breadth_backfill_completed", "market_ledger", job_id,
                 {"rowCount": committed, "oldestDate": oldest,
                  "newestDate": newest, "stateHash": result["stateHash"]},
                 origin="admin_background_job")
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        proof["errorClass"] = error_class[:80]
        _foundation_job_update(job_id, status="failed", result={
            "providerProof": proof}, error_class=error_class[:80])


def _process_peak_memory_mb():
    """Return a platform-normalized peak RSS without adding a dependency."""
    peak = float(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss or 0)
    return round(peak / (1024 * 1024 if sys.platform == "darwin" else 1024), 2)


def _jquants_breadth_process_entry(job_id, connection, memory_soft_limit_mb,
                                    ledger_seed=None):
    """Run provider I/O/calculation in an isolated process; parent owns durability."""
    global _foundation_job_update, _foundation_job, _breadth_commit_rows
    global _journal, _osint_persist
    local_commit = _breadth_commit_rows
    if isinstance(ledger_seed, dict):
        _MARKET_LEDGER.clear()
        _MARKET_LEDGER.update(argus_market_ledger.normalize_state(ledger_seed))
    ledger_seed = None
    gc.collect()
    try:
        limit_bytes = int(memory_soft_limit_mb) * 1024 * 1024
        current_soft, current_hard = resource.getrlimit(resource.RLIMIT_DATA)
        hard = current_hard if current_hard not in (-1, resource.RLIM_INFINITY) else limit_bytes
        resource.setrlimit(resource.RLIMIT_DATA,
                           (min(limit_bytes, hard), current_hard))
    except (ValueError, OSError, AttributeError):
        pass

    def exchange(payload):
        connection.send(payload)
        response = connection.recv()
        if not isinstance(response, dict) or response.get("ok") is not True:
            raise RuntimeError("breadth_parent_ipc_failed")
        return response

    def remote_job(target_job_id):
        return exchange({"op": "job", "jobId": target_job_id}).get("job")

    def remote_update(target_job_id, *, status=None, progress=None,
                      checkpoint=None, result=None, error_class=None,
                      persist=True):
        payload = {"op": "update", "jobId": target_job_id,
                   "status": status, "progress": progress,
                   "checkpoint": checkpoint, "result": result,
                   # Parent checkpoints only after this child has exited.
                   # Progress remains crash-resumable in the small sidecar.
                   "errorClass": error_class, "persist": False}
        if status == "completed":
            payload["ledgerDerivedState"] = {
                key: _MARKET_LEDGER.get(key) for key in (
                    "derivedMetrics", "turningPoints", "backtests",
                    "derivedStateDirty", "lastRebuiltObservationCount",
                    "lastRebuiltAt", "lastUpdatedAt")}
            payload["ledgerDerivedScopeStart"] = (result or {}).get(
                "productionFiveYearStartDate")
        return exchange(payload).get("job")

    def mirrored_commit(rows, now_iso):
        local_result = local_commit(rows, now_iso)
        parent_result = tuple(exchange({"op": "commit", "rows": rows,
                                        "nowIso": now_iso}).get("result") or ())
        if parent_result != tuple(local_result):
            raise RuntimeError("breadth_parent_commit_mismatch")
        return local_result

    def remote_journal(kind, entity_type, entity_id, payload, origin=None):
        return exchange({"op": "journal", "kind": kind,
                         "entityType": entity_type, "entityId": entity_id,
                         "payload": payload, "origin": origin}).get("result")

    _foundation_job = remote_job
    _foundation_job_update = remote_update
    _breadth_commit_rows = mirrored_commit
    _journal = remote_journal
    _osint_persist = lambda: None
    try:
        _jquants_breadth_worker_process_body(job_id)
        connection.send({"op": "done", "workerPeakMemoryMb":
                         _process_peak_memory_mb()})
    except BaseException as exc:
        connection.send({"op": "crashed", "errorClass":
                         type(exc).__name__[:80], "workerPeakMemoryMb":
                         _process_peak_memory_mb()})
    finally:
        connection.close()


def _jquants_breadth_worker(job_id):
    """Supervise the one-at-a-time breadth worker in an independent OS process."""
    try:
        memory_limit = int(os.environ.get(
            "JQUANTS_BREADTH_WORKER_MEMORY_SOFT_LIMIT_MB", "1280"))
    except (TypeError, ValueError):
        memory_limit = 1280
    memory_limit = max(256, min(memory_limit, 1280))
    boot_id = _RUNTIME.get("bootId")
    backend_peak_before = _process_peak_memory_mb()
    start_method = str(os.environ.get(
        "ARGUS_BREADTH_PROCESS_START_METHOD", "spawn")).lower()
    if start_method not in ("spawn", "forkserver", "fork"):
        start_method = "spawn"
    process_context = multiprocessing.get_context(start_method)
    ledger_seed = _breadth_worker_seed_state(job_id)
    parent_connection, child_connection = process_context.Pipe(duplex=True)
    process_target = _jquants_breadth_process_entry
    if start_method != "fork":
        import argus_breadth_worker
        process_target = argus_breadth_worker.process_entry
    process = process_context.Process(
        target=process_target,
        args=(job_id, child_connection, memory_limit, ledger_seed), daemon=True)
    process.start()
    ledger_seed = None
    gc.collect()
    child_connection.close()
    worker_peak = None
    crashed = None
    received_done = False
    try:
        while process.is_alive() or parent_connection.poll(0.2):
            if not parent_connection.poll(0.5):
                continue
            message = parent_connection.recv()
            operation = message.get("op") if isinstance(message, dict) else None
            try:
                if operation == "job":
                    reply = {"ok": True, "job": _foundation_job(message["jobId"])}
                elif operation == "commit":
                    reply = {"ok": True, "result": list(_breadth_commit_rows(
                        message.get("rows") or [], message.get("nowIso") or _ai_now_iso()))}
                elif operation == "update":
                    result = message.get("result")
                    if message.get("status") == "completed" and isinstance(result, dict):
                        derived_state = message.get("ledgerDerivedState") or {}
                        scope_start = message.get("ledgerDerivedScopeStart")
                        if scope_start:
                            retained_metrics = [row for row in
                                (_MARKET_LEDGER.get("derivedMetrics") or [])
                                if not str(row.get("metricId") or "").startswith(
                                    "breadth.") or str(row.get("asOf") or "")
                                < scope_start]
                            metric_ids = {row.get("id") for row in retained_metrics}
                            retained_metrics.extend(row for row in
                                (derived_state.get("derivedMetrics") or [])
                                if row.get("id") not in metric_ids)
                            retained_points = [row for row in
                                (_MARKET_LEDGER.get("turningPoints") or [])
                                if row.get("ruleId") != "BREADTH_TURN"
                                or str(row.get("effectiveFrom") or "") < scope_start]
                            point_ids = {row.get("id") for row in retained_points}
                            retained_points.extend(row for row in
                                (derived_state.get("turningPoints") or [])
                                if row.get("id") not in point_ids)
                            retained_backtests = list(
                                _MARKET_LEDGER.get("backtests") or [])
                            backtest_ids = {row.get("id") for row in retained_backtests}
                            retained_backtests.extend(row for row in
                                (derived_state.get("backtests") or [])
                                if row.get("id") not in backtest_ids)
                            _MARKET_LEDGER["derivedMetrics"] = retained_metrics
                            _MARKET_LEDGER["turningPoints"] = retained_points
                            _MARKET_LEDGER["backtests"] = retained_backtests
                            _MARKET_LEDGER["derivedStateDirty"] = False
                            _MARKET_LEDGER["lastRebuiltObservationCount"] = len(
                                _MARKET_LEDGER.get("observations") or [])
                            _MARKET_LEDGER["lastRebuiltAt"] = derived_state.get(
                                "lastRebuiltAt")
                            _MARKET_LEDGER["lastUpdatedAt"] = derived_state.get(
                                "lastUpdatedAt")
                        else:
                            for key in ("derivedMetrics", "turningPoints",
                                        "backtests", "derivedStateDirty",
                                        "lastRebuiltObservationCount",
                                        "lastRebuiltAt", "lastUpdatedAt"):
                                if key in derived_state:
                                    _MARKET_LEDGER[key] = derived_state[key]
                        result = dict(result)
                        result["stateHash"] = argus_market_ledger.state_hash(
                            _MARKET_LEDGER)
                    reply = {"ok": True, "job": _foundation_job_update(
                        message["jobId"], status=message.get("status"),
                        progress=message.get("progress"),
                        checkpoint=message.get("checkpoint"), result=result,
                        error_class=message.get("errorClass"),
                        persist=message.get("persist", True))}
                elif operation == "journal":
                    reply = {"ok": True, "result": _journal(
                        message.get("kind"), message.get("entityType"),
                        message.get("entityId"), message.get("payload") or {},
                        origin=message.get("origin"))}
                elif operation in ("done", "crashed"):
                    worker_peak = message.get("workerPeakMemoryMb")
                    crashed = message.get("errorClass") if operation == "crashed" else None
                    received_done = operation == "done"
                    continue
                else:
                    reply = {"ok": False}
            except Exception:
                reply = {"ok": False}
            parent_connection.send(reply)
    except (EOFError, BrokenPipeError, OSError):
        if not received_done:
            crashed = crashed or "breadth_worker_ipc_closed"
    finally:
        process.join(timeout=10)
        if process.is_alive():
            process.terminate()
            process.join(timeout=5)
        parent_connection.close()

    final = _foundation_job(job_id) or {}
    runtime_metrics = {
        "executionMode": ("independent_spawned_os_process"
                          if start_method != "fork" else
                          "independent_os_process"),
        "workerProcessStartMethod": start_method,
        "workerConcurrency": 1,
        "workerMemorySoftLimitMb": memory_limit,
        "workerPeakMemoryMb": worker_peak,
        "backendPeakMemoryMb": _process_peak_memory_mb(),
        "backendPeakMemoryAtStartMb": backend_peak_before,
        "backendRestartCountDuringJob": 0 if _RUNTIME.get("bootId") == boot_id else 1,
        "backendBootIdStable": _RUNTIME.get("bootId") == boot_id,
    }
    if crashed or process.exitcode not in (0, None):
        if final.get("status") not in argus_foundation_jobs.TERMINAL_STATES:
            _foundation_job_update(job_id, status="failed",
                                   result=runtime_metrics,
                                   error_class=crashed or
                                   f"breadth_worker_exit_{process.exitcode}")
        return
    result = final.get("result") if isinstance(final.get("result"), dict) else None
    if final.get("status") == "completed" and result is not None:
        result = dict(result)
        result.update(runtime_metrics)
        _foundation_job_update(job_id, status="completed", result=result)
    elif final.get("status") == "failed":
        result = dict(result or {})
        result.update(runtime_metrics)
        _foundation_job_update(job_id, status="failed", result=result,
                               error_class=final.get("errorClass"))


def _journal_reverify_worker(job_id):
    try:
        _foundation_job_update(job_id, status="running")
        receipt = _remote_readback_ack(_ai_now_iso())
        if not receipt or _REMOTE_CYCLE.get("readBackVerified") is not True:
            raise RuntimeError(_REMOTE_CYCLE.get("errorClass")
                               or "journal_readback_unverified")
        result = {"expectedHash": _REMOTE_CYCLE.get("expectedHash"),
                  "actualHash": _REMOTE_CYCLE.get("actualHash"),
                  "remoteCommitSha": _REMOTE_CYCLE.get("remoteCommitSha"),
                  "readBackVerified": True, "verificationStatus": "verified",
                  "ack": {"receiptStatus": _REMOTE_ACK.get("lastReceiptStatus"),
                          "acknowledgedCount": _REMOTE_CYCLE.get(
                              "acknowledgedCount"),
                          "lastVerifiedRemoteAckAt": _REMOTE_ACK.get(
                              "lastVerifiedRemoteAckAt")},
                  "pendingCount": _REMOTE_CYCLE.get("pendingCount"),
                  "errorClass": None,
                  "marketLedgerReadBack": dict(_MARKET_LEDGER_REMOTE)}
        completed_v2 = (_FORMAL_BENCHMARK_V2.get("holdoutResult") or {}).get(
            "benchmarkId")
        if completed_v2:
            updated_v2 = argus_research_benchmark_v2.append_remote_receipt(
                _FORMAL_BENCHMARK_V2, benchmark_id=completed_v2,
                receipt={"remoteCommitSha": result["remoteCommitSha"],
                         "expectedHash": result["expectedHash"],
                         "actualHash": result["actualHash"],
                         "readBackVerified": True,
                         "verifiedAt": _ai_now_iso()})
            _FORMAL_BENCHMARK_V2.clear()
            _FORMAL_BENCHMARK_V2.update(updated_v2)
        _journal("remote_journal_reverified", "remote_journal", job_id,
                 {"verificationStatus": "verified",
                  "remoteCommitSha": result["remoteCommitSha"]},
                 origin="admin_background_job")
        _foundation_job_update(job_id, status="completed", result=result)
    except Exception as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        _foundation_job_update(job_id, status="failed",
                               error_class=error_class[:80])


@app.route("/api/argus/admin/market-ledger/jquants-backfill", methods=["POST"])
def api_argus_admin_market_ledger_jquants_backfill():
    """Backfill contracted official investor flows; preview is mandatory first.

    The two-market flow series uses the official ``TokyoNagoya`` section.  The
    endpoint intentionally does not manufacture aggregate credit balances from
    per-issue share volumes; those remain on the validated admin CSV path.
    """
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    if not _JQUANTS_API_KEY:
        return jsonify({"ok": False, "error": "jquants_not_configured_in_runtime"}), 503
    body = request.get_json(silent=True) or {}
    now_iso = _ai_now_iso()
    from_date = str(body.get("from") or
                    (datetime.now(TZ_JST) - timedelta(days=5 * 366)).strftime("%Y-%m-%d"))
    to_date = str(body.get("to") or datetime.now(TZ_JST).strftime("%Y-%m-%d"))
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", from_date) or \
            not re.fullmatch(r"\d{4}-\d{2}-\d{2}", to_date) or from_date > to_date:
        return jsonify({"ok": False, "error": "invalid_date_range"}), 400
    dry_run = body.get("dryRun") is not False
    if not dry_run and body.get("confirm") is not True:
        return jsonify({"ok": False, "error": "explicit_confirmation_required"}), 400
    try:
        raw = _jquants_paginated("/equities/investor-types",
                                 {"section": "TokyoNagoya", "from": from_date, "to": to_date})
        candidates = argus_market_intelligence.normalize_jquants_investor_rows(
            raw, now_iso, "TokyoNagoya")
        existing = {(x.get("seriesId"), x.get("periodEnd"), x.get("availableFrom"), x.get("value"))
                    for x in (_MARKET_LEDGER.get("observations") or []) if isinstance(x, dict)}
        candidates = [x for x in candidates if
                      (x.get("seriesId"), x.get("periodEnd"), x.get("availableFrom"), x.get("value"))
                      not in existing]
        if not candidates:
            return jsonify({"ok": True, "dryRun": dry_run, "status": "no_changes",
                            "providerRows": len(raw), "candidateRows": 0,
                            "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER)})
        result = argus_market_ledger.import_rows(
            _MARKET_LEDGER, candidates, now_iso=now_iso, dry_run=dry_run)
        if result["ok"] and not dry_run:
            _MARKET_LEDGER.clear()
            _MARKET_LEDGER.update(result.pop("state"))
            _journal("market_ledger_jquants_backfill_committed", "market_ledger",
                     result["importId"],
                     {"rowCount": len(result["preview"]), "section": "TokyoNagoya",
                      "from": from_date, "to": to_date,
                      "stateHash": argus_market_ledger.state_hash(_MARKET_LEDGER)},
                     origin="admin")
            _osint_persist()
        else:
            result.pop("state", None)
        result.update({"providerRows": len(raw), "candidateRows": len(candidates),
                       "section": "TokyoNagoya", "from": from_date, "to": to_date,
                       "unitConversion": "thousand_yen_to_JPY",
                       "publicationPolicy": "official_pubdate_18:00_JST"})
        return jsonify(result), (200 if result["ok"] else 400)
    except (requests.RequestException, RuntimeError, ValueError) as exc:
        error_class = str(exc) if isinstance(exc, RuntimeError) else type(exc).__name__
        return jsonify({"ok": False, "error": "jquants_backfill_failed",
                        "errorClass": error_class[:80]}), 502


@app.route("/api/argus/cause-attribution")
def api_argus_cause_attribution():
    sym = (request.args.get("symbol") or "").strip()
    if not sym:
        return jsonify({"error": "symbol required"}), 400
    mkt = (request.args.get("market") or "JP").upper()
    explain = (request.args.get("explain") or "").lower() in ("1", "true", "yes")
    try:
        return jsonify(get_cause_attribution(sym, mkt, explain=explain))
    except Exception as e:
        return jsonify({"error": "attribution_failed", "message": str(e)[:120]}), 200


# ⑧ Cause Attribution Ledger (v10.117): the cause stack for every active incident,
# in one call, so the daily workflow can persist it (and later compare to outcome).
def get_cause_attribution_batch():
    try:
        ds = get_downside_incidents()
    except Exception:
        ds = {}
    incs = ds.get("incidents") or []
    out = []
    for i in incs[:8]:
        try:
            st = get_cause_attribution(i.get("symbol"), i.get("market", "JP"))
            out.append({"symbol": st.get("symbol"), "market": st.get("market"),
                        "changePct": st.get("changePct"),
                        "immediateTrigger": st.get("immediateTrigger"),
                        "causeProbabilities": st.get("causeProbabilities"),
                        "unknownShare": st.get("unknownShare"),
                        "contagionScope": (st.get("contagion") or {}).get("scope"),
                        "preEventDeRisking": (st.get("preEvent") or {}).get("preEventDeRiskingProbability")})
        except Exception:
            continue
    return {"status": "live" if out else "empty", "asOf": _ai_now_iso(),
            "engineVersion": "cause-attribution-v1", "attributions": out, "count": len(out)}


@app.route("/api/argus/cause-attribution-batch")
def api_argus_cause_attribution_batch():
    return jsonify(get_cause_attribution_batch())


# ━━━ V11.3.3 Mover Cause Engine ━━━
# Unified attribution ladder for sharp movers BOTH directions. The owner's finding:
# every mover showed a bare 原因未確認, making the layer useless. The ladder separates
# 原因確認/有力材料/候補/有力候補なし and always says what was checked + what to check
# next. Public GET = cached/in-memory evidence only (no provider fetch, no LLM);
# admin/cron refresh may fetch providers; AI explanation is admin-generated only.
_MOVER_CAUSES = {}                      # moverCauseId -> record
_MOVER_CAUSES_FILE = "/tmp/argus_mover_causes.json"
_MOVER_CAUSES_STATE = {"restored": False, "lastRefreshAt": None,
                       "lastExplainAt": None, "pathType": "ephemeral_tmp"}
# v11.3.4 AI-explain budget knobs (env-tunable; admin/cron paths only)
_MC_AI_MAX_PER_RUN = int(os.environ.get("MOVER_CAUSE_AI_EXPLAIN_MAX_PER_RUN", "5"))
_MC_AI_COOLDOWN_MIN = int(os.environ.get("MOVER_CAUSE_AI_EXPLAIN_COOLDOWN_MIN", "30"))
_MC_AI_MIN_ABS_MOVE = float(os.environ.get("MOVER_CAUSE_AI_EXPLAIN_MIN_ABS_MOVE", "3.0"))
_MC_AI_ENABLED = (os.environ.get("MOVER_CAUSE_AI_EXPLAIN_ENABLED",
                                 os.environ.get("AI_JUDGE_ENABLED", "1")).lower()
                  not in ("0", "false", "no"))
_MOVER_REFRESH_QUEUE = {"data": None, "expires": 0.0}   # cached queue (5-min TTL)

# ── V11.5.2 explanation request queue ────────────────────────────────────────
# The owner clicks 「理由を詳しく調べる」. That PUBLIC POST enqueues a request here —
# it NEVER calls an LLM or a provider. The admin/cron explain run drains this queue
# FIRST (still cooldown/budget-guarded). Only symbol/market/context/timestamps are
# stored — never prompts, holdings, P&L, or provider bodies. Bounded + deduped.
_MC_EXPLAIN_REQUESTS = {}               # "MKT:SYM" -> {symbol, market, context, count, firstAt, lastAt}
_MC_EXPLAIN_REQ_FILE = "/tmp/argus_mc_explain_requests.json"
_MC_EXPLAIN_REQ_STATE = {"restored": False, "lastDrainAt": None, "lastDrainCount": 0}
_MC_EXPLAIN_REQ_MAX = 100               # bounded (oldest dropped)
_MC_EXPLAIN_REQ_RL = {}                 # "ip|MKT:SYM" -> last epoch (per-IP+symbol throttle)
_MC_EXPLAIN_REQ_RL_SEC = 30


def _mc_explain_key(symbol, market):
    return f"{str(market).upper()}:{str(symbol).upper()}"


def _mc_explain_req_persist():
    try:
        with open(_MC_EXPLAIN_REQ_FILE, "w") as f:
            json.dump({"requests": _MC_EXPLAIN_REQUESTS,
                       "state": {k: _MC_EXPLAIN_REQ_STATE[k]
                                 for k in ("lastDrainAt", "lastDrainCount")}},
                      f, ensure_ascii=False, default=str)
    except Exception:
        pass


def _mc_explain_req_restore_once():
    if _MC_EXPLAIN_REQ_STATE["restored"]:
        return
    _MC_EXPLAIN_REQ_STATE["restored"] = True
    try:
        with open(_MC_EXPLAIN_REQ_FILE) as f:
            blob = json.load(f)
        if isinstance(blob.get("requests"), dict):
            _MC_EXPLAIN_REQUESTS.update(blob["requests"])
        for k in ("lastDrainAt", "lastDrainCount"):
            if (blob.get("state") or {}).get(k) is not None:
                _MC_EXPLAIN_REQ_STATE[k] = blob["state"][k]
    except Exception:
        pass


def _mc_explain_req_add(symbol, market, context, now_iso):
    """Enqueue/refresh a request. Bounded + deduped by symbol+market. No LLM/provider."""
    key = _mc_explain_key(symbol, market)
    e = _MC_EXPLAIN_REQUESTS.get(key)
    if e:
        e["count"] = int(e.get("count") or 1) + 1
        e["lastAt"] = now_iso
        if context:
            e["context"] = str(context)[:40]
        status = "already_queued"
    else:
        _MC_EXPLAIN_REQUESTS[key] = {
            "symbol": str(symbol).upper()[:16], "market": str(market).upper()[:4],
            "context": str(context or "")[:40], "count": 1,
            "firstAt": now_iso, "lastAt": now_iso}
        status = "queued"
    if len(_MC_EXPLAIN_REQUESTS) > _MC_EXPLAIN_REQ_MAX:
        for k in sorted(_MC_EXPLAIN_REQUESTS,
                        key=lambda k: str(_MC_EXPLAIN_REQUESTS[k].get("firstAt"))
                        )[:len(_MC_EXPLAIN_REQUESTS) - _MC_EXPLAIN_REQ_MAX]:
            _MC_EXPLAIN_REQUESTS.pop(k, None)
    return status


def _mc_has_explain_request(symbol, market):
    return _mc_explain_key(symbol, market) in _MC_EXPLAIN_REQUESTS


def _mover_causes_persist():
    try:
        with open(_MOVER_CAUSES_FILE, "w") as f:
            json.dump({"items": _MOVER_CAUSES,
                       "state": {k: _MOVER_CAUSES_STATE[k]
                                 for k in ("lastRefreshAt", "lastExplainAt")}},
                      f, ensure_ascii=False, default=str)
    except Exception:
        pass


def _mover_causes_restore_once():
    """tmp → ledger latest (merge; old snapshots never wipe newer) → empty."""
    if _MOVER_CAUSES_STATE["restored"]:
        return
    _MOVER_CAUSES_STATE["restored"] = True
    try:
        with open(_MOVER_CAUSES_FILE) as f:
            blob = json.load(f)
        items = blob.get("items") or {}
        _MOVER_CAUSES_STATE.update({k: v for k, v in (blob.get("state") or {}).items()
                                    if k in ("lastRefreshAt", "lastExplainAt")})
        if items:
            _MOVER_CAUSES.update(items)
            _MOVER_CAUSES_STATE["pathType"] = "durable_restored"
            return
        # an empty tmp file (calm-moment persist) must NOT block the ledger tier
    except Exception:
        pass
    try:
        r = requests.get(f"{_LEDGER_RAW_BASE}/mover-causes/latest.json?cb={int(time.time())}",
                         timeout=6)
        if r.status_code == 200 and r.text.strip().startswith("{"):
            restored = argus_mover_cause_store.restore_from_snapshot(json.loads(r.text))
            merged = argus_mover_cause_store.merge_records(
                _MOVER_CAUSES, list(restored.values()), now_iso=_ai_now_iso())
            _MOVER_CAUSES.clear()
            _MOVER_CAUSES.update(merged)
            if merged:
                _MOVER_CAUSES_STATE["pathType"] = "ledger_restored"
    except Exception:
        pass


def _mover_move_started_iso(market, now_utc=None):
    """Canonical current-session open, or ``None`` when no move is proven.

    A weekday/hour proxy must never manufacture an intraday cause relationship on
    a holiday or before the exchange's regular open.  DST, holidays, and early
    closes belong exclusively to :mod:`argus_market_clock`.
    """
    market_key = str(market).upper()
    clock_market = (argus_market_clock.JP_EQUITY if market_key == "JP"
                    else argus_market_clock.US_EQUITY if market_key == "US"
                    else None)
    if clock_market is None:
        return None
    current = now_utc
    if current is None:
        try:
            current = datetime.fromisoformat(
                _ai_now_iso().replace("Z", "+00:00"))
        except (TypeError, ValueError):
            return None
    if current.tzinfo is None or current.utcoffset() is None:
        return None
    current = current.astimezone(timezone.utc)
    state = argus_market_clock.market_session(clock_market, current)
    if state.get("isTradingDay") is not True:
        return None
    try:
        session_date = datetime.strptime(
            str(state.get("marketDate")), "%Y-%m-%d").date()
        opened = argus_market_clock.market_session_bounds(
            clock_market, session_date).get("regularOpenUtc")
        open_dt = datetime.fromisoformat(str(opened).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if open_dt.tzinfo is None or current < open_dt.astimezone(timezone.utc):
        return None
    return open_dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _build_mover_cause_inputs(symbol, market, change_pct=None, name=None,
                              cached_only=True, caos_lead=None):
    """Collect evidence for the pure ladder. cached_only=True reads ONLY in-memory
    caches/stores (public-path safe); cached_only=False (admin refresh) may fetch
    free/contracted providers — never LLM."""
    symu, mkt = str(symbol).upper(), str(market).upper()
    code4 = symu[:4]
    cover = {k: False for k in ("tdnetChecked", "officialEventsChecked", "edinetSecChecked",
                                "companyNewsChecked", "jpNewsChecked", "caosChecked",
                                "sectorPeerChecked", "macroChecked", "flowChecked",
                                "technicalChecked")}
    ev = {"coverage": cover}
    direction = "down" if (isinstance(change_pct, (int, float)) and change_pct < 0) else "up"

    # official: TDnet (JP)
    if mkt == "JP":
        try:
            snap = _tdnet_recent_cached_only() if cached_only else get_tdnet_recent()
            if snap:
                # checked = the feed was actually usable, not merely a failure snapshot
                cover["tdnetChecked"] = str(snap.get("status") or "").endswith("live") \
                    or bool(snap.get("items"))
                ev["tdnetItems"] = (snap.get("bySymbol") or {}).get(code4, [])[:8]
        except Exception:
            pass
        try:
            _official_events_restore_once()
            evs = _official_events_by_symbol(symu)
            cover["officialEventsChecked"] = True
            ev["officialEvents"] = evs[:6]
        except Exception:
            pass

    # filings / earnings from the catalysts snapshot
    try:
        cat = None
        if cached_only:
            if _CAT_CACHE.get("data") is not None and time.time() < _CAT_CACHE.get("expires", 0):
                cat = _CAT_CACHE["data"]
        else:
            cat = get_catalysts_snapshot()
        if isinstance(cat, dict):
            cover["edinetSecChecked"] = True
            for it in (cat.get("items") or []):
                if str(it.get("symbol", "")).upper() != symu:
                    continue
                ev["filings"] = (it.get("filings") or [])[:5]
                earn = it.get("earnings") or {}
                # daysUntil=0 with date=None is the "no earnings known" sentinel —
                # passing it through would fabricate a 決算前 vulnerability candidate
                if isinstance(earn.get("daysUntil"), (int, float)) and earn.get("date"):
                    ev["earnings"] = {"daysToEarnings": earn.get("daysUntil"),
                                      "resultReleased": False}
                break
    except Exception:
        pass

    # direct news: Finnhub (US) / Google News JP intel items (JP)
    if mkt == "US":
        try:
            if cached_only:
                fin = (_FINN_CACHE.get(symu) or {}).get("data")
            else:
                res = _finnhub_catalyst(symu)      # returns (data, status)
                fin = res[0] if isinstance(res, tuple) else res
            fin = _finnhub_catalyst_reaged(fin, now_epoch=time.time())
            if isinstance(fin, dict):
                cover["companyNewsChecked"] = True
                # v11.5.5: candidates are built from the ORIGINAL headline — the ladder's
                # identity/corroboration logic needs distinct titles. (The v11.5.1 pre-
                # replacement with displayTitleJa collapsed every untranslated headline
                # into the same 「翻訳待ち…」 string, faking multi_source corroboration and
                # producing meaningless bestLeads — caught by the violations detector.)
                # Japanese-first DISPLAY happens at serve time via
                # _mover_cause_decorate_candidates; _news_decorate here only QUEUES the
                # headline for the translate cron.
                _cn = []
                for n in (fin.get("news") or [])[:8]:
                    if isinstance(n, dict) and n.get("headline"):
                        _news_decorate(str(n["headline"]), n.get("source") or "Finnhub")
                        n = {**n, "headlineEn": str(n["headline"])}
                    _cn.append(n)
                ev["companyNews"] = _cn
        except Exception:
            pass
    else:
        try:
            if not cached_only:
                _jp_stock_news_intel([(symu, name or (_ENTITY_PROFILES.get(symu) or {}).get("name"))])
            # V11.5.3 evidence hygiene: the intel store keeps items for days — never
            # feed >7-day-old articles into TODAY's cause evidence (the freshness
            # gate in argus_mover_cause demotes 72h+ anyway; this trims the pool).
            _now_iso7 = _ai_now_iso()
            # v11.5.4: per-symbol discovery items carry symbolHint (not linkedAssets) —
            # match BOTH so investigate-now's fresh finds actually reach the ladder.
            jp_news = []
            for it in list(_INTEL_STORE):
                if it.get("sourceId") not in (
                        "google_news_jp", "public_article"):
                    continue
                if (symu not in {str(a).upper() for a in
                                 (it.get("linkedAssets") or [])}
                        and str(it.get("symbolHint") or "").upper() != symu):
                    continue
                projected = _decision_news_row({
                    "titleJa": it.get("titleJa") or it.get("title"),
                    "publishedAt": it.get("publishedAt"),
                    "publisher": it.get("author") or "GoogleNewsJP",
                    "source": "google_news_jp", "sentiment": None,
                }, now_epoch=time.time(), timestamp_keys=("publishedAt",))
                if projected is not None:
                    jp_news.append(projected)
            cover["jpNewsChecked"] = True
            # newest first — the cap must never crowd fresh items out with old ones
            jp_news.sort(key=lambda n: argus_news_freshness._epoch(n.get("publishedAt")) or 0.0,
                         reverse=True)
            ev["jpNews"] = jp_news[:8]
        except Exception:
            pass

    # C.A.O.S. association lead (pure in-memory matching)
    try:
        if caos_lead is None:
            mn = _MARKET_NEWS_CACHE.get("data") or {}
            rel = [n for n in (mn.get("items") or []) if n.get("relevant")]
            caos_lead = _caos_catalyst_for(symu, rel, list(_INTEL_STORE)[:80])
        cover["caosChecked"] = True
        if caos_lead:
            ev["caosLead"] = caos_lead
    except Exception:
        pass

    # sector/theme peers (cached quotes only)
    try:
        for theme, members in _DOWNSIDE_THEMES.items():
            if symu not in members:
                continue
            same = total = 0
            for m in members:
                if m == symu:
                    continue
                q = _decision_usable_quote_row(_quote_cached_only(
                    m, "JP" if m[:1].isdigit() else "US") or {}) or {}
                pc = q.get("changePct")
                if isinstance(pc, (int, float)):
                    total += 1
                    if abs(pc) >= 1.0 and ((pc < 0) == (direction == "down")):
                        same += 1
            ev["peers"] = {"theme": theme, "peersTotal": total, "peersSameDirection": same}
            cover["sectorPeerChecked"] = total > 0
            break
    except Exception:
        pass

    # macro events released/imminent today (in-memory macro store + regime cache)
    try:
        _macro_analysis_restore_once()
        regime_data = (_REGIME_CACHE.get("data")
                       if time.time() < float(
                           _REGIME_CACHE.get("expires") or 0.0) else None)
        regime = ((regime_data or {}).get("regime") or {}).get("label") or ""
        consistent = (regime == "RISK_OFF" and direction == "down") or \
                     (regime == "RISK_ON" and direction == "up")
        today = _ai_now_iso()[:10]
        macros = []
        for rec in _MOVER_MACRO_VIEW():
            if rec.get("phase") in ("imminent", "released_pending_result", "post_result") \
                    and str(rec.get("eventTimeUtc") or rec.get("eventDate") or "")[:10] == today:
                macros.append({"eventCode": rec.get("eventCode"), "title": rec.get("title"),
                               "source": rec.get("source"), "marketConsistent": consistent,
                               "whyJa": f"本日の{rec.get('eventCode')}前後の地合い変化の可能性(regime={regime or '不明'})。"})
        cover["macroChecked"] = True
        ev["macroEvents"] = macros[:3]
    except Exception:
        pass

    # No independent flow timestamp exists in the cached quote contract.
    cover["flowChecked"] = False
    if mkt == "JP":
        now_epoch = time.time()
        try:
            margin_cache = _JQ_MARGIN_CACHE.get(code4) or {}
            raw_margin = (margin_cache.get("data") or []
                          if _cache_expiry_usable(
                              margin_cache, now_epoch=now_epoch) else [])
            hist, _margin_reason = _entry_weekly_margin_evidence(
                raw_margin, now_epoch=now_epoch)
            if hist:
                latest = hist[0]                    # _jq_weekly_margin rows are newest-first
                ev["margin"] = {"shortHeavy": bool((latest.get("shortVol") or 0) >
                                                   (latest.get("longVol") or 0))}
        except Exception:
            pass
        try:
            history_cache = _JQ_HISTORY_CACHE.get(code4) or {}
            h = history_cache.get("data") or {}
            if (not _cache_expiry_usable(
                    history_cache, now_epoch=now_epoch)
                    or not _entry_history_source_usable(
                        h, "JP", now_epoch=now_epoch)[0]):
                h = {}
            closes = h.get("closes") or []
            if len(closes) >= 7 and closes[6]:
                runup = round((float(closes[1]) / float(closes[6]) - 1) * 100, 1)
                ev["technical"] = {"priorRunupPct": runup}
                cover["technicalChecked"] = True
        except Exception:
            pass
    return ev


def _MOVER_MACRO_VIEW():
    return list(_MACRO_ANALYSIS.values())


def _market_confirmation_inputs(symbol, market, change_pct):
    """Cached-only inputs for Market Confirmation v1.5 — quote caches, push
    history, JQ daily bars, theme peers. Never fetches (public-path safe)."""
    symu, mkt = str(symbol).upper(), str(market).upper()
    inputs = {"changePct": change_pct}
    try:                                        # index proxy (relative move)
        idx_sym, idx_name = ("1306", "TOPIX ETF(1306)") if mkt == "JP" else ("SPY", "SPY")
        q = _decision_usable_quote_row(
            _quote_cached_only(idx_sym, mkt) or {}) or {}
        if isinstance(q.get("changePct"), (int, float)):
            inputs["indexMovePct"] = q["changePct"]
            inputs["indexName"] = idx_name
    except Exception:
        pass
    try:                                        # theme-peer basket
        for members in _DOWNSIDE_THEMES.values():
            if symu not in members:
                continue
            moves = []
            for m in members:
                if m == symu:
                    continue
                pq = _decision_usable_quote_row(_quote_cached_only(
                    m, "JP" if m[:1].isdigit() else "US") or {}) or {}
                if isinstance(pq.get("changePct"), (int, float)):
                    moves.append(pq["changePct"])
            inputs["peerMoves"] = moves
            break
    except Exception:
        pass
    try:                                        # volume ratio (JP daily bars)
        q = _decision_usable_quote_row(
            _quote_cached_only(symu, mkt) or {}) or {}
        tv = q.get("volume")
        if isinstance(tv, (int, float)) and tv > 0:
            inputs["todayVolume"] = tv
        if mkt == "JP":
            now_epoch = time.time()
            history_cache = _JQ_HISTORY_CACHE.get(symu[:4]) or {}
            h = history_cache.get("data") or {}
            if (not _cache_expiry_usable(
                    history_cache, now_epoch=now_epoch)
                    or not _entry_history_source_usable(
                        h, "JP", now_epoch=now_epoch)[0]):
                h = {}
            vols = [v for v in (h.get("volumes") or [])[1:21] if isinstance(v, (int, float)) and v > 0]
            if len(vols) >= 5:
                inputs["avgVolume"] = sum(vols) / len(vols)
    except Exception:
        pass
    try:                                        # intraday push points (15m/1h moves)
        hist = (_PUSH_HISTORY.get(mkt) or {}).get(symu)
        if hist:
            points = [
                {"ts": p.get("ts"), "price": p.get("price"),
                 "volume": p.get("volume")}
                for p in list(hist) if isinstance(p, dict) and
                _source_time_within(
                    p.get("sourceTimestamp"),
                    _DECISION_QUOTE_LIVE_MAX_AGE_SEC)]
            if points:
                inputs["pushPoints"] = points
    except Exception:
        pass
    return inputs


def _mover_cause_for(symbol, market, change_pct, name=None, direction=None,
                     cached_only=True, caos_lead=None):
    ev = _build_mover_cause_inputs(symbol, market, change_pct, name=name,
                                   cached_only=cached_only, caos_lead=caos_lead)
    now_iso = _ai_now_iso()
    try:
        decision_at = datetime.fromisoformat(now_iso.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        raise ValueError("invalid_mover_decision_time")
    move_started_at = _mover_move_started_iso(market, decision_at)
    if move_started_at is None:
        raise ValueError("current_trading_session_unavailable")
    try:
        ev["marketConfirmation"] = argus_market_confirmation.compute(
            {"symbol": symbol, "market": market, "changePct": change_pct},
            _market_confirmation_inputs(symbol, market, change_pct), now_iso)
    except Exception:
        pass
    # PRIVACY: no owner data goes into the record — records reach public GETs
    # and the public ledger. Owner priority boost is transient (admin queue only).
    mover = {"symbol": symbol, "market": market, "changePct": change_pct,
             "direction": direction, "name": name, "asOf": now_iso,
             "moveStartedAt": move_started_at}
    return argus_mover_cause.resolve(mover, ev, now_iso,
                                     ai_min_abs_move=_MC_AI_MIN_ABS_MOVE)


def _collect_active_movers():
    """The refresh target set: downside incidents + watchlist big up-moves +
    whole-market mover rows (cached tiers only — the scans own the fetching)."""
    movers, seen = [], set()

    def _add(sym, mkt, chg, name=None):
        key = (str(mkt).upper(), str(sym).upper())
        if not sym or key in seen or not isinstance(chg, (int, float)):
            return
        seen.add(key)
        movers.append({"symbol": str(sym).upper(), "market": str(mkt).upper(),
                       "changePct": chg, "name": name,
                       "direction": "down" if chg < 0 else "up"})
    try:
        for inc in (get_downside_incidents().get("incidents") or []):
            _add(inc.get("symbol"), inc.get("market", "JP"), inc.get("changePct"),
                 inc.get("assetName"))
    except Exception:
        pass
    try:
        for snap, mkt in ((get_japan_watchlist_snapshot(), "JP"),
                          (get_us_watchlist_snapshot(), "US")):
            for s in (snap.get("stocks") or []):
                usable = _decision_usable_watch_quote_row(
                    s, mkt, require_latest_completed=True)
                chg = (usable or {}).get("changePct")
                if isinstance(chg, (int, float)) and chg >= 3.0:
                    _add(usable.get("symbol"), mkt, chg,
                         usable.get("nameJa") or usable.get("name"))
    except Exception:
        pass
    try:
        for r in (_moomoo_us_movers() or []):
            _add(r.get("symbol"), "US", r.get("changePct"), r.get("name"))
    except Exception:
        pass
    try:
        y = _YAHOO_MOVERS_CACHE.get("data") or {}
        for r in (y.get("gainers") or [])[:8] + (y.get("losers") or [])[:8]:
            if r.get("decisionUsable") is True:
                _add(r.get("symbol"), "JP", r.get("changePct"), r.get("name"))
    except Exception:
        pass
    movers.sort(key=lambda m: -abs(m["changePct"]))
    return movers


def _refresh_mover_causes(limit=14):
    """Admin/cron: rebuild ladders for the active mover set. Providers allowed
    (cached_only=False), LLM never (explanations are a separate admin route)."""
    _mover_causes_restore_once()
    now_iso = _ai_now_iso()
    built = 0
    for mv in _collect_active_movers()[:limit]:
        try:
            rec = _mover_cause_for(mv["symbol"], mv["market"], mv["changePct"],
                                   name=mv.get("name"), direction=mv.get("direction"),
                                   cached_only=False)
            merged = argus_mover_cause_store.merge_record(
                _MOVER_CAUSES.get(rec["moverCauseId"]), rec, now_iso=now_iso)
            if merged:
                _MOVER_CAUSES[merged["moverCauseId"]] = merged
                built += 1
        except Exception:
            continue
    # bound the store (keep the newest ~200 records)
    if len(_MOVER_CAUSES) > 200:
        for mid in sorted(_MOVER_CAUSES, key=lambda k: str(_MOVER_CAUSES[k].get("asOf")))[:len(_MOVER_CAUSES) - 200]:
            _MOVER_CAUSES.pop(mid, None)
    _MOVER_CAUSES_STATE["lastRefreshAt"] = now_iso
    _mover_causes_persist()
    return {"refreshed": built, "total": len(_MOVER_CAUSES), "asOf": now_iso}


def _mover_cause_decorate_candidates(out):
    """V11.5.2: a candidate's titleJa can be a raw ENGLISH news headline (US Finnhub).
    Rewrite it to Japanese-first for display — cached JA if we have it, else a JP
    fallback — keeping the English original in titleOriginal and queuing it for the
    next translate run. Mutates the (already-copied) served record only."""
    changed_lead = None
    for c in (out.get("causeCandidates") or []):
        t = str(c.get("titleJa") or "")
        if not argus_news_i18n.looks_translatable(t):
            continue
        src = str(c.get("source") or "")
        d = _news_decorate(t, src)                       # queues + cached-only decorate
        c["titleOriginal"] = d["titleOriginal"]
        c["translationStatus"] = d["translationStatus"]
        c["titleJa"] = d["displayTitleJa"]               # JA (cached) or JP fallback
        if changed_lead is None:
            changed_lead = d["displayTitleJa"]
    # keep bestLeadJa consistent if it echoed a now-rewritten English lead
    bl = str(out.get("bestLeadJa") or "")
    if bl and argus_news_i18n.looks_translatable(bl):
        out["bestLeadJa"] = _news_decorate(bl, "")["displayTitleJa"]
    return out


def _mover_cause_serve(rec, now_iso):
    """Read-time annotation on a COPY: freshness/staleness recomputed, market
    confirmation stale-stamped, explanation state resolved (cached/pending/
    not_generated). The store itself is never mutated by serving."""
    out = argus_mover_cause.annotate_freshness(json.loads(json.dumps(rec)), now_iso)
    try:
        if isinstance(out.get("marketConfirmation"), dict):
            out["marketConfirmation"] = argus_market_confirmation.annotate(
                out["marketConfirmation"], now_iso)
    except Exception:
        pass
    try:
        _mover_cause_decorate_candidates(out)            # Japanese-first candidate titles
    except Exception:
        pass
    if out.get("explanationJa"):
        out["explanationStatus"] = "cached"
    elif _mc_has_explain_request(out.get("symbol"), out.get("market")):
        out["explanationStatus"] = "queued"          # V11.5.2: owner requested, awaiting cron
    else:
        out["explanationStatus"] = ("pending" if (out.get("refreshPolicy") or {}).get("eligibleForAiExplain")
                                    and _MC_AI_ENABLED else "not_generated")
    return out


def _mover_cause_items(direction="both", market="ALL", limit=30):
    _mover_causes_restore_once()
    now_iso = _ai_now_iso()
    # list() first: the cron refresh mutates the dict from another thread
    items = sorted(list(_MOVER_CAUSES.values()), key=lambda r: str(r.get("asOf")), reverse=True)
    if direction in ("up", "down"):
        items = [r for r in items if r.get("direction") == direction]
    if market in ("JP", "US"):
        items = [r for r in items if r.get("market") == market]
    return [_mover_cause_serve(r, now_iso) for r in items[:max(1, min(int(limit or 30), 100))]]


def _mover_causes_today():
    today = _ai_now_iso()[:10].replace("-", "")
    return [r for r in list(_MOVER_CAUSES.values())
            if str(r.get("moverCauseId", "")).endswith(today)]


@app.route("/api/argus/admin/mover-causes/refresh-queue/run", methods=["POST"])
def api_argus_admin_mover_causes_queue_run():
    """Admin/cron: execute the queue — evidence refresh for queued movers
    (providers allowed) + cached AI explanations for the budgeted top unresolved.
    Prompts/search traces are never stored or returned."""
    ok, err, code = _require_admin()
    if not ok:
        return jsonify(err), code
    _mover_causes_restore_once()
    ref = _refresh_mover_causes()                      # discover NEW movers from live feeds
    now_iso = _ai_now_iso()
    # transient owner boost — admin path only, never stored/served (privacy)
    owner_map = {}
    try:
        owner_map = {s: (v.get("ownerState") in ("held", "protected") or v.get("priority") == "high")
                     for s, v in _owner_symbols_cached().items()}
    except Exception:
        pass
    queue = argus_mover_cause_refresh.build_queue(
        _mover_causes_today(), now_iso,
        max_ai_explain=_MC_AI_MAX_PER_RUN, ai_cooldown_min=_MC_AI_COOLDOWN_MIN,
        ai_min_abs_move=_MC_AI_MIN_ABS_MOVE, ai_enabled=_MC_AI_ENABLED,
        owner_map=owner_map)
    # execute the REFRESH half of the queue: stored movers that faded out of the
    # live feeds (e.g. a morning -8% spike) would otherwise never clear their
    # SLA breach — _refresh_mover_causes only sweeps currently-visible movers.
    swept = {(m["market"], m["symbol"]) for m in _collect_active_movers()}
    requeued = 0
    for q in queue["queue"]:
        if not q.get("refreshNeeded") or (q["market"], q["symbol"]) in swept:
            continue
        if requeued >= queue["budget"]["maxProviderRefreshPerRun"]:
            break
        try:
            raw_quote = _quote_cached_only(q["symbol"], q["market"]) or {}
            quote = _decision_usable_quote_row(raw_quote) or {}
            chg = quote.get("changePct", q.get("changePct"))
            rec = _mover_cause_for(q["symbol"], q["market"], chg,
                                   name=raw_quote.get("nameJa") or raw_quote.get("name"),
                                   direction=q.get("direction"), cached_only=False)
            merged = argus_mover_cause_store.merge_record(
                _MOVER_CAUSES.get(rec["moverCauseId"]), rec, now_iso=now_iso)
            if merged:
                _MOVER_CAUSES[merged["moverCauseId"]] = merged
                requeued += 1
        except Exception:
            continue
    explained, skipped = [], []
    for q in queue["queue"]:
        if not q.get("aiExplainNeeded"):
            continue
        try:
            done = _mover_ai_explain(q["symbol"], q["market"], now_iso)
            (explained if done else skipped).append(q["symbol"])
        except Exception:
            skipped.append(q["symbol"])
    _mover_causes_persist()
    _MOVER_REFRESH_QUEUE["data"] = None                # queue changed — recompute
    return jsonify({"ok": True, "refreshed": ref.get("refreshed"),
                    "requeuedRefreshed": requeued,
                    "aiExplained": explained, "aiSkipped": skipped,
                    "budget": queue["budget"], "asOf": now_iso})


@app.route("/api/argus/admin/market-confirmation/refresh", methods=["POST"])
def api_argus_admin_market_confirmation_refresh():
    """Admin: warm the JP daily-bar cache for requested symbols then recompute
    (the only fetching step in the market-confirmation layer)."""
    ok, err, code = _require_admin()
